  rep(i, SZ(b)){
    b[i] = a[mid]+m-b[i];
  }
  reverse(ALL(b));
  map<ll, ll> mp;
  rep(i, SZ(b)){
    mp[b[i]]++;
  }
  ll f = 0;
  for(auto&& e: mp){
    f += min(e.first, m) * e.second;
  }
  f /= m;
  return f >= v-p;
}

ll BinarySearchMax(ll lb, ll ub) {
  // 返り値の範囲：[lb, ub)
  // 条件：
  //   (lb, ub)で検証できること
  //   C(lb)==true, C(ub)==false
  while (ub - lb > 1) {
    ll mid = lb + ((ub - lb) >> 1);
    if (C(mid)) {
      // [mid, ub)
      lb = mid;
    } else {
      // [lb, mid)
      ub = mid;
    }
  }
  return lb;
}

