typedef long long ll;
using namespace std;

ll N, M, V, P;
vector<ll> A(1e5, 0);

bool bin(ll i) {
    ll sm = 0;
    ll k = A[i] + M;
    sm += (P - 1) * M + (N - i) * M;
    for (ll x = P - 1; x < i; x++) {
        sm += k - A[x];
    }
    return (sm >= M * V);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> M >> V >> P;
    for (ll i = 0; i < N; i++) {
        cin >> A[i];
    }
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());
    ll l = P - 1;
    ll r = N;
    while (r - l > 1) {
        ll mid = (l + r) / 2;
        if (bin(mid)) {
            l = mid;
        } else {
            r = mid;
        }
    }
    cout << l + 1 << endl;
    return 0;
}

