bool check(ll arr[], ll n, ll m, ll v, ll p, ll mid)
{
	ll cnt = 0, val = arr[mid], i;
	fo(i, 0, n){
		if(arr[i] > val) break;
		cnt++;
	}
	if(n - cnt <= p)
		return true;
	val += m;
	ll g = max(0ll, v - cnt);
	if(g < p && arr[n - p] <= val)
		return true;
	if(arr[n - p] > val)
		return false;

	g -= (p - 1);
	ll fin = 0, tot = m * g;
	foe(i, cnt, n - p){
		if(arr[i] < val)
		fin += (val - arr[i]);
	}
	return(fin >= tot);
}
