bool check(vector<int> a, int idx, int n, int m, int v, int p) {
  int rest = m * (v - 1);
  int base = a[idx] + m;
  a.erase(a.begin() + idx);
  for (int i = 0; i < p - 1; ++i) {
    a[i] += m;
    rest -= m;
  }
  int i = p - 1;
  while (i < a.size() && rest > 0) {
    int t = min(min(m, max(0, base - a[i])), rest);
    rest -= t;
    a[i] += t;
    ++i;
  }
  // cout << a << " " << idx << " " << base << " " << rest << endl;
  return a[p - 1] <= base && rest <= 0;
}

