int main(){
    INT N, M, V, P;
    cin >> N >> M >> V >> P;
    auto As = VECTOR(INT, N, 0);
    cin >> As;

    sort(RANGE(As));

    INT min_pont = As[N-P];

    INT mn_idx = 0;
    while( As[mn_idx] + M < min_pont && mn_idx < N ){mn_idx++;}

    INT ans = P;

    if ( P + mn_idx >= V ){
        ans = N - mn_idx;
    } else {
        INT mn = 0;
        INT mx = N-P;
        do {
            INT mid = (mx+mn+1) / 2;
            INT remain = M*V - (P-1)*M - M*mid -M;
            INT limit  = As[mid] + M;
            for( INT i = mid+1; i <= N-P; i++ ){
                if( As[i] >= limit || remain <= 0) 
                    break;
                else {
                    remain -= (limit - As[i]);
                }
            }
            if( remain > 0 ){
                mn = mid;
            } else {
                mx = mid;
            }
        } while(mx != mn+1);

        if(mn == 1) {
            // 境界 0 テスト
            INT remain = M*V - P*M;
            INT limit  = As[0] + M;
            for( INT i = 1; i <= N-P; i++ ){
                if( As[i] >= limit || remain <= 0) 
                    break;
                else {
                    remain -= (limit - As[i]);
                }
            }
            if( remain > 0 ){
                mn = 1;
            } else {
                mn = 0;
            }
        }

        if( mn != 0){
            INT i = mn;
            while( As[i] != As[mx] ) {i++;} 
            ans = N-i;
        } else {
            ans = N;
        }
    }

    cout << ans << endl;

