class Solve
{
  ll N, M, V, P;
  vector<ll> A;
  vector<ll> sum;

public:
  Solve(ll N, ll M, ll V, ll P, vector<ll> A) : N{N}, M{M}, V{V}, P{P}, A(A), sum(N + 1, 0LL)
  {
    sum[P - 1] = A[P - 1];
    for (auto i = P; i < N; i++)
    {
      sum[i] = A[i] + sum[i - 1];
    }
  }

  ll answer()
  {
    ll ok{-1}, ng{N};
    while (abs(ok - ng) > 1)
    {
      ll t{(ok + ng) / 2};
      if (test(t))
      {
        ok = t;
      }
      else
      {
        ng = t;
      }
    }
    return ok + 1;
  }

  ll test(int X)
  {
    if (X < P)
    {
      return true;
    }
    if (A[X] + M < A[P - 1])
    {
      return false;
    }
    ll sum{0LL};
    for (auto i = 0; i < N; i++)
    {
      if (i < P - 1)
      {
        sum += M;
      }
      else if (i == X)
      {
        sum += M;
      }
      else if (i > X)
      {
        sum += M;
      }
      else
      {
        sum += A[X] + M - A[i];
      }
    }
    return (sum >= M * V);
  }
};

int main()
{
  ll N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  sort(A.rbegin(), A.rend());
  Solve solve(N, M, V, P, A);
  cout << solve.answer() << endl;
}

