                if (rest <= 0) break;
                if (b[i] > cur) return false;
                llong addition = min(m, cur - b[i]);
                rest -= addition;
            }
            return rest <= 0;
        };

        // clog << l << ' ' << r << ' ' << mid << ' ' << ok() << endl;
        if (ok()) r = mid;
        else l = mid;
    }

    cout << n - r;

    return 0;
}

