		V2--;
	}
	int M2 = M;
	if (V2 <= 0) {
		sort(B.rbegin(), B.rend());
		return B[P - 1] <= A[m] + M;
	}
	vector< int > tmp(V2, M);
	int target = B[m];
	int j = 0;
	for (int i = m - 1; i >= P - 1; i--) {
		int k = min(target - B[i], tmp[j]);
		if (k < 0) {
			return false;
		}
		B[i] += k;
		tmp[j] -= k;
		if (tmp[j] == 0)
			++j;
		if (j == V2)
