long long GetSum(int l, int r)
{
    return l == 0 ? sa[r] : sa[r] - sa[l - 1];
}

int GetMax(int l, int r, int w)
{
    assert(l <= r);
    assert(w <= (r - l + 1));
    if (w <= 0) {
        return a[r];
    }
    int result = m + a[r];
    for (int i = l; i <= r; ++i) {
        long long currentResult = 0;
        if (i > l) {
            currentResult = m + a[i - 1];
        }
        int w2 = w - (i - l);
        if (w2 <= 0) {
            assert(currentResult > 0);
            result = min(result, m + a[i - 1]);
            continue;
        }
        int c = r - i + 1;
        long long value = 1LL * w2 * m + GetSum(i, r);
        long long newCurrentResult = value / c;
        if (newCurrentResult * c < value) {
            ++newCurrentResult;
        }
        currentResult = max(currentResult, newCurrentResult);
        if (currentResult <= m + a[i] && currentResult <= result && currentResult >= a[r]) {
            result = currentResult;
        }
    }
    return result;
}

bool Check(int pos)
{
    if (pos >= n - p) {
        return true;
    }
    int l = pos + 1;
    int r = n - p;
    int w = (v - 1) - (p - 1) - pos;
    auto mx = GetMax(l, r, w);
    return a[pos] + m >= mx;
}

