//{0, 2} -> 101
ll biti(vi&a){    int m=0;    for(auto&& v:a) m|=bit(v);    return m;}
//{1, 1, 0} -> 011
ll bitb(vi&a){    int m=0;    rep(i,sz(a)) if(a[i])m|=bit(i);    return m;}
