int main()
{
	ios_base::sync_with_stdio(false);

	cin >> n >> m >> v >> p;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		if (!mp[a[i]])
			vec.push_back(a[i]);
		mp[a[i]]++;
	}
	sort(vec.begin(), vec.end());
	sort(a, a + n);
	reverse(a, a + n);

	int left = 0, right = p - 1, res = p - 1;
	while (left <= right) {
		int mid = (left + right) / 2;
		if (a[mid] == a[p - 1]) {
			res = mid;
			right = mid - 1;
		}
		else
			left = mid + 1;
	}
	int bg = p - res;

	int ans = p;
	left = 0, right = vec.size() - 1, res = vec.size() - 1;
	for (int i = p; i < n; i++) {
		if (a[i] + m < a[p - 1])
			break;
		if (v <= p || a[i] == a[i - 1]) {
			ans++;
			continue;
		}

		int q = m * (v - (p - 1 + n - i));

		if (q <= 0) {
			ans++;
			continue;
		}

		left = 0, right = res;
		while (left <= right) {
			int mid = (left + right) / 2;
			if (vec[mid] > a[i]) {
				res = mid;
				right = mid - 1;
			}
			else
				left = mid + 1;
		}
		for (int j = res; j < vec.size() && q > 0; j++) {
			q -= (a[i] + m - vec[j]) * mp[vec[j]];
			if (vec[j] == a[p - 1]) {
				q += bg * (a[i] + m - vec[j]);
				break;
			}
		}
		if (q <= 0)
			ans++;
		else
			break;
	}

	cout << ans << endl;

	return 0;
}

