int N, M, V, P;
vector<int> A,B,C;

bool calc(int index);

int main()
{
	cin >> N;
	cin >> M;
	cin >> V;
	cin >> P;

	A =vector<int>(N+1);
	for (int i = 1; i <= N; i++) {
		cin >> A[i];
	}

	sort(A.begin()+1,A.end(),greater<int>());


	B = C =vector<int>(N + 1);
	for (int i = 1; i <= N; i++) {
		if (i < P) {
			B[i] = -1;
			C[i] = 0;
		}
		else {
			B[i] = max(0,V-P-N+i)*M;
			C[i] = C[i - 1] + max(0, A[P] - A[i]);
		}
	}

	int n = 1;
	while (n <= N) { n *= 2; }

	int ans = 1;

	while (n > 1) {
		n /= 2;

		if (calc(ans + n)) {
			ans += n;
		}
	}

	cout << ans << endl;

	return 0;
}

bool calc(int index)
{
	if (index <= P) { return true; }
	if (index > N) { return false; }

	int o = A[index] + M - A[P];
	if (o<0) { return false; }

	return B[index] <= C[index-1] + o*(index-P);

}

