int nbProb, nbJuges, nbIncr, nbPris;
vector<int> prob;

bool peutPrendre(int indProtege)
{
	vector<int> cc = prob;
	int rst = nbPris-1;
	int lsInc = -1;
	form(i, nbProb) if (rst > 0) {
		if (i != indProtege) {
			cc[i] = BIG;
			lsInc = i;
			--rst;
		}
	}
	int resteIncr = nbIncr - nbPris;
	priority_queue<int> dispo;
	int toursFaits = 0;
	int indInser = nbProb-1;
	int finalProt = prob[indProtege] + nbJuges;
	if (lsInc+1 < nbProb && lsInc+1 != indProtege && prob[lsInc+1] > finalProt) return false;
	if (resteIncr == 0) return true;

	while (toursFaits < nbJuges) {
		while (indInser >= 0 && vsz(dispo) < resteIncr) {
			if (indInser == indProtege || cc[indInser] > finalProt) { --indInser; continue; }
			dispo.push(cc[indInser] - toursFaits);
			--indInser;
		}
		if (vsz(dispo) < resteIncr) return false;
		int tp = dispo.top();
		int augMax = finalProt - (tp + toursFaits);
		toursFaits += augMax; dispo.pop();
	}
	return true;
}

