using namespace std;

int64_t N, M, V, P;
vector<int64_t> A, S;

bool check(int x){
    int X = upper_bound(A.begin(), A.end(), A[x]) - A.begin() - 1;
    if(X+P >= V){
        return (A[X] + M) >= A[N-P];
    }
    int l = X+1, r = N-P;
    int64_t gain = A[X] + M;
    int64_t rest = M*(V-X-P);
    int64_t pool = 0;
    for(int i=l; i<=r; i++){
        if(A[i] > gain) return false;
        pool += min(M, gain - A[i]);
    }
    return (rest <= pool);
}

int main(){
    cin >> N >> M >> V >> P;
    A.resize(N);
    S.resize(N+1);
    for(int i=0; i<N; i++){
        cin >> A[i];
    }
    sort(A.begin(), A.end());
    for(int i=0; i<N; i++){
        S[i+1] = S[i] + A[i];
    }
    int ok = N-1, ng = -1;
    while(ok-ng>1){
        int mid = (ok+ng)/2;
        (check(mid) ? ok : ng) = mid;
    }
    cout << N-ok << endl;
    return 0;
}

