bool check(int index){
	vector <pair<ll,int> > v2;
	for(int i=0;i<100005;i++) c[i]=0;
	v2=v;
	int _=v2[index].second;
	ll sum=ll(m*ll(V)); 
	v2[index].first+=m; sum-=m;
	int __=v2[index].first;
	for(int i=0;i<v2.size();i++) if(i!=index){
		if(sum<=0) break;
		if(v2[i].first>v2[index].first){
			v2[i].first+=min(sum,m);
			c[i]=min(sum,m);
			sum-=min(sum,m);
			continue;
		}
		if(v2[i].first==v2[index].first) continue;
		if(v2[i].first<v2[index].first){
			ll add=min(sum,min(v2[index].first-v2[i].first,m));
			c[i]=add;
			v2[i].first+=add;
			sum-=min(sum,add);
		}
	}
	for(int i=0;i<v2.size();i++) if(index!=i){
		if(sum<=0) break;
		ll add=min(sum,m-c[i]);
		sum-=add;
		v2[i].first+=add;
	}
	sort(v2.begin(),v2.end());
	reverse(v2.begin(),v2.end());
	for(int i=0;i<p;i++){
		if(-v2[i].second==_||v2[i].first==__) return true;
	}
	return false;
}

