{
    cin.tie(0);
   	ios::sync_with_stdio(false);
    ll N, M, V, P; cin >> N >> M >> V >> P;
    vector<ll> vll;
    REP(i, N) {
        ll tmp; cin >> tmp;
        vll.push_back(tmp);
    }
    sort(vll.begin(), vll.end(), greater<ll>());
    ll target_idx = N;
    while (P <= target_idx--) {//クリアできたらそれより元の配点が大きいものは全部可能性がある
        ll boader_value = vll[P-1];
        ll rest = M * V;
        ll target_value = vll[target_idx];
        //targetへは全員投票
        target_value += M; rest -= M;
        if (rest <= 0 && boader_value <= target_value) break;
        //あとはboaderを出来るだけ上げないように
        //boaderが上がらない安牌
        rest -= M * ((P-1) + (N-1 - target_idx));
        if (rest <= 0 && boader_value <= target_value) break;
        //上がるがターゲットに比べれば薄められる操作
        vector<ll> boader2target_v(target_idx-(P-1));
        copy(vll.begin()+P-1,vll.begin()+target_idx,boader2target_v.begin());
        ll sukima = 0;
        for(auto x: boader2target_v) {
            sukima+=x;
        }
        sukima += rest;
        if (sukima > target_value * (target_idx - (P-1))) continue;
        else break;
    }

    cout << target_idx + 1 << endl;
    return 0;
}

