bool det(int i){
    if (a[i] >= thres) return true;
    auto maxi = a[i] + m;
    if (maxi < thres) return false;
    auto waste = (p-1 + n-i-1 + 1) * m;

    auto sat = 0;
    FOR(j,p,i){
        sat += maxi - a[j];
    }
    return waste + sat >= v * m;
}


