using namespace std;
typedef long long intl;
intl sum(intl k,vector <intl> &tree) {
	intl s = 0;
	intl n=tree.size()-1;
	while (k >= 1) {
		s += tree[k];
		k -= k&-k;
	}
	return s;
}
void add(intl k, intl x,vector <intl> &tree) {
	intl n=tree.size()-1;
	while (k <= n) {
		tree[k] += x;
		k += k&-k;
	}
}
bool f(vector <intl> res,intl n, intl m, intl v, intl p,intl mid){
	v=n-v;
	//cout<<"entre"<<" "<<mid<<endl;
	vector <intl> tree(200030,0);
	bool ans=true;
	intl q=res[mid];
	for(intl i=mid+1;i<n-p+1;i++){
		intl k=sum(i+1,tree);
		//cout<<k<<" "<<res[i]<<" "<<q<<" : ";
		k=res[i]+k;

		if(k>q){
			if(m<k-q){
				ans=false;
				break;
			}
			m-=(k-q);
			add(i+1,-k+q,tree);
			add(i+1+v,k-q,tree);
		}
	}
	//cout<<endl;
	return ans;
}
int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	intl n,m,v,p;
