	//if(caso);
	intl l=-1,h=n-1;
	while(h-l>1){
		intl mid=(h+l)/2;
		if(f(res,n,m,v,p,mid)){
			h=mid;
		}
		else{
			l=mid;
		}
	}

	cout<<n-h<<endl;
}

