ll N, M, V, P;
vector<ll> A;

bool judge(ll idx){
	ll t = A[idx];
	ll X = A.end() - upper_bound(A.begin(), A.end(), t+M);

	if(idx>=N-P){
		return true;
	}else if(X>=P){
		return false;
	}else{
		ll sum = 0;
		REP(i, N-(P-1)){
			if(i==idx) continue;
			if(A[i]<=t+M){
				sum += min(t+M-A[i], M);
			}
		}
		if(sum>=M*(V-P)) return true;
		else return false;
	}
}

