bool prime_(int n){
  if(n==1){
    return false;
  }else if(n==2){
    return true;
  }else{
    for(int i=2;i<=sqrt(n);i++){
      if(n%i==0){
        return false;
      }
    }
    return true;
  }
}

long long gcd_(long long a, long long b){
  if(a<b){
    swap(a,b);
  }
  if(a%b==0){
    return b;
  }else{
    return gcd_(b,a%b);
  }
}

long long lcm_(long long x, long long y){
  return (x/gcd_(x,y))*y;
}



int main(){

  long long n,m,v,p;
  cin>>n>>m>>v>>p;
  vector<long long> a(n);
  REP(i,n){
    cin>>a[i];
  }
  sort(ALL(a));
  long long s[n];
  REP(i,n){
    if(i == 0){
      s[i] = a[i];
    }else{
      s[i] = s[i-1] + a[i];
    }
  }

  long long l = -1, r = n - 1;//(l,r] 
  while(r-l > 1){
    long long i = (l+r)/2;
    auto iter_upper = upper_bound(ALL(a), a[i]+m);
    long long idx_upper = distance(a.begin(), iter_upper);
    long long cnt = n - idx_upper;//a[i] + mより大きい要素数。
    //cout<<cnt<<endl;
    if(cnt >= p){
      continue;
    }
    long long j = idx_upper - 1;
    long long temp;
    if(j-i >= p-1-cnt){
      temp = m * (i + p - 1) + (a[i] + m) * (j + cnt - p - i + 1) - (s[j+cnt+1-p] - s[i]);
    }else{
      temp = m * (j + cnt);
    }
    if(temp >= m*(v-1)){
      r = i;
    }else{
      l = i;
    }
  }
  long long ans = n - r;
  cout<<ans<<endl;
  return 0;
}

