int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n,m,v,p;
    cin>>n>>m>>v>>p;
    vl a(n); cin>>a;

    sort(all(a));
    // puta(a);
    ll ok=n-1,ng=-1;
    while(ok-ng>1){
        ll mid=(ok+ng)/2;
        ll tgt=a[mid] + m;
        ll need=(v-1)*m;
        ll life = p-1;
        ll near=0;
        deque<ll> dq;
        rep(i,n)if(i!=mid){
            ll diff=tgt-a[i];
            if(diff<0){//すでに越されているなら，どうせ無理なので全力で振っていい．ただし猶予は減る
                need-=m;
                life--;
            }else if(diff>=m){//限界まで振っても並ぶか未満なので振っていい
                need-=m;
            }else{
                // diff回振ると，まだ振る猶予がm-diff回ある状態で同じになってしまう
                need-=diff;
                near++;
                dq.push_front(m-diff);
            }
        }
        if(need<=0){//振り切った場合
            if(life>=0){//tgtを超えたものがp-1個以下
                ok=mid;
            }else{
                ng=mid;
            }
        }else{//まだneed回残ってる
            if(life<0){
                ng=mid;
            }else{
                //life個の余裕がある
                //nearなものに1でも振ると越される，ただしどうせ降るなら限界まで振っていい
                rep(i,dq.size()){
                    need-=dq[i];
                    life--;
                    if(life<0 or need<=0)break;
                }
                if(life>=0){//tgtを超えたものがp-1個以下
                    ok=mid;
                }else{
                    ng=mid;
                }
            }
        }
        // puta(ok,ng);
    }
    puta(n-ok);

    return 0;
}

