    // if(N<=V) return false;
    if(N<0) return false;
    ll d[100010]={};
    rep(i,N){
        d[i]=b[k]+m-b[i];
    }
    SegmentTree sg(N);
    rep(i,N){
        sg.update(i,i+1,0,d[i],0,N);
    }
    ll cnt=0;
    rep(i,N-V+1){
        ll Q=sg.query(i);
        if(Q>0){
            sg.update(i,i+V,0,-Q,0,N);
