	scanf("%d%d%d%d", &n, &m, &v, &p);
	for(int i = 1; i <= n; ++i) {
		scanf("%d", a+i);
	}
	sort(a+1, a+1+n);
	for(int i = 1; i <= n; ++i) {
		sum[i] = sum[i-1]+a[i];
	}
	int ans=0;
	for(int i = 1; i <= n; ++i) {
		ll t=(ll)m*v - (ll)i*m;
		int pos = lower_bound(a+1, a+1+n, a[i]+m+1)-a;
		if(n-pos+1>=p) continue;
		if(t<0) {
			ans++;
			continue;
		}
		if((ll)(a[i]+m)*(pos-1-i) - sum[pos-1]+sum[i] >= (ll)t) {
			ans++;
		} else {
			int l=i+1, r=pos, A=r;
			while(l<=r) {
				int mid=(l+r)/2;
				ll d=(ll)(n-mid+1)*m;
				d = d + (ll)(min(mid-1, pos-1) - i)*(a[i]+m) - sum[min(mid-1, pos-1)] + sum[i];
				if(d>=t) A=mid, l=mid+1;
				else r=mid-1;
			}
			A=min(A, pos);
			if(n-A+1 <p) ans++;
		}
	}
