bool check(vector<ll>& A,  ll N, ll M, ll V, ll P, int pos)
{
    // first, make A[pos] high
    ll base = A[pos] + M;
    if (A[P-1]>base) return false;

    // get left votes
    queue<ll> que;
    rep(i, 0, V-(N-pos)-(P-1))
        que.push(M);

    // voting with greedy
    --pos;
    while (que.size()>0 and P-1<=pos)
    {
        ll now = que.front();
        que.pop();

        ll cap = base - A[pos];
        // cout << pos << ' ' << now << ' ' << cap << endl;

        if (cap<now)
            que.push(now-cap);

        --pos;
    }
    return que.size()==0;
}


