bool isOk(ll N, ll M, ll V, ll P, vector<ll>& A, int x) {
    if (x < P)
        return true;

    ll maxP = A[x] + M;
    if (maxP < A[P - 1])
        return false;

    ll res = M * V;
    res -= (P - 1) * M;
    res -= (N - x) * M;
    for (int i = P - 1; i < x; i++) {
        res -= min(max(0ll, maxP - A[i]), M);
    }

    return res <= 0;
}

