    const auto& chk = [&N, &M, &V, &P, &A, &B](unsigned long idx) -> bool {
        if(A[P - 1] > A[idx] + M)return false;
        unsigned long rem = V * M - M * (min(V + 1, P + N - idx) - 1), lim = A[idx] + M;
        return lim * (idx - P + 1) + B[P - 1] >= rem + B[idx];
    };
    unsigned long L = P, R = N - 1;
    while(L + 1 < R){
        auto m = (L + R) / 2;
