	cin >> n >> m >> v >> p;
	vector <int> a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	map <int, int> poss;
	sort(a.begin(), a.end());
	reverse(a.begin(), a.end());
	int target = a[p - 1];
	int pos = -1;
	for (int i = p - 1; i < n; i++) {
		if (a[i] == target) {
			pos = i;
			continue;
		}
		break;
	}
	for (int i = 0; i < n; i++) {
		if (i + 1 <= p) {
			poss[a[i]] = true;
			continue;
		}
		 int vv = v;
		 vv -= p - 1;
		 vv -= n - i;
		 if (vv <= 0 && a[i] + m >= target) {
			 poss[a[i]] = true;
		 } else {
			 ll dist = i - 1 - (p - 1) + 1; 
			 ll need = m * vv;
			 ll val = need / dist;
			 if (need % dist == 0) {
				 if (a[pos] + val <= a[i]) {
					 poss[a[i]] = true;
				 }
			 } else {
				 int dist_of = i - 1 - pos + 1;
				 if (dist_of <= need % dist) {
					 val++;
				 }
				 if (a[pos] + val <= a[i] + m) {
					 poss[a[i]] = true;
				 }
			 }
		 }
	}
	int cnt = 0;
	for (int i = 0; i < n; i++) {
		if (poss[a[i]]) {
			cnt++;
		}
	}
	cout << cnt << '\n';
	return 0;
}

