	if(x<0){x=-x;putchar('-');}
	qwq(x);putchar('\n');
}
int co[100010];int in[100010]; 
int n,m,v,p;
inline bool check(int mid){
	memset(in,0,sizeof(in));
	int ba=co[mid]+m;long long tot=1ll*m*v;
	tot-=1ll*mid*m;
	rep(i,mid+1,n){
		if(co[i]>=ba)continue;
		tot-=ba-co[i];in[i]=ba-co[i];
	}
	if(tot<=0)return true;
	rep2(i,n,mid+1){
		if(tot>=m-in[i]){tot-=m-in[i];in[i]=m;}
		else{in[i]+=tot;break;}
	}
	int cnt=0;
	rep(i,1,n)cnt+=(co[i]+in[i]>ba);
	return cnt<=p-1;
}

int main(){
	read(n);read(m);read(v);read(p);
	rep(i,1,n)read(co[i]);
	sort(co+1,co+n+1);

	int l=1;int r=n;int ans=0;
	while(l<=r){
		int mid=(l+r)>>1;
		if(check(mid)){ans=mid;r=mid-1;}
		else{l=mid+1;}
	}
	write(n-ans+1);
	return 0;
}

