        // A[x] 以下の問題に M 人が投票
        int64 v = V - x - 1; // 残り v 問
        int64 r = M * (N - x - 1 - v);
        for(int i = x + 1; i < N - P + 1; ++i) {
            int64 d = A[i] - A[x];
            if(d > M) return false;
            if(r - d < 0) return false;
            r -= d;
        }
        return true;
    };
    int64 l = -1, r = N - 1;
    while(r - l > 1) {
        int mid = (l + r) / 2;
        if(isOK(mid)) r = mid;
        else l = mid;
    }
    cout << N - r << '\n';
    return 0;
}

