            if (a[ans + 1].s + m < a[p].s) {
                write(ans, 10);
                break;
            }
        }
    } else {
        long long could = (n - v) * m;
        long long sum = 0;
        long long ans = p;
        long long minn = a[p].s - m;
        while (ans <= n) {
            sum += a[ans].s;
            if (a[ans + 1].s < minn) break;
            if (sum - a[ans + 1].s * (ans - p + 1) > could) break;
            ans++;
        }
        write(min(ans, n), 10);
    }
    return 0;
}

