		int v = max(V - mid - P, 0LL); if (V == 0) return true;
		int a = A[mid] + M;
		int lim = 0;
		reps(i, mid+1, N-P+1) {
			if (a < A[i]) return false;
			lim += a - A[i];
		}
		return v * M <= lim;
	}) << endl;
}

