const int M=1e5+20,P=1e9+7;
struct Task{
	int n,m,v,p,a[M];
	LL sum[M];
	void init(){
		scanf("%d%d%d%d",&n,&m,&v,&p);
		for(int i=1;i<=n;++i)
			scanf("%d",&a[i]);
	}
	void run(){
		init();
		sort(a+1,a+n+1);
		for(int i=1;i<=n;++i)
			sum[i]=sum[i-1]+a[i];
		int ans=n-p;
		while(ans>=1){
			if(a[ans]+m<a[n-p+1])
				break;
			if(1LL*(ans+p-1)*m+1LL*(n-p-(ans+1)+1)*(a[ans]+m)-(sum[n-p]-sum[ans])>=1LL*v*m)
				--ans;
			else
				break;
		}
		printf("%d\n",n-ans);
	}
}t;
int main(){
	t.run();
	return 0;
}

