// i番目の問題が採用されうるか否かを調べる
// 入れても構わない表の総数がmv以上になるかどうかを調べよ
bool isOK(int i, vector<int> &a, int n, int m, int v, int p){

    // はじめから上位p以内ならば無条件で採用される
    if (n - i <= p) return true;

    // 入れられても構わない表の総数 >= mv かどうかを調べる
    int comparison = m * v;

    int res = 0;

    rep(j, n){

        if (a[j] <= a[i]) res += m; //a[i]以下の値ならば, m個入れ込んでOk
        else if (n - m <= j) res += m; //上位1, 2, ,,,p-1個にもm個入れ込んでOK
        else{
            res  = res + (a[i] + m - a[j]); //入れられても問題ない個数の上限である
        }
    }

    if (res >= comparison) return true; //ここの理屈はeditorial pdfに丁寧に書いてある.
    else return false;

}


