void solve() {
	int N, M, V, P; cin >> N >> M >> V >> P;
	vector<int>v(N);
	REP(i, N)cin >> v[i];
	VSORT(v);
	int ok = N-1, ng = -1;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		int val = v[mid] + M;
		int rem = M * V - M;
		rem -= M * mid;
		rem -= M * (P - 1);

		FOR(i, mid + 1, N-P+1) {
			if (v[i] <= val) {
				rem -= (val - v[i]);
			}
		}
		if (rem <= 0&&val>=v[N-P])ok = mid;
		else ng = mid;
	}
	REP(i, N) {
		if (v[i] == v[ok]) {
			ok = i;
			break;
		}
	}
	print(N - ok);
}



