ll n,m,v,p;
vector<ll> vec;
bool solve(ll mid){
  if(mid<p) return true;
  if(vec[p-1]>vec[mid]+m) return false;
  ll score=0;
  score+=(p-1)*m;
  score+=(n-mid)*m;
  for(ll i=p-1;i<mid;i++) score+=min(m,max((ll)0,vec[mid]+m-vec[i]));
  return score>=m*v;
}
