bool sub(vi a,int m,int v,int t){
	dmp2(a,m,v,t);
	if(a[0]>t+m)return false;
	if(v<=0)return true;
	int n=a.size();
	vi rem(n);
	rep(i,n)rem[i]=t+m-a[i];
	int mc=inf;

	{
		int s=0;
		rep(i,n+1){
			chmin(mc,s+min(v,n-i)*m);
			if(i<n)s+=rem[i];
		}
	}

	dmp2(a,m,v,t);

	return mc==v*m;
}

