bool isok(int s) {
    ll sum = 0;
    for (int i = n - 1, j = 0; i >= 0; --i) {
        if (i == s)
            continue;
        if (j < p - 1) {
            sum += m;
        }
        else {
            sum += min(m, a[s] + m - a[i]);
        }
        j++;
    }
    if (sum >= m * (v - 1))
        return true;
    return false;
}

int main() {
    cin >> n >> m >> v >> p;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
