    int l = 0, r = n - 1, m;
    while (l < r) {
        m = (l + r) / 2;
        if (isok(m)) {
            r = m - 1;
        }
        else {
            l = m + 1;
        }
    }
    cout << n - l << endl;

    return 0;
}

