bool check(vector<ll> &da, int now) {
	ll h = (ll)n - now + p - 1;
	if (p - v >= 0 || h >= v) {
		return (da[now] + m >= da[p - 1]);
	}
	else {
		if (da[now] + m - da[p - 1] < 0) {
			return false;
		}
