bool che(vector<ll> ar, int k, ll n, ll m, ll v, ll p){
    ar[k] += m;
    ll hyo = m * v - m;
    ll ki = ar[k];
    sort(ar.rbegin(),ar.rend());
    if (ar[p-1] > ki) return false;
    if (ar[p-1] <= ki){
        hyo -= (p-1) * m;
        if (hyo <= 0) return true;
        ll cnt = n-1;
        while (ar[cnt] < ki && hyo > 0){
            hyo -= min(ki - ar[cnt],m);
            cnt--;
        }
        if (hyo <= 0) return true;
        else return false;
    }
}

