bool ok(lli n, lli m , lli v, lli p, vector<lli>&A, lli k){
  // idx k はなりうるか
  lli val = A[k] + m;
  vector<lli> B;
  rep(i, n)if(i!=k)B.push_back(A[i]);
  v-=1;

  // BのB[p-1] 番目の最小化をしたい
  rep(i, p-1) B[i]+=m;
  v -= p-1;

  if(v<=0){
    return B[p-1] <= val;
  }
  // cerr << "HOGE"<< B.size()<<endl;
  // rep(i, B.size())cerr << B[i] << " ";
  // cerr << endl;



  vector<lli> C;
  rep(i, B.size()){
    if(i>=p-1){
      C.push_back(B[i]);
    }
  }

  // Cの最大値の最小化
  lli rem = v * m;
  rep(i, C.size()){
    if(C[i]>val){
      return false;
    }
    lli tmp = val-C[i];
    rem -= min(tmp, m);
  }

  return rem<=0;
}
