bool can(int N, int M, int V, int P, vector<int> A, int k){
	if(k < P){
		return true;
	}
	int i;
	if(V <= P){
		A[k] += M;
		for(i = 0; i < V - 1; i++){
			A[i] += M;
		}
		int count = 0;
		for(i = 0; i < N; i++){
			if(A[i] > A[k]){
				count++;
			}
		}
		if(count >= P){
			return false;
		}
		return true;
	}
	A[k] += M;
	for(i = 0; i < P - 1; i++){
		A[i] += M;
	}
	int count = 0;
	for(i = 0; i < N; i++){
		if(A[i] > A[k]){
			count++;
		}
	}
	if(count >= P){
		return false;
	}
	int sum = 0;
	for(i = P - 1; i < N; i++){
		if(i == k){
			continue;
		}
		sum += min(M, A[k] - A[i]);
	}
	if(sum >= (V - P) * M){
		return true;
	}
	else{
		return false;
	}
}

