int n, v, p;
ll m, a[100005];
bool f(int x) {
    if (x < p) return true;
    if (a[x] + m < a[p - 1]) return false;

    ll res = 0;
    rep(i, n) {
        if (i < p - 1 || i >= x) res += m;
        else res += a[x] + m - a[i];
    }

    return res >= m * v;
}

void solve() {
    cin >> n >> m >> v >> p;
    rep(i, n) cin >> a[i];
    sort(a, a + n, greater<>());

    int l = -1, r = n;
    while (r - l > 1) {
        auto x = (l + r) / 2;

        if (f(x)) l = x;
        else r = x;
    }

    cout << r << endn;

}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
    cout << flush;
    return 0;
}

