using namespace std;
int main(){
  int64_t N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int64_t> vec(N);
  for(int64_t i=0; i<N; i++){
    cin >> vec.at(i);
  }
  sort(vec.rbegin(),vec.rend());
  int64_t border = vec.at(P-1);
  int64_t ok = vec.at(P-1);
  int64_t ans = P;

  if(V <= P){
    for(int64_t i=P; i<N; i++){
      if(vec.at(i) + M >= border){
        ans++;
        ok = vec.at(i);
      }
      else{
        break;
      }
    }
  }
  else{
    int64_t border_first = -1;
    int64_t border_sub = 0;
    for(int64_t i=0; i<N; i++){
      if(vec.at(i) == border){
        border_first = i;
        break;
      }
    }
    for(int64_t i=P; i<N; i++){
      if(vec.at(i) == ok){
        ans++;
        border_sub += border - vec.at(i);
      }
      else{
        int64_t plus_cnt = V-(N-i)-border_first;
        int64_t vec_max = vec.at(i) + M;
        //最大で何個まで足すことが許容できるか
        int64_t sum_max = border_sub + (i - border_first)*(vec_max - border);
        sum_max += P - 1 - border_first;
        if(plus_cnt*M <= sum_max){
          ans++;
          border_sub += border - vec.at(i);
          ok = vec.at(i);
        }
        else{
          break;
        }
      }
    }
  }
  cout << ans << endl;
}

