//***********//
ll binarySearch(vl V, ll key) {
	ll left = -1; //「index = 0」が条件を満たすこともあるので、初期値は -1
	ll right = V.size(); // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は V.size()
	while (right - left > 1) {
		ll mid = left + (right - left) / 2;
		if (V[mid] >= key) right = mid;
		else left = mid;
	}
	/* left は条件を満たさない最大の値、right は条件を満たす最小の値になっている */
	return right;
}
int main() {
	ll V, P;
	cin >> N >> M >> V >> P;
	vl A(N);
	for (i = 0; i < N; i++) {
		cin >> A[i];
	}
	sort(A.begin(), A.end());
	reverse(A.begin(), A.end());
	ll left = -1;
	ll right = N;
	while(right-left>1) {
		ll mid = left + (right - left) / 2;
		ll valid = 1;
		if (mid < P) valid = 1;
		else {
			if (A[mid] + M >= A[P - 1]) {
				ll pre = M * P;
				for (j = P-1; j < N; j++) {
					if (j == mid) continue;
					pre += min(M, A[mid] + M - A[j]);
				}
				if (pre >= M * V) valid = 1;
				else valid = 0;
			}
			else {
				valid = 0;
			}
		}
		if (valid) left = mid;
		else right = mid - 1;
	}
	cout << left + 1;
}

