void solve() {
  ll N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  rep (i, N) cin >> A[i];
  sort(A.begin(), A.end());
  reverse(A.begin(), A.end());
  vector<ll> accum(N + 1);
  accum[0] = 0;
  rep (i, N) {
    accum[i + 1] = accum[i] + A[i];
  }
  if (V <= P) {
    ll ans = 0;
    ll border_score = A[P-1];
    for (auto it: A) if (it + M >= border_score) ans++;
    cout << ans << endl;
    return;
  }
  ll ans = 0;
  for (ll i = 0; i < N; i++) {
    if (i <= P-1) {
      cerr << "add A: " << i << endl;
      ans ++;
      continue;
    }
    ll current = A[i] + M;
    cerr << "current:" << current << ", A[P-1]:" << A[P-1] << endl;
    if (current < A[P-1]) continue;
    ll votes = M * (V - P);
    cerr << "votes:" << votes << endl;
    votes -= (N-i-1) * M;
    cerr << "- votes:" << votes << endl;
    ll existing = accum[i] - accum[P-1];
    ll border = (current * (i - (P - 1))) - existing;
    cerr << "existing:" << existing << ", border:" << border << endl;
    if (votes <= border) {
      ans ++;
      continue;
    }
  }
  cout << ans << endl;
}

