int main(){
    ll n,m,v,p;
    cin>>n>>m>>v>>p;
    vector<ll> a(n);
    for (int i = 0; i < n; ++i) {
        cin>>a[i];
    }
    sort(a.rbegin(),a.rend());

    ll bs=-1,bc=0;
    int bb=-1;

    int ans=0;
    if(p==1){
        bb=0;
        bs=a[0];
        goto a;
    }
    for (int i = 1; i < n; ++i) {
        bs=a[i];
        bc=1;
        while(a[i]==a[i-1]){
            ++i;
            ++bc;
        }
        if(i<p-1)continue;
        bb=i;
        bs=a[i];
        break;
    }
    a:;
    int ok=p-1,ng=n;
    int mid;
    while(ng-ok>1){
        mid=(ng+ok)/2;
        ll rs=(v-n+mid-bb)*m;
        if(rs<0){
            if(a[mid]+m>=bs)ok=mid;
            else ng=mid;
            continue;
        }
        for (int i = bb; i < mid; ++i) {
            if(a[mid]+m<a[i]){
                rs=1;
                break;
            }
            rs-=a[mid]+m-a[i];
        }
        if(rs<=0)ok=mid;
        else ng=mid;
    }
    for (int i = ok+1; i < n; ++i) {
        if(a[i]==a[i-1])++ok;
        else break;
    }
    cout<<ok+1<<endl;
    return 0;
}

