bool isOK(ll N, ll M, ll V, ll P, vector<ll>& A, ll x) {
    if (x < P) return true;
    ll now = A[x] + M;

    if (A[P - 1] > now) return false;

    ll score = 0;
    score += (P - 1) * M;
    score += (N - x) * M;

    reps(i, P - 1, x) { score += min(M, max(0LL, now - A[i])); }
    return score >= M * V;
}

