    long N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<long> A(N);
    for (long i = 0; i < N;i++)
        cin >> A[i];

    sort(A.begin(), A.end(), greater<long>());

    long border = A[P - 1];
    long not_border_count = 0;
    long count = 0;
    for (long i = 0; i < N;i++) {
        if(A[i] > border) {
            count++;
            not_border_count++;
        }
        else if(A[i] == border) {
            count++;
        }
        else {
            break;
        }
    }

    long remind = (V - (N - count)) * M;
    border += remind / count;
    if(remind % count > not_border_count && not_border_count < P){
        border++;
    }

    for (long i = count; i < N;i++){
        if(A[i] + M >=border)
            count++;
        else
            break;
    }

    cout << count << endl;

    return 0;
}

