ll n,m,v,p;
bool f(ll arr[], ll mid){
    // cout << mid << "\n";
    ll temp[n];
    for(ll i=0;i<n;i++){
        temp[i] = arr[i];
    }
    ll val = temp[mid] + m;
    ll i=0;
    ll cnt = (v-1)*m;
    ll more=0;
    ll alreadymore = 0;
    for(ll i=0;i<n;i++){
        if(val < temp[i]) alreadymore++;
        if(alreadymore >= p) return 0;
    }
    while(more < p-1 && i<n){
        if(i!= mid) cnt -= m;
        if(cnt <= 0) return true;
        if(temp[i]+m > val) more++;
        i++;
    }
    if(temp[i] > val) return false;
    while(i<n){
        if(i!=mid) cnt = cnt - min((val-temp[i]),m);
        if(cnt <= 0) return true;
        i++;
    }
    return false;
}
