int main(){
    Init();
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vi a(n);
    rep(i, n) cin >> a[i];
    // スコア上昇の上限はジャッジの人数
    sort(all(a), greater<ll>());
    map<ll, bool> isOK;
    ll pos = 0, sum = 0;
    for(; pos<n; pos++){
        // 上位p-1個は無条件にOK
        if(pos < p-1){
            isOK[a[pos]] = true;
            continue;
        }
        // 累積和の更新
        sum += a[pos];
        // 既にOKの数字なら飛ばす
        if(isOK[a[pos]]) continue;

        // 全員に投票させれば降順p番目の数字を超えられる場合
        if(a[pos]+m >= a[p-1]){
            // 先頭p-1個に投票した後、残りの票を自分を含む自分以下の数値に割り振ることが可能な場合
            if(pos <= n-v+p-1){
                isOK[a[pos]] = true;
                continue;
            }
            // 割り振り切れない場合、自分より大きい値にフラットになるように振れるか
            else{
                // 自分の最高値
                ll selfMax = a[pos]+m;
                // 自分を累積和に加えているので一旦取り除く
                sum -= a[pos];
                // 自分より大きな数の個数と残りの票
                ll num = pos - (p-1);
                ll leftVote = ((v-(p-1))-(n-pos))*m;
                // 自分の最高値を超えないように、自分より大きな数に割り振れるか
                if(num*selfMax-sum >= leftVote){
                    sum += a[pos];
                    isOK[a[pos]] = true;
                    continue;
                }
                else break;
            }
        }
        else break;
    }
    cout << pos << endl;
}

