	sort(a,a+n);
	for (int i=0;i<n;i++) pre[i+1]=pre[i]-a[i];
	int ok=pro;
	while (a[ok+1]==a[pro-1]) ok++;
	for (int i=0;i<n;)
	{
		//cout <<i<<" "<<res<<" #########\n";
		bool fl=0;
		if (i<=ok) fl=1;
		else if (n-i>=k)
		{
			int it=lower_bound(a,a+n,a[i]-m)-a;
			if (it<pro) fl=1;
			//cout <<-a[i]<<" "<<it<<" ##\n";
		}
		else
		{
			ll ki=k-(n-i),ni=i;
			int it=lower_bound(a,a+n,a[i]-m)-a;
			ki-=it,ni-=it;
			ki*=m;
			int l=0,r=i,mid;
			while (l<r)
			{
				mid=(l+r)>>1;
				//cout <<l<<" "<<r<<" "<<mid<<" --- "<<mid*m+(ni-mid)*(-a[i]+m-1)-(pre[i]-pre[i-(ni-mid)])<<" "<<ki<<" ##\n";
