					r=mid;
				else l=mid+1;
			}
			//cout <<ki<<" "<<i<<" "<<-a[i]<<" "<<l<<" ##\n";
			it=lower_bound(a+l,a+n,a[i]-m)-a;
			if (it<pro) fl=1;
		}
		if (!fl) break;
		int j=i;
		while (a[i]==a[j] && i<n) res++,i++;
	}
	cout <<res;
	return 0;
}

