	v=v-(n-x);
	long long lastn=m*(v-1),bgt=0,sum=0;
	vector<long long>vv; 
	for(int i=1;i<x;i++)
		if(a[x]+m<a[i])
		{
			bgt++;
			lastn-=m;
		}
