    VLL A;
    REP(i,N) {
        LL tmp;
        cin >> tmp;
        A.PB(tmp);
    }
    sort(A.begin(),A.end());
    REP(i,N){
        cerr << A[i] << endl;
    }
    VLL S;
    S.PB(0);
    REP(i,N){
        S.PB(S[i]+A[i]);
    }
    cerr << " S = ";
    REP(i,N+1){
        cerr << S[i] << " ";
    }
    cerr << endl;


    LL INF=1001001001001;

    // Binary search
    LL ng = 0, ok = INF; //Initial (ng false, ok True)
    while (ok - ng > 1) {
        LL mid = (ng + ok) / 2;
        cerr << "mid=" << mid << endl;
        //here should be upper bound
        //auto i_next = upper_bound(A.begin(),A.end(),mid);

        LL id_next = upper_bound(A.begin(),A.end(),mid) - A.begin();
        cerr << "id_next= " <<id_next << endl;

        LL rest_add;
        LL n_target = N - P + 1 - id_next;

        if(n_target < 0) n_target = 0;
        cerr << "n_target= " << n_target << endl;

        rest_add = (V - (N- n_target) ) * M;
        if(rest_add < 0) rest_add = 0;
        cerr << "rest_add= " << rest_add << endl;


        // SUM from id_next to N-P
        LL sum = S[N-P + 1]- S[id_next];
        if(sum<0) sum=0;
        cerr << "sum= " << sum << endl;

        // Area is bigger than rest add
        if(n_target==0) ok = mid;
        else{
            ( (mid + M) * n_target - sum >= rest_add ? ok : ng) = mid;
        // equal is safe       
        }

    }
    cerr << "ok= " << ok << endl;

    //here must be lower_bound when same number is ok all number should be ok
    LL ans = A.end() - lower_bound(A.begin(),A.end(),ok);
    cerr << "ans= ";
    cout << ans << endl;

}



