bool bin(ll i) {
    ll sm = 0;
    ll k = A[i] + M;
    if (k < A[P - 1]) {
        return false;
    }
    sm += (P - 1) * M + (N - i) * M;
    for (ll x = P - 1; x < i; x++) {
        sm += max(ll(0), k - A[x]);
    }
    return (sm >= M * V);
}

