bool judge(long long n){
  if (n<P-1){ // P-1番目までは
    return true;
  } else if (A[n]+M<A[P-1]){
    return false;
  }
  long long sum = 0;
  for (int i=P-1; i<N; i++){
    if (i==n){
      continue;
    }
    sum += std::min(M, A[n]+M-A[i]);
  }
  if (sum >= M*(V-P)){
    return true;
  } else {
    return false;
  }
}

