vector< int > Div( int n ) {
    vector< int > ret;
    for( int i = 1; i * i <= n; ++i ) {
        if( n % i == 0 ) {
            ret.pb( i );

            if( i * i != n ) ret.pb( n / i );
        }
    }
    sort( all( ret ) );
    return ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    LL n, m, V, p;
    cin >> n >> m >> V >> p;
    vector< LL > v(n + 1);
    v[0] = LINF;
    for( int i = 1; i <= n; ++i ) {
        cin >> v[i];

    }
    sort( all(v), greater< LL >() );

    int cnt = p;
    LL sum = v[p];
    int d = 1;
    for( int i = p + 1; i <= n; ++i ) {
        int sel = V - ((p - 1) + (n - i) + 1);
        if( v[i] == v[p] ) {
            ++cnt;
            ++d;
            sum += v[i];
            continue;

        }
        if( sel <= 0 ) {
            if( v[p] <= v[i] + m ) {
                ++cnt;

            }
        } else if( sel >= i - p ) {
            ++d;
            sum += v[i];
            continue;

        } else {
            LL dif = (i - p) - sel;
            if( dif * m >= sum - (v[i] * d) ) {
                ++cnt;

            }
        }
        ++d;
        sum += v[i];

    }
    cout << cnt << endl;
    return 0;
}

