using Graph = vector<vector<uint32_t>>;
vector<bool> seen;
vector<uint32_t> dis, A_dis, T_dis;

void dfs(Graph &G, uint32_t v) {
  seen[v] = true;

  for (auto itr = G[v].begin(); itr != G[v].end(); ++itr) {
    if (seen[*itr]) continue;
    dis[*itr] = dis[v] + 1;
    dfs(G, *itr);
  }
}

int main() {
  int64_t N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int64_t> A(N), B;
  ArrayInput(A);
  sort(A.begin(), A.end());
  B = A;
  for (int64_t i = 0; i < (P - 1); ++i) {
    A.pop_back();
  }
  int64_t Border = *(A.end() - 1);
  int64_t Border_num = count(B.begin(), B.end(), Border);
  V -= (P - 1);
  int64_t cnt = 0;
  int64_t sum = 0;
  pair<int64_t, int64_t> sum_p;
  sum_p.first = 0;
  sum_p.second = 0;
  for (auto itr = A.begin(); itr != A.end() && Border > *itr; ++itr) {
    sum_p.first += *itr;
    ++sum_p.second;
  }
  for (auto itr = A.begin(); itr != (A.end() - 1); ++itr) {
    int64_t target = *itr + M, calc = M * ((V - 1) - distance(A.begin(), itr));
    sum_p.first -= *itr;
    --sum_p.second;
    if (target < Border) {
      ++cnt;
      continue;
    }
    calc -= ((target * sum_p.second) - sum_p.first);
    calc -= (target - Border) * Border_num;
    if (calc <= 0)
      break;
    else
      ++cnt;
  }
  cout << N - cnt << endl;
  return 0;
}

