    segment_tree<ll> rsq(n + 1, [] (ll a, ll b) { return a + b; }, 0);
    REP(i, n) rsq.update(i, a[i]);
    int r = n;
    for(int i = n - 1; i >= 0; i--) {
        while(a[r - 1] > a[i] + m) r--;
        if(n - r >= p) continue;
        int u = p - 1 - (n - r);
