        ll rest=(ll)m*(v-x-cnt[x]-p+1);
        int j=x+cnt[x];
        int last=n-p+1;
        int limit=(p>1?a[last]:a[n-1]+1);
        while(j<last && rest>0){
            ll y=a[x]+m-a[j];
            if (y<=0) return false;
            rest -= (ll)y*((a[j]<limit)?cnt[j]:last-j);
            j += cnt[j];
        }
        return rest<=0;
    };
    while(lo<hi){
        int mid=lo+(hi-lo)/2;
        if (va(mid))
