ll power(ll x, ll y, ll m=mod)
{
	if(y<0)
    {
		x = power(x,m-2);
		y = -y;
	}
	ll ans=1;
	x = x % m;
	while(y)
    {
		if(y&1) ans = (ans*x)%m;
		y=y/2;
		x=(x*x)%m;
	}
	return ans;
}

bool poss(ll c, ll arr[],ll pos,ll v, ll m, ll n, ll p)
{
    if(pos>(arr[n-c]+m))
    {
        return 0;
    }
    else if(pos==arr[n-c])
    {
        return 1;
    }
    else
    {
        ll cnt = 0;
        cnt = (p-1)*m;
        lp(i,0,n-p+1)
        {
            cnt += min((arr[n-c]+m-arr[i]),m);
        }
        if(cnt>=v*m)
        {
            return 1;
        }
        else
        {
            return 0;
        }

    }
}

