int32_t main() {
	ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	int n, m, v, p;
	cin >> n >> m >> v >> p;

	vi a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}

	sort(all(a), greater<int>());

	int ans = 0;

	if (v <= p) {
		for (int i = 0; i < n; i++) {

			if (a[i] + m >= a[p - 1]) {
				ans++;
			}
		}
		cout << ans;
		return 0;
	}

	vector<ll> pref(a.begin(), a.end());
	for (int i = 1; i < n; i++) {
		pref[i] = pref[i - 1] + a[i];
	}

	for (int i = 0; i < n; i++) {

		if (a[i] >= a[p - 1]) {
			ans++;
			continue;
		}

		int x = a[i] + m;

		if (x < a[p - 1]) continue;

		ll need = (ll)m * (v - p);
		ll can;

		if (x - a.back() < m) {

			can = (ll)x * (n - p) - (sum(p - 1, n - 1, pref) - a[i]);
		}
		else {

			int lf = p - 1;
			int rg = n - 1;

			while (lf < rg) {

				int md = (lf + rg) >> 1;

				if (x - a[md] < m) {

					lf = md + 1;
				}
				else {

					rg = md;
				}
			}

			can = (ll)x * (lf - p + 1) - sum(p - 1, lf - 1, pref);
			can += (ll)(n - lf) * m;
			if (i < lf) {

				can -= (x - a[i]);
			}
			else {

				can -= m;
			}
		}

		if (can >= need) {
			ans++;
		}
	}

	cout << ans;
}

