const int N=1e5+10;
LL rd()
{
	LL x=0,w=1;char ch=0;
	while(ch<'0'||ch>'9'){if(ch=='-') w=-1;ch=getchar();}
	while(ch>='0'&&ch<='9'){x=(x<<3)+(x<<1)+(ch^48);ch=getchar();}
	return x*w;
}
int n,m,v,p,a[N];
bool ck(int md)
{
	LL rs=1ll*(v-1)*m;
	int j=p-1;
	for(int i=n;i;--i)
	{
		if(i==md) continue;
		if(j>0)
		{
			rs-=m;
			j-=a[i]>a[md];
		}
		else
		{
			int dt=min(m,a[md]+m-a[i]);
			if(dt<0) return 0;
			rs-=dt;
		}
	}
	return rs<=0;
}

int main()
{
	n=rd(),m=rd(),v=rd(),p=rd();
	for(int i=1;i<=n;++i) a[i]=rd();
	sort(a+1,a+n+1);
	int l=1,r=n;
	while(l<=r)
	{
		int mid=(l+r)>>1;
		if(ck(mid)) r=mid-1;
		else l=mid+1;
	}
