void solv()
{
	int N, M, V, P; scanf("%d%d%d%d", &N, &M, &V, &P);
	int table[N_MAX];
	for (int i = 0; i < N; i++){
		int A; scanf("%d", &A);
		table[i] = A;
	}

	sort(table, table + N);

	if (P >= V){
		for (int i = 0; i < N; i++){
			if (table[i] + M >= table[N - P]){
				printf("%d", N - i);
				break;
			}
		}
	}
	else{
		V -= P - 1;
		if (table[V - 1] + M >= table[N - P]){
			for (int i = V - 1; i >= 0; i--){
				int rem = V - (i + 1);
				lli sum = 0;
				for (int j = i + 1; j <= N - P; j++){
					sum += min(M, table[i] + M - table[j]);
				}
				if (sum  < (lli)rem*(lli)M){
					printf("%d", N - (i + 1));
					return;
				}
				sum += (lli)(M, table[N - P] - table[i]);
			}

			printf("%d", N);
		}
		else{
			for (int i = V; i < N; i++){
				if (table[i] + M >= table[N - P]){
					printf("%d", N - i);
				}
			}
		}
	}

	return;
}

