bool chck(int x){
    int vv=v-1, tmp=0;
    multiset<int> st;
    // cout<<x<<endl;
    for(int i=0; i<n; ++i){
        // cout<<a[i]<<" ";
        if(i==x)
        continue;
        if(a[i]>a[x]+m){
            ++tmp;
        }
        if(a[i]>a[x]+m || a[i]<=a[x]){
            --vv;
        }
        else{
            st.insert(-(a[x]+m-a[i]));
        }
    }
    if(tmp>p-1){
        // cout<<"!!"<<endl;
        return 0;
    }
    if(vv<=0){
        return 1;
    }
    // cout<<tmp<<endl;
    // cout<<"__|"<<tmp<<endl;
    tmp=p-1-tmp;
    // cout<<tmp<<endl;
    while(tmp-- && st.size()){
        st.erase(--st.end());
        --vv;
    }
    if(vv<=0){
        return 1;
    }
    ll sm=0, tmp1;
    // cout<<vv<<" "<<tmp<<endl;
    while(vv){
        // cout<<st.size()<<endl;
        if(st.size()==0)
            return  0;
        tmp=-*st.begin();
        sm+=tmp;
        st.erase(st.begin());
        while(sm<m){
            if(st.size()==0)
                return 0;
            tmp=-*st.begin();
            sm+=tmp;
            st.erase(st.begin());
        }
        --vv;
        tmp1=tmp-(sm-m);
        tmp=min(m, tmp)-tmp1;
        st.insert(-tmp);
        sm=0;
    }
    return 1;
}
