bool check(int x){
	if(x >= v)return true;
	int vv = v - x;

	long long s = m * vv;
	long long mx = a[x] + m;
	int place = 1;

	for(int j=x+1;j<=n;j++){
		if(1ll * a[j] > mx){
			rem[j] = 0;
			++place;
			long long delta = min(s , m * 1ll);
			s -= delta;
		}
		else{
			long long delta = min(s , mx - a[j]);
			s -= delta;
			rem[j] = m - delta;
		}
	}

	for(int j=n;j>=x+1;j--){
		if(s == 0)break;

		long long delta =  min(s , 1ll * rem[j]);
		s -= delta;

		++place;
	}

	return place <= p;
}

