	if(cnt<p){
		return a[x]+m>=a[p];
	}
	cnt-=p-1;
	int num=a[x]+m;
	res.clear();
	for(int i=p;i<x;i++) res.push_back(a[i]);
	memset(sum,0ll,sizeof(sum));
	int cntt=0ll;
	for(int i=0;i<res.size();i++){
		if(i>0) sum[i]+=sum[i-1];
		res[i]=res[i]+sum[i];
		if(i+cnt>res.size()) continue;
		if(res[i]<num){
			sum[i]+=(num-res[i]);
			sum[i+cnt]-=(num-res[i]);
			cntt+=(num-res[i]);
		}
	}
	return cntt>=m;
}

