int main() {
  ll n, m, v, p;
  cin >> n >> m >> v >> p;
  vector<ll> a(n);
  for (int i = 0; i < n; i++) cin >> a[i];

  sort(a.begin(), a.end());  // 入れ替えてもいいのでとりあえずソート

  vector<ll> rui(n + 1);  // 累積和とっとく
  for (int i = 0; i < n; i++) rui[i + 1] = a[i] + rui[i];

  // cout << a << endl;
  // cout << rui << endl;

  ll ans = 0;
  for (int i = 0; i < n; i++) {
    ll tohyo = m * v;                                            // 残り投票数
    ll after = a[i] + m;                                         // m人全員がi番目に投票した姿
    ll ika = upper_bound(a.begin(), a.end(), a[i]) - a.begin();  // 自分以下の要素数
    tohyo -= ika * m;                                            // 自分以下には大量に投票してok
    ll migi = upper_bound(a.begin(), a.end(), after) - a.begin();
    if (p <= n - migi) continue;       // afterを超える存在が多すぎる
    tohyo -= (n - migi) * m;           // 元々負けが確定してる相手は積みまくってok
    ll bimcos = migi - ika;            // 微妙なやつの個数
    ll bimsum = rui[migi] - rui[ika];  // 微妙なやつの総和
    ll aki = bimcos * after - bimsum;  // 最大敷き詰めとの差
    tohyo -= aki;
    if (n - migi < p - 1) {  // もっと諦めれるなら差分をとって引く
      ll hami = (p - 1) - (n - migi);
      tohyo -= hami * m + (rui[migi] - rui[migi - hami]) - hami * after;
    }
    if (tohyo <= 0) {
      // cout << a[i] << "はいける" << endl;
      ans++;  // 残り投票数がない
    }
  }
  cout << ans << endl;
}

