bool check(ll i){
    ll norival = i + (p-1); // 無駄に選択する数
    ll rem = v - norival; // v個の残り
    if(rem <= 0 && a[i] + m >= a[n-p]){return true;}

    ll range = n - norival - 1; // +1しなきゃいけない範囲
    ll unselect = range-rem; // 1回あたり選ばなくていい数

    ll count = 0;
    for(int j = i + 1; j <= n-p; ++j) {
        count += (a[j] - a[i]);
    }
    --count;
    if(count > unselect * m){
        return false;
    }
    return true;
}

