    }

    sort(a.begin(), a.end());

    ll lb = 0, ub = n-1;
    while(ub - lb > 1){
        ll mb = (lb + ub) / 2;
        if(check(mb)){
            ub = mb;
        }else{
            lb = mb;
        }
    }
    cout << n-ub << endl;
}

