int main() {
  // 採用されうる問題数
  // ASを降順にした時、上位P-1番目までは確定
  // P番目以降にについて、スコアごとに二分探索していく
  ll N,M,V,P;cin>>N>>M>>V>>P;
  vector<ll> AS(N);
  REP(i,N) cin>>AS[i];

  // ASの降順取得
  sort(ALL(AS));
  reverse(ALL(AS));
  // DUMP(AS);

  vector<ll> dupas(AS);
  sort(ALL(dupas));
  auto checker = [&](ll x) {
    // Mを足してもP番目の数に到達できない場合
    if (x+M<AS[P-1]) return false;

    // x以降の数6|55...0
    ll smaller_cnt = upper_bound(ALL(dupas),x)-dupas.begin();
    ll tmp = 0;
    FOR(i,P-1,N-smaller_cnt) tmp += x+M-AS[i];
    ll baffer = ((P-1)+smaller_cnt)*M+tmp;
    return baffer>=M*V;
  };

  // スコアが最小でもOKの場合
  if (checker(AS.back())) {
    OUT(N);
    return 0;
  }

  ll left=AS.back(),right=AS[P-1];
  while (left<right) {
    ll mid = (left+right)/2;
    checker(mid) ? right=mid : left=mid+1;
  }
  // OUT(left);

  ll imp_cnt = lower_bound(ALL(dupas),left)-dupas.begin();
  OUT(N-imp_cnt);

  return 0;
}

