		if(mid >= v) {
			if(a[mid] + m >= a[n-p+1]) pos = 1;
		}
		else {
			ll left = m*v - mid*m, great = 0, val = a[mid] + m;
			for(ll i = n; i >= mid+1; --i) {
				if(a[i] > val) {
					left -= m;
					++great;
					continue;
				}
				used[i] = min(m, val - a[i]);
				left -= used[i];
			}
			if(great < p && left <= 0) pos = 1;
			else if(great < p) {
