    cin >> a.at(i);
  }
  sort(a.rbegin(), a.rend());
  long long ind = a.at(p - 1);
  sort(a.begin(), a.end());
  long long out = 0;
  long long count = 1;
  long long wa = 0;
  long long ind2;
  long long count2;
  for(int i = 0; i < n - 1; i++){
    if(ind - a.at(i) > m) continue;
    if(a.at(i) == a.at(i + 1)){
      if(i == n - 2) out += count;
      count++;
      continue;
    }else{
      if(ind - a.at(i) <= m){
        if(i + p >= v){
          out += count;
          count = 1;
        }else{
          long long sa = v - (i + p);
          if(wa == 0){
            wa = sa * m;
            for(int j = i + 1; j < n - p + 1; j++){
              wa += a.at(j);
            }
          ind2 = a.at(i);
          count2 = count;
          }else{
            wa = wa - ind2 * count2 - count2 * m;
            ind2 = a.at(i);
            count2 = count;
          }
          if(wa % (n - p - i) == 0){
            ind = wa / (n - p - i);
