	return l + rand()%(r-l+1);
}

void solve(){
    ll n,m,v,p;
    cin>>n>>m>>v>>p;
    v64 arr(n);
    forn(i, n)
    {
        cin>>arr[i];
    }
    sort(all(arr));
    v64 pref(n);
    pref[0] = arr[0];
    forsn(i, 1, n)
    {
        pref[i] = pref[i-1]+arr[i];
    }
    ll ans = p;
    forn(i, n-p)
    {
        ll quan = arr[i]+m;
        ll pos = ll(lower_bound(all(arr), quan+1)-arr.begin());
        if(n-1-pos+1 >= p) continue;
        ll req = v-1-i;
        req -= (p-1);
        if(req <= 0)
        {
            ans++;
            continue;
        }
        ll sm = pref[n-p];
        sm -= pref[i];
        sm = (n-p-i)*quan-sm;
        if(sm >= req*m)
        {
            ans++;
        }
    }
    cout<<ans<<ln;
}

