int check(int k){
	For(i,1,n)
		b[i]=a[i];
	int cnt=v-1-(n-k);
	if (cnt>0){
		LL tot=(LL)cnt*m;
		For(i,1,k-1){
			if (b[i]>a[k]+m)
				continue;
			LL d=max(0LL,a[k]+m-b[i]);
			tot-=d;
			b[i]+=d;
		}
		For(i,1,k-1){
			LL d=min(a[i]+m-b[i],tot);
			tot-=d;
			b[i]+=d;
		}
	}
	int c=p;
	For(i,1,k-1)
		if (b[i]>a[k]+m)
			c--;
	return c>0;
}
