int main(){
	ll n, m, k, p;
	scanf("%llu %llu %llu %llu", &n, &m, &k, &p);
	ll aa[n];
	for (ll i = 0; i < n; i++){
		scanf("%llu", &aa[i]);
	}
	sort(aa, aa + n);
	ll l = 0, r = n - 1;
	while (l < r){
		ll mid = l + (r - l) / 2, pos, a[n], s = 0, left = m * (k - 1);
		copy(aa, aa + n, a);
		for (ll i = 0; i < n; i++){
			if (i == mid) continue;
			if (a[i] > a[mid]){
				pos = i;
				break;
			}
			a[i] += m;
			left -= m;
			if (left == 0) break;
		}
		if (left > 0){
			ll uses[n];
			fill(uses, uses + n, m);
			for (ll i = pos; i < n; i++){
				if (a[i] >= a[mid] + m) break;
				if (left <= a[mid] + m - a[i]){
					a[i] += left;
					uses[i] -= left;
					left = 0;
					break;
				}
				uses[i] -= a[mid] + m - a[i];
				left -= a[mid] + m - a[i];
				a[i] = a[mid] + m;
			}
			if (left != 0){
				for (ll i = n - 1; i >= 0; i--){
					if (left <= uses[i]){
						a[i] += left;
						left = 0;
						break;
					}
					a[i] += uses[i];
					left -= uses[i];
				}
			}
		}
		a[mid] += m;
		bool ok = false, ye = false;
		map<ll, ll> ma;
		for (ll i = 0; i < n; i++) ma[a[i]]++;
		auto it = --ma.end();
		do{
			s += it -> second;
			if (it -> first == a[mid]) ye = true;
			if (s >= p){
				ok = ye;
				break;
			}
			it--;
		}while (it != ma.begin());
		if (ok){
			r = mid;
		}else{
			l = mid + 1;
		}
	}
	printf("%llu\n", n - l);
}

