            B[i] += canvote;
            vote -= canvote;
        }
        if (vote <= 0) return true;
        REP(i, P - 1) {
            int j = N - 1 - i;
            ll canvote = M - voted[j];
            voted[j] += canvote;
            B[i] += canvote;
            vote -= canvote;
        }
