    scanf("%lld", &temp);
    A.push_back(temp);
  }
  sort(A.begin(), A.end(), std::greater<long long>());

  long long edge_start = 0;
  long long edge_end = N-1;
  long long cand;
  while (edge_end - edge_start > 1){
    cand = (edge_start+edge_end)/2;
    if (judge(cand)){
      edge_start = cand;
    } else {
      edge_end = cand;
    }
    //printf("[%lld, %lld]\n", edge_start, edge_end);
  }
  printf("%lld\n",edge_start+1);
  return 0;
}

