typedef long long ll;  
ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN = 100000;

int n, njudge, neach, ntake;
int a[MAXN];

ll asum[MAXN + 1];

bool can(int idx) {
	if (idx < ntake) return true;
	int have = a[idx] + njudge;
	int need = a[ntake - 1];
	if (have < need) return false;
	int nsafe = ntake - 1 + (n - idx);
	//printf("idx=%d neach=%d nsafe=%d\n", idx, neach, nsafe);
	if (neach <= nsafe) return true;
	int nrem = neach - nsafe;
	int cnt = idx - (ntake - 1);
	ll sum = asum[idx] - asum[ntake - 1];
	ll lim = (ll)cnt * have;
	ll extra = lim - sum;
	//printf("nrem=%d njudge=%d extra=%lld\n", nrem, njudge, extra);
	return (ll)nrem * njudge <= extra;
}

int solve() {
	sort(a, a + n); reverse(a, a + n);
	//printf("a:"); REP(i, n) printf(" %d", a[i]); puts("");
	asum[0] = 0; REP(i, n) asum[i + 1] = asum[i] + a[i];
	int ret = 0;
	for (int l = 0, r = l; l < n; l = r) {
		int cur = a[l];
		while (r < n && a[r] == cur) ++r;
		int cnt = r - l;
		if (can(l)) ret += cnt;
	}
	return ret;
}

void run() {
	scanf("%d%d%d%d", &n, &njudge, &neach, &ntake);
	REP(i, n) scanf("%d", &a[i]);
	printf("%d\n", solve());
}

int main() {
	run();
	return 0;
}

