  vector<int> ds(N);
  for (int i = P; i < N; i++) {
    ds[i] = ds[i-1]+(A[P-1]-A[i]);
  }
  auto is_ok = [&](int i) {
    if (A[P - 1] - A[i] > M)
      return false;
    auto buf = long((P-1)+(N-i))*M + ds[i-1] + long(i-P)*(A[i]+M-A[P-1]);
