  };
  int l = P, r = N-1;
  int ans = P;
  while (l <= r) {
    auto c = (l+r)/2;
    if (is_ok(c)) {
      ans = c+1;
      l = c+1;
    } else {
      r = c-1;
    }
  }
  cout << ans << endl;

  return 0;
