public:
    static constexpr int kStressIterations = 0;

    static void generateTest(std::ostream& test) {
    }

    int pivot;
    vector<int> a;
    int n, m, v, p;

    bool check(int i) {
        int val = a[i];
        if (val == pivot) return true;
        if (val + m < pivot) {
            return false;
        }

        int rval = p - 1 + n - i;
        if (rval >= v) {
            return true;
        }
        int vv = v - rval;
        int len = i - p;
        if (vv > len / 2) {
            return false;
        }
        return val + m >= pivot;
    }

