int n, m, v, p, a[N];
inline bool check(int mid) {
	int cur = a[mid] + m, cv = v - 1, rnk = 0, LL = 0, RR;
	for (int i = 1; i <= n; i++)
		if (a[i] <= cur) {
			i--;
			rnk = i;
			cv -= min(cv, i);
			LL = i + 1;
			break;
		}
	int cs = 0;
	RR = mid;
	for (int i = 1; i <= n; i++)
		if (i != mid && a[i] <= a[mid]) cs++, RR = min(RR, i);
	RR--;
	cv -= min(cv, cs);
	for (int i = LL; i <= RR && cv; i++) {
		if (rnk < p - 1) {
			cv--;
			rnk++;
		} else {
			long long sum = 0;
			for (int j = i; j <= RR; j++) {
				sum += cur - a[j];
			}
			if (1ll * cv * m > sum) return false;
			cv = 0;
			break;
		}
	}
	return rnk <= p - 1;
}
