vint a;

bool isOK(ll index){
  if(a[p-1] > m + a[index]) return false;
  ll sum = 0;
  sum += p*m;
  sum += (n - 1 - index)*m;
  for(ll i=p-1; i<index; i++){
    sum += min((m+a[index]) - a[i], m);
  }
  return sum >= m*v;
}

ll binary_search(){
  ll left = -1;
  ll right = n;

  while(right - left > 1){
    ll mid = left + (right-left)/2;

    if(!isOK(mid)) right = mid;
    else left = mid;
  }

  return right;

}


