void solve() {
  ll N, M, V, P;
  cin >> N >> M >> V >> P;

  VL as(N);
  map<ll, ll> act;

  rep(i, N) {
    ll a;
    cin >> a;
    as[i] = a;
    act[a]++;
  }

  sort(all(as));

  auto is_ok = [&](ll index) -> bool {
    ll a = as[index];
    ll rest = M * V;
    ll served = 0;

    auto over_it = upper_bound(all(as), a + M);
    ll over_index = over_it - as.begin();
    ll over_a_ct = N - over_index;
    if (over_a_ct >= P) return false;
    rest -= over_a_ct * M;
    served += over_a_ct;
    ll rr = P - over_a_ct - 1;

    if (rest <= 0) return true;

    ll smaller_a_ct = upper_bound(all(as), a) - as.begin();
    rest -= smaller_a_ct * M;
    served += smaller_a_ct;

    if (rest <= 0) return true;

    over_index -= rr;
    rest -= rr * M;
    served += rr;

    if (rest <= 0) return true;

    ll b_i = upper_bound(all(as), a) - as.begin();

    for (ll ii = b_i; ii < over_index; ii++) {
      rest -= a + M - as[ii];
      served++;
    }

    return rest <= 0 && served >= V;
  };

  if (is_ok(0)) drop(N);

  ll ng = 0;
  ll ok = N - 1;

  while (ok - ng > 1) {
    ll mid = (ng + ok) / 2;
    if (is_ok(mid)) {
      ok = mid;
    } else {
      ng = mid;
    }
  }

  ll res = N - ok;
  cout << res << endl;
}

