	int low = p, top = n - 1, ans = p, mid;

	while(low <= top){
		mid = low + top >> 1;
		if(ok(mid)){
			ans = max(ans, mid + 1);
			low = mid + 1;
		} else {
			top = mid - 1;
		}
	}

	printf("%d\n", ans);
	return 0;
}

