bool f(ll mid){
	ll tt = m * v;
	memcpy(b, a, sizeof(a));
	ll lim = a[mid] + m;
	b[mid] = lim;
	tt -= m;
	for(int i = n-1; i >= 0; i--){
		if(tt == 0) break;
		if(i != mid){
			if(b[i] > lim){
				b[i] += min(m, tt);
				tt -= min(m, tt);
			}
			else if(b[i] < lim){
				ll d = min(m, lim - b[i]);
				b[i] += min(d, tt);
				tt -= min(d, tt);
			}
		}
	}
	if(tt){
		for(int i = 0; i < n; i++) if(i != mid){
			ll d = b[i] - a[i];
			b[i] += min(tt, m-d);
			tt -= min(tt, m-d);
		}
	}
	int cnt = 0;
	for(int i = 0; i < n; i++){
		cnt += b[i] > lim;
	}
	return cnt < p;
}

