int check(vector<int> &a, int lstart, int rstart, ll m, int p, int v) {
    int n = a.size(), res = 0;
    ll have = (rstart - p) * m;
    for(int i = lstart, j = rstart; i < p && j < n; i++, j++) {
        if(a[j] + m - a[i] >= 0) {
            have -= (a[j] + m - a[i]);
            res++;
        }
    }
    return have > 0 ? max(0LL, res - have) : res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    int n, m, v, p;
    cin >> n >> m >> v >> p;

    vector<int> a(n);
    for(int i = 0; i < n; i++) cin >> a[i];
    sort(rbegin(a), rend(a));

    int lstart = max(max(0, p - v), v + p - n);
    int lo = p, hi = n - (p - lstart);
    int init_lo, init_hi;
    if(init_lo = check(a, lstart, lo, m, p, v) < p - lstart) {
        cout << init_lo + p << endl;
    }
    else if(init_hi = check(a, lstart, hi, m, p, v) == p - lstart) {
        cout << n << endl;
    }
    else {
        while(hi - lo > 1) {
            int mid = (hi - lo) / 2 + lo;
            if(check(a, lstart, mid, m, p , v) == p - lstart) {
                lo = mid;
            }
            else {
                hi = mid;
            }
        }

        int ans = lo + check(a, lstart, lo, m, p, v);
        for(int i = ans; i < n && a[i] == a[i - 1]; i++) ans++;
        cout << ans << endl;
    }
}

