ll n, m, v, p;
ll arr[100002];
ll sum[100002];
ll ans;

ll countNum(ll x){
    ll l = 1, r = n, ret = n+1;
    while(l<=r){
        ll m = (l+r)>>1;
        if(arr[m] > x){
            ret = m;
            r = m-1;
        }
        else l=m+1;
    }
    return ret;
}

int main(){
    scanf("%lld %lld %lld %lld", &n, &m, &v, &p);
    for(ll i=1; i<=n; i++) scanf("%lld", &arr[i]);
    sort(arr+1, arr+n+1);
    for(ll i=1; i<=n; i++) sum[i] = sum[i-1] + arr[i];
    for(ll i=v; i<=n; i++){
        if(arr[i] + m >= arr[n-p+1]) ans++;
    }
    for(ll i=v-1; i>=1; i--){
        ll idx = countNum(arr[i] + m);
        if(n+1-idx >= p) break;
        if(n+1-idx >= v-1){
            ans++;
            continue;
        }
        ll space = p - (n+1-idx) - 1;
        idx -= space;
        ll sum1 = m * (v - (n+1-idx) - 1);
        ll sum2 = (arr[i] + m) * (idx - 2) - (sum[idx-1] - arr[i]);
        ll tmp = countNum(arr[i] - 1) - 1;
        sum2 -= arr[i] * tmp - sum[tmp];
        if(sum1 <= sum2) ans++;
    }
    printf("%lld", ans);
}

