// m judge, v problems, first p problems
ll n, m, v, p;
ll a[100005], b[100005];

// score x is good
bool good(ll x) {
    // printf("Good %lld\n", x);

    if (x < p)
        return true;

    ll newsc = a[x] + m;

    {
        int j = 0;
        for (int i = 0; i < n; i++)
            if (i != x)
                b[j++] = a[i];
    }

    ll rem = m * (v - 1); // already burn m into newsc

    for (int i = 0; i < n - 1; i++) {
        ll canadd = i < p - 1 ? min(rem, m) : max(0ll, min(rem, min(newsc - a[i], m)));
        b[i] += canadd;
        rem -= canadd;
    }

    if (rem > 0) {
        // spend from front?
        // if v>p, i.e. judges can add many questions,
        // we have added every problem to newsc. i.e. if we add any more,
        // the problem cannot quality.
        // if v<p, i.e. judges can add few questions,
        // then the quota is already burnt.
        return false;
    }

    sort(b, b + n);
    reverse(b, b + n);

    return newsc >= b[p - 1];
}

bool obj(ll x) { return !good(x); }

