        while (cnt > 0) {
            it = first;
            step = cnt / 2;
            it += step;
            if (obj(it) < 1) {
                first = ++it;
                cnt -= step + 1;
            } else {
                cnt = step;
            }
        }

        cout << first << endl;
    }
}

