#define N 100100

int a[N];
ll pref[N];

void solve() {
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    REP(i, 1, n + 1) {
        cin >> a[i];
    }
    sort(a + 1, a + n + 1);

    reverse(a + 1, a + n + 1);

    REP(i, 1, n + 1) {
        pref[i] = pref[i - 1] + a[i];
    }

//    REP(i, 1, n + 1) {
//        cout << a[i] << ' ';
//    }
//    cout << endl;
    int ans = 0;
    int it = 0;

    REP(i, 1, n + 1) {
        ll A = a[i] + m;
        while (a[it + 1] > A) it++;

        ll need = v - 1 - it - (n - i);
        if (it >= p) {
            break;
        }

        ll rem = p - it - 1;

        assert(rem >= 0);
        ll x;
        if (i - 1 < it + rem) {
            x = 0;
        } else
            x = (1ll * A * (i - 1 - (it + rem)) - (pref[i - 1] - pref[it + rem])) / m;

        if (need <= x + rem) {
            //cout << 1 << ' ';
            ans++;
        } else {
            break;
        }
//        cout << "it = " << it << endl;
//        cout << need << ' ' << rem << ' ' << x + rem << ' ' << endl;


    }

    cout << ans << endl;
}

