using ll = long long;
const int maxn = 1e5+7;

ll n, m, v, p, a[maxn], pre[maxn];

bool gao(ll x) {
	ll posl = std::lower_bound(a+1, a+1+n, x)-(a);
	ll posr = std::upper_bound(a+1, a+1+n, x+m)-(a);
//	std::cout << x << ' ' << x+m << ' ' << posl << ' ' << a[posl] << ' ' << posr << ' ' << a[posr] << '\n';
	assert(posl > 0);
	assert(posr <= n+1);
	posr = std::min(posr, n-p+2);
	posl = std::min(posl, n-p+2);
	if (x+m < a[n-p+1]) {
		return false;
	}
	ll ans = (posl-1)*m+(p-1)*m;
	ans += (x+m)*(posr-posl)-(pre[posr-1]-pre[posl-1]);
//	std::cout << (posl-1+1)*m << ' ' << (p-1)*m << ' ' << (x+m)*(posr-posl) << ' ' << (pre[posr-1]-pre[posl-1]) << ' ';
//	std::cout << ans << ' ' << v*m << '\n';
//	std::cout << "----------\n";
	return ans >= (v*m);
}

int main(int argc, char *argv[]) {  
	std::ios::sync_with_stdio(false);
	std::cin.tie(0); 
	std::cin >> n >> m >> v >> p;
	for (int i = 1; i <= n; i++) {
		std::cin >> a[i];
	}
	std::sort(a+1, a+n+1);
	pre[0] = 0;
	for (int i = 1; i <= n; i++) {
		pre[i] = a[i] + pre[i-1];
	}
//	for (int i = 1; i <= n; i++) {
//		std::cerr << a[i] << " \n"[i==n];
//	}
//	std::cout << "----------\n";
	int res = 0;
	for (int i = 1; i <= n; i++) {
		if (gao(a[i])) {
			res++;
		}
	}
	std::cout << res << '\n';
}

