bool C(ll mid) {
  vll b;
  {
    ll cnt = 0;
    repb(i, n){
      if(i != mid){
        b.emplace_back(a[i]);
        cnt++;
      }
      if(cnt == n-p) break;
    }
  }
  dump(mid, b);
