// 二分探索
// 求める点以上の場合にtrueを返すよう実装する。
template <class V>
V binary_search(V _l, V _r, function<bool(V)> f) {
    V l = _l, r = _r;
    while(r>l) {
        ll mid = (l+r)/2;
        if (f(mid)) {
            r = mid;
        } else {
            l = mid;
        }
        if (l+1==r) {
            if (f(l)) {
                r = l;
            } else {
                l = r;
            }
        }
    }
    return l;
}

