int Ca(int l,int r)
{
	int L=lower_bound(a+1,a+n+1,l)-a;
	int R=upper_bound(a+1,a+n+1,r)-a;
	R--;
	if(L>R) return 0;
	return R-L+1;
}
int Cal(int l,int r)
{
	int L=lower_bound(a+1,a+n+1,l)-a;
	int R=upper_bound(a+1,a+n+1,r)-a;
	R--;
	if(L>R) return 0;
	return sum[R]-sum[L-1];	
}
int Ch(int l,int r,int num)
{
	int cnt=r-l+1;
	cnt=cnt*m+(sum[r]-sum[l-1])-num*cnt;
	return cnt;
}
int Calc(int cost,int num,int l,int r)
{
	int L=lower_bound(a+1,a+n+1,l)-a;
	int R=upper_bound(a+1,a+n+1,r)-a;
	R--;
	r=R;
	if(L>R) return inf;
	int best=-1;
	while(L<=R)
	{
		int mid=(L+R)/2;
		if(Ch(mid,R,num)>=cost) best=mid,L=mid+1;
		else R=mid-1;
	}
	if(best==-1) return inf;
	return r-best+1;
}
