///Can be optimized with radix sort to O(Nw)
///and the checker for the binary search can be done in O(1)

#include <bits/stdc++.h>

#define MAX_N 100000

using namespace std;

typedef long long lint;

lint a[MAX_N + 1];
lint b[MAX_N + 1];

lint mx;
lint rez;

lint n, m, v, p;

bool pos(lint poz)
{
    lint nr = a[poz];
    if(nr >= a[n - p + 1])
        return 1;

    int k = 0;
    for(int i = poz + 1; i <= n - p + 1; i ++)
        b[++ k] = a[i];

    nr += m;
    lint ramas = m * (v - poz - (p - 1));
    lint nx = a[n - p + 1];

    if(ramas <= 0)
        return (nr >= nx);

    lint sum = 0;
    for(int i = 1; i <= k; i ++)
    {
        if(b[i] > nr)
            return 0;

        sum += min(m, nr - b[i]);
    }

    return (ramas <= sum);
}

lint cautBin()
{
    if(pos(1))
        return a[1];

    lint i = 1;
    lint pas = 1 << 29;
    while(pas != 0)
    {
        if(i + pas <= n && pos(i + pas) == 0)
            i += pas;

        pas >>= 1;
    }

    return a[i + 1];
}

