        return S - D <= M * (N - V);
    };
    int l = -1, r = y;
    while(r - l > 1) {
        int mid = (l + r) / 2;
        OK(mid) ? r = mid : l = mid;
    }
    cout << N - r << '\n';
    return 0;
}

