int n, m, v, p;
vector <int> a;

bool check(int pos) {
	int vv = v;
	vv -= n - pos;
	vv -= p - 1;
	if (vv <= 0 && a[pos] + m >= a[p - 1]) {
		return true;
	} else if (vv <= 0) {
		return false;
	}
	vector <int> b;
	for (int i = p - 1; i < pos; i++) {
		b.push_back(a[i]);
	}
	int sz = (int) b.size();
	reverse(b.begin(), b.end());
	int fval = a[pos] + m;
	ll sum = 0;
	for (int i = 0; i < sz; i++) {
		int t = fval - b[i];
		if (t < vv) {
			return false;
		}
		sum += min(m, fval - b[i]);
	}
	if (sz >= vv && sum >= vv * m) {
		return true;
	}
	return false;
}

