using lint = long long int;
#define FOR(i, begin, end) for(int i=(begin),i##_end_=(end);i<i##_end_;i++)
#define IFOR(i, begin, end) for(int i=(end)-1,i##_begin_=(begin);i>=i##_begin_;i--)
#define REP(i, n) FOR(i,0,n)
#define IREP(i, n) IFOR(i,0,n)
constexpr int MOD = 1000000007;
int main()
{
    lint N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<lint> A(N);
    REP(i, N) cin >> A[i];
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());
    vector<lint> sum(N+1);
    FOR(i, 1, N+1) {
        sum[i] = A[i-1] + sum[i-1]; 
    }
    lint ans = 0;
    bool lastup = false;
    REP(i, N) {
        if(i > 0 && A[i] == A[i-1] && lastup) {
            ans++;
            continue;
        }
        if(i < N - (V - P)) {
            if(A[i] + M >= A[P-1]) {
                ans++;
                lastup = true;
            } else {
                lastup = false;
            }
        } else {
            lint target = A[i] + M;
            lint ksum = sum[i] - sum[P-1];
            ksum += M * (V - P - (N-i-1));
            if(target >= ceil((double)ksum / (i - (P-1)))) {
                ans++;
                lastup = true;
            } else {
                lastup = false;
            }
        }
    }
    cout << ans << endl;
}

