    cin>>a[i];
  }
  sort(ALL(a));
  long long s[n];
  REP(i,n){
    if(i == 0){
      s[i] = a[i];
    }else{
      s[i] = s[i-1] + a[i];
    }
  }
  long long ans = 0;
  REP(i,n){
    auto iter_upper = upper_bound(ALL(a), a[i]+m);
    long long idx_upper = distance(a.begin(), iter_upper);
    long long cnt = n - idx_upper;//a[i] + mより大きい要素数。
    //cout<<cnt<<endl;
    if(cnt >= p){
      continue;
    }
    long long j = idx_upper - 1;
    //cout<<j<<endl;
    long long sp = i + p - 1 - cnt;
    //long long temp = m*i + (a[i] + m)*(j-i) - (s[j]-s[i]);
    long long temp;
    if(sp+1<=j){
      temp = m*sp + (a[i]+m)*(j-sp) - (s[j] - s[sp + 1]);
    }else{
      temp = m*j;
      //temp = m*i + (a[i] + m)*(j-i) - (s[j]-s[i]);
    }
    if(temp + m*cnt >= m*(v-1)){
      ans++;
      cout<<temp + m*cnt<<endl;
      cout<<a[i]<<endl;
    }
  }
  cout<<ans<<endl;
  return 0;
}

