	u6 calc() {
		vector<s6> buf;
		read(buf, N);
		sort(ALL(buf));
		u6 result = P - 1;
		if (V <= P) {
			V = 1;
		}
		else { V -= P - 1; }
		vector<s6> buf2;
		s6 s = N - P + 1;
		buf2.resize(s);
		partial_sum(buf.begin(), buf.begin() + s, buf2.begin());
		//u6 s = accumulate(buf.begin(),buf.begin()+N-P+1, 0ull);

		s6 n = 0;
		for (; n < buf2.size(); ++n) {
			auto l = buf[n] + M;
			//auto r = (buf2.back() - buf2[n] + M * (V - 1 - n)) / double(buf2.size() - n - 1);
			s6 rsize = (s6(V) - 1 - n);
			if (rsize < 0)rsize = 0;
			auto r = buf2.back() - buf2[n] + M * rsize;
			//r = max(r, double(buf[s-1]));
			l *= buf2.size() - n - 1;
			r = max(r, buf[s - 1] * (buf2.size() - n - 1));
			if (l >= r) {
				break;
			}
		}
		return result + s - n;
	}

