bool check(ll arr[], ll n, ll m, ll v, ll p, ll mid)
{
	ll cnt = 0, val = arr[mid], i;
	fo(i, 0, n){
		if(arr[i] > val) break;
		cnt++;
	}
	if(n - p <= cnt - 1)
		return true;
	val += m;
	ll g = max(0ll, v - cnt);
