        }else{
            i64 sum = (p-1)*m + (n-mid-1)*m;
            for(int i=p;i<mid;++i)sum += max((i64)0, problems[mid]+m-problems[i]);
            if(sum >= m*(v-1))valid = mid;
            else invalid = mid;
        }
    }

    cout << valid + 1 << endl;

    return 0;
}

