template <typename T>
T meguru_BinarySearch(T ok, T no, function<bool(T)> isVarid) {
    while (abs(ok - no) > 1) {
        T mid = (ok + no) / 2;
        if (isVarid(mid))
            ok = mid;
        else
            no = mid;
    }
    return ok;
}

// a[i]をp位以内にできるか
bool check(lint cand) {
    lint modi = a[cand] + m;
    if (modi < a[n - p]) {
        return false;
    }
    lint l = cand + 1, r = n - p + 1;
    lint limit = 0;
    for (int i = l; i < r; i++) {
        limit += min(m, modi - a[i]);
    }
    return limit >= (v - l - n + r) * m;
}

