// mid ... 添え字 => a[mid]は採用されるか
// midが採用される 
// midがp以内である(n-mid+<=p) => ok
// midがpより後である =>
// midを+1, 0~mid-1を+1する。残り v-(mid+1)
// midがp番目になるには2つ条件が必要
// - v-(mid+1)<=p-1
// - a[mid]+m>=a[n-p (p番目)]
bool isOk(ll mid){
  if(n-mid<=p) return 1;

  ll rem=v-(mid+1)-(p-1); // midを選ぶ上で1人が影響のない分を投票した残り

  if(rem<=0){
    if(a[mid]+m>=a[n-p]) return 1;
  }else{
    ll cnt=(n-(p-1))-(mid+1);
    ll d=(sum[n-(p-1)]-sum[mid+1]);
    ll x=(a[mid]+m)*cnt-d;
    // cout<<mid<<' '<<d<<' '<<x<<' '<<rem<<' '<<cnt<<endl;
    if(x>=rem*m && a[mid]+m>=a[n-p]) return 1;
  }
  return 0;
}


signed main()
{
  cin.tie( 0 ); ios::sync_with_stdio( false );

  cin>>n>>m>>v>>p;

  a.resize(n);
  rep(i,n) cin>>a[i];
  vsort(a);
  sum.resize(n+1);
  rep(i,n) sum[i+1]=sum[i]+a[i];

  // rep(i,n) cout<<a[i]<<' ';
  // cout<<endl;

  ll ng=-1, ok=n-1;
  while(abs(ok-ng)>1){
    ll mid=(ok+ng)/2;
    if(isOk(mid)) ok=mid;
    else ng=mid;
  }
  ll ans=n-ok;

  cout<<ans<<endl;
}

