typedef long long ll;

ll N, M, V, P;
vector<ll> A, S;

bool check(int x) {
    int X = upper_bound(A.begin(), A.end(), A[x]) - A.begin() - 1;
    if (X + P >= V) {
        return (A[X] + M) >= A[N - P];
    }
    int l = X + 1, r = N - P;
    ll gain = A[X] + M;
    // 配らなければいけない残スコア
    ll rest = M * (V - X - P); // x以下の問題と上位P-1個にはM個配って良い,x自身にもM個配っているので,それらを除いた個数*M
    ll pool = 0;
    for (int i = l; i <= r; i++) {
        if (A[i] > gain) return false;
        pool += min(M, gain - A[i]);
    }
    return (rest <= pool);
}

int main() {
