    sort(A.begin(), A.end());
    rep(i, N)S[i + 1] = S[i] + A[i];

    int ok = N - 1, ng = -1;
    while (ok - ng > 1) {
        int mid = (ok + ng) / 2;
        (check(mid) ? ok : ng) = mid;
    }
    cout << N - ok << endl;
    return 0;
}

