using namespace std;

long long N, V, M, P, A[100005];
long long lo, mid, hi, best;

bool works(long long x) {
  long long bigger = 0;
  long long left = M * (V-1);
  for (long long i = 0; i < N; i++) {
    if (i == x-1) continue;
    if (A[i] > A[x-1] + M) {
      //printf("%lld\n", i);
      left -= M;
      bigger++;
    } else if (bigger < P-1) {
      left -= M;
      bigger++;
    } else {
      left -= min(M, A[x-1] + M - A[i]);
    }
    //printf("%lld %lld %lld %lld\n", x, i, left, bigger);
  }

  return (left <= 0 && bigger <= P-1);
}

int main() {
  scanf("%lld %lld %lld %lld", &N, &M, &V, &P);
  for (long long i = 0; i < N; i++) scanf("%lld", &A[i]);

  sort(A, A + N, greater<int>());

  lo = 0, hi = N;
  while (lo <= hi) {
    mid = (lo + hi) / 2;
    if (works(mid)) {
      best = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }

  printf("%lld\n", best);
}

