int judge(li a,const map<li,li>& mp,li m,li v,li p){
  li s=0,cnt=0;
  for(auto itr=mp.rbegin();itr!=mp.rend();itr++){
    if(itr->first > a+m){
      s+=itr->second;
    }
    else break;
  }
  if(df)printf("upper count is %d\n",s);
  if(s>=p)return 0;
  s=0;p--; // p-1 問は無限でよい
  for(auto itr=mp.rbegin();itr!=mp.rend();itr++){
    if((itr->second) <= p){
      s+= itr->second * m; // m 人が推薦
      p-= itr->second;     // 枠は減る
    }
    else if(p>0){
      s+=p * m;  // p枠 はmax
      s+= (itr->second-p)*min(m,(a+m- (itr->first)));  // 残りは a+m と同じだけ
    }else{
      s+= (itr->second)*min(m,(a+m- (itr->first)));  // 全部 a+m と同じだけ
    }
  }
  if(s>=m*v)return 1;
  return 0;
}

