bool f(const vector<int>& A, int index, int P, int VV, int M) {
	if (index < P) {
		return true;
	}
	int target = A[index];
	priority_queue<int> req;
	int su = 0;
	FOR(i, P-1, index) {
		su += A[i] - target;
	}
	int cnt = su / VV;
	if (su % VV != 0) ++cnt;
	return cnt <= M;
}

