	int ok = 0;
	int ng = A.size();
	int VV = N - V;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if (f(A, mid, P, VV, M)) ok = mid;
		else ng = mid;
	}
	cout << ok + 1 << endl;
}

