boolean check(int mid) {
	int hig = V - 1, r1 = m, r2 = 0;
	int cnt = 0, r = n;
	for (r = n; r && cnt < P - 1; r--) {
		if (r == mid)
			continue;
		hig--, cnt++;
	}
	for (int i = 1; i <= r; i++) {
		if (i == mid)
			continue;
		if (a[i] > a[mid] + m)
			return false;
		int need = min(m, a[mid] + m - a[i]);
		if (r1 > need) {
			r1 -= need;
			r2 += need;
		} else {
			r1 = need - r1;
			r2 = m - r1;
			swap(r1, r2);
			hig--;
		}
	}
	return hig <= 0;
}

