// single add, single read, range sum
struct BIT {
	size_t n;
	size_t n2;
	std::vector<int> data;
	BIT (size_t n) {
		this->n = n;
		for (n2 = 1; n2 < n; n2 *= 2);
		data.resize(n + 1);
	}
	inline void add(size_t index, int value) {
		for (int i = index + 1; (size_t) i <= n; i += i & -i) data[i] += value;
	}
	inline int sum(size_t r) const { // sum of [0, r]
		int res = 0;
		for (int i = r + 1; i; i -= i & -i) res += data[i];
		return res;
	}
};

size_t lower_bound(const BIT &tree, const std::vector<int> &a, int value) {
	/*
	std::cerr << "lower_bound call" << std::endl;
	for (auto i : a) std::cerr << i << " ";
	std::cerr << std::endl;
	for (size_t i = 1; i <= tree.n; i++)
		std::cerr << tree.data[i] << " ";
	std::cerr << std::endl;*/
	// do lower_bound in a[i] => a[i] + tree.sum(i) in O(logN) time
	if (a.back() + tree.sum(a.size() - 1) < value) return a.size();
	int l = 0;
	int r = tree.n2;
	int cur_sum = 0;
	while (r - l > 1) {
		size_t mid = l + (r - l) / 2;
		if (mid >= a.size()) {
			r = mid;
			continue;
		}
		int cur = a[mid - 1] + cur_sum + tree.data[mid];
		if (cur >= value) r = mid;
		else l = mid, cur_sum += tree.data[mid];
	}
	// std::cerr << "lower_bound result : " << l << std::endl;
	return l;
}


