bool che(vector<int> ar, int k, int n, int m, int v, int p){
    ar[k] += m;
    int hyo = m * v - m;
    int ki = ar[k];
    sort(ar.rbegin(),ar.rend());
    if (ar[p-1] > ki) return false;
    if (ar[p-1] <= ki){
        hyo -= (p-1) * m;
        if (hyo <= 0) return true;
        int cnt = n-1;
