const ll NUM = 101010;

ll N, M, v, p;
V A;
ll tmp[NUM];
ll check(ll idx){
    rep1(i, N)tmp[i] = A[i];
    ll sum = M * v;
    for(ll i = idx; i <= N; i++, sum -= M){
        if(sum <= 0)break;
        tmp[i] += M;
    }
    for(ll i = 1; i < p; i++, sum -= M){
        if(sum <= 0)break;
        tmp[i] += M;
    }
    for(ll i = p; i < idx; i++){
        if(sum <= 0)break;
        ll hoge = tmp[idx] - tmp[i];
        if(hoge < 0)return 0;
        tmp[i] += hoge;
        sum -= hoge;
    }

    if(sum > 0)return 0;
    if(tmp[idx] < tmp[p])return 0;
    return 1;
}

