#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

int n,v,p;
ll a[100100],b[100100],m;

bool check(int j){
	int i,cnt=v-1;
	ll t,lft,tmp;
	for(i=0; i<n; ++i){
		b[i] = a[i];
	}
	b[j] += m; t = b[j];
	for(i=0; i<n; ++i){
		if(b[i] > a[j] || (!cnt)){
			continue;
		}
		b[i] += m;
		--cnt;
	}
	lft = m*cnt;
	for(i=(n-1); i>=0; --i){
		if(!lft){
			break;
		}
		tmp = min({m+a[i]-b[i],t-b[i],lft});
		b[i] += tmp;
		lft -= tmp;
	}
	for(i=n-1; i>=0; --i){
		if(!lft){
			break;
		}
		if(b[i]-a[i]==m){
			continue;
		}
		tmp = min(m+a[i]-b[i],lft);
		b[i] += tmp;
		lft -= tmp;
	}
	sort(b,b+n,greater<ll>());
	return (b[p]<=t);
}

int main(void){
	int i,ok,ng,med,ans=0;
	cin >> n >> m >> v >> p; --p;
	for(i=0; i<n; ++i){
		cin >> a[i];
	}
	sort(a,a+n);
	ok = n-1; ng = -1;
	while(ok-ng>1){
		med = (ok+ng)/2;
		if(check(med)){
			ok = med;
		}else{
			ng = med;
		}
	}
	for(i=0; i<n; ++i){
		if(a[i]>=a[ok]){
			++ans;
		}
	}
	cout << ans << endl;
	return 0;
}

