void solve() {
	int N, M, V, p; cin >> N >> M >> V >> p;
	vector<int>A(N);
	REP(i, N)cin >> A[i];
	VSORT(A); VREVERSE(A);
	int ok = p, ng = N + 1;
	//print_space(A);
	while (abs(ok - ng) > 1) {

		int mid = (ok + ng) / 2;
		//print(mid);
		int id = mid - 1;
		int rem = V;
		rem -= 1;
		if (A[id] + M < A[p - 1]) {
			ng = mid;
			continue;
		}
		rem -= (N - mid);
		rem -= p - 1;
		if (rem <= 0) {
			ok = mid;
			continue;
		}
		vector<int>tmp;
		for (int i = p - 1; i < id; i++)tmp.push_back(A[i]);
		//print_space(tmp);
		int las = A[id] + M;
		int mx = tmp[rem - 1];
		int addRem = M;
		//DEBUG(las);
		bool can = false;
		ll sum = 0;
		REP(i, tmp.size()) {
			sum += min(addRem, las - tmp[i]);
		}
		sum /= rem;
		if (sum >= addRem)can = true;
		if (can)ok = mid;
		else ng = mid;
	}
	print(ok);
}

