  lint ub = n;
  while(ub - lb > 1) {
    lint mid = (ub + lb) / 2;
    // cerr << "mid = " << mid << endl;

    lint limit = a[mid] + m;
    lint cnt = v - p;

    vector<lint> vv;
    for(int i = p - 1; i < n; i++) {
      if(i == mid) continue;
      vv.push_back(a[i]);
    }
    // cerr << "vv: " << endl;
    // for(int i = 0; i < vv.size(); i++) cerr << vv[i] << " ";
    // cerr << endl;

    // m 回やんなきゃ
    sort(ALL(vv));
    vector<int> ex;
    // cerr << "cnt = " << cnt << endl;
    // assert(cnt <= (int)vv.size());
    if(cnt <= 0) {
      // cerr << "mid = " << mid << endl;
      // cerr << "limit = " << limit << endl;
      // cerr << "v[0] = " << v[0] << endl;
      // cerr << "v.back() = " << v.back() << endl;
      // cerr << "boolean : " << (limit >= v.back()) << endl;
      if(limit >= vv[p - 1]) lb = mid;
      else ub = mid;
      continue;
    }

    for(int i = 0; i < cnt; i++) {
      if(vv[i] + m > limit) {
        ex.push_back(vv[i] + m - limit);
      }
    }

    // cerr << "limit = " << limit << endl;
    // cerr << "ex: " << endl;
    // for(int i = 0; i < ex.size(); i++) cerr << ex[i] << " ";
    // cerr << endl;

    bool ok = false;
    lint rest = vv.size() - cnt;
    if(ex.size() <= rest) {
      ok = true;
      reverse(ALL(ex));
      for(int i = 0; i < ex.size(); i++) {
        lint val = vv[cnt + i] + ex[ex.size() - 1 - i];
        if(val > limit) ok = false;
      }
    }


    if(ok) lb = mid;
    else ub = mid;
  }

  while(lb < n - 1) {
    if(a[lb + 1] == a[lb]) lb++;
    else break;
  }

  cout << lb + 1 << endl;


  return 0;
}

