    // cout << a[n - p] << " " << modi << endl;
    if (a[n - p] > modi) {
        return false;
    }
    v -= p + cand;
    if (v <= 0) {
        return true;
    }
    lint limit = 0;
    for (int i = cand + 1; i < n - p + 1; i++) {
        //    cout << i << " " << min(modi - a[i], m) << endl;
        limit += min(modi - a[i], m);
    }
    // cout << "n-p+1:" << n - p + 1 << endl;
    // cout << "limit:" << limit << endl;
    return limit >= v * m;
}

int main() {
