pi vmax(vi v) {
	int n = size(v);
	int MAX = 0;
	int pos = 0;
	rep(i, n) {
		if (MAX < v[i])pos = i;
		MAX = max(MAX, v[i]);
	}
	return { MAX,pos };
}

pi vmin(vi v) {
	int n = size(v);
	int MIN = INF;
	int pos = 0;
	rep(i, n) {
		if (MIN > v[i])pos = i;
		MIN = min(MIN, v[i]);
	}
	return { MIN,pos };
}

int vsum(vi v) {
	int n = size(v);
	int sum = 0;
	rep(i, n) {
		sum += v[i];
	}
	return sum;
}

int gcd(int a, int b) {
	if (b == 0) {
		swap(a, b);
	}
	int r;
	while ((r = a % b) != 0) {
		a = b;
		b = r;
	}
	return b;
}
int lcm(int a, int b) {
	return (a / gcd(a, b) * b);
}

