    int n, m, v, p;
    cin >> n >> m >> v >> p;
    vec a = ivec(n);
    sort(all(a), greater<int>());
    rep (i, p - 1)
        a[i] += m;
    // if v < p
    v -= p;

    vec rui(n);
    rui[0] = a[0];
    For(i, 1, n - 1) rui[i] = rui[i - 1] + a[i];

    int low = 0;
    int high = n;
    int mid = -1;
    while (high - low > 1) {
        mid = (high + low) / 2;
        bool ok = false;

        if (mid <= p - 1) {
            ok = true;
        } else if (a[mid] + m < a[p - 1]) {
            ok = false;
