                ok = true;
            } else {
                int cap = (a[mid] + m) * (mid - 1 - (p - 2)) -
                          (rui[mid - 1] - rui[p - 2]);
                ok = (cap >= rest);
            }
        }

        if (ok)
            low = mid;
        else
            high = mid;
    }
    print(low + 1);

    return 0;
