ll n, m, v, p;

bool can (ll pos, vector <ll> a) {
	ll left = m*(max(0ll, v-(n-pos+1)-p+1));
	int cnt = 0;
	a[pos] += m;
	for (int i=pos-1; i>=p; i--) {
		if (a[i] <= a[pos]) {
			left -= a[pos]-a[i];
			a[i] = a[pos];
		} else {
			cnt ++;
		}
	}
	return (left <= 0 && cnt < p);
}

