int main()
{
	int n, v, p;
	long long m;
	scanf("%d%lld%d%d", &n, &m, &v, &p);
	long long a[100000];
	for (int i = 0; i < n; ++i)
	{
		scanf("%lld", a + i);
	}
	std::sort(a, a + n, std::greater<long long>());
	int l = p - 1;
	int r = n;
	while (r - l > 1)
	{
		int mid = l + (r - l) / 2;
		bool ok = true;
		if (mid <= n - v)
		{
			ok = a[mid] + m >= a[p - 1];
		}
		else
		{
			int vv = v - (n - mid);
			long long target_max = a[mid] + m;
			if (target_max < a[p - 1])
			{
				ok = false;
				goto finalize;
			}
			int largercnt = std::lower_bound(a, a + mid, target_max, std::greater<long long>()) - a;
			if (vv <= largercnt)
			{
				ok = true;
			}
			else
			{
				vv -= largercnt;
				int safecnt = (a + mid) - std::upper_bound(a + largercnt, a + mid, target_max, std::greater<long long>());
				if (vv <= safecnt)
				{
					ok = true;
				}
				else
				{
					vv -= safecnt;
					int pp = p - largercnt;
					int samecnt = std::upper_bound(a + largercnt, a + mid, target_max, std::greater<long long>()) - std::lower_bound(a + largercnt, a + mid, target_max, std::greater<long long>());
					if (samecnt > vv && pp > vv)
					{
						ok = true;
					}
					else
					{
						ok = false;
					}
				}
			}
		}
		finalize:
		if (ok)
		{
			l = mid;
		}
		else
		{
			r = mid;
		}
	}
	printf("%d\n", r);
}

