int main() {
    int N, M, V, P;
    cin>> N >> M >> V >> P;
    vector<int> A(N);
    vector<long> CP(N + 1, 0);
    long sum = M * V;
    REP(i, 0, N){
        cin >> A[i];
        sum += A[i];
    }
    sort(A.rbegin(), A.rend());

    auto judge = [=](int mid){
        if(mid <= P) {
            return true;
        } else if(A[P-1] - A[mid-1] > M){
            return false;
        } else{
            long possibleV = (P-1)*M + (N-mid+1)*M;
            REP(i, P, mid){
                possibleV += A[mid-1] + M - A[P-1];
            }
            if(possibleV >= M*V) return true;
            else return false;
        }
    };

    auto binary_search = [=](int P, int cnt){
        int left = 1; int right = cnt + 1;
        while(right - left > 1){
            int mid = (right + left) /2;
            if(judge(mid)) left = mid;
            else right = mid;
        }
        return left;
    };

    int ans = binary_search(P, N);
    cout << ans << endl;
}

