inline int read(){
	int x=0,f=1;
	char p=getchar();
	while(!isdigit(p)){
		if(p=='-') f=-1;
		p=getchar();
	}
	while(isdigit(p)) x=(x<<3)+(x<<1)+(p^48),p=getchar();
	return x*f;
}

inline bool cmp(int a,int b){
	return a>b;
}

signed main(){
	n=read();m=read();v=read();p=read();
	for(int i=1;i<=n;i++) a[i]=read();
	sort(a+1,a+1+n,cmp);
	int flag=0;
	for(int i=1;i<=n;i++){
		if(a[i]!=a[i-1]) ans++;
		if(ans>p){
			ans=i-1;
			flag=1;
			break;
		}
	}
	if(!flag){
		cout<<n<<endl;
		return 0;
	}
	siz=ans+1;
	for(int i=p;i<siz;i++) sum+=a[i];
//	for(int i=1;i<=n;i++) cout<<a[i]<<" ";
//	cout<<endl<<"nmsl"<<endl;
//	cout<<ans<<endl;
//	cout<<siz<<endl;
//	cout<<sum<<endl;
	for(int i=siz;i<=n;i++){
		if(a[p]>a[i]+m) break;
		if((n-i+p-1)>=v-1){
			ans++;
			sum+=a[i];
			continue;
		}
		int x=a[i]+m;
		int sum1=(x*(i-p))-sum;
		if(sum1>=m*(v-n+i-p)) ans++;
		sum+=a[i];
