long long A[100010];
long long summemo=0;
void judge(int x){
  summemo+=A[x-1];
  if(summemo-A[x]*(x-P+1)<=(N-V)*M&&A[P-1]-A[x]<=M){
    ans++;
    if(x<N-1) judge(x+1);
  }
}

int main(){
  cin >> N >> M >> V >> P;
  ans=P;
  for(int i=0; i<N; i++) cin >> A[i];
  sort(A, A+N, greater<>());
  judge(P);
  cout << ans << endl;

  return 0;
}

