int main()
{
	ll n,m,v,p;
	cin >> n >> m >> v >> p;
	vector<ll> A(n);
	for(ll i = 0;i<n;i++)cin >> A[i];
	sort(A.begin(),A.end(),greater<>());
	ll l = 0,r = n;
	while(1)
	{
		ll mid = (l+r)/2;
		if(mid<=p||mid-n+v-1<0)
		{
			l=mid;
			if(r-l<2)break;
			continue;
		}
		vector<ll> B = A;
		for(ll i = 0;i<v-1;i++)
		{
			B[(mid+i)%n]+=m;
		}
		ll sum = 0;
		for(ll i = 0;i<(n-v+1);i++)
		{
			sum += B[(mid-i-1+n)%n];
		}
		sum += m;
		ll ave = sum/(n-v+1);
		ll sur = sum%(n-v+1);
		for(ll i = 0;i<(n-v+1);i++)
		{
			B[(mid-i-1+n)%n]= ave;
			if(i<sur)B[(mid-i-1+n)%n]++;
		}
		ll po = B[mid];
		sort(B.begin(),B.end(),greater<>());
		if(B[p-1]<=po)
		{
			l = mid;
		}
		else
		{
			r = mid;
		}
		if(r-l<2)break;
	}	
	cout<<r<<endl;
	return 0;
