int main() {
	ini(n, m, v, p);
	VL A = in[n];
	Sort(A);
	dump(A);

	auto check = [&](int pos)->bool {
		VL a = A;
		VL vote(n);
		ll remain = m * v;

		a[pos] += m;
		vote[pos] += m;
		remain -= m;

		rep(i, n)if (i != pos) {
			ll V = min<ll>({ a[pos] - a[i], remain, m });
			a[i] += V;
			vote[i] += V;
			remain -= V;
		}
		rrep(i, n) {
			ll V = min<ll>({ remain,m - vote[i] });
			a[i] += V;
			vote[i] += V;
			remain -= V;
		}

		int cnt = CountIf(a, [&](ll x) {return x > a[pos]; });
		return cnt < p;
	};

	if (check(0)) {
		out.exit(n);
	} else if (!check(n - 1)) {
		out.exit(0);
	}

	int ng = 0, ok = n - 1;
	while (abs(ng - ok) > 1) {
		int mid = Mid(ng, ok);
		(check(mid) ? ok : ng) = mid;
	}
	dump(A, ng, ok);
	out(n - ok);
}

