bool isOK(int mid){//n log 10^9
    if(mid<=p-1)return true;
    if(v==n)return false;
    if(v<=n+p-1-mid)return a[mid]+m>=b[p-1];
    int to=a[mid]+m;
    vector<int>V;
    int sum=0;
    int c=v-(n+p-1-mid);
    for(int i=p;i<=mid-1;i++){
        V.pb(to-b[i]);
        sum+=to-b[i];
        if(to<b[i])return false;
    }
    if(sum<c*m)return false;
    sort(all(V));
    int nokori=sum-(c*m);
    int ng=-1,ok=INF;
    while(ok-ng>1){
        int MID=(ok+ng)/2;
        int cnt=0;
        for(int e:V){
            if(e>MID)cnt+=e-MID;
        }
        if(cnt<=nokori)ok=MID;
        else ng=MID;
    }
    int ma=ok;
    for(int i=0;i<V.size();i++){
        if(V[i]>ma){
            nokori-=V[i]-ma;
            V[i]=ma;
        }
    }
    for(int i=0;i<V.size();i++){
        if(V[i]==ma&&nokori>0){
            V[i]--;
            nokori--;
        }
    }
    sort(all(V),greater<int>());
    int SUM1=0,SUM2=0;
    for(int i=0;i<c;i++)SUM1+=ma-V[i];
    for(int i=c;i<V.size();i++)SUM2+=V[i];
    return SUM1<=SUM2;
}
