using namespace std;

const int nsz = 1e5;
int n, p, ans;
num m, k, a[nsz + 5], b[nsz + 5];

bool inline cmp(int i, int j) {
    return b[i] - a[i] < b[j] - a[j];
}

bool inline chk(num md) {
    cont (i, n) {
        b[i] = a[i];
    }
    num mx = 0, sum = m * k;
    vector<int> rem;
    cont (i, n) {
        if (b[i] <= md) {
            num del = min(sum, m);
            sum -= del;
            b[i] += del;
            mx = max(mx, b[i]);
        }
    }
    cont (i, n) {
        if (a[i] == b[i] && b[i] < mx) {
            num del = min(sum, mx - b[i]);
            sum -= del;
            b[i] += del;
            rem.push_back(i);
        } else if (a[i] == b[i]) {
            num del = min(sum, m);
            sum -= del;
            b[i] += del;
        }
    }
    sort(all(rem), cmp);
    loop (i, rem.size()) {
