bool voted(int x, int N, int M, int V, int P, std::vector<int>& A){
  if(x < P) return true;
  if(A[x] + M < A[P - 1]) return false;

  long long v = (long long)(V - P) * (long long)M;
  v -= (long long)(N - x - 1) * (long long)M;

  for(int i = P; i < x; i++) v -= (long long)std::min(A[x] + M - A[i], M);

  return v <= 0ll;
}

int count(int N, int M, int V, int P, std::vector<int>& A){
  int ok = P - 1;
  int ng = N;
  while(ng - ok > 1){
    int mid = (ok + ng) / 2;
    (voted(mid, N, M, V, P, A) ? ok : ng) = mid;
  }

  return ok + 1;
}

