void solv() {
	ll m, v, p;
	cin >> n >> m >> v >> p;
	ll a[100010];
	for (size_t i = 0; i < n; i++)
	{
		cin >> a[i];
	}
	sort(a, a + n);
	a[n] = INF;
	ll hi = n + 1;
	ll lo = 0;
	for(int c = 0;c < 100;c++)
	{
		ll mid = (hi + lo) / 2;
		ll he = a[mid] + m;
		ll vr = v - (mid + 1); // 自分以下の数字にvを使用

		auto ov = lower_bound(a, a + n, he + 1) - a; 

		int pc = n - ov; // 自分より大きい数字がいくついるか?
		vr -= (n - ov); // 自分より大きい数字にはvoteしてok
		if (vr <= 0 && pc < p) // vが余っていない状態で自分より大きい数字がp-1未満であれば入る
		{
			hi = mid;
			continue;
		}
		else if (vr <= 0 && pc >= p) {
			lo = mid;
			continue;
		}

		// 必要なvote数
		ll su = 0;
		for (ll j = mid + 1; j < ov; j++)
		{
			su += he - a[j];
		}
		bool ok = false;
		ll vt = vr;
		for (ll j = ov - 1; j > mid; j--)
		{
			if (vt * m <= su) { 
				// vote可能数が必要なvote数の総和を下回ったらok
				ok = true;
				break;
			}
			su -= he - a[j];
			vt--; 
			pc++; //順位は下がっていく
		}

		if (ok && pc < p)
			hi = mid;
		else
			lo = mid;
	}

	cout << n - hi << endl;
}


