	auto f = [&](int t) {
		if(a[t] + m < a[n - p]) return false;
		int V = std::max(0, v - (p - 1 + t + 1));
		int rem = V * m;

		for(int i = t + 1; i <= n - p; i++) rem -= std::min(m, (a[t] + m) - a[i]);
