bool C(int x) {
	/*vi aa = a;
	aa[x] += m;
	rep(i, p - 1) {
		aa[n - 1 - i] += m;
	}
	int vv = v - x;
	*/
	int tmp = a[x] + m;
	int pos = 0;
	rep(i, n) {
		if (tmp >= a[i]) {
			pos++;
		}
	}
	if (p + pos < n)return false;
	int vv = v - x - p;//1人が配らなきゃいけない票
	if (vv <= 0)return true;
	int between = n - p - x;//配れる箱の数
	if (between <= 0) {
		return false;
	}

	vi now(between);
	rep(i, between) {
		now[i] = a[x + i + 1];
	}

	int rem = m * vv;
	rep(i, between) {
		int tt = tmp - now[i];
		rem -=  min(m,tt);
		now[i] += min(m,tt);
		if (rem <= 0)break;
	}

	if (rem <= 0)return true;
	else return false;
}

