	A.push_back(1e10);	//最後にダミーを追加

	ll borderScore = A[P-1];	//ボーダーのスコア

	//(スコア，人数)のベクタを作成
	vector <pair<ll, ll>> B;
	ll prevScore = A[0];
	ll prevNum = 1;
	for (int ii = 1; ii < A.size(); ++ii){
		if (A[ii] == prevScore){
			prevNum++;
		} else {
			B.push_back(make_pair(prevScore, prevNum));
			prevScore = A[ii];
			prevNum = 1;
		}
	}

	// for (int ii = 0; ii < B.size(); ++ii){
	// 	printf("score %lld, num %lld\n", B[ii].first, B[ii].second);
	// }

	//トップグループ，ボーダーグループの数を計算
	ll topNum = 0;
	ll borderNum = 0;
	ll outOfBorderIdx = 0;
	for (int ii = 0; ii < B.size(); ++ii){
		if (B[ii].first > borderScore){
			topNum += B[ii].second;
		} else if (B[ii].first == borderScore) {
			borderNum += B[ii].second;
		} else {
			outOfBorderIdx = ii;
			break;
		}
	}

	// printf("T %i, outOfBorderIdx %i\n", T, outOfBorderIdx);
	// printf("borderNum %i, borderScore %i\n", borderNum, borderScore);

	//自分以下のグループに含まれる総数を計算
	vector <ll> lowerNum(B.size());
	ll cnt = 0;
	for (int ii = 0; ii < B.size(); ++ii){
		lowerNum[ii] = N - cnt;
		cnt += B[ii].second;
	}


	ll ans = topNum + borderNum;
	//ボーダーより下の問題が採用されうるかどうか判定
	ll total = 0;
	for (int ii = outOfBorderIdx; ii < B.size(); ++ii){
		ll boxNum = N - (P - 1 + lowerNum[ii]);
		if (ii == outOfBorderIdx){
			ll tmp = topNum + borderNum - (P - 1);
			total += B[ii-1].first * tmp;
		} else {
			total += B[ii-1].first * B[ii-1].second;
		}

		ll cnt = max(0LL, V - (N - boxNum));
		ll tmpTotal = total + cnt * M;

		// printf("total %lld, tmpTotal %lld, boxNum %lld\n", total, tmpTotal, boxNum);

		// cout << tmpTotal << " " << boxNum << endl;

		ll tmpScore = (tmpTotal + boxNum - 1LL) / boxNum;

		ll refScore = max(borderScore, tmpScore);
		ll score = B[ii].first + M;	//ボーダーより下の問題のスコア

		if (score >= refScore){
			// cout << ans << endl;
			// cout << B[ii].second << endl;
			ans = ans + B[ii].second;
		}
	}

	cout << ans << "\n";

	return 0;
}

