bool ch(ll n, ll m, ll v, ll p, const vector<int>& a, int id) {
    ll x = a[id] + m;
    v -= p;
    v = max((ll)0, v);
    vector<ll> b;
    for (int i = p - 1; i < n; ++i) {
        if (i == id)
            continue;
        if (a[i] > x) {
            return 0;
        }
        b.push_back(max(x - a[i], (ll)0));
    }
    if (v == 0)
        return 1;
    ll ad = 0;
    for (int i = 0; i < b.size(); ++i) {
        ad += min(b[i], m);
    }
    if (ad >= v * m)
        return 1;
    return 0;
}

