        if (a[x] + m < a[p - 1]) return false;
        i64 s = a[x] + m;
        i64 u = v - (p - 1) - (n - x);
        if (u <= 0) return true;
        i64 sum = 0;
        for (int i = p - 1; i < x; ++i) {
            sum += min(m, s - a[i]);
        }
        return sum >= u * m;
    });   

    cout << ans << endl;
    return 0;
}

