bool check(vector<int> &a, int pos, ll m, int p, int v) {
    if(a[pos] + m < a[p - 1]) return false;
    ll can = 0, n = a.size();
    for(int i = p - 1; i < pos; i++) {
        can += a[pos] + m - a[i];
    }
    can += (p - 1 + n - pos) * m;
    return can >= m * v;
}

