    if(!check(a, lo, m, p, v)) {
        cout << p << endl;
    }
    else if(check(a, hi, m, p, v)) {
        cout << n << endl;
    }
    else {
        while(hi - lo > 1) {
            int mid = (hi - lo) / 2 + lo;
            if(check(a, mid, m, p, v)) lo = mid;
            else hi = mid;
        }
        cout << lo + 1 << endl;
    }
}

