bool isOK(Int i) {//A[i]が含まれ得るか

	Int temp = 0;
	temp += M * (P - 1);

	if (A[i]+M<A[N-P]) {
		return false;
	}
	temp += M * (i + 1);
	for (Int j = i+1; j <= N-P; j++) {
		temp += A[i] + M - A[j];
	}

	if (temp>=V*M) {
		return true;
	}
	else {
		return false;
	}
}

// 汎用的な二分探索のテンプレ
Int binary_search() {
	Int ng = -1; // 0が条件を満たすこともあるので、初期値は -1
	Int ok = N-P; // 考えられる答えの上限

	/* ok と ng のどちらが大きいかわからないことを考慮 */
	while (abs(ok - ng) > 1) {
		Int mid = (ok + ng) / 2;

		if (isOK(mid)) ok = mid;
		else ng = mid;
	}
	return ok;
}

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);


	cin >> N >> M >> V >> P;
	A.resize(N);

	for (Int i = 0; i < N; i++) {
		cin >> A[i];
	}

	sort(A.begin(), A.end());

	Int res = binary_search();
	cout << N-res << "\n";
}

