bool judge(int c){
    if(c-(P-1) > (N-V)) {
        ll rem = (c-(P-1) - (N-V))*M;
        for(int i = P-1; i < c; i++){
            if(A[c]+M-A[i] < 0) return false;
            rem -= min(M, A[c]+M-A[i]);
        }
        if(rem <= 0) return true;
        else return false;
    }else{
        if(A[P-1] <= A[c]+M) return true;
        else return false;
    }
}

