    ll cost = m*v;
    b[mid] += m;
    ll lim = b[mid];
    cost -= m;
    for(int i = 0; i < p-1; i++){
        b[i] += m;
        cost -= m;
    }

    for(int i = b.size()-1; i > mid; i--){
        b[i] += m;
        cost -= m;
    }
    if(cost<=0){
        return true;
    }
    for(int i = p-1; i < mid; i++){
