void solve(){
  ll n,m,v,p;
  cin>>n>>m>>v>>p;
  vector<ll>a(n);
  rep(i,n)cin>>a[i];
  sort(a.rbegin(),a.rend());
  ll l=0,r=n;
  while(r-l>1){
    ll mid=(l+r)/2;
    ll val=a[mid]+m;
    if(val<a[p]){
      r=mid;
      continue;
    }
    ll rest=m*((n-mid)+(p-1LL));
    ll sum=0;
    for(ll i=p;i<mid;++i){
      sum+=val-a[i];
    }
    if(sum+rest>=v*m)l=mid;
    else r=mid;
  }
  ll ans=l+1;
  chmin(ans,n);
  cout<<ans<<"\n";
}

