template<typename T>
T meguru_search(T ok, T ng, function<bool(T)> check){
    while(max(ok, ng) - min(ok, ng) > T(1)){
        T mid = (ok + ng) / T(2);
        if(check(mid)){
            ok = mid;
        }else{
            ng = mid;
        }
    }
    return ok;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    lint n, m, v, p;
    cin >> n >> m >> v >> p;

    vector<lint> a(n);
    rep(i, n){
        cin >> a[i];
    }
    SORT_INV(a);

    auto check = [&](lint mid){
        lint score = a[mid] + m;
        lint j = meguru_search<lint>(-1LL, n, [&](lint pos){ return a[pos] > score; });
        if(j + 1LL > p){
            return false;
        }
        lint k = meguru_search<lint>(-1LL, n, [&](lint pos){ return a[pos] > a[mid]; });
        lint nokori = v - (j + 1LL) - (n - k - 1LL);
        lint cnt = 0;
        REP(i, j + 1, k + 1){
            if(i < p - 1){
                cnt += m;
            }else{
                cnt += min(score - a[i], m);
            }
        }
        // cout << mid << ' ' << j << ' ' << k << ' ' << nokori << ' ' << cnt << endl;
        return cnt >= nokori * m;
    };

    lint ans = meguru_search<lint>(p - 1LL, n, check) + 1LL;
    cout << ans << endl;

    cout << flush;

    return 0;
}

