  if (a[x]+m < a[p-1]) return false;
  int vv = v-(n-x)-(p-1);
  if (vv <= 0) return true;
  long long c = 1LL*m*vv;
  long long s = 0;
  for (int i = p-1; i < x; ++i) {
    s += a[x]+m-a[i];
  }
  return s >= c;
