							// cerr << mo << " " << x << '\n';
							ans += tmp;
						} else {
							break;
						}
					} else {
						int64_t pl = ne / usum;
						assert(pl >= 0);
						int64_t am = ne % usum;
						assert(am >= 0);
						if(am == 0) {
							if(idx + m >= bor + pl) {
								ans += tmp;
							} else {
