bool isGood(ll n, ll m, ll v, ll p, vector<ll> const & A, ll x) {
    if (x<p) return true;
    ll now = A[x] + m;
    if (A[p - 1] > now) return false;
    ll score = 0;
    score += (p-1) * m;
    score += (n-x) * m;
    for (ll i = p - 1; i < x; ++i) {
        score += min(m, max(0LL, now - A[i]));
    }
    return score >= m * v;
}

