bool isGood(LL N, LL M, LL V, LL P, vector<LL> &A, LL x) {
    if (x < P) return true;
    if (A[x] + M < A[P - 1]) return false;
    LL s = M * V;
    LL now = A[x] + M;
    s -= (P - 1) * M;
    s -= (N - x) * M;
    for (int i = P - 1; i < x; i++) {
        LL d = min(M, now - A[i]);
        if (d < 0)continue;
        s -= d;
    }
    return s <= 0;
}

int main() {

    LL N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<LL> A(N);
    cin >> A;
    RSORT(A);

    LL ok = -1;
    LL ng = N;

    while (abs(ok - ng) > 1) {
        LL mid = (ok + ng) / 2;
        if (isGood(N, M, V, P, A, mid)) ok = mid;
        else ng = mid;
    }

    cout << ok + 1 << endl;

    return 0;
}

