{
	int val = a[x] + m, cnt = 0;
	ll rst = 1LL * (v - 1) * m;
	for(int i = n; i > x; --i)
	{
		if(a[i] > val)
		{
			++ cnt;
			rst -= m;
		}
		else
		{
			if(cnt < p - 1)
			{
				++ cnt;
				rst -= m;
			}
			else
			{
				rst -= (val - a[i]);
			}
		}
	}
	if(cnt >= p)	return 0;
	return rst <= 1LL * m * (x - 1);
}

