int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;

	ll m, v, p;
	cin >> m >> v >> p;

	vector<ll> as(n);
	for (int i = 0; i < n; ++i) cin >> as[i];
	sort(as.begin(), as.end());

	int low = 0;
	int high = n;
	while(low != high) {
		int mid = (low + high + 1) >> 1;
		int i = n-mid;

		// Can problem i get selected?
		// We have to give in total m(v-p) votes to problems i+1 ... n-p,
		// At most m to each of them, and they all have to have at most x
		ll x = as[i] + m;
		ll tar = m * max(0ll, v-(i+1)-(p-1));
		ll can = 0;
		bool fail = false;
		for (int j = i+1; j <= n-p; ++j) {
			if (as[j] > x) fail = true;
			else can += min(m, x - as[j]);
		}
		if (can >= tar && !fail) {
			low = mid;
		} else {
			high = mid - 1;
		}

	}
	cout << low << '\n';
}

