int main(){

    ll N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<ll> v(N);
    for(int i = 0; i < N; i++) cin >> v[i];

    sort(rall(v));
    ll goal = v[P - 1];


    map<ll, ll> m;
    for(int i = 0; i < N; i++) m[v[i]]++;

    vector<ll> vsum(N);
    vsum[0] = v[0];
    for(int i = 1; i < N; i++){
        vsum[i] = vsum[i - 1] + v[i];
    }

    /*
    vector<ll> msum;
    msum.push_back( m[v[0]] );
    for(int i = 0; i < N - 1; i++){
        if(v[i] != v[i+1]){
