        cout << "vsum " << endl;
        for(int i = 0; i < msum.size(); i++){
            cout << msum[i] << endl;
        }

    }
    */

    ll no_relation = 0;
    for(int i = 0; i < N; i++){
        if(v[i] > goal) {
            no_relation = i;
        }
    }

    ll ans = N;
    for(int i = 0; i < N; i++){
        if( v[i] >= goal ) continue;

        if( v[i] + M < goal) ans --;
        else {
            //　あまりの投票数
            ll vote = (V - no_relation - 1);
            if(vote < 0) continue;

            ll vote_sum = vote * M;
            // そこの区間の合計
            ll vsum_tmp = vsum[i] - vsum[no_relation];
            vsum_tmp += vote_sum;
            ll votemax = ( vsum_tmp + (N - no_relation) ) / (N - no_relation - 1);
            if( votemax > v[i] + M ) ans --;
        }
    }

    cout << ans << endl;
    return 0;


}

