long long n,np,nv,nt;
vector<long long> box(1e5);

bool check(long long mid) {
  bool ans_bool=false;
  if(box.at(nt-1)<=box.at(mid)) {
    ans_bool=true;
  }
  else if(box.at(mid)+np >= box.at(nt-1)) {
    if(nv<=nt) {
      ans_bool=true;
    }
    else {
      long long check_sum=0;
      for(long long i=nt-1;i<n;i++) {
        if(i==mid) continue;
        check_sum+=min(np,box.at(mid)+np-box.at(i));
        if(check_sum>=np*(nv-nt)) {
          ans_bool=true;
          break;
        }
      }
    }
  }
  return ans_bool;
}

long long main() {
  cin >> n >> np >> nv >> nt;
  for(long long i=0;i<n;i++) {
    cin >> box.at(i);
  }

  sort(box.rbegin(),box.rend());

  long long mx=n-1;
  long long mn=nt-1;
  long long mid=(mx+mn)/2;
  while(mx-mn>=2) {
    if(check(mid)) {
      mn=mid;
    }
    else {
      mx=mid;
    }
    mid=(mn+mx)/2;
  }
  cout << mn+1 << endl;
}

