#include <bits/stdc++.h>

using ll = long long;
const int N = 100010;

int a[N];
int n, m, v, p;

bool check(int mid){
    std::vector <int> vec;
    int cnt = 0;
    for (int i = 0; i < n; ++ i){
        if (i == mid){
            continue;
        }
        if (a[i] > a[mid] + m){
            ++ cnt;
        }
        else{
            vec.push_back(a[i]);
        }
    }
    ll left = 1ll * m * (v - 1 - cnt);
    int remain = p - 1 - cnt;
    if (remain < 0){
        return false;
    }
    if (left < 0){
        return true;
    }
    for (auto u : vec){
        if (remain > 0){
            -- remain;
            left -= std::min(left, ll(m));
            continue;
        }
        ll diff = a[mid] + m - u;
        ll x = std::min(diff, ll(m));
        x = std::min(x, left);
        left -= x;
    }
    return left == 0;
}

int main(){
    scanf("%d%d%d%d", &n, &m, &v, &p);
    for (int i = 0; i < n; ++ i){
        scanf("%d", &a[i]);
    }
    std::sort(a, a + n, std::greater <int>());
    int left = 0, right = n - 1;
    while (left < right){
        int mid = (left + right + 1) / 2;
        if (check(mid)){
            left = mid;
        }
        else{
            right = mid - 1;
        }
    }
    printf("%d\n", left + 1);
    return 0;
}

