ll n,m,v,p,ans=-1;
vector<ll> a;


bool solve(ll mid){
    vector<ll> b(n);
    rep(i,n) b[i]=a[i];
    ll ad=m*v;
    b[mid]=a[mid]+m;ad-=m;
    for(int i=0;i<n and ad>0;i++){
        if(i<mid){
            b[i]=a[i]+m;
            ad-=m;
        }
        else if(i==mid){
            continue;
        }
        else{
            if(b[mid]>a[i]){
                ll dif=min(m,b[mid]-a[i]);
                b[i]=a[i]+dif;
                ad-=dif;
            }    
        }
    }

    if(ad>0){
        for(int j=0;j<p and ad>0;j++){
            int i=n-j-1;
            if(i==mid) break;
            ll can_up=m-(b[i]-a[i]);
            b[i]+=can_up;
            ad-=can_up;
        }
    }
    ll num=b[mid],cnt=0;
    rep(i,n){
        if(b[i]>num) cnt++;
    }
    if(cnt<p and ad<=0){
        return true;
    }else{
        return false;
    }

}

