const int maxN = 1 << 19;

int T[maxN];
int n, m, v, p;

priority_queue <int> H;

bool check(int i)
{
	long long x = 1ll * m * v;
	int j, y = T[i] + m;

	if (i <= p)
		return true;
	if (y < T[p])
		return false;

	for (j=n; T[j] <= T[i]; j--)	
		x -= m;

	for (j=1; T[j] > y; j++)
		x -= m;

	int r = j;
	while (T[j] > T[i])
	{
		int d = y-T[j++];
		x -= d;
		H.push(m-d);
	}

	while (!H.empty() and x > 0ll)
	{
		x -= H.top();
		H.pop();
		r++;
	}

	while (!H.empty())
		H.pop();
	assert(x <= 0);

	return r <= p;
}

