void solve(long long N, long long M, long long V, long long P, std::vector<long long> A){
    sort(A.begin(), A.end());
     auto check = [&](int i){
        if(N-P < i){
            return true;
        }
        ll m = A[i] + M;
        if(m < A[N-P]){
            return false;
        }
        ll sum = 0;
        for(int j = 0;j < N;j++){
            if(j == i){
                continue;
            }
            if(N - P < j){
                sum += M;
            }else{
                sum += max(min(M, m - A[j]),0LL);
            }
        }
        return sum >= (V-1) * M;
    };
    int ng = 0;
    int ok = N;
    if(check(0)){
        cout<<N<<endl;
        return;
    }
    while(ok - ng > 1){
        int mid = (ok + ng)/2;
        if(check(mid)){
            ok = mid;
        }else{
            ng = mid;
        }
    }
    cout<<N-ok<<endl; 
    return;
}

