    int ans = 0;
    while (l + 1 < r) {
        int mid = (l + r) >> 1;
        if (check(mid)) {
            l = mid;
            ans = mid;
        } else {
            r = mid ;
        }
    }
    printf("%d\n", ans);
    return 0;
}

