bool ok(int x){
	LL cur = 0LL + a[x] + m;

	if(cur < a[p - 1])	return 0;

	int lft = v;
	for(int i=0; i<n; i++){
		if(a[i] <= a[x])	lft--;
	}

	lft = lft - (p - 1);

	if(lft <= 0)	return 1;

	LL sum = 0;
	for(int i=p; i<x; i++){
		sum = sum + cur - a[i];
	}

	return sum >= 1LL * lft * m;
}

