	}
	else{
		if (x>n-(v-p+1)+1){
			ll sum=(s[x-1]-s[p-1])+((v-p+1)-(n-x+1))*m;
			// cout<<sum<<' '<<(sum+(x-1)-p)/((x-1)-p+1)<<' '<<endl;
			// cout<<sum<<' '<<ave<<endl;
			return (sum+(x-1)-p)/((x-1)-p+1)<=b[x]+m;
		}
		else{
			return b[x]+m>=b[p];
		}
	}
}

