	while (l<=r){
		mid=l+r>>1;
		// cout<<mid<<endl;
		if (ck(mid)){
			l=mid+1;
			ans=max(ans,mid);
			// cout<<"1\n";
		}
		else {
			r=mid-1;
			// cout<<"0\n";
		}
	}
	printf("%d\n", ans);

	return 0;
}

