	int R = N - pos;
	if (L + R >= V) return true;

	LL votes = V - (L + R);
	vector<LL> v;
	REP(i, L, pos) {
		v.push_back(A[pos] + M - A[i]);
	}

	LL sum = 0;
	for (LL& a : v) {
		sum += min(M, a);
	}

	return sum >= M * votes;
}

