    int of2=upper_bound(a.begin(),a.end(),v)-a.begin();
    int ar=N-P+1,al=of2,tgt=v+M;
    int alpha=V-of1-of2;
    //cerr<<"\n"<<v<<" "<<of1<<" "<<of2<<" alpha:"<<alpha<<endl;
    if(alpha<=0){
        if(a[N-P]<=tgt){
            return 1;
        }else{
            return 0;
        }
    }
    int nn=ar-al,f=0;
    vector<int> b(nn);
    vector<int> c(nn+N+10,0);
    int under=-1;
    LL sm=0;
    //cerr<<al<<" "<<ar<<" "<<nn<<" "<<endl;
    FOR(i,0,nn){
        if(i!=0)c[i]+=c[i-1];
        b[i]=a[al+i]+c[i];
        if(b[i]+M<=tgt){
            under=i;
            alpha--;
        }else{
            sm+=tgt-b[i];
        }
    }
    if(sm<1LL*alpha*M){
        return 0;
    }

    return 1;
}

