int main(){
  int N; ll M, V, P;
  cin >> N >> M >> V >> P;

  vector <ll> A(N);
  for (int i = 0; i < N; i++) cin >> A[i];
  sort(A.begin(), A.end(), greater<ll>());

  int L = P - 1, R = N - 1;
  while (true){
    int now = (L + R) / 2;

    if (A[now] + M < A[P - 1]){
      R = now;
      if (now == (L + R) / 2) break;
      continue;
    }

    ll rest = M * V;
    rest -= M * (P - 1);
    rest -= M * (N - now);

    ll C = A[now] + M;
    for (int i = P; i < now; i++){
      rest -= C - A[i];
    }

    if (rest <= 0) L = now;
    else R = now;
    if (now == (L + R) / 2) break;
  }

  if (R == N - 1){
    ll rest = M * P;
    ll C = A[N - 1] + M;
    for (int i = P; i < N - 1; i++){
      rest -= C - A[i];
    }
    if (rest <= 0) R++;
  }


  cout << R << endl;

  return 0;
}

