template <typename T> struct BinaryIndexedTree {
    vector<T> node;
    int n;
    BinaryIndexedTree(int n) : n(n) { node.assign(++n, 0); }
    void add(int k, T x) {
        for (++k; k < n; k += k & -k) {
            node[k] += x;
        }
    }
    T sum(int k) {
        T res = 0;
        for (++k; k > 0; k -= k & -k) {
            res += node[k];
        }
        return res;
    }
};
bool check(int t) {
    if (a[t] + m < a[p - 1]) {
        return false;
    }
    int co = v - p, c2 = 0;
    for (int i = p - 1; i < n; i++) {
        if (i == t) {
            continue;
        }
        if (a[i] <= a[t]) {
            co--;
        } else {
            c2++;
        }
    }
    if (co <= 0) {
        return true;
    }
    BinaryIndexedTree<int> bit(n + 1);
    int cnt = 0;
    for (int i = p - 1; i < p - 1 + c2; i++) {
        if (i + co - 1 >= p - 1 + c2) {
            break;
        }
        a[i] += bit.sum(i);
        cnt += a[t] + m - a[i];
        bit.add(i, a[t] + m - a[i]);
        bit.add(i + co, -(a[t] + m - a[i]));
    }
    return cnt >= m;
}
