int main() {
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<ll> a(n);
    for (int i=0; i<n; i++) {
        cin >> a.at(i);
    }
    sort(a.begin(), a.end(), greater<ll>());
    vector<ll> plusM(n);
    for (int i=0; i<n; i++) {
        plusM.at(i) = a.at(i) + m;
    }
    ll cnt = p;
    ll larger_cnt = 0;
    ll larger_sum = 0;
    for (ll i=p; i<n; i++) {
        ll cur = plusM.at(i);
        if (a.at(p-1) > cur) {
            break;
        }
        ll point = m * (v - (p-1) - (n-i));
        ll cur_larger = plusM.rend() - upper_bound(plusM.rbegin()+n-i, plusM.rend()-p+1, cur) - (p-1);
        ll cur_smaller = i - p + 1 - cur_larger;
        for (int j=p-1+larger_cnt; j<p+cur_larger-1; j++) {
            larger_sum += cur - a.at(j);
        }
        larger_cnt = cur_larger;
        if (point <= cur_smaller * m + larger_sum) {
            cnt++;
            larger_sum -= larger_cnt * (cur - plusM.at(i+1));
        } else {
            break;
        }
    }
    cout << cnt << endl;
    return 0;
}

