void solve() {
    int n, m, v, p; cin >> n >> m >> v >> p;
    map<int, int> ma;
    vector<int> A(n); rep (i, n) cin >> A[i], ma[A[i]]++;
    sort(all(A));
    auto B = A;
    vector<int> wa(n + 1);
    rep (i, n) wa[i + 1] = wa[i] + B[i];
    reverse(all(A));
    int kizyun = A[p-1];
    int ans = 0;
    rep (i, n) {
        // cout << ans << endl;
        if (A[i] >= kizyun) ans++;
        else {
            int tmp = A[i] + m;
            // if (n-i-1 <= v-1) ans++;
             {
                int rem = m * (v-(upper_bound(all(B), A[i]) - B.begin()));
                // cout << i << " " << pos << endl;
                if (tmp < kizyun) continue;
                int naga = (n-(lower_bound(all(B), tmp)-B.begin()));
                chmin(naga, p-1);
                if (naga*m >= rem) ans++;
                else {
                    rem -= (naga)*m;
                    int pos = upper_bound(all(B), A[i])-B.begin();
                    int sum = (p-(naga+1))*m + tmp * (n-p-pos+1) - wa[n-p+1] + wa[pos];
                    // cout << A[i] << " " << naga << " " << sum << rem << endl;
                    // cout << A[i] << " " << sum << " " << rem << endl;
                    if (sum >= rem) ans++;
                }
            }
        }
    }
    cout << ans << endl;
}

