int ni;

struct SegmentTree{
    SegmentTree(int n_){
        ni=1;
        while(ni<n_) ni*= 2;
        for(int i=0;i<2*ni-1;i++){
            dat[i]=0;
        }
    }
    int query(int k){
        k += ni-1;
        int count=dat[k];
        while(k>0){
            k=(k-1)/2;
            count+=dat[k];
        }
        return count;
    }
    void update(int a,int b,int k,int p,int l,int r){
        if(r<=a || b<=l) return;
        if(a<=l && r<=b){
            dat[k]+=p;
        }
        else{
            update(a,b,k*2+1,p,l,(l+r)/2);
            update(a,b,k*2+2,p,(l+r)/2,r);
        }
    }
};



