map<int,int> ls;
bool check(int p){
	if (v>pre[ls[a[p]]]){
		int num=pre[ls[a[p]]];
		int tv=v-num;
		int pp=upper_bound(a,a+n,a[p]+m)-a;
		for (int i=pp,j=n-pp;i>=pre[ls[a[p]]] && j<P;i--,j++){
			if (1ll*max(tv-j,0)*m+qzh[i-1]-qzh[num-1]<=1ll*(a[p]+m)*(i-num)) return true;
		}
		return false;
	}
	else{
		int t=upper_bound(a,a+n,a[p]+m)-a;
		if (n-t<=P) return true;
		else return false;
	}
}
