class BVotingJudges {
public:
	void solve(std::istream& in, std::ostream& out) {
        int n, v, p;
        ll m;
        in >> n >> m >> v >> p;
        vector<ll> a(n);
        rep(i, n){
            in >> a[i];
        }

        sort(all(a));

        int left = -1, right = n;
        while(left + 1 < right){
            int mid = left + (right - left) / 2;
            if(v - 1 - mid < p && a[mid] + m >= a[n - p]) {
                right = mid;
            }else{
                int over = v - 1 - mid - (p-1);
                ll cnt = 0;
                reps(j, mid+1, n-p){
                    cnt += a[mid] + m - a[j];
                }
                if(over * m <= cnt) right = mid;
                else left = mid;
            }
        }

        out << n - right << endl;
	}
};


