LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

const size_t N = 1e5 + 5;

int n, p;
LL m, v, a[N];

bool check(int id) {
    --id;
    LL tot = m * (v - 1);
    int cur = 1;
    for (int i = 0; i < n; ++i) {
        if (i == id) continue;
        if (a[i] > a[id] + m) {
            ++cur;
            tot -= m;
        } else if (tot > 0) {
            tot -= min(m, a[id] + m - a[i]);
        }
    }
    for (int i = 0; i < n && tot > 0; ++i) {
        if (i == id || a[i] > a[id] + m) continue;
        assert(a[i] > a[id]);
        ++cur;
        tot -= a[i] - a[id];
    }
    assert(tot <= 0);
    return cur <= p;
}

