    // }
    // cout << endl;

    LazySegmentTree lst(A);
    ll ans = num;
    for (int i=num; i<N; ++i) {

        bool debug = false;
        // 右側を更新する
        lst.add(i, min(N, i+V), M);

        // 残りこれだけ
        ll left = V - (N-i);
        if (left < P) {
            lst.add(0, left, M);
