            // cout << A[i] << ", " << A[P-1] + tmp << ", " << left2 << endl;

            ll tmp1 = lst.getsum(i, i+1);
            if (tmp + A[P-1] <= tmp1) {
                ans++;
                debug = true;
            }

        }

        // 戻す
        lst.add(i, min(N, i+V), -M);

        // 左側の範囲は
        if (left < P) {
            lst.add(0, left, -M);
        }
        else {
            lst.add(0, P, -M);
        }

