void solve(long long N, long long M, long long V, long long P, vector<long long> A){
	SORT(A);
	ll sum = 0, res = P;
	for (int i = N-P-1; i >= 0; i--) {
		ll nmp = A[N-P]+((M*max(0LL, V-(i+P))-sum)+(N-P-i)-1)/(N-P-i);
