bool isGood(LL N, LL M, LL V, LL P, vector<LL> &A, LL x) {
    if (x < P) return true;
    LL now = A[x] + M;
    if (A[P - 1] > now) return false;
    LL score = 0;
    score += (P - 1) * M;
    score += (N - x) * M;
    for (LL i = P - 1; i < x - 1; i++) {
        score += min(M, max(0LL, now - A[i]));
    }
    return score >= M * V;
}

int main() {

    LL N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<LL> A(N);
    cin >> A;
    RSORT(A);

    LL ok = -1;
    LL ng = N;

    while (abs(ok - ng) > 1) {
        LL mid = (ok + ng) / 2;
        if (isGood(N, M, V, P, A, mid)) ok = mid;
        else ng = mid;
    }

    cout << ok + 1 << endl;

    return 0;
}

