	for (auto&& e : s)
		std::cin >> e;

	std::sort(s.begin(), s.end());

	std::vector<i64> sum(n);
	sum[0] = s[0];
	for (int i = 1; i < n; ++i)
		sum[i] = sum[i - 1] + s[i];

	auto getSum = [&sum](int l, int r) -> i64 {
		if (l > r)
			return 0;

		return sum[r] - sum[l - 1];
	};

	auto check = [&](int x) {
		if (x == n - 1 || n - x <= p)
			return true;

		const i64 g = s.end() - std::upper_bound(s.begin() + x, s.end(), s[x] + m);
		if (g >= p)
			return false;

		i64 a = v - (p - 1) - (x + 1);
		if (a <= 0)
			return true;

		i64 w = n - (x + 1) - (p - 1);
		return a * m <= (s[x] + m) * w - getSum(x + 1, x + w);
	};

	int l = -1, r = n;
	while (std::abs(r - l) > 1) {
		int mid = (l + r) / 2;

		if (check(mid))
			r = mid;
		else
			l = mid;
	}

	std::cout << n - r << std::endl;
}

