class segtree {
    int n = 1; VL dat;
#define def 0
public:
    segtree(int _n) {
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
    }
    segtree(VL a) {
        int _n = a.size();
        while (n < _n)n *= 2;
        dat.resize(2 * n, def);
        FOR(i, 0, _n)dat[i + n] = a[i];
        rFOR(i, 1, n)dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
    }

    ll fun(ll x, ll y) { return x + y; }

    void update(int i, ll a) {
        i += n;
        dat[i] = a;
        while (i > 1) {
            i /= 2;
            dat[i] = fun(dat[2 * i], dat[2 * i + 1]);
        }
    }

    ll value(int l, int r) {
        l += n, r += n;

        ll ret = def;
        for (; l < r; l /= 2, r /= 2) {
            if (l & 1) {
                ret = fun(ret, dat[l]);
                l++;
            }
            if (r & 1) {
                --r;
                ret = fun(ret, dat[r]);
            }
        }

        return ret;
    }

    ll operator[](int k) { return dat[k + n]; }
};


