  }

  sort(A.begin(), A.end(), greater<ll>() );

  ll l = P-1;	// 大きい順にP個目までは、無条件でOK
  ll r = N;
  ll mid;
  while( l+1 < r ) {
    mid = (l+r)/2;
    if ( judge(mid) ) {
//      cout << mid << " OK" << endl;
      l = mid;
    } else {
//      cout << mid << " NG" << endl;
      r = mid;
    }
  }
  cout << (l+1) << endl;
}

