// range = [l, r), return last value causing "t" in evalfunc that returns l->[t,...,t,f,...,f)->r
// NOTE: if [f,...,f) then return l - 1, if [l, r) = empty set then invalid use
template<class val_t, class bsargv_t>
val_t lower_bsearch(val_t l, val_t r, const bsargv_t &v, bool(*evalfunc)(val_t, const bsargv_t&)) {
	if (r - l == 1) {
		if (evalfunc(l, v)) return l;
		else return l - 1;
	}
	val_t m = (l + r) / 2;
	if (evalfunc(m, v)) return lower_bsearch<val_t, bsargv_t>(m, r, v, evalfunc);
	else return lower_bsearch<val_t, bsargv_t>(l, m, v, evalfunc);
}

struct bsargv_t {
	int n;
	ll m;
	int v;
	int p;
	vll a;
};

bool evalfunc(int val, const bsargv_t &v) {
	if (val < v.p) return true;
	ll t = v.a[val] + v.m;
	if (t < v.a[v.p - 1]) return false;
	ll s = v.v - (v.p + v.n - val - 1);
	if (s <= 0) return true;
	else {
		int l = v.p - 1;
		int r = val;
		vll xo(v.n);
		ll cur = 0;
		ll sum = 0;
		for (int i = l; i + s <= r; ++i) {
			ll u = v.a[i] + cur;
			sum += t - u;
			cur += t - u;
			xo[i + s - 1] += t - u;
			cur -= xo[i];
		}
		if (sum >= v.m) return true;
		else return false;
	}
}

int main() {
	quickio();
	bsargv_t v;
	cin >> v.n >> v.m >> v.v >> v.p;
	v.a = vll(v.n);
	Loop(i, v.n) cin >> v.a[i];
	sort(v.a.begin(), v.a.end(), greater<ll>());
	int ans = lower_bsearch(0, v.n, v, evalfunc);
	cout << ans + 1 << endl;
}

