int gao(int x) {
    while(a[x+1]==a[x]) x++;
    int r=lower_bound(a+1,a+n+2,a[x]+m+1)-a;
    r=n-r+1;int g=v-r-(x-1)-1;
    if(g<=0&&r<=p-1) return 1;
    g*=m;f[x]=0;
    for(int i=x+1;i+r<=n;i++) {
        f[i]=a[x]+m-a[i];
        f[i]+=f[i-1];
    }
    int ans=n-x;
    for(int i=n-r;i>x;i--)
        if((n-r-i)*m+f[i]>=g) ans=min(ans,n-i);
    return ans<=p-1;
}

