bool judge(const V<ll> &alist, ll n, ll m, ll v, ll p, ll idx, ll subs)
{
    if (alist[p-1] - alist[idx] > m) return false;
    v = max(0LL, v - (p-1LL) - (n-idx));
    ll upper = m+alist[idx]-alist[p-1LL];
    upper *= idx-(p-1LL);
    ll total = upper + subs;
    return total >= v * m;
}

