  int ok = -1, ng = n;

  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;
    if (check(a, mid, n, m, v, p)) {
      ok = mid;
    } else {
      ng = mid;
    }
  }

  cout << ok + 1 << endl;
