int cutoff;
vector<int> A;

bool solve(int i) {
	int count = v*m;
	if (A[i] + m < cutoff) return false;
	count -= m*i;
	for (int j=i+1; j<=n-p; j++) {
		int val = max(A[i]+m-A[j], 0);
		if (val == 0) {
			return (count <=0);
		}
		count -= min(val , m);
	}
	return (count <=0);
}

