    vector<ll> c = b;
    c[tm] += m;
    ll sc = c[tm], tc = m * v; 
    for(int i = 0; i < c.size(); ++i){
        if(i == tm) continue;
        if(c[i] > sc) continue;
        ll dec = min(sc - c[i], m);
        tc  -= dec;
        c[i] = sc;
    }
    auto it = max_element(c.begin(), c.end());
    return (*it == sc && tc <= 0);
}

