ll two( vector<ll> &v, ll key){

    ll left = 0;
    ll right = v.size() - 1;

    while (right - left != 1)
    {
        ll mid = (left + right) / 2;
        if( v[mid] > key ){
            left = mid;
        }
        else{
            right = mid;
        }
    }

    return left;

}

int main(){

    ll N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<ll> v(N);
    for(int i = 0; i < N; i++) cin >> v[i];

    sort(rall(v));
    ll goal = v[P - 1];
    ll gf = -1;
    ll ge = -1;
    for(int i = 0; i < N; i++){
        if(v[i] == goal){
            if(gf == -1) gf = i;
            ge = i;
        }
    }


    vector<ll> vsum(N);
    vsum[0] = v[0];
    for(int i = 1; i < N; i++){
        vsum[i] = vsum[i - 1] + v[i];
    }

    ll ans = N;
    for(int i = 0; i < N; i++){
        if( v[i] >= goal ) continue;

        if( v[i] + M < goal) ans --;
        else {

            // 関係ある投票数
            // 関係ある区間
            ll key = two(v, v[i]);
            ll relation = key - gf + 1;
            ll no_relation = N - relation;


            // 関係ある区間にしなければならない投票数
            ll vote = V - no_relation;
            if(vote < 0) continue;

            ll vote_sum = vote * M;
            // そこの区間の合計

            // 関係ある区間の合計
            ll vsum_tmp = vsum[ key  ] - vsum[gf - 1];
            if(DEBUG){
                cout << endl;
                cout << "i is " << i << endl;
                cout << "vote is " << vote << endl;
                cout << "relation " << key << " " << gf << endl;
                cout << "vsum_tmp " << vsum_tmp << endl;
            }

            vsum_tmp += vote_sum;
            ll votemax = ( vsum_tmp + (relation - 1) ) / (relation);
            if( votemax > v[i] + M ) ans --;
        }
    }

    cout << ans << endl;
    return 0;


}

