int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  i64 N, M, v, P;
  cin >> N >> M >> v >> P;
  V<i64> A(N);
  REP(i, N) cin >> A[i];
  sort(A.rbegin(), A.rend());
  i64 pth = A[P - 1];

  auto check = [&](int x) -> bool {
    --x;
    if (x < P) return true;
    if (x > N - 1) return false;
    i64 cnt1 = (P - 1) + (N - x);
    i64 h = A[x] + M;
    if (h < pth) return false;
    if (cnt1 >= v) return true;
    i64 width = v - cnt1;
    i64 rem = M;
    V<i64> delta(N + 1);
    for (int i = P - 1; i + width <= x; ++i) {
      delta[i] += i > 0 ? delta[i - 1] : 0;
      i64 y = A[i] + delta[i];
      if (y > h) continue;
      rem -= h - y;
      if (rem <= 0) return true;
      delta[i] += h - y;
      delta[i + width] -= h - y;
    }
    return false;
  };

  int ok = P, ng = N + 1;
  while (ng - ok > 1) {
    int mid = (ok + ng) / 2;
    if (check(mid)) {
      ok = mid;
