ll N,M,V,P;
VL A;

bool solve(ll mid){
  VL Z(N);
  rep(i,N) Z[i]=A[i]; 
  rep(i,min(V,mid+1)) Z[mid-i]+=M;
  ll sum=M*(V-min(V,mid+1));
  ll Y=Z[mid];
  if(sum>0) rep(i,N-mid-1){
    if(Y>Z[mid+1+i]){
      sum-=Y-Z[mid+1+i];
      Z[mid+1+i]=Y;
    }
    if(sum<=0) break;
  }
  if(sum>0) rep(i,N-mid-1){
    if(Z[N-1-i]-A[N-1-i]<M){
      ll tmp=sum;
      sum-=(M-(Z[N-1-i]-A[N-1-i]));
      Z[N-1-i]+=min(tmp,(M-(Z[N-1-i]-A[N-1-i])));
      if(sum<=0) break;
    }
  }
  sort(all(Z));
  if(Z.end()-ub(all(Z),Y)+1<=P) return true;
  return false;
}

