const int N = 1e5 + 5;

int n, m, v, p;
int d[N];

bool cmp(int a, int b) {
    return a > b;
}

bool check(int mid) {
    if (mid <= p) return 1;
    if (d[mid] + m < d[p]) return 0;
    if (v < p && d[mid] + m >= d[p]) return 1;
    LL ans = 0;
    for (int i = 1; i <= p - 1; ++i) {
        ans += m;
    }
    for (int i = n, j = v - p; i > mid && j; i--, j--) {
        ans += m;
    }
    ans += m;
    LL ned = m * v - ans;
    if (ned < 0) return 1;
    for (int i = p; i < mid; ++i) {
        int x = min(m, d[mid] + m - d[i]);
        if (x > ned) x = ned;
        ned -= x;
    }
    return ned == 0;
}

