void solve() {
  int n, m, v, p; cin >> n >> m >> v >> p;
  vi arr(n);
  rep(i,n) cin >> arr[i];

  sort(RALL(arr));

  int target = arr[p-1];

  reverse(ALL(arr));

  auto low = lower_bound(ALL(arr), target);
  auto up = upper_bound(ALL(arr), target);
  int free = arr.end() - up;
  int cnt = up - low;
  ll sum = 0;

  while (low != arr.begin() && target - *(low-1) <= m) {
    up = low;
    low = lower_bound(ALL(arr), *(low-1));
    ll ncnt = up - low;

    ll lack = v - ((up - arr.begin()) + free);
    if (lack > 0) {
      int ntarget = *low + m;
      ll nsum = sum + (ntarget - target) * cnt;
      if (lack * m > nsum) break;
    }

    cnt += ncnt;
    sum += (target - *low) * ncnt;
  }

  cout << free + cnt << endl;
}


