bool check(const vector<int>& a, int m, int v, int p, int idx) {
    if (a.size() - idx <= p)
        return true;

    int val = a[idx] + m;
    if (val < a[a.size() - p])
        return false;

    int need = max(0, v - p);
    vector<int> f;
    for (int i = 0; i <= a.size() - p; ++i)
        if (i != idx)
            f.push_back(val - a[i]);
    reverse(f.begin(), f.end());

    long long sum = 0;
    for (int i = 0; i < f.size(); ++i) {
        int t = i - (f.size() - need);
        if (t > 0) {
            f[i] = min<long long>(f[i], sum / t);
        }
        sum += f[i];
    }

    return sum >= need *1LL* m;
}

