	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	sort(a, a + n);
	prea[0] = a[0];
	for (int i = 1; i < n; i++)
		prea[i] = prea[i - 1] + a[i];
	int j = 0;
	int ans = 0;
	for (int i = 0; i < n; i++) {
		int fb = min(n - i - 1, p - 1);
		int ff = i;
		while (a[j] <= a[i] + m) {
			j++;
		}
		if (n - j >= p)
			continue;
		if (fb + ff >= v - 1)
			ans++;
		else {
			ll req = v-1-(ff + fb);
			req *= m;
			ll avail = j - i - 1;
			avail *= a[i] + m;
			avail = avail - asum(i + 1, j - 1);
			if (avail >= req)
				ans++;
		}
	}
	cout << ans << "\n";
	//system("pause");
	return 0;
}

