    V<i64> delta(N + 1);
    for (int i = P - 1; i + width <= x; ++i) {
      delta[i] += i > 0 ? delta[i - 1] : 0;
      i64 y = A[i] + delta[i];
      if (y > h) continue;
      rem -= h - y;
      if (rem <= 0) return true;
      delta[i] += h - y;
      delta[i + width] -= h - y;
    }
    return false;
  };

  int ok = P, ng = N + 1;
  while (ng - ok > 1) {
    int mid = (ok + ng) / 2;
    if (check(mid)) {
      ok = mid;
    } else {
      ng = mid;
    }
  }
  cout << ok << endl;
}

