void solve()
{
    i64 n, m, v, p;
    cin >> n >> m >> v >> p;
    akari<i64> as(n), acc(n + 1);
    for (int i = 0; i < n; i++)
    {
        cin >> as[i];
        acc[i + 1] = acc[i] + as[i];
    }
    sort(as.begin(), as.end());
    for (int i = 0; i < n; i++)
    {
        acc[i + 1] = acc[i] + as[i];
    }
    int ng = -1, ok = n;
    while (ok > ng + 1)
    {
        int i = (ok + ng) / 2;
        i64 b = as[i] + m;
        int j = distance(as.begin(), upper_bound(as.begin(), as.end(), b));
