int n, m, v, p;
vector<int> a;

bool judge(int i) {
	if (a[p - 1] > a[i] + m) return false;
	int _v = v;
	_v -= p - 1 + n - i;
	if (_v <= 0) return true;
	int b = a[i] + m;
	vector<int> cnt;
	for (int j = p - 1; j < i; ++j)
			cnt.push_back(b - a[j]);
	if (_v == 1) {
		ll sum = accumulate(cnt.begin(), cnt.end(), 0LL);
		return sum >= m;
	}
	int sz = cnt.size();
	ll tmp = 0;
	for (int j = 0; j <= sz - _v; ++j) tmp += cnt[j];
	tmp += min(tmp * (_v - 1LL), accumulate(cnt.begin() + sz - _v + 1, cnt.end(), 0LL));
	return (tmp / _v) >= m;
}

signed main() {
	cin >> n >> m >> v >> p;
	a.resize(n);
	for (int i = 0; i < n; ++i)
		cin >> a[i];
	sort(a.begin(), a.end());
	reverse(a.begin(), a.end());
	// にぶたん
	int ok = p - 1, ng = n;
	while (ok + 1 < n && a[ok + 1] == a[p - 1])
		++ok;
	while (ng - ok > 1) {
		int mid = (ok + ng) / 2;
		if (judge(mid)) ok = mid;
		else ng = mid;
	}
	cout << (ok + 1) << endl;
	return 0;
}

