	for(uint i=P; i<N; i++) {
	    if(A[i] == A[P-1]) {
	        ans++;
	    } else {
	        ull oth = sum - A[i];
	        if(A[i] + V > (oth + MPV) / rst) {
	            ans++;
	        }
	    }
	}

	cout << ans;
}

