int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout<<fixed<<setprecision(10);

	int N=in(),M=in(),V=in(),P=in();
	auto A=vecin<ll>(N);
	sort(ALL(A),greater<ll>());
	vector<ll> B,C;
	copy(A.begin(),A.begin()+P,back_inserter(B));
	copy(A.begin()+P,A.end(),back_inserter(C));

	if(V+P<=N){
		int Q=B.back();
		int sum=0;
		for(auto& x:C){
			if(x+M>=Q) sum++;
		}
		out(B.size()+sum);
	}
	else{
		int L=N-V;
		int R=B.size()-L;
		using PairLB = pair<ll,bool>;
		auto comp1 = [](PairLB& l,PairLB& r){return l.first>r.first;};
		priority_queue<PairLB,vector<PairLB>,decltype(comp1)> BQ(comp1);
		for(int i=R,ei=B.size();i<ei;i++){
			BQ.emplace(B[i],false);
		}
		auto comp2 = [](PairLB& l,PairLB& r){return l.first<r.first;};
		priority_queue<PairLB,vector<PairLB>,decltype(comp2)> CQ(comp2);
		for(auto& x:C){
			x += M;
			CQ.emplace(x,false);
		}
		while(!CQ.empty()){
			auto VB=BQ.top();
			auto VC=CQ.top();
			if(VC>VB){
				ll NVC = (VB.first+VC.first)/2LL;
				CQ.pop();CQ.emplace(NVC,true);
				BQ.pop();BQ.emplace(VB.first+VC.first-NVC,true);
			}
			else break;
		}
		vector<PairLB> D;
		while(!BQ.empty()){
			D.push_back(BQ.top());
			BQ.pop();
		}
		while(!CQ.empty()){
			D.push_back(CQ.top());
			CQ.pop();
		}
		sort(ALL(D),[](PairLB& l,PairLB& r){return l.first>r.first;});
		ll ans = R;
		ll F=D[L-1].first;
		for(int i=0,ei=D.size();i<ei;i++){
			if(D[i].first>=F || D[i].second) ans++;
		}
		out(ans);
	}

	return 0;
}

