using namespace std;

int N, M, V, P; 
vector<int> A;

bool f(int x){
  // M人がV問の点数を1上げる
  // 上位P-1個と自分に点数を上げる
  // 残りは小さいところから上げていく
  if(N-P <= x) return true;

  if(A[x]+M < A[N-P]) return false;
  // 残りM*Vまで上げなければいけない
  // 1個につき上げれる点数はM
  // A[x]+Mになるまで上げれば良い
  int cnt = 0;
  REP(i, N-P+1){
    if(i == x) continue;
    cnt += min(M, A[x]+M-A[i]);
  }
  if(cnt >= M*(V-P)) return true;
  return false;
}

