  A.resize(N);
  REP(i, N) cin >> A[i];

  sort(ALL(A));

  int ok = N-1;
  int ng = -1;
  while(ok-ng > 1){
    int mid = (ok+ng)/2;
    if(f(mid)) ok = mid;
    else ng = mid;
  }

  cout << A.end()-lower_bound(ALL(A), A[ok]) << endl;

  return 0;
}

