				count++;
			}
			continue;
		}

		ll sum = S[N-P]-S[i] - A[i]*(N-P-i);
		if(sum <= (N-V) * M && A[N-P] <= A[i] + M){
			count++;
		}
	}
	cout << count << endl;

	return 0;
}

