	sort(begin(A), end(A));
	int ans_l = -1, ans_r = N-P;
	while(ans_r-ans_l > 1) {
		int K = (ans_l+ans_r)/2;
		if(A[K]+M < A[N-P]) {
			ans_l = K;
			continue;
		}
		if(P-1+K+1 >= V) {
			ans_r = K;
			continue;
		}
		int v = V-P-K;
		vector<int> st_cnt(N-P-K, 0);
		bool ok = true;
		for(int i = N-P, add = 0, m = M; i > K; i--) {
			if(i-v < K) {
				ok = false;
				break;
			}
			add -= st_cnt[i-K-1];
			int cnt = A[K]+M-A[i]-add;
			if(cnt < 0) return 1;
			if(m <= cnt) break;
			m -= cnt;
			add += cnt;
			if(i-v > K) st_cnt[i-v-K-1] += cnt;
		}
		if(ok) ans_r = K;
		else ans_l = K;
	}
	cout << N-ans_r << "\n";
	return 0;
}

