int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    rep(i, 0, N) cin >> A[i];
    sort(all(A));
    reverse(all(A));
    vector<ll> first_prob;
    set<ll> is_exists;
    int cnt = 0;
    int last = -1;
    int idx = -1;
    ll ans = 0;
    rep(i, 0, N) {
        if (cnt == P) {
            idx = i;
            break;
        }
        if (!is_exists.count(A[i])) {
            ++cnt;
            first_prob.push_back(A[i]);
            ++ans;
        }
        last = A[i];
    }
    int tmp = idx;
    rep(i, tmp, N) {
        if (A[i] != last) break;
        ++idx;
        ++ans;
    }
    reverse(all(first_prob));
    set<ll> second_prob;
    if (idx < V - 1) {
        rrep(i, idx, N - V) {
            second_prob.insert(A[i]);
        }
    }
    rep(i, idx, N) {
        ll prev_cnt = (ll)second_prob.size();
        if (!second_prob.count(A[i])) {
            ++prev_cnt;
        }
        auto itr = upper_bound(all(first_prob), A[i] + M);
        ll first_cnt = (ll)(first_prob.end() - itr);  // 自分より大きいものの個数
        if (prev_cnt + first_cnt <= P) {
            ++ans;
        }
        if (i < V) {
            second_prob.insert(A[i]);
        }
    }
    cout << ans << endl;
    return 0;
}

