int n , m , v , p;
int a[N];

bool check(int x){
	if(x >= v)return true;
	int vv = v - x;

	long long mx = a[x] + m;
	int place = 1;

	for(int j=x+1;j<=n;j++){
		if(1ll * a[j] > mx){
			++place;
			vv--;
		}
	}

	if(vv <= 0)return place <= p;

	long long s = vv * 1ll * m;

	vector <int> mas;
	for(int j=x+1;j<=n;j++){
		if(1ll * a[j] <= mx){
			long long delta = min(s , mx - a[j]);
			s -= delta;
			mas.push_back(m - delta);
		}
	}

	sort(mas.begin() , mas.end());
	reverse(mas.begin() , mas.end());

	for(int i=0;i<(int)mas.size();i++){
		if(s == 0)break;

		++place;
		s -= min(s , 1ll * mas[i]);
	}

	return place <= p;
}

