int N, M, V, P, ans = 0;
int A[100000];
ll S[100000];

int findIndex(int current, int val)
{
	int ok = current;
	int ng = -1;

	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;

		if (val - A[mid] > M) ok = mid;
		else ng = mid;
	}

	return ok;
}

int main()
{
	cin >> N >> M >> V >> P;
	rep(i, N) cin >> A[i];

	sort(A, A + N, greater<int>());
	rep(i, N) {
		if (i == 0) S[i] = A[i];
		else S[i] = S[i - 1] + A[i];
	}

	if (A[P - 1] == A[N - 1]) {
		cout << N << endl;
		return 0;
	}

	ans = P;
	int index = P;
	int Fmin = A[P - 1];
	while (A[index] == Fmin) {
		ans++;
		index++;
	}

	repc(i, index, N - 1) {
		ll buff, choice, last, sup;
		int ThisMax = A[i] + M;
		int rem = V - (N - i);

		if (A[P - 1] > ThisMax) break;
		else rem -= P - 1;

		if (rem <= 0) {
			ans++;
			continue;
		}

		buff = (ll)ThisMax * (ll)(i - 1 - (P - 1) + 1) - (S[i - 1] - S[P - 2]);
		choice = (ll)M * (ll)rem;
		last = buff - choice;
		if (last < 0) break;

		int j = max(P - 1, findIndex(i, ThisMax));
		sup = (ll)ThisMax * (ll)(i - j) - (S[i - 1] - S[j - 1]);

		if (sup <= last) ans++;
		else break;
	}

	cout << ans << endl;

	return 0;
}

