// i番目の要素を採用できるか否か
bool f(vector<ll> a, ll V, ll i) {
  if (i < P)
    return true;

  // printf("before a[%lld]=%lld: ", i, a[i]);
  // for (auto e : a) {
  //   cout << e << " ";
  // }
  // cout << endl;


  // 自分自身
