	vector<int64_t> as(n);
	for (auto& a : as) {
		cin >> a;
	}
	sort(as.begin(), as.end(), greater<int64_t>());

	int low  = p - 1;
	int high = n - 1;

	while (low != high) {
		int mid = (high + low) / 2;
		if (mid == low) mid++;
		bool c = is_ok(as, n, m, v, p, mid);
		if (c) {
			low = mid;
		}
		else {
			if (high == mid) high--;
			else high = mid;
		}
	}

	cout << (low + 1) << endl;

	return 0;
}

