bool calc(ll n, ll m, ll v, ll p, ll *s, int index) { //条件判定
	ll i = upper_bound(s, s+n, s[index]) - s - 1;
	ll a = s[i] + m, now = 0;
	ll k = upper_bound(s, s+n, a) - s - 1;
	if (k < n - p) return false;
	if (i >= n - p) return true;
	rep(j, n) {
		if (j >= n - p + 1) now += m;
		else now += min(a - s[j], m);
	}
	//cout << i << " " << now << endl;
	if (now >= m * v)return true;
	return false;
}

bool calc(ll n, ll m, ll v, ll p, ll *a, ll mid, ll nextMax){
    ll fm = a[mid] + m;
    ll allselect = m * (v-p+1LL);
    // cout << allselect << ", " << mid << endl;
    // cout << fm << endl;
    //if(fm < nextMax)return false;

	ll i = upper_bound(a, a+n, a[mid]) - a - 1;
	ll k = upper_bound(a, a+n, fm) - a - 1;

	if (k < n - p) return false;
	if (i >= n - p) return true;
    rep(i, n-(p-1LL)){
        //if(fm-a[i] <= 0LL)continue;
        allselect -= (min(fm-a[i], m));
    }

    if(allselect <= 0LL)return true;
    return false;
}

