	b[j] += m; t = b[j];
	for(i=0; i<n; ++i){
		if(b[i] > a[j] || (!cnt)){
			continue;
		}
		b[i] += m;
		--cnt;
	}
	lft = m*cnt;
	for(i=0; i<n; ++i){
		if(!lft){
			break;
		}
		tmp = min({m+a[i]-b[i],t-b[i],lft});
		b[i] += tmp;
		lft -= tmp;
	}
	for(i=n-1; i>=0; --i){
		if(!lft){
			break;
		}
		tmp = min(m+a[i]-b[i],lft);
		b[i] += tmp;
		lft -= tmp;
	}
	if(lft){
		return false;
	}
	sort(b,b+n,greater<ll>());
	return (b[p]<=t);
}

