bool isOK(vector<ll> A, ll key) {
    if (key < P)
        return true;
    A[key] += M;
    ll tmp = A[key];
    if (A[P - 1] > tmp)
        return false;
    ll score = 0;
    score += (P - 1) * M;
    score += (N - key) * M;
    for (int i = P - 1; i < key; i++) {
        score += min(M, max(0LL, tmp - A[i]));
    }

    return score >= M * V;
}

