int main () {
  int n, m, v, p; 
  cin >> n >> m >> v >> p;
  vector <int> a(n), b(n);
  vector <LL> sum(n);
  for (int i = 0; i < n; ++i) cin >> a[i], b[i] = a[i];
  sort (b.begin(), b.end());
  for (int i = 0; i < n; ++i) sum[i] = b[i];
  for (int i = 1; i < n; ++i) sum[i] += sum[i-1];
  int ans = 0;
  for (int i = 0; i < n; ++i) {
    int pos = upper_bound (b.begin(),b.end(), a[i]) - b.begin();
    int cnt = n - pos - 1;
    if (cnt < p) ++ans;
    else if (a[i]+m < b[pos+cnt-p+1]) continue;
    else {
      LL used = 1LL * (n-(cnt-p+1)) * m;
      if (used >= 1LL * v * m) ++ans;
      else {
        LL left = 1LL * v * m - used;
        if (left + sum[pos+(n-(cnt-p+1))] - sum[pos] <= a[i]+m) ++ans;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

