		lint S=(ix-leftend)*bo-(s[ix]-s[leftend])+m*(n-1-ix),
			need=m*(v-l-1);
		return(S>=need);
	};
	lint ok=p-1,ng=n,cen;
	while(abs(ok-ng)>1)cen=(ok+ng)/2,(fulfill(cen)?ok:ng)=cen;
	out(ok+1);
}

