template < class T > inline void fastScan(T &x){
    register char c = getchar();
    int neg = 0; x = 0;
    for(   ; (c < 48 || c > 57) && (c != '-'); c = getchar());
    if(c == '-') { neg = 1; c = getchar(); }
    for(   ; c > 47 && c < 58; c = getchar()){
        x = (x << 1) + (x << 3) + c - 48;
    }
    if(neg) x = -x;
}

int n;
int m, v, p;

ll inp[N];
ll cum[N];

int f(int mid){
  if(mid <= p){
    return 1;
  }
  if(inp[mid] + m < inp[p]){
    return 0;
  }
  ll need = 0;
  for(int i = 1; i <= n; i++){
    if(i < p || i >= mid){
      need += m;
    } else {
      need += inp[mid] + m - inp[i];
    }
  }
  return need >= 1ll * m * v;
}

int Solve(){
  int low = 1, high = n, ans = p;
  while(low <= high){
    int mid = (low + high) >> 1;
    if(f(mid)){
      ans = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return ans;
}

int main(){
  int test = 1;
  //fastScan(test);
  while(test--){
    fastScan(n);
    fastScan(m);
    fastScan(v);
    fastScan(p);
    for(int i = 1; i <= n; i++){
      fastScan(inp[i]);
      cum[i] += cum[i - 1] + inp[i];
    }
    sort(inp + 1, inp + n + 1, greater < ll > ());
    printf("%d\n", Solve());
  }
  return 0;
}

