ll n,m,v,p;
lvector A;

bool canwin(ll i) {
  if(n-i<=p) return true;
  ll val=A[i]+m;
  lvector B(n);
  rep(j,n) {
    if(j>=n-p+1) B[j]=m;
    else B[j]=min(val-A[j],m);
  }
  if(*min_element(ALL(B))<0) return false;
  B[i]=0;
  ll sum=0;for(ll j:B) sum+=j;
  return sum>=m*(v-1);
}

