llint n, m, v, p;
llint a[100005];
llint sum[100005];

int main(void)
{
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> m >> v >> p;
	for(int i = 1; i <= n; i++) cin >> a[i];
	sort(a+1, a+n+1);
	reverse(a+1, a+n+1);

	for(int i = 1; i <= n; i++) sum[i] = sum[i-1] + a[i];

	llint ans = 0;
	for(int i = 1; i <= n; i++){
		if(i <= p){
			ans++;
			continue;
		}
		if(a[p] > a[i] + m) continue;
		if(p >= v){
			ans++;
			continue;
		}
		llint s = (n-p+1-1)*(a[i]+m);
		s -= (n-i)*a[i];
		s -= sum[i-1]-sum[p-1];
		if(s / (v-p) >= m) ans++;
	}
	cout << ans << endl;

	return 0;
}

