      if(sequence_begin < 0){
        sequence_begin = i;
      }
      long long diff = rank_p - A[i];
      if(diff > M){
        break;
      }
      long long spill = (V - (i + 1) - (P - 1)) * M;
      //cout << i << " spill: " << spill << endl;
      long long spill_range_sum = cum_sum_A[last_rank_p] - cum_sum_A[i];
      long long spill_range = last_rank_p - i;
      long long tmp = spill + spill_range_sum;

      if(spill <= 0){
        ans += (sequence_begin - i + 1);
        sequence_begin = -1;
        continue;
      }

      if(tmp % spill_range == 0){
        if(tmp / spill_range <= A[i] + M){
          ans += (sequence_begin - i + 1);
        } else {
          break;
        }
      } else {
        if(tmp / spill_range + 1 <= A[i] + M){
          ans += (sequence_begin - i + 1);
        } else {
          break;
        }
      }
      sequence_begin = -1;
    } else {
      if(sequence_begin < 0){
        sequence_begin = i;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

