int check(int k,vi &a,int m,int v,int p,int n) {

	if(k <= p-1) return 1;

	int total=v-1;

	int mn = min(p-1,total);

	total -= mn;

	if(total > 0) {
		mn = min(n-1 - (k+1) + 1,total);
		total -= mn;
	}

	// spread out the votes
	if(total > 0) {
		int no = (k-1)-(p-1)+1;
		int rem = total*m;

		int x = rem / no;
		if(rem % no) x++;
		return a[p-1] + x - a[k] <= m;
	}

	return a[p-1] - a[k] <= m;
}

