    RSORT(A);

    LL ok = -1;
    LL ng = N;

    while (abs(ok - ng) > 1) {
        LL mid = (ok + ng) / 2;
        if (isGood(N, M, V, P, A, mid)) ok = mid;
        else ng = mid;
    }

    cout << ok + 1 << endl;

    return 0;
}

