using namespace std;

typedef pair<int, int> P;

class BVotingJudges {
public:
    int N, M, V, P;

    void solve(std::istream& cin, std::ostream& cout) {
        cin >> N >> M >> V >> P;

        vector<int> A(N);
        REP(i, N) cin >> A[i];

        sort(A.begin(), A.end());
        int b = A[N - 1 - (P - 1)];

        vector<int> sum(N + 1);
        REP(i, N) sum[i + 1] = sum[i] + A[i];

        int res = 0;
        REP(i, N) {
            int a = A[i];
            if (a >= b) {
                res++;
                continue;
            }
            if (a + M < b) {
                continue;
            }

            int rem = V - (P - 1 + i + 1);
            rem *= M;
            if (rem <= 0) {
                res++;
                continue;
            }

            int from = i + 1;
            int to = N - 1 - (P - 1);
            int num = to - from + 1;
            int val = (A[i] + M) * num - (sum[to + 1] - sum[from]);
            if (rem <= val) {
                res++;
            }
        }
        cout << res << endl;
    }
};


signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    std::istream& in(std::cin);
    std::ostream& out(std::cout);

    BVotingJudges solver;
    solver.solve(in, out);
    return 0;
}

