int main(){
    long long int N, M, V, P;

    scanf("%lld%lld%lld%lld", &N, &M, &V, &P);

    vector<long long int> A(N);

    for(int i = 0; i < N; i ++){
        scanf("%lld", &A[i]);
    }
    sort(A.begin(), A.end(), greater<long long int>());

    long long int P_num = A[P - 1];

    int i = 0;
    long long int X = 0;

    for(; i < N; i ++){
        if(A[i] == P_num){
            break;
        }
        X ++;
    }
    long long int Y = 0;

    for(; i < N; i ++){
        if(A[i] != P_num){
            break;
        }
        Y ++;
    }
    int ans = X + Y;
    long long int Z = 0;
    long long int W = N - X - Y - Z;

    for(; i < N;){
        int count = 1;

        for(int j = i + 1; j < N; j ++){
            if(A[j] == A[i]){
                count ++;
            }
        }
        if(V - X - W < 0){
            ans += count;
        }
        else if(((V - X - W) * M + Y + Z - 1) / (Y + Z) + P_num <= A[i] + M){
            ans += count;
        }
        i += count;
        Z += count;
        W -= count;
    }
    printf("%d\n", ans);
}

