using namespace std;

int main() {
	IOS;

	ll n, m, v, p, a[100005], used[100005];
	set<ll> distinct;
	cin >> n >> m >> v >> p;
	for(ll i = 1; i <= n; ++i) {
		cin >> a[i];
		distinct.insert(-1*a[i]);
	}
	sort(a+1, a+n+1);
	ll store=n+1, low = 1, high = n, pth = -1;

	ll distinctcount = 0;
	for(auto it: distinct) {
		++distinctcount;
		if(distinctcount == p) {
			pth = -1*it;
			break;
		}
	}

	while(low <= high) {
		ll mid = (low+high)/2;

		// code start
		ll pos = 0;
		if(mid >= v) {
			if(a[mid] + m >= pth) pos = 1;
		}
		else {
			ll left = m*v - mid*m, great = 0, val = a[mid] + m;
			for(ll i = n; i >= mid+1; --i) {
				if(a[i] > val) {
					left -= m;
					++great;
					continue;
				}
				used[i] = min(m, val - a[i]);
				left -= used[i];
			}
			if(great < p && left <= 0) pos = 1;
			else if(great < p) {
				for(ll i = n; i >= mid+1; --i) {
					if(a[i] > val) {
						continue;
					}
					if(used[i] != m) ++great;
					left -= (m - used[i]);
					if(left <= 0) break;
				}	
				if(great < p && left <= 0) pos = 1;
			}
		}
		// code over

		if(pos) {
			high = mid-1;
			store = mid;
		}
		else low = mid+1;
	}
	cout << n-store+1;
    return 0;
}

