	sort(points.begin(), points.end());
	auto limit = min(points[n - p - 1], max);
	auto pos = 0;
	for (auto i = p; i >= 0; i--) {
		if (points[i] < limit) {
			pos = i + 1;
			break;
		}
	}
	cout << (n - pos) << endl;

	return 0;
}

