using namespace std;


struct solver
{

    solver()
    {
        i64 n,m,V,P;
        cin>>n>>m>>V>>P;
        vector<int> a(n); cin>>a;
        sort(all(a));

        auto f=[&](const int i)->bool
        {
            i64 B=m+a[i];
            vector<int> b(a);
            b.erase(b.begin()+i);
            reverse(all(b));
            if(b[P-1]>B) return false;

            if(V<=P)
            {
                return true;
            }
            else
            {
                i64 R=V-P;
                b.erase(b.begin(),b.begin()+P-1);
                // reverse(all(b));

                vector<int> c;
                i64 sum=0;
                for(int x : b)
                {
                    sum+=B-x;
                    c.emplace_back(B-x);
                }

                while(R)
                {
                    if(sum<R*m) return false;

                    if(c.back()>=m)
                    {
                        sum-=c.back();
                        c.pop_back();
                        R--;
                    }
                    else
                    {
                        return true;
                    }
                }

                return true;
            }
        };

        cout << n-bin(f,n,-1) << "\n";
    }
}; // struct solver


