  int val = aC[id];
  sort(aC, aC + N);
  itr = upper_bound(aC, aC + N, val);  //奥
  pos = N - distance(aC, itr);         //より大きい要素数
  PRINTARR(a, a + N);
  DUMP(id, pos < P);
  PRINTARR(aC, aC + N);
  return pos < P;
}
