int main()
{
    int n, v, p;
    ll m;
    cin >> n >> m >> v >> p;
    vl a(n, 0);
    rep(i, n) cin >> a[i];
    sort(a.begin(), a.end());
    int l = -1;
    int r = n - 1;
    while(l < r - 1)
    {
        int mid = (l + r) / 2;
        auto check = [=](){
            //mが選択されるか確認
            vl temp = a;
            if(mid + 1 >= v)
            {
                for(int i = mid; i >= 0; i--)
                {
                    temp[i] += m;
                }
                sort(temp.begin(), temp.end());
                reverse(temp.begin(), temp.end());
                return temp[p - 1] <= (a[mid] + m);
            }else{
                vpl temp2(n);
                rep(i, n)  temp2[i]  = {temp[i], 0} ;            
                int count = v;
                for(int i = 0; i < mid + 1; i++)
                {
                    temp2[i].first += m;
                    temp2[i].second = 1;
                    count--;
                }
                sort(temp2.begin(), temp2.end());
                reverse(temp2.begin(), temp2.end());
                return temp2[p - 1].first <= (a[mid] + m);
            }
        };
        if(check())
        {
            r = mid;
        }else{
            l = mid;
        }
    }
    cout << n - 1 - l << endl;
}

