    sort(A.begin(), A.end(), greater<ll>());

    ll sum = A[P-1];
    vector<bool> ok(N, false);
    rep(i, P) ok[i] = true;
    for(ll i = P; i < N; i++) {
        if(A[i] == A[i-1]) {
            ok[i] = ok[i-1];
        }
        else if(N-1-i+P >= V) {
            if(A[i]+M >= A[P-1]) ok[i] = true;
        }
        else {
            ll res = V - (N-1-i+P);
            if((i-P+1)*(A[i]+M)-sum >= M*res) ok[i] = true;
        }
        sum += A[i];
    }
    ll ans = 0;
    rep(i, N) if(ok[i]) ans++;
    cout << ans << endl;
}

