			num -= (p - 1);
			if(num <= 0){
				if((a[i] + m) >= a[p]) ans++;
				continue;
			}
			ll tmp = ((a[i] + m) * (i - p)) - (sum[i] - sum[p - 1]);
			if((tmp) >= (num * m)) ans++; //no one will take too much
		}
	}
	cout << ans << endl;
	return 0;
