{
	lint n, m, v, p;
	cin >> n >> m >> v >> p;

	vec a(n);
	rep(i, n)
		cin >> a[i];

	sort(rall(a));

	vec ss(n+1);
	ss[0] = 0;
	rep(i, n)
		ss[i + 1] = ss[i] + a[i];

	lint ans = p;

	lint bo = a[p - 1];
	repi(i, p, n)
	{
		if (a[i] + m < bo)
			break;

		if (i + v - 1 < n)
		{
			ans++;
			continue;
		}

		lint r = m * (i + v - n);

		auto bi = upper_bound(all(a), a[i] + m, greater<lint>()) - a.begin();

		lint s = m * (p - 1);

		//repi(j, mmax(bi, p-1), i)
		//{
		//	s += a[i] + m - a[j];
		//}

		s += (i - mmax(bi, p - 1)) * (a[i] + m) - (ss[i] - ss[mmax(bi, p-1)]);

		if (r <= s)
		{
			ans++;
		}

	}

	cout << ans << endl;

	return 0;
}

