llong eqsum;

int main() {
    cin >> n >> m >> v >> p;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    sort(a, a + n);
    b = a[n - p];
    for (int i = 0; i < n; i++) {
        if (a[i] > b) upsum++;
        if (a[i] == b) eqsum++;
        sum[i + 1] = sum[i] + a[i];
    }

    for (int i = 0; i < n; i++) {
        if (a[i] >= b) {
            ans++;
            continue;
        }
        llong s = a[i] + m;
        llong tmp = m * v;

        tmp -= m;
        tmp -= upsum * m;
        tmp -= i * m;
        if (tmp <= 0 && s >= b) {
            ans++;
            continue;
        }

        llong idx = upper_bound(a, a + n - upsum - eqsum, s) - a;
        idx--;
        tmp -= s * (idx - i) - (sum[idx + 1] - sum[i + 1]);
        if (tmp <= 0 && s >= b) {
            ans++;
            continue;
        }

        tmp -= b * (n - upsum - idx) - (sum[n - upsum + 1] - sum[idx + 1]);
        if (tmp <= 0 && s >= b) {
            ans++;
            continue;
        }

        llong length = n - upsum - idx;
        if ((tmp + length - 1) / length <= m &&
            s >= b + (tmp + length - 1) / length) {
            ans++;
            continue;
        }
    }

    //cout << a[i] << ' ' << tmp << endl;

