using namespace std;

using ll = int;
using vi = vector<ll>;
using vvi = vector<vi>;

bool accept(const vi& A, int i, int m, int v, int p){
    if (A[i] + m < A[p-1]) return false;
    int n = A.size();
    int score = m * (v - p - n + i + 1);
    if (score <= 0) return true;
    for (int k = p-1; k < i; k++) score += A[k];
    if (score % (i+1-p) == 0) score /= (i+1-p);
    else score = score / (i+1-p) + 1;
    return A[i] + m >= max(score, A[p-1]);
}

int main(){
    int n, m, v, p;
    cin >> n >> m >> v >> p;
    vi A(n);
    for (int& i : A) cin >> i;
    sort(A.begin(), A.end(), greater<int>());
    int l = p, r = n-1, ans = p-1;
    while (l <= r) {
        int mid = (l+r)/2;
        if (accept(A, mid, m, v, p)) {
            l = mid+1;
            ans = mid;
        }
        else r = mid-1;
    }
    cout << ans+1 << endl;
}

