int main(void) {
  int64_t N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int64_t> A(N);
  rep(i, N) { cin >> A[i]; }
  sort(A.begin(), A.end(), greater<int>());

  int64_t target = A[P - 1];
  int64_t select = max(1L, V - (P - 1));
  int64_t answer = P;
  int64_t rest = 0;
  for (int i = P; i < N; ++i) {
    if ((A[i] + M) < target) continue;
    if (select <= N - i)
      ++answer;
    else {
      // have to choose some numbers before i.
      int64_t sel_num = select - (N - i);
      int64_t before_num = i - (P - 1);
      int64_t total_point = M * sel_num - rest;
      int64_t add_num = (total_point + before_num - 1) / before_num;
      if ((target + add_num) <= (A[i] + M)) {
        ++answer;
      }
    }
    rest += A[i] - target;
  }
  cout << answer << endl;
  return 0;
}

