const long long inf = 1e18;
typedef long long ll;
typedef vector<ll> vl;
#define rp(i, f, t) for (int i = f; i < t; i++)
#define pr(i, f, t) for (int i = t - 1; i >= f; i--)
#define ca(n, a) rp(ca_i, 0, n) cout << a[ca_i] << ((ca_i == n - 1) ? "\n" : " ")
#define za(n, a) rp(za_i, 0, n) a[za_i] = 0
#define be(a) a.begin(), a.end()
ll n, m, v, p;
bool solve(ll mid, vl aa)
{
    aa[mid] += m;
    ll k = aa[mid];
    sort(be(aa));
    ll kk = upper_bound(be(aa), k) - aa.begin();
    ll kkk = lower_bound(be(aa), k) - aa.begin();
    if (n - kk < p)
    {
        vl co(n);
        za(n, co);
        rp(i, 0, n)
        {
            if (i != kkk)
            {
                if (aa[i] < k)
                {
                    co[i] = k - aa[i];
                }
                else
                {
                    co[i] = inf;
                }
            }
        }
        ll pos = 0;
        while (true)
        {
            sort(be(co));
            reverse(be(co));
            if (co[v - 1] > 0)
            {
                pos += co[v - 2];
                rp(i, 0, v - 2)
                {
                    co[i] -= co[v - 2];
                }
                co[v - 2] = 0;
            }
            else
            {
                break;
            }
        }

        if (pos >= m)
            return true;
        else
            return false;
    }
    else
    {
        return false;
    }
}
