{

    cin >> n >> m >> v >> p;
    vl a(n);
    rp(i, 0, n) cin >> a[i];
    sort(be(a));
    ll ok = n - 1;
    ll ng = -1;
    ll mid = 0;
    while (abs(ok - ng) > 1)
    {
        mid = (ok + ng) / 2;
        if (solve(mid, a))
        {
            ok = mid;
        }
        else
        {
            ng = mid;
        }
    }
    cout << n - mid << endl;
}

