		int sidx = upper_bound(a.begin(), a.end(), a[i]) -a.begin();
		if(n -sidx < p){
			ans++;
			continue;
		}
		int unbeatable = n -ubidx;
		if(p-unbeatable > 0){
			ubidx -= p-unbeatable;
		}
		int rem = v -(n-ubidx) -sidx;
		//cerr << ubidx << " " << sidx << " " << rem << endl;
		if(rem <= 0){
			ans++;
			continue;
		}
		int remnum = ubidx - sidx;
		if(remnum <= rem){
			continue;
		}
		int remcap = rem*(a[i]+m) -(csum[ubidx-1] -csum[sidx-1]);
		if(remcap >= 0){
			ans++;
		}
	}
	cout << ans << endl;
	return 0;
}

