void solve() {
  ll N, M, V, P;
  cin >> N >> M >> V >> P;

  VL as(N);
  rep(i, N) cin >> as[i];

  sort(all(as));

  auto is_ok = [&](ll index) -> bool {
    ll a = as[index];
    ll rest = M * V;

    auto over_it = upper_bound(all(as), a + M);
    ll over_a_ct = as.end() - over_it;
    if (over_a_ct >= P) return false;

    rest -= (P - 1) * M;
    if (rest <= 0) return true;

    ll smaller_a_ct = upper_bound(all(as), a) - as.begin();
    rest -= smaller_a_ct * M;
    if (rest <= 0) return true;

    ll b_i = upper_bound(all(as), a) - as.begin();
    repf(i, b_i, N - (P - 1)) { rest -= a + M - as[i]; }

    return rest <= 0;
  };

  if (is_ok(0)) drop(N);

  ll ng = 0;
  ll ok = N - 1;

  while (ok - ng > 1) {
    ll mid = (ng + ok) / 2;
    if (is_ok(mid)) {
      ok = mid;
    } else {
      ng = mid;
    }
  }

  ll res = N - ok;
  cout << res << endl;
}

