void solve(long long N, long long M, long long V, long long P, std::vector<long long> A){
  sort(A.begin(),A.end());
  dump(A);
  ll l=-1,r=A.size()-1;
  while(l+1<r){
    dump(l);
    dump(r);
    ll mid=(l+r)/2;
    ll score = A[mid]+M;
    dump(score);
    ll rank = upper_bound(A.begin(),A.end(),score)-A.begin()-1;
    rank=A.size()-rank;
    if(rank>P){
      l=mid;
      continue;
    }
    dump(rank);
    ll stock = (V-P-mid)*M;
    FOR(i,mid+1,A.size()-(P-1)){
      if(i==mid)continue;
      stock-=max(0LL,min(M,score-A[i]));
    }
    dump(stock);
    if(stock>0){
      l=mid;
      continue;
    }else{
      r=mid;
      continue;
    }
  }
  cout<<A.size()-r<<endl;
}

