bool bin(int i) {
    ll sm = 0;
    ll k = a[i] + m;
    if (k < a[p - 1]) {
        return false;
    }
    sm += (p - 1) * m + (n - i) * m;
    for (int x = p - 1; x < i; x++) {
        sm += max(ll(0), k - a[x]);
    }
    return sm >= m * v;
}

