int main() {
    i64 n, m, v, p;
    std::cin >> n >> m >> v >> p;
    std::vector<i64> a(n);
    for (auto &e : a) std::cin >> e;
    std::sort(a.begin(), a.end());

    int l = -1, r = n - p;
    while (r - l > 1) {
        int k = (l + r) / 2;
        auto b(a);
        b[k] += m;
        i64 rem = (v - 1) * m, t = b[k];
        for (int i = 0; rem && i < n; i++) {
            if (i == k) continue;
            i64 d = std::min({ rem, m, std::max(0ll, t - a[i])});
            b[i] += d;
            rem -= d;
        }
        for (int i = n - 1; rem && i >= 0; i--) {
            i64 d = std::min({ m, rem, a[i] + m - b[i] });
            b[i] += d;
            rem -= d;
        }
        std::nth_element(b.begin(), b.begin() + (n - p), b.end());
        if (b[n - p] <= t) r = k;
        else l = k;
    }

    std::cout << n - r << std::endl;

    return 0;
}

