  vector<int> temp(i + 1 - P);
  rep(j, i + 1 - P) {
    temp[j] = A[i - 1 - j] - A[i];
  }

  int sum = 0, mx = 0;
  for (auto elem : temp) {
    sum += elem;
    chmax(mx, elem);
  }

  return (mx <= M && sum <= M * V);
}

signed main() {
  cin >> N >> M;
  cin >> V >> P;

  V = N - V;

  A = vector<int>(N);

  rep(i, N) {
    cin >> A[i];
  }
  sort(all(A), greater<int>());

  int ans = find_max(0LL, N, f) + 1;
  cout << ans << endl;
}

