int main()
{
	long long n, m, v, p;
	scanf("%lld%lld%lld%lld", &n, &m, &v, &p);
	long long a[100000];
	for (long long i = 0; i < n; ++i)
	{
		scanf("%lld", a + i);
	}
	std::sort(a, a + n, std::greater<long long>());
	long long l = p - 1;
	long long r = n;
	while (r - l > 1)
	{
		long long mid = l + (r - l) / 2;
		bool ok = true;
		if (mid <= n - v)
		{
			ok = a[mid] + m >= a[p - 1];
		}
		else
		{
			long long vv = v - (n - mid);
			long long target_max = a[mid] + m;
			if (target_max < a[p - 1])
			{
				ok = false;
				goto finalize;
			}
			long long largercnt = std::lower_bound(a, a + mid, target_max, std::greater<long long>()) - a;
			if (vv <= largercnt)
			{
				ok = true;
			}
			else
			{
				vv -= largercnt;
				long long safecnt = (a + mid) - std::upper_bound(a + largercnt, a + mid, target_max, std::greater<long long>());
				ok = (vv <= safecnt);
			}
		}
		finalize:
		if (ok)
		{
			l = mid;
		}
		else
		{
			r = mid;
		}
	}
	printf("%lld\n", r);
}

