long long GetSum(int l, int r)
{
    return l == 0 ? sa[r] : sa[r] - sa[l - 1];
}

long long GetMin(int l, int r, int w)
{
    assert(l <= r);
    assert(w <= (r - l + 1));
    if (w <= 0) {
        return a[r];
    }
    long long result = m + a[r];
    for (int i = l; i <= r; ++i) {
        long long lower = a[r];
        long long upper = m + a[i];
        if (i > l) {
            lower = max(lower, m + a[i - 1]);
        }
        long long w2 = w - (i - l);
        if (w2 > 0) {
            long long c = r - i + 1;
            long long value = w2 * m + GetSum(i, r);
            long long newLower = value / c;
            if (newLower * c < value) {
                ++newLower;
            }
            lower = max(lower, newLower);
        }
        if (lower <= upper) {
            result = min(result, lower);
        }
    }
    return result;
}

bool Check(int pos)
{
    if (pos >= n - p) {
        return true;
    }
    int l = pos + 1;
    int r = n - p;
    int w = (v - 1) - (p - 1) - pos;
    auto mx = GetMin(l, r, w);
    return a[pos] + m >= mx;
}

void Solve()
{
    sort(a.begin(), a.end());
    sa.assign(n, 0);
    sa[0] = a[0];
    for (int i = 1; i < n; ++i) {
        sa[i] = sa[i - 1] + a[i];
    }
    int l = 0;
    int r = n - 1;
    int result = 0;
    while (l <= r) {
        int middle = (l + r) >> 1;

        if (Check(middle)) {
            result = n - middle;
            r = middle - 1;
        } else {
            l = middle + 1;
        }
    }
    cout << result << endl;
}

