        if(A[i] == A[i-1]) {
            if(ok[i-1]) ans++, ok[i] = true;
            sum += A[i];
            continue;
        }

        if(N-1-i+P >= V) {
            if(A[i]+M >= A[P]) ans++, ok[i] = true;
        }
        else {
            ll res = V - (N-1-i+P);
            if((i-P+1)*(A[i]+M)-sum >= M*res) ans++, ok[i] = true;
        }
        sum += A[i];
    }
    cout << ans << endl;
}

