bool check(int x) {
  if (x < p) return true;

  int bound = a[x] + m;
  int vote = v - (n-x) - (p-1);

  if (bound < a[p-1]) return false;
  if (vote <= 0) return true;

  long long empty = 0;
  for (int i = p; i < x; ++i) {
    empty += bound - a[i];
  }

  if (empty < 1LL * vote * m) return false;
  return true;
}

