int main(){
  ios::sync_with_stdio(0);
  cin.tie(0);
  lll N,M,V,P;
  cin >> N >> M >> V >> P;
  vector<lll> a(N);
  vector<ll> psum(N+1);
  map<ll,ll> m;
  for(ll i = 0; i < N; ++i){
    cin >> a[i];
    ++m[a[i]];
  }
  sort(a.rbegin(),a.rend());
  for(ll i = 0; i < N; ++i) psum[i+1] = psum[i]+a[i];
  vector<lll> keys,nans;
  for(auto& p : m) keys.push_back(p.first);
  nans.push_back(0);
  for(ll i = 1; i < keys.size(); ++i){
    nans.push_back(nans.back()+m[keys[i-1]]);
  }
  ll b = 0,e = keys.size()-1;
  lll ans = P;
  while(b <= e){
    ll i = (b+e)/2;
    ll key = keys[i];
    ll tot = nans[i]+m[key];
    if(N-tot < P){
      ans = max(ans,N-nans[i]);
      e = i-1;
      continue;
    }
    if(tot+P-1 >= V){
      if(key+M >= a[P-1]){
        ans = max(ans,N-nans[i]);
        e = i-1;
        continue;
      }
    }
    else{
      ll L = N-tot;
      ll Len = L-(P-1);
      ll Tot = (V-(tot+P-1))*M;
      ll Tot1 = Len*a[P-1]-(psum[L+1]-psum[P-1]);
      ll delta = 0;
      if(Tot > Tot1) delta = (Tot-Tot1+Len-1)/Len;
      if(key+M >= a[P-1]+delta){
        ans = max(ans,N-nans[i]);
        e = i-1;
        continue;
      }
    }
    b = i+1;
  }
  cout << ans;
  return 0;
}

