int main() {
  //input
  int64_t N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int64_t> A(N);
  rep(i,N) {
    cin >> A.at(i);
  }
  //calc
  sort(A.begin(), A.end());
  map<int64_t,int64_t> group;
  vector<int64_t> uniq_v(0);
  int64_t AA;
  rep(i,N) {
    AA = A.at(i);
    if ( group.count(AA) ) {
      group[AA]++;
    }
    else {
      group[AA] = 1;
      uniq_v.push_back(AA);
    }
  }
  sort(uniq_v.begin(), uniq_v.end());
  int64_t VV = 0;
  int64_t un = uniq_v.size();
  int64_t i = 0;
  while ( i < un && VV < V ) {
    VV += group[uniq_v.at(i)];
    i++;
  }
  int64_t L_min = uniq_v.at(i);
  int64_t N_L = 0;
  for(int64_t j = i; j < un; j++) {
    N_L += group[uniq_v.at(j)];
  }
  int64_t S_L = 0;
  for(int64_t k = 0; k < i; k++) {
    if ( uniq_v.at(k) + M >= L_min ) {
      S_L += group[uniq_v.at(k)];
    }
  }
  int64_t answer = max(P, N_L + S_L);
  //output
  cout << answer << endl;
}

