    ll n, m, v, p; cin >> n >> m >> v >> p;
    VL a(n); cin >> a;

    SORT(a);

    auto solve = [&](ll x) {
        ll y = x + m, cnt = v * m - m;
        bool use = false;
        VL over; ll overcnt = 0, k = 0;
        FOR(i, 0, n) {
            if (a[i] == x && !use) {
                use = true;
                continue;
            }
            if (y < a[i]) {
                ++overcnt;
                ++k;
            }
            else if (y - a[i] <= m) {
                cnt -= y - a[i];
                over.push_back(m - y + a[i]);
            }
            else cnt -= m;
        }

        cnt -= k * m;

        rSORT(over, greater<ll>());
        for (int i = 0; i < over.size() && 0 < cnt;) {
            cnt -= over[i];
            ++overcnt;
        }
        return overcnt < p;
    };

    ll ok = LLINF, ng = 0;
    while (ok - ng > 1) {
        ll mid = (ok + ng) / 2;
