typedef pair<ll,ll> P;

bool ck(ll x,ll m,ll k,ll p,vector<ll> v) {
  vector<ll> a,b;
  rep(i,v.size()) {
    if(v[i]>x) a.pb(v[i]);
    else b.pb(v[i]);
  }
  if(a.size()>=p) return 0;
  ll z=min((ll)a.size(),k);
  k-=z;
  p-=a.size();
  ll sum=m*k;
  P c[b.size()];
  rep(i,b.size()) c[i]=P(0,i);
  rep(i,b.size()) {
    ll d=min(m,x-b[i]);
    d=min(d,sum);
    c[i].F+=d;
    sum-=d;
  }
  sort(c,c+b.size());
  rep(i,b.size()) {
    ll d=m-c[i].F;
    d=min(d,sum);
    b[c[i].S]+=d+c[i].F;
    sum-=d;
    if(b[c[i].S]>x) p--;
  }
  if(!sum&&p>=1) return 1;
  return 0;
}

