bool isOK(int N, LL M, int V, int P, VLL &A, int x){
  if(x <= P) return true;
  LL now = A.at(--x) + M;
  if(A.at(--P) > now) return false;
  LL sco = 0;
  sco += P*M;
  sco += (N-x)*M;
  FOR(i,P,x) sco += min(M,max(0LL,now-A.at(i)));
  return sco >= M*V;

}

