// 一次元累積和
template<class T>
class Ruiseki
{
private:
	int num;

public:
	vector<T> sumVal;
	Ruiseki(const vector<T> &srcVal)
	{
		num = srcVal.size();
		sumVal.resize(num + 1, 0);
		for (int i = 0; i < num; i++) {
			sumVal[i + 1] = sumVal[i] + srcVal[i];
		}
	}

	T GetSumAll()
	{
		return sumVal[num];
	}

	T GetSumRange(int startIdx, int endIdx)
	{
		return sumVal[endIdx] - sumVal[startIdx];
	}

	T GetSumFromTop(int endIdx)
	{
		return sumVal[endIdx] - sumVal[0];
	}

	T GetSumFromEnd(int startIdx)
	{
		return sumVal[num] - sumVal[startIdx];
	}
};


// 処理
void Solve()
{
	ll N, M, V, P;
	cin >> N >> M >> V >> P;
	vector<ll> A(N);
	REP(i, N) {
		cin >> A[i];
	}
	sort(ALL(A), greater<ll>());

	ll minScore = A[P - 1];
	ll nokori = V - (P - 1);
	ll ans = 0;
	reverse(ALL(A));
	Ruiseki<ll> seki(A);
	for (int i = 0; i < N; i++) {
		if (minScore <= A[i]) {
			ans++;
		} else {
			ll sameCnt = 0;
			for (; i < N - 1; i++) {
				sameCnt++;
				if (A[i] != A[i + 1]) {
					break;
				}
			}

			ll num = nokori - i - 1;
			ll addVal = A[i] + M;
			if (minScore <= addVal) {
				if (num <= 0) {
					ans += sameCnt;
				} else {
					ll nokoriNum = N - P - i; 
					ll nokoriSum = addVal * nokoriNum - seki.GetSumRange(i + 1, i + 1 + nokoriNum);
					if (nokoriSum >= num * M) {
						ans += sameCnt;
					}
				}
			}
		}
	}

	cout << ans << endl;
}

