/*先按初始分数从小到大排序
1~p一定有机会上 
二分答案check(mid):
如果a[mid]+m>=a[p] 则一定行
否则一定不行 
共有m*v张票，先给a[mid]加上m张票
然后给1~p-1区间内的每一个加上m张票
若有剩余 再给mid+1往后的每一个加上m张票
若仍有剩余 在p~mid-1区间内 给每一个加上a[mid]+m-a[inx]
若无剩余 则ok   否则不行 
*/ 
#include<bits/stdc++.h>
using namespace std;
int n,m,v,p;
int sco[100007];
long long tot=m*v;
bool cmp(int a,int b){
	return a>b;
}
bool check(int mid){
	if(sco[mid]+m<sco[p])  return false;
	long long s=m;
	s+=(1-p)*m;
	s+=(n-mid)*m;
	for(int i=p;i<mid;i++){
		s+=sco[mid]+m-sco[i];
	}
	if(s>=tot) return 1;
	else  return 0;
}
int main(){
	cin>>n>>m>>v>>p;
	for(int i=1;i<=n;i++){
		cin>>sco[i];
	}
	sort(sco+1,sco+n+1,cmp);
	int ans=p;
	int mid=(p+1+n)/2;
	int l=p+1;
	int r=n;
	while(r>l){
		if(check(mid)){
			l=mid+1;
			mid=(l+r)/2;
		}
		else{
			r=mid-1;
			mid=(l+r)/2;
		}
	}
	cout<<l-1<<endl;
}

