          if(s >= M * (V-(P+N-i-1))){
            ans++;
          }else{
            if((sum[i]-sum[P] + M * (V-(P+N-i-1)) + (i-P))/(i-P) <= M + A[i]){
              ans++;
            }else{
              break;
            }
          }
        }else{
          break;
        }
      }
    }
  }
  cout << ans << endl;
}

