    else if(vec[mid-1]+m<vec[p-1])right=mid;
    else{
      ll vote = m*(p-1) + m*(n-mid);
      for(ll i=p-1;i<=mid-1;i++){
        vote+=vec[mid-1]+m-vec[i];
      }
      if(vote>=m*v)left=mid;
      else right=mid;
    }
  }
  cout<<left<<endl;                        

}

