//////////一般化した二分探索

const bool LEFT = false;
const bool RIGHT = true;
bool judgeLR1(ll i, ll key);// 左に属するか右に属するかを判断する関数。下で定義する。
bool judgeLR2(ll i);// 左に属するか右に属するかを判断する関数。下で定義する。

ll nibutanL1(ll size, ll key) {// LEFTグループに属するうち最も右側のindexを得る
	ll L = -1;
	ll R = size;
	while (abs(R - L) > 1) {
		ll mid = (L + R) / 2;
		if (judgeLR1(mid, key) == RIGHT) R = mid;
		else L = mid;
	}
	return L;
}
ll nibutanR1(ll size, ll key) {//RIGHTグループに属するうち最も左側のindexを得る
	return nibutanL1(size, key) + 1;
}

ll nibutanL2(ll size) {// LEFTグループに属するうち最も右側のindexを得る
	ll L = -1;
	ll R = size;
	while (abs(R - L) > 1) {
		ll mid = (L + R) / 2;
		if (judgeLR2(mid) == RIGHT) R = mid;
		else L = mid;
	}
	return L;
}
ll nibutanR2(ll size) {//RIGHTグループに属するうち最も左側のindexを得る
	return nibutanL2(size) + 1;
}


bool judgeLR1(ll i, ll key) {// v[i]がkeyよりも大きいかどうか
	if (key < v[i]) { return RIGHT; }
	return LEFT;
}

bool judgeLR2(ll i) {
	ll n = V;
	ll sum = 0;
	ll x = v[i] + M; n--;
	sum += M;
	ll k = nibutanR1(N, x);
	k = (N - k);
	if (k >= P) { return LEFT; }
	sum += k * M; n -= k;
	if (n <= 0) { return RIGHT; }

	for (ll j = 0; j < N - k; j++) {
		if (j == i) { continue; }
		if (j > N - P) { sum += M; }
		else {
			sum += min(v[i] + M - v[j], M);
		}
	}
	if (sum >= M * V) { return RIGHT; }
	return LEFT;
}

int main() {
	cin >> N >> M >> V >> P;
	for (ll i = 0; i < N; i++) {
		ll a; cin >> a;
		v.push_back(a);
	}

	sort(v.begin(), v.end());
	for (ll i = 0; i < N; i++) {
		if (i == 0) { s.push_back(0); }
		else { s.push_back(s[i - 1] + v[i]); }
	}

	ll k = nibutanR2(N);
	cout << N - k << endl;

	return 0;
}

