typedef vector<VI> VVI;
const ll MOD = 1000000007;
const ll INF = 2147483647;
const ll LLINF = 9223372036854775807;
#define REP(i, n) for(int i = 0; i < n; i++)
#define ALL(v) v.begin(), v.end()

int main() {
	ll n, m, v, p; cin >> n >> m >> v >> p;
	VI a(n); REP(i, n)cin >> a[i];
	sort(ALL(a), greater<ll>());
	int l = p, r = n - 1;
	while (r - l > 1) {
		int t = l + ((r - l) / 2);
		if (a[p - 1] > a[t] + m) {
			r = t;
			continue;
		}
		else if (v - (n - t) <= 0) {
			l = t;
			continue;
		}
		priority_queue<ll> q;
		REP(i, v - (n - t)) q.push(m);
		for (int i = t - 1; i >= 0; i--) {
			ll yo = (a[t] + m - a[i]);
			if (i < p)yo = INF;
			ll x = q.top(); q.pop();
			if (yo <= 0 || x == 0) break;
			x = max((ll)0, x - yo);
			if(x != 0) q.push(x);
		}
		if (q.empty()) {
			l = t;
		}
		else {
			r = t;
		}
	}
	cout << l + 1 << endl;
	return 0;
}

