bool C(ll m){
    // index m以下の問題数がV-P以下の時はindex mは採用され得る
    if(V - P <= m) return true;

    // スコアの合計と残りのポイント数の合計が小さければ大丈夫
    if((S[N-(P-1) + 1] - S[m+1]) + M * (V - (m + P)) <= (N - (P-1) - m) * (A[m] + M) ) return true;

    return false;
}

