const int N = 1e5;
llong a[N+3],s[N+3];
int n; llong M,X,K;
int ans;

int main()
{
	scanf("%d%lld%lld%lld",&n,&M,&X,&K);
	for(int i=1; i<=n; i++) scanf("%lld",&a[i]); sort(a+1,a+n+1);
	int left = 1,right = n;
	while(left<right)
	{
		int mid = left+((right-left)>>1); llong x = X; x--; int rk = 0; bool ret = false;
//		printf("check %d\n",mid);
		for(int i=1; i<=n; i++)
		{
			if(a[i]>a[mid]+M) {x--; rk++;}
		}
		if(rk>=K) {ret = false;}
		else if(x<=0) {ret = true;}
		else
		{
			llong rst = M*x;
//			printf("rst=%lld\n",rst);
			for(int i=1; i<=n-rk; i++)
			{
				if(i==mid) continue;
				rst -= min(M,a[mid]+M-a[i]);
			}
//			printf("rst=%lld\n",rst);
			if(rst<=0) {ret = true;}
			else
			{
				int gg = K-1-rk;
				for(int i=n-rk,j=1; j<=gg; i--)
				{
					if(i==mid) continue;
					rst -= max(0ll,a[i]-a[mid]); j++;
				}
//				printf("gg=%d rst=%lld\n",gg,rst);
				if(rst<=0) {ret = true;}
			}
		}
		if(ret) {right = mid;}
		else {left = mid+1;}
	}
	printf("%d\n",n-right+1);
	return 0;
}

