llong n, m, v, p;
llong a[100005];
llong sum[100005];
llong b;
llong ans;

int main() {
    cin >> n >> m >> v >> p;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    sort(a, a + n);
    b = a[n - p];
    for (int i = 0; i < n; i++) {
        sum[i + 1] += sum[i] + a[i];
    }

    for (int i = 0; i < n; i++) {
        if (a[i] >= b) {
            ans++;
            continue;
        }

        llong tmp = m * v;
        tmp -= m;
        tmp -= i * m;
        tmp -= (p - 1) * m;

        llong s = a[i] + m;
        if (tmp <= 0 && s >= b) {
            ans++;
            continue;
        }

        llong valid = n - p - 1;
        llong invalid = i - 1;
        while (valid - invalid > 1) {
            llong mid = (valid + invalid) / 2;

            if (s > a[mid]) {
                invalid = mid;
            }
            else {
                valid = mid;
            }
        }
        while (s < a[valid]) valid--;

        if (tmp - s * (valid - i) + sum[valid + 1] - sum[i + 1] <= 0 &&
            s >= b) {
            tmp -= s * (valid - i) - sum[valid + 1] - sum[i + 1];
            ans++;
            continue;
        }

        if (tmp <= m &&
            s >= b + tmp) {
            tmp -= m;
            ans++;
            continue;
        }

        //cout << a[i] << ' ' << tmp << endl;
    }

    cout << ans << endl;

    return 0;
}

