int main() {

	////==================================
	cin.tie(nullptr);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(30);
	////==================================

	ll N, M, V, P;
	cin >> N >> M >> V >> P;

	vll A(N);
	for (int i = 0; i < N; i++)
	{
		cin >> A[i];
	}

	sort(A.begin(), A.end(), greater<ll>());

	ll can_last = P - 1;
	for (int i = can_last + 1; i < N; i++)
	{
		if (A[can_last] == A[i])
		{
			can_last++;
		}
	}

	ll ans = can_last + 1; // 上位P問は可能


	// P問目の投票前スコア
	ll border = A[P - 1];


	vll accum(N);
	for (int i = 0; i < N; i++)
	{
		accum[i] =A[i];
	}

	for (int i = 1; i < N; i++)
	{
		accum[i] += accum[i - 1];
	}



	ll border_begin = 0;
	for (int i = 0; i < N; i++)
	{
		if (A[i] == border)
		{
			border_begin = i;
			break;
		}
	}



	for (int i = can_last + 1; i < N; i++)
	{

		// 上位P-1問は捨てて、ボーダーはP問目の投票後スコア
		ll super_waste = (P - 1) * M;


		// i番目の取得スコア
		ll get_score = 1 * M;
		ll final_score = A[i] + get_score;
		if (final_score < border)
		{
			continue;
		}

		// P位～i-1問目までに捨てられる量
		ll mid_waste;
		if (border_begin != 0)
		{
			mid_waste = final_score * (i - border_begin) - (accum[i - 1] - accum[border_begin - 1]);
		}
		else
		{
			mid_waste = final_score * (i - border_begin) - accum[i - 1];
		}

		// iより低いものには毎回投票してよい
		ll infer_waste = (N - i - 1) * M;


		if (super_waste + get_score + mid_waste + infer_waste >= M * V)
		{
			ans++;
		}


	}

	cout << ans << endl;


}

