bool isOK(int index) {
    if (index<=pos) return false;
    int cnt=0;
    int maxr=0;
    rep(i,N){
        if(i<pos) continue;
        else if(i<index){
            cnt+=A[i]-A[index];
            maxr=max(maxr,A[i]-A[index]);
        }
        else break;
    }
    if(min(N-V,index-pos)*M>=cnt && maxr<=M ) return false;
    else return true;
}

int binary_search() {
    int left = -1;
    int right = N-1;

    while (right - left > 1) {
        int mid = left + (right - left) / 2;

        if (isOK(mid)) right = mid;
        else left = mid;
    }

    return left;
}

