		s[i] = (i?s[i-1]:0)+a[i];
	}
	F0R(i,n) {
		if (i >= n-p) {
			ans++;
			continue;
		}
		long long num = p-1+i;
		if (num >= v-1) {
			if (a[i]+m >= a[n-p]) {
				ans++;
			}
			continue;
		}
		long long tmp = upper_bound(a.begin(), a.end(), a[i]+m)-a.begin()-1;
//		printf("sum = %d*%d-(%d-%d)\n", (min(tmp,n-p)-i), (a[i]+m), s[min(tmp,n-p)], s[i]);
		long long sum = (min(tmp,n-p)-i)*(a[i]+m)-(s[min(tmp,n-p)]-s[i]);
//		printf("%d:%d %d %d\n", i, num, tmp, sum);
		if (sum >= m*(v-num-1)) ans++;
	}
	cout << ans;
}

