ll N, M, V, P;
vector<ll> A;

ll check_(ll check_index) {
  ll ans;

  vector<ll> B;
  REP(i, 0, N) {
    B.push_back(A[i]); // A is sorted A.
  }

  B[check_index] = A[check_index] + M;
  sort(B.begin(), B.end());
  ll target_index__ = N;
  REP(i, 0, N) {
    if (B[i] > A[check_index] + M) {
      target_index__ = i; // B[target_index] > A[check_index] + M
      break;
    }
  }
  // cout << "target_index__: " << target_index__ << endl;
  if ( (N - target_index__) > P ) {
    // cannot accept this number
    // cout << "11111111" << endl;
    return 0;
  }
  else {
    // pay point to problems higher than target.
    ll rest_points = V - (N - target_index__ + 1); // V - (number of higher point problems)
    if (rest_points <= 0) {
      // cout << "22222222" << endl;
      return 1; // can accept this number
    }

    ll VV[M]; // rest points of M judges
    REP(i, 0, M) {
      VV[i] = rest_points;
    }
    // cout << "rest_points: " << rest_points << endl;
    ll target_index = 0;
    REP(i, 0, N) {
      if (B[i] == A[check_index] + M) {
        target_index = i - 1; // B[target_index] is lower than A[check_index] + M
        break;
      }
    }

    REP(i, 0, M) {
      VV[i] = VV[i] - (A[check_index] + M - B[i]);
      // cout << "VV[" << i << "]: " << VV[i] << endl;
    }
    ll temp = 0;
    REP(i, 0, M) {
      if(VV[i] > 0) {
        temp++;
      }
    } // (N - 5) + 1
    // cout << "target_index: " << target_index << endl;
    // cout << "temp: " << temp << endl;
    if ( (N - target_index__ + 1) + temp <= P ) {
      // cout << "333333333" << endl;
      return 1; // can accept this number
    }
    else {
      // cout << "444444444" << endl;
      return 0; // cannot accept this number
    }
  }

  return ans; // if 0, this number cannot be accepted.
}

