int main() {
    ll N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<ll> Ais(N);
    rep(i,0,N) {
        cin >> Ais[i];
    }
    sort(Ais.begin(), Ais.end());
    auto is_ok = [N, M, V, P, &Ais](ll i) -> bool {
        ll v = V;
        ll p = P;
        v--;
        vector<ll> others;
        others.reserve(Ais.size());
        rep(j,0,Ais.size()) {
            if (i != j) {
                others.push_back(Ais[j]);
            }
        }
        vector<ll> sum(others.size()+1);
        rep(n,1,others.size()+1) {
            sum[n] = sum[n-1] + others[n-1];
        }
        auto it1 = upper_bound(others.begin(), others.end(), Ais[i]+M);
        if (distance(it1, others.end()) >= p) {
            return false;
        }
        p -= distance(it1, others.end());
        v -= distance(it1, others.end());
        auto it0 = upper_bound(others.begin(), others.end(), Ais[i]);
        v -= distance(others.begin(), it0);
        if (v <= 0) {
            return true;
        }
        // [it0, it1) = Ai[i]より大、Ai[i]+M以下
        rep(q,0,distance(it0, it1)+1) {
            if (q > v) {
                break;
            }
            if (q >= p) {
                break;
            }
            ll w = v - q;
            ll s = (sum[distance(others.begin(), it1-q)] - sum[distance(others.begin(), it0)]);
            ll b = (Ais[i] + M) * distance(it0, it1-q) - s;
            if (w * M <= b) {
                return true;
            }
        }
        return false;
    };
    if (is_ok(0)) {
        cout << N << endl;
        return 0;
    }
    ll bad = 0;
    ll good = N-1;
    while (good - bad >= 2) {
        ll mid = (bad + good) / 2;
        if (is_ok(mid)) {
            good = mid;
        } else {
            bad = mid;
        }
    }
    cout << N - (bad + 1) << endl;
}

