    if ( P + mn_idx -1 >= V ){
        ans = N - mn_idx;
    } else {
        INT mn = 0;
        INT mx = N-P;
        do {
            INT mid = (mx+mn+1) / 2;
            INT remain = M*V - (P-1)*M - M*mid -M;
            INT limit  = As[mid] + M;
            for( INT i = mid+1; i <= N-P; i++ ){
                if( As[i] >= limit || remain <= 0) 
