void solve() {
    int n, m, v, p;
    cin >> n >> m >> v >> p;

    vector<int> va(n);
    for (int i = 0; i < n; ++i) {
        cin >> va[i];
    }
    sort(va.rbegin(), va.rend());

    int lo = p - 1;
    int hi = n - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2;

        ll cum = -1;
        if (va[mid] + m >= va[p-1]) {
            cum = 0;
            for (int i = p-1; i < mid; ++i) {
                cum += va[mid] + m - va[i];
            }
        }
        ll vcnt = max(0, v - (n - mid) - p + 1);

        if (cum < vcnt * m) {
            hi = mid - 1;
        } else {
            lo = mid;
        }
    }
    cout << lo+1 << endl;
}

