int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout << fixed << setprecision(11);
	cerr << fixed << setprecision(6);

	int n, m, v, p;
	cin >> n >> m >> v >> p;

	vll scores(n);
	for (ll &x : scores) { cin >> x; }
	sort(ALL(scores), greater<ll>());
	debug() << imie(scores);

	auto CanHave = [&](int idx) {
		debug() << imie(idx);
		if (idx < p) { return true; }
		const ll idx_score = scores[idx] + m;
		const int always_take = (p-1) + (n-idx-1);
		const int L = p-1;
		const int R = idx-1;
		const int rem_others = v - always_take - 1;
		debug() << imie(idx_score) << imie(always_take) << imie(rem_others);
		debug() << imie(L) << imie(R) << imie(idx_score);
		ll total = 0;
		for (int i = L; i <= R; ++i) {
			const ll rem = idx_score - scores[i];
			if (rem < 0) { return false; }
			total += min<ll>(max<ll>(0, rem), m);
		}
		if (rem_others <= 0) { return true; }
      // to make total number of votes >= m*v
		return total >= (ll)rem_others * m;
	};

	int lft = 0, rgt = n;
	while (rgt - lft > 1) {
		const int mid = (lft + rgt) / 2;
		if (CanHave(mid)) {
			lft = mid;
		} else {
			rgt = mid;
		}
	}

	cout << rgt << "\n";
}

