bool moze(int q) {
	copy(a, a+q, b);
	copy(a+q+1, a+n, b+q);
	int h = a[q] + m;
	ll w = 0;
	reverse(b, b+n-p);
	for (int i=0; i<n-p; i++) {
		if (b[i] > h)
			return false;
		w += h - b[i];
		if (w < max(0, (v - p) + i - (n - p - 1)) * 1ll * m)
			return false;
	}
	return true;
}

