const int DY[9] = { 1,-1,0,0, 1, -1, 1, -1, 0 }; // 8:８近傍 9:(0,0)を含む
const ll MOD = 1e9 + 7; //10^9 + 7
const double PI = 3.14159265358979323846264338327950288;
//========================================================================

int main() {

	//==================================
	cin.tie(nullptr);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(30);
	//==================================

	ll N, M, V, P;
	cin >> N >> M >> V >> P;
	vll A(N);
	for (ll i = 0; i < N; i++) {
		cin >> A[i];
	}


	// 最後のP問（同率も）は可能性あり。
	sort(A.begin(), A.end(), greater<ll>());

	// 一か所に集中できる
	if (P >= V) {

		ll ans = 0;

		// A[p-1] - A[i] <= M なら可能性あり
		for (ll i = 0; i < N; i++) {
			if (A[P - 1] - A[i] <= M) {
				ans++;
			}
			else {
				break;
			}
		}
		cout << ans;
		return 0;


	}
	else {
		// P-1問と自分より下にあげても足りるかどうか

		ll border = A[P - 1];

		ll mae = P-1; // 尺取り

		vll ruiseki(N);
		for (ll i = 0; i < N; i++) {
			ruiseki[i] = 0;
		}
		ruiseki[0] = A[0];
		for (ll i = 1; i < N; i++){
			ruiseki[i] = A[i - 1] + ruiseki[i - 1];
		}

		ll ans = 0;

		for (ll i = 0; i < N; i++) {


			// M個で足りなければ論外
			if (border - A[i] > M) {
				cout << ans;
				return 0;
			}
			else {

				ll mine = A[i] + M;// これを抜かれなければOK

				ll amari = V - P; // これをうまく分けて抜かれなければOK

				if (i + amari <= N - 1) {
					// 自分より後ろに配ればよい
					ans++;
				}
				else {
					ll front = V - P - (N - 1 - i); // 前に配らないといけない数

					if (front >= i - P && P < i) {
						// 前全員配らないといけないから無理
						cout << ans;
						return 0;
					}
					else {

						// min(mine - A[j], M)の累積 <= front * M　ならOK

						for (ll k = mae; mae < i; k++) {
							if (A[k] < mine) {
								mae = k;
								break;
							}
						}

						ll can = mine * (i - mae) - (ruiseki[i] - ruiseki[mae]);

						if (can >= front * M) {
							ans++;
						}
						else {
							cout << ans;
							return 0;
						}
					}

				}

			}

		}
	}




}

