int n,np,nv,nt;
vector<int> box(1e5);

bool check(int mid) {
  bool ans_bool=false;
  if(box.at(nt-1)<=box.at(mid)) {
    ans_bool=true;
  }
  else if(box.at(mid)+np >= box.at(nt-1)) {
    if(nv<=nt) {
      ans_bool=true;
    }
    else {
      long long check_sum=0;
      for(int i=nt-1;i<n;i++) {
        if(i==mid) continue;
        check_sum+=min(np,box.at(mid)+np-box.at(i));
        if(check_sum>=np*(nv-nt))) {
          ans_bool=true;
          break;
        }
      }
    }
  }
  return ans_bool;
}

int main() {
  cin >> n >> np >> nv >> nt;
  for(int i=0;i<n;i++) {
    cin >> box.at(i);
  }

  sort(box.rbegin(),box.rend());

  int mx=n-1;
  int mn=nt-1;
  int mid=(mx+mn)/2;
  while(mx-mn>=2) {
    if(check(mid)) {
      mn=mid;
    }
    else {
      mx=mid;
    }
    mid=(mn+mx)/2;
  }
  cout << mn+1 << endl;
}

