static void exec()
{
	int N;
	getint(N);
	LLONG M;
	getint(M);
	int V, P;
	getint(V, P);

	std::vector<LLONG> ai(N);
	for (int i = 0; i < N; i++) {
		getint(ai[i]);
	}
	std::sort(ai.begin(), ai.end(), std::greater<LLONG>());
	int ans = P;
	LLONG bfr = 0;
	for (int i = P; i < N; i++) {
		if (ai[i] + M < ai[P - 1]) {
			break;
		}
		if (bfr == ai[i]) {
			ans++;
			continue;
		}

		LLONG otherPt = 0;
		for (int j = P - 1; j < i; j++) {
			otherPt += (ai[i] + M) - ai[j];
		}
		otherPt += (M * (P - 1)) + (M * (N - i));
		if (otherPt >= (M * V)) {
			ans++;
			bfr = ai[i];
		}
		else {
			break;
		}
	}
	printf("%d\n", ans);
}

