int main() {
	int n, m, v, p; scanf("%d%d%d%d", &n, &m, &v, &p);
	std::vector<int> a(n);
	for(int i = 0; i < n; i++) scanf("%d", &a[i]);
	sort(begin(a), end(a));

	auto check = [&](int t) {
		int val = a[t] + m, nv = v, L = 1 << 30, R = -1;
		for(int i = 0; i < n; i++) {
			nv -= (a[i] <= a[t] or val < a[i]);

			if(a[t] < a[i]) L = std::min(L, i);
			if(a[i] <= val) R = std::max(R, i);
		}
		if(n - R - 1 >= p) return false;
		if(nv <= 0) return true;

		i64 tmp = 0, add = m;
		std::vector<int> b = a;
		std::queue<std::pair<int, int>> qu;
		for(int i = R; i >= L + nv - 1; i--) {
			while(!qu.empty() and i <= qu.front().first) {
				tmp -= qu.front().second;
				qu.pop();
			}

			b[i] = a[i] + tmp;
			i64 diff = val - b[i];
			add -= diff;
			tmp += diff;
			b[i] += diff;
			qu.push({i - nv, diff});
		}
		if(add <= 0) return true;

		int np = n - R - 1;
		for(int i = L; i < L + nv; i++) {
			if(b[i] + add > val) np++;
		}
		return np < p;
	};

	int ok = n - 1, ng = -1;
	while(std::abs(ok - ng) > 1) {
		int mid = (ok + ng) >> 1;

		if(check(mid)) ok = mid;
		else ng = mid;
	}

	printf("%d\n", n - ok);
	return 0;
}

