ll mod_pow(ll x, ll n, ll mod)
{
    ll res = 1;
    bool c = false;
    while (n)
    {
        if (n & 1)
            res = res * x;

        if (res > mod)
        {
            c = true;
            res %= mod;
        }
        x = x * x % mod;
        n >>= 1;
    }
    if (c)
        return mod;
    return res;
}

#define SIEVE_SIZE 5000000 + 10
bool sieve[SIEVE_SIZE];
void make_sieve()
{
    for (int i = 0; i < SIEVE_SIZE; ++i)
        sieve[i] = true;
    sieve[0] = sieve[1] = false;
    for (int i = 2; i * i < SIEVE_SIZE; ++i)
        if (sieve[i])
            for (int j = 2; i * j < SIEVE_SIZE; ++j)
                sieve[i * j] = false;
}

bool isprime(ll n)
{
    if (n == 0 || n == 1)
        return false;
    for (ll i = 2; i * i <= n; ++i)
        if (n % i == 0)
            return false;
    return true;
}

template <typename T>
vector<T> gauss_jordan(const vector<vector<T>> &A, const vector<T> &b)
{
    int n = A.size();
    vector<vector<T>> B(n, vector<T>(n + 1));

    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            B[i][j] = A[i][j];
        }
    }

    for (int i = 0; i < n; ++i)
        B[i][n] = b[i];

    for (int i = 0; i < n; ++i)
    {
        int pivot = i;
        for (int j = i; j < n; ++j)
        {
            if (abs(B[j][i]) > abs(B[pivot][i]))
                pivot = j;
        }
        swap(B[i], B[pivot]);

        if (abs(B[i][i]) < EPS)
            return vector<T>(); //解なし

        for (int j = i + 1; j <= n; ++j)
            B[i][j] /= B[i][i];
        for (int j = 0; j < n; ++j)
        {
            if (i != j)
            {
                for (int k = i + 1; k <= n; ++k)
                    B[j][k] -= B[i][j] * B[i][k];
            }
        }
    }

    vector<T> x(n);

    for (int i = 0; i < n; ++i)
        x[i] = B[i][n];
    return x;
}

typedef vector<ll> vec;
typedef vector<vec> mat;

mat mul(mat &A, mat &B)
{
    mat C(A.size(), vec((int)B[0].size()));
    for (int i = 0; i < A.size(); ++i)
    {
        for (int k = 0; k < B.size(); ++k)
        {
            for (int j = 0; j < B[0].size(); ++j)
            {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j] % MOD) % MOD;
            }
        }
    }
    return C;
}
mat mat_pow(mat A, ll n)
{
    mat B(A.size(), vec((int)A.size()));

    for (int i = 0; i < A.size(); ++i)
    {
        B[i][i] = 1;
    }

    while (n > 0)
    {
        if (n & 1)
            B = mul(B, A);
        A = mul(A, A);
        n >>= 1;
    }
    return B;
}

