const int MAX = 510000;
long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit()
{
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int bit[1000010];
int sums(int i)
{
    i++;
    int s = 0;
    while (i > 0)
    {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}
void add(int i, int x)
{
    i++;
    while (i <= 1000010)
    {
        bit[i] += x;
        i += i & -i;
    }
}
long long extGCD(long long a, long long b, long long &x, long long &y)
{
    if (b == 0)
    {
        x = 1;
        y = 0;
        return a;
    }
    long long d = extGCD(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

ll GCD(ll a, ll b)
{

    if (b == 0)
        return a;
    return GCD(b, a % b);
}

struct BipartiteMatching
{
    vector<vector<int>> graph;
    vector<int> match, alive, used;
    int timestamp;

    BipartiteMatching(int n) : graph(n), alive(n, 1), used(n, 0), match(n, -1), timestamp(0) {}

    void add_edge(int u, int v)
    {
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    bool dfs(int idx)
    {
        used[idx] = timestamp;
        for (auto &to : graph[idx])
        {
            int to_match = match[to];
            if (alive[to] == 0)
                continue;
            if (to_match == -1 || (used[to_match] != timestamp && dfs(to_match)))
            {
                match[idx] = to;
                match[to] = idx;
                return true;
            }
        }
        return false;
    }

    int bipartite_matching()
    {
        int ret = 0;
        for (int i = 0; i < graph.size(); i++)
        {
            if (alive[i] == 0)
                continue;
            if (match[i] == -1)
            {
                ++timestamp;
                ret += dfs(i);
            }
        }
        return ret;
    }

    void output()
    {
        for (int i = 0; i < graph.size(); i++)
        {
            if (i < match[i])
            {
                cout << i << "-" << match[i] << endl;
            }
        }
    }
};

ll N, M, V, P;
ll A[100010];
pair<ll, ll> B[100010];
bool C(ll idx)
{
    for (int i = 0; i < N; i++)
    {
        B[i] = make_pair(A[i], i);
    }

    //cout << N << " " << M << " " << V << " " << P << endl;
    B[idx].first += M;

    ll nokori_V = V - 1;
    sort(B, B + N);

    ll nidx = 0;
    ll val = 0;
    for (int i = 0; i < N; i++)
    {
        if (B[i].second == idx)
        {
            nidx = i;
            val = B[i].first;
            break;
        }
    }

    ll bigger = 0, equal = 0;
    for (int i = 0; i < N; i++)
    {
        if (B[i].second == nidx)
            continue;

        if (val < B[i].first)
        {
            bigger++;
        }
        if (val == B[i].first)
        {
            equal++;
        }
    }

    if (bigger >= P)
        return false;
    ll times = M;
    ll nokori_P = P - bigger - 1;

    times += bigger * M;

    if (nokori_P <= equal)
    {
        nokori_P = 0;
        times += nokori_P * M;

        for (int i = 0; i < N; i++)
        {
            if (val == B[i].first)
                break;
            times += min(M, val - B[i].first);
        }
    }
    else
    {
        nokori_P -= equal;
        times += equal * M;

        for (int i = N - 1; i >= 0; i++)
        {
            if (val <= B[i].first)
                continue;

            if (min(M, val - B[i].first) == M)
            {
                times += M;
            }
            else
            {
                if (nokori_P)
                {
                    times += M;
                    nokori_P--;
                }
                else
                {
                    times += val - B[i].first;
                }
            }
        }
    }

    //cout << idx << " " << times << " " << M << endl;

    if (times / V >= M)
    {
        return true;
    }
    else
    {
        return false;
    }
}
int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    cin >> N >> M >> V >> P;
    for (int i = 0; i < N; i++)
    {
        cin >> A[i];
    }
    sort(A, A + N);
    ll lb = -1, ub = N - 1;

    while (ub - lb > 1)
    {
        ll mid = (ub + lb) / 2;

        if (C(mid))
        {
            ub = mid;
        }
        else
        {
            lb = mid;
        }
    }
    cout << N - lb - 1 << endl;
    return 0;
}

