#define MAXN 100100
int N, M, V, P;
int a[MAXN];
int aC[MAXN];
bool isOK(int id) {
  if (id == -1) return false;
  if (id == N) return true;
  //
  memcpy(aC, a, sizeof(int) * N);
  auto itr = upper_bound(a, a + N, a[id] + M);
  int pos = distance(a, itr);
  int cnt = M * (V - 1);
  aC[id] += M;
  REP(i, pos) {
    if (cnt == 0) break;
    if (i == id) continue;
    if (a[i] < a[id]) {
      aC[i] += M;
      cnt -= M;
    } else if (a[i] > a[id]) {
      int val = min(a[i] - a[id], cnt);
      aC[i] += val;
      cnt -= val;
    }
  }
  REPR(i, N - 1) {
    if (cnt == 0) break;
    int val = min(aC[i] - a[i], cnt);
    aC[i] += val;
    cnt -= val;
  }
  DUMP(id);
  PRINTARR(a, a + N);
  PRINTARR(aC, aC + N);
//  assert(accumulate(a, a + N, 0) + M * V == accumulate(aC, aC + N, 0));
  //  REP(i, V) aC[(id - i + N) % N] += M;
  int val = aC[id];
  sort(aC, aC + N);
  itr = upper_bound(aC, aC + N, val);  //奥
  pos = N - distance(aC, itr);         //より大きい要素数
  PRINTARR(a, a + N);
  DUMP(id, pos < P);
  PRINTARR(aC, aC + N);
  return pos < P;
}
signed main() {
  cin.tie(0), ios::sync_with_stdio(false);
  cout << fixed << setprecision(12);
  cin >> N >> M >> V >> P;
  REP(i, N) cin >> a[i];
  sort(a, a + N);

  //初期値は異なる。
  int left = -1;
  int right = N;
  DUMP(isOK(N - 1));
  DUMP(isOK(0));
  while (right - left > 1) {
    int mid = (left + right) / 2;
    // left trueの場合
    if (isOK(mid))
      right = mid;
    else
      left = mid;
  }
  print(N - right);
}

