		LL PM = pM[a[i]];

		if (Final <= a[i]) {
			ans++;

		} else if (v <= PM) {
			LL F = a[i] + m;
			if (F >= Final) {
				ans++;
			}

		} else {
			LL F = a[i] + m;
			LL other = v - PM;
			LL s_cnt = (n - i - 1) - p; // F-1以下になってほしい数
			LL cnt = 0; //F-1以下になった数

			// plasMされないところの最大
			int pos_npm = n - other - 1;
			// F-1以下の最大
			int pos = Upper(a, F - 1) - 1;
			// F-1以下の数
			int cnt_f = pos > pos_npm ? pos_npm - i : max(0, pos - i);
			//残り
