const int Max=1e5+7;
ll a[Max];
ll b[Max];
ll n,m,v,p;
bool check(ll x,ll m,ll v,ll p,ll n){

    memcpy(b,a,sizeof a);
    for(int i = x;i <= n;++i){
        if(!v) break;
        b[i] += m;
        v --;
    }
    for(int i = 1;i <= p-1;++i){
        if(!v) break;
        b[i] += m;
        v --;
    }
    ll d = v * m;
    if(d == 0){
        return b[x] >= b[p];
    }
    else{
        for(int i = p;i < x;++i){
            if(b[i] - b[x] > 0) return 0;
            ll po = b[x] - b[i];
            po = min(po,m);
            d -= po;
            if(d <= 0) break;
        }
        if(d > 0) return 0;
        return 1;
    }
}
int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin>>n>>m>>v>>p;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    sort(a+1,a+1+n,greater<ll>());
    ll l=p;
    ll r=n;
    while(l<r){
        ll mid=l+r>>1;
        if(check(mid,m,v,p,n)){
            l=mid+1;
        }else{
            r=mid-1;
        }
    }
    cout<<l<<endl;
    return 0;
}

