bool check(vector<int> a, int idx, int n, int m, int v, int p) {
  ll rest = m * (v - 1);
  int base = a[idx] + m;
  for (int i = 0; i < p - 1; ++i) {
    a[i] += m;
    rest -= m;
  }
  for (int i = p - 1; i < n - 1; ++i) {
    ll t = min(m, max(0, base - a[i]));
    rest -= t;
    a[i] += t;
    // cout << i << " " << t << ", ";
  }
  // cout << a << " " << idx << " " << base << " " << rest << endl;
  return a[p - 1] <= base && rest <= 0;
}

