int n,v,p;
ll a[100100],b[100100],m;

bool check(int j){
	int i,cnt=0;
	ll t,lft,tmp;
	for(i=0; i<n; ++i){
		b[i] = a[i];
	}
	lft = m*(v-1);
	b[j] += m; t = b[j];
	for(i=0; i<n; ++i){
		if(!lft){
			break;
		}
		tmp = min({m+a[i]-b[i],max(t-b[i],0ll),lft});
		b[i] += tmp;
		lft -= tmp;
	}
	for(i=n-1; i>=0; --i){
		if(!lft){
			break;
		}
		tmp = min(m+a[i]-b[i],lft);
		b[i] += tmp;
		lft -= tmp;
	}
	if(lft){
		return false;
	}
	for(i=0; i<n; ++i){
		if(b[i]>b[j]){
			++cnt;
		}
	}
	return (cnt<p);
}

