bool korajay(int idx, vector<ll>&arr, int bhot, ll bhoter, int nibo){
    int n = arr.size();
    bhot -= n-idx+nibo-1;
    ll cur = arr[idx] + bhoter;
    vector<ll>baal(arr.begin()+nibo-1, arr.begin()+idx);
    if(baal.empty()) return true;
    if(cur>=baal[0] and bhot<=0) return true;
    if(cur<baal[0]) return false;
    ll bakivot = bhot * bhoter;
    while(baal.size()){
        ll dif = cur - baal.back();
        baal.pop_back();
        bakivot -= min(dif, bhoter);
    }
    if(bakivot>0) return false;
    return true;
}

