int bin_search(int x, vector<int> &A)
{
        int N = A.size();
        if (A[N - 1] <= x)
                return (N - 1);

        int beg = 0;
        int end = N - 1;

        while ((end - beg) > 1)
        {
                int mid = (beg + end)/2;
                if (A[mid] > x)
                        end = mid;
                else
                        beg = mid;
        }

        return beg;
}

