long long A[100000];
long long cum_sum_A[100000];
int main(){
  int N;
  long long M;
  int V;
  int P;
  cin >> N >> M >> V >> P;
  for(int i = 0; i < N; i++){
    cin >> A[i];
  }
  sort(A, A + N);

  cum_sum_A[0] = A[0];
  for(int i = 1; i < N; i++){
    cum_sum_A[i] = A[i] + cum_sum_A[i - 1];
  }
  long long rank_p = A[N - P];
  int start_ind;
  int ans = P;

  for(int i = N - P; i >= 0; i--){
    if(A[i] != rank_p){
      ans += (N - P - i - 1);
      start_ind = i;
      break;
    }
  }

  int rank_p_num = 0;
  int last_rank_p = 0;
  for(int i = 0; i < N; i++){
    if(A[i] == rank_p){
      rank_p_num ++;
    }
  }
  for(int i = N - 1; i >= 0; i --){
    if(A[i] == rank_p){
      last_rank_p = i;
      break;
    }
  }
  if(V > N - rank_p_num){
    cout << ans << endl;
    return 0;
  }

  int sequence_begin = -1;
  for(int i = start_ind; i >= 0; i--){
    //cout << i << " " << ans << endl;
    if(i == 0 || A[i - 1] != A[i]){
      if(sequence_begin < 0){
        sequence_begin = i;
      }
      int diff = rank_p - A[i];
      if(diff > M){
        break;
      }
      int spill = (V - (i + 1) - (P - 1)) * M;
      //cout << i << " spill: " << spill << endl;
      long long spill_range_sum = cum_sum_A[last_rank_p] - cum_sum_A[i];
      long long spill_range = last_rank_p - i;
      long long tmp = spill + spill_range_sum;

      if(spill <= 0){
        ans += (sequence_begin - i + 1);
        sequence_begin = -1;
        continue;
      }

      if(tmp % spill_range == 0){
        if(tmp / spill_range <= A[i] + M){
          ans += (sequence_begin - i + 1);
        } else {
          break;
        }
      } else {
        if(tmp / spill_range + 1 <= A[i] + M){
          ans += (sequence_begin - i + 1);
        } else {
          break;
        }
      }
      sequence_begin = -1;
    } else {
      if(sequence_begin < 0){
        sequence_begin = i;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

