ll n, m, v, p;
ll a[maxn];
vector<pair<ll, ll> > x;
#define X first
#define Y second

ll preX[maxn];
ll preY[maxn];
ll preXY[maxn];
ll has[maxn];

bool check(int idx) {
    if (preY[n] - preY[idx - 1] <= p) return true;
    ll need = x[idx].first + m;
    ll needv = (ll)(v - preY[idx]) * m;
    if (needv <= 0) return true;
    int l = idx, r = n;
    int rank = 0;
    while (l <= r) {
        int mid = l + r >> 1;
        if (x[mid].X > need) {
            rank = mid;
            r = mid - 1;
        } else l = mid + 1;
    }
    int pos = 0;
    if (rank == 0) rank = 1, pos = n;
    else {
        pos = rank - 1;
        needv -= m * (preY[n] - preY[rank - 1]);
        rank = preY[n] - preY[rank - 1] + 1;
    }
    if (rank > p) return false;
    if (needv <= 0) return true;
    for (int i = idx + 1; i <= pos; ++i) {
//        if (need < x[i].X) {
//            printf("%lld %lld\n",  need, x[i].X);
//            assert(0);
//        }
        assert(need >= x[i].X);
//        if (need <= x[i].X) break;
        has[i] = (m - need + x[i].X);
        needv -= x[i].Y * (need - x[i].X);
        if (needv <= 0) return true;
    }
    for (int i = pos; i >= idx + 1; --i) {
        if (rank + x[i].X <= p) needv -= has[i] * x[i].Y;
        else {
            needv -= (p - rank) * has[i];
            return needv <= 0;
        }
        if (needv <= 0) return true;
    }
    return false;
}

