const int SIZE = 1e6+10;
LL A[SIZE];
LL N,M,V,P;
LL d[SIZE];
bool solve(int n,int over_num){
    if(over_num>n)return 0;
    d[n+1]=0;
    sort(d,d+n+1,greater<int>());
    int pos=0,div=0;
    LL all=0;
    REP(i,n)all+=d[i];
    FOR(i,1,over_num){
        if(d[pos]==0){
            return 0;
        }
        div++;
        while(d[pos]>all/div){
            all-=d[pos++];
            div--;
        }
        if(i==over_num) return all/div>=M;
    }
    return 0;
}
bool good(LL mm){
    LL base=A[mm]+M;
    if(V<=P){
        return base>=A[N-P];
    }
    else{
        LL over_num=V-P;
        int n=0;
        d[0]=0;
        FOR(i,0,N-P){
            if(i==mm)continue;
            if(A[i]>base)return 0;
            if(A[i]<base)d[++n]=base-A[i];
        }
        return solve(n,over_num);
    }
}
