signed main() {
	ll N, M, V, P;
	vector<ll> A;
	scanf("%lld%lld%lld%lld", &N, &M, &V, &P);
	A.assign(N, 0);
	for(ll i=0; i<N; i++) scanf("%lld", &A[i]);
	sort(A.begin(), A.end());

	auto isOK = [&](ll val) -> bool {
		if(N-P<=val){
			return true;
		}
		ll valpoint=A[val]+M;
		ll amaripoint=(V-P-val)*M;
		ll sumpoint=0;
		for(ll i=val+1; i<=N-P; i++){
			ll t=valpoint-A[i];
			if(t<0)return false;
			sumpoint+=min(M,t);
		}
		if(amaripoint>sumpoint)return false;
		return true;
	};

	if(isOK(0)){
		printf("%lld\n", N);
		return 0;
	}

	ll left = 0;
	ll right = N-1;
	while(right - left > 1) {
		ll mid = left + (right - left) / 2;
		if(isOK(mid)) right = mid;
		else left = mid;
	}

	printf("%lld\n", N-right);
