using namespace std;

int A[100005], B[100005];

bool func(int val, int N, int M, int V, int P)
{
    int indx = 0;

    for(int i=N; i>=1; i--)
    {
        B[i] = A[i];

        if(B[i] == val)
            indx = i;
    }

    long long rem = 1LL * M * V;

    for(int i=indx; i<=N; i++)
        B[i] += M, rem -= M;

    // cout << val << ": ";

    // for(int i=1; i<=N; i++)
    //     cout << B[i] << " ";
    // cout << "\n";

    int ptr = 1;

    while(ptr < indx && B[ptr] > B[indx])
        P--, B[ptr++] += M, rem -= M;

    // for(int i=1; i<=N; i++)
    //     cout << B[i] << " ";
    // cout << "\n";

    if(P < 0)
        return false;

    long long best_ans = 0;

    for(int i = ptr; i < indx; i++)
        best_ans += min(B[indx] - B[i], M);

    // cout << "Test : " << best_ans << " " << indx << " " << ptr << " " << rem << " " << P << "\n";

    for(int i = ptr; i < indx; i++)
    {
        if(best_ans < rem)
        {
            best_ans -= min(B[indx] - B[i], M);
            P--, B[i] += M, rem -= M;

            if(P < 0)
                return false;
        }
        else
            return true;
    }

    return true;
}

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(NULL), cout.tie(NULL);

    int N, M, V, P;
    cin >> N >> M >> V >> P;

    for(int i=1; i<=N; i++)
        cin >> A[i];

    sort(A+1, A+1+N);
    reverse(A+1, A+1+N);

    int left = P, right = N, ans = P;

    while(left <= right)
    {
        int mid = (left + right) / 2;

        if(func(A[mid], N, M, V, P-1))
            ans = mid, left = mid + 1;
        else
            right = mid - 1;
    }

    cout << ans << "\n";
    return 0;
}

