bool check(int pos){
	if (pos + p >= n)
		return true;
	if (v <= p)
		return a[n - p] <= a[pos] + m;

	int cnt = v - p;
	int need = m;
	multiset<int> vals;
	int add = 0;
	forn(i, n - (p - 1)) if (i != pos){
		vals.insert(min(m, a[pos] + m - a[i]) + add);
		if (sz(vals) == cnt){
			li t = min(need, *vals.begin() - add);
			need -= t;
			add += t;
			while (*vals.begin() - add == 0){
				vals.erase(vals.begin());
			}
		}
	}

	return need == 0;
}

