using namespace std;

const int maxn=1e5+10;
int a[maxn];
int n,m,v,p;
int b[maxn];
int vis[maxn];
bool judge(int mid){
    memset(vis,0,sizeof(vis));
    int res=max(0ll,(v-mid)*m);
    int now=a[mid]+m;
    for(int i=1;i<=n;i++)b[i]=a[i];
    for(int i=mid+1;i<=n;i++){
        if(res==0)continue;
        if(a[i]>now){
            int del=res>=m?m:res;
            b[i]=a[i]+del;
            res-=del;
            if(del==m)vis[i]=1;
        }
        else{
            int del=min(res,min(now-a[i],m));
            b[i]=a[i]+del;
            res-=del;
            if(del==m)vis[i]=1;
        }
    }
    if(res>0){
        for(int i=n;i>=1;i--){
            if(res==0)break;
            if(vis[i])continue;
            int add=res>=m?m:res;
            res-=add;
            b[i]+=add;
        }
    }
    if(res>0)return false;
    sort(b+1,b+n+1);
    if(now>=b[n-p+1]){
        return true;
    }
    return false;
}
