  for (int i = 0; i < n; ++i) cin >> a[i], b[i] = a[i];
  sort (b.begin(), b.end());
  for (int i = 0; i < n; ++i) sum[i] = b[i];
  for (int i = 1; i < n; ++i) sum[i] += sum[i-1];
  int ans = 0;
  for (int i = 0; i < n; ++i) {
    int pos = upper_bound (b.begin(),b.end(), a[i]) - b.begin();
    int cnt = n - pos - 1;
    if (cnt < p) ++ans;
    else if (a[i]+m < b[pos+cnt-p+1]) continue;
    else {
      LL used = 1LL * (n-(cnt-p+1)) * m;
      if (used >= 1LL * v * m) ++ans;
      else {
        LL left = 1LL * v * m - used;
        if (left + sum[pos+cnt-p+1] - sum[pos] > 1LL * (cnt-p+1) * (a[i]+m)) continue;
        else {
          int len = cnt+p-1, have = v - len;
          memset (tmp, 0, sizeof(int)*(len+1));
          int ed = pos+len, add = 0, need = a[i]+m, qwq = m;
          for (int j = 0; j < len; ++j) {
            add += tmp[j];
            int now = b[ed-j]+add, canadd = need - now;
            add += canadd;
            tmp[j+have] -= canadd;
            qwq -= canadd;
            if (qwq <= 0) break;
          }
          if (qwq <= 0) ans++;
        }
      }
    }
  }
