// midがpより後である =>
// midを+1, 0~mid-1を+1する。残り v-(mid+1)
// midがp番目になるには2つ条件が必要
// - v-(mid+1)<=p-1
// - a[mid]+m>=a[n-p (p番目)]
bool isOk(ll mid){
  if(n-p-1<=mid) return 1;

  ll rem=v-(mid+1)-(p-1); // midを選ぶ上で1人が影響のない分を投票した残り

