    ll cnt=(n-(p-1))-(mid+1);
    ll d=(sum[n-(p-1)]-sum[mid+1]);
    ll x=(a[mid]+m)*cnt-d;
    // cout<<mid<<' '<<d<<' '<<x<<' '<<rem<<' '<<cnt<<endl;
    if(x>=rem*m) return 1;
  }
  return 0;
}


