    else if (a[i]+m < b[pos+cnt-p+1]) continue;
    else {
      LL used = 1LL * (n-(cnt-p+1)) * m;
      if (used >= 1LL * v * m) ++ans;
      else {
        LL left = 1LL * v * m - used;
        if (left + sum[pos+cnt-p+1] - sum[pos] > 1LL * (cnt-p+1) * (a[i]+m)) continue;
        else {
          int have = v - (n-cnt+p-1), len = cnt+p-1;
          memset (tmp, 0, sizeof(int)*(len+1));
          int ed = pos+len, add = 0, need = a[i]+m, qwq = m;
          for (int j = 0; j < len; ++j) {
            add += tmp[j];
            int now = b[ed-j]+add, canadd = need - now;
            add += canadd;
            tmp[j+have+1] -= canadd;
            m -= canadd;
            if (qwq <= 0) break;
          }
          if (qwq <= 0) ans++;
        }
      }
    }
  }
  cout << ans << endl;
  return 0;
}

