long long target;
long long leftBound; 

bool check(long long curPos) {
	long long curNum = a[curPos] + m;
	if (curNum < target) {
		return false;
	}

	long long leftV = v - (n - curPos);
	long long totalM = leftV * m;	//剩下的总数据 

	long long pPos = curPos - 1;
	while (totalM > 0) {
		if (pPos < leftBound)
			return false;

		long long dist = curNum - 1 - a[pPos];
		if (dist < 0)
		{
			pPos--;
			continue;
		}

		if (dist > m)
			dist = m;

		totalM = totalM - dist;
		pPos--;
	}

	return true;
}

long long doSearch(long long left, long long right) {
//	long long n = szA;
	long long head = left;
	long long tail = right;
	long long result = -1;
	long long mid;

	while (head <= tail)
	{
		mid = (head + tail) / 2;
		if (check(mid))
		{
			result = mid;
			head = mid + 1;			
		}
		else
		{
			tail  = mid - 1;			
		}
	}

	return result;
}

