typedef long long          num;

using namespace std;

const int nsz = 1e5;
int n, p, ans;
num m, k, a[nsz + 5], b[nsz + 5];

bool inline cmp(int i, int j) {
    return b[i] - a[i] < b[j] - a[j];
}

bool inline chk(num md) {
    cont (i, n) {
        b[i] = a[i];
    }
    num mx = 0, sum = m * k;
    vector<int> rem;
    cont (i, n) {
        if (b[i] <= md) {
            num del = min(sum, m);
            sum -= del;
            b[i] += del;
            mx = max(mx, b[i]);
        }
    }
    cont (i, n) {
        if (a[i] == b[i] && b[i] < mx) {
            num del = min(sum, mx - b[i]);
            sum -= del;
            b[i] += del;
            rem.push_back(i);
        } else if (a[i] == b[i]) {
            num del = min(sum, m);
            sum -= del;
            b[i] += del;
        }
    }
    sort(all(rem), cmp);
    loop (i, rem.size()) {
        int id = rem[i];
        num del = min(sum, m - (b[id] - a[id]));
        b[id] += del;
        sum -= del;
    }
    sort(b + 1, b + n + 1);
    reverse(b + 1, b + n + 1);
    cont (i, p) {
        if (b[i] == mx)  return 1;
    }
    return 0;
}

int main()  {
