    cin >> n >> m >> k >> p;
    cont (i, n) {
        cin >> a[i];
    }
    sort(a + 1, a + n + 1);
    reverse(a + 1, a + n + 1);
    num l = -1, r = 1e16, md = (l + r) >> 1;
    for (; r - l > 1; md = (l + r) >> 1) {
        (chk(md) ? r : l) = md;
    }
    cont (i, n) {
        ans += a[i] >= r;
    }
    cout << ans << ln;
}

