	sort(A.begin(), A.end(), greater<ll>());

	// 一か所に集中できる
	if (P >= V) {

		ll ans = 0;

		// A[p-1] - A[i] <= M なら可能性あり
		for (ll i = 0; i < N; i++) {
			if (A[P - 1] - A[i] <= M) {
				ans++;
			}
			else {
