			}
		}
		cout << ans;
		return 0;


	}
	else {
		// P-1問と自分より下にあげても足りるかどうか

		ll border = A[P - 1];

		ll mae = P-1; // 尺取り

		vll ruiseki(N);
		for (ll i = 0; i < N; i++) {
			ruiseki[i] = 0;
		}
		ruiseki[0] = A[0];
		for (ll i = 1; i < N; i++){
			ruiseki[i] = A[i - 1] + ruiseki[i - 1];
		}

		ll ans = 0;

		for (ll i = 0; i < N; i++) {


			// M個で足りなければ論外
			if (border - A[i] > M) {
