const int MAX = 1e5 + 5;
const int INF = 1001001001;
const int MOD = 1e9 + 7;

int N, M, V, P;
vector<int> A;

bool f(int x) {
    int num = A[x] + M;
    int nV = V - 1;

    // Ax + M よりも最初から大きいものに投票する
    int countUp = A.end() - upper_bound(A.begin(), A.end(), num);
    nV -= countUp;

    if (nV <= 0) return countUp + 1 <= P;

    // Ai + M <= Ax + M なるAi に投票する
    rep(i, N) {
        if (i == x) continue;
        if (num <= A[i]) break;

        if (A[i] + M <= num) {
            nV--;
        }
    }

    if (nV <= 0) return countUp + 1 <= P;

    ll plus = (ll)M * nV;

    rep(i, N) {
        if (i == x) continue;
        if (num <= A[i]) break;
        if (A[i] + M <= num) continue;

        plus -= num - A[i];
    }

    if (plus <= 0) return countUp + 1 <= P;

    int i = 0;
    while (1 < plus) {
        if (i == x) {
            i++;
            continue;
        }
        if (A[i] + M <= num) {
            i++;
            continue;
        }

        plus -= M - (num - A[i]);
        i++;
        countUp++;
    }

    return countUp + 1 <= P;
}

