    for (int64_t i = 0; i < N; i++) {
        sum[i + 1] = sum[i] + A[i];
    }

    int64_t ans = 0;
    for (int64_t i = 0; i < N; i++) {
        //i番目のものが選ばれうるか

        //そもそも上位P個は大丈夫
        if (i < P) {
            ans++;
            continue;
        }

        //A[i]が到達可能なスコア
        //int64_t value = A[i] + M;

        //最適な割り振り
        //上位P - 1個までに選ぶ
        //自分より下位に選ぶ
        //余ったやつが問題
        int64_t rem_vote = V - (P - 1) - (N - 1 - i) - 1;

        //rem_voteがM回発生する
        //それを上位[P - 1, i)までに割り振ることになる
        //j in [P - 1, i)としてA[j]が受け取れる回数は
        //min(value - A[j], M)
        //これを足していってrem_vote * M以上になるなら大丈夫
        //さてこれではO(N^2)
        //value = A[i] + Mで戻すと
        //min(A[i] + M - A[j], M)
        //A[i] < A[j]なのでこれはつまりM - A[j] + A[i]
        //これの和なのでnum * M - sum[P-1 ~ i)_A + num * A[i]
        //分解すると
        int64_t num = i - (P - 1);

        int64_t v = num * (M + A[i]) - sum[i] + sum[P - 1];
        if (v >= rem_vote * M) {
            ans++;
        }
    }

    cout << ans << endl;
}

