template<class T>class CulSum {
	int n; vector<T> s;
public:
	static vector<T> bulid(const vector<T>& a) {
		int N = a.size();
		vector<T> ret(N + 1);
		for (int i = 0; i < N; ++i)ret[i + 1] = ret[i] + a[i];
		return ret;
	}
	template<class U, class F>static vector<T> bulid(const U& a, F f) {
		int N = a.size();
		vector<T> ret(N + 1);
		for (int i = 0; i < N; ++i)ret[i + 1] = ret[i] + static_cast<T>(f(a[i]));
		return ret;
	}
	CulSum(const vector<T>& a) :n(a.size()) {
		s = bulid(a);
	}
	template<class U, class F>CulSum(const U& a, F f) : n(a.size()) {
		s = bulid(a, f);
	}
	// [l, r)
	T operator()(int l, int r)const {
		l = min(max(l, 0), n); r = min(max(r, 0), n);
		return l > r ? 0 : s[r] - s[l];
	}
	// [0, r)
	T operator()(int r)const {
		r = min(max(r, 0), n);
		return s[r];
	}
	vector<T> get_s()const { return s; }
};

int main() {
	LL n = in, m = in, v = in, p = in;
	VL a = in[n]; Sort(a);
	CulSum<LL> cul(a);
	dump(a);

	LL Final = a[n - p];

	map<LL, LL> pM;
	rep(i, n) {
		if (i == n - 1 || a[i] < a[i + 1]) {
			pM[a[i]] = (LL)(i + 1);
		}
	}

	LL ans = 0;

	rep(i, n) {

		LL PM = pM[a[i]];

		if (Final <= a[i]) {
			ans++;

		} else if (v <= PM) {
			LL F = a[i] + m;
			if (F >= Final) {
				ans++;
			}

		} else {
			LL F = a[i] + m;
			// plas Mされる数
			LL other = v - PM;
			// F以下になった数
			LL cnt = 0;
			// plas Mされないところの最大
			LL pos_npm = n - other - 1;
			// F以下になってほしい数
			LL s_cnt = (n - p) - PM + 1;
			// F以下の最大
			LL pos = Upper(a, F) - 1;
			// F以下の数
			LL cnt_f = pos > pos_npm ? pos_npm - i : max(0LL, pos - i);
			// マイナスにできる残り
			LL rem = 0;

			// p <= pos_npm //
			cnt += cnt_f;
			rem += (F - 1) * cnt_f - cul(i + 1, i + 1 + cnt_f);

			// p > pos_npm      //
			// plas M されている //

			auto need = [&](LL pos_) {
				LL size = pos_ - pos_npm;
				return cul(pos_npm + 1, pos_npm + 1 + size) + m * size  // sum
					- F * size;
			};

			LL res = -1;
			if (need(pos_npm + 1) > rem) {
				res = 0;
			} else if (need(n - 1) <= rem) {
				res = n - 1 - pos_npm;
			} else {
				LL left = pos_npm + 1, right = n - 1;
				while (right - left > 1) {
					LL mid = (left + right) / 2;
					if (need(mid) <= rem) {
						left = mid;
					} else {
						right = mid;
					}
				}
				res = left;
			}
			cnt += (res - pos_npm);


			//dump(i, s_cnt, cnt);

			if (s_cnt <= cnt) {
				ans++;
			}
		}
	}

	out(ans);
}

