const int MAXN = 100005;

int n, m, v, p;
int a[MAXN];

bool trial(int x){
	auto idx = upper_bound(a, a + n, a[x]) - a;
	if(v <= idx + p - 1) return 1;
	lint tmp = 1ll * (v - idx - p + 1) * m;
	for(int i=idx; i<n-p+1; i++){
		if(a[x] + m < a[i]) return 0;
		tmp -= max(0, a[x] + m - a[i]);
	}
	return tmp <= 0;
}

int main(){
	scanf("%d %d %d %d",&n,&m,&v,&p);
	for(int i=0; i<n; i++) scanf("%d",&a[i]);
	sort(a, a + n);
	int s = 0, e = n;
	while(s != e){
		int m = (s+e)/2;
		if(trial(m)) e = m;
		else s = m + 1;
	}
	cout << n - s << endl;
}

