ll solve1(ll N, ll M, ll V, ll P, vector<ll>& A) {
    sort(A.begin(), A.end());
    if ( P >= V ) {
        //ll cr = A[N-1-(V-1)] - M;
        ll cr = A[N-P] - M;
        ll i = lower_bound(A.begin(), A.end(), cr) - A.begin();
        return N - i;
    } else {
        ll cr = A[N-1-(P-1)] - M;
        ll i0 = lower_bound(A.begin(), A.end(), cr) - A.begin();
        if ( i0 > V - P ) {
            return N - i0;
        } else {
            vector<ll> ca(N);
            ll sm = 0;
            for ( int i = 0; i < N; i++ ) {
                sm += A[i];
                ca[i] = sm;
            }
            for ( ll j = i0; j < N-P; j++ ) {
                ll rm = (V - P - j) * M;
                ll f = (A[j]+M) * (N-P-j) - (ca[N-P] - ca[j]);
                if ( f >= rm ) {
                    return N - j;
                }
            }
            return P;
        }
    }
    return -1;
}

ll solve2(ll N, ll M, ll V, ll P, vector<ll>& A) {
    sort(A.begin(), A.end(), greater<>());

    auto check = [&](ll x) {
        if ( x < P ) return true;
        ll c = (P-1) * M;
        if ( A[P-1] > A[x] + M ) return false;
        c += (N - x) * M;
        for ( int i = P-1; i < x; i++ ) {
            c += A[x] + M - A[i];
        }
        return c >= V * M;
    };

    ll l = 0, r = N;
    while ( r - l > 1 ) {
        ll m = (l + r) / 2;
        if ( check(m) ) l = m;
        else r = m;
    }
    return l + 1;
}
