bool check(ll N, ll M, ll V, ll P, vec A, ll X)
{
    ll z = A[P - 1];
    if (X <= P - 1)
        return true;
    if (A[X] + M < z)
        return false;
    //投票されても構わない回数
    ll nopro = 0;
    nopro += (P - 1) * M;
    nopro += (N - X) * M;
    for (ll i = P - 1; i <= X - 1; i++)
    {
        nopro += (A[X] + M - A[i]);
    }
    if (nopro >= M * V)
        return true;
    else
        return false;
}
