    loop(i, 100)
    {
        ll mid = (ok + ng) / 2;
        if (check(N, M, V, P, A, mid))
            ok = mid;
        else
            ng = mid;
        if (ok == ng)
            break;
    }
    putout(ok + 1);
    return 0;
}

