int N, M, V, P;
int A[1010101];

bool can(int ind)
{
    if(N-ind <= P) return true;

    int jpt = V;

    jpt -= P-1; // P-1 problems stashed
    jpt -= ind; // ind problems stashed()
    jpt -= 1; // given to ind-th problem

    jpt = max(0, jpt);

    int pt_ind = M+A[ind];

    //printf("!%d %d %d\n", jpt, ind, pt_ind);

    //kick N-P'th problem
    if(A[N-P] > pt_ind) return false;

    long long sv = 0;

    for(int i=ind+1; i<=N-P; ++i)
        sv += pt_ind-A[i];

    return sv >= 1LL*jpt*M;


    //distribute between i+1 ~ P

}
int main()
{
    cin >> N >> M >> V >> P;
    for(int i=0; i<N; ++i) cin >> A[i];
    sort(A, A+N);
    int lo = 0;
    int hi = N;

    while((lo+1)!=hi)
    {
        int mi = (lo+hi)>>1;
        if(can(mi)) hi = mi;
        else lo = mi;
    }
    //printf("%d %d\n", lo, hi);
    //hi~N-1: possible
    printf("%d\n", N-hi);
}

