bool stg(int x)
{
	for (int i = 1; i <= n; ++i)
		qq[i] = 0;
	long long q = 0;
	qq[x] += m;
	q += m;
	for (int i = 1; i <= n; ++i)
	{
		if (i == x)
			continue;
		if (a[i] > a[x] + m)
			break;
		if (a[i] + m <= a[x] + m)
		{
			qq[i] += m;
			q += m;
		}
		else
		{
			qq[i] += (a[x] + m - a[i]);
			q += qq[i];
		}
	}
	for (int i = n; i >= 1; --i)
	{
		if (q >= (m * 1LL * v))
			break;
		q += (m - qq[i]);
		qq[i] = m;
	}
	int t = 0;
	for (int i = 1; i <= n; ++i)
	{
		if (a[x] + qq[x] >= a[i] + qq[i])
			++t;
	}
	return t >= pp;
}

