{
	return x > y;
}

bool check(int x)
{
	if(x <= p) return 1;
	if(a[x] + m < a[p]) return 0;
	int rv = v - (p - 1) - (n - x + 1);
	if(rv < 0) return 1;
	ll rs = rv * m;
	for(int i = p + 1; i <= x - 1; i++)
		rs -= a[x] + m - a[i];
	return (rs <= 0);
}

