template <typename T>
struct BIT {
private:
    vector<T> v;
public:
    BIT(int n) : v(n, 0) {}
    T sum(int i) const {
        T s = 0;
        while (i > 0) {
            s += v[i];
            i = (i & (i + 1)) - 1;
        }
        return s;
    }
    void add(int i, T x) {
        while (i < (int)v.size()) {
            v[i] += x;
            i |= i + 1;
        }
    }
    int size() const { return v.size(); }
};

int main() {
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<ll> a(n);
    for (auto &e: a) cin >> e;

    sort(a.begin(), a.end());

    BIT<ll> a_bit(n+1);
    for (int i = 1; i <= n; ++i) {
        a_bit.add(i, a[i-1]);
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        ll tn = a[i];
        ll s = upper_bound(a.begin(), a.end(), tn) - a.begin();
        ll t = upper_bound(a.begin(), a.end(), tn+m) - a.begin() - s;
        ll q = n-(s+t);
        if (q >= p) continue;

        if (t+q <= p-1) {
            ++ans;
            continue;
        }

        t -= (p-1)-q;
        q = p-1;

        int ts = upper_bound(a.begin(), a.end(), tn) - a.begin();
        int tt = n-(p-1);
        ll tsum = a_bit.sum(tt) - a_bit.sum(ts);

        ll lim = (q+s)*m + (t*(tn+m) - tsum);
        if (m*v <= lim) ++ans;
    }

    cout << ans << endl;

    return 0;
}

