bool can_clear(ll index){
    //cout<<index<<endl;
    if(N-index<=P) return true;
    ll necess=max((ll)0, V-P-index);
    ll value_maxim=A[index]+M;
    ll count=0;
    ll i=index+1;
    while(true){
        //cout<<i<<endl;
        if(i>N-P) break;
        if(A[i]>value_maxim) return false;
        count+=min(M, value_maxim-A[i]);
        i++;
    }
    //
    if(count>=necess*M) return true;
    else return false;
}

//条件に合致する最小indexを二分探索 O(logN)
//-2...全indexがみたす -1...条件に合致するものがない
ll nibutan_min(ll min, ll max){
  //評価関数can_clear(ll　value) を指定すること
  ll left=min, right=max;
  ll ans;
  while(true){
      //cout<<left<<" " <<right<<endl; //debug用
      if(left+1==right){
        if(can_clear(left)){
          if(left==min) return -2;
          else return left;
        }
        else{
          if(can_clear(right)) return right;
          else return -1;
        }
        break;
      }
      ll nibutan=(left+right)/2;
      bool can_do_it=can_clear(nibutan);
      if(can_do_it) right = nibutan;
      else left = nibutan;
  }
}

