bool can(int idx)
{
	int curr = a[idx] + m;
	int curr_v = v, curr_p = p-1; 
	curr_v--;

	int cnt_greater = 0;
	for (int i = 1; i <= n; i++)
		if (a[i] > curr)
			cnt_greater++;

		if (cnt_greater >= p)
			return false;

    curr_p -= cnt_greater;
    curr_v -= cnt_greater; 
    if (curr_v <= 0)
    	return true;

    long long sum = 0;
    for (int i = n; i >= 1; i--)
    	if (i != idx && a[i] <= curr)
    	{
    		if (curr_p)
    		{
    			curr_v--;
    			curr_p--;
    			continue;
    		}

    		sum += min(curr-a[i], m);
    	}

    return sum / curr_v >= m;
}

