		if (cnt_greater >= p)
			return false;

    curr_p -= cnt_greater;
    curr_v -= cnt_greater; 
    if (curr_v <= 0)
    	return true;

    long long sum = 0;
    for (int i = n; i >= 1; i--)
    	if (i != idx && a[i] <= curr)
    	{
    		if (curr_p)
    		{
    			curr_v--;
    			curr_p--;
    			continue;
    		}

    		sum += min(curr-a[i], m);
    	}

    return sum / curr_v >= m;
}

void solve()
{
	sort (a + 1, a + n + 1);
	int low = 1, high = n;
	while (low < high)
	{
		int mid = (low + high) / 2;
		if (can(mid))
			high = mid; 

		else 
			low = mid + 1; 
	}

	cout << n - low + 1 << endl; 
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	read();
	solve();
}

