    ll k = max((ll)0,len-avi);
    ll maa = enm[0];
    ll sum = k*m;
    dF(i,len-1,0){
        ll d = maa-enm[i];
        if(d>=num[i]){
            sum-=m;
            len--;
        }
        else{
            enm[i]+=d;
            num[i]-=d;
            sum-=d;
        }
        if(sum<=0) return x>=maa?1:0;
    }
    ll cur = 0;
    //F(i,0,len-1) cout<<enm[i]<<endl;
    dF(i,len-1,0){
        if(num[i]==cur){
            len--;
            continue;
        }
        if(sum>=len*(num[i]-cur)) maa+=num[i]-cur;
        else{
            maa+=ceil(sum*1.0/len);
            return x>=maa?1:0;
        }
        sum-=len*(num[i]-cur);
        cur+=num[i];
        len--;
        if(sum<=0) return x>=maa?1:0;
    }
}

