inline void solve() {
	int n, m, v, p;
	cin >> n >> m >> v >> p;
	vector<int> a(n);
	vector<ll> sm(n + 1);
	cin >> a;
	sort(all(a));
	reverse(all(a));
	for (int i = 1; i <= n; ++i) {
		sm[i] = sm[i - 1] + a[i - 1];
	}
	int ans = p;
	for (int i = p; i < n; ++i) {
		if (a[i] + m < a[p - 1]) break;
		ll need = ll(m) * (v - (n - i + p - 1));
		ll can = ll(m + a[i]) * (i - p + 1) - (sm[i] - sm[p - 1]);
		assert(can >= 0);
		if (need > can) break;
		++ans;
	}
	cout << ans << endl;
}

