        if (a[i] != a[i - 1])
            ra[i] = i;
        else
            ra[i] = ra[i - 1];
        //printf("%lld %d\n", a[i], ra[i]);
    }
    //printf("\n");
    int ans = 0;
    for (int i = 1; i <= n; i++)
    {
        if (ra[i] <= p)
        {
            ans++;
            continue;
        }
        if (n - (ra[i] - p) < v)
        {
            //printf("i=%d\n", i);
            int f = ra[i] - (n - v);
            if (f == i)
                continue;
            //printf("f=%d\n", f);
            int cnt = f - p + 1;
            ll add = sum[f] - sum[p - 1];
            ll now = add - a[i] * cnt;
            //printf("i=%d %lld\n", i, now);
            if (m >= now)
                ans++;
            continue;
        }
        if (m >= a[p] - a[i])
            ans++;
    }
    cout << ans << endl;

    return 0;
}

