  auto can = [&](int idx) -> bool {
    vector<int> B = A;
    int x = B[idx] + M;
    B.erase(B.begin() + idx);

    int votes_left = V - 1;
    {
      int d = min(votes_left, P - 1);
      for (int i = 0; i < d; ++i) B[i] += M;
      votes_left -= d;
    }

    int i = lower_bound(B.begin(), B.end(), x, greater<int>()) - B.begin();
    if (i >= P) return false;

    vector<int> C;
    for (int j = P; j < (int)B.size(); ++j) {
      if (P - 1 - i > j - P) {
        C.push_back(M);
      } else {
        C.push_back(min(M, x - B[j]));
      }
    }

    int64_t area = std::accumulate(C.begin(), C.end(), 0LL);
    return area >= static_cast<int64_t>(votes_left) * M;
  };

  int lo = 0, hi = (int)A.size() - 1;
  while (lo < hi) {
    int mid = (lo + hi + 1) / 2;
    if (can(mid)) {
