template <int mod> 
long long fast_pow(long long x, int deg)
{
	long long ans = 1, y = x;
	while (deg)
	{
		if (deg & 1)
			ans = ans * y % mod;

		deg >>= 1; 
		y = y * y % mod;
	}

	return ans; 
}

