	int curr_v = v, curr_p = p-1; 
	curr_v--;

	int cnt_greater = 0;
	for (int i = 1; i <= n; i++)
		if (a[i] > curr)
			cnt_greater++;

		if (cnt_greater >= p)
			return false;

    curr_p -= cnt_greater;
