#include <bits/stdc++.h>
using namespace std;
const int maxn = 100100;
long long mint[maxn<<2], maxt[maxn<<2], sum[maxn<<2], lazy[maxn<<2];
void push(int id, int l, int r){
	if(lazy[id]){
		mint[id] += lazy[id];
		maxt[id] += lazy[id];
		sum[id] += (r - l + 1) * lazy[id];
		if(l != r){
			lazy[id<<1] += lazy[id];
			lazy[id<<1|1] += lazy[id];
		}
		lazy[id] = 0;
	}
}
void add(int id, int l, int r, int x, int y, long long t){
	push(id, l, r);
	if(l > y || r < x) return;
	if(x <= l && r <= y){
		lazy[id] += t;
		push(id, l, r);
		return;
	}
	int mid = (l + r)>>1;
	add(id<<1, l, mid, x, y, t);
	add(id<<1|1, mid + 1, r, x, y, t);
	mint[id] = min(mint[id<<1], mint[id<<1|1]);
	maxt[id] = max(maxt[id<<1], maxt[id<<1|1]);
	sum[id] = sum[id<<1] + sum[id<<1|1];
}
long long get(int id, int l, int r, int x, int y, int q, int R){
	push(id, l, r);
	if(l > y || r < x) return 0ll;
	if(x <= l && r <= y){
		if(R - mint[id] <= q){
			return 1ll * (r - l + 1) * R - sum[id];
		}
		if(R - maxt[id] >= q){
			return 1ll * (r - l + 1) * q;
		}
	}
	int mid = (l + r) >> 1;
	return get(id<<1, l, mid, x, y, q, R) + get(id<<1|1, mid + 1, r, x, y, q, R);
}
int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int n, m, v, P; cin >> n >> m >> v >> P;
	vector<int> a(n);
	for(int i = 0; i < n; i++) cin >> a[i];
	sort(a.rbegin(), a.rend());
	int p = -1;
	int ans = 0;
	vector<long long> acc(n + 1, 0ll);
	for(int i = 0; i < n; i++) acc[i + 1] = acc[i] + a[i];
	for(int i = 0; i < n; i++){
		while(p + 1 < i && a[p + 1] - a[i] > m) p++;
		if(i) add(1, 0, n, 0, i - 1, a[i - 1] - a[i]);
		int np = max(p, P - 2);
		int cast = np + 1 + n - i;
		if(cast >= v){
			if(np + 2 <= P){
				ans++;
			}
		} else {
			long long to_do = 1ll * (v - cast) * m;
			int l = np + 1, r = i - 1;
			long long h = acc[r + 1] - acc[l];
			if(l <= r && 1ll * (r - l + 1) * (a[i] + m) - h >= to_do) {
				if(np + 2 <= P){
					ans++;
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

