		totalM = totalM - dist;
		pPos++;
	}

	return true;
}

long long doSearch(long long left, long long right) {
//	long long n = szA;
	long long head = left;
	long long tail = right;
	long long result = -1;
	long long mid;

	while (head <= tail)
	{
		mid = (head + tail) / 2;
		if (check(mid))
		{
			result = mid;
			head = mid + 1;			
		}
		else
		{
			tail  = mid - 1;			
		}
	}

	return result;
}

