using namespace std;

bool check(ll mid, ll arr[], ll n, ll m, ll v, ll p)
{
    //cout<<"at "<<mid+1<<"\n";
    ll maxi = arr[mid] + m;
    ll cnt = 0;
    rep(n)  
        if(arr[i]>maxi)
            cnt++;
    //cout<<"cnt = "<<cnt<<'\n';        
    if(cnt>=p)
        return 0;
    ll cnt1 = mid;
    if(cnt1+cnt>=v-1)
        return 1;
    ll pex = p-1-cnt;
    ll temp1 = 0;
    for(ll i=mid+1;i<n;i++)
    {
        if(arr[i] == arr[mid])
            temp1++;
    }

    if(cnt1+cnt+temp1 >= v-1)
        return 1;
    ll vextra = v-cnt1-cnt-temp1-1;        

    ll si = mid+temp1+1;
    ll ei = n-1-cnt;

   // cout<<"si = "<<si<<" and ri = "<<ei<<"\n";

    if(ei-si+1<=pex)
        return 1;
    multiset<ll,greater<ll>> ms;
    ll tot = m*vextra;
    for(ll i=si;i<=ei;i++)
    {
        tot-=maxi-arr[i];
        ms.insert(max(0ll,m-maxi+arr[i]));
    }

    if(tot<=0)
        return 1;
    ll fcnt = 0;
    while(tot>0)
    {
        tot-=*ms.begin();
        fcnt++;
        ms.erase(ms.begin());
    }

    if(fcnt>pex)
        return 0;
    return 1;    
}

