using namespace std;

int main() {
  int n, m, v, p;
  cin >> n >> m >> v >> p;
  vector<int> a(n);
  for (int i = 0; i < m; i++) {
    cin >> a.at(i);
  }
  int ans = 0;
  for (int i = 0; i < n; i++) {
    int border = a.at(i) + v;
    int point = m * (v-1);
    bool flag = false;

    vector<int> exa;
    for (int j = 0; j < n; j++) {
      if (i == j) continue;
      else {
        exa.push_back(a.at(j));
      }
    }

    int count_over = 0;
    for (int x: exa) {
      if (x > border) count_over++;
    }

    if (p > count_over) { // 範囲内
      point -= count_over * v; // 前に割り振る
      if (point <= 0) {
        ans++;
        continue; // 次の大ループへ
      }
      else { // 後ろにpointを割り振る
        for (int x: exa) {
          if (x < border) {
            point -= border - x;
          }
          else {
            continue; // 小ループ
          }
        }
        if (point < 0) {
          flag = true;
        }
        if (flag) { // flag遷移先
          continue;
        }
        count_over += point;
        if (count_over >= p) continue;
        else {
          ans++;
          continue;
        }
      }
    }
    else { // 範囲外
      continue;
    }
  }

  cout << ans << endl;
}

