bool chk(ll lim) {
    rep(i, 1, n) a[i] = b[i];
    ll vv = v, pos;
    pos = 1;
    while (pos <= p - 1 && vv) {
        a[pos] += m; --vv, ++pos;
    }
    pos = lim;
    while (pos <= n && vv) {
        a[pos] += m; --vv, ++pos;
    }
    if (!vv) {
        return a[lim] >= a[p];
    }
    ll rest = 1ll * vv * m;
    rep(i, p, lim - 1) {
        ll t = a[lim] - a[i];
        if (t < 0) return 0;
        t = min(t, rest);
        rest -= t;
        if (!rest) return 1;
    } return 0;
}

