  rep(i,n) sum[i+1]=sum[i]+a[i];

  // rep(i,n) cout<<a[i]<<' ';
  // cout<<endl;

  ll ng=0, ok=n-1;
  while(abs(ok-ng)>1){
    ll mid=(ok+ng)/2;
    if(isOk(mid)) ok=mid;
    else ng=mid;
  }
  ll ans=n-ok;

  cout<<ans<<endl;
}

