int okcnt;
int smallercnt; 

bool chk(int mid)
{
	int maxscore=scores[mid]+m;

	if(maxscore<okscore)return 0;

	ll leftvote=m*v*1ll;
	ll voteLargescore=okcnt*m*1ll;

	leftvote-=voteLargescore;

	for(int i=1;i<=smallercnt;i++)
	{
		int maxvote=max(0,maxscore-scores[i]);

		leftvote-=min(m,maxvote);
	}

	return (leftvote<=0);
}

