bool is_pos(vector<ll> A,int mid){
    if(A[mid]+M<border) return false;
    ll score=A[mid]+M;

    ll sum=M*(V-P);
    //cout<<mid<<", "<<score<<", "<<sum<<endl;
    for(int i=0;i<=N-P;++i){
        if(i==mid) continue;
        sum-=min(M,score-A[i]);
        if(sum<=0) return true;
    }
    return false;
}

