#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int N, V, P;
ll M;

bool solve(int i, vector<ll> &A) {
    ll r = M * (V - P);
    ll x = A[i] + M;
    if (x < A[P - 1]) return false;
    for (int j = P - 1; j < N; j++) {
        if (j == i) continue;
        r -= min(x - A[j], M);
        if (r <= 0) return true;
    }
    return false;
}

int binary_search(int ok, int ng, vector<ll> &A) {
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        if (solve(mid, A)) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    return ok;
}

int solve(vector<ll> &A) {
    int res;
    if (V < P) {
        for (int i = N - 1; i >= P; i--) {
            if (A[i] + M >= A[P - 1]) return i + 1;
        }
        return P;
    } else {
        return binary_search(P - 1, N, A) + 1;
    }
}

int main() {
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    sort(A.begin(), A.end(), greater<ll>());
    cout << solve(A) << endl;
    return 0;
}

