#include <bits/stdc++.h>

using namespace std;

/*
a_0 a_1 ... a_{n-1}
wlog assume that
a_0 >= a_1 >= ... >= a_{n-1}
a_0, ..., a_{p-1} all have a chances obviously.

Now take a_i with i >= p.


Then we can look at:

a_{p-1}, a_{p+1}, ..., a_{i-1}

We can give one to all of a_0, ..., a_{p-2} and all of a_{i+1}, ... , a_{n-1} in each round. And of course i.
That is p-1 + n-i-1 + 1 = p + n - i - 1 in total. So:
Case (1): p + n - i - 1 >= v. Then we just check if a_i + m >= a_{p-1}.

Now assume that p + n - i - 1< v. Then say that alpha = v - (p + n - i - 1) is the number of votes we need to give to a_{p-1}, ..., a_{i-1} in each round.
We assume that a_i + m >= a_{p-1} since otherwise it becomes trivial: it is not possible. The total number of votes we can afford to give to these members is:
\sum_{j={p-1}}^{i-1} (a_i + m) - a_j = (i-p+1) * (a_i + m) - A_i + A_{p-1} where A_j = a_1 + ... + a_{j-1}
So now we just check if (i-p+1) * (a_i + m) - A_i + A_{p-1} >= alpha * m or not.
Remember to calculate with long longs since A_j can be approx 10^18.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    long long n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<long long> as(n);
    for (auto& a : as) {
        cin >> a;
    }
    sort(as.begin(), as.end(), [](int i, int j) { return i > j; });
    vector<long long> As(n+1, 0);
    for (int i = 0; i < n; ++i) {
        As[i+1] = As[i] + as[i];
    }
    long long count = 0;
    for (int i = 0; i < n; ++i) {
        if (i < p) {
            ++count;
            continue;
        }
        if (as[i] + m < as[p-1]) {
            continue;
        }
        long long alpha = v - (p + n - i - 1);
        if (alpha <= 0) {
            ++count;
            continue;
        }
        // Now we know that alpha > 0 and a[i] + m >= a[p-1]
        long long beta = (i-p+1) * (as[i] + m) - As[i] + As[p-1];
        if (beta >= alpha * m) {
            ++count;
        }
    }
    cout << count << endl;
    return 0;
}

