bool isOK(int param,int v,int m,int p,vector<int> a){
    if(a.end()-lower_bound(a.begin(),a.end(),param)<=p)return true;
    int memo=a.end()-upper_bound(a.begin(),a.end(),param+m);
    v-=memo;
    int cnt=0;
    int e=upper_bound(a.begin(),a.end(),param+m)-a.begin();
    bool b=false;
    rep(i,e){
        cnt+=min(m,m+param-a[i]);
    }
    bool be=cnt>=v*m,c=a.size()-e+max(0ll,v*m-cnt-1)/m+1<p,d=a.size()-e<=p;
    return (cnt>=v*m||a.size()-e+max(0ll,(v*m-cnt-1)/m+1)<p)&&a.size()-e<=p;
}
int binarySearch(const vector<int>& a,int v,int m,int p,int ok,int ng){
    while(abs(ng-ok)>1){
        int mid=(ng+ok)/2;
        if(isOK(mid,v,m,p,a))ok=mid;
        else ng=mid;
    }
    return ok;
}
