bool check(long long x){
	v=v-(n-x);
	long long lastn=m*v-m,bgt=0,sum=0;
	v=v+(n-x);
	vector<long long>vv;
	for(int i=1;i<x;i++)
		if(a[x]+m<a[i])
		{
			bgt++;
			if(bgt>=p)
				return 0;
			lastn-=m;
		}
		else
			vv.push_back(a[i]);
	if(lastn<=0)return 1;
	sort(vv.begin(),vv.end(),cmp);
	for(int i=0;i<p-1-bgt;i++)
		sum+=m;
	for(int i=p-bgt;i<vv.size();i++)sum+=(m-vv[i]+a[x]);
	if(sum>=lastn)return 1;
	return 0;
}
