    long long border = A[P - 1];
    long long not_border_count = 0;
    long long count = 0;
    for (long long i = 0; i < N;i++) {
        if(A[i] > border) {
            count++;
            not_border_count++;
        }
        else if(A[i] == border) {
            count++;
        }
        else {
            break;
        }
