int n, m, v, p;
bool check(vi a, int pos) {
    vpi kek(n);
    for (int i = 0; i < a.size(); i++) {
        kek[i] = {a[i], i};
    }
    int cnt = (v - 1) * m;
    kek[pos].first += m;
    vector <int> us(n);
    int ans = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (kek[i].first <= kek[pos].first)
            continue;
        us[i] = m;
        ans++;
        cnt -= m;
    }
    if (ans > p) {
        return false;
    }
    for (int i = 0; i < n; i++) {
        if (kek[i].first > kek[pos].first || pos == i)
            continue;
        int y = min(min(kek[pos].first - kek[i].first, m), cnt);
        us[i] = y;
        cnt -= y;
    }
    vi lol;
    for (int i = 0; i < n; i++) {
        if (i == pos || cnt == 0) {
            continue;
        }
        if (us[i] != m) {
            lol.push_back(us[i]);
        }
    }
    sort(RALL(lol));
    for (int i = 0; i < lol.size(); i++) {
        if (cnt == 0)
            break;
        int y = min(m - us[i], cnt);
        cnt -= y;
        ans++;
    }
    if (ans > p)
        return false;

    return true;
}

