    cin >> n >> m >> v >> p;
    vi a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    sort(RALL(a));

    int l = -1, r = n;
    while (l + 1 < r) {
        int mid = l + r >> 1;
        if (check(a, mid))
            l = mid;
        else
            r = mid;
    }

    cout << l + 1;
}

