bool judge(int mid){
    //printf("hello %lld\n",mid);
    if(mid<=p)return true;
    if(a[mid]+m<a[p])return false;
    if(v<=p-1&&a[mid]+m>=a[p])return true;
    int temp=(p-1)*m;
    //给开头的p-1个元素加值
    int inx=n,cnt=v-p+1;
    //给后面的元素加值
    while(inx>mid&&cnt>1){
        temp+=m;
        inx--;
        cnt--;
    }
    temp+=m;
    int now=a[mid]+m;
    int res=m*v-temp;
    //中间还能被填多少
    for(int i=p+1;i<mid;i++){
        int add=min(m,min(now-a[i],res));
        res-=add;
        temp+=add;
    }
    if(temp<m*v){
        return false;
    }
    //printf("debug %lld %lld\n",mid,temp);
    return true;
}
