			LL cnt = 0;
			// plasMされないところの最大
			int pos_npm = n - other - 1;
			//F以下になってほしい数
			int s_cnt = (n - p) - PM + 1;
			// F以下の最大
			int pos = Upper(a, F) - 1;
			// F以下の数
			int cnt_f = pos > pos_npm ? pos_npm - i : max(0, pos - i);
			//残り
			int rem = 0;

			// p <= pos_npm //
			cnt += cnt_f;
			rem += (F - 1) * cnt_f - cul(i + 1, i + 1 + cnt_f);

			// p > pos_npm       //
			// plas M されている  //

			auto need = [&](int pos_) {
				int size = pos_ - pos_npm;
				return cul(pos_npm + 1, pos_npm + 1 + size) + m * size  // sum
					- F * size;
			};

			int res = -1;
			if (need(pos_npm + 1) > rem) {
				res = 0;
			} else if (need(n - 1) <= rem) {
				res = n - 1 - pos_npm;
			} else {
				int left = pos_npm + 1, right = n - 1;
				while (right - left > 1) {
					int mid = (left + right) / 2;
					if (need(mid) <= rem) {
						left = mid;
					} else {
						right = mid;
					}
				}
				res = left;
			}
			cnt += (res - pos_npm);


			//dump(i, s_cnt, cnt);

			if (s_cnt <= cnt) {
				ans++;
			}
		}
	}

	out(ans);
}

