bool ok(int c){
	// can c go through?
	assert(c > p); // if c <= p it's trivial to get it through
	int remain = max(0, v - p); // first vote for top (p-1) and self
	// assume tie break by index for now
	int compete = max(0, remain - (n - c)); // then vote for those behind
	int a_new = a[c] + m; // all m judges vote for me!
	long long remain_votes = 1LL * compete * m;
	for(int i = p; i < c; i++){
		if(a_new < a[i]){
			return false;
		}
		remain_votes -= (a_new - a[i]);
	}
	return (remain_votes <= 0);
}

