ll N, M, V, P;
map<ll, ll> mp1, mp2;

bool judge(ll pos, vector<ll> &A){
	if(N-pos<=P){
		return true;
	}else{
		ll X = A[pos];
		ll shita_kazu = mp2[X];
		ll Y = X + M;
		ll nokori = max(V - shita_kazu, 0ll);
		nokori = max(nokori - (P-1), 0ll);

		if(Y<A[N-P]){
			return false;
		}else{
			ll cum = 0;
			for(int i=pos+1;i<=N-P;i++){
				cum += min(Y-A[i], M);
			}
			if(nokori*M <= cum) return true;
			else return false;
		}
	}
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    REP(i, N) cin >> A[i];
    sort(A.begin(), A.end());

    REP(i, N) mp1[A[i]]++;
    ll cum = 0;
    for(auto x: mp1){
    	cum += x.second;
    	mp2[x.first] = cum;
    }

    ll lb = -1;
    ll ub = N;
    while(ub-lb>1){
    	ll mid = (ub+lb)/2;
    	if(judge(mid, A)) ub = mid;
    	else lb = mid;
    }
    cout << N - ub << endl;
    return 0;
}

