template <class T> bool checkmin(T &a,T b){return b<a ? a=b,1 : 0;}
const int N=200005;
int n,m,v,p;
int a[N],sum[N];
void init()
{
    read(n); read(m); read(v); read(p);
    for (int i=1;i<=n;++i)
    {
    	read(a[i]);
	}
	sort(a+1,a+n+1);
	reverse(a+1,a+n+1);
	for (int i=1;i<=n;++i)
	{
		sum[i]=sum[i-1]+a[i];
	}
}

bool check(int x)
{
	if (a[x]+m<a[p]) return 0;
	return m*v<=(p-1)*m+(n-x+1)*m-(sum[x-1]-sum[p-1])+(x-p)*(a[x]+m);
}

void solve()
{
	int l=p,r=n,mid,best=p;
	while (l<=r)
	{
		mid=(l+r)>>1;
		if (check(mid))
		{
			best=mid;
			l=mid+1;
		}
		else r=mid-1;
	}
	printf("%lld\n",best);
}

#undef int
int main()
{
	init();
	solve();
    return 0;
}

