int main() {
  ll N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  rep(i, N) cin >> A[i];

  sort(rall(A));

  int ok = 0;
  int ng = N;

  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;

    if (mid < P) {
      cout << mid << ' ' << P << endl;
      ok = mid;
      continue;
    }

    vector<ll> a = A;
    ll cnt = V * M;
    REP(i, mid, N) {
      if (cnt <= 0) break;
      cnt -= M;
      a[i] += M;
