    REP(i, P - 1, mid) if (a[i] > a[mid]) flg = false;
    if (!flg) {
      ng = mid;
      continue;
    }

    REP(i, P - 1, mid) {
      if (cnt <= 0) break;
      cnt -= (a[mid] - a[i]);
    }

    if (cnt > 0)
      ng = mid;
    else
      ok = mid;
  }

