#define ll long long
const int N = 1e5 +5;
ll a[N];
ll b[N];
bool ok(ll x,ll m,ll v,ll p,ll n){
    if(a[x] + m < a[p]) return 0;
    if(v <=p - 1 && a[x] + m >= a[p]) return 1;
    memcpy(b,a,sizeof a);

    for(int i = x;i <= n;++i){
        if(!v) break;
        b[i] += m;
        v --;
    }
    for(int i = 1;i <= p-1;++i){
        if(!v) break;
        b[i] += m;
        v --;
    }
    ll d = v * m;
    for(int i = p;i < x;++i) {
        if(!d) break;
        b[i] += d / (x - p);
    }
    if(d){
        d %= (x - p);
        for(int i = x-1;i >= p;--i){
            if(!d) break;
            b[i] ++;
            d --;
        }
    }
    for(int i = p;i < x;++i){
        if(b[i] > b[x]) return 0; 
    }
    return 1;
}
int main()
{
    //freopen("in.txt","r",stdin);
    //freopen("out.txt","w",stdout);
	ll n,m,v,p;
	cin >> n >> m >> v>>p;
	for(int i = 1;i <= n;++i){
		cin >> a[i];
	}
    sort(a + 1,a + n + 1,greater<ll>());
    int l = p ,r = n;
    while(l < r){
        int mid = l + r + 1 >> 1;
        if(ok(mid,m,v,p,n)) l = mid;
        else r = mid - 1;
    }
    cout<<l;

    return 0;


}

