inline int Get(vector < int > X , int t) {
   // each time take t numbers and redice them by 1 , X is sorted
   if(t <= 0)
      return inf;
   long long le = 0 , ri = 1e15;
   int sz = X.size();
   while(ri - le > 1) {
      long long mid = ((le + ri) >> 1);
      long long low = mid , high = 0 , val_low = 0;
      for(int i = sz - 1;i >= 0;-- i) {
         long long x = X[i];
         x = min(x , mid);
         if(low > x) {
            low -= x;
            high += x;
         } else {
            x -= low;
            high = mid;
            ++ val_low;
            swap(low , high);
            low -= x;
            high += x;
         }
      }
      //cout << mid << ' ' << val_low << endl;
      if(val_low >= t)
         le = mid;
      else
         ri = mid;
   }
   return le;
}
int32_t main() {
   //cout << Get({1 , 2 , 10} , 3);
   scanf("%lld %lld %lld %lld" , & n , & m , & v , & p);
   for(int i = 1;i <= n;++ i)
      scanf("%lld" , a + i);
   sort(a + 1 , a + 1 + n);
   int le = 0 , ri = n;
   while(ri - le > 1) {
      int mid = ((le + ri) >> 1);
      if(a[n - p + 1] > a[mid] + m) {
         le = mid;
         continue ;
      }
      vector < int > X;
      int new_v = v - mid - (p - 1);
      for(int i = mid + 1;i <= n - p + 1;++ i)
         X.push_back(a[mid] + m - a[i]);

      if(Get(X , new_v) >= m)
         ri = mid;
      else
         le = mid;
   }
   printf("%lld\n" , n - le);
   return 0;
}

