#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define ALL(x) std::begin(x), std::end(x)
using namespace std;
template <class T, class U> inline void chmax(T & a, U const & b) { a = max<T>(a, b); }

template <typename UnaryPredicate>
int64_t binsearch(int64_t l, int64_t r, UnaryPredicate p) {
    assert (l <= r);
    -- l;
    while (r - l > 1) {
        int64_t m = l + (r - l) / 2;
        (p(m) ? r : l) = m;
    }
    return r;
}

int64_t solve(int64_t n, int64_t m, int64_t v, int64_t p, vector<int64_t> a) {
    sort(ALL(a));
    int k = binsearch(0, n, [&](int j) {
        int64_t limit = a[j] + m;
        int64_t votes = m * (v - 1);
        int failure = 0;
        REP (i, n) if (i != j) {
            int64_t residual = limit - a[i];
            if (residual < 0) {
                ++ failure;
            } else {
                votes -= min(m, residual);
            }
        }
        if (votes > 0) {
            chmax(failure, (votes + m - 1) / m);
        }
        return failure < p;
    });
    return n - k;
}

int main() {
    int64_t n, m, v, p; cin >> n >> m >> v >> p;
    vector<int64_t> a(n);
    REP (i, n) {
        cin >> a[i];
    }
    cout << solve(n, m, v, p, a) << endl;
    return 0;
}

