bool IsValid(const int N, const int M, const int V, const int P,
	     const vector<int> &A, int i) {
  if (A[P - 1] <= A[i] + M) {
    int sum = 0;
    for (int j = P - 1; j < i; ++j) {
      sum += (A[i] + M) - A[j];
    }
    int X = P - 1;
    int Y = N - 1 - i;
    if (M * (V - (X + Y + 1)) < sum) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

int main() {
  int N, M, V, P;
  cin >> N >> M >> V >> P;

  vector<int> A(N);
  for (int i = 0; i < N; ++i) {
    cin >> A[i];
  }

  sort(A.begin(), A.end());
  reverse(A.begin(), A.end());

  if (IsValid(N, M, V, P, A, N - 1)) {
    cout << N << endl;
    return 0;
  }

  int p = 0;
  int q = N - 1;

  while (p + 1 < q) {
    int m = (p + q) / 2;
    if (IsValid(N, M, V, P, A, m)) {
      p = m;
    } else {
      q = m;
    }
  }

  cout << p + 1 << endl;
  return 0;
}

