static void exec()
{
	int N;
	getint(N);
	LLONG M;
	getint(M);
	int V, P;
	getint(V, P);

	std::vector<LLONG> ai(N);
	for (int i = 0; i < N; i++) {
		getint(ai[i]);
	}
	std::sort(ai.begin(), ai.end(), std::greater<LLONG>());

	int ans = 0;
	int start = 0, base = 0;
	int noAdd = N - V;
	if (noAdd >= P) {
		base = P - 1;
		start = P;
		ans = P;

		for (int i = start; i < N; i++) {
			if (ai[base] <= ai[i] + M) {
				ans++;
			}
			else {
				break;
			}
		}
	}
	else {
		base = N - V - 1;
		start = N - V;
		ans = N - V;

		int count = 0;
		LLONG bfr = 0;
		for (int i = start; i < N; i++) {
			if (count <= P - (N - V)) {
				count++;
			}
			else if (((count <= P) || (bfr == ai[i])) && (ai[base] <= ai[i] + M)) {
				count++;
			}
			else {
				break;
			}
			bfr = ai[i];
		}
		ans += count;
	}

	printf("%d\n", ans);
}

