vector<int> pv;

bool ps(int pi)
{
	pv.clear();
	for (int i = 0; i < n && pv.size() < p; i++) {
		if (i == pi) continue;
		int t = a[pi] + m - a[i];
		if (t < 0) return false;
		pv.push_back(t);
	}
	long long s = 0;
	for (int i = 0; i < pv.size(); i++) 
		s += min(pv[i], m);
	s += 1LL * (n - p) * m;
	return (s >= 1LL * m * v);
}

int bs(int s, int e)
{
	int md = (s + e) / 2;
	if (s >= e) return md;
	if (ps(md)) bs(s, md);
	else bs(md + 1, e);
}

