using namespace std;
using ll = long long;

bool check(vector<ll>& A,  ll N, ll M, ll V, ll P, int pos)
{
    // first, make A[pos] high
    ll base = A[pos] + M;
    if (A[P-1]>base) return false;

    // get left votes
    if (V<=(N-pos)+(P-1)) return true;
    queue<ll> que;
    rep(i, 0, V-(N-pos)-(P-1))
        que.push(M);

    // voting with greedy
    --pos;
    while (que.size()>0 and P-1<=pos)
    {
        ll now = que.front();
        que.pop();
        ll cap = base-A[pos];

        if (cap<=0) return false;
        if (cap<now) que.push(now-cap);

        --pos;
    }
    return que.size()==0;
}


int main()
{
    // read input
    ll N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    rep(i, 0, N)  cin >> A[i];

    // rsort
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());

    // binary search    
    ll low = 0;
    ll high = N-1;
    while (low<high)
    {
        ll mid = (low+high+1)/2;
        // check
        bool is_ok = check(A, N, M, V, P, mid);

        if (is_ok)
            low = mid;
        else
            high = mid-1;
    }
    cout << low+1 << endl;
    return 0;
}

