bool search(int idx){
    int free = (P-1) + (N-idx);
    int rem = V - free;
    ll sup = A[idx] + M;
    if(sup < A[P-1])
        return false;
    ll num = rem * M;

    for(int i = P-1; i < idx; i++){
        ll a = A[i];
        ll sub = 0;
        chmax(sub, min(M, sup - a));
        num -= sub;
    }

    if(num <= 0) return true;
    else return false;
}

