    }
    bool be=cnt>=v*m,c=a.size()-e+max(0ll,v*m-cnt-1)/m+1<p,d=a.size()-e<=p;
    return (cnt>=v*m||a.size()-e+max(0ll,v*m-cnt-1)/m+1<p)&&a.size()-e<p;
