using ll = long long;

int main() {
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<ll> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a.at(i);
    }

    sort(a.begin(), a.end());
    //for_each(a.begin(), a.end(), [](int v){cout << v << " ";}); cout << endl;

    vector<ll> a_of(n);
    for (int i = 0; i < n; i++) {
        a_of.at(i) = a.at(i);
    }

    auto is_ok = [&](int idx){
        ll sum = m * v;
        vector<pair<ll, int>> b(n);
        for (int i = 0; i < n; i++) {
            b.at(i) = make_pair(a.at(i), i);
        }
        b.at(idx).first += m;
        sum -= m;

        sort(b.begin(), b.end());

        int next_idx = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (b.at(i).first == a.at(idx) + m) {
                next_idx = i;
                break;
            }
        }

        for (int i = next_idx + 1; i < n; i++) {
            ll d = min(m, sum);
            b.at(i).first += d;
            sum -= d;
        }

        for (int i = 0; i < next_idx; i++) {
            ll d = min(sum, min(m, b.at(next_idx).first - b.at(i).first));
            b.at(i).first += d;
            sum -= d;
        }

        for (int i = next_idx - 1; i >= 0; i--) {
            ll d = min(m - (b.at(i).first - a_of.at(b.at(i).second)), sum);
            b.at(i).first += d;
            sum -= d;
        }

        sort(b.begin(), b.end());
        //for_each(b.begin(), b.end(), [](int v){cout << v << " ";}); cout << endl;

        int cnt = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (b.at(i).first == a.at(idx) + m) break;
            cnt++;
        }

        return cnt + 1 <= p;
    };

    int ng = -1;
    int ok = (int)a.size();

    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (is_ok(mid)) {
            ok = mid;
            //cout << "true: " << mid << endl;
        }
        else {
            ng = mid;
            //cout << "false: " << mid << endl;
        }
    }
    cout << n - ok << endl;
}

