lint n, m, v, p;
vector<lint> a(0, 0LL);
bool check(int i) {
  vector<lint> b(n, 0ll);
  rep(i, n) { b[i] = a[i]; }
  lint vv = v;
  b[i] += m;
  vv--;
  lint tmp = b[i];
  sort(all(b));
  int idx;
  for (lint i = n - 1; 0 <= i; i--) {
    if (b[i] == tmp) {
      idx = i;
      break;
    }
  }
  lint right = n - (idx + 1);
  lint left  = idx;
  if (right >= vv) {
    rep(i, vv) { b[idx + 1 + i] += m; }
  } else {
    rep(i, right) { b[idx + 1 + i] += m; }
    vv -= right;
    rep(i, vv) { b[i] += m; }
  }
  sort(all(b));
  reverse(all(b));
  bool ok = false;
  for (int i = 0; i < p; i++) {
    if (b[i] == tmp) {
      ok = true;
      break;
    }
  }
  return ok;
}
