        questions.at(i) = A;
    }
    sort(questions.begin(), questions.end(), greater<ll>());
    vector<ll> ruisekiPoint(N + 1);
    for(ll i = 0; i < N; i++){
        ruisekiPoint.at(i + 1) += ruisekiPoint.at(i) + questions.at(i);
    }
    ll answer = P;
    for(ll i = P; i < N; i++){
        ll remainV = max((V - (P - 1) - (N - i)), (ll)0);
        ll remainScore = remainV * M;
        ll borderPoint = questions.at(P - 1);
        //先にボーダーの右側の追い越し対象にPと同じ値まで均等に振る
        remainScore -= borderPoint * (i - P) - (ruisekiPoint.at(i) - ruisekiPoint.at(P));
        //余りが残ったらボーダーを含めてなるべく均等に振る
        if(remainScore > 0){
            borderPoint += remainScore / (i - P + 1);
            if (remainScore % (i - P + 1)){
                borderPoint++;
            }
        }
        ll currentMaxPoint = questions.at(i) + M;
        if(borderPoint <= currentMaxPoint){
            answer++;
        }
    }
    cout << answer << endl;
    return 0;
}

