		//~ reverse(all(zz));
		int tot=v2*m;
		vi used;
		for(auto i:zz){
			if(tot>b[mid]-b[i]){
				used.pb(b[mid]-b[i]);
				tot-=b[mid]-b[i];
				b[i]=b[mid];
			}
			else{
