// i番目の問題が採用されうるか否かを調べる
// 入れても構わない表の総数がmv以上になるかどうかを調べよ
bool isOK(int i, vector<long long> &a, long long n, long long m, long long v, int p){

    // はじめから上位p以内ならば無条件で採用される
    if (n - i <= p) return true;

    // 入れられても構わない表の総数 >= mv かどうかを調べる
    long long comparison = m * v;

    long long res = 0;

    rep(j, n){

        if (a[j] <= a[i]) res += m; //a[i]以下の値ならば, m個入れ込んでOk
        else if (n - m <= j) res += m; //上位1, 2, ,,,p-1個にもm個入れ込んでOK
        else{
            res  = res + (a[i] + m - a[j]); //入れられても問題ない個数の上限である
        }
    }

    if (res >= comparison) return true; //ここの理屈はeditorial pdfに丁寧に書いてある.
    else return false;

}


int main(){
    long long n, m, v, p;
    cin >> n >> m >> v >> p;

    vector<long long> a(n);
    rep(i, n) cin >> a[i];

    sort(a.begin(), a.end());

    // 昇順ソートがポイントである
    // a[i] が採用されるならば, a[i+1],,,も採用される
    // 単調性がある
    // binary_serchである
    // めぐる式のアイデアを利用する

    int ng = -1; //絶対に条件を満たさない
    int ok = n; //条件を満たす最小のインデックスを表す

    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;

        if (isOK(mid, a, n, m, v, p)) ok = mid;
        else ng = mid;

        //cout << ng << " " <<  ok << endl;
    }

    int ans = n - ok; // okは0-indexベースで返されることに注意せよ
    cout << ans << endl;
}

