struct RangeAddQuery {
	int n;
	vector<int> d;
	RangeAddQuery(int m) {
		for (n = 1; n < m; n *= 2);
		d.assign(n * 2, 0);
	}
	void add(int l, int r, int x) {
		for (; l && l + (l&-l) <= r; l += l & -l)
			d[(n + l) / (l&-l)] += x;
		for (; l < r; r -= r & -r)
			d[(n + r) / (r&-r) - 1] += x;
	}
	int get(int i) {
		int ret = d[n + i];
		for (int j = (n + i) / 2; j > 0; j >>= 1)
			ret += d[j];
		return ret;
	}
	void output() {
		rep(i, 0, n) {
			cerr << get(i) << " ";
		}
		cerr << endl;
	}
};

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int N, M, V, P; cin >> N >> M >> V >> P;
	vector<int> A(N); rep(i, 0, N) {
		cin >> A[i];
	}
	sort(all(A));

	map<int, int> cnt;
	rep(i, 0, N) {
		cnt[A[i]]++;
	}
	dump(cnt);

	map<int, int> sum = cnt;
	rep(i, 0, N - 1) {
		if (A[i + 1] == A[i])continue;
		sum[A[i + 1]] += sum[A[i]];
	}
	dump(sum);

	auto f = [&](int x) {
		if (x >= N - P)return true;

		RangeAddQuery raq(N);

		rep(i, 0, N) {
			raq.add(i, i + 1, A[i]);
		}

		int y = x + 1;
		int m = M;
		while (y < N && A[x] == raq.get(y)) {
			y++;
		}
		while (m) {
			int Y = raq.get(y) - A[x];
			raq.add(y, min(y + (N - V), N), -min(Y, m));
			m -= min(Y, m);

			while (y < N && A[x] == raq.get(y)) {
				y++;
			}
			if (y == N)
				return true;
		}

		if (raq.get(N - P) == A[x]) {
			return true;
		}

		return false;
	};
	auto binarySearch = [&](int ng, int ok) {
		if (f(ng))return ng;
		while (ng + 1 < ok) {
			int m = (ng + ok) / 2;
			if (f(m))
				ok = m;
			else
				ng = m;
		}
		return ok;
	};

	int ans = N - binarySearch(0, N);

	cout << ans << endl;
	return 0;
}

