bool check(int k){
	ll cnt=0;
	for(int i=0; i<k; i++){
		cnt+=c[i];
	}
	if(cnt<=p-1) return true;
	cnt=p-1;
	for(int i=k; i<n1; i++){
		cnt+=c[i];
	}
	ll v1=max(0ll, v-cnt);
	vector<ll> va;
	for(int i=0; i<k; i++){
		for(int j=0; j<c[i]; j++) va.push_back(a1[i]);
	}
	vector<ll> x;
	for(int i=p; i<va.size(); i++) x.push_back(a1[k]+m-va[i]);
	ll s=0;
	for(int i=0; i<x.size(); i++){
		x[i]=min(x[i], m);
		s+=x[i];
	}
	if(s>=v1*m) return true;
	else return false;
}
