typedef long long ll;

vector<ll> T;
ll l, size;

void Stworz(ll n)
{
    ll p = 1;
    while (p < n)
        p *= 2;
    l = p;
    size = 2 * p - 1;
    for (int i = 0; i <= size; ++i)
        T.push_back(0);
}

void Dodaj(ll a, ll b, ll x)
{
    a += l;
    b += l;
    T[a] += x;
    if (b != a)
        T[b] += x;
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            T[a + 1] += x;
        if (b % 2 == 1)
            T[b - 1] += x;
        a /= 2;
        b /= 2;
    }
}

ll Daj(ll a)
{
    a += l;
    ll s = 0;
    while (a != 0)
    {
        s += T[a];
        a /= 2;
    }
    return s;
}

bool Ok(vector<ll> a, ll m, ll v, ll p, ll nr)
{
    ll stara = a[nr];
    a[nr] += m;
    ll nowa = a[nr];
    sort(a.begin(), a.end());
    reverse(a.begin(), a.end());
    nr = 0;
    while (a[nr] != nowa)
        ++nr;
    if (nr + 1 > p)
        return false;
    v -= p;
    for (int i = 0; i < a.size(); ++i)
        if (a[i] < stara)
            --v;
    if (v <= 0)
        return true;
    vector<ll> r;
    for (int i = p; i < a.size(); ++i)
        if (a[i] >= stara)
            r.push_back(nowa - a[i]);
    if ((ll) r.size() < v)
        return false;
    Stworz(r.size());
    for (int i = 0; i < r.size(); ++i)
        Dodaj(i, i, r[i]);
    ll ileMaks = 0;
    for (ll i = 0; i + v <= (ll) r.size(); ++i)
    {
        ll il = Daj(i);
        if (il > 0)
        {
            Dodaj(i, i + v - 1, -il);
            ileMaks += il;
        }
    }
    return ileMaks >= m;
}

