		{
			border = sorted[N - V + P];
		}
		count = P;
		for (ll i = P; i < N; ++i)
		{
			if (target - sorted[i] <= M && sorted[i] >= border)
			{
				++count;
			}
		}
	}

	cout << count << endl;

	return 0;
}

