void solve() {
    for (int i = 0; i < maxn; ++i) ans[i] = '#';     
    cin >> n >> m >> t;
    if (t == 1) exit(1); 
    if (n == 2) {
        cout << -1; 
        return; 
    }    
    for (int i = 0; i < m; ++i) {
        int a, b; cin >> a >> b, --a, --b; 
        gr[a].insert(b);
        gr[b].insert(a); 
        E[{a, b}] = i; 
        E[{b, a}] = i; 
        edge.eb(a, b);         
    }
    solve1();  
    map<pii, int> last; 
    int A = edge.back().ff;      
    int B = edge.back().ss; 
    int T = -1; 
    bool fl = false; 
    for (auto v : edge) {
//        if (v == mp(min(A, B), max(A, B))) exit(1); 
//        cerr << A << " " << B << endl; 
        ++T; 
        if (ans[T] != '#') {
            A = to(A, v, ans[T]);
            B = to(B, v, ans[T]);
            continue;     
        }
        if (last.count(v)) {            
            ans[T] = ans[last[v]]; 
            continue; 
        }
        if (last.count(mp(v.ss, v.ff))) {
            swap(v.ff, v.ss); 
            ans[T] = ans[last[v]]; 
            continue;             
        }
        if (A != v.ff && A != v.ss && B != v.ff && B != v.ss) {
            ans[T] = 'v'; 
            last[v] = ans[T]; 
            continue; 
        }
        if (fl) {
            ans[T] = in(A, B, v); 
            last[v] = ans[T]; 
            continue; 
        } 
        fl = true; 
        if (A != v.ff && A != v.ss) {
            swap(A, B); 
        }
        int to = v.ff ^ v.ss ^ A; 
        ans[T] = in(A, v); 
        last[v] = ans[T]; 
        ans[E[{to, B}]] = dir(B, to); 
        last[{to, B}] = dir(B, to); 
        ans[E[{A, B}]] = dir(A, B); 
        last[{A, B}] = dir(A, B); 
    }
//    cerr << A << " " << B << endl; 
    for (int i = 0; i < m; ++i) cout << ans[i]; 
}                                

