        cin >> A[i];
    }
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());
    ll l = P - 1;
    ll r = N;
    while (r - l > 1) {
        ll mid = (l + r) / 2;
        if (bin(mid)) {
            l = mid;
        } else {
            r = mid;
        }
    }
    cout << l + 1 << endl;
    return 0;
}

