void smain() {
    int n;
    ll m, v;
    int p;
    cin >> n >> m >> v >> p;
    vl a(n);
    fori (i, n) {
        cin >> a[i];
    }

    sort(ALL(a));

    vl pref(n);
    pref[0] = a[0];
    for (int i = 1; i < n; ++i) {
        pref[i] = pref[i - 1] + a[i];
    }

    auto get = [&] (int l, int r) -> ll {
        if (l > r)
            return 0;
        return pref[r] - (l ? pref[l - 1] : 0);
    };

    ll ans = p - 1;
    v -= p;
    for (int i = 0; i < n - p + 1; ++i) {
        ll cur = a[i] + m;
        if (cur < a[n - p])
            continue;

        ll sum = i * m + cur * (n - p - i) - get(i + 1, n - p);
        if (sum >= v * m) {
            ans++;
        }
    }
    cout << ans;
}

