bool solve(LL &t, VLL a, LL &n, LL &m, LL &v, LL &p) {
    a[t] += m;
    LL rem = m * (v-1);
    REP(i,0,p-1) {
        if (rem == 0) break;
        a[n-1-i] += m;
        rem -= m;
    }

    REP(i,0,t) {
        rem -= m;
        a[i] += m;
    }
    //if (rem <= 0) return true;
    REP(i,t+1,n-p) {
        if (rem <= 0) {
            while (i < n && a[i] <= a[t]) ++i;
            return n - i + 1 <= p;
        }
        LL diff = max(0LL, min(rem, a[t] - a[i]));
        //dump(diff);
        rem -= diff;
        a[i] += diff;
    }
    //dump(rem);

    return rem <= 0;
}

long long meguru_bin(VLL &a, LL &n, LL &m, LL &v, LL &p) {
    long long ok = n;
    long long ng = -1;

    while (abs(ok - ng) > 1) {
        long long mid = ng + (ok - ng) / 2;
        //dump(mid);
        if (solve(mid,a,n,m,v,p)) ok = mid;
        else ng = mid;
    }
    //dump(ok);
    return ok;
}

