class seg {
public:
    int l, r,v;
    bool operator < (const seg&x) const {
        if(l == x.l) return r < x.r;
        return l < x.l;
    }
};

set<seg>::iterator split(set<seg> &S, int p) { //
    auto it = S.upper_bound(seg{p,int(2e9)});
    if(it == S.begin()) return it;
    --it;
    if(it->r <= p) return ++it;
    int l = it->l, r = it->r,v = it->v;
    S.erase(it), S.insert({l, p,v});
    return S.insert({p+1, r,v}).first;
}

void cal(set<seg> &S, seg c) {
    split(S, c.r);
    auto it = split(S, c.l-1);
    auto it2 = it;
    for(; it2 != S.end() && it2->r <= c.r; ++it2);
    S.erase(it, it2);
    S.insert(c);
}

