bool ok(ll k){
    ll b[100010]={},c[100010]={};
    rep(i,n) b[i]=a[i],c[i]=a[i];
    // reverse(c,c+n);
    // ll s=lower_bound(c,c+n,b[p-1])-c-1;
    // s=n-1-s;
    /*
    if(k<s){
        // cout<<"11111"<<endl;
        return true;
    }
    */
    if(k<p) return true;
    ll t=n-k;
    ll N=k;
    ll V=v-t;
    if(V<=0){
        ll cnt=0;
        rep(i,k){
            if(a[i]>b[k]+m) cnt++;
        }
        if(cnt<p) return true;
        else return false;
    }
    if(N<=V) return false;
    ll d[100010]={};
    rep(i,N){
        d[i]=b[k]+m-b[i];
    }
    SegmentTree sg(N);
    rep(i,N){
        sg.update(i,i+1,0,d[i],0,N);
    }
    ll cnt=0;
    rep(i,N-V+1){
        ll Q=sg.query(i);
        if(Q>0){
            sg.update(i,i+V,0,-Q,0,N);
            cnt+=Q;
        }
    }
    sg.update(N-V,N,0,-(m-cnt),0,N);
    cnt=0;
    rep(i,N){
        if(sg.query(i)<0) cnt++;
        // cerr<<sg.query(i)<<" ";
    }
    if(cnt<p){
        return true;
    }
    else return false;
}




