	for (int i{1}; i < N; i++)
		sum[i] += sum[i - 1];
	int ok{N - 1}, ng{-1};
	while (ok - ng > 1)
	{
		int mid{(ok + ng) >> 1};
		if (N - mid <= P)
			ok = mid;
		else if (A[mid] + M < A[N - P])
			ng = mid;
		else
		{
			int64_t rest{M * (V - 1)};
			for (int i{N - 1}; i > mid && rest > 0; i--)
			{
				if (i > N - P) rest -= M;
				else rest -= A[mid] + M - A[i];
			}
			for (int i{}; i < mid && rest > 0; i++)
				rest -= M;
			if (rest <= 0) ok = mid;
			else ng = mid;
		}
	}
	printf("%d\n", N - ok);

