int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL);
    cin >> n >> m >> v >> p;

    rep(i, 0, n) {
        cin >> a[i];
    }

    sort(a, a+n);

    pre[0] = a[0];
    rep(i, 1, n) {
        pre[i] = pre[i-1] + a[i];
    }

    int ans = 0;

    rep(i, 0, n) {
        int lastSame = upper_bound(a+i+1, a+n, a[i]) - a - 1;
        if (n-lastSame <= p) {
            ans++;
            continue;
        }
        int t = max(0, v - (lastSame+1)); // v is at least 1 in the Problem

        if (!t) {
            int last = upper_bound(a+lastSame+1, a+n, a[i]+m) - a - 1;
            if (n-last <= p)
                ans++;
        }
        else {
            int last = upper_bound(a+lastSame+1, a+n, a[i]+m) - a - 1;
            int rank = n-last;

            int range = last - (lastSame+1) + 1;
            ll s = sum(lastSame+1, last);
            ll target = (ll) (a[i]+m) * range - s;
            ll votingPower = (ll) t * m;
            if (target >= votingPower) {
                ans++;
            }
            else {
                if ((votingPower - target + m-1) / m + rank <= p) {
                    ans++;
                }
            }
        }
    }

    cout << ans << '\n';

    return 0;
}

