main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, m, k, p;
	cin >> n >> m >> k >> p;

	vector <int> v(n);

	for(auto& i : v)
		cin >> i;

	sort(v.begin(), v.end(), [] (const int &x, const int &y) { return x >= y; });

	int l = 0;
	int r = n - 1;

	int ans = 0;

	auto check = [&] (int x)
	{
		if(x < p)
			return true;

		if(v[x] + m < v[p - 1])
			return false;

		if(k <= p)
			return true;

		int cnt = 0;

		for(int i = max(0, p - 1); i < n; i++)
			if(i != x)
				cnt += min(m, v[x] + m - v[i]);

		return (cnt >= m * (k - p));
	};

	while(l <= r)
	{
		int mid = (l + r) / 2;

		bool ok = check(mid);

		if(ok == true)
		{
			l = mid + 1;
			ans = mid;
		}
		else
		{
			r = mid - 1;
		}
	}

	cout << ans + 1;
}

