#define EQ(a, b) (abs((a)-(b))<EPS)

int n;
ll m, v, p, a[125252];

bool is_ok(int mid){
  ll b[125252];
  REP(i, n){
    b[i]=a[i];
  }
  ll cnt=m*v;
  // p~mid
  if(b[p-1]-b[mid]>m){
    return false;
  }
  FOR(i, p, mid+1){
    cnt-=b[p-1]-b[i];
    b[i]=b[p];
  }
  if(cnt<0){
    return false;
  }
  // 0~p-2
  REP(i, p-1){
    cnt-=m;
    b[i]+=m;
  }
  if(cnt<=0){
    return true;
  }
  // mid+1~n-1
  FOR(i, mid+1, n){
    cnt-=min(b[p-1]-b[i], (ll)m);
    b[i]=min(b[p-1], b[i]+m);
  }
  if(cnt<=0){
    return true;
  }
  // cntを余らせる
  ll tmp=cnt;
  if(b[mid]+tmp/(mid-(p-1)+1)<=a[mid]+m){
    tmp%=(mid-(p-1)+1);
    FOR(i, mid+1, n){
      if(b[i]-a[i]<m){
        tmp-=a[i]+m-b[i];
      }
    }
    if(tmp<=0){
      return true;
    }
  }
  // 余らせない
  tmp=cnt/(mid-(p-1)+1)+1;
  if(b[mid]+tmp<=a[mid]+m){
    cnt-=(cnt/(mid-(p-1)+1)+1)*(mid-(p-1)+1);
    cnt=-cnt;
    b[p-1]+=tmp;
    REP(i, p-1){
      cnt-=min(b[i]-b[p-1], (ll)m);
    }
    if(cnt<=0){
      return true;
    }
    FOR(i, mid+1, n){
      cnt-=b[i]-a[i];
    }
    if(cnt<=0){
      return true;
    }
  }
  return false;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  // cout<<setprecision(10)<<fixed;
  cin>>n>>m>>v>>p;
  REP(i, n){
    cin>>a[i];
  }
  sort(a, a+n, greater<int>());
  int lb=p-1, ub=n;
  while(ub-lb>1){
    int mid=(lb+ub)/2;
    if(is_ok(mid)){
      lb=mid;
    }
    else{
      ub=mid;
    }
  }
  cout<<lb+1<<'\n';
  return 0;
}

