typedef long long int64;

const int MAXN = 100000 + 10;

int n, m, v, p;
int a[MAXN], id[MAXN];

bool cmp(int x, int y) { return a[x] < a[y]; }

bool judge(int k) {
	int i, overcnt = 0, v0, x, t;
	int64 sum = 0;

	x = a[k] + m;

	for(i=1; i<=n; i++)
		if(a[i] > x)
			overcnt++;
	if(overcnt >= p)
		return false;

	v0 = v - m - 1;
	t = n - p + 1;
	for(i=1; i<=t; i++) {
		if(a[id[i]] <= x) {
			if(id[i] == k) {
				t++;
				continue;
			}
			sum += std::min(x - a[id[i]], m);
		}
	}
	return sum >= 1ll * v0 * m;
}

int main() {
	int i, l, r, mid;
	int ans=0;

	scanf("%d %d %d %d", &n, &m, &v, &p);
