bool check(int x)
{
	//cout<<a[x]<<" "<<k<<" "<<tt<<endl;
	if(x<=p) return 1;
	int rest=v-(p-1)-(n-x+1);
	if(rest<0) rest=0;
	int choose=n-(p-1)-(n-x+1);
	int Sum=0;
	for(int i=1;i<=choose;i++) t[i]=a[i+p-1]-a[x],Sum+=t[i];
	//cout<<rest<<endl; for(int i=1;i<=choose;i++) cout<<t[i]<<" "; cout<<endl; cout<<endl;
	if(a[x]+m<a[p]) return 0;
	return Sum<=m*(choose-rest);
}

