bool calc(ll n, ll m, ll v, ll p, ll *a, ll mid){
    ll fm = a[mid] + m;
    ll allselect = m * (v-p+1LL);

    rep(i, n-(p-1LL)){
        if(fm-a[i] <= 0LL)continue;
        allselect -= (min(fm-a[i], m));
    }

    if(allselect <= 0LL)return true;
    return false;
}

