const int N = 100005;

int n, m, v, p;
int dat[N];

bool can(int idx) {
	int rem = n-v;
	for (int pos = idx+1; pos < n; pos++) {
		int tmp = dat[pos] + (pos-rem-idx);
		if (dat[idx] + m < tmp) {
			// printf("pos = %d\n", pos);
			return (n-(pos-1) <= p);
		}
	}
	return true;
}

int main() {
	scanf("%d %d %d %d", &n, &m, &v, &p);
	for (int i = 0; i < n; i++) {
		scanf("%d", &dat[i]);
	}
	sort(dat, dat+n);
	int lo = 0, hi = n-1;
	int res;
	while (lo <= hi) {
		int mid = (lo+hi) >> 1;
		// printf("mid = %d\n", mid);
		if (can(mid)) {
			res = mid;
			hi = mid - 1;
		}
		else {
			lo = mid + 1;
		}
	}
	printf("%d\n", n-res);
	return 0;
}

