bool judge(ll n, ll person_cnt, ll select_cnt, ll border,
           const V<ll> &alist, ll idx)
{
    if (idx < border) return true;

    ll ceil = alist[idx] + person_cnt;
    srep (i, border-1, idx) if (alist[i] > ceil) return false;

    select_cnt -= (border-1);
    select_cnt -= (n-idx);
    if (select_cnt <= 0) return true;

    ll remain = select_cnt * person_cnt;

    srep (i, border-1, idx) {
        remain -= (ceil-alist[i]);
    }
    return (remain <= 0LL);
}

