    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    ll person_cnt; llin(person_cnt);
    ll select_cnt; llin(select_cnt);
    ll border; llin(border);
    V<ll> alist; llina(alist, n);

    sort_reverse(alist);

    ll left = 0;
    ll right = n-1;
    ll now = (left + right) / 2LL;
    ll maxidx = 0;

    for ( ; left <= right; now = (left + right) / 2LL) {
        if (judge(n, person_cnt, select_cnt, border, alist, now)) {
            maxidx = max(maxidx, now);
            left = now + 1LL;
        }
        else right = now - 1LL;
    }

    cout << maxidx + 1LL << endl;
}

