int main(){
	int N,V,P;
	long long M;
	cin >> N >> M >> V >> P;
	vector<long long> A(N);
	for(auto &i:A)cin >> i;

	sort(A.begin(),A.end(),greater<long long>());
	int ok=-1,ng=N;
	while(abs(ok-ng)>1){
		//printf("ok=%d,ng=%d\n",ok,ng);
		int mid=(ok+ng)/2;
		if(mid<P){
			ok=mid;
			continue;
		}
		if(A[mid]+M<A[P-1]){
			ng=mid;
			continue;
		}
		vector<long long> add(N,0);
		long long score=A[mid]+M;
		add[mid]=M;
		long long c=M*(V-1);
		for(int i=N-1;i>=0;i--){
			if(i==mid)continue;
			if(c<=0)break;
			if(A[i]<score){
				c-=min(score-A[i],M);
				add[i]=min(score-A[i],M);
			}
			else break;
		}
		for(int i=0;i<P;i++){
			if(c<=0)break;
			c-=M-add[i];
			add[i]=M;
		}

		if(A[P-1]+add[P-1]<=score)ok=mid;
		else ng=mid;
	}
	//printf("ok=%d,ng=%d\n",ok,ng);
