const ll L = 1e5+5;

bool can(ll index, basic_string <ll> a, ll n, ll m, ll v, ll p)
{
    if(v < p)
    {
        if(a[index] + m >= a[n-p])
        {
            return true;
        }

        return false;
    }

    ll voted = m;

    for(ll i=0; i<n; i++)
    {
        if(i == index)
        {
            continue;
        }

        if(i > n - p)
        {
            voted += m;
        }

        else if(a[i] > a[index] + m)
        {
            return false;
        }

        else
        {
            voted += max(0LL, min(m, a[index] + m - a[i]));
        }
    }

    return (voted >= m*v);
}

void solve()
{
    ll n = nxt(), m = nxt(), v = nxt(), p = nxt();
    basic_string <ll> a(n, 0);
    generate(all(a), nxt);
    sort(all(a));

    ll low = 0, high = n;
    ll ans = -1;

    while(low <= high)
    {
        ll mid = low + (high - low)/2;

        if(can(mid, a, n, m, v, p))
        {
            ans = mid;
            high = mid-1;
        }

        else
        {
            low = mid + 1;
        }
    }

    assert(ans != -1);

    cout << n - ans << endl;
}

