bool isok(ll mid){
  if(mid < P) return true;
  // 当該問題の最高スコア
  ll maxi = A[mid]+M; if(maxi < A[P-1]) return false; //到達できないので
  ll V_ = V;// M人が残りV_ 問に投票
  V_--;// 自分には投票するので
  V_ -= (P-1); // 超上位には投票しておけばいいので
  V_ -= (N-mid-1); // 下位のものにも投票してよいので
  if(V_<=0) return true; // 投票先残ってないならええやろ

  ll M_ = M; // V_問を残りM_回の投票
  ll counter = 0;
  // 投票先はA[P]からA[mid-1]まで
  for(ll i=P; i<mid; i++){
    counter += maxi-A[i];
  }

  if(counter >= M_*V_) return true;
  else return false;
}

ll binsch(){
  ll ng = N;
  ll ok = P-1;
  while(abs(ok-ng)>1){
    ll mid = (ok+ng)/2;
    if(isok(mid)) ok = mid;
    else ng = mid;
  }
  return ok;
}

