bool judge_bigger(int x,int p,vint A,int m,int n,int v){
  if(x < p) return true;
  int key = A[x] + m;
  if(A[p-1] > key) return false;
  int sum = 0;
  sum += (p-1)*m;
  sum += (n-x)*m;
  rep(i,p-1,x){
    sum += min(m,key-A[i]);
  }
  return sum >= v*m;
}

