bool solve(vector<pair<long long,int>> a,int idx)
{
    long long now=a[idx].first+m; //height of my index
    long long sum=m*v-m; //how many votes left
    vector<long long> up(n,m); //how much more can you raise it
    up[idx]=0;
    for(int i=0;i<n;i++)
    {
        if(a[i].first<=now)
        {
            long long t=min(min(sum,m),min(now-a[i].first,up[a[i].second]));
            a[i].first+=t;
            sum-=t;
            up[a[i].second]-=t;
        }
        else
        {
            long long t=min(min(sum,m),up[a[i].second]);
            a[i].first+=t;
            sum-=t;
            up[a[i].second]-=t;
        }
    }
    vector<pair<long long,int>> b; //up[i],i
    for(int i=0;i<n;i++)
    {
        if(a[i].first==now&&a[i].second!=idx) b.push_back({up[a[i].second],i});
    }
    sort(b.begin(),b.end(),greater<pair<long long,int>>());
    for(pair<long long,int> c:b)
    {
        long long t=min(min(sum,m),c.first);
        sum-=t;
        a[c.second].first+=t;
        up[a[c.second].second]-=t;
    }
    int cnt=0;
    for(int i=0;i<n;i++) if(a[i].first>now) cnt++;
    return (cnt<p);
}

