    for (int i = 0; i < n; ++i) {
      cin >> a[i];
    }
    sort(a.begin(), a.end());
    int lb = -1, ub = n - 1;
    while (ub - lb > 1) {
      int mid = (lb + ub) / 2;
      if (selected(mid)) {
        ub = mid;
      } else {
        lb = mid;
      }
    }
    cout << n - ub << endl;
  }
  bool selected(int x) {
    DBG(x, a)
    LL th = a[x] + m;
    LL rem = m * (v - 1);
    int pos = n - 1;
    int cnt = 0;
    DBG(pos, th, rem)
    while (pos >= 0 && cnt < p - 1) {
      if (pos == x) {
        pos--;
        continue;
      }
      rem -= m;
      if (a[pos] + m > th) cnt++;
      pos--;
    }
    DBG(pos, rem, cnt)

    for (; pos >= 0; --pos) {
      if (pos == x) {
        pos--;
      }
      if (a[pos] > th) return false;
      rem -= min(m, th - a[pos]);
    }
    DBG(rem)
    return rem <= 0;
  }
};
