bool fc(vector<int> &a, int m, int v, int p, int mid){
  int n = a.size();
  ll add = (ll)m;
  ll top = a.at(mid) + add;
  ll sum = 0;
  int tc = 0;
  rep(i, n){
    if(i == mid) continue;
    if(top < a.at(i)) tc++;
    else sum += top - a.at(i);
  }
  // cerr << top << " "  << sum << " " << (ll)(v-1)*m << " " << tc << " " << p << endl;
  if(tc >= p) return false;
  int nt = p - tc;
  ll ex = (ll)(max(0, v-p))*m;
  sum -= ex;
  sum -= nt;
  return sum > 0;
}

