int N, M, V, P, A[101010];

bool check(int i) {
    int bigger = 0, less = 0;
    ll other = 0;
    for (int j = 0; j < N; j++) {
        if (j != i) {
            if (A[i] + M < A[j]) bigger++;
            else if (A[j] <= A[i]) less++;
            else other++;
        }
    }

    if (P <= bigger) return false;

    ll rest = V - 1 - bigger - less;
    if (rest <= 0) return true;

    ll tot = 0;
    ll cnt = 0;
    for (int j = 0; j < N; j++) {
        if (A[i] < A[j] and A[j] <= A[i] + M) {
            tot += A[i] + M - A[j];

            cnt++;
            ll ok = min({tot / M, other, rest});
            ll ng = rest - ok;
            if (bigger + ng < P and cnt + ng <= other) {
                return true;
            }
        }
    }

    return false;
}

int main() {
    cin >> N >> M >> V >> P;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    sort(A, A + N);

    int ng = -1, ok = N;
    while(ng + 1 != ok) {
        int md = (ng + ok) / 2;
        if (check(md)) {
            ok = md;
        }
        else ng = md;
    }

    int ans = N - ok;
    cout << ans << endl;
    return 0;
}

