bool solve(int ind){
  if(A[P-1]>A[ind]+M) return 0;
  ll sum=(P+(N-ind))*M;
  for(int i=P-1;i<ind;i++) sum+=A[ind]+M-A[i];
  if(sum>=M*V) return 1;
  else return 0;
}

