void solve(std::istream &in, std::ostream &out) {
  int n,m,v,p;
  in >>n>>m>>v>>p;
  vector<int>a(n);
  for(int &i:a)in>>i;
  sort(a.rbegin(),a.rend());
  int lo = -1, hi = n;
  function<bool(int)> check=[&](int ind) {
    if (ind < p) return true;
    if (a[p - 1] > a[ind] + m) return false;
    int64_t cnt = (int64_t) m * (p - 1 + n - ind);
    for (int i = p - 1; i < ind; ++i) cnt += a[ind] + m - a[i];
    return cnt >= (int64_t) m * v;
  };
  while (hi - lo > 1) {
    int mid = lo+hi>>1;
    if (check(mid)) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  out << lo + 1 << '\n';
}

