bool fc(vector<int> &a, int m, int v, int p, int mid){
  int n = a.size();
  ll add = (ll)m;
  ll top = a.at(mid) + add;
  int tc = 0;
  vector<int> tr;
  rrep(i, n){
    if(i == mid) continue;
    if(top < a.at(i)) tc++;
    tr.push_back(a.at(i));
  }
  if(tc >= p) return false;

  ll ex = (ll)(max(0, v-p))*m;
  rep(i, n-1){
    if(i < p-1) ex -= m;
    else ex -= min(m, a.at(mid) - tr.at(i));
  }
  return ex <= 0;
}

