{
    ios_base::sync_with_stdio(0);
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<ll> a(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];
    sort(a.begin(), a.end());
    reverse(a.begin(), a.end());
    ll L = 0, P = n - 1, s, r = -1;
    while (L <= P)
    {
        s = (L + P) / 2;
        if (Ok(a, m, v, p, s))
        {
            r = s;
            L = s + 1;
        }
        else
            P = s - 1;
    }
    cout << r + 1;
    return 0;
}

