int nbProb, nbJuges, nbIncr, nbPris;
vector<int> prob;

bool peutPrendre(int indProtege)
{
	vector<int> cc = prob;
	int rst = nbPris-1;
	int lsInc = -1;
	form(i, nbProb) if (rst > 0) {
		if (i != indProtege) {
			cc[i] = BIG;
			lsInc = i;
			--rst;
		}
	}
	int resteIncr = nbIncr - nbPris;
	priority_queue<int> dispo;
	int finalProt = prob[indProtege] + nbJuges;
	if (lsInc+1 < nbProb && lsInc+1 != indProtege && prob[lsInc+1] > finalProt) return false;
	if (resteIncr <= 0) return true;

	int score = 0;
	form(i, nbProb) if (i != indProtege && cc[i] < finalProt) {
		score += min(nbJuges, finalProt - cc[i]);
	}

	return score >= nbJuges*resteIncr;
}

void solve()
{
	cin >> nbProb >> nbJuges >> nbIncr >> nbPris;
	prob.resize(nbProb);
	form(i, nbProb) cin >> prob[i];
	sort(all(prob));
	reverse(all(prob));
	int lo = nbPris-1, ri = nbProb-1;
	while (lo < ri) {
		int mid = (lo+ri+1)/2;
		if (peutPrendre(mid)) lo = mid;
		else ri = mid-1;
	}
	cout << lo+1 << "\n";
}

