#define N_MAX 100000
#define MOD 1000000007

int N, M, V, P;
int table[N_MAX];
bool func(int index)
{
	if (table[index] + M < table[N - P]){
		return false;
	}

	int vote = V - P;
	if (vote <= index){
		return true;
	}

	vote -= index;
	lli sum = 0;
	for (int i = index + 1; i <= N - P; i++){
		if (table[index] + M - table[i] <= 0){
			break;
		}
		sum += (lli)min(M, table[index] + M - table[i]);
	}

	return sum >= (lli)vote*(lli)M;
}

void solv()
{
	scanf("%d%d%d%d", &N, &M, &V, &P);
	for (int i = 0; i < N; i++){
		int A; scanf("%d", &A);
		table[i] = A;
	}

	sort(table, table + N);

	if (P >= V){
		for (int i = 0; i < N; i++){
			if (table[i] + M >= table[N - P]){
				printf("%d", N - i);
				break;
			}
		}
	}
	else{
		int left = 0, right = N - 1;
		while (right - left>1){
			int mid = (left + right) / 2;
			if (func(mid)){
				right = mid;
			}
			else{
				left = mid;
			}
		}
		if (func(left)){
			right = left;
		}
		printf("%d", N - right);
	}

	return;
}

