typedef long long ll;
#define REP(i,n) for(int i=0;i<(int)(n);i++)

int judge(ll* a, ll num, ll add, ll max, ll m){
    //printf("###%lld %lld %lld %lld\n",num, add, max, m);
    if(num<=0)return 1;
    if(add<=0){
        if(a[num-1]<=max)return 1;
        else return 0;
    }
    ll b[100005]={};
    REP(i,num){
        b[i]=a[i];
    }
    REP(i,add){
        b[i] = b[i]+m;
    }
    //REP(i,num)printf("##%d##\n",b[i]);

    ll sum[100005]={};
    for(int i=num-1;i>=0;i--){
        sum[i]=sum[i+1]+b[i];
        //printf("####%d####\n",sum[i]);
    }
    ll h=-1;
    for(int i=add-2;i>=0;i--){
        if(sum[i+1]/(num-1-i)>=b[i]){
            h=sum[i+1]/(num-1-i) + (sum[i+1]%(num-1-i)!=0);
            break;
        }
    }
    if(h==-1){
        h=sum[0]/num + (sum[0]%num!=0);
    }
    if(h>max)return 0;
    else return 1;
}

int main(){
    ll n,m,v,p;
    ll a[100005]={};
    scanf("%lld%lld%lld%lld",&n,&m,&v,&p);
    REP(i,n)scanf("%lld",&a[i]);
    sort(a,a+n);
    ll now = n/2;
    ll s=0;
    ll g=n;
    while(1==1){
        int flag = judge(a+now+1, n-p-now, v-p-now, a[now]+m, m);
        //printf("%lld %lld\n",now, flag);
        //printf("%d %d %d\n",s,g,now);
        if(s+1==g){
            if(flag)break;
            else{
                now=now+1;
                break;
            }
        }
        if(flag){
            g=now;
            now = (s+g)/2;
        }
        else{
            s=now;
            now = (s+g)/2;
        }
    }
    printf("%lld\n",n-now);
    return 0;
}

