llong n, m, v, p, b[MXN], ans;

bool check(llong pos){
    llong left = (v - (p - 1)) * m;
    if(b[p] > b[pos] + m) return false;
    for(llong i = 1; i <= n; i++){
        if(b[i] <= b[pos]){
            left -= m;
        }
    }
    for(llong i = pos; i >= p; i--){
        if(b[pos] == b[i]) continue;
        left -= b[pos] + m - b[i];
    }
    if(left <= 0) return true;
    else return false;
}

