long long m,v,a[100100],b[100100],del[100100],cur,vote;
bool check(int x){//二分
	for(int i=1;i<=n;i++){
		b[i]=a[i];
		del[i]=0;
	}
	cur=a[x]+m;
	vote=m*v-m;
	b[x]+=m;
	int tmp=x;//交换，排序 
	while(tmp>1&&b[tmp]>b[tmp-1]){
		swap(b[tmp],b[tmp-1]);
		tmp--;
	}
	int xxx;
	for(int i=1;i<=n;i++)//找到它的位置 
		if(b[i]==cur){
			xxx=i;
			break;
		}
	xxx--;
	if(xxx>=p)
		return false;
	for(int i=n;i>xxx+1;i--){//计算：比它小的 
		long long delta=min((cur-b[i]),m);//尽力补 
		vote-=delta;
		del[i]=delta;
		b[i]+=delta;
		if(vote<=0){
			return true;//投完了 
		}
	}
	for(int i=1;i<=xxx;i++){
		vote-=m;
		b[i]+=m;
		if(vote<=0){
			return true;
		}
	}
	int fore=xxx;
	for(int i=xxx+2;i<=n;i++){
		vote-=(m-del[i]);
		if(b[i]+(m-del[i])>cur)
			fore++;
		if(vote<=0){
			if(fore<p)
				return true;
		}
	}
	return false;
}
