            in >> a[i];
        }

        sort(all(a));

        int cnt = 0;
        rep(i, n){
            if(i >= v-1){
                if(a[i] + m >= a[n - p]) cnt++;
            }else{
                if(v - 1 - i < p){
                    if(a[i] + m >= a[n - p]) cnt++;
                }else{
                    int over = v - 1 - i - (p-1);
                    int afford = n - i - 1 - (p-1); // n - i - p
                    if(a[i] + m >= a[n - p] + m*over / afford
                        && a[i] + m > a[i + (over*m)%afford] + ceill(over*m, afford)) cnt++;
                }
            }
        }

        out << cnt << endl;
	}
};


