using namespace std;

int main() {
    int64_t N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<int64_t> A(N);
    for (int64_t i = 0; i < N; i++) {
        cin >> A[i];
    }

    assert(N <= 10);

    sort(A.begin(), A.end(), greater<int64_t>());

    vector<int64_t> sum(N + 1, 0);
    for (int64_t i = 0; i < N; i++) {
        sum[i + 1] = sum[i] + A[i];
    }

    int64_t ans = 0;
    set<int64_t> ok;
    for (int64_t i = 0; i < N; i++) {
        //i番目のものが選ばれうるか

        //そもそも上位P個は大丈夫
        if (i < P) {
            ans++;
            ok.insert(A[i]);
            continue;
        }

        //最適な割り振りは「上位P - 1個まで + 自分より下位」に選ぶ
        //余ったやつが問題
        int64_t rem_vote = V - (P - 1) - (N - i);

        if (rem_vote <= 0) {
            //届くかどうか
            if (A[i] + M >= A[P - 1]) {
                ok.insert(A[i]);
                ans++;
            }
            continue;
        }

        //rem_voteがM回発生する
        //それを[P - 1, i)までに割り振ることになる
        //j in [P - 1, i)としてA[j]が受け取れる回数はM + A[i] - A[j]
        //これの和なのでnum * (M + A[i]) - sum[P-1 ~ i)_A
        int64_t num = i - (P - 1);

        int64_t capacity = num * (M + A[i]) - sum[i] + sum[P - 1];
        if (capacity >= rem_vote * M) {
            ans++;
        }
    }

    cout << ans << endl;
}

