ll power(ll x, ll y, ll m=mod)
{
	if(y<0)
    {
		x = power(x,m-2);
		y = -y;
	}
	ll ans=1;
	x = x % m;
	while(y)
    {
		if(y&1) ans = (ans*x)%m;
		y=y/2;
		x=(x*x)%m;
	}
	return ans;
}

bool poss(ll c, ll arr[],ll pos,ll v, ll m, ll n, ll p)
{
    ll i, cnt = m*v,k=0;
    ll left[n];
    lp(i,0,n)
    {
        left[i] = m;
    }
    for(i=n-c;arr[i]<=pos;i++)
    {
        if(arr[i]<pos)
        {
            if((pos-arr[i])<=m)
            {
                cnt = cnt- (pos-arr[i]);
                left[i] = m-(pos-arr[i]);
            }
            else
            {
                return 0;
            }
        }
        k++;
        if(cnt<0)
        {
            return 0;
        }
    }
    if(cnt==0)
    {
        return 1;
    }
    ll sumc = 0,sl=0;
    lp(i,0,n-c)
    {
        sumc += min(m,pos-arr[i]);
        left[i] = m - min(m,pos-arr[i]);
        sl += left[i];
    }
    if(cnt>0)
    {
        ll min = left[n-c];
        ll sum=0,sumi=0;
        lp(i,n-p+1,n)
        {
            if(arr[i]>=(pos+min))
            {
                sumi += 0;
            }
            else
            {
                sumi = pos+min-arr[i];
            }
            sum +=m;    
        }
        if(cnt<sum+sumc)
        {
            return 1;
        }
        if(cnt>=(min)&& cnt<=(k*min+sumc+sum+sl))
        {
            return 1;
        }
        else
        {
            return 0;
        }        
    }
}

