	ll n,m,v,p,i;
    cin >> n >> m >> v >> p;
    ll arr[n];
    lp(i,0,n)
    {
        cin >> arr[i];
    }
    sort(arr,arr+n);
    ll pos = arr[n-p];
    ll min = p, max = n,avg,res=p;
    while(min<=max)
    {
        avg = min + (max-min)/2;
        if(poss(avg,arr,pos,v,m,n,p))
        {
            res = avg;
            min = avg+1;
        }
        else
        {
            max = avg-1;
        }        
    }
    lp(i,res,n)
    {
        if(arr[i]==arr[res])
        {
            res++;
        }
        else
        {
            break;
        }

    }
    cout << res << "\n";
	return 0;
}

