bool ok(int el){
    while(a[el]==a[el+1] && el<n) el++;
    if(el>=n-p+1LL && el<=n) return true;
    if(el+p-1LL>=v){
        if(a[n-p+1]-a[el]<=m) return true;
        else return false;
    }
    else{
        int tz=m*(v-(el+p-1LL));
        int sum=0LL;
        for(int i=el+1;i<=n-p+1;i++){
            sum+=(a[n-p+1]-a[i]);
        }
        tz-=sum;
        if(tz<=0LL){
            if(a[n-p+1]-a[el]<=m) return true;
            else return false;
        }
        int pop=(n-p+1LL-el);
        a[n-p+1]+=((tz-1LL)/pop+1LL);
        if(a[n-p+1]-a[el]<=m) return true;
        else return false;
    }

}

