int n,m,v,p;
int a[N],sum[N];
bool check(int x){
	int num=n-p+1;
	return m*v<=(p-1)*m+x*m+(a[x]+m)*(num-x)-(sum[num]-sum[x]);
}
signed main() {
	scanf("%lld%lld%lld%lld",&n,&m,&v,&p);
	for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
