    int N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<int> A(N);
    rep(i, N) cin >> A[i];
    sort(A.begin(), A.end());

    //! Binary search. (l, r]
    int l = -1;
    int r = N-1;

    int debug = 0;
    while (debug < 5 && 1 < r-l) {
        ++debug;
        int m = (r+l) / 2;

        if (N-m <= P) {
            //! m is already in top P before adding points
            r = m;
            // cout << "N-m <= P, setting m to r" << endl;
        } else {
            // cout << "P < N-m" << endl;
            int maxM = A[m]+M; //! the max points that m can take
            //! the best case for m is to distribute all points to low score problems in greedy way
            int remaining = max(0, V-m-1) * M;

            //! distribute points to top (P-1) problems
            remaining -= (P-1) * M;
            remaining = max(0, remaining);

            // cout << "maxM, remaining = " << maxM << ' ' << remaining << endl;

            bool ok = true;
            for (int i = N-P; ok && m < i; --i) {
                if (maxM < A[i]) {
                    ok = false;
                } else {
                    remaining -= min(M, maxM-A[i]);
                    remaining = max(0, remaining);
                }
            }
            if (0 < remaining) {
                // cout << "ok = false, because 0 < remaining" << endl; 
                ok = false;
            }

            if (ok) {
                r = m;
            } else {
                l = m;
            }
        }
        // cout << "BOTTOM l , r = " << l << ' ' << r << endl;
    }

    cout << (N-r) << endl;

    return 0;
}

