bool check(ll A)
{
	while(A>0&&a[A]==a[A-1])A--;
	if(A<=p-1)return true;
	ll g=0;
	ll h=(p-1+n-A);
	if(h>=v)
        return true;
    ll rest=m*(v-h);
	g+=(p-1+n-A)*m;
	for(ll i=p-1;i<A;i++)
		{
		ll tp=min(a[A]+m-a[i],min(m,rest));
		if(a[i]+tp>a[A]+m)return false;
		rest-=tp;
		}
	return rest==0;
}
