  rrep(i, 1, n) sum[i] += sum[i - 1];
  rrep(i, n - p, n) { mp[a[i]] = 1; }
  rrrep(i, n - p - 1, 0LL) {
    ll ju = m * v, af = a[i], cost;
    af += m;
    ju -= m;
    ju -= (p - 1) * m;
    ju -= i * m;
    ju = max(ju, 0LL);
    cost = sum[n - p];
    cost -= sum[i];
    k = (n - p) - i;
    tmp = ((cost + ju) % k == 0 ? (cost + ju) / k : (cost + ju) / k + 1);
    tmp = max(tmp, a[n - p]);
    if (af >= tmp) mp[a[i]] = 1;
  }
  rep(i, n) {
    if (mp[a[i]]) ans++;
  }
  Cout(ans);
  return 0;
}

