// f2 a[b]~a[c] を m * t 使って k 以下にできるか
bool f2(ll b, ll c, ll t, ll k) {
    ll s = (ll)t * m;
    for (ll i = b; i <= c; i++) {
        if (k - a[i] < 0) return false;
        s -= min(m, k - a[i]);
    }
    return s <= 0;
}

// a[k] がいけるか
// k = 5, v = 2, p = 2, m = 1, n = 6
bool f1(ll k) {
    if (p >= k) {
        return true;
    }
    else if (a[k] + m < a[p-1]) {
        return false;
    }
    else if (v - (n - k + p - 1) < 0 && a[p] <= a[k] + m) {
        return true;
    }
    else {
        ll t = v - (n - k + p - 1);
        if (f2(p - 1, k - 1, t, a[k] + m)) {
            return true;
        }
    }
    return false;
}

