int isOk(long long n,long long m,long long v,long long p,long long k){
    long long sum = v*m;
    long long minus = min(sum,(n-k+1)*m);
    sum -= minus;
    long long my = a[k] + m;
    int ok = 1;
    for(int i = 1; i <= k-1; i++){
        if(i<=(p-1)){
            long long add = min(sum,m);
            sum -= add;
        }
        else{
            if(a[i]>my){
                ok = 0;
                break;
            }
            else{
                long long add = min(sum,my-a[i]);
                sum -= add;
            }
        }
    }
    if(ok==0 || sum!=0) return 0;
    return 1;
}

