bool check(int id) {
    int x = a[id];
    int sum = v * m; 
    int add = max(0ll, a[p - 1] - a[id]);
    if (add > m) return false;
    sum -= add;                                 
    x += add; 
    vector<int> upper;
    vector<int> lower;
    vector<int> eq; 
    for (int i = 0; i < n; ++i) {
        if (i == id) continue; 
        if (a[i] == x) eq.pb(m); 
        else if (a[i] > x) upper.pb(a[i]);                     
        else lower.pb(a[i]); 
    } 
    for (auto v : upper) {
        sum -= min(sum, m); 
    }
    for (auto &v : lower) {
        int pp = min(sum, x - v, m);         
        v += pp; 
        if (v == x) {                
            eq.pb(m - pp); 
        }             
        sum -= pp; 
    }
    if (sum == 0) return true; 
    sort(all(eq)); 
    int ctr = p - upper.size() - 1; 
    for (int i = 0; i < ctr; ++i) {
        if (eq.size()) {
            sum -= min(sum, eq.back());
            eq.pop_back();                         
