using namespace std;
typedef long long ll;

bool topP(vector<ll> A, ll p, ll M, ll V, ll P){
  if (p < P) return true;
  ll rem = M * V;
  ll back_n = A.size() - p;
  rem -= M * back_n;
  ll sum = 0;
  ll gt = 0;
  ll tmp = 0;
  vector<ll> B;
  for (int i=0; i<A.size(); i++){
    if (i >= p){
      B.push_back(A[i] + M);
    }
    else{
      if (i < (V - back_n)){
        B.push_back(A[i] + M);
      }
      else{
        B.push_back(A[i]);
      }
    }
  }
  ll rem2 = 0;
  for (int i=p - 1; i>(V - back_n - 1); i--){
    rem2 += max((ll)0, B[p] - B[i]);
  }
  ll p2 = (V - back_n - 1);
  while (rem2 > 0){
    if (B[p2] - A[p2] <= rem2){
      rem2 -= B[p2] - A[p2];
      B[p2] = A[p2];
      p2--;
    }
    else{
      B[p2] -= rem2;
      rem2 = 0;
    }
  }
  for (int i=0; i<A.size(); i++){
    if (B[i] > B[p]) gt++;
  }

  cerr << endl;
  cerr << "gt : " << gt << endl;
  return gt < P;
}


