  cerr << endl;
  ll lp = 0;
  ll rp = N - 1;
  ll mp = (lp + rp) / 2;
  unordered_set<ll> visited;
  while (true){
    bool can = topP(A, mp, M, V, P);
    cerr << mp << " " << can << endl;
    if (visited.find(mp) != visited.end()){
      if (!can){
        mp--;
      }
      break;
    }
    visited.insert(mp);
    if (can){
      lp = mp;
      mp = round((lp + rp) / 2.0);
    }
    else{
      rp = mp;
      mp = round((rp + lp) / 2.0);
