vector<int> A;

bool C(int X) {
  if (X <= P) {
    return true;
  }
  if (A[X] + M < A[P]) {
    return false;
  }

  int sum = 0;
  sum += M * P;
  sum += M * (N - X);
  for (int i = P; i < X; i++) {
    sum += A[X] + M - A[i];
  }

  if (sum < M * V) {
    return false;
  }

  return true;
}

