bool ok(int m) {
  vector<LL> as(A,A+N);
  int v=0;
  as[m]+=M,++v;
  REP(i,P-1) if(v<V) as[i]+=M,++v;
  int i=N-1;
  for(; i>=0&&v<V&&as[i]<=as[m]-M; --i) {
    LL x=min(as[m]-as[i],(LL)M);
    if(x>0) as[i]+=x,++v;
