    std::cin >> N >> M >> V >> P;
    std::vector< int > A(N);
    for(int i=0; i<N; i++){
        std::cin >> A[i];
    }

    std::sort(A.begin(), A.end());
    A.resize(N-P);
    long long total = A[N-P];
    long long pre = 0;
    std::vector< long long > score_diff(N-P);
    for (int i = N-P-1; i >= 0; i--){
        if(A[i] == A[i+1]){
            score_diff[i] = pre;
            total += A[i];
        }else{
            score_diff[i] = total;
            pre = total;
            total += A[i];
        }
    }

    int ans = -1;
    int same = 0;
    for (int i = 0; i < N-P; i++){
        if(A[i] == A[i+1]){
            same++;
            continue;
        }
        long long diff = A[N-P-1] - A[i];

        long long score_need = score_diff[i] - A[i] * (N-P - i);
        int V_en = N - V;
        long long cur_score_diff;
        if(V_en <= 0){
            cur_score_diff = 0;
        }else{
            cur_score_diff = score_need / V_en + (long long)(score_need % V_en != 0);
        }
        long long max = std::max(diff, cur_score_diff);
        if(max <= M){
            ans = same + N - i;
            break;
        }
        same = 0;
    }
    if(ans == -1){
        ans = P + same;
    }


    std::cout << ans << std::endl;

    return 0;
}

