signed main(){
  ll n,m,v,p; cin>>n>>m>>v>>p;
  vector<ll> a(n); rep(i,n) cin>>a[i]; sort(ALL(a));
  // vector<ll> b(n); b[0]=a[0]; reps(i,n-1) b[i]=b[i-1]+a[i];

  // ll ans = p;
  ll lim = a[n-p];

  int ng = -1, ok = n-p;
  while(ok-ng>1){
    int i = (ok+ng)/2;
    bool flg = false;

    // if(i>=n-p) flg=true; // 上からp問目までは無条件でOK

    ll tor = a[i]+m; // ボーダーライン
    ll last = v-p-i;
    if(last<=0){ // 入れたくない問題に投票されない場合
      if(tor>=lim) flg=true;
    }else{ // 入れたくない問題に投票されてしまう場合
      ll amari = last*m; // 残りの表
      // ll sa = b[n-p]-b[i];
      // ll yoyu = tor*last - sa;
      // if(amari<=yoyu) ans++;
      for(int j=i+1; j<=n-p; j++){
        amari -= llmin((tor-a[j]),m);
      }
      if(amari<=0) flg=true;
    }
    if(flg) ok=i;
    else ng=i;
  }

  cout << n-ok << endl;

  return 0;
}

