        bool use = false;
        VL over; ll overcnt = 0;
        FOR(i, 0, n) {
            if (a[i] == x && !use) {
                use = true;
                continue;
            }
            else if (y < a[i]) {
                ++overcnt;
                cnt -= m;
            }
            else if (y - a[i] < m) {
                cnt -= y - a[i];
                over.push_back(m - y + a[i]);
            }
            else cnt -= m;
        }

        rSORT(over, greater<ll>());
        for (int i = 0; i < over.size() && 0 < cnt; ++i) {
            cnt -= over[i];
            ++overcnt;
        }
        return overcnt; 
    };

    ll ok = n, ng = -1;
    while (ok - ng > 1) {
        ll mid = (ok + ng) / 2;
        if (solve(a[mid]) < p)ok = mid;
        else ng = mid;
    }

