	if(m > N) return true;

	for(int i = 0; i < m; i++){
		B[i] += M;
		sum -= M;
	}

	if(sum <= 0) return true;

	for(int i = N-1; i >= m;i--){
		if(A[i] > B[m-1]) {
			B[i] += M;
			sum -= M;
			hoge = i;
			con++;
		}
	}

	if(con >= P) return false;
	if(sum <= 0) return true;

	for(int i = m; i < hoge; i++){

		B[i] = B[m-1];
		sum -= B[m-1] - A[i];
	}

	if(sum <= 0) return true;

	for(int i = hoge-1; i >= m; i--){
		if(A[i] > A[m+1]) con++;
		sum += B[m-1] - A[i];
		sum -= M;

		if(con >= P) return false;
		if(sum <= 0) return true;
	}

	if(con >= P) return false;
	if(sum <= 0) return true;

	return false;
}

