bool IsValid(const ll N, const ll M, const ll V, const ll P,
	     const vector<ll> &A, int i) {
  if (A[P - 1] <= A[i] + M) {
    ll sum = 0;
    for (int j = P - 1; j < i; ++j) {
      sum += (A[i] + M) - A[j];
    }
    int X = P - 1;
    int Y = N - 1 - i;
    if (M * (V - (X + Y + 1)) <= sum) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

