    cout << N << endl;
    return 0;
  }

  int p = 0;
  int q = N - 1;

  while (p + 1 < q) {
    int m = (p + q) / 2;
    if (IsValid(N, M, V, P, A, m)) {
      p = m;
    } else {
      q = m;
    }
  }

  cout << p + 1 << endl;
  return 0;
}

