  for(ll i = 0; i < N; ++i){
    cin >> a[i];
    ++m[a[i]];
  }
  sort(a.rbegin(),a.rend());
  for(ll i = 0; i < N; ++i) psum[i+1] = psum[i]+a[i];
  vector<lll> keys,nans;
  for(auto& p : m) keys.push_back(p.first);
  nans.push_back(0);
  for(ll i = 0; i < keys.size(); ++i){
    nans.push_back(nans.back()+m[keys[i]]);
  }
  ll b = 0,e = keys.size()-1;
  lll ans = P;
  while(b <= e){
    ll i = (b+e)/2;
    ll key = keys[i];
    ll tot = nans[i+1];
    if(tot+P-1 >= N){
      ans = max(ans,N-nans[i]);
      e = i-1;
      continue;
    }
    if(tot+P-1 >= V){
      if(key+M >= a[P-1]){
        ans = max(ans,N-nans[i]);
        e = i-1;
        continue;
      }
