		long long can_distribute = 0;
		for(int j = 0; j < n; j++) {
			if(j == i) {
				continue;
			}
			if(j > n - min(v, p)) { // j > 4
				can_distribute += m; // 1
			}
			else if(a[j] > me) {
				return false;
			}
			else {
				can_distribute += min(m, me - a[j]);
			}
		}
		return can_distribute >= (long long) m * (v - 1);
