#include <bits/stdc++.h>
using namespace std;
const int maxn=200050;
typedef long long ll;
const ll MOD=998244353;
int a[maxn];
ll sum[maxn];
int main() {
	int n,m,v,p;
	scanf("%d%d%d%d", &n, &m, &v, &p);
	for(int i = 1; i <= n; ++i) {
		scanf("%d", a+i);
		sum[i] = sum[i-1]+a[i];
	}
	sort(a+1, a+1+n);
	for(int i = 1; i <= n; ++i) {
		sum[i] = sum[i-1]+a[i];
	}
	int ans=0;
	for(int i = 1; i <= n; ++i) {
		ll t=(ll)m*v - (ll)i*m;
		ll pos = lower_bound(a+1, a+1+n, a[i]+m+1)-a;
		if(n-pos+1>=p) continue;
		if(t<0) {
			ans++;
			continue;
		}
		if((ll)(a[i]+m)*(pos-1-i) - sum[pos-1]+sum[i] >= (ll)t) {
			ans++;
		} else {
			ll d = n-pos+1;
			t = t - ((ll)(a[i]+m)*(pos-1-i) - sum[pos-1]+sum[i]);
			if(t>=pos-1-i) d+=(pos-1-i);
			else d+=t;
			if(d<p) {
				ans++;
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

