ll m;

int check(int x){
	if(x<p) return 1;
	vl change;
	for(auto y: a) change.eb(y);
	ll t = v;
	change[x] += m;
	t--;

	if(t<=0 && change[x]>=a[p-1]) return 1;
	if(t<= 0) return 0;
	vl rid;
	f1r(i, x+1, n) {
		rid.eb(m);
		//t--;
	}
	f0r(i, p-1){
		rid.eb(m);
	}
	// [p, x-1](

	f1r(i, p-1, x){
		if(change[x]>=change[i]){
			rid.eb(min(change[x] - change[i], m));
		}
	}
	ll tot = 0;
	for(auto y: rid){
		tot += y;
	}
	if(tot>= m*t) return 1;
	return 0;

}

