	reverse(all(a));
	int l = 0;
	int r = n-1;
	while(abs(l-r)>1){
		int mid = (l+r)/2;
		int c = check(mid);
		if(c){
			l = mid;
		}
		else{
			r = mid - 1;
		}
	}
	if(l>r) swap(l, r);
	if(check(r)) ps(r+1);
