ll N, M, V, P;
vector<int> A;
vector<int> cumsum;

bool check(int i){
    ll capacity = 0;
    ll border = A[i] + M;
    for(int k=(i < P - 1 ? P : P - 1);k<N;k++){
        if(i == k) continue;
        if(A[k] > border) return false;
        capacity += min(border - A[k], M);
    }
    return (capacity >= M * (V - 1 - (P - 1)));
}

