    int val = a[ id ] + m ;
    long long sm = 0 ;
    long long lg = 0 ;
    for ( int i = n ; i >= 1 ; -- i ) {
        if ( i == id ) { continue ; }
        int aux = val - a[ i ] ;
        if ( aux < 0 ) { ++ lg ; continue ; }
        sm += min ( aux , m ) ;
    }
    sm = 1LL * m * ( cnt - 1 ) - sm ;
    long long sr = 0 ;
    for ( int i = 1 ; i <= n ; ++ i ) {
        if ( i == id ) { continue ; }
        if ( sm <= 0 ) {
            if ( a[ i ] > val ) { ++ sr ; }
            continue ;
        }
        int aux = 0 ;
        if ( a[ i ] > val ) { aux = m ; }
        else {
            aux = m - min ( val - a[ i ] , m ) ;
        }
        sm -= aux ;
        if ( aux > 0 ) { ++ sr ; }
    }
    return ( sr + 1 <= lim ) ;
}

void input ( ) {
    scanf ( "%d%d%d%d" , &n , &m , &cnt , &lim ) ;
    for ( int i = 1 ; i <= n ; ++ i ) {
