    r = n ;
    while ( r - l > 3 ) {
        mid = ( l + r ) / 2 ;
        if ( f ( mid ) == false ) { r = mid ; }
        else { l = mid ; }
    }
    while ( f ( r ) == false ) { -- r ; }
    printf ( "%d\n" , r ) ;
}


