int IsPossible(int k) {

	if (k <= 0) { return -1; }

	H.clear();

	for (int i = 1; i <= N; i++) { c[i] = 0; }

	long long int rem = M*V;
	c[k] = M; rem -= M;

	long long int tmp;

	for (int i = 1; i <= N; i++) {
		if (i == k) { continue; }

		if (i < k) { tmp = min(M, rem);  c[i] = tmp;  rem -= tmp; }
		else if ((i > k) && (W[k] + c[k] < W[i])) { tmp = min(M, rem); c[i] = tmp; rem -= tmp; }
	}

	for (int i = k + 1; i <= N; i++) {
		if (W[k] + c[k] >= W[i]) {
			tmp = min(rem, W[k] + c[k] - W[i]); c[i] += tmp; rem -= tmp;
		}
	}

		for (int i = N; i >= 0; i--) {
			if (c[i] < M && rem>0) {
				tmp =min( M - c[i],rem);
				c[i] += tmp; rem -= tmp;
			}
		}

		for (int i = 1; i <= N; i++) {
			H.push_back(W[i] + c[i]);
		}

		sort(H.rbegin(), H.rend());

		int pos = 0;

		for (int i = 0; i < N; i++) {
			if (W[k] + c[k] == H[i]) { pos = i + 1; break; }
		}

		if (pos <= P) { return 1; }



