	return -1;
}

int Binary_Search(void) {

	int left = 0;
	int right = N;

	int med;

	while (right >left+1) {
		med = (right + left) / 2;

		if (IsPossible(med) == 1) { right = med; }
		else { left = med; }
	}

	return right;
}

