int main(void){
    ll N,M,V,P; cin >> N >> M >> V >> P;
    vector<ll> A(N); REP(i,N) cin >> A[i];
    SORT(A); REVERSE(A);

    ll l = 0, r = N, n = (l+r)/2;
    while(r-l>1){
        bool flag;
        vector<ll> v(A);
        if(v[n] >= A[P-1]) flag = true;
        else if(v[n]+M < A[P-1]) flag = false;
        else{
            v[n] += M;
            ll res = M*(V-1);
            REP(i,min(P-1,V-1)){
                v[i] += M;
                res -= M;
            }
            RREP(i,N){
                if(i == n) continue;
                if(res <= 0 || v[i]>=v[n]) break;
                res -= min(M,v[n]-v[i]);
                v[i] += min(M,v[n]-v[i]);
            }
            flag = res>0 ? false : true;
        }
        if(flag) l = n;
        else r = n;
        n = (l+r)/2;
    }
    ll ans = r;
    cout << ans << endl;
    return 0;
}

