  for(int i = 0; i < n; i++) cin >> a[i];
  sort(a, a+n, greater<ll>());
  //for(int i = 0; i < n; i++) cout << a[i] << ' '; cout << endl;
  int L = 0;
  int R = n;
  int M;
  while(L < R-1) //index
  {
    M = (L+R)/2;
    if(C(M)) L = M;
    else R = M;
  }
  while(L < n-1 && a[L] == a[L+1]) ++L;
  cout << L+1 << endl;

  return 0;
}


