#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main()
{
    ll N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<int> A;
    int a;
    for (int i = 0; i < N; i++) {
        cin >> a;
        A.push_back(a);
    }

    sort(A.begin(), A.end(), greater<int>());

    int th = A.at(P - 1); // 閾値

    // ----- 閾値を調整
    ll remain = M * V;
    for (int i = 0; i < P-1; i++) {
        if (remain >= M) {
            A[i] = A[i] + M;
            remain = remain - M;
        } else {
            A[i] = A[i] - remain;
            break;
        }
    }

    while(true) {
        int th_right = 0;
        while(A[th_right] >= th) {
            th_right++;
        }
        //cout << "th=" << th << endl;
        ll remain_tmp = remain;
        for (int i = th_right + 1; i < N; i++) {
            //cout << "remain_begin=" << remain_tmp << endl;
            if (remain_tmp <= 0) break;

            if (th - A[i] <= M) {
                remain_tmp = remain_tmp - (th - A[i]);
            } else {
                remain_tmp = remain_tmp - M;
            }
        }

        //cout << "remain_end=" << remain_tmp << endl;
        if (remain_tmp <= 0) break;

        th++;
    }
    // -----

    int ans;
    for (int i = 0; th <= A[i] + M; i++) {
        ans = i + 1;
    }

    cout << ans << endl;

    return 0;
}

