			}
			else {

				ll mine = A[i] + M;// これを抜かれなければOK

				ll amari = V - P; // これをうまく分けて抜かれなければOK

				if (i + amari <= N - 1) {
					// 自分より後ろに配ればよい
					ans++;
				}
				else {
					ll front = V - P - (N - 1 - i); // 前に配らないといけない数

					if (front >= i - P && P < i) {
						// 前全員配らないといけないから無理
						cout << ans;
						return 0;
					}
					else {

						// min(mine - A[j], M)の累積 <= front * M　ならOK

						for (ll k = mae; k < i; k++) {
							if (A[k] < mine) {
								mae = k;
								break;
							}
						}

						ll can = mine * (i - mae) - (ruiseki[i-1] - ruiseki[mae-1]);

						if (can >= front * M &&   mine * (i-mae - front) - (ruiseki[i-front-1] - ruiseki[mae-1] ) >= M -1) {
							ans++;
						}
						else {
							cout << ans;
							return 0;
						}
					}

				}

			}

		}
	}




}

