bool check(vector< int > &A, int m) {
	if (m < P)
		return true;
	vector< int > B = A;

	rep(i, P - 1) {
		B[i] += M;
	}

	int V2 = V - P;
	while (A[m - 1] == A[m])
		--m;
	B[m] += M;
	if (V2 <= 0) {
		sort(B.rbegin(), B.rend());
		return B[P - 1] <= A[m] + M;
	}

	for (int i = m + 1; i < N; i++) {
		B[i] += M;
		V2--;
	}
	int M2 = M;
	if (V2 <= 0) {
		sort(B.rbegin(), B.rend());
		return B[P - 1] <= A[m] + M;
	}
	vector< int > tmp(V2, M);
	int target = B[m];
	int j = 0;
	for (int i = m - 1; i >= P - 1; i--) {
		int k = min(target - B[i], tmp[j]);
		B[i] += k;
		tmp[j] -= k;
		if (tmp[j] == 0)
			++j;
		if (j == V2)
			break;
		if (B[i] < target) {
			k = min(M - k, target - B[i]);
			tmp[j] -= k;
			B[i] += k;
		}
	}
	if (j == V2)
		return true;
	else
		return false;
	sort(B.rbegin(), B.rend());
	return B[P - 1] <= A[m] + M;
}
