const int MAXN = 1e5 + 1;
ll N, M, V, P;
ll A[MAXN];

bool chk(ll idx) {
    ll add = max(0LL, V - 1 - idx - (P - 1));
    // idx + 1 ~ N - P
    ll sum = 0;
    for(int i = idx + 1; i <= N - P; ++i) {
        if(A[idx] + M < A[i]) return false;
        sum += A[idx] + M - A[i];
    }
    return sum >= add * M;
}

