bool isGood(LL N, LL M, LL V, LL P, LL pos, vector<LL> A) {
    for (int i = 0; i <= pos; i++) {
        A[i] += M;
        V--;
    }
    if (V > 0) {
        vector<LL> B;
        for (int i = pos + 1; i < N; i++) B.push_back(A[i]);
        vector<LL> cap(B.size(), 0);
        LL rem = M * V;
        for (int i = (int) B.size() - 1; i >= 0; i--) {
            if (B[i] > A[pos]) {
                cap[i] += M;
                rem -= M;
            }
        }

        priority_queue<PLL, vector<PLL>, greater<>> Q;
        for (int i = 0; i < B.size(); i++) {
            Q.push(make_pair(B[i], i));
        }

        while (!Q.empty() and rem > 0) {
            auto t = Q.top();
            Q.pop();
            LL now = t.first;
            LL which = t.second;
            LL ok = max(0LL, A[pos] - now);
            if (ok <= 0) continue;
            LL plus = min(ok, M);
            cap[which] += plus;
            rem -= plus;
        }
        if (rem > 0) {
            for (int i = (int) B.size() - 1; i >= 0; i--) {
                if (cap[i] < M) {
                    LL d = min(M - cap[i], rem);
                    cap[i] += d;
                    rem -= d;
                }
            }
        }
        for (int i = 0; i < B.size(); i++) {
            A[pos + 1 + i] = B[i] + cap[i];
        }
    }
    vector<PLL> C(N);
    REP(i, N) C[i] = MP(A[i], i);
    RSORT(C);

    LL cnt = 0;
    for (int i = 0, j = 0; i < N; i = j) {
        bool now = false;
        while (j < N and C[i].first == C[j].first) {
            if (C[j].second == pos) {
                now = true;
            }
            j++;
        }
        if (now) {
            if (cnt < P and cnt + (j - i) >= P) {
                return true;
            }
        }
        cnt += (j - i);
    }

    return false;
}

int main() {

    LL N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<LL> A(N);
    cin >> A;

    SORT(A);

    LL ng = -1;
    LL ok = N;

    while (abs(ok - ng) > 1) {
        LL mid = (ok + ng) / 2;
        if (isGood(N, M, V, P, mid, A)) ok = mid;
        else ng = mid;
    }

    cout << N - ok << endl;

    return 0;
}

