    sort(A, A+N);

    ll p_val = A[N-P];
    int l = 0, r = N;
    for(int i = 1; i < N-1; i++){
        if(A[i] == p_val && A[i-1] < A[i]) l = i;
        if(A[i] == p_val && A[i] < A[i+1]) r = i+1;
    }
    //単調性がある
    //A[ok]が境目 -> ans = N - (A[ok]が最初に出現する場所)
    int ng = -1, ok = N;
    //にぶたん
    int m = (ng+ok)/2;
    while(abs(ng-ok) > 1){
        //A[m]は問題の中でN-m番目に大きい問題
        //結果的にP番目より上にならないといけない
        //上げる問題の選び方で最適なのはA[0]からA[m-1]まで選び,まだ選ぶ必要があればA[N-1]より高い順に選ぶ
        //選ぶ種類はV種類
        //操作前に,上からP番目のものを選ばなきゃいけないとなると抜かせないのでNG(ただしN-m > Pのときに限る)
        //そうでなければ,A[m] + M >= A[N-P]となってくれれば選ばれる可能性がある
        if(A[m] >= A[N-P]) ok = m;
        else{
            //A[m]がP番目に大きい値よりも小さい時
            int rem = V - (m+1); //A[0]からA[m]までは確実に選ぶ
            //P番目に大きい値が複数該当する場合,それらをバランスよく選ぶのが最適
            //P=3でV=5で,A=[0,1,2,2,2,2,3,4]で,m=1で,M=5のとき
            //rem = 3
            //A[N-P]と同じ値は4つある
            //そのうち一つを毎回の操作で選ぶと,どれかは二度選ぶ必要があり,基準は4となる
            if(rem <= 0){
                if(A[m] + M >= p_val) ok = m;
                else ng = m;
            }
            else{
                int must_choose = N-rem; //A[must_choose]は選ばないといけない
                if(l <= must_choose && must_choose < r){
                    int choose_num = r - must_choose;
                    ll total_add = M * choose_num;
                    //p_val + (total_add / (r-l))+1となるものがtotal_add % (r-l)個
                    //p_val + (total_add / (r-l))となるものが(r-l) - K個
                    //A[must_choose]を超えなきゃいけない
                    int K = total_add % (r-l);
                    if(choose_num <= K){
                        if(A[m] + M >= p_val + (total_add / (r-l)) + 1) ok = m;
                        else ng = m;
                    }
                    else{
                        if(A[m] + M >= p_val + (total_add / (r-l))) ok = m;
                        else ng = m;
                    }
                    //if(m == 2) cout << "K: " << K << endl;
                }
                else if(must_choose < l){
                    ng = m;
                }
                else{
                    if(A[m] + M >= p_val) ok = m;
                    else ng = m;
                }
            }
        }
        m = (ng+ok)/2;
    }

    //出力 この問題においてはどうやってもok == Nとなることはない
    rep(i, N){
        if(A[ok] == A[i]){
            cout << N-i << endl;
            break;
        }
    }
    return 0;
}

