    for(ll i=0;i<M;){
        // cout<<"ihyo "<<i<<" "<<hyo<<" "<<pos<<" "<<"v[pos]"<<" "<<hold<<endl;
        if(pos<v.size()&&v[pos]>=hold+(hyo>0)){
            // cout<<"AAA"<<endl;
            imos[pos]++;
            hold++;
            if(pos+hyo<=v.size())imos[pos+hyo]--;
            else return 0;
            i++;
        } else {
            pos++;
            hold+=imos[pos];
        }
        if(pos>=imos.size()){
            return 0;
        }
    }
    return 1;
}

