	V<int> c(n + 1, 0);
	REP(i, n) c[i + 1] = c[i] + a[i];

	V<int> lazy;
	std::map<int, bool> result;

	int ans = 0;
	REP(i, n) {
		if (i + 1 < n && a[i] == a[i + 1]) {
			lazy.emplace_back(a[i]);
			continue;
		}
		if (n - i <= p) {
			++ans;
