		int rest = m * v;
		rest -= (it - (a.begin() + i)) * (a[i] + m) - (c[it - a.begin()] - c[i]);
		rest -= i * m;
		rest -= (p - 1) * m;
		if (rest <= 0) {
			++ans;
			result[a[i]] = true;
		}
		else {
			result[a[i]] = false;
		}
	}
	for (auto& x : lazy) ans += result[x];
	OUT(ans)BR;

	return 0;
