    	ll incnum = V-(N-i)-(P-1);
    	ll leftnum = N-(N-i)-(P-1);
    	ll tot = getsum(P-1, i);
    	ll endsum = tot+incnum*M;
    	if(ending*leftnum >= endsum){
    		ans++;
    	}
    	else{

    	}

    }

    cout << ans;
}

