#include<bits/stdc++.h>
using namespace std;
const int maxn=1e5+7;
#define ll long long
int n,m,v,P;
int a[maxn],hve[maxn],pre[maxn];
ll qzh[maxn];
map<int,int> ls;
bool check(int p){
	if (v>pre[ls[a[p]]]){
		int num=pre[ls[a[p]]];
		int tv=v-num;
		int pp=upper_bound(a,a+n,a[p]+m)-a;
		for (int i=pp,j=n-pp;i>=pre[ls[a[p]]] && j<P;i--,j++){
			if (1ll*(tv-j)*m+qzh[i-1]-qzh[num-1]<=1ll*(a[p]+m)*(i-num)) return true;
		}
		return false;
	}
	else{
		int t=upper_bound(a,a+n,a[p]+m)-a;
		if (n-t<=P) return true;
		else return false;
	}
}
int main(){
	scanf("%d%d%d%d",&n,&m,&v,&P);
	for (int i=0;i<n;i++){
		scanf("%d",a+i);
	}
	sort(a,a+n);
	for (int i=0;i<n;i++){
		if (!i) qzh[i]=a[i];
		else qzh[i]=qzh[i-1]+a[i];
	}
	int p=-1,cnt=0;
	for (int i=0;i<n;i++){
		if (a[i]==p){
			hve[cnt]++;
			continue;
		}
		cnt++;
		ls[a[i]]=cnt;
		hve[cnt]=1;
		p=a[i];
	}
	for (int i=1;i<=cnt;i++){
		pre[i]=pre[i-1]+hve[i];
	}
	int l=0,r=n-1,mid,ans=-1;
	while (l<=r){
		int mid=(l+r)>>1;
		if (check(mid)){
			ans=mid;
			r=mid-1;
		}
		else l=mid+1;
	}
	printf("%d\n",n-ans);
	return 0;
}

