int cmp(const int a,const int b){
    return a>b;
}
int n,m,v,p;
int b[maxn];
bool judge(int mid){
    //printf("hello %lld\n",mid);
    if(mid<=p)return true;
    if(a[mid]+m<a[p])return false;
    if(v<=p-1&&a[mid]+m>=a[p])return true;
    int temp=0;
    for (int i=n,j=v-p;i>mid&&j;i--,j--){
        temp+=m;
    }
    temp+=m*p;
    int res=m*v-temp;
    int ww;
    for(int i=p;i<mid;i++){
        int add=min(m,max(a[mid]+m-a[i],0ll));
        if(add>res)add=res;
        res-=add;
        if(i==p){
            ww=a[p]+add;
        }
    }
    return a[mid]+m>=ww&&res<=0;
}
signed main(){
