bool ispossible(int n, int m, int v, int p, const vector<int> &a, int k) {
  if (k == n) return false;
  if (k < p) return true;
  int64_t s = 0;
  for (int i = 0; i < n; i++) {
    if (i < p - 1) {
      s += m;
    } else {
      int d = a.at(k) + m - a.at(i);
      if (d < 0) return false;
      s += min(m, d);
    }
  }
  return s >= (int64_t) m * v;
}

int main() {
