  for (int i = 0; i < n; i++) cin >> a.at(i);
  sort(a.rbegin(), a.rend());
  int lower_bound = p - 1, upper_bound = n;
  while (upper_bound - lower_bound > 1) {
    int half = (lower_bound + upper_bound) / 2;
    if (ispossible(n, m, v, p, a, half)) {
      lower_bound = half;
    } else {
      upper_bound = half;
    }
  }
  cout << lower_bound + 1 << endl;
}

