const int MAXN = 100000 + 10;

int n, m, v, p;
int a[MAXN];

bool judge(int k) {
	int i, overcnt = 0, x;
	int64 sum = 0;

	x = a[k] + m;

	for(i=n; i; i--) {
		if(i == k) {
			sum += m;
			continue;
		}

		if(a[i] > x or overcnt < p - 1) {
			overcnt++;
			sum += m;
		}
		else 
			sum += std::min(x - a[i], m);
	}
	return overcnt <= p - 1 and sum >= 1ll * m * v;
}

int main() {
	int i, l, r, mid;
	int ans=0;

	scanf("%d %d %d %d", &n, &m, &v, &p);
	for(i=1; i<=n; i++) 
		scanf("%d", &a[i]);

	std::sort(a+1, a+1+n);

	l = 1;
	r = n;
	while(l ^ r) {
		mid = (l + r) >> 1;
		if(judge(mid))
			r = mid;
		else
			l = mid + 1;
	}
	for(i=1; i<=n; i++)
		if(a[i] >= a[l])
			ans++;
	printf("%d\n", ans);
	return 0;
}

