        int cnt = max(0LL,V-(P-1)-(N-i-1)-1);
        cnt *= M;
        if(A[P-1] > A[i]+M) {
            break;
        }
        if(sum+cnt <= (A[i]+M)*(N-(P-1)-(N-i-1)-1)) {
            ans++;
        }
        sum += A[i];
    }
    cout << ans << endl;
}

