bool is_OK(vll& B, ll N, ll M, ll V, ll K) {
    ll X = K;
    ll limit = 0;
    REP(i, V, N) {
        limit += min(M, X - B[i]);
    }

    ll S = 0;
    rep(i, N) {
        if (B[i] > X) {
            S += B[i] - X;
        }
    }
    if (S <= limit) return true;
    return false;
}

ll calc_under(vll& A, ll N, ll M, ll V, ll P) {
    if (V < P) return A[P - 1];

    V -= (P - 1);
    N -= (P - 1);
    vll B(A.begin() + (P - 1), A.end());
    sort(B.begin(), B.end());
    rep(i, V) {
        B[i] += M;
    }
    ll L = B[N - 1] - 1;
    ll R = B[N - 1] + M;

    while (R - L > 1) {
        ll K = (L + R) / 2;
        if (is_OK(B, N, M, V, K)) {
            R = K;
        }
        else {
            L = K;
        }
    }
    return R;
}

