    sort(all(A));

    auto valid = [&](int k)
    {
        vector<ll> a;
        for (int i = 0; i < N; ++i) if (i != k)
            a.push_back(A[i] + M;);
        sort(all(a));

        int i = 0;
        while (i < N - 1 && a[i] <= A[k] + M) ++i;
