using namespace std;

using ll = long long;
const ll MOD = 1e9 + 7;
const ll INF = 1e18;
vector<ll> A;
ll n, m, i, j, k;
ll v, p;

bool isOK(ll index) {
    ll now = A[index]+m;
    priority_queue<ll> pq;
    pq.push(now);
    ll nokori = ((v-1)*(m)); // 残りの票
    for(i=0;i<n;i++){
        if(i==index)continue;
        ll x = A[i]+min({m,max(0ll,now-A[i]),nokori});
        pq.push(x);
        nokori-=min({m,max(0LL,now-A[i]),nokori});
    }
    if(nokori==0){
        for(i=0;i<p;i++){
            if(pq.top()==now)return true;
            pq.pop();
        }
        return false;
    }else{
        for(i=0;i<min(p-1,n-1-index);i++){
            pq.pop();
            nokori -= (m - max(0ll,now - A[n-1-i]));
            pq.push(A[n-1-i]+m);
        }
        if(nokori>0)return false;
        for(i = 0; i < p; i++) {
            if(pq.top() == now) return true;
            pq.pop();
        }
        return false;
    }
}

ll binary_search() {
    ll ng = -1;
    ll ok = (ll)A.size();
    //okとngの初期値によって最大値だけでなく最小値も求められる.
    //ng=-1の時はkey以上の数値の最小値

    while(abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;

        if(isOK(mid))
            ok = mid;
        else
            ng = mid;
    }
    return ok;
}

int main() {
    cin >> n >> m >> v >> p;
    A.resize(n);
    for(i=0;i<n;i++){
        cin >> A[i];
    }
    sort(A.begin(),A.end());
    cout << n-binary_search() << endl;
    return 0;
}

