bool ok(ll x,ll m,ll v,ll p,ll n){
    memcpy(b,a,sizeof a);
    for(int i = x;i <= n;++i){
        if(!v) break;
        b[i] += m;
        v --;
    }
    for(int i = 1;i <= p-1;++i){
        if(!v) break;
        b[i] += m;
        v --;
    }
    ll d = v * m;
    for(int i = p;i < x;++i) {
        if(!d) break;
        b[i] += d / (x - p);
    }
    if(d){
        d %= (x - p);
        for(int i = x-1;i >= p;--i){
            if(!d) break;;
            b[i] ++;
            d --;
        }
    }
    for(int i = p;i < x;++i){
        if(b[i] > b[x]) return 0; 
    }
    return 1;
}
