using namespace std;
typedef long long int lli;

int main(){
	lli n,m,v,p;
	cin >> n >> m >> v >> p;
	vector<lli> a(n);
	for(int i=0; i<n; i++){
		cin >> a[i];
	}
	sort(a.begin(), a.end());
	auto csum = a;
	for(int i=0; i<n-1; i++){
		csum[i+1] += csum[i];
	}

	lli ans = 0;
	for(int i=0; i<n; i++){
		//cerr << "i = " << i << endl;
		lli ubidx = upper_bound(a.begin(), a.end(), a[i]+m) -a.begin();
		if(n -ubidx >= p){
			continue;
		}
		lli sidx = upper_bound(a.begin(), a.end(), a[i]) -a.begin();
		if(n -sidx < p){
			ans++;
			continue;
		}
		lli unbeatable = n -ubidx;
		if(p-unbeatable-1 > 0){
			ubidx -= p-unbeatable-1;
		}
		lli rem = v -(n-ubidx) -sidx;
		//cerr << ubidx << " " << sidx << " " << rem << endl;
		if(rem <= 0){
			ans++;
			continue;
		}
		lli remnum = ubidx - sidx;
		lli remcap = remnum*(a[i]+m) -(csum[ubidx-1] -csum[sidx-1]);
		if(remcap >= rem*m){
			ans++;
		}
	}
	cout << ans << endl;
	return 0;
}

