void solve()
{
    ll n,m,v1,p;
    cin>>n>>m>>v1>>p;
    vl v;
    map <ll,ll> cnt;
    map <ll,ll> vis;
    ll sum[n+1]={0};
    rep(i,n)
    {
        ll c;
        cin>>c;
        v.pb(c);
        cnt[c]++;
    }
    sort(all(v));
    for(int i=0;i<n;i++)
    {
        if(i==0)
            sum[i]=v[i];
        else
            sum[i]=sum[i-1]+v[i];
    }
    ll smreq=(n-p);
    ll ans=0;
    for(int i=n-1;i>=0;i--)
    {
        if(vis[v[i]])
            continue;
        vis[v[i]]=1;
        if(n-i<=p)
        {
            ans+=cnt[v[i]];
            continue;
        }
        ll temp=v1;
        temp-=(i+1);
        temp-=(p-1);
        temp*=m;
        auto it=upper_bound(all(v),v[i]+m);
