bool judge(ll i,vector<ll> &a,ll m,ll v,ll p,ll memo){
  ll tmpv=v-i-(p-1);
  ll sum=tmpv*m;
  bool ans=false;
  for(ll j=memo+1;j<=n-p+1;j++){
    if(a[j]>a[i]+m){
      break;
    }
    else {
      sum-=(a[i]+m-a[j]);
    }
    if(sum<=0){
      ans=true;
      break;
    }
  }
  return ans;
}
