bool check(int idx) {
    int t = v[idx] + M;

    LL vot = M * V - M;

    vector<int> r;
    int res = N;
    for(int i = 0; i < N; ++i) {
        if(i == idx) continue;
        if(t < v[i]) {
            vot -= M;
        } else {
            r.pb(v[i]);
            --res;
        }
    }

    if(res > P) {
        return false;
    }

    sort(all(r), greater<>());
    for(int i = 0; i < r.size(); ++i) {
        if(t - r[i] < M && res < P) {
            vot -= M;
            ++res;
        } else {
            vot -= min((int)M, t - r[i]);
        }
    }

    return vot <= 0;
}

