const int N = 1e5+5;
ll arr[N],n,m,v,p;

bool ok(int x) {
    if(x < p) return true;
    if(arr[x] + m < arr[p]) return false;
    ll tot = (p - 1) * m; // first p - 1 elements.
    tot += (n - 1 - x) * m; // elements less than arr[x].
    tot += m; // own vote for arr[x]
    // from p to x - 1.
    FOR(i, p, x) {
        tot += max(0LL, min(m, arr[x] + m - arr[i]));
    }
    return tot >= m * v;
}

