    FOR(i, 0, n) {
        cin>>arr[i];
    }
    sort(arr, arr + n, greater<ll>());
    int lo = p, hi = n - 1, res = p;
    while(lo <= hi) {
        int mid = (lo + hi)>>1;
        if(ok(mid)) {
            res = max(res, mid + 1);
            lo = mid + 1;
        } else hi = mid - 1;
    }
    cout<<res;
    cerr << endl << "Time (in ms): " << double(clock() - clk) * 1000.0 / cps << endl;
    return 0;
}

