struct Problem {
	void Solve() {
		ULL N, M, V, P; cin >> N >> M >> V >> P;

		UL ans = 0;
		ULL A[100000];
		for (UL i = 0; i < N; i++) cin >> A[i];
		sort(A, A + N);
		if (V >= P) {
			N -= P - 1;
			V -= P - 1;
			ans += P;
			reverse(A, A + N);
			LL S = M;
			for (UL i = 1; i < N; i++) {
				if (A[i] + M < A[0]) break;
				S -= (A[i - 1] - A[i]) * i;
				if (V * M <= S + (N - i) * M) ans++;
				S += M + A[i] - A[i - 1];
			}
		}
		else {
			N -= P - 1;
			V = 1;
			ans += P;
			reverse(A, A + N);
			for (UL i = 1; i < N; i++) {
				if (A[0] <= A[i] + M) ans++;
			}
		}
		cout << ans << endl;
	}


	Problem();
};
