    for(int i=0;i<n;i++){
        cin >> a[i];
    }
    vector<long long> b(n);
    sort(a.begin(),a.end());
    long long ans=-1;
    long long left=-1;
    long long right=n;
    while(right-left!=1){
        long long mid=(right+left)/2;
        long long s=v*m;
        s-=(mid+1)*m;
        a[mid]+=m;
        if(s<=0){
            goto end;
        }
        for(int j=mid+1;j<n;j++){
            if(a[j]<=a[mid]){
                b[j]=min(s,a[mid]-a[j]);
                a[j]+=b[j];
                s-=b[j];
            }
            else{
                b[j]=min(s,m);
                a[j]+=b[j];
                s-=b[j];
            }
            if(s==0){
                goto end;
            }
        }
        for(int j=n-1;j>mid;j--){
            b[j]+=min(m-b[j],s);
            a[j]+=b[j];
            s-=b[j];
            if(s==0){
                goto end;
            }
        }
end:
        if(judge(mid)){
            ans=max(ans,mid);
            left=mid;
        }
        else{
            right=mid;
