ll n,m,v,pc;
ll a[100010],b[100010];

bool ok(ll pos){
	ll totv = m*(v-1);
	ll cpov = a[pos]+m;
	//cout<<pos<<' '<<cpov<<endl;
	memcpy(b,a,sizeof(a));
	ll m2 = n-1;
	for(int i=pos;i<=m2;i++)b[i] = b[i+1];
	ll cu = 0;
	vector<int> cc;
	ll cnt = 0;
	for(int i=1;i<=m2;i++){
		int cab = 0;
		if(b[i]>cpov){
			cab = m;
			cnt+=1;
		}else{
			cab = min(m,cpov-b[i]);
		}
		cu+=cab;
		cc.push_back(m-cab);
	}
	sort(cc.begin(),cc.end());
	while(cnt<pc-1){
		cu+=cc[cc.size()-1];
		cc.pop_back();
		cnt++;
	}
	if(cnt>pc-1)return false;
	if(cu>=totv)return true;
	return false;
}

