	int l = 0,r = n;
	sort(a+1,a+n+1);
	while(l+1!=r){
		int mid = (l+r+1)/2;
		if(ok(mid)){
			r = mid;
		}else{
			l = mid;
		}
	}
	cout<<n-r+1<<endl;
	return 0;
}

