int N, M, V, P, A[101010];
BIT<ll> bit(101010);
//---------------------------------------------------------------------------------------------------
void _main() {
	cin >> N >> M >> V >> P;
	rep(i, 0, N) cin >> A[i];

	sort(A, A + N);


	A[N] = inf*2;
	rep(i, 0, N) bit.add(i, A[i]);

	int ans = 0;
	int nxt = 0;
	int same = 0;
	rep(i, 0, N) {
		while (A[nxt] <= A[i] + M) nxt++;
		while (A[same] <= A[i]) same++;

		int cnt_bck = i + (same - i - 1);
		int cnt_nxt = N - nxt;

		if (P <= cnt_nxt) continue;
		int rest = V - 1 - cnt_bck - cnt_nxt;

		if (rest <= 0) {
			//printf("%d %d %d\n", i, cnt_bck, cnt_nxt);
			ans++;
			continue;
		}

		// 残りを[same, nxt)で分割
		int ok = same, ng = nxt + 1;
		while (ok + 1 != ng) {
			// [same, md)は超えないよう頑張る
			int md = (ng + ok) / 2;
			int ng_man = nxt - md;
			ll tot = bit.get(same, md);
			if (1LL * (M + A[i]) * (md - same) - tot >= 1LL * M * (rest - ng_man)) ok = md;
			else ng = md;
		}

		if (1 + cnt_nxt + (nxt - ok) <= P) {
			//cout << i << endl;
			ans++;
		}
	}
	cout << ans << endl;
}

