		if(n-pos+1>=p) continue;
		if(t<0) {
			ans++;
			continue;
		}
		if((ll)(a[i]+m)*(pos-1-i) - sum[pos-1]+sum[i] >= (ll)t) {
			ans++;
		} else {
			ll d = n-pos+1;
			t = t - ((ll)(a[i]+m)*(pos-1-i) - sum[pos-1]+sum[i]);
			if(t>=pos-1-i) d+=(pos-1-i);
			else d+=t;
			if(d<p) {
				ans++;
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

