int main() {
	Int N, M, V, P;
	cin >> N >> M >> V >> P;
	vector<Int> a(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }

	sort(a.begin(), a.end());
	Int ok = N - 1, ng = -1;
	while (ok - ng > 1) {
		Int idx = (ok + ng) / 2;
		bool ad = true;
		Int sum = (idx + 1) * M;
		vector<Int> add(N, 0);
		for (int i = idx + 1; i < N; ++i) {
			if (sum >= M * V) { break; }
			if (a[idx] + M < a[i]) { break; }
			add[i] = min(M, a[idx] + M - a[i]);
			sum += add[i];
		}
		for (int i = N - 1; i > idx; --i) {
			if (sum >= M * V) { break; }
			sum += M - add[i];
			add[i] = M;
		}
		if (sum < M * V) {
			ad = false;
		}
		Int cnt = 0;
		for (int i = idx + 1; i < N; ++i) {
			if (a[idx] + M < a[i] + add[i]) { ++cnt; }
		}
		if (cnt >= P) { ad = false; }

		if (ad) { ok = idx; }
		else { ng = idx; }
	}

	Int ans = N - ok;
	cout << ans << endl;

	return 0;
}

