bool ck(ll x,ll m,ll k,ll p,vector<ll> v) {
  vector<ll> a,b;
  rep(i,v.size()) {
    if(v[i]>x) a.pb(v[i]);
    else b.pb(v[i]);
  }
  if(a.size()>=p) return 0;
  ll z=min((ll)a.size(),k);
  k-=z;
  p-=a.size();
  ll sum=m*k;
  rep(i,b.size()) {
    ll d=m;
    if(p<=1) d=min(d,x-b[i]);
    d=min(d,sum);
    b[i]+=d;
    sum-=d;
    if(b[i]>x) p--;
  }
  if(!sum&&p>=1) return 1;
  return 0;
}

