    rep(i,0,N) cin >> A[i];

    sort(rbegin(A),rend(A));

    auto ok=[&](i64 i){
        i64 x=A[i]+M;

        vector<i64> top,other;
        rep(j,0,N){
            if(i==j) continue;
            if(top.size()<P-1) top.emplace_back(j);
            else other.emplace_back(j);
        }

        i64 remain=M*(V-1);
        for(auto j:top){
            i64 consumption=min(remain,M);
            remain-=consumption;
        }

        for(auto j:other){
            if(A[j]>x) return false; // 上位P-1以外でもxを超えることが確定していたらfalse
            i64 consumption=min({remain,x-A[j],M});
            remain-=consumption;
        }

        return remain==0;
    };

    i64 lb=0,ub=N;
    while(ub-lb>1){
        i64 mid=(lb+ub)/2;
        if(ok(mid)) lb=mid;
        else ub=mid;
    }

    cout << lb+1 << endl;
}

