template <typename UnaryPredicate>
int64_t binsearch(int64_t l, int64_t r, UnaryPredicate p) {
    assert (l <= r);
    -- l;
    while (r - l > 1) {
        int64_t m = l + (r - l) / 2;
        (p(m) ? r : l) = m;
    }
    return r;
}

int64_t solve(int64_t n, int64_t m, int64_t v, int64_t p, vector<int64_t> a) {
    sort(ALL(a));
    int k = binsearch(0, n, [&](int j) {
        int64_t limit = a[j] + m;
        int64_t used = 0;
        int cnt = 0;
        REP_R (i, n) if (i != j) {
            ++ cnt;
            if (cnt <= p - 1) {
                used += m;
            } else if (limit < a[i]) {
                return false;
            } else {
                used += min(m, limit - a[i]);
            }
        }
        return m * (v - 1) <= used;
    });
    return n - k;
}

