      //割り当てきれなくてもi番目の問題よりスコアが小さい問題に、並ばれない程度に割り当てきれれば可能性あり
      else{
        //i番目の問題の点数未満の問題数のカウント
        int mi_idx=0;
        for(int j=1;j<N+1;j++){
