mt19937 mt;
#define ls nodes[p].ch[0]
#define rs nodes[p].ch[1]
#define get(s) nodes[s]
#define getl(s) nodes[s].ch[0]
#define getr(s) nodes[s].ch[1]
#define self nodes[p]
template <typename T>
struct Treap {
   public:
    struct Node {
        T val;
        int ch[2];
        int sz;
        int cnt;
        int pri;
        Node() {}
        Node(T val) : val(val), sz(1), cnt(1), pri(mt() % 1000000) {
            ch[0] = 0, ch[1] = 0;
        }
    };
    int tot, root;
    Node nodes[MAXN];
    Treap() {
        tot = 0;
        get(0).pri = 9999999;
        root = newNode(numeric_limits<T>::max());
        get(root).sz = 0;
        get(root).cnt = 0;
        get(root).pri = -1;
    }
    inline void push_up(int p) {
        self.sz = self.cnt;
        if (ls) self.sz += get(ls).sz;
        if (rs) self.sz += get(rs).sz;
    }
    // 插入一个数到treap中
    inline void insert(T val) { root = _insert(root, val); }
    inline void erase(T val) { root = _delete(root, val); }
    // 获取一个数的排名，如果这个数不在其中就输出应该处于的排名
    inline int rank(T val) { return _rank(root, val); }
    // 获取一个排名为k的数
    inline T kth(int k) {
        if (k <= 0 || k > get(root).sz) return 0;
        return _kth(root, k);
    }
    inline T getPre(T val) { return _pre(root, val); }
    inline T getNext(T val) { return _post(root, val); }

   private:
    inline int newNode(T val) {
        nodes[++tot] = Node(val);
        return tot;
    }

    T _pre(int p, T val) {
        T pre;
        while (p) {
            if (self.val < val) {
                pre = self.val;
                p = rs;
            } else {
                p = ls;
            }
        }
        return pre;
    }

    T _post(int p, T val) {
        T pre;
        while (p) {
            if (self.val <= val) {
                p = rs;
            } else {
                pre = self.val;
                p = ls;
            }
        }
        return pre;
    }

    int _insert(int p, T val) {
        if (!p) return newNode(val);
        if (self.val == val) {
            ++self.cnt;
        } else {
            // 按照左小右大的顺序插入
            int d = !(val < self.val);
            self.ch[d] = _insert(self.ch[d], val);
            if (self.pri > get(self.ch[d]).pri) {
                p = rotate(p, d ^ 1);
            }
        }
        push_up(p);
        return p;
    }

    int _rank(int p, T val) {
        if (!p) return 1;
        if (self.val == val) return get(ls).sz + 1;
        // 比当前值小就往左边搜索
        else if (val < self.val)
            return _rank(ls, val);
        else
            // 否则就是左边的个数+右边的排名
            return get(ls).sz + self.cnt + _rank(rs, val);
    }

    T _kth(int p, int k) {
        // 排名小于左子树，说明目标小于当前值
        if (k <= get(ls).sz) return _kth(ls, k);
        // 如果排名在当前节点的范围内，说明目标就是当前值
        if (k <= get(ls).sz + self.cnt)
            return self.val;
        else
            // 否则就往右边找，同时缩小排名
            return _kth(rs, k - get(ls).sz - self.cnt);
    }

    int _find(int p, T val) {
        if (!p) return 0;
        if (self.val == val) return p;
        int d = !(val < self.val);
        return _find(self.ch[d], val);
    }

    // 旋转，0为左旋，1为右旋
    inline int rotate(int p, int d) {
        int tson = self.ch[d ^ 1];
        self.ch[d ^ 1] = get(tson).ch[d];
        get(tson).ch[d] = p;
        push_up(p);
        push_up(tson);
        return tson;
    }

    int _delete(int p, T val) {
        if (!p) return 0;
        if (self.val == val) {
            if (self.cnt > 1)
                --self.cnt;
            else {
                // 如果左右子树非空，则需要旋到底部删除
                if (rs || ls) {
                    if (!rs || get(rs).pri > get(ls).pri) {
                        p = rotate(p, 1);
                        rs = _delete(rs, val);
                    } else {
                        p = rotate(p, 0);
                        ls = _delete(ls, val);
                    }
                } else
                    p = 0;
            }
        } else {
            int d = !(val < self.val);
            self.ch[d] = _delete(self.ch[d], val);
        }
        if (!p) return 0;
        push_up(p);
        return p;
    }
};

