  for(int i = 0; i < P-1; ++i){
    A[N-1-i] += M;
  }
  int ans = P;
  for(int i = 0; i < N-P; ++i){
    long long r = M*V - (i+1)*M;
    r -= (P-1)*M;
    long long k = V - i - 1 - (P-1);
    int cnt = A.end() - upper_bound(A.begin(), A.end(), A[i]+M);
    if(cnt >= P) continue;
    if(k > 0){
      int jj = lower_bound(A.begin(), A.end(), A[i]+M) - A.begin();
      int d = jj-i-1;
      long long x = d*(A[i]+M) - cs.getsum(i+1,jj);
