bool check(int pos){
	if (pos>=v)
		return a[pos]+m>=a[n-p+1];
	int d=v-pos+1;
	if (d<=p-1){
		if (a[pos]+m>=a[n-p+1])
			return 1;
	}else{
		ll sum=1ll*(d-p+1)*m;
		for (int i=pos+1;i<=n;i++){
			if (a[pos]+m<a[i]) break;
			sum-=min(a[pos]+m-a[i],m);
		}
		return sum<=0;
	}
}
