int Lcm(int a, int b) {
  int bigger = max(a,b);
  int smaller = min(a,b);
  int ans = bigger;
  while(ans%smaller!=0) ans+=bigger;
  return ans;
}

bool IsPrime(int a) {
  if(a <= 1) return false;
  if(a == 2) return true;
  if(a%2 == 0) return false;
  for(int i = 3; i*i <= a; i+=2) {
    if(a%i==0) return false;
  }
  return true;
}

int Factorial(int n){
  int ans = 1;
  while(n > 1){
    ans *= n;
    --n;
  }
  return ans;
}

int NPR(int n, int r) {
  return Factorial(n)/Factorial(n-r);
}

int NCR (int n, int r){
  return NPR(n,r)/Factorial(r);
}

