bool check(int pos){
	if (pos + p >= n)
		return true;
	if (v <= p)
		return a[n - p] <= a[pos] + m;
	li sum = 0;
	forn(i, n - (p - 1)) if (i != pos)
		sum += min(m, a[pos] + m - a[i]);
	int cnt = v - p;
	return sum >= cnt * li(m);
}

void solve() {
	sort(a, a + n);
	//cerr << vector<int>(a, a + n) << endl;
	int l = 0, r = n - 1;
	int ans = -1;
	while (l <= r){
		int m = (l + r) / 2;
		if (check(m)){
			ans = m;
			r = m - 1;
		}
		else{
			l = m + 1;
		}
	}
	printf("%d\n", n - ans);
}

