using namespace std;

const int N = 2e5 + 5;

int n, m, v, p;
int arr[N], lf[N], rt[N];

bool valid(int mid)
{
    int c = v-1, val = arr[mid] + m, pp = p, mm = m;
    vector<int> xx;
    for(int i = 0 ; i < n ; i++)
    {
        if(i != mid)
        {
            if(arr[i] + m <= val or (c <= 0 and arr[i] <= val)) c--;
            else if(arr[i] > val and c > 0) pp--, c--;
            else
            {
                xx.push_back(arr[i]);
            }
        }
    }
    if(xx.size() < pp) return 1;
    priority_queue<int> Q;
    for(int i = 0 ; i < pp-1 and c > 0 ; i++)
    {
        c--;
        xx[i] += m;
    }
    for(int i = 0 ; i < c ; i++) Q.push(-m);
    for(int i = pp-1 ; i < xx.size() and Q.size() ; i++)
    {
        int mn = val - xx[i];
        while(mn > 0 and Q.size())
        {
            int nxt = -Q.top();
            Q.pop();
            if(nxt > mn)
            {
                nxt -= mn;
                xx[i] = val;
                Q.push(-nxt);
                break;
            }
            else
            {
                xx[i] += nxt;
                mn -= nxt;
            }
        }
    }
    if(Q.size()) return 0;
    xx.push_back(val);
    sort(xx.rbegin(), xx.rend());
    return xx[pp-1] <= val;
}

