LL pref[MR];

int main()
{
	int N, M, V, P;
	scanf("%d%d%d%d", &N, &M, &V, &P);
	vector<int> A;
	REP(i, N)
	{
		int a;
		scanf("%d", &a);
		A.push_back(a);
	}

	sort(A.begin(), A.end());
	pref[0] = A[0];
	FOR(i, 1, N)
		pref[i] = A[i] + pref[i - 1];

	int res = 0;
	REP(i, N)
		if (N - i <= P)
			res++;
		else
		{
			int left = max(V - i, 0);

			if (left - P <= 0)
			{
				if (A[i] + M >= A[N - P])
					res++;
			}
			else
			{
				int Vleft = left - P;
				// mamy przedzial [i+1,N-P] kandydatow i M*Vleft glosow
				// zobacz, czy to sie da rozlozyc tak, by kazdy na tym przedziale mial max A[i]+M
				int len = N - P - i;
				if (M*(LL)Vleft <= len * (LL)(A[i] + M) - (pref[N - P] - pref[i])
					&& A[i] + M >= A[N - P])
					res++;
			}
		}

	printf("%d\n", res);

	return 0;
}

