using lint = long long int;

template<class Monoid> struct SegmentTree {
    using func = function<Monoid(Monoid, Monoid)>;
    int n;
    Monoid ie;
    func f;
    vector<Monoid> node;

    SegmentTree(){};
    SegmentTree(int n, Monoid ie, func f) : n(n), ie(ie), f(f) {
        const int cn = n;
        n = 1; while(n < cn)  n *= 2;
        node.assign(2*n, ie);
    }

    void update(int i, Monoid x) {
        i += n;
        node[i] = x;
        while(i /= 2)  node[i] = f(node[2*i], node[2*i+1]);
    }

    // [l, r)
    Monoid query(int l, int r) {
        l = max(l, 0);  r = min(n, r);
        if(l >= r)  return ie;

        Monoid res = ie;
        for(l += n, r += n; l != r; l /= 2, r /= 2) {
            if(l % 2)  res = f(res, node[l++]);
            if(r % 2)  res = f(res, node[--r]);
        }
        return res;
    }

    Monoid operator[](int i) {
        assert(0 <= i && i < n);
        return node[i+n];
    }
};

int main() {
    lint n, m, v, p;
    cin >> n >> m >> v >> p;

    vector<lint> a(n);
    for(lint i=0; i<n; i++)  cin >> a[i];

    sort(begin(a), end(a));

    map<lint, lint> mp;
    for(auto e : a)  mp[e]++;

    reverse(begin(a), end(a));
    lint bottom = a[p-1];
    lint bottom_cnt = mp[bottom];
    reverse(begin(a), end(a));

    SegmentTree<lint> seg(n, 0LL, plus<lint>());
    for(lint i=0; i<n; i++) {
        seg.update(i, a[i]);
    }

    lint ans = 0;
    for(lint i=0; i<n; i++) {
        if(a[i] >= bottom) {
            ans++;
            continue;
        }

        lint left = upper_bound(begin(a), end(a), a[i]) - begin(a);
        lint right = upper_bound(begin(a), end(a), bottom) - begin(a);
        lint goal = a[i] + m;
        if(goal < bottom)  continue;

        lint need = goal * (right - left) - seg.query(left, right);
        lint nv = (right - left) * m - need;
        ans += (nv <= m * (n-v));
    }

    cout << ans << endl;
}

