        ll curr = acc[idx-1] - (acc[fir[itr->first] + itr->second - 1]);
        //cerr << curr << " " << rem << endl;
        if((m + itr->first) * (ll)(idx - 1 - (fir[itr->first] + itr->second - 1)) - curr >= rem * m)ok = true;
      }
    }
    if(ok)res += itr->second;
    //cerr << itr->first << " " << ok << endl;
  }
  cout << res << endl;
  return 0;
}

