  vector<ll> A(N);
  rep(i, N) cin >> A[i];

  sort(all(A));

  int ok = N - 1;
  int ng = -1;

  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;

    if (N - P <= mid + 1) {
      ok = mid;
      continue;
    }

    vector<ll> a = A;
    ll target = a[mid] + M;
    ll v = V - 1;
    rep(i, mid) {
