    }

    bool flg = true;
    ll cnt = v * M;
    REP(i, mid + 1, N - (P - 1)) {
      if (target < a[i])
        flg = false;
      else
        cnt -= (target - a[i]);
    }

    if ((cnt > 0) || !flg)
      ng = mid;
    else
      ok = mid;
  }

  cout << N - ok << endl;
}

