bool isOk(ll mid){
  if(mid<=p-1) true;
  ll point=a[mid]+m;
  if(a[p-1]>point) return false;
  ll total=(p-1)*m+(n-mid)*m;
  irep(i,p-1,mid){
    // mid と 同じスコアになる or 最大m票 まで目一杯票を入れる
    total+=min(m,point-a[i]);
  }
  // [p-1,mid) までの a[i] が、a[mid] と同じスコアになるために必要な票数が全投票数以上になる
