ll n, m, v, p;
vector<ll> a;

bool check(int pos){
	vector<ll> b;
	const ll val = a[pos];

	rep(i, n) {
		if(i == pos) continue;
		b.push_back(a[i]);
	}

	const ll thr = val + m;
	ll over = 0LL;

	rep(i, n - 1) {
		if(b[i] > thr) {
			over++;
		}
	}

	ll total = 1LL * m * (v - 1);
	rep(i, n - 1) {
		if(i < p - 1) {
			total -= m;
		} else {
			total -= max(0LL, min(val + m - b[i], m));
		}
	}

	return (over <= p - 1) and (total <= 0);
}

