		cin >> tmp;
		a.push_back(tmp);
	}

	sort(rbegin(a), rend(a));

	int low = 0, high = n;

	while(high - low > 1) {
		const int mid = (low + high) / 2;
		if(check(mid))
			low = mid;
		else
			high = mid;
	}

	cout << high << endl;
	return 0;
}

