bool ok(int a) {
	int at = 0, tar = x[a] + m;
	while (x[at] <= tar)
		at++;
	if (n - at > p - 1)
		return 0;
	long long per = (v - 1) - (p - 1);
	if (per <= 0)
		return 1;
	long long need = m * per;
	for (int i = 0; i < n; i++)
		g[i] = 0;
	g[a] = 1;
	for (int i = 0, aat = n - 1; i < p - 1; i++) {
		if (aat == a)
			aat--;
		g[aat] = 1;
		aat--;
	}
	long long tot = 0;
	for (int i = 0; i < n; i++)
		if (!g[i])
			tot += min(m, tar - x[i]);
	return tot >= need;
}

