bool poss(int idx) {
  if (idx < p) return true;
  ll val = a[idx] + m;
  if (val < a[p-1]) return false;
  ll cast = 0;
  cast += p*m;
  cast += (n-idx-1)*m;
  for (int i = p-1; i < idx; ++i) {
    assert(val >= a[i]);
    cast += val - a[i];
  }
  return (cast >= m*v);
}

