int a[M];
LL sum[M]={0};
bool exceed=0;
int need;
int cal(int l,int r,int num) {
	if(0==num) return a[r];
	int lo=l,hi=r+1;
	LL all=1ll*num*m;
	for(int mid=(lo+hi)>>1;lo<hi;mid=(lo+hi)>>1){
		LL now=all+sum[mid]-sum[l-1];
		LL val=now/(mid-l+1);
		LL ex=now%(mid-l+1);
		LL right=val+!!ex;
		if(right>a[mid+1])
			lo=mid+1;
		else if(right<a[mid])
			hi=mid;
		else {
			if(val>a[l]+m) {
				exceed=1;
				break;
			}
			return max((int)right,a[r]);
		}
	}
	return exceed?need:max(a[r],a[l]+m);
}
