ll solve() {
    ll N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> A[i];
    }
    sort(A.begin(), A.end());
    if ( P >= V ) {
        ll cr = A[N-1-(P-1)] - M;
        ll i = lower_bound(A.begin(), A.end(), cr) - A.begin();
        return N - i;
    } else {
        ll cr = A[N-1-(P-1)] - M;
        ll i0 = lower_bound(A.begin(), A.end(), cr) - A.begin();
        if ( i0 > V - P ) {
            return N - i0;
        } else {
            vector<ll> ca(N);
            ll sm = 0;
            for ( int i = 0; i < N; i++ ) {
                sm += A[i];
                ca[i] = sm;
            }
            for ( ll j = i0; j < N-P; j++ ) {
                ll rm = (V - P - j) * M;
                ll f = (A[j]+M) * (N-P-j) - (ca[N-P] - ca[j]);
                if ( f >= rm ) {
                    return N - j;
                }
            }
            return P;
        }
    }
    return -1;
}

