bool can(int ind) {
    int cut = n + 1;
    int cnt = 0;
    for (int i = n; i >= 1; i--) {
        if (i == ind) continue;
        cnt++;
        if (cnt == p - 1) {
            cut = i;
            break;
        }
    }
    ll lft = max(0LL, v - p);
    ll score = a[ind] + m;
    vector < ll > add;
    for (int i = cut - 1; i >= 1; i--) {
        if (i == ind) continue;
        if (score < a[i]) return false;
        add.push_back(min(m, score - a[i]));
    }
    sort(add.begin(), add.end());
    ll tot_sum = 0;
    for (ll v : add) tot_sum += v;
    reverse(add.begin(), add.end());
    for (int i = 0; i < lft; i++) {
        if (tot_sum < (lft - i) * m) return false;
        tot_sum -= add[i];
    }
    return true;

}
