bool c(int d, int v, int p, int n, ll m) {
    if (d >= n-p) return true;

    ll midv = a[d];
    auto itr1 = upper_bound(all(a), midv);
    int ns = itr1 - a.begin();
    auto itr2 = upper_bound(all(a), a[n-p]);
    int nl = a.end() - itr2;
    //if (nl+ns>=v) return true;
    //else {
    ll sum = 0;
    ll red = (ll)(v-nl-ns);
    for (auto itr = itr1; itr != itr2; ++itr) {
        sum += (midv + m - *itr);
    }
    if (m * red <= sum) {
        return true;
    }
    else return false;
    //}
}

int main() {
    int n;
    ll m;
    int v, p;
    cin >> n >> m >> v >> p;
    a.resize(n);
    rep(i,n) cin >> a[i];

    int ub = n-1;
    int lb = 0;
    sort(all(a));
    while (ub-lb>1) {
        int mid = (ub+lb) / 2;
        if (c(mid, v, p, n, m)) ub = mid;
        else lb = mid;
    }
    ll maxv = a[ub];
    auto itr = lower_bound(all(a), maxv);
    int ans = a.end() - itr;
    cout << ans << endl;
    return 0;
}

