bool ok(const vector<int> &A, ll M, ll V, ll P, int index) {
  if (index < P) {
    return true;
  }

  if (A[P - 1] > A[index] + M) {
    return false;
  }

  ll rest = M * V;
  REP(i, A.size()) {
    if (i == index) {
      rest -= M;
    } else if (i < P - 1) {
      rest -= M;
    } else {
      rest -= min(max<ll>(A[index] + M - A[i], 0), M);
    }
    // cout << A << " " << P << " " << index << " "  << rest << " " << A.size() << " " << i << endl;

  }
  // cout << A << " " << P << " " << index << " "  << rest << " " << A.size() << endl;
  return rest <= 0;
}

int main(int argc, char *argv[]) {

  int N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int> A(N);
  REP(i, N) {
    cin >> A[i];
  }
  sort(ALL(A), greater<int>());
  // cout << A << endl;

  int ub = N;
  int lb = 0;
  while ((ub - lb) > 1) {
    int mb = (ub + lb) / 2;
    if (ok(A, M, V, P, mb)) {
      lb = mb;
    } else {
      ub = mb;
    }
  }
  cout << ub << endl;
}

