inline bool check(li pos) {
    pos = upper_bound(a, a + n, a[pos]) - a - 1;
    if (pos >= n - p) {
        return true;
    }
    if (a[pos] + m < a[n - p]) {
        return false;
    }
    li cnt = 0;
    rep(i, pos + 1) {
        cnt += m;
    }
    rep(i, p - 1) {
        cnt += m;
    }
    repp(i, pos + 1, n - p + 1) {
        cnt += a[pos] + m - a[i];
    }
    return cnt >= m * v;
}

