using i64 = int64_t;

int main(){
    i64 n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<i64> problems;
    for(int i=0;i<n;++i){
        i64 a;
        cin >> a;
        problems.push_back(a);
    }

    sort(problems.rbegin(), problems.rend());

    i64 valid = 0, invalid = n - 1;
    while(abs(valid-invalid) > 1){
        i64 mid = (valid + invalid) / 2;
        if(mid < p){
            valid = mid;
        }else if(problems[mid]+m < problems[p-1]){
            invalid = mid;
        }else{
            i64 sum = (p-1)*m + (n-mid-1)*m;
            for(int i=p;i<mid;++i){
                if(problems[i] > problems[mid] + m){
                    sum = -1;
                    break;
                }
                sum += problems[mid]+m-problems[i];
            }
            if(sum >= m*v)valid = mid;
            else invalid = mid;
        }
    }

    cout << valid + 1 << endl;

    return 0;
}

