typedef long long int64;

int64 n,m,v,p;

bool HasPossibility(int tgt, vector<int64>& a){
  vector<int> score(n);
  for(int i=0;i<n;i++){
    if(i==tgt) continue;
    score[i]=a[i];
  }
  score[tgt]=a[tgt]+m;
  int tgt_score=score[tgt];
  std::sort(score.begin(), score.end(), std::greater<>());
  int r=0;
  for(int i=0;i<n;i++){
    if(score[i]==tgt_score){
      r=i;
      break;
    }
  }

  if(r>=p) return false;

  bool found_tgt=false;
  int added=0;
  for(int i=0;i<p;i++){
    if(score[i]==tgt_score){
      if(found_tgt){
        added+=m;
      }else{
        found_tgt=true;
      }
    }else{
      added+=m;
    }
  }
  for(int i=p;i<n;i++){
    added+=min((int64)(tgt_score-score[i]),m);
  }

  return (added>=(v-1)*m);
}

int main(){
  cout << std::fixed << std::setprecision(16);
  cin.tie(nullptr);
  std::ios::sync_with_stdio(false);


  cin>>n>>m>>v>>p;
  vector<int64> a(n);
  for(int i=0;i<n;i++){
    cin>>a[i];
  }

  std::sort(a.begin(), a.end(), std::greater<>());

  int left=0,right=n,mid=n/2;
  while(right-left>1){
    if(HasPossibility(mid,a)){
      left=mid;
    }else{
      right=mid;
    }
    mid=(left+right)/2;
  }

  cout<<left+1<<endl;



  return 0;
}

