using namespace std;

int n, m, v, p;
int a[100021];

bool Cmp(int x, int y) {
	return x > y;
}

bool Valid(int d) {
	if (d <= p) return true;
	for (int i = d; i >= 1; --i) {
		if (a[i] != a[d]) {
			d = i + 1;
			break;
		}
	}
	// printf("%d\n", d);
	int s = m * v;
	for (int i = 1; i < p && s; ++i) {
		a[i] += m;
		s -= m;
	}
	for (int i = d; i <= n && s; ++i) {
		a[i] += m;
		s -= m;
	}
	if (s == 0) {
		if (a[d] >= a[p]) return true;
		else return false;
	}
	if (a[d] < a[p]) return false;
	for (int i = d - 1; i >= p && s; --i)
		s = s - (a[d] - a[i]);
	return s <= 0;
}

