long long extra(int poz, int len, int init)
{
    return (Sum[poz]-Sum[poz-len])-1LL*len*init;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	int n,m,v,p;
    cin>>n>>m>>v>>p;
    for(int i=1; i<=n; i++)
        cin>>A[i];

    sort(A+1,A+n+1);

    for(int i=1; i<=n; i++)
        Sum[i]=Sum[i-1]+A[i];

    int rez=0;
    int ind=1;
    for(int i=1; i<=n; i++)
    {
        while(A[ind+1]<=A[i]+m && ind+1<=n)
            ind++;

        if(n-ind+1>p)
            continue;

        long long cr=1LL*(i-1)*m+1LL*(n-ind+1)*m+1LL*(ind-i)*(A[i]+m)-(Sum[ind]-Sum[i]);
        long long total=1LL*m*v;
        if(cr>=total)
        {
            rez++;
            continue;
        }

        int add=0;
        for(int j=16; j>=0; j--)
            if(ind-(add+(1<<j))+1>i && cr+extra(ind,add+(1<<j),A[i])<total)
                add+=(1<<j);

        add++;
        if(n-ind+1+add<=p)
            rez++;
    }
    cout<<rez<<"\n";
    return 0;
}

