			ruiseki[i] = 0;
		}
		ruiseki[0] = A[0];
		for (int i = 1; i < N; i++){
			ruiseki[i] = A[i - 1] + ruiseki[i - 1];
		}

		int ans = 0;

		for (int i = 0; i < N; i++) {


			// M個で足りなければ論外
			if (border - A[i] > M) {
				cout << ans;
				return 0;
			}
			else {

				int mine = A[i] + M;// これを抜かれなければOK

				int amari = V - P; // これをうまく分けて抜かれなければOK

				if (i + amari <= N - 1) {
					// 自分より後ろに配ればよい
					ans++;
				}
				else {
					int front = V - P - (N - 1 - i); // 前に配らないといけない数

					if (front >= i - P && P < i) {
						// 前全員配らないといけないから無理
						cout << ans;
						return 0;
					}
					else {

						// min(mine - A[j], M)の累積 <= front * M　ならOK

						for (int k = mae; mae < i; k++) {
							if (A[k] < mine) {
								mae = k;
								break;
							}
						}

						ll can = mine * (i - mae) - (ruiseki[i] - ruiseki[mae]);

						if (can >= front * M) {
							ans++;
						}
						else {
							cout << ans;
							return 0;
						}
					}

				}

