bool check(vector<int> a, int idx, int n, int m, int v, int p) {
  if (a[idx] + m < a[p - 1]) return false;
  ll rest = m * v;
  int base = a[idx] + m;
  for (int i = 0; i < p - 1; ++i) {
    a[i] += m;
    rest -= m;
  }
  for (int i = idx; i < n; ++i) {
    a[i] += m;
    rest -= m;
  }
  for (int i = p - 1; i < idx; ++i) {
    ll t = max(0, base - a[i]);
    a[i] += t;
    rest -= t;
  }
  // cout << a << " " << idx << " " << base << " " << rest << endl;
  return rest <= 0;
}

