  }
  REPR(i, N - 1) {
    if (cnt == 0) break;
    int val = min(M - (aC[i] - a[i]), cnt);
    aC[i] += val;
    cnt -= val;
  }
  DUMP(id);
  PRINTARR(a, a + N);
  PRINTARR(aC, aC + N);
  assert(accumulate(a, a + N, 0) + M * V == accumulate(aC, aC + N, 0));
