#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

bool is_ok(vector<int64_t>& as, int n, int64_t m, int v, int p, int i)
{
	int cv = (n - i);
	FOR_DW(j, i - 1, 0) {
		if (as[i] == as[j]) cv++;
		else break;
	}

	int ti = p - 2;
	FOR_DW(j, ti, 0) {
		if (as[ti] == as[p - 1]) ti--;
		else break;
	}

	int64_t av = as[i] + m;

	int64_t rc = 0;
	FOR_LT(j, ti + 1, i) {
		if (as[j] == as[i]) break;
		rc += av - as[j];
	}

	int64_t nc = (v - cv - (ti + 1)) * m;

	return (nc <= rc);
}

