        vector<ll> d(N, 0);
        ll delta = 0;
        while (N - 1 - i >= P)
        {
            delta += d[i];
            ll x = a[i] + delta;
            if (x <= A[k] + M)
            {
                ++i;
                continue;
            }
            if (x - (A[k] + M) > downs) return false;

            ll steps = x - (A[k] + M);
            downs -= steps;
            int step_sz = min(N - V, N - 1 - i);
            int r = i + step_sz;
            delta -= steps;
            d[r] += steps;
            ++i;
        }
        return true;
    };

    int vl = -1;
    int vr = N;
    while (vr - vl > 1)
    {
        int k = (vl + vr) / 2;
        if (valid(k))
            vr = k;
        else
            vl = k;
    }
    cout << N - vr << '\n';

    return 0;
}

