const int maxn = 2e5;

int n, m, V, P;
int A[maxn];

bool Check(int i) {
  if (n - i <= P) return true;

  int h_start = n - (P - 1);
  if (h_start <= i) --h_start;
  int l_end = h_start - 1;
  if (l_end == i) --l_end;
  int lim = A[i] + m;

  li rest = (li)(P - 1) * m;
  for (int j = 0; j <= l_end; ++j) {
    if (j == i) continue;
    if (A[j] > lim) return false;
    rest += min(m, lim - A[j]);
  }
  return rest >= (li)m * (V - 1);
}

