  int l = 0, r = n;
  while (r - l > 1) {
    int mid = l + r >> 1;
    if (Check(mid - 1)) {
      r = mid;
    } else {
      l = mid;
    }
  }
  printf("%d\n", n - l);
  return 0;
}

