  ll V = in();
  ll P = in();
  vector<ll> A = in(N);
  sort(A);

  // A[x]の問題が採用され得るか否か
  auto f = [&](ll x){
    if(x >= N - P) return true;
    ll voteSum = 0;
    debug(x);

    vector<ll> B(A);
    ll voteNum = M * V;

    // 全員B[x]に投票
    B[x] += M;
    voteSum += M;

    ll target = B[x];
    ll cnt = 0;
    rep(i, N){
      if(A[i] > target) cnt++;
    }
    if (cnt >= P) return false;

    // 無駄に消化できる票を消化
    voteSum += M * (P - 1);
    rep(i, N - P, N){
      B[i] += M;
    }
    debug(B);

    rep(i, N){
      if(B[i] <= target){
        if(B[i] <= target - M){
          voteSum += M;
          B[i] += M;
        }else{
          voteSum += target - B[i];
          B[i] = target;
        }
      }
    }
    debug(B);
    debug(voteSum);
    debug(voteNum);
    debug(voteSum >= voteNum);

    return voteSum >= voteNum;
  };

  ll ans = 0;
  ll ok = N - 1;
  ll ng = -1;
  while(abs(ok - ng) > 1){
    ll md = (ok + ng) / 2;
    (f(md) ? ok : ng) = md;
  }
