typedef long long int64;

int64 n,m,v,p;

bool HasPossibility(int64 tgt, vector<int64>& a){
  vector<int64> score(n);
  for(int i=0;i<n;i++){
    if(i==tgt) continue;
    score[i]=a[i];
  }
  score[tgt]=a[tgt]+m;
  int64 tgt_score=score[tgt];
  std::sort(score.begin(), score.end(), std::greater<>());
  int64 r=0;
  for(int i=0;i<n;i++){
    if(score[i]==tgt_score){
      r=i;
      break;
    }
  }

  if(r>=p) return false;

  bool found_tgt=false;
  int64 added=0;
  for(int i=0;i<p;i++){
    if(score[i]==tgt_score){
      if(found_tgt){
        added+=m;
      }else{
        found_tgt=true;
      }
    }else{
      added+=m;
    }
  }
  for(int64 i=p;i<n;i++){
    added+=min((int64)(tgt_score-score[i]),m);
  }

  return (added>=(v-1)*m);
}

