// i番目の要素を採用できるか否か
bool f(vector<ll> a, ll V, ll i) {
  if (i < P)
    return true;

  // 自分自身
  a[i] += M; V--;
  if (a[P-1] > a[i])
    return false;

  // 自分自身より小さいものはどうでもよい
  ll t = 0;
  t += (N-1 - (i+1) +1) * M;

  // 1 ~ P-1番目のものはどうでもよい
  t += (P-1) * M;

  // P番目までは逆転したい -> j = P-1 ~ i-1 に、つまりできるだけ分散させたい
  for (ll j=P-1; j<i; j++) {
    t += min(M, max(0ll, a[i] - a[j]));
  }

  return t >= M * V;
}

