    cont (i, n) {
        if (a[i] == b[i] && b[i] < mx) {
            num del = min(sum, mx - b[i]);
            sum -= del;
            b[i] += del;
            rem.push_back(i);
        } else if (a[i] == b[i]) {
            num del = min(sum, m);
            sum -= del;
            b[i] += del;
        }
    }
    sort(all(rem), cmp);
    loop (i, rem.size()) {
        int id = rem[i];
        num del = min(sum, m - (b[id] - a[id]));
        b[id] += del;
        sum -= del;
