template<typename T>
struct CumSum{
private:
  size_t size;
  vector<T> data;
public:
  CumSum(vector<T> dat){
    size = dat.size();
    data.resize(size+1,0);
    for(size_t i = 0; i < size; ++i)
      data[i+1] = data[i] + dat[i];
  }
  T getsum(size_t l, size_t r){//0-indexed, [l,r)
    return data[r] - data[l];
  }
  T getsum(size_t r){//0-indexed, [0,r)
    return data[r];
  }
};

int main(){
  int N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<long long> A(N);
  for(int i = 0; i < N; ++i)
    cin >> A[i];
  sort(A.begin(), A.end());

  CumSum<long long> cs(A);
  {
    for(auto  a : A)
      cerr << a << " ";
    cerr << endl;
  }

  int ans = 0;
  for(int i = 0; i < N; ++i){
    long long r = M*V - i*M;
    r -= (P-1)*M;
    long long k = V - i - (P-1);
    if(k > 0){
      int j = upper_bound(A.begin(), A.end(), A[i]+M) - A.begin();
      int d = j-i-1;
      long long x = d*(A[i]+M) - cs.getsum(i+1,j);
      r -= x;
    }
    if(r <= 0) ++ans;
  }
  cout << ans << endl;
}

