void solve() {  
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<ll> a(n);

    v -= p;
    v = max(v, 0ll);

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    sort(all(a));

    int l = -1, r = n - p;
    while (r - l > 1) {
        int k = (l + r) / 2; 

        if (a[k] + m < a[n - p]) {
            l = k;
            continue;
        }

        if (k >= v) {
            r = k;
            continue;
        }

        ll initv = v;
        v -= k;

        vector<ll> vals; 
