        i = (left + right) / 2;
        while (a[i-1] == a[i]) --i;
        //cerr << "left, right = " << left << ", "<<right<<", checking a[" << i << "] = " << a[i] << endl;
        ll cur = a[i] + m;
        if (cur < ap) {
            right  = i;
            continue;            
        };
        //cerr << "v - 1 is " << (v-1)  << ", n - 1 - i is " << n - 1 -i << ", p - 1 is " << p - 1<< endl;
        ll rest = (v - 1 - (n - 1 - i) - (p - 1));
        //cerr << "rest is " << rest << endl;
        if (rest <= 0) {
            rest = 0;
        }
        rest = m * rest;
        //cerr << "m * rest is " << rest << endl;
        for (ll j = p; j < i; ++j) {
            //cerr << "rest is " << rest << endl;
            if (rest <= 0) break;
            rest -= min(m, cur - a[j]);
            //cerr << "> rest is " << rest << endl;
        }
        if (rest <= 0) {
            left = i;
        } else {
            right = i;
        }
        while (a[left+1] == a[left]) ++left;
        while (a[right-1] == a[right]) --right;
    }
    while (a[left+1] == a[p]) ++left;
    cout << left + 1 << endl;
}

