    long iPointSum = m * (long)(v - p + 1);  //分配可能点  大きいp-1問に全振りした残り

    int nCanWin;  //勝ちうる問題で最弱の奴
    int i = 0;
    while(va[i] + m < va[n - p]){  //p-1番目に大きいやつとm点差以下の最低点を探す
        i++;
        iPointSum -= m;  //(m+1)点以上負けてるザコにm点やる
    }
    if(iPointSum <= 0){  //この時点で分配可能点が尽きてるならva[i]は逆転勝利可能
        nCanWin = i;
    } else {
        for(int k = i; k < n - p; k++){
            iPointSum -= (va[n - p] - va[k]);  //iからn-pまで得点をそろえるように分配
        }
        if(iPointSum <= 0){  //この時点で分配可能点が尽きてるならva[i]は逆転勝利可能
            nCanWin = i;
        } else {
            while(iPointSum > 0){  //iを1つずつ増やしてiからn-pまで得点をそろえるように分配
                i++;
                iPointSum -= (va[n - p] - va[i]) * (long)(n - p - i + 1);
            }
            nCanWin = (int)i;
        }
    }
