bool fc(vector<int> &a, int m, int v, int p, int mid){
  int n = a.size();
  if(mid < p) return true;
  vector<int> tr;
  rep(i, n){
    if(i == mid) continue;
    tr.push_back(a.at(i));
  }

  ll top = a.at(mid) + m;
  if(top < tr.at(p-1)) return false;
  ll ex = (ll)(v-1)*m;
  rep(i, n-1){
    if(i < p-1) ex -= m;
    else ex -= min((ll)m, top - tr.at(i));
  }
  return ex <= 0;
}

