int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	lint n, m, v, p;
	cin >> n >> m >> v >> p;

	vector<lint> a(n);
	for (lint i = 0; i < n; i++) {
		cin >> a[i];
	}
	sort(a.begin(), a.end());


	auto judge = [&](auto idx) {

		if (p + idx >= v) {
			return a[idx] + m >= a[n - p];
		}
		else {

			lint rem = v - (p + idx);
			lint sum = 0;
			lint A = a[idx] + m;
			for (lint i = idx + 1; i <= n - p; i++) {
				sum += max(A - a[i], 0LL);
			}
			DMP(idx, sum, rem, m);
			return sum >= rem * m;

		}

	};

	auto binary_search = [&](auto f) {

		auto ng = -1LL;
		auto ok = n - p;

		while (abs(ok - ng) > 1) {
			auto mid = (ok + ng) / 2;

			if (f(mid)) ok = mid;
			else ng = mid;
		}

		return ok;
	};

	// ok 見つけた後も次が同じか考える

	lint ans = binary_search(judge);
	DMP(ans);
	while (ans > 0) {
		if (a[ans] == a[ans - 1]) ans--;
		else break;
	}

	cout << n - ans << "\n";

	return 0;
}

