bool judge(vector<ll> &a, ll index, ll m, ll v, ll p) {
    ll n = a.size();
    if (n - index < p) {
        return true;
    }
    ll value = a[index] + m;
    auto lower = lower_bound(a.begin(), a.end(), value + 1);
    ll over_num = a.end() - lower;
    if (over_num > p - 1) {
        return false;
    }
    ll index_left = index + 1;
    ll index_right = n - (p - 1);

    ll rem_num = m * v;
    rem_num -= (index + 1 + (p - 1)) * m;
    repd(i, index_left, index_right) { rem_num -= value - a[i]; }
    if (rem_num <= 0) {
        return true;
    } else {
        return false;
    }
}

