    int len = chizu.size();
    REP(i, len){
        ll num = chizu[i];
        map<ll, ll> hiku;
        for(auto pa: ms){
            ll hik = min(pa.second, num);
            //dump(pa.first)
            //dump(pa.second)
            num -= hik;
            hiku[pa.first] = hik;
            if (num == 0){
                break;
            }
        }
        if (num > 0){
            return false;
        }
        for(auto pa: hiku){
            ms[pa.first] -= pa.second;
            if (ms[pa.first] == 0){
                ms.erase(pa.first);
            }
            if (pa.first+1 < 0){
                ms[pa.first+1] += pa.second;
            }
        }
    }
    return true;
}


