    int dis=v-p+1; // 还剩下个数
    for(int i = n ; i > mid ; i -- ){
        if(dis==1) break;//只能给mid
        sum += m ;
        dis--;
        b[i]+=m;
    }
    sum += m ;// mid消化掉
    ll flag = a[mid]+m;
    ll st = m*v-sum;//剩余量
    for(int i = p ; i < mid ; i ++ ){
        int up = min(m,max(a[mid]+m-a[i],0ll));
        if(up > st) up = st;//不够量
        st -= up;
        b[i] += up;
    }
    if( a[mid]+m>=b[p] && st<=0 ) return 1;
    return 0;
}
int main()
{
