    for(int i = 1 ; i <= n ; i ++ ){
        cin >> a[i];
    }
    sort(a+1,a+1+n,cmp);//前P个
    ll l = 1 , r = n;
    ll mid ;
    ll ans = 0;
    while(l<=r){
        mid = (l+r)>>1;
        if(check(mid)){
            l = mid+1;
            ans = mid;
        }
        else r = mid-1;
    }
    cout<<ans<<endl;
}

