int bin_search(vector<int> arr, int M, int left, int right,int ref){
    int mid = (left+right)/2;
    //cout<<left<<" "<<mid<<" "<<right<<endl;
    if(right-left <= 1){
        if(arr[left]==arr[right]){
            //cout<<right<<endl;
            return right;
        }
        //cout<<left<<endl;
        return left;
    }
    if(arr[mid] + M<ref)
        return bin_search(arr, M, left, mid, ref);
    else
        return bin_search(arr, M, mid, right, ref);
}

int main(){
    int i,x,N,M,V,P;
    cin>>N>>M>>V>>P;
    vector<int> arr;
    for(i=0;i<N;i++){
        cin>>x;
        arr.push_back(x);
    }
    //cout<<"!"<<endl;
    sort(arr.begin(),arr.end(),greater<int>());
    int right_index = bin_search(arr,M,P-1,N-1, arr[P-1]);
    //<<"Done bin-search"<<endl;
    int prod = M*V;
    int res = P;
    //cout<<right_index<<endl;
    for(x=P; x<=right_index; x++){
        int sum = (P-1)*M + (N-x)*M;
        //cout<<"2"<<endl;
        for(i=P-1; i<x; i++){
            sum += arr[x] + M - arr[i];
        }
        if(sum>=prod)
            res++;
        sum=0;
    }
    cout<<res<<endl;
}

