long long a[200000];
long long b[200000];
long long d[200000];
int n;
long long m,p,v;
bool pos(int t) {
    for(int i=0;i<n;i++) {
        b[i]=a[i];
        d[i]=0;
    }
    b[t]+=m;
    long long lj=v-1;
    if(t>=lj) return true;
    lj-=t;
    for(int i=0;i<t;i++) b[i]+=m;
    int c=0;
    while(t+c+1<n && a[t+c+1]==a[t]) c++;
    if(c>=lj) return true;
    lj-=c;
    for(int i=t+1;i<=t+c;i++) b[i]+=m;
    long long rem=lj*m;
    //cout<<a[t]<<":"<<endl;
    //cout<<rem<<endl;
    for(int i=t+c+1;i<n && rem>0;i++) {
        if(b[i]>b[t]) break;
        d[i]=min(rem,b[t]-b[i]);
        rem-=min(rem,b[t]-b[i]);
        b[i]=b[t];
    }
    //cout<<rem<<endl;
    //for(int i=0;i<n;i++) cout<<b[i]<<" ";
    //cout<<endl;
    if(rem>0) {
        for(int i=n-1;i>t+c && rem>0;i--) {
            b[i]+=min(rem,m-d[i]);
            rem-=min(rem,m-d[i]);
        }
    }
    int r=0;
    for(int i=0;i<n;i++) {
        if(b[i]>b[t]) r++;
    }
    if(r>=p) return false;
    return true;
}
