int main(){
    int N, V, P;
    lint M;
    cin >> N >> M >> V >> P;
    lint A[N];
    cins(A, A + N);
    sort(A, A + N);
    map<lint, int> A_kind;
    for(int i = 0; i < N; i++){
        A_kind[A[i]]++;
    }
    int ans = 0;
    lint sum[N + 1];
    sum[0] = 0;
    for(int i = 0; i < N; i++){
        sum[i + 1] = sum[i] + A[i];
    }
    for(auto i: A_kind){
        lint num = i.first;
        int pos = int(upper_bound(A, A + N, num) - A - 1);
        if(pos >= N - P){
            ans += i.second;
            continue;
        }
        if(num + M < A[P - 1]){
            continue;
        }
        if(pos >= V - 1){
            if(num + M >= A[P - 1]){
                ans += i.second;
            }
            continue;
        }
        lint allow = (P - 1) * M + (pos + 1) * M;
        allow += (N - P - pos) * (num + M) - (sum[N - P + 1] - sum[pos + 1]);
        if(allow >= M * V){
            ans += i.second;
        }
    }
    cout << ans << endl;
}

