int main()
{
    long N, M, V, P;
    std::cin >> N >> M >> V >> P;
    std::vector<long> score(N);
    for(int i = 0; i < N; ++i) std::cin >> score[i];
    std::sort(score.begin(), score.end(), std::greater<long>());

    std::map<long , long> ct;
    for(int i = 0; i < N; ++i) ++ct[score[i]];

    long possibleProb = V;
    long count = 0;
  	long idx = N-1;
    long limit = score[P-1];
    for(auto it = ct.begin(); it != ct.end(); ++it){
        possibleProb -= it->second;
      	idx -= it->second;
        if(possibleProb < P){
            if(it->first + M >= limit) count += it->second;
        }
        else{
          long long newLimit = it->first + M;
          long long newLimitMem = (possibleProb - P) * M;
          long long maxMem = 0;
          for(long i = P-1; i <= idx; ++i){
          	maxMem += newLimit - score[i];
          }
          if(maxMem <= newLimitMem) count += it->second;
        }
    }
    std::cout << count << std::endl;
    return 0;
}

