void Main()
{
    ll n = in(), m = in(), v = in(), p = in();
    vll a = in(n);
    sort(ALL(a));

    ll ok = 1000000000;
    ll ng = -1;

    DUMP(a);
    const auto is_ok = [&](ll score) {
        DUMP(score);
        auto score_itr = upper_bound(ALL(a), score);
        ll score_pos = score_itr - a.begin();

        DUMP(score_pos);
        if (p > n - score_pos)
        {
            return true;
        }
        if (score_pos - 1 + (p - 1) >= v - 1 && score + m >= a[n - p])
        {
            return true;
        }

        if (score < 5)
            DUMP("AA");

        ll cnt = 0;
        for (ll i = score_pos; i < v - (p - 1); ++i)
        {
            cnt += a[i] - score;
        }
        ll cur_score = score + m;

        bool ret = false;
        for (ll i = v - (p - 1); i < n - (p - 1); ++i)
        {
            if (cur_score <= a[i])
                break;
            cnt -= min(cur_score - a[i], m);
            if (cnt <= 0)
            {
                ret = true;
                break;
            }
        }
        return ret;
    };

    while (abs(ok - ng) > 1)
    {
        ll mid = (ok + ng) / 2;
        (is_ok(mid) ? ok : ng) = mid;
    }
    DUMP(ok);
    DUMP(a);
    auto itr = lower_bound(ALL(a), ok);
    ll ans = n - (itr - a.begin());
    cout << ans << endl;
}

