  int l = 1, r = n;
  while (l < r) {
    int mid = (l + r + 1) / 2;
    int mx = a[n - mid] + m;
    int64 votes = m * 1ll * (v - 1);
    int above = 0;
    for (int i = n - 1; i >= 0 && votes >= 0; --i) {
      if (i == n - mid) {
