ll N, M, V, P;

bool isOK(vector<ll> A, ll key) {
    A[key] += M;
    ll tmp = A[key];
    ll nokori = M * (V - 1);
    if (nokori >= N - 1) {
        int amari = nokori % nokori;
        nokori /= N - 1;
        rep(i, N) {
            if (i == key)
                continue;
            else
                A[i] += nokori;
        }

        for (int i = N - 1; i > -1; i--) {
            if (i == key)
                continue;
            A[i] += 1, amari--;
            if (amari == 0)
                break;
        }
    } else {
        for (int i = N - 1; i > -1; i--) {
            A[i] += 1, nokori--;
            if (nokori == 0)
                break;
        }
    }

    sort(all(A), greater<ll>());
    set<int> se;
    rep(i, N) {
        se.insert(A[i]);
        if (A[i] == tmp)
            break;
    }

    if (se.size() <= P)
        return true;
    else
        return false;
}

int main() {
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    rep(i, N) { cin >> A[i]; }

    sort(all(A));
    int ng = -1, ok = N;
    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        if (isOK(A, mid))
            ok = mid;
        else
            ng = mid;
    }

    cout << N - ok << endl;
}

