using namespace std;

void solve() {
  int64_t N, num_judge, num_sel, num_pass;
  cin >> N >> num_judge >> num_sel >> num_pass;
  vector<int64_t> scores(N);
  for (int64_t i = 0; i < N; ++i) {
    cin >> scores[i];
  }
  sort(scores.begin(), scores.end());
  int64_t can_pass = num_pass - 1;
  num_sel = max((int64_t)0, num_sel - num_pass);
  scores.resize(scores.size() - num_pass + 1);




  vector<int64_t> inte(scores.size() + 1);
  for (size_t i = 0; i < scores.size(); ++i) {
    inte[i + 1] = inte[i] + scores[i];
  }
  for (auto it = scores.begin(); it != scores.end(); ++it) {
    auto score = *it + num_judge;
    if (score < scores.back()) continue;
    auto idx = it - scores.begin();
    auto right = scores.end() - it - 1;
    auto sel = max((int64_t)0, num_sel - idx);
    // cerr << " sel " << sel << endl;
    auto right_area = inte.back() - inte[idx + 1];
    // cerr << " right_area " << right_area << endl;
    auto mass = sel * num_judge + right_area;
    // cerr << " mass " << mass << endl;
    auto height = mass ? (mass - 1) / right + 1 : 0;
    height = max(height, scores.back());
    if (height <= score) {
      // cerr << "### PASS ### : " << *it << " h " << height << " sc " << score<<endl;
      ++can_pass;
    } else {
      // cerr << "### NO   ### : " << *it << " h " << height << " sc " << score<<endl;
    }
  }
  cout << can_pass << endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  solve();
}

