struct BipartiteMatching
{
    vector<vector<int>> graph;
    vector<int> match, alive, used;
    int timestamp;

    BipartiteMatching(int n) : graph(n), alive(n, 1), used(n, 0), match(n, -1), timestamp(0) {}

    void add_edge(int u, int v)
    {
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    bool dfs(int idx)
    {
        used[idx] = timestamp;
        for (auto &to : graph[idx])
        {
            int to_match = match[to];
            if (alive[to] == 0)
                continue;
            if (to_match == -1 || (used[to_match] != timestamp && dfs(to_match)))
            {
                match[idx] = to;
                match[to] = idx;
                return true;
            }
        }
        return false;
    }

    int bipartite_matching()
    {
        int ret = 0;
        for (int i = 0; i < graph.size(); i++)
        {
            if (alive[i] == 0)
                continue;
            if (match[i] == -1)
            {
                ++timestamp;
                ret += dfs(i);
            }
        }
        return ret;
    }

    void output()
    {
        for (int i = 0; i < graph.size(); i++)
        {
            if (i < match[i])
            {
                cout << i << "-" << match[i] << endl;
            }
        }
    }
};

ll N, M, V, P;
ll A[100010];
pair<ll, ll> B[100010];
bool C(ll idx)
{
    for (int i = 0; i < N; i++)
    {
        B[i] = make_pair(A[i], i);
    }

    //cout << N << " " << M << " " << V << " " << P << endl;
    B[idx].first += M;

    ll nokori_V = V - 1;
    sort(B, B + N);

    ll nidx = 0;
    ll val = 0;
    for (int i = 0; i < N; i++)
    {
        if (B[i].second == idx)
        {
            nidx = i;
            val = B[i].first;
            break;
        }
    }

    ll bigger = 0, equal = 0;
    for (int i = 0; i < N; i++)
    {
        if (i == nidx)
            continue;

        if (val < B[i].first)
        {
            bigger++;
        }
        if (val == B[i].first)
        {
            equal++;
        }
    }

    if (bigger >= P)
        return false;
    ll times = M;
    ll nokori_P = P - bigger - 1;

    times += bigger * M;

    if (nokori_P <= equal)
    {
        nokori_P = 0;
        times += nokori_P * M;

        for (int i = 0; i < N; i++)
        {
            if (val == B[i].first)
                break;
            times += min(M, val - B[i].first);
        }
    }
    else
    {
        nokori_P -= equal;
        times += equal * M;

        for (int i = N - 1; i >= 0; i--)
        {
            if (val <= B[i].first)
                continue;

            if (min(M, val - B[i].first) == M)
            {
                times += M;
            }
            else
            {
                if (nokori_P)
                {
                    times += M;
                    nokori_P--;
                }
                else
                {
                    times += val - B[i].first;
                }
            }
        }
    }

    //cout << idx << " " << times << " " << M << endl;

    if (times / V >= M)
    {
        return true;
    }
    else
    {
        return false;
    }
}
