    cin >> N >> M >> V >> P;
    for (int i = 0; i < N; i++)
    {
        cin >> A[i];
    }
    sort(A, A + N);
    ll lb = -1, ub = N - 1;

    while (ub - lb > 1)
    {
        ll mid = (ub + lb) / 2;

        if (C(mid))
        {
            ub = mid;
        }
        else
        {
            lb = mid;
        }
    }
    cout << N - lb - 1 << endl;
    return 0;
}

