	long long head = left;
	long long tail = right;
	long long result = -1;
	long long mid;

	while (head <= tail)
	{
		mid = (head + tail) / 2;
		if (check(mid))
		{
			result = mid;
			head = mid + 1;			
		}
		else
		{
			tail  = mid - 1;			
		}
	}

	return result;
}

