    served += smaller_a_ct;

    if (rest <= 0) return true;

    over_index -= can_over;
    rest -= can_over * M;
    served += can_over;

    if (rest <= 0) return true;

    ll b_i = upper_bound(as.begin(), as.end(), a) - as.begin();

    for (ll ii = b_i; ii < over_index; ii++) {
      rest -= a + M - as[ii];
      served++;
    }

    return rest < 0 && served >= V;
  };

  if (check(0)) {
    cout << N << endl;
  }

  ll ng = 0;
  ll ok = N - 1;

  while (ok - ng > 1) {
    ll mid = (ng + ok) / 2;
    if (check(mid)) {
      ok = mid;
    } else {
      ng = mid;
    }
  }

  ll res = N - ok;
  cout << res << endl;

  return 0;
}

