void solve(){
  inl(N,M,V,P);
  vl a(N); in(a);
  sort(all(a),greater<>());

  auto f = [&](int n) -> bool{
    vl b = a;
    // a[i]が選ばれる場合
    // a[0] ~ a[P - 2]とa[i]に V票入れる
    rep(j,P-1) b[j] += M;
    b[n] += M;

    trc(n,b);
    ll rest = 0;
    rep(j , N){
      if(j == n) continue;
      if(j < P - 1) continue;
      if(b[n] < b[j]) return false;
      rest += min(M , b[n] - b[j]);
      trc(j , rest);
    }
    if(rest < M * (V - P)) return false;
    return true;
  };
  int ok = P - 1 , ng = N;
  while(ok + 1 < ng){
    int med = (ok + ng) / 2;
    //trc(med , f(med));
    (f(med) ? ok : ng) = med;
  }
  out(ng);

}

