ll n,m,v,p;
bool judge(ll mid)
{
    if(mid<=p)
    {
        return 1;
    }
    if(a[mid]+m<a[p])
    {
        return 0;
    }
    if(v<=p-1&&a[mid]+m>=a[p])
        return true;
    for(int i=1;i<=n;i++)
    {
        b[i]=a[i];
    }
    ll temp=0;
    for(int i=11;i<p;i++)
    {
        b[i]+=m;
        temp+=m;
    }
    ll inx=n,cnt=v-p+1;
    while(inx>mid&&cnt>1)
    {
        temp+=m;
        inx--;
        cnt--;
        b[inx]+=m;
    }
    temp+=m;
    ll now=a[mid]+m;
    ll res=m*v-temp;
    //中间还能被填多少
    for(int i=p;i<mid;i++){
        ll add=min(m,max(now-a[i],0ll));
        if(add>res)add=res;
        res-=add;
        b[i]+=add;
    }
    return now>=b[p]&&res<=0;
}
