		while (abs(ok - ng) > 1) {
			lint mid = (ok + ng) / 2;

			if (f(mid)) ok = mid;
			else ng = mid;
		}

		return ok;
	};

	// ok 見つけた後も次が同じか考える

	lint ans = binary_search(judge);
	DMP(ans);
	while (ans > 0) {
		if (a[ans] == a[ans - 1]) ans--;
