typedef long long ll;
using namespace std;
int mod = 1000000007;

int main(void){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N, M, V, P; cin >> N >> M >> V >> P;
    ll A[N]; rep(i, N) cin >> A[i];
    sort(A, A+N);
    //採用される可能性のある問題には単調性がある
    ll ok = N, ng = -1;
    ll m = (ok+ng)/2;

    ll ruiseki[N+1] = {};
    rep(i, N) ruiseki[i+1] = ruiseki[i] + A[i];

    while(abs(ok-ng) > 1){
        //A[m]は採用される可能性があるか?
        //つまりA[m]+Mは,投票後に上からP番目以内となり得るか?
        //A[m+1]からA[N-P]以上となりたい
        if(A[m]+M < A[N-P]) ng = m;
        else{
            //A[0]からA[m], A[N-1]からA[N-P+1]までは足しちゃってよい
            ll rem = M*V - (m+1)*M - (P-1)*M;
            if(rem <= 0) ok = m;
            else{
                //rem個のものをA[m+1],...,A[N-P]に対して分ける
                ll sum = ruiseki[N-P+1] - ruiseki[m+1] + rem;
                ll boarder;
                if(sum % (N-P-m)) boarder = sum/(N-P-m) + 1;
                else boarder = sum/(N-P-m);
                if(A[m]+M < boarder) ng = m;
                else ok = m;
            }
        }
        m = (ok+ng)/2;
    }
    cout << N-ok << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

int main() {
    int64_t N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<int64_t> A(N);
    for (int64_t i = 0; i < N; i++) {
        cin >> A[i];
    }

    assert(V < N - 1);

    sort(A.begin(), A.end(), greater<int64_t>());

    vector<int64_t> sum(N + 1, 0);
    for (int64_t i = 0; i < N; i++) {
        sum[i + 1] = sum[i] + A[i];
    }

    int64_t ans = 0;
    set<int64_t> ok;
    for (int64_t i = 0; i < N; i++) {
        //i番目のものが選ばれうるか

        //そもそも上位P個は大丈夫
        if (i < P) {
            ans++;
            ok.insert(A[i]);
            continue;
        }

        //最適な割り振りは「上位P - 1個まで + 自分より下位」に選ぶ
        //余ったやつが問題
        int64_t rem_vote = V - (P - 1) - (N - i);

        if (rem_vote <= 0) {
            //届くかどうか
            if (A[i] + M >= A[P - 1]) {
                ok.insert(A[i]);
                ans++;
            }
            continue;
        }

        //rem_voteがM回発生する
        //それを[P - 1, i)までに割り振ることになる
        //j in [P - 1, i)としてA[j]が受け取れる回数はM + A[i] - A[j]
        //これの和なのでnum * (M + A[i]) - sum[P-1 ~ i)_A
        int64_t num = i - (P - 1);

        int64_t capacity = num * (M + A[i]) - sum[i] + sum[P - 1];
        if (capacity >= rem_vote * M) {
            ans++;
        }
    }

    cout << ans << endl;
}

