#define RPT(i, b, e) for (int i = (b); i <= (e); i++)
#define RPT0(i, n) RPT(i, 0, n - 1)
#define RPT1(i, n) RPT(i, 1, n)

int N, M, V, P;
int ans;

void resolve()
{
    cin >> N >> M >> V >> P;
    vector<int> A;
    RPT1(i, N)
    {
        int tmp;
        cin >> tmp;
        A.push_back(tmp);
    }

    sort(A.begin(), A.end(), greater<int>());

    int Z;
    if (V >= P) {
        int X = V - P + 1;
        vector<int> B;
        RPT(i, P - 1, N - 1) B.push_back(A[i]);

        RPT1(i, M)
        {
            RPT0(j, X) B[N - P - j] += 1;
            sort(B.begin(), B.end(), greater<int>());
        }

        Z = B[0];

    } else {
        Z = A[P - 1];
    }

    ans = N;
    RPT0(i, N) if (A[i] + M < Z) ans--;

    cout << ans << endl;
}

