using namespace std;

typedef long long ll;

const int INF = 1 << 30;
const ll LLINF = 1LL << 60;

int mod = 1000000007;

int main(void){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N, M, V, P; cin >> N >> M >> V >> P;
    ll A[N]; rep(i, N) cin >> A[i]; sort(A, A+N);
    int ok = N, ng = -1;
    int m = (ok+ng)/2;
    while(abs(ok-ng) > 1){
        //A[m]は採用されうるか
        ll eval = A[m]+M;
        if(m >= N-P) ok = m;
        else if(eval >= A[N-P]){
            ll distribute = M*V;
            distribute -= M*((m+1) + (P-1));
            if(distribute <= 0) ok = m;
            else{
                //A[m+1]からA[N-P]までにdistributeを均等になるように配る
                ll acc = 0;
                for(int i = m+1; i <= N-P; i++) acc += A[i];
                acc += distribute;
                ll res = (acc + (N-P-m - 1))/(N-P-m);
                if(eval >= res) ok = m;
                else ng = m;
            }
        }
        else ng = m;
        m = (ok+ng)/2;
    }
    cout << N-ok << endl;
    return 0;
}

