template <typename T>
vector<T> gauss_jordan(const vector<vector<T>> &A, const vector<T> &b)
{
    int n = A.size();
    vector<vector<T>> B(n, vector<T>(n + 1));

    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            B[i][j] = A[i][j];
        }
    }

    for (int i = 0; i < n; ++i)
        B[i][n] = b[i];

    for (int i = 0; i < n; ++i)
    {
        int pivot = i;
        for (int j = i; j < n; ++j)
        {
            if (abs(B[j][i]) > abs(B[pivot][i]))
                pivot = j;
        }
        swap(B[i], B[pivot]);

        if (abs(B[i][i]) < EPS)
            return vector<T>(); //解なし

        for (int j = i + 1; j <= n; ++j)
            B[i][j] /= B[i][i];
        for (int j = 0; j < n; ++j)
        {
            if (i != j)
            {
                for (int k = i + 1; k <= n; ++k)
                    B[j][k] -= B[i][j] * B[i][k];
            }
        }
    }

    vector<T> x(n);

    for (int i = 0; i < n; ++i)
        x[i] = B[i][n];
    return x;
}

