int jud(int x){
	ll cnt=a[x]+m;
	if(cnt<a[n-p+1]) return 0;
	if(v<=p-1+x) return 1;
	ll tmp=v-(p-1+x);
	if(tmp>=n-p+1-x) return 0;
	//while(!q.empty()) q.pop();
	vector<ll> v,pre;
	ll cap=0;
	ll su=0;v.clear();pre.clear();
	for(int i=n-p+1;i>=x+1;i--){
		if(cnt-a[i]){
			cap++;
			su+=cnt-a[i];
			v.push_back(cnt-a[i]);
			pre.push_back(su);
		} 
	}
	if((int)v.size()<tmp) return 0;
	su=0;
	ll r=0;
	for(int i=0;i<(int)v.size()-tmp;i++){
		r+=v[i];
	}
	ll ta=0;ll pt=0;
	for(int i=(int)v.size()-tmp;i<(int)v.size();i++){
		pt++;
		if(i==(int)v.size()-1){
			ta=max(ta,r/pt+v[i]);
		}
		else{
			ll ub=v[i+1];
			ta=max(ta,min(v[i+1],v[i]+r/pt));
			if(pt*(ub-v[i])>r) break;
			r-=pt*(ub-v[i]);
		}
	}
	return ta>=m;

}
