long long N, M, V, P;
std::vector<long long > A;

bool judge(long long n){
  if (n<P){
    return true;
  } else if (A[n]+M<A[P-1]){
    return false;
  }
  long long sum = 0;
  for (int i=P-1; i<N; i++){
    if (i==n){
      continue;
    }
    sum += std::min(M, A[n]+M-A[i]));
  }
  if (sum >= (long long)M*(V-P)){
    return true;
  } else {
    return false;
  }
}

int main(){
  scanf("%lld", &N);
  scanf("%lld", &M);
  scanf("%lld", &V);
  scanf("%lld", &P);
