Int N, M, V, P;
vector<Int> A;

bool isOK(Int i) {

	Int temp = 0;
	temp += M * (P - 1);

	if (A[i] + M < A[N - P]) {
		return false;
	}
	temp += M * (i + 1);
	for (Int j = i + 1; j <= N - P; j++) {
		temp += A[i] + M - A[j];
	}

	return temp >= V * M;
}

Int binary_search() {
	Int ng = -1;
	Int ok = N-P; 

	while (abs(ok - ng) > 1) {
		Int mid = (ok + ng) / 2;

		if (isOK(mid)) ok = mid;
		else ng = mid;
	}
	return ok;
}

