// 処理
void Solve()
{
	ll N, M, V, P;
	cin >> N >> M >> V >> P;
	vector<ll> A(N);
	REP(i, N) {
		cin >> A[i];
	}
	sort(ALL(A));
	auto compExec = [&](ll mid)
	{
		ll addVal = A[mid] + M;
		ll nokoriNum = N - P - mid - 1;
		ll diffSum = 0;
		for (int i = mid + 1; i < N - P; i++) {
			if (A[i] < addVal) {
				diffSum += addVal - A[i];
			}
		}
		ll kubaruNum = V - P - mid;
		return (diffSum < kubaruNum * M);
	};

	ll lb = 0;
	ll lu = N;
	ll mid = 0;
	while ((lb + 1) != lu) {
		mid = (lb + lu) / 2;
		if (compExec(mid)) {
			lb = mid;
		} else {
			lu = mid;
		}
	}

	cout << N - lu << endl;
}

