#define ALL(v) v.begin(), v.end()
using namespace std;
typedef long long ll;
typedef long double ld;

int n,m,v,p;
vector<ll> a;

bool solve(int x)
{
	int bigger = 0;
	int less = 0;
	int other = 0;
	REP(i,n) if(i!=x){
		if(a[i] > a[x]+m) bigger++;
		else if(a[i] <= a[x]) less++;
		else other++;
	}
	if(p<=bigger) return false;
	int rest = v-1 - bigger - less;
	if(rest<=0) return true;

	ll to = 0;
	int cnt = 0;
	REP(i,n) if(a[x] < a[i] && a[i] <= a[x] + m){
		to += a[x] + m - a[i];
		cnt++;
		int ok = min(to/m, (ll)min(other, rest));
		int ng = rest - ok;
		if(bigger+ng < p && cnt+ng <= other){
			return true;
		}
	}
	return false;
}

