int main()
{
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<ll> a(n);
    for(int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    ll h = n;
    ll l = -1;
    while(h - l > 1)
    {
        ll mid = (h+l) >> 1;
        ll score = a[mid];
        ll stock = m*v;
        score += m;
        stock -= m;
        ll cnt = 0;
        bool flag = true;
        priority_queue<ll> que;
        for(int i = 0; i < n; i++)
        {
            if(i == mid) continue;
            if(a[i] < score)
            {
                ll del = min(score-a[i], m);
                stock -= del;
                que.push(m-del);
            }
            else if(a[i] > score)
            {
                cnt++;
                if(cnt == p)
                {
                    flag = false;
                    break;
                }
                else
                {
                    stock -= m;
                }
            }
        }

        if(!flag)
        {
            l = mid;
        }
        else
        {
            ll num = p-1-cnt;
            while(num > 0)
            {
                if(que.empty()) break;
                ll sc = que.top();
                que.pop();
                stock -= sc;
                num--;
            }
            if(stock <= 0) h = mid;
            else l = mid;
        }
    }
    cout << n-h << endl;
