    long long idx_upper = distance(a.begin(), iter_upper);
    long long cnt = n - idx_upper;//a[i] + mより大きい要素数。
    //cout<<cnt<<endl;
    if(cnt >= p){
      continue;
    }
    long long j = idx_upper - 1;
    long long temp;
    if(j-i >= p-1-cnt){
      temp = m * (i + p - 1) + (a[i] + m) * (j + cnt - p - i + 1) - (s[j+cnt+1-p] - s[i]);
    }else{
      temp = m * (j + cnt);
    }
    if(temp >= m*(v-1)){
      r = i;
    }else{
      l = i;
    }
  }
  long long ans;
  if(r == -1){
    ans = n;
  }else{
    ans = n - r;
  }
  cout<<ans<<endl;
  return 0;
}

