#define int long long
using namespace std;
const int maxn=110000;
const int inf=10000000000000000;
int n,m,v,p;
int a[maxn];
int sum[maxn];
int Ca(int l,int r)
{
	int L=lower_bound(a+1,a+n+1,l)-a;
	int R=upper_bound(a+1,a+n+1,r)-a;
	R--;
	if(L>R) return 0;
	return R-L+1;
}
int Cal(int l,int r)
{
	int L=lower_bound(a+1,a+n+1,l)-a;
	int R=upper_bound(a+1,a+n+1,r)-a;
	R--;
	if(L>R) return 0;
	return sum[R]-sum[L-1];	
}
int Ch(int l,int r,int num)
{
	int cnt=r-l+1;
	cnt=cnt*m+(sum[r]-sum[l-1])-num*cnt;
	return cnt;
}
int Calc(int cost,int num,int l,int r)
{
	int L=lower_bound(a+1,a+n+1,l)-a;
	int R=upper_bound(a+1,a+n+1,r)-a;
	R--;
	r=R;
	if(L>R) return inf;
	int best=-1;
	while(L<=R)
	{
		int mid=(L+R)/2;
		if(Ch(mid,R,num)>=cost) best=mid,L=mid+1;
		else R=mid-1;
	}
	if(best==-1) return inf;
	return r-best+1;
}
signed main()
{
	scanf("%lld%lld%lld%lld",&n,&m,&v,&p);
	for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
	sort(a+1,a+n+1);
	for(int i=1;i<=n;i++) sum[i]=sum[i-1]+a[i];
	int cnt=0;
	for(int i=1;i<=n;i++)
	{
		int mrak=Ca(a[i]+m+1,inf);
		int cost=m*v;
		cost-=Ca(-inf,a[i])*m;
		cost-=mrak*m;
		cost-=(a[i]+m)*Ca(a[i]+1,a[i]+m)-Cal(a[i]+1,a[i]+m);
		if(cost>0) mrak+=Calc(cost,a[i]+m,a[i]+1,a[i]+m);
		if(mrak+1<=p) cnt++; 
	}
	printf("%lld\n",cnt);
	return 0;
}

