	int mx = A[idx] + M;

	for (int i = idx + 1; i <= N - P; ++i) {
		zan -= max(mx - A[i], 0ll);
	}

	return zan <= 0;
}

signed main()
{
	cin >> N >> M >> V >> P;
	rep(i, 200100) A[i] = inf;
	rep(i, N) cin >> A[i];
	sort(A, A + N);

	int lo = -1, hi = N - 1;

	int cnt = 0;

	while (hi - lo > 1) {
		int mid = (hi + lo) / 2;

		if (check(mid)) {
			hi = mid;
		} else {
			lo = mid;
		}

		cnt++;
	}

	cout << N - hi << endl;
}

