int main()
{
    ll N,M,V,P,res;
    cin >> N >> M >> V >> P;
    vector <ll> a(N);
    REP(i, N)cin >> a[i];
    sort(a.rbegin(),a.rend());

    //まず、降順にならべる
    //自分よりすでに下の部分の数を知りたい

    //自分よりめちゃくちゃ票を持っている人にいくら票が入ろうが問題ない
    //-> 現時点で何位か
    //-> P位以内に入るには、何票はいるか
    //まず、+MでP位以内に入るか
    //入るなら、Vを上位と下位に割り振ってがどこまで削れるか
    //残り(例:V = 3)をいい感じに割り振って、P位以内に入るか
