    //

    int point = a[P-1];

    ll wa = a[P-1];
    res = P;
    //0-indexd
    for(int i = P; i < N; ++i)
    {
        //おわり
        if(a[i] + M < point)break;
        //上位下位
        if(V <= P-1 + N-i)
        {
            ++res;
        }
        else
        {
            ll zan = V - (P-1) - (N-i);
            ll ke = M + a[i];
            //cout << zan << endl;
