// -----------------------------------------------------------------------------
struct PrefSum {
    vl s;
    PrefSum(vl a) {
        s.assign(isz(a) + 1, 0);
        for (int i = 0; i < isz(a); i++) {
            s[i+1] = s[i] + a[i];
        }
    }
    ll operator()(ll i, ll j) const {
        assert(0 <= i && i <= j && j+1 < isz(s));
        return s[j+1] - s[i];
    }
};
