    int ok = p-1;
    int ng = n;
    while(ng-ok>1){
        int mid = (ok+ng)/2;
        int K = v-p+1-(n-mid);
        // cerr << v << " " << p-1 << " "<< mid << endl;
        if(a[mid]+m<a[p-1]){
            ng = mid;
            continue;
        }
        if(K<0){
            ok = mid;
            continue;
        }
        vector<ll> s;
        for(int i=p;i<mid;i++){
            s.push_back(a[mid]+m-a[i]);   
        }
        bool flag = false;
        int sm = 0;
        ll res = 0;
        for(auto x:s){
            if(x<0){
                flag = 1;
            }else{
                res += x;
            }
        }
        int M = s.size();
        //cerr << mid << " " << res << " " << m*K << endl;

        if(flag){
            ng = mid;
            continue;
        }

        if(res >= m*K ){
            ok = mid;
        }else{
