int main(){
	int n,m,v,p;
	cin >> n >> m >> v >> p;
	vector<int> a(n);
	for(int i=0; i<n; i++){
		cin >> a[i];
	}
	sort(a.begin(), a.end());
	auto csum = a;
	for(int i=0; i<n-1; i++){
		csum[i+1] += csum[i];
	}

	int ans = 0;
	for(int i=0; i<n; i++){
		//cerr << "i = " << i << endl;
		int ubidx = upper_bound(a.begin(), a.end(), a[i]+m) -a.begin();
		if(n -ubidx >= p){
			continue;
		}
		int sidx = upper_bound(a.begin(), a.end(), a[i]) -a.begin();
		if(n -sidx < p){
			ans++;
			continue;
		}
		int unbeatable = n -ubidx;
		if(p-unbeatable > 0){
			ubidx -= p-unbeatable;
		}
		int rem = v -(n-ubidx) -sidx;
		//cerr << ubidx << " " << sidx << " " << rem << endl;
		if(rem <= 0){
			ans++;
			continue;
		}
		int remnum = ubidx - sidx;
		if(remnum <= rem){
			continue;
		}
		int remcap = rem*m -(csum[ubidx-1] -csum[sidx-1]);
		if(remcap >= 0){
			ans++;
		}
	}
	cout << ans << endl;
	return 0;
}

