bool f(const vector<int>& A, int index, int P, int VV, int M) {
	if (index < P) {
		return true;
	}
	int target = A[index];
	vector<int> req;
	FOR(i, P-1, index) {
		req.push_back(A[i] - target);
	}
	sort(ALL(req), greater<int>());

	int su = 0;
	int res = 0;
	queue<pair<int, int> > que;
	REP(i, req.size()) {
		if (not que.empty() and que.front().first == i) {
			su -= que.front().second;
			que.pop();
		}
		if (req[i] - su > 0) {
			res += req[i] - su;
			que.emplace(i + VV, req[i] - su);
			su += req[i] - su;
		}
	}
	return res <= M;
}

void solve() {
	int N, M, V, P; cin >> N >> M >> V >> P;
	vector<int> A(N); for (auto& a : A) cin >> a;
	sort(ALL(A), greater<int>());
	int ok = 0;
	int ng = A.size();
	int VV = N - V;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if (f(A, mid, P, VV, M)) ok = mid;
		else ng = mid;
	}
	cout << ok + 1 << endl;
}

