int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);		//DON'T USE scanf/printf/puts !!
	cout << fixed << setprecision(20);

	ll N,M,K,P; cin >> N >> M >> K >> P;
	V<ll> A(N); rep(i,N) cin >> A[i];
	sort(all(A));
	auto can = [&](int i){
		if(N-i <= P) return true;
		ll t = A[i]+M;
		ll f = 0;
		rep(j,N-P) if(j != i){
			if(t < A[j]) return false;
			f += min(t-A[j],M);
		}
		return f >= (K-P)*M;
	};
	int lb = -1, ub = N;
	while(ub-lb>1){
		int m = (lb+ub)/2;
		if(can(m)) ub = m;
		else lb = m;
	}
	cout << N-ub << endl;
}

