const int MAX_N=1e6+1;
LL A[MAX_N];
int N,M,V,P;

bool ok(int m) {
  vector<LL> as(A,A+N);
  int v=0;
  REP(i,P-1) if(v<V-1) as[i]+=M,++v;
  int i=N-1;
  for(; i>=0&&v<V-1&&as[i]<=as[m]; --i) if(i!=m) {
    as[i]+=M,++v;
  }
  as[m]+=M,++v;
  LL rem=(V-v)*M;
  if(i==m) --i;
  if(i-(P-2)<=V-v) return false;
  while(rem>0&&i>P-2) {
    LL x=min(as[m]-as[i],rem);
    rem-=x,as[i]+=x;
    --i;
  }
  //dump(p,rem,i,as[P-1],as[p]);
  //dumpc(as);
  if(rem>0) return false;
  else return as[m]>=as[P-1];
}
void solve() {
  sort(A,A+N),reverse(A,A+N);
  //dumpC(A,A+N);
  int good=P-1,bad=N;
  while(abs(good-bad)>1) {
    int mid=(good+bad)/2;
    bool res=ok(mid);
    //dump(mid,res);
    (res?good:bad)=mid;
  }
  cout<<good+1<<endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>N>>M>>V>>P;
  REP(i,N) cin>>A[i];
  solve();

  return 0;
}

