bool fanc(int mid, vector<int> &a, int n, int m, int v, int p){
	vector<int> ot;
	if(mid < p) return true;
	rep(i, n){
		if(i == mid) continue;
		ot.push_back(a.at(i));
	}
	ll now = a.at(mid);
	now += m;
	if(now < ot.at(p-1)) return false;
	ll add = (ll)m * (v-1);
	rep(i, n-1){
		if(i < p-1) add -= m;
		else{
			add -= min((ll)m, now - ot.at(i));
		}
	}
	// cerr << "t " << mid << " " << add << " " << now << endl;
	if(add > 0) return false;
	else return true;
}

