const int MAX = 1e5+10;

ll N, M, V, P;
ll A[MAX];

bool check(int n) {
    int v = V - (P-1) - (N-n);
    // cout << n << " " << v << endl;
    if (v < 0) return true;

    int y = A[n] + M;

    if (A[P-1] > y) return false;
    ll z = 0;
    FOR (i, P-1, n) {
        z += y - A[i];
    }
    // cout << "n = " << n << ", v = " << v << ", y = " << y << ", z = " << z << ", Mv = " << M * v << endl;
    return z >= M * v;
}

ll solve() {
    sort(A, A+N); reverse(A, A+N);
    ll ok = 0, ng = N-1;
    while (ng - ok > 1) {
        ll mid = (ok + ng) / 2;
        if (check(mid)) ok = mid;
        else ng = mid;
    }
    return ok+1;
}

