const int CASES = 3;

ll n, m, v, p;
vector<ll> a;

bool check(ll i){
    ll rival = a[n-p];
    ll norival = 0; // 無駄に選択する数
    for(int j = 0; j < n; ++j){
        if(a[j] <= a[i] || rival < a[j]){
            ++norival;
        }
    }
    ll rem = v - norival -1 ; // v個の残り
    ll range = n - norival - 1; // +1しなきゃいけない範囲
    ll unselect = range-rem; // 1回あたり選ばなくていい数

    if(rem <= 0 && a[i] + m >= rival){return true;}

    ll count = 0;
    for(int j = i + 1; j < n; ++j){
        if(rival < a[j]){
            continue;
        }
        count += (a[j] - a[i]);
    }

    if(count > unselect * m){
        return false;
    }
    return true;
}

void solve() {
    cin >> n >> m >> v >> p;
    a.resize(n);
    for(int i = 0; i < n; ++i){
        cin >> a[i];
    }

    sort(a.begin(), a.end());

    ll lb = 0, ub = n-1;
    while(ub - lb > 1){
        ll mb = (lb + ub) / 2;
        if(check(mb)){
            ub = mb;
        }else{
            lb = mb;
        }
    }
    cout << n-ub << endl;
}

