const ll MOD = 1e9+7;

ll N, M, V, P;
vector<ll> A;

//[left, right)
bool solve(ll n, ll left, ll right, int rem){
    ll val = rem * M;
    for(int i = left; i < right; i++){
        ll a = A[i];
        ll sub = 0;
        chmax(sub, min(n - a, M));
        val -= sub;
    }

    if(val <= 0) return true;
    else return false;
}

bool search(int idx){
    int free = (P-1) + (N-idx);
    int rem = V - free;
    ll num = 0;
    if(rem <= 0){
        num = A[P-1];
    }
    else{
        //ll left = A[idx];
        //ll right = 1e17;
        ll left = 0;
        ll right = 1e18;
        //ll right = 10;
        while(right - left > 1){
            ll mid = (right + left) / 2;
            bool valid = solve(mid, P-1, idx, rem);
            if(valid) right = mid;
            else left = mid;
        }
        num = right;
    }


    if(A[idx] + M >= num)
        return true;
    else
        return false;
}

int main(){
    cin >> N >> M >> V >> P;
    A.resize(N);
    REP(i,N){
        cin >> A[i];
    }

    sort(A.rbegin(), A.rend());

    ll ans = 0;

    int left = 0;
    int right = N;
    //int left = 6;
    //int right = 8;
    while(right - left > 1){
        int mid = (left+right)/2;
        bool valid = search(mid);
        if(valid) left = mid;
        else right = mid;
    }

    ans = left+1;
    cout << ans << endl;
    return 0;
}

