int main() {
	int n, m, v, p; scanf("%d%d%d%d", &n, &m, &v, &p);
	std::vector<int> a(n);
	for(int i = 0; i < n; i++) scanf("%d", &a[i]);
	sort(begin(a), end(a));

	auto check = [&](int t) {
		int val = a[t] + m, nv = v, L = 1 << 30, R = -1;
		for(int i = 0; i < n; i++) {
			nv -= (a[i] <= a[t] or val < a[i]);

			if(a[t] < a[i]) L = std::min(L, i);
			if(a[i] <= val) R = std::max(R, i);
		}
		if(n - R - 1 >= p) return false;
		if(nv <= 0) return true;

		int add = m;
		std::vector<int> b = a;
		for(int i = L + nv - 1; i < R; i += nv) {
			int diff = val - a[i];

			add -= diff;
			for(int j = i - nv + 1; j < i + 1; j++) b[i] += diff;
		}

		int np = n - R - 1;
		for(int i = L; i < L + nv; i++) {
			if(b[i] + add > val) np++;
		}
		return np < p;
	};

	int ok = n - 1, ng = -1;
	while(std::abs(ok - ng) > 1) {
		int mid = (ok + ng) >> 1;

		if(check(mid)) ok = mid;
		else ng = mid;
	}

	printf("%d\n", n - ok);
	return 0;
}

