bool f(int x) {
    if (x < p) return true;
    if (a[x] + m < a[p]) return false;

    ll res = 0;
    rep(i, n) {
        if (i < p - 1 || i >= x) res += m;
        else res += a[x] + m - a[i];
    }

    return res >= m * v;
}

