  map<ll, ll> fir, cnt;
  rrep(i, n)fir[a[i]] = i;
  rep(i, n)cnt[a[i]]++;
  int res = 0;
  ll sum = 0;
  //cerr << a << endl;
  irep(itr, cnt){
    sum += itr->second;
    bool ok = false;
    if(n - sum <= p - 1)ok = true;
    else if(sum >= v){
      int idx = upper_bound(whole(a), itr->first + m) - a.begin();
      if(n - idx >= p)ok = false;
      else ok = true;
    }else{
      int idx = upper_bound(whole(a), itr->first + m) - a.begin();
      if(n - idx >= p)ok = false;
      else{
        ll len = (n - 1 - (p - 1)) - (fir[itr->first] + itr->second - 1);
        ll box = acc[n - 1 - (p - 1)] - acc[fir[itr->first] + itr->second - 1];
        if(len * (itr->first + m) - box >= m * (v - sum - (p - 1)))ok = true;
        else ok = false;
      }
    }
    if(ok)res += itr->second;
  }
  cout << res << endl;
  return 0;
}

