    for(int j = 0; j < n; ++j){
        if(a[j] <= a[i] || rival < a[j]){
            ++norival;
        }
    }
    ll rem = v - norival -1 ; // v個の残り
    ll range = n - norival - 1; // +1しなきゃいけない範囲
    ll unselect = range-rem; // 1回あたり選ばなくていい数

