const int N = 100005;
int a[N];
int n, m, v, p;

void init() {
    scanf(IIII,&n,&m,&v,&p);
    rep (i,n) scanf(I,&a[i]);
    sort(a, a+n); 
    rep (i,n) ses(a[i]); see("");
}

int b[N];
bool jury(int u) {
    rep (i,n) b[i] = a[i];
    b[u] += m;
    sort(b, b+n);
    int id = 0;
    rep (i,n) if (b[i] == a[u] + m) id = i;
    if (n-id > p) return 0;
    int sp = (p-1) * m;
    rep (i,n-p) {
        sp += min(m, b[id] - b[i]);
    }   
    if (sp >= m*(v-1)) return 1;
    return 0;
}

void solve() {
    int l=0, r=n-1;
    while (l<r) {
        int m = (l+r) / 2;
        ses(m);see(jury(m));
        if (jury(m)) {
            r = m;
        } else {
            l = m+1;
        }
    }
    printf(IN,n - l);
}

