    ll s = M * (V - 1);
    vector<ll> v(N, 0);
    REP(i, N) {
        if (i == n)
            continue;
        ll m = std::min({M, s, std::max(0LL, A[n] + M - A[i])});
        v[i] += m;
        s -= m;
    }
    for (ll i = N - 1; i >= 0; --i) {
        if (i == n)
            continue;
        ll m = std::min(s, M);
        m = std::min(m, M - v[i]);
        v[i] += m;
        s -= m;
    }
    ll p = 0;
    REP(i, N) {
        if (i == n)
            continue;
        if (v[i] + A[i] > A[n] + M)
            p++;
    }
    return p < P;
}

