bool judge(ll tar){
  tar--;
  if(A[tar]+M<A[P-1]) return false;
  if((P-1)+(N-(tar+1))>=V-1) return true;

  ll ok=A[P]+M,ng=A[tar-1];
  ll num=V-1-(P-1+N-(tar+1));
  while(abs(ok-ng)>1){
    ll mid=(ok+ng)/2;
    ll res=0;
    for(int i=P;i<tar;i++) res+=min(M,mid-A[i]);
    if(res>=M*num) ok=mid;
    else ng=mid;
  }
  if(ok<=A[tar]+M) return true;
  else return false;
}

