		for (int i = 0; i < V - P + 1; ++i) {
			ms.insert(M);
		}
		for (int i = 0; i <= N - P && ms.size(); ++i) {
			llong now = *ms.begin();
			ms.erase(ms.begin());
			now -= A[mid] + M - A[i];
			if (now > 0) {
				ms.insert(now);
			}
		}

		if (ms.size() == 0) {
			ok = mid;
		}
		else {
			ng = mid;
		}
	}

	cout << N - ok << endl;


	return 0;
}

