const int INF = 1LL << 29;
const ll LONGINF = 1LL << 60;
const ll MOD = 1000000007LL;

int main() {
    ll N, M, V, P; cin >> N >> M >> V >> P;

    vector<ll> A(N);
    for(int i=0; i<N; i++) cin >> A[i];
    sort(A.rbegin(), A.rend());

    vector<ll> B(N);
    int ub = N, lb = -1;
    while(ub - lb > 1) {
        int mid = (ub + lb) / 2;

        // mid 番目の問題は P 位以内に入るか？
        ll target = A[mid] + M;

        // target よりも大きい要素の数が P-1 以下ならおっけー
        ll rem = M * (V - 1);
        B = A; B[mid] = target;

        vector< pair<ll, ll> > vote;
        for(int i=0; i<N; i++) {
            // なにもしない
            if(i == mid) {
                vote.emplace_back(B[i], M);
                continue;
            }

            // 最初から超えているので M 票全部振る
            if(B[i] > target) {
                ll diff = min(rem, M);
                rem -= diff;
                B[i] += diff;
                vote.emplace_back(B[i], diff);
            }
            // 超えてないので target を超えないように追加
            // ただし最大でも min(rem, M) 票まで
            else {
                ll diff = min({target - B[i], rem, M});
                rem -= diff;
                B[i] += diff;
                vote.emplace_back(B[i], diff);
            }
        }

        // target より小さい -> rem が残ってないか M 票全部いれたかなのでこれ以上どうしようもない
        // target より大きい -> すでに M 票つかってるはずなのでどうしようもない
        // それ以外 (target と等しい) -> まだ余ってるかも (たくさん入れられるところに貪欲に入れるしかない)
        sort(vote.begin(), vote.end(), [](auto a, auto b) {
                return a.second < b.second;
            });

        for(int i=0; i<N and rem>0; i++) {
            ll diff = min(rem, M - vote[i].second);
            rem -= diff;
            vote[i].first += diff;
            vote[i].second += diff;
        }
        assert(rem == 0);

        sort(vote.rbegin(), vote.rend());        
        int cnt = 0;
        for(int i=0; i<N; i++) if(vote[i].first > target) cnt++;

        if(cnt < P) lb = mid;
        else ub = mid;
    }
    cout << ub << endl;
    return 0;
}

