		return 0;	
	v1=v-p,sum=0;
	minn=b[n-p+1];
	for(int i=1;i<=n-p;i++)
	{
		sum+=minn-b[i];
		if(minn-b[i]>=m)
			sum-=minn-b[i]-m;
	}
	if(sum<v1*m)
		return 0;
	return 1;
}
