	sort(all(A));

	auto isOK = [&](ll val) -> bool {
		if(N-P<=val){
			return true;
		}
		ll valpoint=A[val]+M;
		ll amaripoint=(V-P-val)*M;
		ll sumpoint=0;
		for(ll i=val+1;i<=N-P;i++){
			ll t=valpoint-A[i];
			if(t<0)return false;
			sumpoint+=min(M,t);
		}
		if(amaripoint>sumpoint)return false;
		return true;
	};

	if(isOK(0)){
		p(N);return;
	}

	ll left = N-1;
	ll right = 0;
	while((ll)abs(right - left) > 1) {
		ll mid = left + (right - left) / 2;
		if(isOK(mid)) left = mid;
		else right = mid;
	}

	printf("%lld\n", N-left);
}

