int N, V, M, P, A[100005];
int lo, mid, hi, best;

bool works(int x) {
  int bigger = 0;
  long long left = M * (V-1);
  for (int i = 0; i < N; i++) {
    if (i == x-1) continue;
    if (A[i] > A[x-1] + M) {
      //printf("%d\n", i);
      left -= M;
      bigger++;
    } else if (bigger < P-1) {
      left -= M;
      bigger++;
    } else {
      left -= min(M, A[x-1] + M - A[i]);
    }
    //printf("%d %d %lld %d\n", x, i, left, bigger);
  }

  return (left <= 0 && bigger <= P-1);
}

