  lo = 0, hi = N;
  while (lo <= hi) {
    mid = (lo + hi) / 2;
    if (works(mid)) {
      best = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }

  printf("%d\n", best);
