bool check(vector<ll>& A, ll N, ll M, ll V, ll P, int pos, vector<ll>& B)
{
    debug("*******check********");
    // first, make A[pos] high
    ll base = A[pos] + M;
    if (A[P-1]>base) return false;

    // get left votes
    if (V<=(N-pos)+(P-1)) return true;
    ll k = V-(N-pos)-(P-1);
    debug(pos, P-1, k);

    ll sum = B[pos] - B[P-1];
    debug(sum, M);
    debug(base * (pos-P+1), base, pos-(P-1));
    debug(sum + k*M);
    return base * (pos-P+1) >= sum + k*M;
    // return que.size()==0;
}

int main()
{
    // read input
    ll N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    rep(i, 0, N)  cin >> A[i];

    // rsort
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());

    vector<ll> B(N+1, 0);
    rep(i, 0, N) B[i+1] = B[i] + A[i];
    debug(A, B);

    // binary search 
    ll low = 0;
    ll high = N-1;
    while (low<high)
    {
        ll mid = (low+high+1)/2;
        // check
        bool is_ok = check(A, N, M, V, P, mid, B);

        if (is_ok)
            low = mid;
        else
            high = mid-1;
    }
    cout << low+1 << endl;
    return 0;
}

