long long solve() {
  long long res = p, sum = m;
  sort(a.begin(), a.end(), greater<long long>());
  for(int i = p; i < n; ++i) {
    sum -= (i - (p - 1)) * (a[i - 1] - a[i]);
    sum = max(0LL, sum);
    long long now = a[i] + m, rem = max(v - p, 0LL);
    if(now < a[p - 1]) continue;
    rem = max(0LL, rem - (n - 1 - (i + 1) + 1));
    if(a[i - rem] <= a[i])
      ++res;
    else if(sum >= rem * m)
      ++res;

    sum += m;
  }

  return res;
}

