			xxx=i;
			break;
		}
	xxx--;
	if(xxx>=p)
		return false;
	for(int i=n;i>xxx+1;i--){//计算：比它小的 
		long long delta=min((cur-b[i]),m);//尽力补 
		vote-=delta;
		del[i]=delta;
		b[i]+=delta;
		if(vote<=0){
			return true;//投完了 
		}
	}
	for(int i=1;i<=xxx;i++){
		vote-=m;
		b[i]+=m;
		if(vote<=0){
			return true;
		}
	}
	int fore=xxx;
	for(int i=xxx+2;i<=n;i++){
