int main(){
	ll N,M,V,P;
	cin >> N >> M >> V >> P;
	vector<ll> A(N);
	for(auto &x:A) cin >> x;
	sort(A.begin(), A.end());

	ll ok = N-1, ng = -1;
	while(ok-ng>1){
		ll mid = (ok+ng)/2;
		auto B = A;
		ll rest = V*M-M;
		B[mid] += M;
		ll morebig = 0;
		for(int i=N-1;i>=0;i--){
			if(i==mid)continue;
			if(B[i]+M>B[mid] && morebig<P-1){
				morebig++;
				B[i] += M;
				rest -= M;
			}else if(B[i]>B[mid]){
				rest = 1;
				break;
			}else if(rest){
				ll add = min(M,B[mid]-B[i]);
				B[i] += add;
				rest -= add;
			}
		}
		if(rest<=0){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	cout << N-ok << endl;
}

