bool can(int x)
{	
	ll rem = (v - 1) * 1LL * m;

	int cc = p - 1;
	for (int j = 1; j <= n; j++) {
		if (j == x) continue;
		if (cc) {
			rem -= m;
			cc--;
		}
		else {
			rem -= min(m, a[x] + m - a[j]);
			if (a[x] + m < a[j]) return false;
		}
	}

	return rem <= 0;
}

