using namespace std;
using ll = long long;

ll n, m, v, p, a[100010];

int main() {
  cin >> n >> m >> v >> p;
  REP(i, n) cin >> a[i];
  sort(a, a + n, greater<ll>());

  ll ans = p - 1, sum = 0;
  v -= p - 1;
  for(ll i = p - 1; i < n; ++i) {
    int tv = v - (n - i);
    if (tv <= 0) {
      if(a[i] + m >= a[p - 1]) ++ans;
    } else {
      // 累積和をとる。それとインデックスを合わせて、そこまでの
      ll need = tv * m;
      if ((i - p + 1) * (a[i] + m - 1) - sum >= need && a[i] + m >= a[p - 1]) ++ans;
    }
    sum += a[i];
  }

  cout << ans << endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;

int n,np,nv,nt;
vector<int> box(1e5);

bool check(int mid) {
  bool ans_bool=false;
  if(box.at(nt-1)<=box.at(mid)) {
    ans_bool=true;
  }
  else if(box.at(mid)+np >= box.at(nt-1)) {
    if(nv<=nt) {
      ans_bool=true;
    }
    else {
      long long check_sum=0;
      for(int i=nt-1;i<n;i++) {
        if(i==mid) continue;
        check_sum+=min(np,box.at(mid)+np-box.at(i));
        if(check_sum>=np*(nv-nt)) {
          ans_bool=true;
          break;
        }
      }
    }
  }
  return ans_bool;
}

int main() {
  cin >> n >> np >> nv >> nt;
  for(int i=0;i<n;i++) {
    cin >> box.at(i);
  }

  sort(box.rbegin(),box.rend());

  int mx=n-1;
  int mn=nt-1;
  int mid=(mx+mn)/2;
  while(mx-mn>=2) {
    if(check(mid)) {
      mn=mid;
    }
    else {
      mx=mid;
    }
    mid=(mn+mx)/2;
  }
  cout << mn+1 << endl;
}

