llong n, m, v, p;
llong a[100005];
llong sum[100005];
llong b;
llong ans;
llong upsum;
llong eqsum;

int main() {
    cin >> n >> m >> v >> p;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    sort(a, a + n);
    b = a[n - p];
    for (int i = 0; i < n; i++) {
        if (a[i] > b) upsum++;
        if (a[i] == b) eqsum++;
        sum[i + 1] = sum[i] + a[i];
    }

    for (int i = 0; i < n; i++) {
        if (a[i] >= b) {
            ans++;
            continue;
        }
        {
            llong s = a[i] + m;
            llong tmp = m * v;
            tmp -= m;
            if (tmp <= 0 && s >= b) {
                ans++;
                continue;
            }

            llong idx = upper_bound(a + i, a + n - p, s) - a; idx--;
            tmp -= s * (idx - i) - (sum[idx + 1] - sum[i + 1]);
            if (tmp <= 0 && s >= b) {
                ans++;
                continue;
            }

            tmp -= i * m;
            if (tmp <= 0 && s >= b) {
                ans++;
                continue;
            }
            tmp -= (p - 1) * m;
            if (tmp <= 0 && s >= b) {
                ans++;
                continue;
            }

            if (tmp <= m && s >= b + tmp) {
                ans++;
                continue;
            }
        }
        {
            llong s = a[i] + m;
            llong tmp = m * v;
            tmp -= m;
            tmp -= upsum * m;
            tmp -= i * m;
            if (tmp <= 0 && s >= b) {
                ans++;
                continue;
            }

            llong idx = upper_bound(a + i, a + n - upsum - eqsum, s) - a; idx--;
            tmp -= s * (idx - i) - (sum[idx + 1] - sum[i + 1]);
            if (tmp <= 0 && s >= b) {
                ans++;
                continue;
            }

            if ((tmp + eqsum - 1) / eqsum <= m &&
                s >= b + (tmp + eqsum - 1) / eqsum) {
                ans++;
                continue;
            }
        }

        //cout << a[i] << ' ' << tmp << endl;
    }

    cout << ans << endl;

    return 0;
}

