// 1-indexed BIT (i : [1, len])
template<typename T>
struct BIT
{
    int len;
    vector<T> val;
    BIT(int num) : len(num), val(num + 1) {}
    BIT() : BIT(0) {}
    void reset() { fill(val.begin(), val.end(), 0); }
    void add(int pos, T v) { while (pos > 0 and pos <= len) val[pos] += v, pos += pos & -pos; }
    T sum(int pos) const // (0, pos]
    {
        T res = 0;
        while (pos > 0) res += val[pos], pos -= pos & -pos;
        return res;
    }
};
template<typename T> ostream &operator<<(ostream &os, const BIT<T> &b){ T prv = 0; os << "["; REP(i, b.len) { T nxt = b.sum(i + 1); os << nxt - prv << ","; prv = nxt; } os << "]"; return os; }


int main()
{
    lint N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<lint> A(N);
    cin >> A;

    sort(ALL(A));

    BIT<lint> bit(N);
    REP(i, N) bit.add(i + 1, A[i]);

    lint border = A[N - P];
    int ret = 0;
    if (V <= P) {
        for (auto a : A) if (a + M >= border) ret++;
    }
    else
    {
        REP(i, N) {
            if (i >= N - P) ret++;
            else if (A[i] + M >= border and i >= V - P) ret++;
            else
            {
                lint w = (V - 1 - (P - 1) - i) * M;
                auto itr = upper_bound(ALL(A), A[i] + M);
                lint j = itr - A.begin();
                mmin(j, N - P);
                lint su = bit.sum(j) - bit.sum(i + 1);
                if (su + w <= (A[i] + M) * (j - i - 1)) ret++;
            }
        }
    }
    cout << ret << endl;
}

