                if(arr[m]<=arr[i]+M) hi=m;
                else lo=m+1;
            }
            if(lo<=P){
                if((P-1)*M+(i-P+1)*(arr[i]+M)-(ps[i]-ps[P-1])>=rem) cnt++;
            }
        }
    }
    printf("%lld\n",cnt);
    return 0;
}

