// 降順P番目までは確実に採用される
// 絶対に問題セットに採用されない問題：ジャッジ全員が点数を入れても降順P番目に点数が入らない場合
// そのとき、他の問題への投票は、降順P番目未満の問題
// V問を選ぶ：昇順V-1問目までの場合は、他の問題に投票する場合を考えなくてはいけない　→　不要？？？？
// 初期で降順P番目の問題の点数と比較する必要がありそう

// ジャッジにより最大+m点が加算される
// 降順P番目の問題に加点されてしまうのは、V>Pのとき

// 入れたい問題には、全員が点をいれればいい
// i番目の問題を入れるとする
// それ以外の点数の振り方は、降順でP-1番目までの問題＞入れたい問題よりも昇順で早い問題
// 困るとき：(p-1)+i < v のとき(予定よりも多くの問題に点を入れなければいけないとき)

signed main(){
  ll n,m,v,p; cin>>n>>m>>v>>p;
  vector<ll> a(n); rep(i,n) cin>>a[i]; sort(ALL(a));

  ll lim = a[n-p];

  ll ng = -1, ok = n-p;
  while(ok-ng>1){
    ll i = (ok+ng)/2;
    bool flg = false;

    // if(i>=n-p) flg=true; // 上からp問目までは無条件でOK

    ll tor = a[i]+m; // ボーダーライン
    ll last = v-p-i;
    if(last<=0){ // 入れたくない問題に投票されない場合
      if(tor>=lim) flg=true;
    }else{ // 入れたくない問題に投票されてしまう場合
      ll amari = last*m; // 残りの表
      for(int j=i+1; j<=n-p; j++){
        amari -= llmin((tor-a[j]),m);
      }
      if(amari<=0) flg=true;
    }
    if(flg) ok=i;
    else ng=i;
  }

  cout << n-ok << endl;

  return 0;
}

