void solve() {
	lli n, m, v, p;
	cin >> n >> m >> v >> p;

	vector<lli> ai(n);
	for (auto &x : ai) cin >> x;
	sort(ALL(ai));

	if (v <= p) {
		int ans = 0;
		for (auto x : ai) ans += (x + m >= ai[n - p]);
		cout << ans << "\n";
		return;
	}

	lli vote = m * (v - p);
	int lo = 0, hi = n-p, mi;
	while (lo < hi) {
		mi = lo + hi >> 1;
		lli left = vote;

		if (ai[mi] + m < ai[n - p]) left = 0;

		for (int i = 0; i <= n-p; ++i) {
			if (mi == i) continue;
			left -= min(m, ai[mi] + m - ai[i]);
		}

		if (left <= 0) hi = mi;
		else           lo = mi + 1;
	}

	cout << n - lo << "\n";
}

