    cin >> a[i];
  }
  sort(a.begin(), a.end());

  ll bgn = -1, end = N;
  while(end - bgn > 1){
    ll mid = bgn + (end - bgn) / 2;
    vector<ll> b(N, 0);

    for(ll i = 0; i < N; i++){
      b[i] = a[i];
  	}
    ll cnt = 0;
    for(ll i = 0; i <= mid; i++){
      b[i] += M;
      cnt++;
  	}
    for(ll i = 1; i < P; i++){
      b[N - i] += M;
      cnt++;
  	}

    if(b[N - P] > b[mid]){
      bgn = mid;
    }else if(cnt >= V){
      end = mid;
    }else{
      ll s = cnt * M;
      for(ll i = mid+1; i <= N - P; i++){
        s += b[mid] - b[i];
      }
      if(s <= M * V){
        bgn = mid;
      }else{
        end = mid;
      }
    }
  }
  while(bgn < N - 1 && a[bgn] == a[bgn+1]){
    bgn++;
  }
  cout << max(N - bgn - 1, 1LL) << endl;
}

