long N,M,V,P;
long A[100000];
long ans = 0;
int impossible_line;//ここ以上のindexのAは絶対に採用されない

//A[X]が採用される可能性があるかを返す
bool get_safevote(int X){
	if(X>=impossible_line) return false;
	if(X<P) return true;
	long safevote = 0;
	safevote+=(N-X+P-1)*M;
	for(int i=P-1;i<X;i++){
		safevote+=A[X]+M-A[i];
	}
	if(safevote<=M*V) return false;
	return true;
}

void solve(){
	//二分探索
	int top = impossible_line-1;
	int bottom = P;
	int index = (top-bottom+1)/2;
	/*for(int i=0;i<N;i++){
		cout << A[i] << " ";
	}*/
	//cout << endl;
	while(1){
		//cout << "bottom:" << bottom << "index:" << index << "top:" << top << endl;
		if(get_safevote(index)){
			bottom = index;
			index = index + (top-index+1)/2;
		}else{
			top = index;
			index = index - (index-bottom+1)/2;
		}
		if(top==bottom+1){
			ans = top;
			break;
		}
	}
}

int main(){
	cin >> N >> M >> V >> P;
	for(int i=0;i<N;i++) cin >> A[i];
	sort(A,A+N,greater<long>());//降順にソート

	impossible_line = N;
	for(int i=P-1;i<N;i++){
		if(A[i]+M<A[P-1]){
			impossible_line = i;
			break;
		}
	}

	solve();

	cout << ans;
	return 0;
}

