const ll MAX_N = 2e5 + 5;
ll n, m, v, p, ans;
ll Arr[MAX_N];
ll Brr[MAX_N];

bool can(ll d) {
    ll ind = n - p + 1;
    if (d < Arr[ind - 1])
        return false;

    ll nv = v - (p - 1);
    if (nv <= 0)
        return true;

    for (int i = 0; i < ind; i++)    
        Brr[i] = d - Arr[i];

    ll s = 0;
    while (s < ind && Brr[s] >= m && nv) {
        nv--;
        s++;
    }

    if (nv <= 0)
        return true;

    ll sum = 0;
    for (int i = s; i < ind; i++)
        sum += Brr[i];

    return sum >= nv * m;
}

int main() {
    ios::sync_with_stdio(false), cin.tie(0);
    cin >> n >> m >> v >> p;
    for (int i = 0; i < n; i++)
        cin >> Arr[i];
    sort(Arr, Arr + n);
    ll s = 0, e = 2e9;
    while (e - s > 1) {
        ll mid = e + s >> 1;
        if (can(mid))
            e = mid;
        else
            s = mid;
    }

    for (int i = 0; i < n; i++)
        if (Arr[i] + m >= e)
            ans++;

    cout << ans << "\n";
    return 0;
}

