//------------------------------- Solver ------------------------------------//

void solve()
{
    i64 n, m, v, p;
    cin >> n >> m >> v >> p;
    akari<i64> as(n);
    for (int i = 0; i < n; i++)
    {
        cin >> as[i];
    }
    sort(as.begin(), as.end());
    int ng = -1, ok = n - 1;
    while (ok > ng + 1)
    {
        int i = (ok + ng) / 2;
        i64 b = as[i] + m;
        auto bs = as;
        bs.erase(bs.begin() + i);
        i64 plus = m * v - m;
        int pena = p - 1;
        for (int k = n - 2; k >= 0; k--)
        {
            if (bs[k] > b)
            {
                pena--;
                plus -= m;
                bs[k] += m;
                continue;
            }
            if (pena == 0)
            {
                plus -= min(m, b - bs[k]);
                bs[k] += min(m, b - bs[k]);
            }
            else
            {
                plus -= m;
                pena--;
            }
        }
        (pena == 0 && plus <= 0 ? ok : ng) = i;
    }
    cout << n - ok << endl;
}

int main()
{
    solve();
    return 0;
}

