        int index=lastOccurence[cindex];
        if (A[index]+M >= A[N-P] && (P+index)>=V) ans++;
        else  {
            int balance=V-(P+index);
            if (index+balance < N-P-balance+1)
            {
                int ub = A[index]+M-A[N-P];
                int lb = A[index+balance]-A[index];
                if (lb>ub);
                else ans++;
            }
            else {
                int ub = A[index]+M-A[N-P];
                int lb = A[index+balance]-A[index];
                if (lb>ub);
                else if (lb==0) ans++;
            }
        }
        cindex--;
    }
    cout << ans << "\n";
    return 0;
}

