    int x = a[id];
    int sum = v * m; 
    int add = max(0ll, a[p] - a[id]);
    if (add > m) return false;
    sum -= add;
    x += add; 
    vector<int> upper;
    vector<int> lower;
    vector<int> eq; 
    for (int i = 0; i < n; ++i) {
        if (i == id) continue; 
        if (a[i] == x) eq.pb(m); 
        else if (a[i] > x) upper.pb(a[i]);                     
