    } 
    for (auto v : upper) {
        sum -= min(sum, m); 
    }
    for (auto &v : lower) {
        int pp = min(sum, x - v, m);         
        v += pp; 
        if (v == x) {                
            eq.pb(m - pp); 
        }             
        sum -= pp; 
    }
    if (sum == 0) return true; 
    sort(all(eq)); 
    int ctr = p - upper.size() - 1; 
