int check(int x)
{
	if (x < p)
		return 1;
	ll tmp = a[x] + m;
	int cnt = p - 1 + n - x - 1;
	ll sum = 0;
	for (int i = p - 1; i < x; i++) {
		ll rem = tmp - a[i];
		if (rem < 0)
			return 0;
		sum += min(1LL * m, max(0LL, rem));
	}
	if (v - cnt - 1 <= 0)
		return 1;
	return sum >= 1LL * m * (v - cnt - 1);
}

