ll bs1(ll key, vint &a){
  ll left = -1;
  ll right = n;

  while(right-left>1){
    ll mid = left + (right-left)/2;
    if(a[mid] <= key) right = mid;
    else left = mid;
  }
  return right;
}

bool isOK(ll t, vint &a){
  ll s = n-1 - t;
  ll r = v - p - s;

  if(t <= bi) return true;
  if(a[bi] - a[t] > m) return false;

  if(r <= 0) return true;

  // ll diff = a[bi] - a[t];
  ll diff = m;
  ll bii = bs1(m+a[t]-1, a) - 1;
  ll i = t - r;
  while(diff > 0 && i > bii){
    diff -= (a[bii] - a[i]);
    i -= r;
  }
  if(diff <= 0) return true;
  else return false;

}

ll bs(vint &a){
  ll left = 0;
  ll right = a.size();

  while(right - left > 1){
    ll mid = left + (right - left)/2;
    if(!isOK(mid, a)) right = mid;
    else left = mid;
  } 

  return right;
}




