int N, M, V, P;

bool ok(int n, vi &A) {
    if(n<=P-1) return true;
    int sum = M*P+M*(N-n-1);
    FOR(i, P-1, n) {
        sum += A[n]+M-A[i];
    }
    return sum>=M*V;
}

