const int maxn=2e5+5;
int a[maxn],m,v,p,n,ans;
bool check(int pos){
	int f=a[pos]+m>=a[n-p+1];
	if (!f)return 0;
	if (pos>=v)
		return f;
	int d=v-pos+1;
	if (d<=p-1){
		if (a[pos]+m>=a[n-p+1])
			return f;
	}else{
		ll sum=1ll*(d-p+1)*m;
		for (int i=pos+1;i<=n;i++){
			if (a[pos]+m<a[i]) break;
			sum-=a[pos]+m-a[i];
		}
		return (sum<=0);
	}
}
