int main(void){
    ll N,M,V,P;
    cin>>N>>M>>V>>P;

    vector<ll> A;

    for(int i=0;i<N;i++){
        ll a;cin>>a;
        A.push_back(a);
    }

    sort(A.begin(),A.end());
    reverse(A.begin(),A.end());

    while(true){
        if(A[P-1]==A[P]){
            P++;
        }
        else{
            break;
        }
    }

    ll res = 0;
    if(V<=N-P){
        for(ll i=0;i<N-P;i++){
            if(A[P-1]<=A[P+i] +M){
                res++;
            }
        }
      res = res+P;
    }
    else{
        ll dw = (N-V)*M;
        ll Pf = P;
        res =P;
        while(true){
            if(A[Pf-1]==A[P-1]){
                Pf--;
            }
            else{
              break;
            }
        }
        while(true){
            ll diff = A[P-1]-A[P];
            dw -= diff *(P-Pf+1);
            if(dw<0){
                break;
            }
            P++;
            res++;
            while(true){
                if(A[P-1]==A[P]){
                    P++;
                    res++;
                }
                else{
                    break;
                }
            }
        }

    }
    cout<<res<<endl;
}

