typedef long long ll;
#define rep(i,a) for(int i=0;i<(a);i++)
const ll MOD=1000000007;
// const ll MOD=998244353;

ll N,M,V,P;
vector<ll> A;

bool solve(int ind){
  if(A[ind]+M<A[P-1]) return 0;
  ll rest=M*V-M*P-M*(N-1-ind);
  for(int i=P-1;i<ind;i++) rest-=A[ind]+M-A[i];
  if(rest>0) return 0;
  else return 1;
}

int main(){
  cin>>N>>M>>V>>P;
  A.resize(N);
  rep(i,N){
    cin>>A[i];
  }
  sort(A.rbegin(),A.rend());
  A.push_back(-1e18);
  if(M>=N){
    int cnt=0;
    for(int i=P;i<N;i++) if(A[i]==A[P-1]) cnt++;
    cout<<P+cnt<<endl;
  }else{
    int ok=P-1,ng=N;
    while(abs(ok-ng)>1){
      int mid=(ok+ng)/2;
      if(solve(mid)) ok=mid;
      else ng=mid;
    }
    cout<<ok+1<<endl;
  }
  return 0;
}

