			modulomatrix tmp{};
			rep(i, dim) { tmp.buf[i][i] = 1; }
			return tmp;
		}
		modulomatrix & operator*=(const modulomatrix & lhs) {
			//*this = lhs * *this;
			return *this = lhs * *this;
		}
		friend std::ostream & operator<<(std::ostream & out, const modulomatrix & x) {
