ll has[maxn];

int check(int idx) {
    int need = a[idx] + m;
    int needv = m * v;
    int rank = 1;
    for (int i = 1; i <= n; ++i) {
        if (i <= idx) {
            has[i] = 0;
            needv -= m;
        } else if (need < a[i]) {
            has[i] = 0;
            needv -= m;
            rank ++;
        } else {
            has[i] = m - (need - a[i]);
            needv -= (need - a[i]);
        }
    }
    if (rank > p) return 0;
    if (needv <= 0) return 1;
    for (int i = n; i >= 1; --i) {
        if (has[i]) {
            needv -= has[i];
            rank ++;
        }
        if (rank > p) return 0;
        if (needv <= 0) return 1;
    }
    return 0;
}

