ll N, M, V, P;
vector<ll> A;

bool isok(ll mididx){
  if(mididx <= P-1) return true;
  // 当該問題の最高スコア
  ll maxi = A[mididx]+M; if(maxi < A[P-1]) return false; //到達できないので
  ll V_ = V;// M人が残りV_ 問に投票
  V_--;// 自分には投票するので
  V_ -= (P-1); // 超上位には投票しておけばいいので
  V_ -= (N-mididx-1); // 下位のものにも投票してよいので
  if(V_<=0) return true; // 投票先残ってないならええやろ

  // V_問を残りM_回の投票
  ll counter = 0;
  // 投票先はA[P-1]からA[mididx-1]まで
  for(ll i=P-1; i<mididx; i++){
    counter += min(M, maxi-A[i]);
  }

  if(counter >= M*V_) return true;
  else return false;
}

ll binsch(){
  ll ngidx = N;
  ll okidx = P-1;
  while(abs(okidx-ngidx)>1){
    ll mididx = (okidx+ngidx)/2;
    if(isok(mididx)) okidx = mididx;
    else ngidx = mididx;
  }
  return okidx;
}

int main(){
  cin >> N >> M >> V >> P;
  A.resize(N); rep(i,N) cin >> A[i];
  sort(rall(A));
  cout << binsch()+1 << endl;
  return 0;
}

