	ll l = 0, r = n - 1;
	while (l < r){
		ll mid = l + (r - l) / 2, pos, a[n], s = 0, left = m * (k - 1);
		copy(aa, aa + n, a);
		for (ll i = 0; i < n; i++){
			if (i == mid) continue;
			if (a[i] > a[mid]){
				pos = i;
				break;
			}
			a[i] += m;
			left -= m;
			if (left == 0) break;
		}
		a[mid] += m;
		if (left > 0){
			ll uses[n];
			fill(uses, uses + n, m);
			for (ll i = pos; i < n; i++){
				if (a[i] >= a[mid]) break;
				if (left <= a[mid] - a[i]){
					uses[i] -= left;
					a[i] += left;
					left = 0;
					break;
				}
				uses[i] -= a[mid] - a[i];
				left -= a[mid] - a[i];
				a[i] = a[mid];
			}
			if (left > 0){
				for (ll i = n - 1; i >= 0; i--){
					if (left <= uses[i]){
						a[i] += left;
						left = 0;
						break;
