const int MAXN = (int)1e5 + 777;
ll a[MAXN];
int n, p;
ll m, v;

int check(int pos) {
	ll to_add = m * v - m;
	ll x = a[pos] + m;

	int cnt = 0;
	for(int i = 0; i < n; ++i) {
		if(i != pos) {
			cnt += a[i] > x;
		}
	}

	if(cnt >= p) {
		return 0;
	}

	for(int i = n - 1; i >= 0; --i) {
		if(i != pos) {
			if(a[i] > x) {
				ll take = min(to_add, m);
				to_add -= take;
			} else {
				ll take = min(to_add, m);

				if(a[i] + take > x) {
					if(cnt + 1 < p) {
						++cnt;
					} else {
						take = min(take, x - a[i]);
					}
				}

				to_add -= take;
			}
		}
	}

	return to_add == 0;
}

