int main() {
  ll N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  REP(i, N) { cin >> A[i]; }
  sort(ALL(A));
  ll ng = -1, ok = N - P;

  while (ng + 1 < ok) {
    ll mid = (ok + ng) / 2;
    if (A[N - P] - A[mid] > M) {
      ng = mid;
      continue;
    }
    ll b = A[mid] + M;  //ボーダーライン
    ll margin = 0;
    REP(i, N) {
      if (i <= mid || i >= N - P + 1) {
        margin += M;
      } else {
        margin += min(b - A[i], M);
      }
    }
    if (margin >= M * V) {
      ok = mid;
    } else {
      ng = mid;
    }
  }
  cout << N - ok << endl;
}

