    //if(fm < nextMax)return false;

	ll i = upper_bound(a, a+n, a[mid]) - a - 1;
	ll k = upper_bound(a, a+n, fm) - a - 1;

	if (k < n - p) return false;
	//if (i >= n - p) return true;
    rep(i, n-(p-1LL)){
        //if(fm-a[i] <= 0LL)continue;
        allselect -= (min(fm-a[i], m));
    }

