		if (mid < (N - P))
		{

			ll tag = B[mid] + M;
			ll tp = M * (V - 1 - mid - P + 1);
			if (tp < 0)
			{
				tp = 0;
			}
			ll tokuten = sum[N - P + 1] - sum[mid + 1] + tp;

			cerr << sum[N - P + 1] << " " << sum[mid + 1] << " " << tp << endl;
			cerr << "tokuten=" << tokuten << " tag=" << tag << " kosuu=" << N - P - mid << endl;
			if (tag * (N - P - mid) < tokuten)
			{
				flag = false;
			}
		}

		/* 回答の応じて、年齢を絞る */
		if (flag == false)
		{
			if (left == mid)
				break;
			left = mid; // mid 歳以上なら、mid 歳以上 right 歳以下になるように
		}
		else
		{
			if (right == mid)
				break;
			right = mid; // mid 歳未満なら、left 歳以上 mid 歳未満になるように
		}
		cerr << "mid=" << mid << " " << flag << endl;
	}
	cerr << right << endl;
	cerr << A[right] << endl;
	ll ans = 0;
	FOR(i, 0, N - 1)
	{
		if (A[i] >= A[right])
			ans++;
	}

	cout << ans << endl;

	return 0;
}

