        }
        else if(V-1<=i){
            if(A[i]+M>=A[N-P]) ans++;
            continue;
        }
        else{
            if(A[i]+M<A[N-P]) continue;
            ll T = (N-P-i)*(A[i]+M) - (S[N-P+1] - S[i+1]);
            if(T >= (V-P-i)*M) ans++;
        }
    }

    cout << ans << endl;
}

