    for(int i=1;i<=n;i++){
        d[i]=d[i-1];
        if(a[i]!=a[d[i]])d[i]=i;
        c[d[i]]++;
    }
    int ans=d[p]-1+c[d[p]];
    int sum=0,tot=c[d[p]];
