        if(a[i]+m<a[p])break;
        if(v<=n-tot)ans++;
        else{
            int x=m*(v-n+tot)-sum;
            x=(x+tot-1)/tot;
            if(a[i]+m>=a[p]+x)ans++;
        }
        sum+=min(m,a[p]-a[i]);
        tot++;
    }
    cout<<ans<<endl;
    return 0;
}

