bool possible(ll ind)
{
    ll v1=v;
    v--;
    vi temp=a;
    a[ind]+=m;

    ll index=ind;
    for(ll i=0;i<n && v>0;i++)
    {
        if(temp[i]<=temp[ind])
        {
            if(i!=index)
            {
                a[i]+=m;
                v--;
            }
        }
        else
        {
            index=i;
            break;
        }
    }

    ll votes=v*m;
    if(votes>0)
    {
        for(ll i=0;i<n && votes>0;i++)
        {
            if(a[i]>a[ind])
            {
                votes-=m;
                a[i]+=m;
            }
        }
    }
    if(votes>0)
    {
        for(ll i=index;i<n && votes>0;i++)
        {
            if(a[i]<a[ind])
            {
                votes-=a[ind]-a[i];
                a[i]=a[ind];
            }
        }
    }
    if(votes>0)
    {
        for(ll i=n-1;i>=index && votes>0;i--)
        {
            if(a[i]==a[ind] )
            {
                ll ma=temp[i]+m;
                votes-=(ma-a[i]);
                a[i]=ma;
            }
        }
    }

    ll greater=0;
    for(ll i=0;i<n;i++)
    {
        if(a[i]>a[ind])
            greater++;
    }
    v=v1;
    a=temp;
    return greater<p;
}
