    ll a;
    cin >> a;
    as[i] = a;
  }

  sort(as.begin(), as.end());

  auto check = [&](ll i) {
    ll a = as[i];
    ll rest = M * V;

    ll served = 0;
    auto over_it = upper_bound(as.begin(), as.end(), a + M);
    ll over_index = over_it - as.begin();
    ll over_a_ct = N - over_index;
    if (over_a_ct >= P) return false;
    rest -= over_a_ct * M;
    served += over_a_ct;
    ll can_over = P - over_a_ct - 1;

    if (rest <= 0) return true;

    ll over_a_i = upper_bound(as.begin(), as.end(), a) - as.begin();
    ll sm_eq_a_ct = over_a_i;
    rest -= sm_eq_a_ct * M;
    served += sm_eq_a_ct;

    if (rest <= 0) return true;

    over_index -= can_over;
    rest -= can_over * M;
    served += can_over;

    if (rest <= 0) return true;

    ll b_i = upper_bound(as.begin(), as.end(), a) - as.begin();

    for (ll ii = b_i; ii < over_index; ii++) {
      rest -= a + M - as[ii];
      served++;
    }

    return rest <= 0 && served >= V;
  };

