ll N, M, V, P;
vector<ll> A;

void solve() {
	scanf("%lld%lld%lld%lld", &N, &M, &V, &P);
	A.assign(N, 0);
	rep(i, N) { scanf("%lld", &A[i]); }
	sort(all(A));

	auto isOK = [&](ll val) -> bool {
		if(N-P<=val){
			return true;
		}

		ll valpoint=A[val]+M;
		if(V-P<=0){
			ll maxpoint=A[N-P];
			if(valpoint>=maxpoint)return true;
			return false;
		}
		/*
		if(P+val>=V){
			ll maxpoint=A[N-P];
			if(valpoint>=maxpoint)return true;
			return false;
		}

		ll kosu=N-(P-1)-(val+1);
		if(kosu<=0){
			return true;
		}
		*/
		ll amaripoint=(V-P-val)*M;
		ll sumpoint=0;
		for(ll i=val+1;i<=N-P;i++){
			ll t=valpoint-A[i];
			if(t<0)return false;
			sumpoint+=min(M,t);
		}
		if(amaripoint>sumpoint)return false;
		return true;
	};

	if(isOK(0)){
		p(N);return;
	}

	ll left = N-1;
	ll right = 0;
	while((ll)abs(right - left) > 1) {
		ll mid = left + (right - left) / 2;
		if(isOK(mid)) left = mid;
		else right = mid;
	}

	printf("%lld\n", N-left);
}

