	else {
		// P-1問と自分より下にあげても足りるかどうか

		ll border = A[P - 1];

		ll mae = P-1; // 尺取り

		vll ruiseki(N);
		for (ll i = 0; i < N; i++) {
			ruiseki[i] = 0;
		}
		ruiseki[0] = A[0];
		for (ll i = 1; i < N; i++){
