    for (long i = 0; i < N; i++) {
        cin >> A.at(i);
    }

    sort(A.begin(), A.end());
    //全部同じ数の時
    if (A.at(0) == A.at(N - 1)) {
        cout << N << endl;
        return 0;
    }

    long boundary = A.at(N - P); //この数を超えればよい    
    auto itr0 = lower_bound(A.begin(), A.end(), boundary - M); //boundaryを超えうる数がある最左端
    auto itr1 = lower_bound(A.begin(), A.end(), boundary); //boundaryと同値の数の最左端
    auto itr2 = A.end() - P; //boundaryのある場所

    long num0 = itr0 - A.begin(); //itr0より小さい数の個数
    long num1 = V - (P - 1); //boundaryより右の数に割り振る

    if ( (num1 - 1 -num0) <= 0) {
       cout << N - num0 << endl;
       return 0;
    }



    long sum = 0, flag = 0;
    for (itr0; itr0 < itr1; itr0++) {
        num0 = itr0 - A.begin();
        sum = 0;
        if ((num1 - 1 - num0) <= 0) {
            cout << N - num0 << endl;
            return 0;
        }

        long t_boundary = max(boundary, *itr0 + M);
        for (auto itr = itr0 + 1; itr < itr2; itr++) {
            if ((t_boundary - *itr) == 0) {
                break;
            }

            sum += min((t_boundary - *itr), M); //
            if (sum >= M * (num1 - 1 - num0)) {
                flag = 1;
                break;
            }
        }

        if (flag) {
            cout << N - num0 << endl;
            return 0;
        }

    }

    num0 = itr0 - A.begin(); //この時itr0 = itr1
    cout << N - num0 << endl;
    return 0;        
}

