using namespace std;

bool is_ok(vector<int64_t>& as, int64_t n, int64_t m, int64_t v, int64_t p, int64_t i)
{
	int64_t cv = (n - i);

	int64_t ti = p - 2;
	int64_t av = as[i] + m;

	int64_t rc = 0;
	FOR_LT(j, ti + 1, i) {
		rc += av - as[j];
	}

	int64_t nc = (v - cv - (ti + 1)) * m;

	return (nc <= rc);
}

