bool check(int pos)
{
    int k=n-v;
    for (int i=1;i<=n;++i){
        pref[i]=0;
    }
    int cur=0;
    int cnt=m;
    for (int i=pos+1;i<=n;++i){
        cur+=pref[i];
        int l=a[i]-cur;
        if (l>a[pos]){
            int f=min(l-a[pos],cnt);
            cnt-=f;
            cur+=f;
            pref[i]+=f;
            int c=min(n+1,i+k);
            pref[c]-=f;
        }
    }
    cur=0;
    int kol=0;
    for (int i=1;i<=n;++i){
        cur+=pref[i];
        if (a[i]-cur>a[pos]){
            ++kol;
        }
    }
    return kol<p;
}

