const int N = 100005;

int n, m, v, p, ans = 0, a[N];

bool check(int u) {
    if (a[u] + m < a[n - p + 1]) {
        return false;
    }
    long long tmp = 0;
    for (int i = 1; i <= n - p; i++) {
        if (u != i) {
            tmp += max(0, min(a[u] + m - a[i], m));
        }
    }
    // cout << u << ": " << tmp << " " << 1LL * v * m << '\n';
    return tmp >= 1LL * v * m;
}

int find_ans() {
    int l = 1, r = n;
    while (l <= r) {
        int m = (l + r) / 2;
        if (check(m)) {
            r = m - 1;
        } else {
            l = m + 1;
        }
    }
    return r;
}

