const int INF = 1001001001;
ll n,m,v,p;
vector<ll> a;

ll judge(ll x){
  ll bd = a.at(n-p);
  if(x+p>=v){
    if(bd<=a.at(x)+m) return 1; else return 0;
  }
  if(bd>(a.at(x)+m)) return 0;
  ll rest_vote = (v-(x+p)) * m;
  for(int i=n-p;i>x;i--){
    rest_vote -= (a.at(x)+m) - a.at(i);
  }
  if(rest_vote>0) return 0; else return 1;
}

int main(){
  cin >> n >> m >> v >> p;
  a.resize(n,0);
  for(ll i=0;i<n;i++){
    cin >> a.at(i);
  }
  sort(a.begin(),a.end());
  ll l = -1, r = n-1, c = (l+r)/2;
  while(r-l>1){
    if(judge(c) == 1) r=c; else l=c;
    c = (l+r)/2;
  }
  cout << n-r << endl;
}

