struct Calc {
	DEFINITER;
	DEFVALUES(//////////////////////////////////////////////////
		(u6,N,M,V,P)
	);///////////////////////////////////////////////////////
	u6 calc() {
		vector<u6> buf;
		read(buf, N);
		sort(ALL(buf));
		u6 result = P - 1;
		if (V <= P) {
			V = 1;
		}
		else { V -= P - 1; }
		vector<u6> buf2;
		u6 s = N - P + 1;
		buf2.resize(s);
		partial_sum(buf.begin(),buf.begin()+s, buf2.begin());
		//u6 s = accumulate(buf.begin(),buf.begin()+N-P+1, 0ull);

		u6 n = 0;
		for (; n < buf2.size(); ++n) {
			auto l = buf[n] + M;
			auto r = (buf2.back() - buf2[n] + M * (V - 1 - n)) / double(buf2.size() - n - 1);
			r = max(r, double(buf[s-1]));
			if (l >= r) {
				break;
			}
		}
		return result + s-n ;
	}

	/*******************************************************************************/
};

