void solve()
{
	ll N, M, V, P;
	cin >> N >> M >> V >> P;
	vll A = cinv(N);

	sort(A.begin(), A.end(),
		[](ll &a, ll &b) {return a > b; });

	vll Arui(N+1);
	Arui[0] = 0;
	REP(i, N){
		Arui[i+1] = Arui[i] + A[i];
	}

	ll a = A[P-1]; //P位の値aを求める

	ll I = P-1;
	REPS(i, P, N-1){
		if (A[i-1] == A[i])continue;
		ll b = A[i];
		ll S = (Arui[i] - Arui[P-1]) - b * (i-P+1);
		ll d = N-V;
		ll val = max(CEIL(S, d), a-b);
		if (val > M){
			I = i-1;
			break;
		}
	}
	cout << I+1 << '\n';




}

