int n,m,v,p;
int a[100010];
bool isOK(int mid){//n log 10^9
    if(mid<=p-1)return true;
    if(v==n)return false;
    if(v<=n+p-1-mid)return a[mid]+m>=a[p-1];
    int to=a[mid]+m;
    vector<int>V;
    int sum=0;
    int c=v-(n+p-1-mid);
    for(int i=p;i<=mid-1;i++){
        V.pb(to-a[i]);
        sum+=to-a[i];
        if(to<a[i])return false;
    }
    if(sum<c*m)return false;
    sort(all(V));
    int nokori=sum-(c*m);
    int ng=-1,ok=INF;
    while(ok-ng>1){
        int MID=(ok+ng)/2;
        int cnt=0;
        for(int e:V){
            if(e>MID)cnt+=e-MID;
        }
        if(cnt<=nokori)ok=MID;
        else ng=MID;
    }
    int ma=ok;
    for(int i=0;i<V.size();i++){
        if(V[i]>ma){
            nokori-=V[i]-ma;
            V[i]=ma;
        }
    }
    for(int i=0;i<V.size();i++){
        if(V[i]==ma&&nokori>0){
            V[i]--;
            nokori--;
        }
    }
    sort(all(V),greater<int>());
    int SUM1=0,SUM2=0;
    for(int i=0;i<c;i++)SUM1+=V[0]-V[i];
    for(int i=c;i<V.size();i++)SUM2+=V[i];
    return SUM1<=SUM2;
}
signed main(){
    cin>>n>>m>>v>>p;
    rep(i,n)cin>>a[i];
    sort(a,a+n,greater<int>());

    int ok=0,ng=n;
    while(ng-ok>1){//log n
        int mid=(ok+ng)/2;
        if(isOK(mid))ok=mid;
        else ng=mid;
    }
    cout<<ok+1<<endl;
}

