lint N, M, V, P, arr[100000];
map<lint, lint> st;
map<lint, lint> ed;
bool check(lint i) {
	if (P >= st[i] + 1) return false;
	else if (arr[P - 1] > i + M) return true;
	lint safe = (P - 1 + N - st[i]) * M;
	for (int j = P - 1; j < st[i]; j++) {
		safe += min(M, i + M - arr[j]);
	}
	return safe < M * V;
}

int main() {
	cin.tie(0); ios_base::sync_with_stdio(false);
	cin >> N >> M >> V >> P;
	lint maxv = 0;
	REP(i, N) {
		cin >> arr[i];
		chmax(maxv, arr[i]);
	}
	sort(arr, arr + N, greater<lint>());
	REP(i, N) {
		if (st.find(arr[i]) == st.end()) st[arr[i]] = i;
		chmax(ed[arr[i]], i);
	}
	st[0] = N - 1;
	ed[0] = N - 1;

	lint lb = -1, ub = maxv + 1;
	while (ub - lb > 1) {
		lint mid = (lb + ub) / 2;
		if (check(mid)) lb = mid;
		else ub = mid;
	}
	reverse(arr, arr + N);
	lint a = *(upper_bound(arr, arr + N, ub) - 1);
	cout << ed[a] + 1 << endl;
}

