ll N, M, P;

// i番目の要素を採用できるか否か
bool f(vector<ll> a, ll V, ll i) {
  if (i < P)
    return true;

  // printf("before a[%lld]=%lld: ", i, a[i]);
  // for (auto e : a) {
  //   cout << e << " ";
  // }
  // cout << endl;


  // 自分自身
  a[i] += M; V--;
  // 自分自身より小さいもの
  for (ll j=i+1; j<N+1; j++) if (V > 0) { a[j] += M; V--; }

  // 1 ~ P-1番目のものはどうでもよい
  for (ll j=0; j<P-1; j++)   if (V > 0) { a[j] += M; V--; }

  // P番目までは逆転したい -> j = P-1 ~ i-1 に、つまりできるだけ分散させたい
  ll t = 0;
  for (ll j=P-1; j<i; j++) {
    t += min(M, a[i] - a[j]);
  }
  return t >= M * V; // 十分に j=P^1 ~ i-1 に振り分け可能
}

