	}
	return true;
}

template<size_t rows, size_t cols>
void MatrixMul(lli (&a)[rows][cols], lli b[rows][cols]) {
	lli c[rows][cols];
	memset(c, 0, sizeof(c));

	for (int i = 0; i < rows; ++i) {
		for (int j = 0; j < rows; ++j) {
			for (int k = 0; k < rows; ++k) {
				c[i][j] += a[i][k] * b[k][j];
				c[i][j] %= mod;
			}
		}
	}

	for (int i = 0; i < rows; ++i) {
		for (int j = 0; j < cols; ++j) {
			a[i][j] = c[i][j];
		}
	}
}

