void upd(int v, int tl, int tr, int l, int r, int delta) {
    if (l <= tl && r >= tr)
        add[v] += delta;
    else if (l >= tr || tl >= r)
        return;
    else {
        int tm = (tl + tr) >> 1;
        upd(v * 2, tl, tm, l, r, delta);
        upd(v * 2 + 1, tm, tr, l, r, delta);
    }
}

int get(int pos) {
    int v = 1, tl = 0, tr = n, res = 0;
    while (tr - tl > 1) {
        res += add[v];
        int tm = (tl + tr) >> 1;
        if (pos < tm) {
            v = v * 2;
            tr = tm;
        }
        else {
            v = v * 2 + 1;
            tl = tm;
        }
    }
    res += add[v];
    return res;
}

