ll n,m,v,p;
ll a[100010];

bool chk(int mid)
{
	ll totaloperationcnt=0ll;
	ll kill=n-p;

	for(int i=n;i>=1&&kill;i--)if(i!=mid)
	{
		if(a[mid]-a[i]>m)return false;

		totaloperationcnt+=max(0ll,a[mid]-a[i]);

		kill--;
	}

	return(totaloperationcnt<=m*v);
}

