	v=n-v;

	sort(a+1,a+n+1);

	ll L=1ll,R=n;

	while(L<R)
	{
		int mid=(L+R+1ll)>>1ll;

		if(chk(mid))L=mid;
		else R=mid-1ll;
	}

	cout<<L;

	//printf("Time used = %.12f",(double)(clock())/CLOCKS_PER_SEC);
	return 0;
}

