            num++;
            prev = A[i];
        }
        else if (prev > A[i]) {
            prev = A[i];
            if (num >= P) break;
            else num++;
        }
    }

    //cout << "num = " << num << endl;

    // rep(i, N) {
    //     cout << A[i] << " ";
    // }
    // cout << endl;

    LazySegmentTree lst(A);
    ll ans = num;
    for (int i=num; i<N; ++i) {

        bool debug = false;
        // 右側を更新する
        lst.add(i, min(N, i+V), M);

        // 残りこれだけ
        ll left = V - (N-i) + 1;
        if (left < P) {
            lst.add(0, left, M);
            // 取得する
            ll tmp1 = lst.getsum(i, i+1);
            if (A[P-1] <= tmp1) {
                ans++;
                debug = true;
            }
        }
        else  {

            // P-1個+Mする
            lst.add(0, P, M);

            ll left2 = left - (P-1);
            ll tmp = (left2*M)/(N-(V-left2));
            if ((left2*M)%(N-(V-left2)) > 0) {
