vector<ll> arr;
bool cmp(ll a, ll b) {
    return a>b;
}
bool check(vector<ll> &arr, int num, int n, ll m, int v, int p){
    if(p-1+n-num>=v && arr[num]+m>=arr[p-1]){
        return true;
    }
    else if(p-1+n-num>=v && arr[num]+m<arr[p-1]) return false;
    else if(p-1+n-num<v && arr[num]+m<arr[p-1]) return false;
    else v-=(p-1+n-num);
    ll summ=0;
    for(int i=p-1;i<=num-1;i++){
        summ+=(arr[num]+m-arr[i]);
    }
    return summ >= m * v;
}

void solve(){
    int n,v,p;
    ll m;
    cin>>n>>m>>v>>p;
    arr.resize(n);
    for(int i=0;i<n;i++) cin>>arr[i];
    sort(arr.begin(), arr.end(), cmp);
    int l=0;
    int r=n;
    /*for(int son:arr) cout<<son<<" ";
    cout<<endl;*/
    while(r-l>1){
        int num=(l+r)/2;
        if(check(arr, num, n,m,v,p)){
            l=num;
        }
        else r=num;
    }
    cout<<l+1;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n=1;
    for (int i = 0; i < n; i++) solve();
    return 0;
}

