typedef long long ll;
using namespace std;
int main(void){
    ll n,m,v,p;cin>>n>>m>>v>>p;
    vector<ll> a(n);
    rep(i,n)cin>>a[i];
    sort(a.begin(),a.end());
    vector<ll> b(n,a[0]);
    rep(i,n-1)b[i+1]=a[i+1]+b[i];
    ll res=0;
    ll x=a[n-p];
    auto itr=lower_bound(a.begin(),a.end(),x);
    auto itr3=upper_bound(a.begin(),a.end(),x);
    int k=itr-a.begin(),k3=itr3-a.begin();//実際のボーダー
    k3--;
    rep(i,n){
        if(a[i]>=a[k]){
            res++;
            continue;
        }else if(a[i]+m<a[k])continue;
        auto itr2=upper_bound(a.begin(),a.end(),a[i]);
        int k2=itr2-a.begin();k2--;

        ll tmp = (m*(k2+p+1)+(a[i]+m)*(n-p-k2-1)-(b[n-p-1]-b[k2]));
        if(a[k]==a[i]+m)tmp-=(k3-(n-p-1))*m;
        else if(a[i]+m==a[n-p+1]){
            auto it=upper_bound(a.begin(),a.end(),a[i]+m);
            int k4=it-a.begin();k4--;
            tmp-=(k4-(n-p-1))*m;
            tmp+=(a[i]+m)*(n-p-1-k3)-(b[k3]-b[n-p-1]);
        }
        if(tmp>=v*m)res++;
    }
    cout<<res<<endl;
}

