ll n,m,v,p;

int main(){
  ll ans=-1;
  cin >> n >> m>>v>>p;
  vi a(n),sm(n);
  REP(i,n)cin>>a[i];

  sort(a.begin(), a.end());
  REP(i,n){
    if (i==0){
      sm[0]=a[0]; 
    }else{
      sm[i]=sm[i-1]+a[i];
    }
  }

  ll pmonmescore;
  pmonmescore=a[n-p];
  ll lastm=n-p+1;
  REP(i,n){
    if (pmonmescore==a[i]){
      lastm--;
    }
  }
  //ここでlastmはありうる問題を含めた最低番号
  if (lastm==0){
    cout<<n<<endl;
  }

  ll canusep=n-lastm;
  ll menseki=m*v;//使える面積

  //cout<<"lastm"<<lastm<<endl;

  REP(i,lastm){
    ll ii=lastm-i-1;
    if (a[ii]+m<pmonmescore){
      ans=ii;//ありえない番号をいれてbreak
      break;
    }

    ll maxscore=a[ii]+m;
    //auto Iter2 = upper_bound(a.begin(),a.end()-p+1, maxscore-1);
    //1,2,2,3・・のときl=3なら2が返る
    //ll henlen=Iter2-a.begin();
    //cout<<henlen<<endl;
    ll henlen=n-p+1;

    //使わないといけない面積計算
    menseki=m*(v-(p-1)-1-ii);
    if (menseki<0)
      menseki=-1;
    //
    ll umemen//埋めないといけない面積
    =(henlen-1-ii)*(maxscore);
    umemen-=sm[henlen-1]-sm[ii];

    if (umemen<menseki){//であれば不可能。==までは大丈夫
      ans=ii;//ありえない番号をいれてbreak
      break;
    }

  }

//cout<<endl;
  cout<<(n-ans-1)<<endl;
  return 0;
}

