inline ll read(){
	ll x=0,f=1;char c=getchar();
	while(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}
	while(c>='0'&&c<='9') x=(x<<1)+(x<<3)+(c^'0'),c=getchar();
	return x*f;
}

const int N=1e5+5;
int a[N],n,p,v,m,b[N];
inline bool chk(ll mid){
	if(a[mid]>=a[n-p+1])return 1;
	ll tot=m*v,x=a[mid]+m,y=mid+1;
	tot-=mid*m;
	if(tot<=0)return x>=a[n-p+1];
	if(x<a[n-p+1])return 0;
	rep(i,mid,n)b[i]=a[i];
	while(tot>0&&y<=n){
		if(x-b[y]<=tot){
			tot-=x-b[y];b[y]=x;
		}
		else{
			b[y]+=tot;tot=0;
		}
		++y;
	}//if(mid<=3)cout<<mid<<' '<<tot<<endl;
	if(tot<=0)return x>=b[n-p+1];
	ll cur;
	REP(i,n,mid+1){
		if(b[i]-a[i]<m){
			cur=m-(b[i]-a[i]);
			if(cur<=tot){
				tot-=cur;b[i]+=cur;
			}else b[i]+=tot,tot=0;
		}
		if(tot<=0)break;
	}
	if(tot>0)return 0;
	return x>=b[n-p+1];
}

