int main(){
  int64_t n,m,v,p;
  cin >> n >> m >> v >> p;
  vector<int64_t> a(n);
  rep(i,n) cin >> a.at(i);
  sort(a.begin(),a.end());
  reverse(a.begin(),a.end());
  int64_t criteria = a.at(p-1);
  int64_t sabun = 0;
  int64_t dame = 0;
  int64_t priorproblem = -1;
  vector<int64_t> gabage(n);
  rep(i,n){
    if(a.at(i) > criteria){
      priorproblem = i;
    }else{
      if(i != 0){
        gabage.at(i) = gabage.at(i-1)+a.at(i);
      }else{
        gabage.at(0) = gabage.at(0);
      }
    }
  }

  rep(i,n){
    int64_t hoge = priorproblem+1+(n-i);//ゴミ捨て場の数
    int64_t gabagepoint = (hoge)*m;//捨てれるごみ
    if(a.at(i) < criteria){
      if(v-hoge<=0){
        if(a.at(i) + m < criteria){
          dame++;
          //cout <<"#%";
        }
      }else{
        int64_t honu = (i-priorproblem-1);
        if( gabage.at(i)-a.at(i)+(m*v)-gabagepoint
           > (a.at(i) + m)*honu){
          dame++;
          //cout << "#$" << "i";
        }
      }
    }
  }
  cout << n - dame << endl;
}

