    ios::sync_with_stdio(false);

    ll n, m, v, p; cin>>n>>m>>v>>p;
    vector<ll> a(n);
    for(int i=0; i<n; i++) cin>>a[i];

    sort(a.begin(), a.end());

    // (ng, ok]
    int ng = -1, ok = n - 1;
    while(ok - ng > 1){
        int mid = (ng + ok) / 2;

        ll base = a[mid] + m;

        if((n - p) <= mid){
            ok = mid;
            continue;
        }

        if(base < a[(n - p)]){
            ng = mid;
            continue;
        }

        // 上位 P - 1 問、a[mid] より低い mid 問、a[mid] に M 人が 1 票入れる
        ll rest = v - (p - 1) - mid - 1;

        ll sum = 0;
        for(int i=0; i<n; i++){
            if(mid < i && i <= n - p && a[i] < base){
                sum += min(base - a[i], m);
            }
        }

        if(sum < rest * m) ng = mid;
        else ok = mid;
    }

    cout << (n - ok) << endl;

    return 0;
}

