ll n, m, v, p;
vector<ll> a;
bool check(int t) {
    ll sum = 0, co = 0;
    for (int i = 0; i < n; i++) {
        if (i == t) {
            continue;
        }
        if (a[i] > a[t] + m) {
            co++;
        } else {
            sum += min(m, a[t] + m - a[i]);
        }
    }
    ll ok = p - 1 - co;
    for (int i = 0; i < n; i++) {
        if (i == t || a[i] > a[t] + m) {
            continue;
        }
        if (ok == 0 || a[t] + m - a[i] > m) {
            break;
        }
        sum += m - (a[t] + m - a[i]);
        --ok;
    }
    if (co >= p) {
        return false;
    }
    return sum >= (v - co - 1LL) * m;
}
