    ll a = as[i];
    ll rest = M * V;

    ll served = 0;
    auto over_it = upper_bound(as.begin(), as.end(), a + M);
    ll over_index = over_it - as.begin();
    ll over_a_ct = N - over_index;
    if (over_a_ct >= P) return false;
    rest -= over_a_ct * M;
    served += over_a_ct;
    ll can_over = P - over_a_ct - 1;

    if (rest <= 0) return true;

