    ll sm_eq_a_ct = over_a_i;
    rest -= sm_eq_a_ct * M;
    served += sm_eq_a_ct;

    if (rest <= 0) return true;

    over_index -= can_over;
    rest -= can_over * M;
    served += can_over;

    if (rest <= 0) return true;

    ll b_i = upper_bound(as.begin(), as.end(), a) - as.begin();

    for (ll ii = b_i; ii < over_index; ii++) {
      rest -= min(M, a + M - as[ii]);
      served++;
    }

    return rest <= 0 && served >= V;
  };

