inline int read()
{
	int ret, f=1;
	char c;
	while((c=getchar())&&(c<'0'||c>'9'))if(c=='-')f=-1;
	ret=c-'0';
	while((c=getchar())&&(c>='0'&&c<='9'))ret=(ret<<3)+(ret<<1)+c-'0';
	return ret*f;
}

int n, m, v, p, a[maxn];

bool check(int x)
{
	int val = a[x] + m, cnt = 0;
	ll rst = 1LL * (v - 1) * m;
	for(int i = n; i > x; --i)
	{
		if(a[i] > val)
		{
			++ cnt;
			rst -= m;
		}
		else
		{
			if(cnt < p - 1)
			{
				++ cnt;
				rst -= m;
			}
			else
			{
				rst -= (val - a[i]);
			}
		}
	}
	if(cnt >= p)	return 0;
	return rst <= 1LL * m * (x - 1);
}

int main()
{
	n = read(); m = read(); v = read(); p = read();
	for(int i = 1; i <= n; ++i)
		a[i] = read();
	sort(a + 1, a + n + 1);
	int l = 1, r = n, mid, ans;
	while(l <= r)
	{
		int mid = (l + r) >> 1;
		if(check(mid))
			ans = mid, r = mid - 1;
		else
			l = mid + 1;
	}
	printf("%d", n - ans + 1);
	return 0;
}

