        auto cntm = cnt;
        cntm[a[mid]]--;
        lint score = a[mid] + m;
        if (score < a[p - 1])
            return false;
        lint adds = (v - 1) * m;
        adds -= (p - 1) * m;
        lint ps = p - 1;
        for (auto it = cntm.rbegin(); it != cntm.rend(); it = next(it)) {
            int use = min(ps, it->second);
            it->second -= use;
            ps -= use;
            if (p == 0)
                break;
        }
        for (auto &c : cntm) {
            if (score > c.first)
                adds -= min(m, score - c.first) * c.second;
        }
        return adds <= 0;
    };
    if (check(ng)) {
        cout << n << "\n";
        return 0;
    }
    while (abs(ok - ng) != 1) {
        lint mid               = (ok + ng) / 2;
        (check(mid) ? ok : ng) = mid;
