void solve(){
  ll n,m,v,p;
  cin>>n>>m>>v>>p;
  vector<ll>a(n);
  rep(i,n)cin>>a[i];
  sort(a.rbegin(),a.rend());
  ll l=0,r=n;
  while(r-l>1){
    ll mid=(l+r)/2;
    ll val=a[mid]+m;
    if(mid<=p-1){
      l=mid;
      continue;
    }
    if(val<a[p-1]){
      r=mid;
      continue;
    }
    ll sum=0;
    for(ll i=0;i<n;++i){
      if(i<p-1)sum+=m;
      else sum+=min(val-a[i],m);
    }
    if(sum>=v*m)l=mid;
    else r=mid;
  }
  ll ans=l+1;
  cout<<ans<<"\n";
}

