bool check(vector<ll>& A, ll N, ll M, ll V, ll P, int pos, vector<int>& B)
{
    debug("*******check********");
    // first, make A[pos] high
    ll base = A[pos] + M;
    if (A[P-1]>base) return false;

    // get left votes
    if (V<=(N-pos)+(P-1)) return true;
    int k = V-(N-pos)-(P-1);
    debug(pos, P-1, k);

    int sum = B[pos] - B[P-1];
    debug(sum, M);
    debug(base * (pos-P+1), base, pos-(P-1));
    debug(sum + k*M);
    return base * (pos-P+1) >= sum + k*M;
    // return que.size()==0;
}

