    // rsort
    sort(A.begin(), A.end());
    reverse(A.begin(), A.end());

    vector<int> B(N+1, 0);
    rep(i, 0, N) B[i+1] = B[i] + A[i];
    debug(A, B);

    // binary search 
    ll low = 0;
    ll high = N-1;
    while (low<high)
    {
        ll mid = (low+high+1)/2;
        // check
        bool is_ok = check(A, N, M, V, P, mid, B);

        if (is_ok)
            low = mid;
        else
            high = mid-1;
    }
    cout << low+1 << endl;
    return 0;
}

