        cin>>a[i];
    }
    auto chance = [&](int i){
        if(i>=n-p)return true;
        ll curr = a[i]+m;
        if(curr<a[n-p])return false;
        int spend = 0;
        for(int j=0;j<n;j++){
            if(i==j)continue;
            if(j<i){
                spend += m;
            }
            else if(j>n- min(v,p)){
                spend += m;
            }
            else{
                spend += min((ll)m, (ll)curr-a[j]);
            }
        }
        return spend >= (ll)m*(v-1);
    };
    sort(a.begin(),a.end());
    int low = 0, high = n-1;
    int answer =-1;
    while(low<=high){
        int mid = (low+high)/2;
        if(chance(mid)){
            answer = mid;
            high = mid-1;
        }else{
            low = mid+1;
        }
    }
    //assert(answer!=-1);
    cout<<n-answer;
}

