bool isGood(long long N, long long M, long long V, long long P, std::vector<long long> &A,lli x){
    if(x<P)return true;
    lli now = A[x] + M;
    if(now < A[P-1])return false;

    lli score = (P-1)*M;
    score += (N-x)*M;

    for(lli i=P;i<x;i++){
        score += min(M,max(0LL,now-A[i]));
    }

    return score >= M*V;

}

void func(long long N, long long M, long long V, long long P, std::vector<long long> A){
    sort(A.rbegin(),A.rend());

    lli small = -1,large = N;
    while(small + 1 < large){
        lli middle = (small+large)/2;
        if(isGood(N,M,V,P,A,middle)){
            small = middle;
        }
        else{
            large = middle;
        }
    }
    cout<<small+1<<endl;
}

