		ll x = a[med] + m;
		copy_v -= (n - med);
		ll all_v = copy_v * m;
		for (ll i = p - 1; i < med; i++)
			all_v -= min(m, (x - a[i]));
		if (all_v > 0)
			r = med;
		else
			l = med + 1;
	}
	ll copy_v = v;
	ll x = a[n - 1] + m;
	copy_v--;
	ll all_v = copy_v * m;
	for (ll i = p - 1; i < n - 1; i++)
		all_v -= min(m, (x - a[i]));
