int main() {
  std::ios_base::sync_with_stdio(false);

  int N, M, V, P;
  cin >> N >> M >> V >> P;

  vector<int> A(N);
  for (int i = 0; i < N; ++i) {
    cin >> A[i];
  }
  sort(A.begin(), A.end(), greater<int>());

  auto can = [&](int idx) -> bool {
    vector<int> B = A;
    int x = B[idx] + M;
    B.erase(B.begin() + idx);

    int votes_left = V - 1;

    int i = lower_bound(B.begin(), B.end(), x, greater<int>()) - B.begin();
    if (i >= P) return false;

    {
      int d = min(i, votes_left);
      for (int j = 0; j < d; ++j) B[j] += M;
      votes_left -= d;
    }

    vector<int> C;
    for (int j = i; j < (int)B.size(); ++j) {
      if (j < P - 1) {
        C.push_back(M);
      } else {
        C.push_back(min(M, x - B[j]));
      }
    }

    int64_t area = std::accumulate(C.begin(), C.end(), 0LL);
    return area >= static_cast<int64_t>(votes_left) * M;
  };

  int lo = 0, hi = (int)A.size() - 1;
  while (lo < hi) {
    int mid = (lo + hi + 1) / 2;
    if (can(mid)) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }

  cout << lo + 1 << '\n';
  return 0;
}

