bool can(int K) {
  if (K < P) return true;
  if (A[K] + M < A[P-1]) return false;
  if (V <= P) return true;

  LL votes_left = M * (LL)(V-P);
  FOR(i,P-1,N) {
    if (i == K) continue;
    votes_left -= min(M, A[K]+M-A[i]);
  }
  return votes_left <= 0;
}

