    long long int V, P;

    cin >> N >> M >> V >> P;

    long long int A[N];

    for (long long int i = 0; i < N; i++)
    {
        cin >> A[i];
    }

    sort(A, A + N);

    long long int possibleUse = 0;
    long long int key = N - P;

    if (V < P)
    {
        for (long long int i = 0; i < key; i++)
        {
            if (A[i] + M >= A[key])
            {
                possibleUse++;
            }
        }
    }
    else
    {
        for (long long int i = 0; i < key; i++)
        {
            long long int voteSum = M * V;

            voteSum -= (P - 1) * M; //高い方から
            voteSum -= (i + 1) * M; //低い方から

            long long int score_i = A[i] + M; // i問目の点数

            if (score_i >= A[key])
            {
                for (long long int j = key; j > i; j--)
                {
                    voteSum -= score_i - A[j];
                    if (voteSum <= 0)
                    {
                        possibleUse++;
                        break;
                    }
                }
            }
        }
    }

    possibleUse += N - key;

    // for (long long int i = key; i < N; i++)
