		}
		sum += m;
		ll ave = sum/(n-v+1);
		ll sur = sum%(n-v+1);
		for(ll i = 0;i<(n-v+1);i++)
		{
			B[(mid-i-1+n)%n]= ave;
			if(i<sur)B[(mid-i-1+n)%n]++;
		}
		ll po = B[mid];
		sort(B.begin(),B.end(),greater<>());
		if(B[p-1]<=po)
		{
			l = mid;
		}
		else
		{
			r = mid;
		}
		if(r-l<2)break;
	}	
	cout<<r<<endl;
	return 0;
}

