const int maxn = 2e5;

int n, m, V, P;
int A[maxn];

bool Check(int i) {
  int h_start = n - (P - 1);
  if (h_start <= i) --h_start;
  int l_end = h_start - 1;
  if (l_end == i) --l_end;
  int lim = A[i] + m;

  li rest = (P - 1) * m;
  for (int j = 0; j <= l_end; ++j) {
    if (j == i) continue;
    if (A[j] > lim) return false;
    rest += min(m, lim - A[j]);
  }
  return rest >= (li)m * (V - 1);
}

int main(void) {
  scanf("%d%d%d%d", &n, &m, &V, &P);
  for (int i = 0; i < n; ++i) {
    scanf("%d", A + i);
  }
  sort(A, A + n);
  int l = 0, r = n;
  while (r - l > 1) {
    int mid = l + r >> 1;
    if (Check(mid - 1)) {
      r = mid;
    } else {
      l = mid;
    }
  }
  printf("%d\n", n - l);
  return 0;
}

