		cin >> A[i];
	}
	sort(all(A));

	auto f = [&](int x) {
		if (x >= N - P)return true;

		RangeAddQuery raq(N);

		rep(i, 0, N) {
			raq.add(i, i + 1, A[i]);
		}

		int y = x + 1;
		int m = M;
		while (A[x] == raq.get(y)) {
			y++;
			if (y == N)
				return true;
		}
		while (m) {
			int Y = raq.get(y) - A[x];
			raq.add(y, min(y + (N - V), N), -min(Y, m));
			m -= min(Y, m);

			while (A[x] == raq.get(y)) {
				y++;
				if (y == N)
					return true;
			}
		}

		if (raq.get(N - P) <= A[x]) {
			return true;
		}

		return false;
	};
	auto binarySearch = [&](int ng, int ok) {
		if (f(ng))return ng;
		while (ng + 1 < ok) {
			int m = (ng + ok) / 2;
			if (f(m))
				ok = m;
			else
				ng = m;
		}
		return ok;
	};

