        rep(i, pos + 1) {
            aa[i] += m;
        }
        if (aa[i] < aa[n - p]) {
            return false;
        }
        rest -= pos + 1;
        if (rest <= p - 1) {
            rep(i, rest) {
                aa[n - 1 - i] += m;
            }
        } else {
            rep(i, p - 1) {
                aa[n - 1 - i] += m;
            }
            rest -= p - 1;
            vector<li> aaa;
            repp(i, pos + 1, n - p + 1) {
                aaa.pb(aa[pos] - aa[i]);
                if (aaa.back() < 0) {
                    return false;
                }
            }
            priority_queue<li> pq;
            rep(i, rest) {
                pq.push(m);
            }
            for (auto v : aaa) {
                if (pq.empty()) {
                    break;
                }
                li now = pq.top();
                pq.pop();
                now -= min(now, v);
                if (now > 0) {
                    pq.push(now);
                }
            }
            return pq.empty();
        }
    }
    //cout << pos << " : "; dumpi(aa);
    li orig = aa[pos];
    sort(allof(aa));
    auto it = upper_bound(allof(aa), orig);
    it--;
    auto idx = it - aa.begin();
    //p5(pos, orig, *it, idx, (idx >= n - p));
    return idx >= n - p;
}

int main() {
