int main() {
  //input
  int64_t N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int> A(N);
  rep(i,N) {
    cin >> A.at(i);
  }
  //calc
  sort(A.begin(), A.end());
  map<int64_t,int64_t> group;
  vector<int64_t> uniq_v(0);
  int64_t AA;
  rep(i,N) {
    AA = A.at(i);
    if ( group.count(AA) ) {
      group[AA]++;
    }
    else {
      group[AA] = 1;
      uniq_v.push_back(AA);
    }
  }
  sort(uniq_v.begin(), uniq_v.end());
  int64_t VV = 0;
  int64_t un = uniq_v.size();
  int64_t i = 0;
  while ( i < un && VV < V ) {
