  }
  int64_t S_L = 0;
  for(int k = 0; k < i; k++) {
    if ( uniq_v.at(k) + M >= L_min ) {
      S_L += group[uniq_v.at(k)];
    }
  }
  int64_t answer = max(P, N_L + S_L);
