        }
    }

    //cout << "num = " << num << endl;

    // rep(i, N) {
    //     cout << A[i] << " ";
    // }
    // cout << endl;

    LazySegmentTree lst(A);
    ll ans = num;
    for (int i=num; i<N; ++i) {

        bool debug = false;
        // 右側を更新する
        lst.add(i, min(N, i+V), M);

        // 残りこれだけ
