typedef long long ll;
ll n, m, v, p;
vector<ll> a;

bool cond(int x){
	if(x <= p-1) return true;
	if(a[p-1] > a[x] + m) return false;

	ll votes = (p - 1) * m + (n - x) * m;
	for(int i = p; i < x; i++){
		votes += a[x] + m - a[i];
	} 

	return votes >= m * v;
}

// condを満たす最大のxを求める(upper_bound)
// 全てのxが条件を満たさない場合は-1を返す(-1はとりえない値)
int upper_bound_cond(){
	int lb = -1, ub = n;

	while(ub - lb > 1){
		int mid = (lb + ub) / 2;

		if(cond(mid)) lb = mid;   // Answer is in [mid, ub)
		else ub = mid;            // Answer is in [lb, mid)
	}

	// now lb + 1 = ub
	return lb;
}

