        }
        ll sum = 0;
        for(ll i = 0; i <= n - p; i++) {
            if(i == mid) continue;
            ll dif = a[mid] + m - a[i];
            if(dif > m) dif = m;
            sum += dif;
        }
        if(sum < m * (v - p)) check = false;
        if(check) ok = mid;
        else ng = mid;
    }
    cout << n - ok << endl;
    return;
}

