int n, m, v, p;
vector <int> a;

bool check(int pos) {
	int vv = v;
	vv -= n - pos;
	vv -= p - 1;
	if (vv <= 0 && a[pos] + m >= a[p - 1]) {
		return true;
	} else if (vv <= 0) {
		return false;
	}
	vector <int> b;
	for (int i = p - 1; i < pos; i++) {
		b.push_back(a[i]);
	}
	int sz = (int) b.size();
	int fval = a[pos] + m;
	ll sum = 0;
	for (int i = 0; i < sz; i++) {
		int t = fval - b[i];
		sum += min(m, fval - b[i]);
	}
	int cntt = 0;
	for (int i = 0; i < sz; i++) {
		if (b[i] == b[sz - 1]) {
			cntt++;
		}
	}
	if (cntt >= vv && sum >= vv * m) {
		return true;
	}
	return false;
}

int32_t main() {
	cin >> n >> m >> v >> p;
	a.resize(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}
	map <int, int> poss;
	sort(a.begin(), a.end());
	reverse(a.begin(), a.end());
	for (int i = 0; i < n; i++) {
		//cout << a[i] << ' ';
	}
	//cout << '\n';
	int l = 0, r = n - 1;
	int res = 0;
	while (l <= r) {
		int mid = (l + r) / 2;
		if (check(mid)) {
			l = mid + 1;
			res = mid;
		} else {
			r = mid - 1;
		}
	}
	for (int i = 0; i < n; i++) {
		if (a[i] >= a[res]) {
			poss[a[i]] = true;
		}
	}
	int ans = 0;
	for (int i = 0; i < n; i++) {
		if (poss[a[i]]) {
			ans++;
		}
	}
	//check(7);
	cout << ans << '\n';
	//system("pause");
	return 0;
}

