void solve(long long N, long long M, long long V, long long P, std::vector<long long> A){

    sort(rall(A));

    ll ap = A[P - 1];
    int lo = 0, hi = N;
    while(hi - lo > 1) {
        int mid = lo + (hi - lo) / 2;
        if (mid < P) lo = mid;
        else if (A[mid] + M < ap) hi = mid;
        else {
            ll tmp = 0;
            rep(i, P - 1) tmp += M;
            for(int i = P - 1; i <= mid; i++) {
                tmp += max(0LL, A[mid] + M - A[i]);
            }
            for (int i = mid + 1; i < N; i++) tmp += M;
            if (tmp < M * V) hi = mid;
            else lo = mid;
        }
    }
    cout << lo + 1 << endl;
}

