int main(){
    ll N,M,V,P; cin >> N >> M >> V >> P;
    vector<Pl> A(N);
    rep(i,N){
        cin >> A[i].first;
        A[i].second = i;
    }

    sort(A.begin(),A.end());
    int ok = N-1,ng = -1;
    while(ok-ng > 1){
        vector<Pl> B = A;
        int mid = (ok+ng)/2;
        bool flag = false;
        if(mid+1 >= V){
            if(N-mid <= P) flag = true;
        }
        ll k = V-(mid+1);
        B[mid].first += M;
        ll t = B[mid].first;
        ll sum = 0;
        vector<ll> used(N);
        repr(i,mid+1,N){
            ll d = max(t-B[i].first,0LL);
            B[i].first += d;
            sum += d;
            used[i] += d;
            if(sum >= k*M){
                B[i].first -= sum-k*M;
                used[i] -= sum-k*M;
                break;
            }
        }
        ll e = max(k*M-sum,0LL);
        ll sum2 = 0;
        for(int i = N-1; i >= mid+1; i--){
            B[i].first += M-used[i];
            sum2 += M-used[i];
            if(sum2 >= e){
                B[i].first -= sum2-e;
                break;
            }
        }
        sort(B.begin(),B.end(),greater<Pl>());
        rep(i,P){
            if(B[i].first == t) flag = true;
        }
        if(flag) ok = mid;
        else ng = mid;
    }
    cout << N-ok << endl;

}

