int n, m, v, p;
bool check(vi a, int pos) {
    vpi kek(n);
    for (int i = 0; i < n; i++) {
        kek[i] = {a[i], i};
    }
    int cnt = (v - 1) * m;
    vector <int> us(n);
    kek[pos].first += m;
    us[pos] = m;
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (kek[i].first <= kek[pos].first)
            continue;
        int y = min(m, cnt);
        us[i] = y;
        ans++;
        cnt -= y;
    }
    if (ans > p)
        return false;
    if (cnt == 0) 
        return true;
    for (int i = 0; i < n; i++) {
        if (kek[i].first > kek[pos].first || pos == i)
            continue;
        int y = min(min(kek[pos].first - kek[i].first, m), cnt);
        us[i] = y;
        cnt -= y;
    }
    if (cnt == 0)
        return true;

    vi lol;
    for (int i = 0; i < n; i++) {
        if (i == pos || cnt == 0) {
            continue;
        }
        if (us[i] != m) {
            lol.push_back(us[i]);
        }
    }
    sort(RALL(lol));
    for (int i = 0; i < lol.size(); i++) {
        if (cnt == 0)
            break;
        int y = min(m - lol[i], cnt);
        cnt -= y;
        ans++;
    }
    if (ans > p)
        return false;

    return true;
}

