using namespace std;

long long N, M, V, P;
vector<long long> A;

bool possible(int index) {
    while (index > 0 && A[index] == A[index - 1])
        index--;

    if (index < P)
        return true;

    long long automatic = P - 1 + N - index;

    if (automatic >= V)
        return A[index] + M >= A[P - 1];

    long long still_need_per_judge = V - automatic;
    long long still_to_add = M * still_need_per_judge;
    long long target = A[index] + M;

    for (int i = P - 1; i < index; i++) {
        long long take = min(M, target - A[i]);
        take = min(take, still_to_add);
        take = max(take, 0LL);

        if (A[i] + take > target)
            return false;

        still_to_add -= take;
    }

    return still_to_add == 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> V >> P;
    A.resize(N);

    for (auto &a : A)
        cin >> a;

    sort(A.rbegin(), A.rend());
    int low = 0, high = N;

    while (low < high) {
        int mid = (low + high) / 2;

        if (possible(mid))
            low = mid + 1;
        else
            high = mid;
    }

    cout << low << '\n';
}

