LL a[N], b[N];

bool check(int x, int n, LL m, LL v, LL p){
  b[x] += m;
  v--;
  vector<pair<int, int>> pp(n);
  RF(i, n-1, n-p+1){
    if(i == x) return true;
    if(v) b[i] += m;
    else break;
    v--;
  }
  LL point = m*v;  
  RF(i, n-p, 0){
    if(i == x) continue;
    LL k = max((LL)0, min(b[x]-b[i], min(point, v)));
    b[i] += k;
    point -= k;
  }
  if(point) return false;
  else {
    F(i, 0, n-1){
      pp[i] = MP(b[i], i);
    }
    sort(pp.begin(), pp.end());
    int pos = 1;
    LL bef = pp[n-1].first;
    RF(i, n-1, 0){
      if(bef > pp[i].first) pos++;
      bef = pp[i].first;
      if(pp[i].second == x){
        return (pos <= p);
      }
    }  
  }
  return false;
}

int solve(){
  int n;
  LL m, v, p;
  cin >> n >> m >> v >> p;
  int l = 0, r=n-1, mid;
  F(i, 0, n-1) cin >> a[i];
  sort(a, a+n);
  while(l != r){
    F(i, 0, n-1) b[i] = a[i];
    mid = (l+r)/2;
    if(check(mid, n, m, v, p)){
      r = mid;
    } else {
      l = mid+1;
    }
  }
  cout << n - l << endl;
  return 0;
}

void fun(){
  int t = 1;
  // cin >> t;
  while(t--) solve();
} 

