int main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL);
    cin >> n >> m >> v >> p;

    rep(i, 0, n) {
        cin >> a[i];
    }

    sort(a, a+n);

    pre[0] = a[0];
    rep(i, 1, n) {
        pre[i] = pre[i-1] + a[i];
    }

    int ans = 0;

    rep(i, 0, n) {
        int lastSame = upper_bound(a+i+1, a+n, a[i]) - a - 1;
        if (n-lastSame <= p) {
            ans++;
            continue;
        }
        int t = max(0, v - (lastSame+1)); // v is at least 1 in the Problem, so we greedily vote the current Problem i and any small or equal Problem

        if (!t) {
            int movedTo = upper_bound(a+lastSame+1, a+n, a[i]+m) - a - 1;
            if (n-movedTo <= p)
                ans++;
        }
        // The case where t*m Votes remain after voting for the smallest (v-t) Problems by all m Judges
        else {
            int movedTo = upper_bound(a+lastSame+1, a+n, a[i]+m) - a - 1;
            int rank = n-movedTo;

            t -= n - (movedTo+1);
            if (t <= 0) {
                if (rank <= p)
                    ans++;
            }
            else {
                int range = movedTo - lastSame;
                ll s = sum(lastSame+1, movedTo);
                ll target = (ll) (a[i]+m) * range - s;
                ll votingPower = (ll) t * m;
                if (target >= votingPower && rank <= p) {
                    ans++;
                }
                else if ((votingPower - target) / m + rank <= p) {
                    ans++;
                }
            }
        }
    }

    cout << ans << '\n';

    return 0;
}

