int dat[N];

bool can(int idx) {
	while (idx < n-1 && dat[idx] == dat[idx+1]) idx++;
	int rem = n-v;
	for (int pos = idx+1; pos < n; pos++) {
		int tmp = dat[pos];
		if (pos - rem - idx > 0) {
			tmp += dat[pos - rem] - dat[idx];
		}
		if (dat[idx] + m < tmp) {
			// printf("pos = %d\n", pos);
			return (n-(pos-1) <= p);
		}
	}
	return true;
}

