        needDifSub += (i - P + 1) * ((tests[i - 1] - tests[i]) % (N - V));
        if(needDifSub / (N - V) > 0){
            ll t = needDifSub / (N - V);
            needDifSub -= t * (N - V);
            needDif += t;
        }
        if(needDif < M){
            ans++;
        }else{
            if(needDif == M && needDifSub == 0){
                ans++;
            }else{
                break;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

