const int mod = 998244353;
const int inf = 1'000'000'007;

int power(int x, int y) {
  if (y == 0) {
    return 1;
  }
  int z = power(x, y >> 1);
  z = z * 1ll * z % mod;
  if (y & 1) {
    z = z * 1ll * x % mod;
  }
  return z;
}

void solve() {
  int n, m, v, p;
  cin >> n >> m >> v >> p;
  vector<int> a(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }
  sort(a.begin(), a.end());
  reverse(a.begin(), a.end());

  auto can = [&](int pos) {
    if (a[pos] + m < a[p - 1]) {
      return false;
    }
    if (pos < p) {
      return true;
    }
    ll f = (p - 1) * 1ll * m + (n - pos) * 1ll * m;
    for (int i = p; i < pos; ++i) {
      f += a[pos] + m - a[i];
    }
    return f >= m * 1ll * v;
  };

  int ans = 0;
  for (int i = 30; i >= 0; --i) {
    if (ans + (1 << i) < n && can(ans + (1 << i))) {
      ans += (1 << i);
    }
  }
  cout << ans + 1 << "\n";
}

