void solve() {
    ll n, m, v, p;
    cin >> n >> m >> v >> p;
    vll a(n);
    rep(i, n) cin >> a[i];
    sort(a.begin(), a.end());
    ll ok = n - p, ng = -1;
    while(ok - ng > 1) {
        ll mid = (ok + ng) / 2;
        bool check = a[mid] + m >= a[n - p];
        if(!check) {
            ng = mid;
            continue;
        }
        ll sum = 0;
        for(ll i = 0; i <= n - p; i++) {
            if(i == mid) continue;
            ll dif = a[mid] + m - a[i];
            if(dif > m) dif = m;
            sum += dif;
        }
        if(sum < m * (v - p)) check = false;
        if(check) ok = mid;
        else ng = mid;
    }
    cout << n - ok << endl;
    return;
}

