  vector<lint> b(n, 0ll);
  rep(i, n) { b[i] = a[i]; }
  lint vv = v;
  b[i] += m;
  vv--;
  lint tmp = b[i];
  sort(all(b));
  int idx;
  for (lint i = n - 1; 0 <= i; i--) {
    if (b[i] == tmp) {
      idx = i;
      break;
    }
  }
  lint right = n - (idx + 1);
  lint left  = idx;
  if (right >= vv) {
    rep(i, vv) { b[idx + 1 + i] += m; }
  } else {
    rep(i, right) { b[idx + 1 + i] += m; }
    vv -= right;
    int times = 0;
    rep(i, vv) {
      if (b[i] + m <= tmp) {
        b[i] += m;
        times++;
      }
    }
    b[idx - 1] += (vv - times) * m;
  }
  sort(all(b));
  reverse(all(b));
  // for (int i = 0; i < n; i++) {
