const int max_n = 100111, inf = 1000111222;

int n, m, v, p, a[max_n];
long long sum[max_n];

long long get_sum(int l, int r) {
    if (l == 0) {
        return sum[r];
    }
    return sum[r] - sum[l - 1];
}

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    scanf("%d%d%d%d", &n, &m, &v, &p);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }
    sort(a, a + n);
    reverse(a, a + n);
    sum[0] = a[0];
    for (int i = 1; i < n; ++i) {
        sum[i] = sum[i - 1] + a[i];
    }
    int ans = p;
    int pos = p - 1;
    for (int i = p; i < n; ++i) {
        int x = a[i] + m;
        if (x < a[p - 1]) {
            break;
        }
        while (pos < n && x - a[pos] <= m) {
            ++pos;
        }
        long long sum = 1LL * (pos - p + 1) * x - get_sum(p - 1, pos - 1);
        sum += 1LL * (n - pos) * m;
        sum -= min(x - a[i], m);
        //cout << i << ": " << sum << "  " << pos << endl;
        if (sum >= 1LL * m * (v - p)) {
            ++ans;
        }
    }
    printf("%d\n", ans);
    return 0;
}

