void MAIN() {

    cin >> n >> m >> v >> p;
    fori (i, n) cin >> ar[i];
    sort(ar, ar + n, greater<ll>());
    ll l = p - 1, r = n;
    while (r - l > 1) {
        ll d = (l + r) / 2;
        ll f = ar[d] + m;
        if (f < ar[p - 1]) {
            r = d;
            continue;
        }
        ll s = 0;
        forifrom (i, p - 1, n) {
            if (i == d) continue;
            s += min(m, f - ar[i]);
        }
        if (s >= m * (v - p)) {
            l = d;
        } else {
            r = d;
        }
    }
    cout << l + 1 << '\n';

}

