void solve()
{
    int n, V, P; ll M;
    scanf("%d%lld%d%d", &n, &M, &V, &P);
    vector<ll> a(n);
    int i;
    for (i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }
    sort(a.begin(), a.end());

    int l = -1, r = n;
    while (r - l > 1) {
        int m = (l + r) / 2;
        ll cnt = (ll)M * ((ll)P+m);
        int bad = 0;
        for (i = m + 1; i <= n - P; i++) {
            if(a[m]+M-a[i]<0) bad=1;
            cnt += (a[m] + M - a[i]);
        }
        if (cnt > (ll)M*V && bad==0) {
            r = m;
        }
        else {
            l = m;
        }
    }
    printf("%d\n", n-r);

    return;
}

