using namespace std;

long long MOD = 1000000007;

int N, M, V, P;

int bin_search(int l, int r, vector<int> &A){
    int mid=(l+r)/2;
    if(mid==l){
        return l;
    }

    long long value = A[mid]+M;

    if(value<A[P-1]){
        return bin_search(l, mid, A);
    }
    if(V<=P){
        return bin_search(mid, r, A);
    }else if(V>P && mid<N-V+P){
        return bin_search(mid, r, A);
    }else{
        long long diff=(V-P-(N-mid-1));
        long long cnt=(long long) diff*M;
        for(int i=P-1; i<mid; i++){
            //cout << cnt << endl;
            cnt-=min((long long) M, value-A[i]);
        }
        //cout << cnt << endl;
        if(cnt<=0){
            return bin_search(mid, r, A);
        }else{
            return bin_search(l, mid, A);
        }
    }
}

int main(){
    cin >> N >> M >> V >> P;
    vector<int> A(N,0);
    for(int i=0; i<N; i++){
        cin >> A[i];
    }

    sort(A.rbegin(), A.rend());

    cout << bin_search(P-1, N, A)+1 << endl;
}

