int main(void) {
  int64_t N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<int64_t> A(N);
  rep(i, N) { cin >> A[i]; }
  sort(A.begin(), A.end(), greater<int>());

  int left = 0;
  int right = N - 1;
  while (left <= right) {
    int mid = left + (right - left) / 2;
    if ((A[mid] + M) < A[P - 1]) {
      right = mid - 1;
      continue;
    }
    int64_t point = M * V;
    point -= M * (1 + (P - 1) + (N - mid - 1));
    for (int j = P; j < mid; ++j) {
      if (A[j] < (A[mid] + M)) {
        point -= (A[mid] + M - A[j]);
      }
    }
    if (point <= 0) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  int answer = left;
  cout << answer << endl;
  return 0;
}

