	sort(b+1,b+1+n);
	reverse(b+1,b+1+n);
	for(int i=1;i<=n;i++)
		if(b[i]==val)
		{
			x=i;
			break;
		}
	if(x>p)
		return 0;
	b[x]-=m;
	v-=x;
	for(int i=1;i<=x;i++)
		b[i]+=m;
	sort(b+1,b+1+n);
	reverse(b+1,b+1+n);

	LL cnt=v*m;
	vector<LL> add;
	for(int i=x+1;i<=n;i++)
	{
		LL d=min(min(b[x]-b[i],m),cnt);
