int checker(std::vector<int>& a, int n, int m, int v, int p, int mid)
{
    if (mid >= n - p) {
        return 1;
    } else if (a[mid] + m < a[n - p]) {
        return 0;
    }
    int sum = m * (v - 1);
    sum -= (mid + (p - 1)) * m;
    if (sum <= 0) {
        return 1;
    } else {
        for (int i = mid + 1; i <= n - p; i++) {
            sum -= min((int)m, a[mid] + m - a[i]);
        }
        if (sum <= 0) {
            return 1;
        } else {
            return 0;
        }
    }
}


