bool isOK(int id) {
  if (id == -1) return false;
  if (id == N) return true;
  //
  memcpy(aC, a, sizeof(int) * N);
  // auto itr = upper_bound(a, a + N, a[id] + M);
  //  int pos = distance(a, itr);
  int cnt = M * (V - 1);
  aC[id] += M;
  int i = 0;
  while (1) {
    DUMP(i, cnt);
    DUMP(i, a[i], aC[i], a[id], M);
    if (cnt == 0) break;
    if (i == id) {
      i++;
      continue;
    }
    if (i == N || a[i] >= a[id] + M) break;
    int val = min(M, min(a[id] + M - a[i], cnt));
    aC[i] += val;
    cnt -= val;
    i++;
  }
  REPR(i, N - 1) {
    if (cnt == 0) break;
    int val = min(M - (aC[i] - a[i]), cnt);
    aC[i] += val;
    cnt -= val;
  }
  DUMP(id);
  PRINTARR(a, a + N);
  PRINTARR(aC, aC + N);
  assert(cnt == 0);
  // assert(accumulate(a, a + N, 0) + M * V == accumulate(aC, aC + N, 0));
  //  REP(i, V) aC[(id - i + N) % N] += M;
  int val = aC[id];
  sort(aC, aC + N);
  auto itr = upper_bound(aC, aC + N, val);  //奥
  int pos = N - distance(aC, itr);          //より大きい要素数
  PRINTARR(a, a + N);
  DUMP(id, pos < P);
  PRINTARR(aC, aC + N);
  return pos < P;
}
