  sort(a, a + N);

  //初期値は異なる。
  int left = -1;
  int right = N;
  DUMP(isOK(N - 1));
  DUMP(isOK(0));
  while (right - left > 1) {
    int mid = (left + right) / 2;
    // left trueの場合
    if (isOK(mid))
      right = mid;
    else
      left = mid;
  }
  print(N - right);
}

