#define rep(i, n) for(ll i = 0; i < n; i++)
#define exrep(i, a, b) for(ll i = a; i <= b; i++)
#define out(x) cout << x << endl
#define exout(x) printf("%.10f\n", x)
#define chmax(x, y) x = max(x, y)
#define chmin(x, y) x = min(x, y)
#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define pb push_back
#define re0 return 0
const ll mod = 1000000007;
const ll INF = 1e16;
const ll MAX_N = 100010;

int main() {
    ll n, M, V, P;
    cin >> n >> M >> V >> P;

    vl a(n+1);
    a[0] = INF;
    exrep(i, 1, n) {
        cin >> a[i];
    }
    sort(rall(a));

    // aを降順にソートすると、a[i]が採用されるならばa[1],a[2],…,a[i-1]も採用される
    // なので「x番目に初期スコアが高い問題は採用されるか？」という判定問題で二分探索すればよい
    // x <= P の場合問題xは採用される
    // a[x] + M < a[P] の場合問題xは採用されない
    // それ以外の場合は「1,2,…,P-1 & x」番目の問題が採用されるようにするのが最適
    // なぜなら問題xはP-1問を除いて他のすべての問題よりスコアが高くなる必要があるので、除くP-1問としてはスコアの大きい方から順に選ぶべきだから
    // 全ジャッジが問題1,2,…,P-1 & xに投票するとしてよい
    // 問題x+1,x+2,…,nも問題xよりスコアが高くなることはないので全ジャッジが投票してよい
    // そして投票後の問題xのスコアは a[x] + M なので、P <= i < x なるiについては a[x] + M - a[i] 人まで投票してよい
    // 以上より入れられてもかまわない票の総数yは、 y = M * (P + n - x) + (sum_{P <= i < x} (a[x] + M - a[i])) となる
    // y < M*V のとき問題xに採用される可能性はない
    // M*V <= y のとき問題xに採用される可能性があることを示す
    // 問題iに入れられてもかまわない票の数をb[i](<=M)とし、(sum_{1 <= i <= n} b[i]) >= M*V と仮定する
    // 問題iがiの昇順でb[i]回連続で現れる数列を考えこの数列の最初のM*V問にジャッジ1,2,…,M,1,2,…,M,…,1,2,…,Mと票を割り当てる
    // このときどの問題に入る票数もb[i]以下で、どのジャッジもV票を投じ、どのジャッジも同じ問題に二度投票していない
    // よって M*V <= y のとき問題xに採用される可能性があるといえる

    ll left = 0;
    ll right = n+1;
    while(right - left > 1) {
        ll mid = (left + right)/2;
        ll x = mid;
        if(x <= P) {
            left = mid;
        }
        else if(a[x] + M < a[P]) {
            right = mid;
        }
        else {
            ll y = M * (P + n - x);
            exrep(i, P, x-1) {
                y += a[x] + M - a[i];
            }
            if(M*V <= y) {
                left = mid;
            }
            else {
                right = mid;
            }
        }
    }

    out(left);
    re0;
}

