using namespace std;

int binary_search(vector<int> &a, int x){
    int ok = a.size();
    int ng = - 1;
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (a[mid] >= x) ok = mid;
        else ng = mid;
    }
    return ok;
}

int main(){
    int n, m, v, p;
    cin >> n >> m >> v >> p;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    int ok = a.size();
    int ng = - 1;
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        int below_x = binary_search(a, a[mid]);
        int above_x = binary_search(a, a[mid] + m + 1);
        long long tmp = 0;
        tmp += (long long)below_x * m;
        tmp += (n - above_x) * m;
        for (int i = below_x; i < above_x; i++){
            if (i == mid) continue;
            tmp += m - (a[i] - a[mid]);
        }
        int z = n - above_x;
        bool flag = false;
        if (z < p && tmp >= (long long)m * (v - 1)) flag = true;
        int now = above_x - 1;
        while (tmp < (long long)m * (v - 1)){
            if (now == mid) break; 
            tmp += a[now] - a[mid];
            z++;
            if (z >= p) break;
            if (tmp >= (long long)m * (v - 1)) flag = true;
            now--;
        }
        if (flag) ok = mid;
        else ng = mid;
    }
    cout << n - binary_search(a, a[ok]) << endl;
}

