bool possible(const vector<int> &arr, int x) {
    if(x <= p) return true;
    if(arr[p] - arr[x] > m) return false;
    int votes = 0;
    for(int i = 1; i <= n; ++i) {
        if(i <= (p-1)) votes += m;
        else if(i >= x) votes += m;
        else {
            votes += max(0LL, arr[x]+m - arr[i]);
        }
    }
    return votes >= m*v;
}

