bool isPossible(LL target, int V, LL M, VEC<LL> &C) {
  // isPossible? max(C) is less than or equal target.
  //DUMP("isPossible", target, V, M, C);
  if (V == 0) {
    return C[0] <= target;
  }
  if (C[0] > target) {
    return false;
  }
  priority_queue<LL, VEC<LL>, greater<LL>> pq;
  REP(i, 0, C.size()) { pq.push(C[i]); }
  LL cnt = 0;
  LL prev = 0;
  while (cnt < M) {
    VEC<LL> tmp;
    LL ma = 0;
    REP(i, 0, V) {
      LL a = pq.top();
      pq.pop();
      tmp.push_back(a);
      ma = max(ma, a);
    }
    // //DUMP("isPossible loop", cnt, pq.top(), tmp);
    if (ma > target) {
      return false;
    }
    cnt += (target - ma);
    if (cnt >= M) break;
    REP(i, 0, tmp.size()) {
      tmp[i] += target - ma;
      pq.push(tmp[i]);
    }
    if (cnt == prev) {
      return false;
    }
    prev = cnt;
  }
  return true;
}
LL ProbT(LL N, LL M, LL V, VEC<LL> &C) {
  // return value
  //DUMP("ProbT", N, M, V, C);
  LL possi = 1e9 + 1;
  LL cant = 0;
  while (possi - cant > 1) {
    LL mid = (possi + cant) / 2;
    if (isPossible(mid, V, M, C)) {
      //DUMP("ProbT", mid, "is possible");
      possi = mid;
    } else {
      //DUMP("ProbT", mid, "is not possible");
      cant = mid;
    }
  }
  return possi;
}
LL ProbS(int jj, LL N, LL M, LL V, LL P, VEC<LL> &A) {
  // return value
  //DUMP("ProbS", jj, N, M, V, P, A);
  VEC<LL> B = A;
  B.erase(B.begin() + jj);
  // //DUMP("ProbS, B", B);

  VEC<LL> C = VEC<LL>(B.begin() + P - 1, B.end());
  return ProbT(N - P, M, V - P, C);
}

