#define N_ 101000
using namespace std;
long long w[N_], K, m, T[N_], U[N_];
int n, P;
bool OK(int pv) {
	int i, cnt = 0;
	for (i = 1; i <= n; i++) {
		if (i != pv)T[++cnt] = w[i];
	}
	long long z = w[pv] + m;
	long long rem = (K - 1)*m;
	for (i = 1; i <= cnt; i++) {
		long long t;
		if (z >= T[i]) {
			t = min(min(rem, z - T[i]), m);
		}
		else {
			t = min(rem, m);
		}
		rem -= t;
		U[i] = t;
		T[i] += t;
	}
	for (i = cnt; i >= 1 && rem; i--) {
		long long t;
		if (z >= T[i]) {
			t = min(rem, m - U[i]);
			T[i] += t;
			U[i] += t;
			rem -= t;
		}
	}
	int r = 1;
	for (i = 1; i <= cnt; i++) {
		if (T[i] > z)r++;
	}
	return r <= P;

}
int main() {
	int i;
	scanf("%d%lld%lld%d", &n, &m, &K, &P);
	for (i = 1; i <= n; i++) {
		scanf("%lld", &w[i]);
	}
	sort(w + 1, w + n + 1);
	int b = 1, e = n, mid, r=0;
	while (b <= e) {
		mid = (b + e) >> 1;
		if (OK(mid)) {
			r = mid;
			e = mid - 1;
		}
		else b = mid + 1;
	}
	printf("%d\n", n - r + 1);
}

