    vector<long long> A(N);
    for (long long &a : A)
    {
        cin >> a;
    }
    sort(A.rbegin(), A.rend());

    V -= P - 1;
    long long total = M * V;
    long long target = A[P - 1];

    vector<long long> diff;
    diff.push_back(0);
    for (int i = P; i < N; i++)
    {
        diff.push_back(min(M, target - A[i]));
    }
    for (long long d : diff)
    {
        total -= d;
    }
    diff.push_back(1e10);

    long long ans = P;
    if (total <= 0)
    {
        for (int i = P; i < N; i++)
        {
            if (A[i] + M >= target)
            {
                ans++;
            }
        }
    }
    else
    {
        set<long long> dset;
        for (long long d : diff)
        {
            if (d < M)
            {
                dset.insert(d);
            }
        }
        long long prev = M;
        for (auto itr = dset.rbegin(); itr != dset.rend(); itr++)
        {
            long long m = *itr;
            long long l = 0;
            long long r = diff.size() - 1;
            while (r - l > 1)
            {
                long long c = (l + r) / 2;
                if (diff[c] > m)
                {
                    r = c;
                }
                else
                {
                    l = c;
                }
            }
            assert(prev > m);
            total -= l * (prev - m);
            if (total <= 0)
            {
                ans += l;
                break;
            }
            prev = m;
        }
    }
