bool cmp(const int aa, const int bb)
{
	return aa > bb;
}

bool isValid(int k) 
{
	ll sum = m * v;
	int tmp = a[k] + m;
	sum -= (n - k)*m;
	sum -= (p - 1)*m;
	if (sum <= 0) {
		if (tmp >= a[p - 1]) return true;
		else return false;
	}
	else {
		if (tmp < a[p - 1]) return false;
		int ii = k - 1;
		while (sum > 0) {
			if (ii == p - 2) return false;
			sum -= (tmp - a[ii]);
			ii--;
		}
		return true;
	}
}

