int n,m,v,p;
vector<LL> A;

bool P(const int i, int v)
{
    if (n-i <= p)
        return true;
    const LL x = A[i]+m;
    const int j = n - min(p,v);
    if (x < A[j])
        return false;
    v -= n-(j+1)+1;
    v -= i;
    if (v > 0) {
        const int j = n - min(p-1, v-1);
        const int y = j-i;
        LL vol = x*y;
        FOR(k,i+1,j+1)
            vol -= A[k];
        return vol >= v*m;
    }
    return true;
}

