  vector<int> ds(N);
  for (int i = P; i < N; i++) {
    ds[i] = ds[i-1]+(A[P-1]-A[i]);
  }
  auto is_ok = [&](int i) {
    if (A[P - 1] - A[i] > M)
      return false;
    auto buf = ((P-1)+(N-i))*M + ds[i-1];
    return buf >= M*V;
  };
  int l = P, r = N-1;
  int ans = P;
  while (l <= r) {
    auto c = (l+r)/2;
    if (is_ok(c)) {
      ans = c+1;
      l = c+1;
    } else {
      r = c-1;
    }
  }
  cout << ans << endl;

  return 0;
}

