priority_queue<int> Q;
inline bool cmp(int x,int y){return x>y;}
inline bool check(int ps){
	if(a[ps]>=a[p])return 1;
	if(a[ps]+m<a[p])return 0;
	if(v<=p)return 1;
	int t=max(p,(int)(upper_bound(a+1,a+n+1,a[ps]+m,cmp)-a)),i,res=0,k=n-v+p,tmp;
	if(n-t<v-p)return 0;
	while(!Q.empty())Q.pop();
	for(i=0;i<v-p;++i)if(n-i!=ps)Q.push(a[n-i]);
	else Q.push(a[k--]);
	while(1){
		if(k==ps)--k;
		tmp=Q.top();Q.pop();
		if((res=a[ps]+m-tmp)>=m)return 1;
		if(k<t)return 0;
		Q.push(a[--k]-res);
	}
}
