using namespace std;

bool ispossible(int n, int m, int v, int p, const vector<int> &a, int k) {
  if (k == n) return false;
  int64_t s = 0;
  for (int i = 0; i < n; i++) {
    if (i < p - 1) {
      s += m;
    } else {
      s += min(m, a.at(k) + m - a.at(i));
    }
  }
  return s >= (int64_t) m * v;
}

int main() {
  int n, m, v, p;
  cin >> n >> m >> v >> p;
  vector<int> a(n);
  for (int i = 0; i < n; i++) cin >> a.at(i);
  sort(a.rbegin(), a.rend());
  int lower_bound = 0, upper_bound = n;
  while (upper_bound - lower_bound > 1) {
    int half = (lower_bound + upper_bound) / 2;
    if (ispossible(n, m, v, p, a, half)) {
      lower_bound = half;
    } else {
      upper_bound = half;
    }
  }
  cout << lower_bound + 1 << endl;
}

