#define rep1(i,n) for(ll i=1;i<=n;++i)
ll n;
bool judge(int i,vector<ll> &a,ll m,ll v,ll p,ll memo){
  ll tmpv=v-i-(p-1);
  ll sum=tmpv*m;
  bool ans=false;
  for(int j=memo+1;j<=n-p+1;j++){
    if(a[j]>=a[i]+m){
      break;
    }
    else {
      sum-=(a[i]+m-a[j]);
    }
    if(sum<=0){
      ans=true;
      break;
    }
  }
  return ans;
}
int main(){
  ll m,v,p;cin>>n>>m>>v>>p;
  bool tag=false;
  ll buf;
  vector<ll> a(n+1,0);
  rep1(i,n)cin>>a[i];
  sort(a.begin(),a.end());
  ll ans=0;
  for(int i=n;i>0;i--){
    if(i>=v&&v<n-p+1){
      if(a[i]+m>=a[n-p+1])ans++;
    }
    /*
    else if(i<v&&v<=n-p+1){
      int tmpp=p-(v-i);
      if(tmpp<=0)continue;
      if(a[i]+m>=a[n-tmpp+1])ans++;
    }*/
    else if(i>=v&&v>=n-p+1){
      ans++;
    }
    else{
      /*
      int tmpp=p-(v-i);
      if(tmpp<=0)continue;
      if(a[i]+m>=a[n-tmpp+1])ans++;*/
      int tmpv=v-i;
      if(p>tmpv){
        if(a[i]+m>=a[n-p+1])ans++;
      }
      else if(p<=tmpv){
        tag=true;
        buf=i;
        goto FINE;
      }
    }
  }
  FINE:
  int left=1;
  int right=buf;
  if(tag){
    while(right-left>1){
      int mid=(left+right)/2;
      if(judge(mid,a,m,v,p,buf))right=mid;
      else left=mid;
    }
  if(a[left]==a[right]){
    while(a[left]==a[right]){
      left--;
    }
    right=left+1;
  }
  if(judge(right,a,m,v,p,buf))
  ans=n-left;
  }
  cout<<ans<<endl;
  return 0;
}

