using namespace std;
typedef long long ll;
int main() {
  int n, m, v, p, f;
  cin >> n >> m >> v >> p;
  vector<int> A;
  for (int i = 0; i < n; i++) {
    cin >> f;
    A.push_back(f);
  }

  sort(A.begin(), A.end(), greater<int>()); //昇順ソート
  int p1, p2, p3, p4;
  p1 = A[p - 1]; //何もない時の前からp取るときの最低値
  for (int i = p - 2; i >= 0; i--) {
    if (A[i] > p1) {
      p2 = i + 1; //最低値より大きい個数。ここではジャッジ先にできる個数
      for (int j = p2; j < n; j++) {
        if (A[j] < p1) {
          p3 = j - p2; //最低値の個数。ジャッジ振り分け先がn-p3>vの場合
          p4 = j; //p4(0～最低値の数)が答えになる
          break;
        }
      }
      break;
    }
  }
  //得点によって最低値より上でも抜かされる可能性はある。考慮すべき？
//  cout << p2 << "," << p3 << "," << p4 << endl;
  if (n - p3 < v) {
    cout << p4;
  } else if (n - p3 == v) {
    //求め方は最低値以外のすべての数に対して+し、
    //p1(最低値)+m>未満値か
    //p-p2=(残り枠)で上記条件を満たさなくても定員を満たせば締め切っていく

    int p5;
    //p4は最低値の数なのでそこからスタート
    for (int i = p4 + 1; i < n; i++) {
      if (A[i] < p1 - m) {
//        cout << A[i] << "," << p1 - m << "," << i - p3 << endl;
        p5 = i + 1;
        break;
      } else if (p == i - p3) { //枠数の場合同じ値は順番替えれば入るので探す
        for (int j = i; j < n; j++) {
          if (A[i] < A[j]) {
            p5 = j - 1; //最低値の個数。
            break;
          }
        }
        break;
      }
    }
    cout << p5;
  } else {
    //求め方はp1(最低値)+m>未満を探し、
    //超の数+未満の数<=vならそれで終わり。
    //そうでないなら、n-p3-vで枠数を数え、枠数に当てはまる値を取得していれる。
    int p5, p6=-1;
    //p4は最低値の数なのでそこからスタート
    for (int i = p4 + 1; i < n; i++) {
      if (A[i] < p1 - m) {
        cout << A[i] << "," << p1 - m << "," << i - p3 << endl;
        if (i + 1 - p3 <= v) {
          p5 = i + 1;
        } else {
          for (int j = i; j >= 0; j--) {
            if (j + 1 - p3 <= v) {
              if(p6 >= 0){
                p5 = p6 + 1;
                break;

              }else{
                for (int k = j; k <n; k++) {
                  if (A[j] < A[k]) {
                    p5 = k - 1; //最低値の個数。
                    break;
                  }
                }
                break;
              }
            } else if (A[i] < A[j]) {
              p6 = j;
            }
          }
        }
        break;
      }
    }
    cout << p5;

  }
  return 0;
}

