//[left, right)
bool solve(ll n, ll left, ll right, int rem){
    ll val = rem * M;
    for(int i = left; i < right; i++){
        ll a = A[i];
        ll sub = 0;
        chmax(sub, min(n - a, M));
        val -= sub;
    }

    if(val <= 0) return true;
    else return false;
}

bool search(int idx){
    int free = (P-1) + (N-idx);
    int rem = V - free;
    ll num = 0;
    if(rem <= 0){
        num = A[P-1];
    }
    else{
        //ll left = A[idx];
        //ll right = 1e17;
        ll left = -1;
        ll right = 1e18;
        //ll right = 10;
        while(right - left > 1){
            ll mid = (right + left) / 2;
            bool valid = solve(mid, P-1, idx, rem);
            if(valid) right = mid;
            else left = mid;
        }
        num = right;
    }


    if(A[idx] + M >= num)
        return true;
    else
        return false;
}

