bool Cmp(int x, int y) {
	return x > y;
}

bool Valid(int d) {
	if (d <= p) return true;
	for (int i = d; i >= 1; --i) {
		if (a[i] != a[d]) {
			d = i + 1;
			break;
		}
	}
	ll s = (p + n - d) * m;
	for (int i = p; i < d; ++i) {
		if (a[d] + m < a[i]) return false;
		s += a[d] + m - a[i];
	}
	return s >= ll(m) * ll(v);
}

