struct PrefSum {
    vl s;
    PrefSum(vl a) {
        s.assign(isz(a) + 1, 0);
        for (int i = 0; i < isz(a); i++) {
            s[i+1] = s[i] + a[i];
        }
    }
    ll operator()(ll i, ll j) const {
        assert(0 <= i && i <= j && j+1 < isz(s));
        return s[j+1] - s[i];
    }
};
int main() {
    // solution
    ll n, m, v, p;
    while (std::cin >> n >> m >> v >> p) {
        vl a(n); std::cin >> a;
        std::sort(all(a),std::greater<>());
        PrefSum s(a);
        ll i = p;
        while (i < n && a[i-1] == a[i]) i++;
        watchln("------------------");
        watchln(a);
        watchln(i);
        while (i < n) {
            ll val = a[i] + m;
            ll total = v * m;
            total -= (n - i) * m;
            total -= (p - 1) * m;
            // sum on [p-1, ..., i-1]
            ll sum = s(p-1,i-1);
            total -= val * ((i-1) - (p-1) + 1) - sum;
            if (a[p-1] > val || total > 0) {
                break;
            }
            i++;
        }
        std::cout << i << std::endl;
    }
    return 0;
}

