int const N = 100000;
int x[N];

int main(){
	int n, m, v, p;
	scanf("%d%d%d%d", &n, &m, &v, &p);
	f(i, 0, n)scanf("%d", x + i);
	sort(x, x + n);
	reverse(x, x + n);
	int j = p;
	ll sm = 0;
	while (j < n){
		sm += x[j - 1];
		if (x[p - 1] - x[j] > m)break;
		int sad = j - (p - 1);
		int lft = v - (n - sad);
		int z = sad - lft;
		ll can = (ll)z * m;
		if (can < sm - (ll)x[j] * sad)break;
		++j;
	}
	printf("%d\n", j);
}

