        // 全ツッパしてもA[i]+M以下になる人が何人いるか iはここに含む
        LL under_A = distance(begin(A), upper_bound(ALL(A), A[i]));

        LL use = 0;
        // A[i]+Mより大きい人には全ツッパ
        use += M * over;

        // A[i]+M-V以下の人にも全ツッパ ※ここにiは含まれる
        use += M * under_A;

        // 全ツッパしていい人たち
        LL X = max(min(P - 1 - over, over_AplusM_pos - under_A), 0ll);
        use += M * X;

        // それ以外の人はA[i]+Mのところまで
        use += (over_AplusM_pos - X - under_A) * (A[i] + M)
               - (B[over_AplusM_pos - X] - B[under_A]);
        if (use >= M * V) ret++;
    }
    cout << ret << endl;
    return 0;
}

