		int mid = l + (r - l) / 2;
		std::vector<int> b;
		for (int i = 0; i < n; i++) if (i != mid) b.push_back(a[i]);
		b.erase(b.end() - (p - 1), b.end());
		auto ok = [&] () {
			for (auto &i : b) {
				if (i > a[mid] + m) return false;
				i = a[mid] + m - i;
			}
			std::reverse(b.begin(), b.end());


			int64_t sum = 0;
			for (int i = 1; i < n; i++) {
				sum += b[i - 1];
				// std::max(0, v + i - n) * m
				if (sum < (int64_t) std::max<int>(0, v + i - b.size()) * m) {
					return false;
				}
			}
			return true;
		};
		bool res = ok();
		if (res) r = mid;
		else l = mid;
	}
	std::cout << n - r << std::endl;

	return 0;
}

