  CumSum<long long> cs(A);
  {
    for(auto  a : A)
      cerr << a << " ";
    cerr << endl;
  }

  int ans = 0;
  for(int i = 0; i < N; ++i){
    long long r = M*V - i*M;
    r -= (P-1)*M;
    long long k = V - i - (P-1);
    if(k > 0){
      int j = upper_bound(A.begin(), A.end(), A[i]+M) - A.begin();
      j = min<long long>(j,N-(P-1)+1);
      int d = j-i-1;
      long long x = d*(A[i]+M) - cs.getsum(i+1,j);
      r -= x;
    }
    if(r <= 0) ++ans;
  }
  cout << ans << endl;
}

