    long long ans = P;
    if (total <= 0)
    {
        for (int i = P; i < N; i++)
        {
            if (A[i] + M >= target)
            {
                ans++;
            }
        }
    }
    else
    {
        set<long long> dset;
        for (long long d : diff)
        {
            if (d < M)
            {
                dset.insert(d);
            }
        }
        long long prev = M;
        for (auto itr = dset.rbegin(); itr != dset.rend(); itr++)
        {
            long long m = *itr;
            long long l = 0;
            long long r = diff.size() - 1;
            while (r - l > 1)
