int main()
{
	cin.tie(0);
	ios::sync_with_stdio(0);

    LL N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<LL> A(N);
    rep(i, N) cin >> A[i];
    sort(A.begin(), A.end());

    //! Binary search. (l, r]
    LL l = -1;
    LL r = N-1;

    while (1 < r-l) {
        LL m = (r+l) / 2;

        if (N-m <= P) {
            //! m is already in top P before adding points
            r = m;
            // cout << "N-m <= P, setting m to r" << endl;
        } else {
            // cout << "P < N-m" << endl;
            LL maxM = A[m]+M; //! the max points that m can take
            //! the best case for m is to distribute all points to low score problems in greedy way
            LL remaining = max(0LL, V-m-1) * M;

            //! distribute points to top (P-1) problems
            remaining -= (P-1) * M;
            remaining = max(0LL, remaining);

            // cout << "maxM, remaining = " << maxM << ' ' << remaining << endl;

            bool ok = true;
            for (LL i = N-P; ok && m < i; --i) {
                if (maxM < A[i]) {
                    ok = false;
                } else {
                    remaining -= min(M, maxM-A[i]);
                    remaining = max(0LL, remaining);
                }
            }
            if (0 < remaining) {
                // cout << "ok = false, because 0 < remaining" << endl; 
                ok = false;
            }

            if (ok) {
                r = m;
            } else {
                l = m;
            }
        }
        // cout << "BOTTOM l , r = " << l << ' ' << r << endl;
    }

    cout << (N-r) << endl;

    return 0;
}

