template<class F>
i64 bisect(i64 l, i64 r, F f) { // (l, r]
  if (r - l <= 1) return r;
  i64 m = l + (r - l) / 2;
  return f(m) ? bisect(l, m, f) : bisect(m, r, f);
}
template<class F>
i64 bisect_left(i64 l, i64 r, F f) {
  return bisect(l, r, [=](i64 x) { return !f(x); }) - 1;
}
i64 n, m, v, p;
vector<i64> a;
int main() {
    cin >> n >> m >> v >> p;
    read_n(a, n);
    sort(begin(a), end(a), greater<i64>());

    i64 ans = 1 + bisect_left(0, n, [&](i64 x) {
        if (x < p) return true;
        if (a[x] + m < a[p - 1]) return false;
        i64 s = a[x] + m;
        i64 u = v - (p - 1) - (n - x);
        if (u <= 0) return true;
        i64 sum = 0;
        for (int i = p; i < x; ++i) {
            sum += min(m, s - a[i]);
        }
        return sum >= u * m;
    });   

    cout << ans << endl;
    return 0;
}

