long long N, M, V, P;
std::vector<long long > A;

bool judge(long long n){
  if (n<P){ // 最初からP番目までであった場合は必ず選べるのでtrue
    return true;
  } else if (A[n]+M<A[P-1]){ // M票足しても最低必要な票数(左からP番目の人の数)に届かない
    return false;
  }
  long long sum = 0;
  for (int i=P-1; i<N; i++){
    if (i==n){
      continue;
    }
    sum += std::min(M, A[n]+M-A[i]);
  }
  if (sum >= M*(V-P)){
    return true;
  } else {
    return false;
  }
}

int main(){
  scanf("%lld", &N);
  scanf("%lld", &M);
  scanf("%lld", &V);
  scanf("%lld", &P);
  long long temp;
  for (int i=0; i<N; i++){
    scanf("%lld", &temp);
    A.push_back(temp);
  }
  sort(A.begin(), A.end(), std::greater<long long>());

  long long edge_start = 0;
  long long edge_end = N-1;
  long long cand;
  while (edge_end - edge_start > 1){
    cand = (edge_start+edge_end)/2;
    if (judge(cand)){
      edge_start = cand;
    } else {
      edge_end = cand;
    }
    //printf("[%lld, %lld]\n", edge_start, edge_end);
  }
  printf("%lld\n",edge_start+1);
  return 0;
}

