  cin >> N >> M >> v >> P;
  V<i64> A(N);
  REP(i, N) cin >> A[i];
  sort(A.rbegin(), A.rend());
  i64 pth = A[P - 1];

  auto check = [&](int x) -> bool {
    --x;
    if (x < P) return true;
    if (x > N - 1) return false;
    i64 cnt1 = (P - 1) + (N - x);
    i64 h = A[x] + M;
