      delta[i] += i > 0 ? delta[i - 1] : 0;
      i64 y = A[i] + delta[i];
      if (y > h) return false;
      i64 d = h - y;
      rem -= d;
      if (rem <= 0) return true;
      delta[i] += d;
      delta[i + window] -= d;
    }
    return false;
  };

  int ok = P, ng = N + 1;
