	if(mid<=p) return 1;
	if(a[mid]+m<a[p]) return 0;
	int ost=max(0,v-(n-mid+1)-(p-1));
	if(ost==0) return 1;
	for(int i=p;i<mid;i++) b[i-p+1]=a[mid]+m-a[i];
	int sz=mid-p;
	vector<pair<int,int>> v;
	v.push_back({-1,0});
	for(int i=1;i<=sz;i++)
	{
		//printf("%i ",b[i]);
		if(v.empty() || v.back().first!=b[i]) v.pb({b[i],0});
		v[(int)v.size()-1].second++;
	}
	//printf("\n");
	//reverse(v.begin(),v.end());
	//for(auto p:v) printf("(%i %i) ",p.first,p.second);
	//printf("\n");
	int work=m;
	int pre=0,sub=0;
	stack<pair<ll,int>> vals;
	vals.push({inf,0});
	//printf("mid:%i ost:%i\n",mid,ost);
	while(pre+v.back().second<ost)
	{
		pre+=v.back().second;
		vals.push(v.back());
		//printf(":D\n");
		v.pop_back();
	}
	int val_z,sz0,sz1;
	val_z=v.back().first;
	sz0=v.back().second;
	sz1=0;
	v.pop_back();
	auto BinarySearch=[&]()
	{
		int bot=0,top=work,mid,ans=0;
		ll val_y=vals.top().first-sub;
		int val_w=v.back().first;
		while(top>=bot)
		{
			mid=top+bot>>1;
			ll y=val_y-mid;
			int z=val_z-((ll)mid*(ost-pre)+sz1)/(sz0+sz1);
			int lo=((ll)mid*(ost-pre)+sz1)%(sz0+sz1);
			int w=val_w;
			bool ok=1;
			if(z==0 && lo>0) ok=0;
			if(y<z) ok=0;
			if(z<w) ok=0;
			if(ok) bot=mid+1,ans=mid;
			else top=mid-1;
		}
		return ans;
	};
	while(work)
	{
        int now=BinarySearch();
        //printf("%i %i %i %i %lld\n",val_z,sz0,sz1,now,vals.top().first-sub);
        if(now==0) return 0;
        work-=now;
        val_z-=((ll)now*(ost-pre)+sz1)/(sz0+sz1);
        int tmp_sz=((ll)now*(ost-pre)+sz1)%(sz0+sz1);
        tie(sz0,sz1)=mp(sz0+sz1-tmp_sz,tmp_sz);
        sub+=now;
        if(vals.top().first-sub==val_z)
		{
			sz0+=vals.top().second;
			pre-=vals.top().second;
			vals.pop();
		}
		if(v.back().first==val_z)
		{
			sz0+=v.back().second;
			v.pop_back();
		}
	}
	return 1;
}
