class Solve
{
  ll N, M, V, P;
  vector<ll> A;
  vector<ll> sum;

public:
  Solve(ll N, ll M, ll V, ll P, vector<ll> A) : N{N}, M{M}, V{V}, P{P}, A(A), sum(N + 1, 0LL)
  {
    sum[P - 1] = A[P - 1];
    for (auto i = P; i < N; i++)
    {
      sum[i] = A[i] + sum[i - 1];
    }
  }

  ll answer()
  {
    if (V <= P)
    {
      return answer0();
    }
    else
    {
      return answer1();
    }
  }

private:
  ll answer0()
  {
    ll ans{0};
    for (auto i = P; i < N; i++)
    {
      if (A[P - 1] <= A[i] + M)
      {
        ans++;
      }
    }
    return ans + P;
  }

  ll answer1()
  {
    ll ok{P - 1};
    ll ng{N};
    while (abs(ok - ng) > 1)
    {
      ll t{(ok + ng) / 2};
      if (test(t))
      {
        ok = t;
      }
      else
      {
        ng = t;
      }
    }
    assert(ng == N || A[ok] != A[ng]);
    return ok + 1;
  }

  bool test(ll i)
  {
    ll K{V - (P - 1) - (N - i)};
#if DEBUG == 1
    cerr << "i = " << i << ", K = " << K << endl;
#endif
    if (K <= 0)
    {
      return A[i] + M >= A[P - 1];
    }
#if DEBUG == 1
    cerr << "A[" << i << "] = " << A[i] << endl;
    cerr << "M = " << M << endl;
    cerr << "i - (P - 1) = " << i - (P - 1) << endl;
    cerr << "sum[" << i - 1 << "] = " << sum[i - 1] << endl;
    cerr << "K * M = " << K * M << endl;
#endif
    return (A[i] + M) * (i - (P - 1)) >= sum[i - 1] + K * M;
  }
};

int main()
{
  ll N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> A[i];
  }
  sort(A.rbegin(), A.rend());
  Solve solve(N, M, V, P, A);
  cout << solve.answer() << endl;
}

