vll divisor(ll n) {
	// returns common divisors in O(sqrt(min(n,m)))
	vll res;
	for (ll i = 1; i*i <= n; i++) {
		if (n%i == 0) {
			res.push_back(i);
			res.push_back(n / i);
		}
		if (i * i == n)res.push_back(i);
	}
	sort(res.begin(), res.end());
	return res;
}

vll divisor(ll n, ll m) {
	// returns common divisors in O(sqrt(min(n,m)))
	if (n > m) swap(n, m);
	vll res;
	for (ll i = 1; i*i <= n; i++) {
		if (n%i == 0) {
			if (m%i == 0) res.push_back(i);
			if (m % (n / i) == 0) res.push_back(n / i);
		}
		if (i * i == n && m % i == 0) res.push_back(i);
	}
	sort(res.begin(), res.end());
	return res;
}

vpll prime_factorize(ll n) {
	// returns prime factorization of n in O(sprt(n))
	vector<pll> res;
	for (ll p = 2; p*p <= n; ++p) {
		if (n%p != 0)continue;
		ll num = 0;
		while (n%p == 0) { ++num; n /= p; }
		res.push_back({ p,num });
	}
	if (n != 1) res.push_back(make_pair(n, 1));
	return res;
}








ll kmp_search(const string& text, const string& word) {
	// @return: the iterator where word was found in text
	if (word.empty()) return 0;

	vector<int> pi(word.size(), 0);
	for (int i = 1, k = 0; i < (int)word.size(); ++i) {
		while (k && word[k] != word[i]) k = pi[size_t(k) - 1];
		if (word[k] == word[i]) ++k;
		pi[i] = k;
	}

	for (int i = 0, k = 0; i < (int)text.size(); ++i) {
		while (k && word[k] != text[i]) k = pi[size_t(k) - 1];
		if (word[k] == text[i]) ++k;
		if (k == (int)word.size()) return size_t(i) - k + 1;
	}
	return text.size();
}

template<ll MOD = MOD, ll B = 9973>
struct RollingHash {
	vector<modint<MOD>> hash, p;
	RollingHash() {}
	RollingHash(const string& s) :hash(s.size()+1), p(s.size()+1,1){
		rep (i ,0, s.size()) {
			hash[i + 1] = (hash[i] * B + s[i]);
			p[i + 1] = p[i] * B;
		}
	}
	//hash of S[l, r)
	modint<MOD> operator()(ll l, ll r) {
		return hash[r] - hash[l] * p[r - l];
	}
};
