	reverse(a + 1, a + n + 1);
	int l = 1, r = n, ans = 0; 
	while(l <= r){
		int mid = (l + r) / 2;
		if(check(mid)){
			l = mid + 1;
			ans = mid;  
		}
		else {
			r = mid - 1;
		}
	}
	cout <<	ans;
}

