// f2 a[b]~a[c] を m * t 使って k 以下にできるか
bool f2(ll b, ll c, ll t, ll k) {
    ll s = (ll)t * m;
    for (ll i = b; i <= c; i++) {
        if (k - a[i] < 0) return false;
        s -= min(m, k - a[i]);
    }
    return s <= 0;
}

// a[k] がいけるか
// k = 5, v = 2, p = 2, m = 1, n = 6
bool f1(ll k) {
    if (p >= k) {
        return true;
    }
    else if (v - (n - k + p - 1) < 0 && a[p] <= a[k] + m) {
        return true;
    }
    else {
        ll t = v - (n - k + p - 1);
        if (f2(p - 1, k - 1, t, a[k] + m)) {
            return true;
        }
    }
    return false;
}

int main() {
    cin >> n >> m >> v >> p;
    a.resize(n);
    for (ll i = 0; i < n; i++) {
        cin >> a[i];
    }
    sort(a.rbegin(), a.rend());
    ll l = 0, r = n;
    while (r - l > 1) {
        ll mid = l + (r - l) / 2;
        if (f1(mid)) {
            l = mid;
        }
        else {
            r = mid;
        }
    }
    for (ll i = l; i < n; i++) {
        if (a[i] != a[l]) {
            l = i - 1;
            break;
        }
        else if (i == n - 1) {
            l = n - 1;
        }
    }
    cout << l + 1 << endl;
    return 0;
}

