            INT remain = M*V - (P-1)*M - M*mid -M;
            INT limit  = As[mid] + M;
            for( INT i = mid+1; i <= N-P; i++ ){
                if( As[i] >= limit || remain <= 0) 
                    break;
                else {
                    remain -= (limit - As[i]);
                }
            }
            if( remain > 0 ){
                mn = mid;
            } else {
                mx = mid;
            }
        } while(mx != mn+1);

        INT i = mx;
        while( As[i] != As[mx] ) {i--;} i++;
        ans = N-i;
    }

    cout << ans << endl;

