void solve() {
    ll N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<ll> A(N);
    REP(i, N) cin >> A[i];
    sort(A.begin(), A.end());

    ll th = A[N-P];
    ll left = distance(A.begin(), lower_bound(A.begin(), A.end(), th));
    ll right = distance(A.begin(), upper_bound(A.begin(), A.end(), th));
    ll value = th * (right - left);
    ll cnt = right - left;
    ll margin = N - right;
    ll ans = N - left;
    for (ll l = left-1; l >= 0; l--) {
        if (A[l] + M < th) break;
        ll tmp = l + 1ll;
        tmp += margin;
        if (tmp < V && (A[l] + M - 1ll) * cnt - value < M * (V - tmp)) continue;
        ans++;
        value += A[l];
        cnt++;
    }
    print(ans);
}

