    }
    if(mid + P - 1 >= V-1){
      ok = mid;
      continue;
    }



    ll rest = V - mid - P;
    ll X = A[mid] + M;
    vector<ll> B;
    for(ll i = mid + 1; i <= N-P; i++){
      B.pb(X-A[i]);
    }
    sort(B.begin(), B.end());//足せる回数


    ll point = rest * M;
    revrep(i, B.size()){
      point -= min(point, min(M, B[i]));
    }
    if(point == 0){
      ok = mid;
    }else{
      ng = mid;
    }
  }
  cout << N - ok << endl;
}

