  vector<long long> sum(n + 1, 0);
  for (int i = 1; i <= n; i++)
    sum[i] = sum[i - 1] + a[i];

  int ans = 0;
  for (int i = 1; i <= n;)
  {
    int j = i;
    while (j <= n && a[j] == a[i])
      j++;

    if (i <= p) ans += j - i;
    else if (a[i] + m >= a[p])
    {
      long long canVote = (n - i + 1LL) * m;
      canVote += (i - p - 1LL) * (a[i] + m) - (sum[i - 1] - sum[p]);
      canVote += (p - 1LL) * m;
      if (canVote >= 1LL * m * v)
        ans += j - i;
    }
    i = j;
  }

  cout << ans << endl;
}

