		}
		if (A[MID] + M < A[P]) {
			R = MID;
			continue;
		}
		long long COUNT = SUM[MID] - SUM[P - 1];
		long long X = max(0LL, V - (N - MID) - (P - 1));
		COUNT += X * M;
		long long Y = max(0LL, MID - (P - 1));
		long long MAX;
		if (X % Y == 0) MAX = COUNT / Y;
		else MAX = COUNT / Y + 1;
		if (A[MID] + M < MAX) R = MID;
		else L = MID;
	}
	cout << R << endl;
}

