    if (rest <= 0) return true;

    over_index -= can_over;
    rest -= can_over * M;
    served += can_over;

    if (rest <= 0) return true;

    ll b_i = upper_bound(as.begin(), as.end(), a) - as.begin();

    for (ll ii = b_i; ii < over_index; ii++) {
      rest -= a + M - as[ii];
      served++;
    }

