  read(n), read(m), read(v), read(p);
  for (RI i = 1; i <= n; ++i) read(a[i]);
  sort(a + 1, a + 1 + n);
  for (RI i = 1; i <= n; ++i) sum[i] = sum[i - 1] + a[i];
  for (RI i = n; i >= 1; --i) {
    if (a[i] + m < a[n - p]) break;
