const ll MAX_N = 10e5;
ll N, M, V, P;
ll A[MAX_N];

void Main() {
  cin >> N >> M >> V >> P;
  rep(i, N) cin >> A[i];

  sort(A, A + N);

  ll lb = -1, ub = N;

  while(ub - lb > 1) {
    ll i = (lb + ub) / 2;
    ll t = A[i] + M;
    if (i < N - 1 - (P - 1) + 1 && t < A[N - 1 - (P - 1) + 1]) {
      lb = i;
      continue;
    }
    if (P - 1 >= V - 1) {
      ub = i;
      continue;
    }
    ll l = M * (V - 1);
    l -= M * (P - 1);
    int b = 0;
    rep(j, N - P - 1) {
      if (j == i) b = 1;
      if (t - A[j + b] < 0) continue;
      l -= min(M, t - A[j + b]);
    }
    if (l <= 0) {
      ub = i;
    } else {
      lb = i;
    }
  }

  cout << N - 1 - lb << endl;
}

