	struct findResultVec {
		unionfind * punifind;
		using Cont = std::vector<std::tuple<T, std::vector<T>, bool > >;
		struct proxy {
			T val;
			bool newnode;
			operator T()const { return val; }
			explicit operator bool()const { return !newnode; }
			friend bool operator==(const proxy & l, const proxy & r) {
				return l.val == r.val;
			}
			friend bool operator!=(const proxy & l, const proxy & r) {
				return l.val != r.val;
			}
		};
		Cont st;
