ll N,M,V,P; 
vector<ll> A;
bool f(ll k) {
    if (k < 0) return false;
    if (k >= N) return true;
    vector<ll> B = A;
    ll p = A[k] + M;
    ll sump = M*V;
    ll v = 0;
    while (v < N && B[v] < p && sump > 0) {
        ll val = min({p - B[v],sump,M});
        B[v] += val;
        sump -= val;
        v++;
    }
    v = N-1;
    while (v >= 0 && sump > 0) {
        ll val = min(sump,M);
        B[v] += val;
        sump -= val;
        v--;
    }

    sort(all(B));
    ll x = upper_bound(all(B),p) - B.begin();
    if (N - x >= P) return false;
    else return true;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N >> M >> V >> P;
    A.resize(N);
    rep(i,N) cin >> A[i];

    sort(all(A));
    ll left = -1;
    ll right = N;
    while (left + 1 < right) {
        ll mid = left + (right - left) / 2LL;
        if (f(mid)) right = mid;
        else left = mid;
    }

    cout << N - right << endl;
}

