  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  rep(i, N) cin >> A[i];

  sort(rall(A));

  int ok = 0;
  int ng = N;

  while (abs(ok - ng) > 1) {
    int mid = (ok + ng) / 2;

    if (mid < P) {
      ok = mid;
      continue;
    }

    vector<ll> a = A;
    ll cnt = V * M;
    REP(i, mid, N) {
      if (cnt <= 0) break;
      cnt -= M;
      a[i] += M;
    }
    rep(i, P - 1) {
      if (cnt <= 0) break;
      cnt -= M;
      a[i] += M;
    }

    REP(i, P - 1, mid) if (a[i] > a[mid]) {
      ng = mid;
      continue;
    }

    REP(i, P - 1, mid) {
      if (cnt <= 0) break;
      cnt -= (a[mid] - a[i]);
    }

    if (cnt > 0)
      ng = mid;
    else
      ok = mid;
  }

  cout << ok + 1 << endl;
}

