	for (ll i = 0; i < n; i++){
		scanf("%lld", &aa[i]);
	}
	sort(aa, aa + n);
	ll l = 0, r = n - 1;
	while (l < r){
		ll mid = l + (r - l) / 2, pos, a[n], s = 0, left = m * (k - 1), uses[n];
		copy(aa, aa + n, a);
		fill(uses, uses + n, m);
		for (ll i = 0; i < n; i++){
			if (i == mid) continue;
			if (a[i] > a[mid]){
				pos = i;
				break;
			}
			a[i] += m;
			left -= m;
			uses[i] -= m;
			if (left == 0) break;
		}
		a[mid] += m;
		uses[mid] -= m;
		if (left > 0){
			for (ll i = pos; i < n; i++){
				if (a[i] >= a[mid]) break;
				if (left <= a[mid] - a[i]){
					uses[i] -= left;
					a[i] += left;
					left = 0;
					break;
				}
				uses[i] -= a[mid] - a[i];
				left -= a[mid] - a[i];
				a[i] = a[mid];
			}
			if (left > 0){
				for (ll i = n - 1; i >= 0; i--){
					if (i == mid) continue;
					if (left <= uses[i]){
						a[i] += left;
						left = 0;
						break;
					}
					a[i] += uses[i];
					left -= uses[i];
				}
			}
		}
		bool ok = false, ye = false;
		map<ll, ll> ma;
		for (ll i = 0; i < n; i++){
			if (ma.find(a[i]) == ma.end()){
				ma[a[i]] = 1;
			}else{
				ma[a[i]]++;
			}
		}
		auto it = --ma.end();
		do{
			s += it -> second;
			if (it -> first == a[mid]) ye = true;
			if (s >= p){
				ok = ye;
				break;
			}
			it--;
		}while (it != ma.begin());
		if (ok){
			r = mid;
		}else{
			l = mid + 1;
		}
	}
	printf("%lld\n", n - l);
}

