int N, M, V, P;
bool check(vector<int> A, int index) {
    if (index < P) {
        return true;
    } else {
        if (V - 1 <= P - 1) {
            if (A[index] + M >= A[P - 1]) {
                return true;
            } else {
                return false;
            }
        } else {
            if ((V - 1) - (P - 1) <= (N - 1) - index) {
                if (A[index] + M >= A[P - 1]) {
                    // cout << "1\n";
                    return true;
                } else {
                    // cout << "2\n";
                    return false;
                }
            } else {
                int left = (V - 1) - (P - 1) - ((N - 1) - index);
                int under = A[index] + M;
                ll sum = 0;
                FOR(j, P - 1, index) { sum += under - A[j]; }
                // printf("left:%d, under:%d, sum:%lld\n", left, under, sum);
                if (sum >= left * M) {
                    // cout << "3\n";
                    return true;
                } else {
                    // cout << "4\n";
                    return false;
                }
            }
        }
    }
}

