void solve() {
    i64 N = RD();
    i64 M = RD();
    i64 V = RD();
    i64 P = RD();
    auto A = RD_VEC(N);

    ALL(sort, A, greater<>{});
    DBG(A);

    // 問題 i が採用されうるか
    auto is_ok = [&](i64 i) -> bool {
        i64 a = A[i];
        if(i < P) return true;
        if(a+M < A[P-1]) return false;

        i64 room = M * ((P-1) + (N-i));
        FOR(j, P-1, i) {
            room += a+M-A[j];
        }

        return room >= M*V;
    };

    // 採用されうる最大のインデックスを二分探索
    i64 lo = 0;
    i64 hi = N;
    while(lo+1 < hi) {
        i64 mid = (lo+hi) / 2;
        if(is_ok(mid))
            lo = mid;
        else
            hi = mid;
    }

    i64 ans = lo + 1;

    PRINTLN(ans);
}

