void solve() {
  int N, M, V, P;
  cin >> N >> M >> V >> P;
  vi32 A(N);
  cin >> A;
  sort(A.rbegin(), A.rend());
  int ok = -1, ng = N;
  while (ng - ok > 1) {
    int md = (ok + ng) / 2;
    auto a = A;
    i64 rest = (i64) M * V;
    a[md] += M, rest -= M;
    if (a[md] < a[P - 1]) {
      ng = md;
      continue;
    }
    rep(i, P - 1) {
      if (i == md) continue;
      if (rest > 0) {
        a[i] += M, rest -= M;
      }
    }
    repi(i, P - 1, N) {
      if (i == md) continue;
      if (rest > 0) {
        i64 add = max(0, a[md] - a[i]);
        add = min(rest, add);
        add = min(add, (i64) M);
        a[i] += add, rest -= add;
      }
    }
    (rest == 0 ? ok : ng) = md;
  }
  cout << ng << endl;
}

