bool chk(int mid){
    int lim=a[mid]+M;
    ll res=1ll*M*(V-(N-mid+1)-(P-1));
    for(int i=mid-1;i>=P;--i){
        if(lim-a[i]<0)return 0;
        res-=lim-a[i];
    }
    if(res>0)return 0;
    else return 1;
}
