ll binarysearch(ll s, ll e)
{
	ll ans = -1; // INVALID ANS IS -1
	while (s <= e) {
		ll mid = s + (e - s) / 2;
		if (check(mid)) {
			ans = mid;
			e = mid - 1;
		}
		else
			s = mid + 1;
	}
	return ans;
}
