int main(){
    int n,v,p;
    long m;
    scanf("%d %ld %d %d", &n, &m, &v, &p);
    vector<long> va(n);
    for(int i = 0; i < n; i++){
        scanf("%ld", &va[i]);
    }
    sort(va.begin(), va.end());  //小さい順
    long iPointSum = m * (long)(v - p + 1);  //分配可能点  大きいp-1問に全振りした残り


    int i = 0;  //勝ちうる問題で最弱の奴
    while(va[i] + m < va[n - p]){  //p番目に大きいやつとm点差以下の最低点を探す
        i++;
    }
    while(true){
        if(va[i] == va[n - p]){  //va[i]がp番目に大きいやつだったらやめる
            break;
        }
        long iPointRequire = 0;  //va[i] + m に揃えるのに必要なポイント
        for(int k = 0; k < n - p + 1; k++){
            iPointRequire += min(va[i] + m - va[k], m);
        }
        if(iPointRequire > iPointSum){
            break;
        }
        i++;
    }
    printf("%d", n-i);
    return 0;
}

