using Int = long long;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    Int N, M, V, P; cin >> N >> M >> V >> P;
    vector<int> A(N); for (auto &a : A) cin >> a;
    sort(rbegin(A), rend(A));
    int ans = 0;
    if (V <= P) {
        ans = P;
        for (int i = P; i < N; i++) if (A[i] + M >= A[P - 1]) ans++;
    } else {
        ans = P;
        int i = P, same = 0;
        while (i < N && A[i] == A[P - 1]) ans++, i++, same++;
        int ok = i - 1, ng = N;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            Int val = A[mid] + M;
            Int add = 0;
            bool fail = false;
            for (int i = P - 1; i < N; i++) {
                if (A[i] > val) { fail = true; break; }
                add += min(M, val - A[i]);
            }
            if (!fail && (V - P + 1) * M <= add) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        ans = ok + 1;
    }
    cout << ans << endl;
    return 0;
}

