bool f(ll idx) {
    if (idx < p) return true;
    if (a[p - 1] > (a[idx] + m)) return false;
    ll cnt = (p - 1) * m + (n - idx - 1) * m + m;
    reps(i, p, idx) {
        cnt += (a[idx] + m) - a[i];
    }
    return cnt >= (m * v);
}

