bool jud(ll num)
{
	if (V <= P + N - num - 1)
	{
		return A[P - 1] <= A[num] + M;
	}
	else
	{
		ll l = num - (P - 1);
		ll k = l - (V - (P + N - num - 1));
		vector<ll> vec;
		ll sum = 0;
		for (ll i = P - 1; i < num; i++)
		{
			vec.push_back(A[i] - A[num]);
			sum += A[i] - A[num];
		}
		return max(vec[0], (sum + k - 1) / k) <= M;
	}
}

void solve()
{
	sort(A, A + N);
	reverse(A, A + N);
	ll lb = P - 1, ub = N;
	while (lb + 1 < ub)
	{
		ll mid = (lb + ub) / 2;
		if (jud(mid))
		{
			lb = mid;
		}
		else
		{
			ub = mid;
		}
	}
	ans = lb + 1;
}

