/*+* 二分探索 *+*/
// judge を満たすような下限を求める
// l:[X] 定義域外部の上限
// r:[X] 定義域外部の下限
// judge:[X -> bool] X を評価する関数
// lower:[bool] falseにすると代わりに上限を求める
// eps:[X] 終了距離

template <typename X>
X BinSearch(X l, X r, function<bool(X)> judge, bool lower = true, X eps = 1) {
    while (r - l > eps) {
        X m = (r + l) / 2;
        if (judge(m) == lower) {
            r = m;
        } else {
            l = m;
        }
    }
    return lower ? r : l;
}

int main() {
    i64 N, M, V, P;
    cin >> N >> M >> V >> P;
    vector<i64> A(N), S(N);
    for(i64 &x : A) cin >> x;
    sort(REV_WHOLE(A));
    for(int i = 0; i < N; i++) {
        S[i] = A[i] + (i ? S[i - 1] : 0);
    }
    int ans = P;
    for(i64 i = P; i < N; i++) {
        i64 v = V * M;
        v -= (P - 1) * M;
        int j = BinSearch<int>(P - 2, N, [&](int k) -> bool {
            return A[k] > A[i] + M;
        }, false);
        v -= (M + A[i]) * (i - j) - (S[i] - (j < 0 ? 0 : S[j]));
        v -= (N - 1 - i) * M;
        if(v <= 0 && A[i] + M >= A[P - 1]) ans++;
    }
    cout << ans << endl;
    return 0;
}

