    ll sum = 0;
    int s = p, e = n-1, mid, best = p;
    while(s <= e)
    {
        mid= (s+e)/2;
        if(valid(mid))
        {
            best = mid + 1;
            s = mid + 1;
        }
        else e = mid - 1;
    }
    printf("%d\n", best);
}

