int chk(int x) {
  if (x <= k) {
    return 1; 
  }
  if (n - x + 1 + k > v) {
    if (a[x] + m >= a[k]) return 1; 
    else return 0; 
  }
  int P = v - (n - x + 1) - (k - 1);  
  long long S = sum[x - 1] - sum[k - 1]; 
  long long T = -S + 1ll * (x - k) * (a[x] + m);
  if (1ll * P * m <= T) {
    return 1; 
  }
  return 0; 
}

int check(int X) {
  int p = lst[X]; 
  for (int i = p; i <= n; i++) {
    if (a[i] != a[X]) break ; 
    if (chk(i)) return 1; 
  }
  return 0; 
}

