int main() {
  ll N, M, V, P;
  cin >> N >> M >> V >> P;
  vector<ll> A(N);
  REP(i, N) { cin >> A[i]; }
  sort(ALL(A));
  ll ng = -1, ok = N - P;

  while (ng + 1 < ok) {
    ll mid = (ok + ng) / 2;
    if (A[N - P] - A[mid] > M) {
      ng = mid;
      continue;
    }
