bool judge(int i) {
	if (a[p - 1] > a[i] + m) return false;
	int _v = v;
	_v -= p - 1 + n - i;
	if (_v <= 0) return true;
	int b = a[i] + m;
	vector<int> cnt;
	for (int j = p - 1; j < i; ++j)
		cnt.push_back(b - a[j]);
	int sz = cnt.size();
	sort(cnt.begin(), cnt.end());
	for (int j = sz - _v + 1; j < sz; ++j)
		cnt[j] = cnt[sz - _v];
	ll sum = accumulate(cnt.begin(), cnt.end(), 0LL);
	return (sum / _v) >= m;
}

