/* subroutines */

bool check(int n, int m, int v, int p, int u) {
  if (as[p] > as[u] + m) return false;
  ll x = (ll)(u - p) * (as[u] + m) - (ass[u] - ass[p]);
  ll y = (ll)(v - (p + (n - u))) * m;
  return x >= y;
}

/* main */

int main() {
  int n, m, v, p;
  scanf("%d%d%d%d", &n, &m, &v, &p);
  p--;

  for (int i = 0; i < n; i++) scanf("%d", as + i);
  sort(as, as + n, greater<int>());
  //for (int i = 0; i < n; i++) printf("%d ", as[i]); putchar('\n');

  for (int i = 0; i < n; i++) ass[i + 1] = ass[i] + as[i];

  int u = p;
  while (u < n && check(n, m, v, p, u)) u++;

  printf("%d\n", u);
  return 0;
}

