bool chk(int x){
        if (x + w >= n) return true;
        int r = v - w - x;
        if (r < 0) return true;
        ll s = 1ll * r * m;
        for (int i = x + 1; i + w <= n; ++i) {
            int y = a[p[x]] + m - a[p[i]];
            if (y > 0)
                s -= a[p[x]] + m - a[p[i]];
            else if (y < 0)
                return false;
        }
        return s <= 0;
    }

