bool f(VI A, ll idx){
  ll vote = M*V;

  // 自分に全力
  ll me = A[idx] + M;
  vote -= M;

  // 上位P-1人に全力
  rep(i, P-1){
    A[i] += M;
    vote -= M;
  }

  debug(vote);

  FOR(i, P, N){
    // 他のやつをギリまで上げる
    if(i==idx) continue;
    // 限度はM
    if(A[i]<me){
      ll v = min(me-A[i], M);
      A[i] += v;
      vote -= v;
    }
    else if(A[i]>me){
      // そいつは抜けない
      debug("wow");
      return false;
    }    
  }
  if(vote>0){
    debug("vote>0");
    return false; // 配りきれなかった
  }

  // P問以内に入れたか
  // 自分より強いやつのcnt
  ll cnt=0;
  rep(i, N){
    if(i==idx)continue;
    if(A[i]>me)cnt++;
  }
  if(cnt>P){
    return false;
  }else{
    return true;
  }
}

