  sort(rng(A));
  reverse(rng(A));
  ll l=0;
  ll r=N+1;
  ll m;
  while(r-l>1){
    m=(r+l)/2;
    ll AA=A[m]+M;
    vector<ll>B=A;
    ll VV=V*M-M;
    int c=0;
    for(int i=0;i<N;i++){
      if(i==m)continue;
      if(AA<B[i]){
        c++;
        if(VV>=0){
          B[i]+=M;
          VV-=M;
        }
        else{
          B[i]+=VV;
          VV=0;
        }
      }
    }
    if(c>P){
      r=m;
      continue;
    }
    ll D=0;
    for(int i=N-1;i>=0;i--){
      if(i==m)continue;
      if(AA>=B[i]){
        if(VV>=M){
          if(B[i]+M<=AA){
            B[i]+=M;
            VV-=M;
          }
          else{
            D++;
            B[i]=AA;
            VV-=AA-B[i];
          }
        }
        else{
          if(B[i]+VV<=AA){
            B[i]+=VV;
            VV=0;
          }
          else{
            D++;
