const int MAX_N=1e6+1;
LL A[MAX_N];
int N,M,V,P;

bool ok(int p) {
  vector<LL> as(A,A+N);
  int v=0;
  REP(i,P-1) if(v<V-1) as[i]+=M,++v;
  int i=N-1;
  for(; i>=0&&v<V-1&&as[i]<=as[p]; --i) if(i!=p) {
    as[i]+=M,++v;
  }
  as[p]+=M,++v;
  LL rem=(V-v)*M;
  if(i==p) --i;
  while(rem>0&&i>P-2) {
    LL x=min(as[p]-as[i],rem);
    rem-=x,as[i]+=x;
    --i;
  }
  //dump(p,rem,i,as[P-1],as[p]);
  //dumpc(as);
  if(rem>0) return false;
  else return as[p]>=as[P-1];
}
void solve() {
  sort(A,A+N),reverse(A,A+N);
  //dumpC(A,A+N);
  int good=P-1,bad=N;
  while(abs(good-bad)>1) {
    int mid=(good+bad)/2;
    bool res=ok(mid);
    //dump(mid,res);
    (res?good:bad)=mid;
  }
  cout<<good+1<<endl;
}

