    vector<int64_t> A(N);
    for (int64_t i = 0; i < N; i++) {
        cin >> A[i];
    }

    sort(A.begin(), A.end(), greater<int64_t>());

    vector<int64_t> sum(N + 1, 0);
    for (int64_t i = 0; i < N; i++) {
        sum[i + 1] = sum[i] + A[i];
    }

    if (V == N - 1) {
        int64_t ans = 0;
        for (int64_t i = 0; i < N; i++) {
            if (i < P) {
                ans++;
                continue;
            }

            int64_t v = sum[i] - sum[P - 1] - (i - (P - 1)) * A[i];
            if (v <= M) {
                ans++;
            }
        }

        assert(false);

        cout << ans << endl;
        return 0;
    }

    int64_t ans = 0;
    for (int64_t i = 0; i < N; i++) {
        //i番目のものが選ばれうるか

        //そもそも上位P個は大丈夫
        if (i < P) {
            ans++;
            continue;
        }

        //最適な割り振りは「上位P - 1個まで + 自分より下位」に選ぶ
        //余ったやつが問題
        int64_t rem_vote = V - (P - 1) - (N - i);

        if (rem_vote <= 0) {
            //届くかどうか
            if (A[i] + M >= A[P - 1]) {
                ans++;
