vector<pair<ll,ll>> rle (vector<ll> x) {
  vector<pair<ll,ll>> res;
  ll n = (ll)x.size();
  for (ll i = 0; i < n;) {
    ll j = i;
    ll cnt = 0;
    while (j < n && x[j] == x[i]) {
      ++j;
      ++cnt;
    }
    res.emplace_back(x[i], cnt);
    i = j;
  }
  return res;
}

