int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout<<fixed<<setprecision(10);

	int N=in(),M=in(),V=in(),P=in();
	auto A=vecin<ll>(N);
	sort(ALL(A),greater<ll>());
	vector<ll> B,C;
	copy(A.begin(),A.begin()+P,back_inserter(B));
	copy(A.begin()+P,A.end(),back_inserter(C));

	if(V+P<=N){
		int Q=B.back();
		int sum=0;
		for(auto& x:C){
			if(x+M>=Q) sum++;
		}
		out(B.size()+sum);
	}
	else{
		int L=N-V;
		int R=B.size()-L;
		priority_queue<ll,vector<ll>,greater<ll>> BQ;
		for(int i=R,ei=B.size();i<ei;i++){
			BQ.push(B[i]);
		}
		priority_queue<ll> CQ;
		for(auto& x:C){
			x += M;
			CQ.push(x);
		}
		while(!CQ.empty()){
			auto VB=BQ.top();
			auto VC=CQ.top();
			if(VC>VB){
				ll NVC = (VB+VC)/2LL;
				CQ.pop();CQ.push(NVC);
				BQ.pop();BQ.push(VB+VC-NVC);
			}
			else break;
		}
		vector<ll> D;
		while(!BQ.empty()){
			D.push_back(BQ.top());
			BQ.pop();
		}
		while(!CQ.empty()){
			D.push_back(CQ.top());
			CQ.pop();
		}
		sort(ALL(D),greater<ll>());
		ll ans = R;
		ll F=D[R-1];
		for(int i=R-1,ei=D.size();i<ei;i++){
			if(D[i]==F) ans++;
		}
		out(L+ans);
	}

	return 0;
}

