    long count = 0;
    for (long i = 0; i < N;i++) {
        if(A[i] > border)
            count++;
        else if(A[i] == border){
            count++;
            border_count++;
        }
        else
            break;
    }

    long remind = (V - (N - count)) * M;
    border += remind / count != 0
        ? remind / count : (remind % count >= count - border_count)
        ? 1 : 0;
    for (long i = count; i < N;i++){
        if(A[i] + M >=border)
            count++;
        else
            break;
    }

    cout << count << endl;

    return 0;
}

