void solve() {
    int n, m, v, p;
    cin >> n >> m >> v >> p;
    int pn = n, pm = m, pv = v, pp = p;
    vec<int> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    sort(all(a));
    vec<int> ps(n + 1);
    for (int i = 1; i <= n; ++i) {
        ps[i] = ps[i - 1] + a[i];
    }

    // for (int i = 1; i <= n; ++i) {
    //     cout << a[i] << " ";
    // }
    // cout << endl;

    int ans = 0;
    for (int i = 1; i <= n; ++i) {
        int id = upper_bound(all(a), a[i] + m) - a.beg();
        int cnt1 = id - 1, cnt2 = n + 1 - id;
        if (cnt2 > p) {
            n = pn, m = pm, v = pv, p = pp;
            continue;
        }
        v--, cnt1--;
        v -= (cnt2 + i - 1);
        if (v < 0) {
            ans++;
            n = pn, m = pm, v = pv, p = pp;
            continue;
        }
        // отрезок от (i + 1) до (id - 1) 
        assert(i + 1 <= id - 1);
        int sum = ps[id - 1] - ps[i];
        int dif = (a[i] + m) * (id - 1 - (i + 1)) - sum;
        int amount = v * m;
        if (amount <= dif) {
            ans++;
            n = pn, m = pm, v = pv, p = pp;
            continue;
        }     
        amount -= dif;
        if (amount < v) {
            cnt2 += amount;
            if (cnt2 < p) {
                ans++;
            }
        }
        else {
            cnt2 += v;
            if (cnt2 < p) {
                ans++;
            }
        }
        n = pn, m = pm, v = pv, p = pp;
    }   

    cout << ans << endl;
}

