    int i;
    for (i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }
    sort(a.begin(), a.end());

    int l = -1, r = n - P;
    while (r - l > 1) {
        int m = (l + r) / 2;
        ll cnt = (ll)M * (P+m);
        int bad = 0;
        for (i = m + 1; i <= n - P; i++) {
