	if(X>=impossible_line) return false;
	if(X<P) return true;
	long safevote = 0;
	safevote+=(N-X+P-1)*M;
	for(int i=P-1;i<X;i++){
		safevote+=A[X]+M-A[i];
	}
	if(safevote<=M*V) return false;
	return true;
