        has[i] = (m - need + x[i].X);
        needv -= x[i].Y * (need - x[i].X);
        if (needv <= 0) return true;
    }
    for (int i = pos; i >= idx + 1; --i) {
        if (rank + x[i].X <= p) {
            needv -= has[i] * x[i].Y;
            rank += x[i].X;
        } else {
            needv -= (p - rank) * has[i];
