int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll N,M,V,P;
  cin>>N>>M>>V>>P;
  vector<ll>A(N);
  for(int i=0;i<N;i++)cin>>A[i];
  sort(rng(A));
  reverse(rng(A));
  ll l=0;
  ll r=N;
  ll m;
  while(r-l>1){
    m=(r+l)/2;
    ll AA=A[m]+M;
    vector<ll>B=A;
    ll VV=V*M-M;
    ll c=0;
    for(int i=0;i<N;i++){
      if(i==m)continue;
      if(AA<B[i]){
        c++;
        if(VV>=0){
          B[i]+=M;
          VV-=M;
        }
        else{
          B[i]+=VV;
          VV=0;
        }
      }
    }
    if(c>P){
      r=m;
      continue;
    }
    ll D=0;
    for(int i=N-1;i>=0;i--){
      if(i==m)continue;
      if(AA>=B[i]){
        if(VV>=M){
          if(B[i]+M<=AA){
            B[i]+=M;
            VV-=M;
          }
          else{
            D++;
            B[i]=AA;
            VV-=AA-B[i];
          }
        }
        else{
          if(B[i]+VV<=AA){
            B[i]+=VV;
            VV=0;
          }
          else{
            D++;
            B[i]=AA;
            VV-=AA-B[i];
          }
        }
      }
    }
    ll cc=0;
    ll VVV=0;
    for(int i=0;i<N;i++){
      if(i==m)continue;
      if(A[i]+M>AA&&B[i]==AA)cc++;
      VVV=B[i]-A[i];
    }
    B[m]=AA;
    if(min({VVV,cc})+c>=P)r=m;
    else l=m;
  }
  cout<<l+1<<endl;
  return 0;
}

