	vector<int> B(A);
	int sum = M * V;
	int hoge = N, con = 0;

	if(m <= 0) return false;
	if(m > N) return true;

	B[m-1] += M;
	sum -= M;

	for(int i = 0, j = 0; i < m-1 && j < V-1; i++, j++){
		B[i] += M;
		sum -= M;
	}
