class Solve {
public:
    Int N, M, V, P;
    vector<Int> A;

    // A[x]が採用される可能性はあるか
    bool check(Int x) {
        Int X = A[x];

        if (X + M < A[N - P]) {
            return false;
        }

        Int w = V - P - x;
        if (w <= 0) return true;

        Int sum = 0;
        Int L = A[x] + M;
        for (int i = x + 1; i <= N - P; ++i) {
            sum += min(L - A[i], M);
        }

        return sum / w >= M;
    }

    void solve() {
        cin >> N >> M >> V >> P;
        A.resize(N);
        for (int i = 0; i < N; ++i) cin >> A[i];
        sort(all(A));

        Int ng = -1, ok = N - P;
        while (ok - ng > 1) {
            Int mid = (ok + ng) / 2;
            if (check(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }
        Int ans = N - ok;
        cout << ans << endl;
    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

