			if (n-pos+1<p) ans++;
		}
		else
		{
			int pos=upper_bound(a+1,a+2+n,a[i]+m)-a;
			if (n-pos+1>=p) continue;
			if (v-i-p+1<=0)
			{
				ans++;
				continue;
			}
			int cnt=v-i-p+1;
			int l=i+1,r=min(n-p+1,pos-1);
			if (r-l+1>=cnt && cnt*m<=(a[i]+m)*(r-l+1)-(sum[r]-sum[l-1])) ans++;
		}
	}
	printf("%lld\n",ans);
}

