    while (right - left > 1) {
        li idx = (left + right) / 2;
        li init_a = as[idx];
        li best_a = init_a + m;

        vector<li> bins;
        li uppers = 0;
        for (int i = 0; i < n; ++i) {
            if (i == idx) {
                continue;
            }
            li sz = best_a - as[i];
            if (sz < 0) {
                uppers += 1;
            } else {
                bins.push_back(sz);
            }
        }

        while (uppers < p - 1 && !bins.empty()) {
            uppers++;
            bins.pop_back();
        }

        bool ok;
        if (uppers >= p) {
            ok = false;
        } else {
            li votes = max(v - 1 - uppers, 0LL);
            li judges = m;
            li costs = votes * judges;
//            cout << idx << " " << bins.size() << " " << votes << " " << judges << endl;

            for (int i = 0; i < bins.size(); ++i) {
                costs -= min(bins[i], judges);
            }

//            cout << costs << endl;
            ok = costs <= 0;
        }

        if (ok) {
            right = idx;
        } else {
            left = idx;
        }
    }

    cout << n - right << endl;
    return 0;
