	vote -= index;
	lli sum = 0;
	for (int i = index + 1; i < N; i++){
		if (table[index] + M - table[i] <= 0){
			break;
		}
		sum += (lli)min(M, table[index] + M - table[i]);
	}

	return sum >= (lli)vote*(lli)M;
}

