    for (int i = 0; i < n; i++) {
        if (a[i] >= b) {
            ans++;
            continue;
        }

        llong tmp = m * v;
        tmp -= m; //vote to problem i
        tmp -= (p - 1) * m;
        tmp -= i * m;

        llong s = a[i] + m;
        if (tmp <= 0 && s >= p) {
            ans++;
            continue;
        }

        if (tmp <= m &&
            s >= p + tmp) {
            ans++;
            continue;
        }

        llong valid = n - p - 1;
        llong invalid = i - 1;
        while (valid - invalid > 1) {
            llong mid = (valid + invalid) / 2;

            if (s > a[mid]) {
                valid = mid;
            }
            else {
                invalid = mid;
            }
        }

        if (tmp - s * (valid - i) + sum[valid + 1] - sum[i + 1] <= 0 &&
            s >= p) {
            ans++;
        }
        //cout << a[i] << ' ' << tmp << endl;
    }

    cout << ans << endl;

    return 0;
}

