	FOR(i, P-1, index) {
		req.push_back(A[i] - target);
	}
	sort(ALL(req), greater<int>());

	int su = 0;
	int res = 0;
	int amari = 0;
	queue<pair<int, int> > que;
	REP(i, req.size()) {
		if (not que.empty() and que.front().first == i) {
			su -= que.front().second;
			que.pop();
		}
		if (req[i] - su - amari > 0) {
			res += req[i] - su - amari;
			que.emplace(i + VV, req[i] - su - amari);
			amari = 0;
			su += req[i] - su;
		}
		else {
			amari += su - req[i];
		}
	}
	return res <= M;
}

