		int ff = i;
		while (a[j] <= a[i] + m) {
			j++;
		}
		if (n - j >= p)
			continue;
		if (fb + ff >= v - 1)
			ans++;
		else {
			ll req = v-1-(ff + fb);
			req *= m;
			ll avail = j - i - 1;
			avail *= a[i] + m;
			avail = avail - asum(i + 1, j - 1);
			if (avail >= req)
				ans++;
		}
	}
	cout << ans << "\n";
	//system("pause");
	return 0;
}

