int jud(int x){
	ll cnt=a[x]+m;
	if(cnt<a[n-p+1]) return 0;
	if(v<=p-1+x) return 1;
	ll tmp=v-(p-1+x);
	if(tmp>=n-p+1-x) return 0;
	while(!q.empty()) q.pop();
	ll cap=0;
	for(int i=x+1;i<=n-p+1;i++){
		if(cnt-a[i]) q.push(cnt-a[i]),cap++;
