bool test(vll& A, int i, int N, ll M, ll V, int P) {
    vll B(A);

    B[i] += M;
    ll total = M*(V-1);

    // cout << "start: " << endl;
    // for (int j=0;j<N;j++) cout << j << " " << B[j] << endl;

    for (int j=0;j<N;j++) {
        if (B[j] < B[i]) {
            ll diff = min(B[i] - B[j], min(M, total));
            B[j] += diff;
            total -= diff;

        } else if (B[j] > B[i]) {
            B[j] += min(M, total);
            total -= min(M, total);
        }
    }

    // cout << "mid: " << endl;
    // for (int j=0;j<N;j++) cout << j << " " << B[j] << endl;

    for (int j=N-1;j>0;j--) {
        ll diff = min(M - (B[j] - A[j]), total);
        B[j] += diff;
        total -= diff;
    }

    int num_greater = 0;
    for (int j=0;j<N;j++) {
        if (B[j] > B[i]) num_greater++;
    }

    if (num_greater < P) return true;
    else return false;
}

