        if (test(A, i, N, M, V, P)) {
            // cout << mid << "(" << A[i] << ") is possible" << endl;
            low = mid;
        } else {
            // cout << mid << "(" << A[i] << ") is not possible" << endl;
            high = mid;
        }
    }

    cout << low + 1 << endl;
}

