bool check(int x) {
	vector <int> small;
	for (int i = 0; i < N && small.size() < N - P; i++)
		if (i != x)
			small.push_back(a[i]);

	ll mx = 0, sum = 0;
	for (int i = N - P - 1; i >= 0; i--) {
		sum += small[i];
		mx = max(mx, (sum + (ll)M * max(V - P - i, 0) - 1) / (N - P - i) + 1);
	}

	return mx <= a[x] + M;
}

