    if(i == P-1){
      num = A[i];
    }
    sum[i+1] = A[i] + sum[i];
  }
  //cout << num << endl;
  ll ans = P;
  if(V <= P){
    for(ll i = P;i < N;i++){
      if(A[i] + M >= num){
        ans++;
      }else{
        break;
      }
    }
  }else{
    for(ll i = P;i < N;i++){
      if((N-i-1) >= V - P){
        ans++;
      }else{
        if(M+A[i] >= num){
          ll s = A[P] * (i-P) - (sum[i] - sum[P]);
          if(s >= M * (V-(P+N-i-1))){
            ans++;
          }else{
            if((sum[i]-sum[P] + M * (V-(P+N-i-1)) + (i-P))/(i-P) <= M + A[i]){
              ans++;
            }else{
              break;
            }
          }
        }else{
          break;
        }
      }
    }
  }
  cout << ans << endl;
}

