// midがpより後である =>
// midを+1, 0~mid-1を+1する。残り v-(mid+1)
// midがp番目になるには2つ条件が必要
// - v-(mid+1)<=p-1
// - a[mid]+m>=a[n-p (p番目)]
bool isOk(ll mid){
  if(n-mid<=p) return 1;

  ll rem=v-(mid+1)-(p-1); // midを選ぶ上で影響のない分を投票した残り

  if(rem<=0){
    if(a[mid]+m>=a[n-p]) return 1;
  }else{
    ll cnt=(n-(p-1))-mid-1;
    ll x=(a[mid]+m)*cnt-(sum[n-(p-1)]-sum[mid+1]);
    // cout<<mid<<' '<<(sum[n-(p-1)]-sum[mid+1])<<' '<<x<<' '<<rem<<' '<<cnt<<endl;
    if(x>=rem*m) return 1;
  }
  return 0;
}


