    if(ind - a.at(i) > m) continue;
    if(a.at(i) == a.at(i + 1)){
      if(i == n - 2) out += count;
      count++;
      continue;
    }else{
      if(ind - a.at(i) <= m){
        if(i + p >= v){
          out += count;
          count = 1;
        }else{
          long long sa = v - (i + p);
          long long wa = sa * m;
          for(int j = i + 1; j < n - p + 1; j++){
            wa += a.at(j);
          }
          if(wa % (n - p - i) == 0){
            ind = wa / (n - p - i);
          }else{
            ind = wa / (n - p - i) + 1;
          }
          if(ind - a.at(i) <= m){
            out += count;
            count = 1;
          }
          count = 1;
        }
      }
    }
  }
  cout << out + 1;
}

