int main() {
  ll N, M, V, P; cin >>N >>M >>V >>P;
  vector<ll> A(N);
  for (ll i=0; i<N; i++){
    cin >>A.at(i);
  }
  sort(A.begin(), A.end());
  reverse(A.begin(), A.end());
  // 降順ソート

  ll ans = P;
  // とりあえず最初のP個は大丈夫でしょ
  ll comp = A.at(P-1); // コレと比べる

  bool ok = true;
  ll sumemp = 0;
  ll infe = A.at(P-1); // okなら条件を満たすやつの現時点での下限

  // 最後のV-1個を除くやつらは単純に＋Mしてcomp以上になればOK
  for (ll i=P; i<N-(V-1); i++){
    if (A.at(i) + M >= comp){ ans++; infe = A.at(i);
    }else{                    ok = false; break;
    }
    sumemp += comp - A.at(i);
  }
  ll compNum = 1; //compと一致するやつの数
  for (ll i=0; i<N-(V-1); i++){
    if (i == P-1) continue;
    if (A.at(i) == comp) compNum++;
  }

  if (ok){
    /* で、最後のV-1個。こいつらに関してはジャッジ一人当たりindi = V-(N-i)個の、
       自分以上のスコアの問題にもスコアが入る。indiがP-1個以下ならcompを増やさないようにできる。
       P以上なら、全員まず自分と最初P-1個に入れる。残りはP-1から自分-1の空いている分である
       sumempまでまず入れて、それでもスコアが余るならcompは(余り)/(現時点でのcompの数)分だけ増える。
    */
    for (ll i=N-V+1; i<N; i++){
      if (i<P) continue;
      // 既にチェックされてる値なら大丈夫
      if (A.at(i) == infe){
        ans++; sumemp += comp - A.at(i); compNum++;
        continue;
      }

      ll indi = V-(N-i); // ジャッジ1人あたり
      ll sum = M * (indi - (P-1)); // 残り
      ll comp2 = comp + (sum - sumemp) / compNum;

      // compの値が増えないなら普通にチェック出来る
      if (indi > P-1){
        // compの値が増えないなら(ry)
        if (sum > sumemp){
          // 美味いことやる
          if (A.at(i) + M < comp2){
            break;
          }
        }
      }

      if (A.at(i) + M >= comp){
        ans++; sumemp += comp - A.at(i); infe - A.at(i);
        continue;
      }else{
        break;
      }
    }

    cout <<ans <<endl;
  }

}

