		ll r = remv * m / len;
		ll q = remv * m % len;

		if(q == 0){
			if(a[p-1] + r <= a[i] + m) ans++; 
		}else{
			if(max(a[p-1] + r, a[i-q] + r + 1) <= a[i] + m) ans++;
		}

	}

