#define MAX_N  100000

int tmp[MAX_N];

void mergeSort(int x[], int left, int right) {
	int mid, i, j, k;
	if (left >= right) {
		return;
	}
	mid = (left + right) / 2;
	mergeSort(x, left, mid);
	mergeSort(x, mid + 1, right);
	for (i = left;i <= mid; i++) {
		tmp[i] = x[i];
	}
	for (i = mid+1,j=right;i <= right; i++,j--) {
		tmp[i] = x[j];
	}

	i = left;
	j = right;
	for (k = left;k <= right;k++) {
		if (tmp[i] <= tmp[j]) {
			x[k] = tmp[i++];
		}
		else {
			x[k] = tmp[j--];
		}
	}
}
