分割して逃がすことが可能！

逃がすとは？
・M*makiを埋める
・1箇所にMを超えて突っ込んではいけない

*/

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int main(int argc, char **argv)
{
	int N, M, V, P;
	scanf("%d %d %d %d", &N, &M, &V, &P);

	static int A[100001];
	int *map = calloc(sizeof(int), 1000000001);
	int lowest = 1000000000;
	int highest = 0;
	for (int i = 0; i < N; i++) {
		scanf("%d", &A[i]);
		map[A[i]]++;
		if (A[i] < lowest)
			lowest = A[i];
		if (highest < A[i])
			highest = A[i];
	}

	static int S[100001];
	static int T[100001];
	static int L[200001];
	int *tmap = calloc(sizeof(int), 1000000001);

	int ans = 0;
	for (int i = 0; i < N; i++) {
		int score = A[i];
		int n = 0;
		int require = highest;
		for (int h = highest; h >= lowest; h--) {
			if (h > score) {
				n += map[h];
			} else if (h == score) {
				S[i] = 1;
				fprintf(stderr, "%d enough score %d\n", i, score);
				goto nexti;
			}
			require = h;
			if (n >= P)
				break;
		}
		fprintf(stderr, "require %d\n", require);
		if ((require - score) > M)
			goto nexti;
		memcpy(T, A, (sizeof(int) * N));
		memcpy(tmap, map, (sizeof(int) * highest));
		tmap[T[i]]--;
		T[i] += M;
		fprintf(stderr, "%d score %d -> %d\n", i, score, score + M);
		tmap[T[i]]++;
		for (int m = 0; m < M; m++) {
			memset(L, 0, sizeof(int) * (highest + M));
			L[i] = 1;
			for (int v = 1; v < V; v++) {
				int tlow = highest;
				int tidx = N;
				for (int x = 0; x < N; x++) {
					if (L[x])
						continue;
					if (T[x] < tlow) {
						tlow = T[x];
						tidx = x;
					}
				}
				tmap[T[tidx]]--;
				T[tidx]++; // vote
				fprintf(stderr, " %d score %d -> %d\n", tidx, T[tidx], T[tidx] + 1);
				tmap[T[tidx]]++;
				L[tidx]++;
			}
		}
		score += M;
		n = 0;
		for (int h = highest+M; h >= lowest; h--) {
			if (h > score) {
				n += tmap[h];
			} else if (h == score) {
				S[i] = 1;
				goto nexti;
			}
			if (n >= P)
				break;
		}
nexti:
		if (S[i]) {
			fprintf(stderr, "%d ok\n", i);
			++ans;
		}
	}

	printf("%d\n", ans);

	return 0;
}

