int N, M, V, P;
int A[114514];

int main(void) {
	int i;
	int ume;
	int ok, ng;
	if (scanf("%d%d%d%d", &N, &M, &V, &P) != 4) return 1;
	for (i = 0; i < N; i++) {
		if (scanf("%d", &A[i]) != 1) return 1;
	}
	qsort(A, N, sizeof(*A), cmp);
	ume = V - (P - 1);
	if (ume < 1) ume = 1;
	ok = P - 1;
	ng = N;
	while (ok + 1 < ng) {
		int mid = ok + (ng - ok) / 2;
		if (mid < P) ok = mid;
		else if (N <= mid) ng = mid;
		else if (A[P - 1] > A[mid] + M) ng = mid;
		else {
			int64_t left = (int64_t)M * ume;
			int target = A[mid] + M;
			for (i = P - 1; i < N; i++) {
				int delta = target - A[i];
				if (delta > M) delta = M;
				if (delta > left) delta = left;
				left -= delta;
			}
			if (left > 0) ng = mid; else ok = mid;
		}
	}
	printf("%d\n", ok + 1);
	return 0;
}

