    uint64_t vSum;
} UF_Node;

static UF_Node uf_Node[101];

static size_t uf_GetRoot(const size_t idx) {
    if (uf_Node[idx].parent == UF_ROOT) {
        return idx;
    }

    const size_t root = uf_GetRoot(uf_Node[idx].parent);

    uf_Node[idx].parent = root;

    return root;
}

static void uf_Merge(const size_t a, const size_t b) {
    const size_t aRoot = uf_GetRoot(a);
    const size_t bRoot = uf_GetRoot(b);

    if (aRoot != bRoot) {
        uf_Node[aRoot].parent = bRoot;

        uf_Node[bRoot].wSum += uf_Node[aRoot].wSum;
        uf_Node[bRoot].vSum += uf_Node[aRoot].vSum;
    }
}

static uint64_t A[100000];
static uint64_t ASum[100000];

#define NOT_FOUND (UINT64_MAX)

static uint64_t BSearch_V(const uint64_t base, const uint64_t size, const uint64_t v) {
    const uint64_t tgt = base + size / 2;

    if (v <= A[tgt]) {
        const uint64_t rightSize = base + size - tgt - 1;
        if (rightSize == 0) {
            return NOT_FOUND;
        }

        return BSearch_V(tgt + 1, rightSize, v);
    }
    else {
        const uint64_t leftSize = tgt - base;
        if (leftSize == 0) {
            return tgt;
        }

        const uint64_t leftResult = BSearch_V(base, leftSize, v);

        if (leftResult == NOT_FOUND) {
            return tgt;
        }
        else {
            return leftResult;
        }
    }
}

