fun main(args : Array<String>) {
    val (n, m, v, p) = readLine()!!.split(" ").map { it.toInt() }
    val aa = readLine()!!.split(" ").map { it.toInt() }.sortedDescending()

    var cnt = 0
    var min = -1
    var minSum = 0L
    var lastIndex = 0
    var sameCnt = 1
    repeat(n) {
        if (it < p) {
            cnt++
            if (aa[it] != min) {
                min = aa[it]
                minSum = min.toLong()
                lastIndex = it
                sameCnt = 1
            } else {
                minSum += min
                sameCnt++
            }
            return@repeat
        }

        if (min == aa[it]) {
            cnt++
            sameCnt++
            minSum += min
            return@repeat
        }

        val max = aa[it] + m
        val countUpSafely = (n - it) + lastIndex
        if (min <= max && v <= countUpSafely) {
            cnt++
            minSum += aa[it]
            return@repeat
        }

        val vNeeded = v - countUpSafely
        val voteSum = minSum + (m * vNeeded)
        val itemCnt = it - lastIndex
        if ((voteSum.toFloat() / itemCnt.toFloat()) <= max) cnt++
        minSum += aa[it]
    }

    println(cnt)
}

fun main(args: Array<String>) {
    val (N, M, V, P) = readLine()!!.split(" ").map{it.toInt()}
    val A = readLine()!!.split(" ").map{it.toLong()}.sorted()

    fun check(p: Int): Boolean {
        val v = A[p] + M

        var rest = M * (V - 1L)
        var cnt = 0

        val b = ArrayList<Long>()

        for (i in A.indices) {
            if (i == p) continue

            if (A[i] > v) {
                rest -= M
                cnt++
            } else if (v - A[i] < M.toLong()) {
                rest -= v - A[i]
                b.add(M - (v - A[i]))
            } else {
                rest -= M.toLong()
            }
        }

        b.sortDescending()

        for (t in b) {
            if (rest <= 0) break
            cnt++
            rest -= t
        }

        return cnt <= P - 1
    }

    var l = 0
    var u = N - P

    while (u - l > 1) {
        val c = (l + u) / 2

        if (check(c)) {
            u = c
        } else {
            l = c
        }
    }

    println(N - u)
}

