    val n = sc.nextInt()
    val m = sc.nextLong()
    val v = sc.nextInt()
    val p = sc.nextInt()
    val a = Array(n) { sc.nextInt() }
    a.sortDescending()
    val count = a.drop(p - 1).count { it == a[p - 1] }
    var l = 0
    var r = n
    while (r - l > 1) {
        val mid = (l + r) / 2
        var safe = m * (p - 1 + n - mid)
        for (i in p - 1 until mid) {
            safe += a[mid] + m - a[i]
        }
        if (mid < p || safe >= m * v) {
            l = mid
        } else {
            r = mid
        }
    }
    println(r)
}

