fun main(args: Array<String>) {
    val (N, M, V, P) = readInputLine().split(" ").map { it.toLong() }
    val AArr = readInputLine().split(" ").map { it.toLong() }

    val scoreCnt = mutableMapOf<Long, Long>()

    for (A in AArr) {
        val cnt = scoreCnt.get(A) ?: 0L
        scoreCnt[A] = cnt + 1L
    }

    val scores = scoreCnt.keys.toLongArray()
    scores.sortDescending()

    var border = 0L
    var cnt = 0L

    for (s in scores) {
        if (cnt > P) {
            break
        }
        border = s
        cnt += scoreCnt[s]!!
    }

    cnt = 0L
    var borderHigherCnt = 0L
    val borderCnt = scoreCnt[border]!!
    var borderDiff = 0L
    var borderLowerCnt = 0L
    var ans = 0L

    for (s in scores) {
        if (border > s + M) {
            break
        }

        if (s < border && (V - borderHigherCnt - (N - cnt)) * M > (M - border + s) * borderCnt + borderDiff) {
            break
        }

        ans += scoreCnt[s]!!
        cnt += scoreCnt[s]!!

        if (s > border) {
            borderHigherCnt += scoreCnt[s]!!
        }
        if (s < border) {
            borderLowerCnt += scoreCnt[s]!!
            borderDiff += (border - s) * scoreCnt[s]!!
        }
    }

    println(ans)
}

