fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val m = sc.nextLong()
    val v = sc.nextInt()
    val p = sc.nextInt()
    val a = Array(n) { sc.nextInt() }
    a.sortDescending()
    var l = 0
    var r = n
    while (r - l > 1) {
        val mid = (l + r) / 2
        if (mid < p) {
            l = mid
            continue
        }
        val rem = m * v - m * (p - 1 + n - mid)
        val x = rem / (mid - p + 1) + if (a[p - 1] != a[mid - 1]) 0 else 1
        if (a[p - 1] + x <= a[mid] + m) {
            l = mid
        } else {
            r = mid
        }
    }
    println(r)
}

