            if (cnt >= P) break
            else {
                before[i] = true
                cnt++
            }
        }

        for (i in 0 until N) {
            if (before[i]) {
                sum -= M
            } else {
                if (AmMax < A[i]) return false
                sum -= min(AmMax - A[i], M)
            }
        }

        return sum <= 0L    }

    var l = L; var r = R
    while (l < r-1) {
        val m = (l + r) / 2
        if (isCondition(A, m)) {
            l = m
        } else {
            r = m
        }
    }
    return l
}

