import java.util.*;
import java.io.*;

class Main{
    static int n, v, p;
    static long m;
    static long[] a;
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        n=fsc.nextInt();
        m=fsc.nextLong();
        v=fsc.nextInt();
        p=fsc.nextInt();
        a=new long[n];
        for(int i=0;i<n;i++){
            a[i]=fsc.nextLong();
        }
        fsc.close();
        revSort(a);
        int pass=p-1;
        int fail=n;
        while(fail-pass>1){
            int mid=pass+(fail-pass)/2;
            if(pass(mid)) pass=mid;
            else fail=mid;
        }
        System.out.println(pass+1);
    }
    static boolean pass(int k){
        if(p-1+n-k-1>=v) return true;
        int restNo=v-(p-1+n-k);
        long rest=m*restNo;
        for(int i=p-1;i<k;i++){
            rest-=a[k]+m-a[i];
        }
        if(rest<=0) return true;
        else return false;
    }
    static void revSort(long[] a){
        Arrays.sort(a);
        int l=a.length;
        long tmp;
        for(int i=0;i<l/2;i++){
            tmp=a[i];
            a[i]=a[l-i-1];
            a[l-i-1]=tmp;
        }
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.*;
import java.io.*;
import java.util.function.*;

class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        long m = in.nextLong();
        int v = in.nextInt();
        int p = in.nextInt();
        long[] a = in.nextLongArray(n);
        long[] s = Arrays.copyOf(a, n);
        sort(s, Comparator.reverseOrder());
        TreeMap<Long, Integer> map = new TreeMap<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            map.put(a[i], map.getOrDefault(a[i], 0) + 1);
        }
        int sum = 0;
        long border = -1;
        long ans = 0;
        long ok = 0;
        int ch = 0;
        Map.Entry<Long, Integer> last = null;
        for (Map.Entry<Long, Integer> entry : map.entrySet()) {
            sum += entry.getValue();
            if (border == -1) {
                ans += entry.getValue();
                if (p <= sum) {
                    border = entry.getKey();
                } else {
                    ch += entry.getValue();
                    v -= entry.getValue();
                }
                last = entry;
                continue;
            }
            int rem = n - sum + entry.getValue();
            long vote = (v - rem) * m;
            ok += m * last.getValue() - (sum - ch - entry.getValue()) * (last.getKey() - entry.getKey());
            if (vote <= ok) {
                ans += entry.getValue();
            }
            last = entry;
        }
        out.println(ans);
    }

    static void sort(long[] a, Comparator<Long> comparator) {
        Long[] b = new Long[a.length];
        for (int i = 0; i < a.length; i++) {
            b[i] = a[i];
        }
        Arrays.sort(b, comparator);
        for (int i = 0; i < a.length; i++) {
            a[i] = b[i];
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class In {
    private BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 0x10000);
    private StringTokenizer tokenizer;

    String next() {
        try {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        } catch (IOException ignored) {
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    char[][] nextCharArray(int n, int m) {
        char[][] a = new char[n][m];
        for (int i = 0; i < n; i++) {
            a[i] = next().toCharArray();
        }
        return a;
    }

    int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    int[] nextIntArray(int n, IntUnaryOperator op) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = op.applyAsInt(nextInt());
        }
        return a;
    }

    long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
        }
        return a;
    }

    long[] nextLongArray(int n, LongUnaryOperator op) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = op.applyAsLong(nextLong());
        }
        return a;
    }
}

