    int MOD = (int)1e9+7;
    long ceil(long a, long b){return (a + b - 1) / b;}
    long gcd(long a, long b){return b == 0 ? a : gcd(b, a % b);}
    long lcm(long a, long b){return a / gcd(a, b) * b;}

    void solve() {
        int N = in.nextInt(), M = in.nextInt(), V = in.nextInt(), P = in.nextInt();
        int[] A = in.nextIntArray(N);
        for(int i = 0; i < N; i++) A[i] *= -1;
        Arrays.sort(A);
        for(int i = 0; i < N; i++) A[i] *= -1;

        int ok = 0, ng = N;
        while(Math.abs(ok - ng) > 1){
            int mid = (ok + ng) / 2;
            if(mid <= P-1){
                ok = mid;
            }else if(A[mid] + M < A[P-1]){
                ng = mid;
            }else{
                long sum = 0;
                for(int i = 0; i < P-1; i++) sum += M;
                for(int i = mid; i < N; i++) sum += M;
                for(int i = P-1; i < mid; i++) sum += Math.max(0, (A[mid] + M) - A[i]);
                if(sum >= (long)M * V) ok = mid;
                else ng = mid;
            }
        }
        out.println((ok + 1));
    }

