	static boolean f(long[] A,long M,int P,int V,int mid) {
		if (mid>=A.length-P) {
			return true;
		}
		long sum=0;
		for (int i = 0; i < A.length-P; i++) {
			if (i==mid) {
				continue;
			}
			if (A[mid]+M<A[i]) {
				return false;
			}
			sum+=Math.min(M, A[mid]+M-A[i]);
		}
		if (sum>=M*(V-P)) {
			return true;
		}else {
