public class Main {

  private static void solve() {
    int n = ni();
    long m = ni();
    long v = ni();
    int p = ni();
    long[] a = nal(n);

    Arrays.sort(a);


    long[] sum = new long[n + 1];
    for (int i = 0; i < n; i++) {
      sum[i + 1] += sum[i] + a[i];
    }

    int ret = p;
    for (int i = 0; i < n - p; i++) {
      if (a[i] + m < a[n - p])
        continue;

      long vote = m * v;
      vote -= p * m;
      long x = a[i] + m;

      vote -= i * m;

      int j = Math.min(n - p, lowerBound(a, x + 1));
      if (j > i) {
        vote -= (j - (i + 1)) * x - (sum[j] - sum[i + 1]);
      }

      if (vote <= 0) {
        ret++;
      }
    }
    System.out.println(ret);
  }

  public static int lowerBound(long[] a, long v) {
    int low = -1, high = a.length;
    while (high - low > 1) {
      int h = high + low >>> 1;
      if (a[h] >= v) {
        high = h;
      } else {
        low = h;
      }
    }
    return high;
  }

