		for (int i = 0; i < a.length; i++) {
			a[i] = sc.nextLong();
		}
		sc.close();
		Arrays.sort(a);
		a = reverse(a, a.length);

		boolean flag = true;

		int l = 0;
		int r = n;
		while (l < r) {
//			System.out.printf("Checking l=%d r=%d \n", l, r);
			int mid = (l + r) >>> 1;
			boolean able = true;
			if (mid < p) {
				flag = true;
			} else if (a[mid] + m < a[p - 1]) {
				flag = false;
			} else {
				long sum = (p - 1) * m + (n - mid - 1) * m + m;

				for (int i = p - 1; i < mid; i++) {
