        int n = sc.nextInt();
        long m = sc.nextLong();
        long v = sc.nextLong();
        int p = sc.nextInt();
        long[] a = new long[n];

        Map<Long, Long> map = new HashMap<Long, Long>();

        for(int i = 0; i < n; i++){
            long tmp = sc.nextLong();
            a[i] = tmp;
            if(map.containsKey(tmp)){
                map.put(tmp,map.get(tmp)+1);
            }else{
                map.put(tmp,(long)1);
            }
        }
        Arrays.sort(a);
        long border = a[n-p];
        for(int i = 1; i < n; i++){
            a[i] += a[i-1];
        }
        Object[] mapkey = map.keySet().toArray();
        Arrays.sort(mapkey);

        long[] arr = new long[mapkey.length];
        arr[0] = (long)mapkey[0] * map.get((long)mapkey[0]);
        for(int i = 1; i < mapkey.length; i++){
            arr[i] = arr[i-1] + (long)mapkey[i] * map.get((long)mapkey[i]);
        }

        long backCnt = 0;
        for(int i = 0; i < mapkey.length; i++){
            long tmp = (long)mapkey[i];
            if(tmp+m < border){
                backCnt += map.get(tmp);
                continue;
            }else{
                long back = backCnt + map.get(tmp);
                long remPoint = m*(v-(back + p-1));
                if(n-p-back < 0){
                    break;
                }
                float average = (a[n-p]-a[(int)back]+remPoint) / (n-p-back);
                if(average > tmp+m){
                    backCnt += map.get(tmp);
                    continue;
                }else{
                    break;
                }
            }

        }
        System.out.println(n-backCnt);
    }
}

import java.util.Arrays;

public class Main {

  private static void solve() {
    int n = ni();
    long m = ni();
    long v = ni();
    int p = ni();
    long[] a = nal(n);

    Arrays.sort(a);
    for (int i = 0, j = n - 1; i < j; i++, j--) {
      long tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
    }


    int ok = p - 1;
    int ng = n;
    long[][] b = new long[n][2];
    while (Math.abs(ok - ng) > 1) {
      int k = (ok + ng) / 2;

      long vote = (long) m * v;


      for (int i = 0; i < n; i++) {
        b[i][0] = i == k ? -1 : i;
        b[i][1] = a[i];
      }
      vote -= m;
      b[k][1] += m;
      long x = b[k][1];

      for (int i = 0; i < p - 1; i++) {
        b[i][1] += m;
        vote -= m;
        if (vote == 0)
          break;
      }


      for (int i = 0; i < n; i++) {
        if (i == k)
          continue;

        long d = Math.min(vote, Math.min(m, Math.max(0, x - a[i])));
        vote -= d;
        b[i][1] += d;
      }

      Arrays.sort(b, (o1, o2) -> {
        if (o1[1] == o2[1]) {
          return Long.signum(o1[0] - o2[0]);
        } else {
          return Long.signum(o2[1] - o1[1]);
        }
      });

      boolean suc = false;
      for (int i = 0; i < p; i++) {
        if (b[i][0] < 0) {
          suc = true;
          break;
        }
      }

      if (suc && vote <= 0) {
        ok = k;
      } else {
        ng = k;
      }
    }

    System.out.println(ok + 1);
  }

