    void solve() {
        int n = in.nextInt();
        long m = in.nextLong();
        int v = in.nextInt();
        int p = in.nextInt();
        long[] a = in.nextLongArray(n);
        Arrays.sort(a);
        int left = 0, right = n;
        while (right - left > 1) {
            int mid = (left + right) / 2;
            long border = a[mid] + m;
            long vote = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] <= a[mid] || n - i < p) {
                    vote += m;
                } else {
                    vote += border - a[i];
                }
            }
            if (vote >= v * m) {
                right = mid;
            } else {
                left = mid;
            }
        }
        out.println(n - right);
    }

