public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long m = sc.nextLong();
        long v = sc.nextLong();
        int p = sc.nextInt();
        long[] a = new long[n];

        Map<Long, Long> map = new HashMap<Long, Long>();

        for(int i = 0; i < n; i++){
            long tmp = sc.nextLong();
            a[i] = tmp;
            if(map.containsKey(tmp)){
                map.put(tmp,map.get(tmp)+1);
            }else{
                map.put(tmp,(long)1);
            }
        }
        Arrays.sort(a);
        long border = a[n-p];
        for(int i = 1; i < n; i++){
            a[i] += a[i-1];
        }
        Object[] mapkey = map.keySet().toArray();
        Arrays.sort(mapkey);

        long[] arr = new long[mapkey.length];
        arr[0] = (long)mapkey[0] * map.get((long)mapkey[0]);
        for(int i = 1; i < mapkey.length; i++){
            arr[i] = arr[i-1] + (long)mapkey[i] * map.get((long)mapkey[i]);
        }

        long backCnt = 0;
        for(int i = 0; i < mapkey.length; i++){
            long tmp = (long)mapkey[i];
            if(tmp+m < border){
                backCnt += map.get(tmp);
                continue;
            }else{
                long back = backCnt + map.get(tmp);
                long remPoint = Math.max(0,m*(v-(back + p-1)));
                if(n-p+1-back <= 0){
                    break;
                }
                long average = (a[n-p]-a[(int)(back-1)]+remPoint) / (n-p+1-back);
                if((a[n-p]-a[(int)(back-1)]+remPoint) % (n-p+1-back) != 0){
                    average += 1;
                }
                //System.out.println(tmp +" "+ (n-p+1-back) +" "+average + " " + (tmp + m) + " " + remPoint + " " + (a[n-p]-a[(int)(back-1)]+remPoint) );
                if(average > tmp+m){
                    backCnt += map.get(tmp);
                    continue;
                }else{
                    break;
                }
            }

        }
        System.out.println(n-backCnt);
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    long M = scanner.nextInt();
    long V = scanner.nextInt();
    int P = scanner.nextInt();
    int[] A = new int[N];
    for (int i = 0; i < N; i++) A[i] = scanner.nextInt();
    Arrays.sort(A);
    reverse(A);
    long[] cum = new long[N];
    for (int i = 1; i < N; i++) cum[i] = cum[i - 1] + A[i - 1];

    int count = P;
    int Q = P - 1;
    for (int i = P; i < N && A[i] + M < A[Q]; i++) {
      long cap = M * Q + M * (N - i) + (i - Q) * (A[i] + M) - (cum[i] - cum[Q]);
      if (cap >= M * V) count++;
    }
    System.out.println(count);
  }

  private static void reverse(int[] a) {
    int i = 0;
    int j = a.length - 1;
    while (i < j) {
      int tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
      i++;
      j--;
    }
  }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    FastScanner in;
    PrintWriter out;

    public static void main(String[] args) {
        new Main().runIO();
    }


    void solve() {
        int n = in.nextInt();
        int judges = in.nextInt();
        int chooseProblems = in.nextInt();
        int stayProblems = in.nextInt();
        int[] score = new int[n];
        for (int i = 0; i < n; i++) {
            score[i] = in.nextInt();
        }
        Arrays.sort(score);
        int lastBad = n - stayProblems;
        int left = -1, right = lastBad;
        while (right - left > 1) {
            int mid = (left + right) >> 1;
            // mid-th problem want to stay
            int badVotes = Math.max(0, chooseProblems - stayProblems - mid);
            int myScore = score[mid] + judges;
            long totalFree = 0;
            if (score[lastBad] > myScore) {
                left = mid;
                continue;
            }
            for (int i = mid + 1; i <= lastBad; i++) {
                totalFree += myScore - score[i];
            }
            if (totalFree >= badVotes * 1L * judges) {
                right = mid;
            } else {
                left = mid;
            }
        }
        out.println(n - right);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

