public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BVotingJudges solver = new BVotingJudges();
        solver.solve(1, in, out);
        out.close();
    }

    static class BVotingJudges {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            long njudge = in.nextLong(), v = in.nextLong();
            int P = in.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextLong();
            }
            mySort(a);
            for (int i = 0; i < a.length / 2; i++) {
                long tmp = a[n - 1 - i];
                a[n - 1 - i] = a[i];
                a[i] = tmp;
            }
            int L = 0, R = n;
            while (R - L > 1) {
                int M = (L + R) >> 1;
                long x = a[M];
                if (x + njudge < a[(int) (P - 1)]) R = M;
                else if (M < P) L = M;
                else {
                    long used = (P - 1) * njudge;
                    for (int i = (P - 1); i < n; i++) {
                        used += Math.min(x + njudge - a[i], njudge);
                    }
                    if (used >= njudge * v) L = M;
                    else R = M;
                }
            }
            out.println(L + 1);
        }

        private void mySort(long[] a) {
            Random random = new Random(System.currentTimeMillis());
            for (int i = 0; i < a.length; i++) {
                int j = random.nextInt(i + 1);
                long tmp = a[j];
                a[j] = a[i];
                a[i] = tmp;
            }
            Arrays.sort(a);
        }

    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int m = scan.nextInt();
    int v = scan.nextInt();
    int p = scan.nextInt();
    int[] ar = new int[n];
    for (int i = 0; i < ar.length; i++) {
      ar[i] = scan.nextInt();
    }

    Arrays.sort(ar);

    // binary search the answer
    int l = -1;
    int r = n - 1;
    int target = ar[n - p];
    int totalVote = m * (n-v);
    while (l+1 < r) {
      int mid = (r + l) / 2;
      if (mid >= n - p) {
        r = mid;
      } else {
        if (ar[mid] + m < target) {
          l = mid;
        } else {
          int max = ar[mid] + m;
          int nv = 0;
          boolean able = true;
          for (int i = mid + 1; i <= n - p; i++) {
              int x=m - (max-ar[i]);
              if(x > m){
                  able = false;
                  break;
              }
              nv+=x;
          }

          if(nv > totalVote || !able){
              l = mid;
          }else{
              r = mid;
          }
        }
      }
    }
    System.out.println(n - r);
  }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    long M = scanner.nextInt();
    long V = scanner.nextInt();
    int P = scanner.nextInt();
    int[] A = new int[N];
    for (int i = 0; i < N; i++) A[i] = scanner.nextInt();
    Arrays.sort(A);
    reverse(A);

    int left = 0;
    int right = N;
    while (right - left > 1) {
      int mid = (right + left) / 2;
      if (A[mid] <= A[P - 1]) {
        right = mid;
      } else {
        left = mid;
      }
    }

    int count = 0;
    for (int i = 0; i < N; i++) {
      if (A[i] >= A[right]) {
        count++;
        continue;
      }
      if (A[i] + M < A[right]) continue;
      long cap = 0;
      for (int j = right; j < i; j++) {
        cap += A[i] + M - A[j];
      }
      if (cap >= M * (V - N + i - right)) count++;
    }
    System.out.println(count);
  }

  private static void reverse(int[] a) {
    int i = 0;
    int j = a.length - 1;
    while (i < j) {
      int tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
      i++;
      j--;
    }
  }
}

