    static class B {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int n = in.ints();
            long m = in.longs();
            int v = in.ints(), p = in.ints();
            long[] a = in.longs(n);
            IntroSort.sort(a);
            long[] sum = IntMath.sum(a);

            int ans = p;
            for (int i = 0; i < n - p; i++) {
                if (a[i] + m < a[n - p]) continue;

                long rem = m * (v - p);
                rem -= (n - p - i) * (a[i] + m) - (sum[n - p + 1] - sum[i + 1]);
                rem -= i * m;
                if (rem <= 0) ans++;
            }
            out.ans(ans).ln();
        }

    }

    static class InsertionSort {
        private InsertionSort() {
        }

        static void sort(long[] a, int low, int high) {
            for (int i = low; i < high; i++) {
                for (int j = i; j > low && a[j - 1] > a[j]; j--) {
                    ArrayUtil.swap(a, j - 1, j);
                }
            }
        }

    }

    static final class IntMath {
        private IntMath() {
        }

        public static long[] sum(long[] a) {
            long[] sum = new long[a.length + 1];
            for (int i = 0; i < a.length; i++) {
                sum[i + 1] = sum[i] + a[i];
            }
