        for (int i=0;i<n;i++)   A[i] = in.nextLong();
        int count = 0;
        Arrays.sort(A);
        for (int i=0;i<n;i++)
        {
            if (i >= v - 1)
            {
                int idx = last(A, 0, n - 1, A[i] + m, n);
                if (idx < 0)    idx = -Arrays.binarySearch(A, A[i] + m) - 2;
                if (n - idx <= v)
                    count ++;
            }
            else
            {
                if (v == n)
                {
                    int idx = last(A, 0, n - 1, A[i], n);
                    if (n - idx <= v)
                        count++;
                }
                else
                {
                    if (A[i] + m >= A[n - 1])
                    {
                        int idx = last(A, 0, n - 1, A[i], n);
                        if (n - idx <= v)
                            count ++;
                    }
                    else
                    {
                        int idx = last(A, v, n - 1, A[i] + m, n);
                        if (idx < 0)
                            idx = -binarySearch0(A, v, n, A[i] + m) - 1;
                        if (v + n - i - idx - 2 < p)
                            count ++;
                    }
                }
            }
        }
