int num;
long m;
int v;
int p;
long point[];

int bisect() {
	int ng = num;
	int ok = 0;
	while (Math.abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if(isOK(mid)) {
			ok = mid;
		}else {
			ng = mid;
		}
	}
	return ok;
}
boolean isOK(int index) {
	long p2[] = new long[num];
	long add[] = new long[num];
	fill(add, 0);
	for(int i = 0; i < num; i ++) {
		p2[i] = point[i];
	}
	long max = point[index] + m;
	add[index] = m;
	long left = m * (v - 1);
	for(int i = num - 1; i >= 0; i --) {
		if(i == index) { continue; }
		add[i] = min(max - point[i], m);
		if(add[i] < 0) { add[i] = m; }
		if(left < add[i]) { add[i] = left; }
		left -= add[i];
	}
	for(int i = 0; i < num; i ++) {
		if(add[i] < m) {
			long add2 = min(left, m - add[i]);
			add[i] += add2;
			left -= add2;
		}
	}
	for(int i = 0; i < num; i ++) {
		p2[i] = point[i] + add[i];
	}

	int cnt = 0;
	for(int i = 0; i < num; i ++) {
		if(p2[i] > p2[index]) { cnt ++; }
	}
	return cnt < p;
}

