/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            int M = in.nextInt();
            int V = in.nextInt();
            int P = in.nextInt();
            Integer A[] = in.nextIntArray(N);
            Arrays.sort(A, Collections.reverseOrder());
            int ans = P;
            int remaining = N - 1;
            BigInteger sum = BigInteger.valueOf(A[P - 1]);
            BigInteger m = BigInteger.valueOf(M);
            for (int i = P; i < N; i++) {
                if (V <= remaining) {
                    if (A[i] + M >= A[P - 1]) {
                        ans++;
                    }
                } else {
                    BigInteger rem = m.multiply(BigInteger.valueOf(V - remaining));
                    BigInteger points = rem.add(sum);
                    int people = i - P + 1;
                    BigInteger maxPoints = points.divide(BigInteger.valueOf(people));
                    if (points.remainder(BigInteger.valueOf(people)).compareTo(BigInteger.ZERO) > 0) {
                        maxPoints = maxPoints.add(BigInteger.ONE);
                    }

                    if (BigInteger.valueOf(A[i]).add(m).compareTo(maxPoints) >= 0) {
                        ans++;
                    }
                }
                sum = sum.add(BigInteger.valueOf(A[i]));
                remaining--;
            }
            out.printLine(ans);
        }

    }

    static class OutputWriter {
        PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tokenizer = null;

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(in.readLine());
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                return null;
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public Integer[] nextIntArray(int size) {
            Integer array[] = new Integer[size];
            for (int i = 0; i < size; i++) {
                array[i] = nextInt();
            }
            return array;
        }

    }
}

import java.util.Arrays;
import java.util.Collections;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = Integer.parseInt(sc.next());
		int m = Integer.parseInt(sc.next());
		int v = Integer.parseInt(sc.next());
		int p = Integer.parseInt(sc.next());
		int threshold;

		Integer[] a = new Integer[n];

		for (int i = 0 ; i < n ; i++) {
			a[i] = Integer.parseInt(sc.next());
		}

		Arrays.sort(a, Collections.reverseOrder());
		int possibilityNum = n;
		threshold = a[p-1];

		//自分以下の合計
		long stock = 0;
		for (int i = p +1 ; i < n ; i++) {
			stock += threshold - a[i] ;
		}

		int v2 = (v - p);
		if(v2 < 0) {
			v2 = 0;
		}
		//合計しなければならない値
		int addValue = (v2)*m ;
		for (int i = p ; i < n ; i++) {
			threshold = a[p-1];

			if(addValue >= stock) {
			 threshold += (int) ((addValue - stock)/(n - p) + 1);
			}

			if(threshold > (a[i] + m)) {
				possibilityNum = i;
				break;
			}

			if(i != n-1) {
				stock -= a[i+1];
			}
		}		

		System.out.println(possibilityNum);

	}



}

