  public static class Solver {

    int N;
    long M, V, P;

    long[] A;

    public boolean ok(int t) {

      long[] B = new long[N];
      long[] C = Arrays.copyOf(A, N);

      long unvoted = M * V;

      long score = A[t] + M;
      C[t] = score;
      unvoted -= M;

      for (int i=0; i<N && unvoted > 0; i++) {
        if (i == t) continue;
        if (A[i] <= score) {
          if (A[i] + M <= score) {
            B[i] = 0;
            C[i] = A[i] + M;
            unvoted -= M;
          } else {
            B[i] = M - (score-A[i]);
            C[i] = score;
            unvoted -= (score - A[i]);
          }
        } else {
          B[i] = 0;
          C[i] = A[i] + M;
          unvoted -= M;
        }
      }

      for (int i=N-1; i>=0 && unvoted > 0; i--) {
        if (B[i] > 0) {
          C[i] += B[i];
          unvoted -= B[i];
        }
      }

      Arrays.sort(C);

      /*
      out.println(t);
      out.print(C, " ");
      out.println(score);
      out.println();
      */

      for (int i=N-1; i>=0; i--) {
        if (C[i] == score) {
          return (i >= N - P);
        }
      }

      return false;

    }

    public Solver() {

      N = sc.nextInt();
      M = sc.nextLong();
      V = sc.nextLong();
      P = sc.nextLong();

      A = sc.nextLongArray(N, false);

      Arrays.sort(A);

      int low = -1;
      int high = N-1;
      int mid = (high + low + 1) / 2;
      while (high - low > 1) {
        mid = (high + low) / 2;
        if (ok(mid)) {
          high = mid;
        } else {
          low = mid;
        }
      }

      out.println(N-high);

    }
  }

  public static void main(String[] args) {
    new Solver();
    out.flush();
  }

  static class FastScanner {
    private InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;


    public void load() {
      try {
        in = new FileInputStream(next());
      } catch (Exception e) {
        e.printStackTrace();
      }
    }

    private boolean hasNextByte() {
      if (ptr < buflen) {
        return true;
      } else {
        ptr = 0;
        try {
          buflen = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (buflen <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) return buffer[ptr++];
      else return -1;
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    public boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) throw new NoSuchElementException();
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    public long nextLong() {
      if (!hasNext()) throw new NoSuchElementException();
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int N, boolean oneBased) {
      if (oneBased) {
        int[] array = new int[N + 1];
        for (int i = 1; i <= N; i++) {
          array[i] = sc.nextInt();
        }
        return array;
      } else {
        int[] array = new int[N];
        for (int i = 0; i < N; i++) {
          array[i] = sc.nextInt();
        }
        return array;
      }
    }

    public long[] nextLongArray(int N, boolean oneBased) {
      if (oneBased) {
        long[] array = new long[N + 1];
        for (int i = 1; i <= N; i++) {
          array[i] = sc.nextLong();
        }
        return array;
      } else {
        long[] array = new long[N];
        for (int i = 0; i < N; i++) {
          array[i] = sc.nextLong();
        }
        return array;
      }
    }
  }

