public void solve() {
	int num = ni();
	long m = nl();
	int v = ni();
	int p = ni();
	long a[] = nl(num);
	Arrays.sort(a);
	reverse(a);
	long sum[] = sums(a);
	int cnt = 0;
	for(int i = 0; i < num; i ++) {
		int cntLarge = cntBS(a, a[i] + m, false, true, false);
		if(cntLarge >= p) continue;
		cntLarge = p - 1;
		long tmp = 0;
		tmp += m * cntLarge;
		tmp += m * (num - i);
		tmp += (a[i] + m) * (i - cntLarge) - (sum[i] - sum[cntLarge]);
		if(tmp >= m * v) cnt ++;
	}
	prtln(cnt);
}



