		long[] a = new long[n];
		for(int i = 0; i < n; i++)
			a[i] = sc.nextLong();

		Arrays.sort(a);

		int l = 0;
		int r = n-1;

		int worstgud = 3*n;
//		System.out.println(Arrays.toString(a));
		while(r>=l)
		{
			int consider = (l+r)/2;

			//can this problem get chosen?
			long score = a[consider] + m; //this problem will get this much score
			//pth highest score should be <= score^
//			System.out.println(l + " " + r + " " + consider + ": score " + score);

			int beaters = 0; //initial beaters
			for(int i = 0; i < n; i ++)
			{
				if(a[i] > score)beaters++;
			}
			//beaters must be less than p

			long[] b = a.clone();
			long rem = (m*v)-m;
			for(int i = 0; i < n && rem > 0; i++)
			{ //distribute rest of score
				if(i == consider)continue;

				//give b[i] score
				long give = Math.min(score - b[i], m); //up to m that doesn't beat score

				give = Math.min(give, rem);
				if(give > 0)
				{
					b[i] += give;
					if(b[i]>score)beaters++;
					rem -= give;
				}
				else 
				{
					break;
				}
			}

			//distribute rem into beaters first
			for(int i = n-1; i >= 0 && rem > 0; i--)
			{
				boolean wasbeater = b[i] > score;
				long alreadygiven = b[i] - a[i];
				long givefroma = m;
				long give = givefroma - alreadygiven; //give this many more
				give = Math.min(give, rem);

				b[i] += give;
				rem -= give;
				if(!wasbeater && b[i] > score)beaters++; //now beater
			}

			if(rem == 0 && beaters < p)
			{
//				System.out.println("GUD ");
				//gud
				worstgud = Math.min(worstgud, consider);
				r = consider-1;
			}
			else
			{
//				System.out.println("NOP");
				//nop
				l = consider+1;
			}

		}

//		System.out.println("wg " + worstgud);
		System.out.println(n-worstgud);
	}

}

import java.util.Arrays;

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    int v = ni();
    int p = ni();
    int[] a = na(n);

    Arrays.sort(a);
    for (int i = 0, j = n - 1; i < j; i++, j--) {
      int tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
    }


    int ok = p - 1;
    int ng = n;
    int[][] b = new int[n][2];
    while (Math.abs(ok - ng) > 1) {
      int k = (ok + ng) / 2;

      long vote = (long) m * v;

      for (int i = 0; i < n; i++) {
        b[i][0] = i == k ? -1 : i;
        b[i][1] = a[i];
      }

      for (int i = 0; i < p - 1; i++) {
        b[i][1] += m;
        vote -= m;
      }
      vote -= m;
      b[k][1] += m;
      int x = b[k][1];

      for (int i = 0; i < n; i++) {
        if (i == k)
          continue;

        int d = Math.min(m, x - a[i]);
        vote -= d;
        b[i][1] += d;
      }

      Arrays.sort(b, (o1, o2) -> {
        if (o1[1] == o2[1]) {
          return o1[0] - o2[0];
        } else {
          return o2[1] - o1[1];
        }
      });

      boolean suc = false;
      for (int i = 0; i < p; i++) {
        if (b[i][0] < 0) {
          suc = true;
          break;
        }
      }

      if (suc && vote <= 0) {
        ok = k;
      } else {
        ng = k;
      }
    }

    System.out.println(ok + 1);
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
        if (debug != null) {
          try {
            is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(debug));
          } catch (Exception e) {
            throw new RuntimeException(e);
          }
        }
        reader = new java.io.BufferedReader(new java.io.InputStreamReader(is), 32768);
        solve();
        out.flush();
        tr((System.currentTimeMillis() - start) + "ms");
      }
    }, "", 64000000).start();
  }

  private static java.io.InputStream is = System.in;
