		N = nextInt();
		M = nextLong();
		V = nextInt();
		P = nextInt();

		long []A = nextLongArray(N);
		Arrays.sort(A);
		long []maxup = A.clone();
		long []Rup = A.clone();
		long up = M*1;
		for(int i=0;i<N;i++) {
			maxup[i] += up;
		}
		for(int i=N-1;i>N-P;i--) {
			Rup[i] += up;
		}

		int low = 0,hi = N-1;
		for(int i=0;i<N;i++) {
			if(maxup[i]>=Rup[N-P]) {
				low = i;
				break;
			}
		}

		int index = (low + hi) / 2;
		int tr = N-P;
		long order_p = Math.max(0,V-P);
		while(low < hi) {
			if(order_p <= index) {
				hi = index;
			}else {
				long _order_p = (order_p-index)*M; //右側に送るポイント
				int _i = index+1;
				while(_order_p > 0 && _i < tr+1) {
					long t = Math.max(maxup[index]-A[_i],0);
					if(t == 0)break;
					_order_p -= t;
					_i++;
				}
				if(_order_p <= 0) {
					hi = index;
				}else {
					low = index+1;
				}
			}
			index = (low + hi) / 2;
		}
		long cnt = N-index;

		out.println(cnt);
	}

