import java.util.*;

public class Main {
    static long[] nums;
    static int n;
    static long m;
    static long v;
    static long p;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n=sc.nextInt();
        m=sc.nextInt();
        v=sc.nextInt();
        p=sc.nextInt();
        nums=new long[n];
        for(int i=0;i<n;i++){
            nums[i]=sc.nextInt();
        }
        Arrays.sort(nums);
        int now=n/2;
        int toadd=n/2;
        boolean ablenow;
        boolean ablenext;
        while(true){
            if(now<=-1||now>=n-1){
                break;
            }
            ablenow=isable(now);
            ablenext=isable(now+1);

            if(!ablenow&&ablenext){
                break;
            }else if(ablenow){
                now-=Math.max(1,toadd/=2);

            }else{
                now+=Math.max(1,toadd/=2);
            }
        }
        System.out.println(n-now-1);


    }
    static boolean isable(int index){
        long max=nums[index]+m;
        long rest=(v-1)*m;
        long count=p-1;
        for(int i=n-1;i>=0;i--){
            if(i==index)continue;
            if(count>0&&rest>=m){
                rest-=m;
                count--;
            }else if(count>0){
                rest=0;
                count--;
            }else if(nums[i]<=max){
                long tmp=Math.min(rest, Math.min(m, max-nums[i]));
                rest-=tmp;
            }else if(nums[i]>max){
                return false;
            }

        }
        if(rest>0){
            return false;
        }
        return true;
    }

}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.*;

public class Main {

  public static void main(String[] args) {
    solve(System.in, System.out);
  }

  private static class Problem implements Comparable<Problem> {

    public int getScore() {
      return score;
    }

    public int getIndex() {
      return index;
    }

    private final int index;
    private final int score;

    private Problem(int index, int score) {
      this.score = score;
      this.index = index;
    }

    @Override
    public int compareTo(Problem o) {
      return Integer.compare(this.score, o.score);
    }
  }

  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();
    int m = sc.nextInt();
    int v = sc.nextInt();
    int p = sc.nextInt();

    List<Problem> list = new ArrayList<>(n);

    for (int i = 0; i < n; i++) {
      Problem problem = new Problem(i, sc.nextInt());
      list.add(problem);
    }

    list.sort(Comparator.comparingInt(Problem::getScore));

    List<Integer> accum = new ArrayList<>();

    int sum = 0;
    for (int i = 0; i < n; i++) {
      accum.add(sum);
      sum += list.get(i).score;
    }
    accum.add(sum);

    Set<Problem> ans = new HashSet<>();

    for (int i = n - 1; 0 <= i; i--) {
      Problem problem = list.get(i);
      if (!isAcceptable(n, m, v, p, i, problem, accum)) break;
      ans.add(problem);
    }
    os.println(ans.size());
  }

  private static boolean isAcceptable(int n, long m, long v, int p, int i, Problem problem, List<Integer> accum) {
    long vote = 0;
    int l = i;
    int r = Math.max(i, (n - 1) - ((p - 1) - 1));
    vote += m * ((n - 1) - r);
    vote += m * (l + 1);
    long targetScore = problem.score + m; // all man will vote to the target
    vote += targetScore * (r - l) - (accum.get(r) - accum.get(l));
    return m * v <= vote;
  }
}

import java.util.Arrays;
import java.util.Collections;
