import java.util.*;

public class Main {
    static long[] nums;
    static int n;
    static int m;
    static int v;
    static int p;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n=sc.nextInt();
        m=sc.nextInt();
        v=sc.nextInt();
        p=sc.nextInt();
        nums=new long[n];
        for(int i=0;i<n;i++){
            nums[i]=sc.nextInt();
        }
        Arrays.sort(nums);
        int now=n/2;
        int toadd=n/2;
        boolean ablenow;
        boolean ablenext;
        while(true){
            if(now<=-1||now>=n-1){
                break;
            }
            ablenow=isable(now);
            ablenext=isable(now+1);

            if(!ablenow&&ablenext){
                break;
            }else if(ablenow){
                now-=Math.max(1,toadd/=2);

            }else{
                now+=Math.max(1,toadd/=2);
            }
        }
        System.out.println(n-now-1);


    }
    static boolean isable(int index){
        long max=nums[index]+m;
        long rest=(v-1)*m;
        int count=p-1;
        for(int i=n-1;i>=0;i--){
            if(i==index)continue;
            if(count>0&&rest>=m){
                rest-=m;
                count--;
            }else if(rest<1){
                return true;
            }else if(nums[i]<=max){
                long tmp=Math.min(rest, Math.min(m, max-nums[i]));
                rest-=tmp;
            }else if(nums[i]>max){
                return false;
            }

        }
        if(rest>0){
            return false;
        }
        return true;
    }

}

import java.util.*;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt(), M = sc.nextInt(), V = sc.nextInt(), P = sc.nextInt();
		int A[] = new int[N];
		for(int i = 0;i<N;i++) A[i]=sc.nextInt();
		sc.close();
		rsort(A);

		long l = P-1;
		long r = N;
		while(l+1<r) {
			long c = (l+r)/2;
			int tar = (int)c;
			long now = A[tar];
			long line = (long)now + M;
			//A[P-1]~A[tar - 1]をline以下にできるか
			long needPlus = ((long)V-(P-1)-((long)(N-1)-tar + 1))*M;
			long sum = 0;
			for(int i=P-1;i<tar;i++) {
				sum += A[i];
			}
			long max = Math.max(A[P-1], ((long)sum+needPlus+tar-(P-1)-1)/((long)tar-(P-1)));
			if(line>=max) l=c;
			else r=c;
		}

		System.out.println(l);
	}
	static void rsort(int arr[]) {
		Arrays.sort(arr);
		int len = arr.length;
		for(int i=0;i<len/2;i++) {
			int tmp = arr[i];
			arr[i]=arr[len-1-i];
			arr[len-1-i]=tmp;
		}
	}
}

