class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        long m = in.nextLong();
        int v = in.nextInt();
        int p = in.nextInt();
        long[] a = in.nextLongArray(n);
        Arrays.sort(a);
        TreeMap<Long, Integer> map = new TreeMap<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            map.put(a[i], map.getOrDefault(a[i], 0) + 1);
        }
        int sum = 0;
        int index = 0;
        for (Map.Entry<Long, Integer> entry : map.entrySet()) {
            sum += entry.getValue();
            if (p <= sum) {
                break;
            }
            index = sum;
        }
        index = n - index;
        int left = 0, right = n;
        while (right - left > 1) {
            int mid = (left + right) / 2;
            long border = a[mid] + m;
            long vote = (n - index) * m;
            for (int i = 0; i < index; i++) {
                if (a[i] <= a[mid]) {
                    vote += m;
                } else {
                    vote += border - a[i];
                }
            }
            if (vote > v * m) {
                right = mid;
            } else {
                left = mid;
            }
        }
        out.println(n - right);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

