    static boolean pass(int k){
        if(p-1+n-k>=v){
            if(a[k]+m>=a[p-1]) return true;
            else return false;
        }
        if(a[k]+m<a[p-1]) return false;
        int restNo=v-(p-1+n-k);
        long rest=m*restNo;
        for(int i=p-1;i<=k-1;i++){
            rest-=a[k]+m-a[i];
        }
        return rest<=0;
