public class Main {
    static Scanner sc = new Scanner(System.in);
    static int n = 0;
    static int m = 0;
    static int v = 0;
    static int p = 0;
    static Long[] a = null;

    public static void main(String[] args) {
        n = sc.nextInt();
        m = sc.nextInt();
        v = sc.nextInt();
        p = sc.nextInt();
        a = new Long[n];
        for(int i = 0; i < n; ++i) a[i] = sc.nextLong();

        Arrays.sort(a, Comparator.reverseOrder());
        // System.out.println(Arrays.toString(a));

        int ans = binaryLowerSearch() + 1;
        System.out.println(ans);
    }

    static int binaryLowerSearch() {
        int left = 0;
        int right = n;
        while(right - left > 1) {
            int mid = right - (right - left) / 2;
            // System.out.println("mid = " + mid);
            if(canMeetCondition(mid)) {
                // System.out.println("CAN MEET");
                left = mid;
            } else {
                // System.out.println("CANNOT MEET");
                right = mid;
            }
        }
        return left;
    }

    static boolean canMeetCondition(int index) {
        if(index < p) return true;

        long votes = 0;
        for(int i = 0; i < n; ++i) {
            if(i < p - 1) {
                votes += m;
            } else if(i <= index) {
                votes = votes + a[index] + m - a[i];
            } else {
                votes += m;
            }
        }
        return (votes >= 1L * m * v);
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.*;

public class Main {

  public static void main(String[] args) {
    solve(System.in, System.out);
  }

  private static class Problem implements Comparable<Problem> {

    public int getScore() {
      return score;
    }

    public int getIndex() {
      return index;
    }

    private final int index;
    private final int score;

    private Problem(int index, int score) {
      this.score = score;
      this.index = index;
    }

    @Override
    public int compareTo(Problem o) {
      return Integer.compare(this.score, o.score);
    }
  }

  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();
    int m = sc.nextInt();
    int v = sc.nextInt();
    int p = sc.nextInt();

    List<Problem> list = new ArrayList<>(n);

    for (int i = 0; i < n; i++) {
      Problem problem = new Problem(i, sc.nextInt());
      list.add(problem);
    }

    list.sort(Comparator.comparingInt(Problem::getScore));

    List<Long> accum = new ArrayList<>();

    long sum = 0;
    for (int i = 0; i < n; i++) {
      accum.add(sum);
      sum += list.get(i).score;
    }
    accum.add(sum);

    Set<Problem> ans = new HashSet<>();
    Problem threshold = list.get(n - p);

    for (int i = n - 1; 0 <= i; i--) {
      Problem problem = list.get(i);
      if (!isAcceptable(n, m, v, p, i, problem, threshold, accum)) break;
      ans.add(problem);
    }
    os.println(ans.size());
  }

  private static boolean isAcceptable(int n, long m, long v, int p, int i, Problem problem, Problem threshold, List<Long> accum) {
    if (problem.score + m < threshold.score) return false;

    long vote = 0;
    int l = i;
    int r = Math.max(i, (n - 1) - ((p - 1) - 1));
    vote += m * (long) ((n - 1) - r);
    vote += m * (long) (l + 1);
    long targetScore = problem.score + m; // all man will vote to the target
    vote += targetScore * (long) (r - l) - (accum.get(r) - accum.get(l));
    return m * v <= vote;
  }
}

