class Main {
    final static int INF = 1 << 28;
    final static long LNF = 1L << 60;
    final static double EPS = 1e-9;
    final static double GOLDEN_RATIO = (1.0 + Math.sqrt(5)) / 2.0;

    static final long MOD = 1_000_000_007;

    public static void main(String[] args) throws Exception {
        // long start = System.currentTimeMillis();
        final MyScanner sc = new MyScanner();
        int N;
        N = sc.nextInt();
        int M;
        M = sc.nextInt();
        int V;
        V = sc.nextInt();
        int P;
        P = sc.nextInt();
        int[] A = new int[(int)(N)];
        for(int i = 0 ; i < N ; i++){
                A[i] = sc.nextInt();
        }
        solve(N, M, V, P, A);
        // long end = System.currentTimeMillis();
        // System.out.println((end - start)  + "ms");
    }

    static void solve(int N, int M, int V, int P, int[] A){
        HashMap<Integer, Integer> hashmap = new HashMap<>();

        for (int l : A) {
            if(hashmap.containsKey(l)) hashmap.put(l, hashmap.get(l) + 1);
            else hashmap.put(l, 1);
        }

        TreeSet<Integer> ts = new TreeSet(hashmap.keySet());

        int v;
        int n_v;
        int n_sum = 0;
        int n_border = 0;
        int n_ok = 0;
        int v_border = 0;
        int ans = 0;
        int fix = 0;

        while(!ts.isEmpty()) {
            v = ts.pollLast();
            n_v = hashmap.get(v);
            n_sum += n_v;

            if(n_sum < P) {
                ans = n_sum;
                n_ok = n_sum;
            } else {
                if(v_border < 0) v_border = v;
                n_border += n_v;
                fix += (v_border - v) * n_v;

                int n_vote = (V - (N - n_border)) * M;
                int n_fixxed_vote = n_vote - fix;
                if(n_fixxed_vote < 0) {
                    ans = n_sum;
                } else {
