    void solve() {
        int n = in.nextInt();
        long m = in.nextLong();
        int v = in.nextInt();
        int p = in.nextInt();
        long[] a = in.nextLongArray(n);
        long[] s = Arrays.copyOf(a, n);
        sort(s, Comparator.reverseOrder());
        TreeMap<Long, Integer> map = new TreeMap<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            map.put(a[i], map.getOrDefault(a[i], 0) + 1);
        }
        int sum = 0;
        long border = -1;
        long ans = 0;
        long ok = 0;
        int ch = 0;
        Map.Entry<Long, Integer> last = null;
        for (Map.Entry<Long, Integer> entry : map.entrySet()) {
            sum += entry.getValue();
            if (border == -1) {
                ans += entry.getValue();
                if (p < sum) {
                    border = entry.getKey();
                } else {
                    ch += entry.getValue();
                    v -= entry.getValue();
                }
                last = entry;
                continue;
            }
            int rem = n - sum + entry.getValue();
            long vote = (v - rem) * m;
            ok += m * last.getValue() - (sum - ch - entry.getValue()) * (last.getKey() - entry.getKey());
            if (vote <= ok) {
                ans += entry.getValue();
            }
            last = entry;
        }
        out.println(ans);
    }

