                } else if(n_fixed_vote < 0) {
                    ans = n_sum;
                } else {
                    int delta = (int)Math.ceil(1.0 * n_fixed_vote / (n_sum - P + 1));
                    if(v + M >= v_border + delta) ans = n_sum;
