    long tmp2 = a[(int)n-(int)p-1]; //一個下

    //境目が同じ数字だったら
    int cnt = 0;
    long tmp3 = 0;
    if(tmp==tmp2){ //どちらも選べる状態
      cnt = (int)n-(int)p; //一個下からスタート
      while(a[cnt]==tmp2){
        cnt--;
        if(cnt==0){
          ok = false;
          break;
        }
      }
      tmp3 = a[cnt]; //選ばれない上限値
    }
    else{
