    static boolean pass(int k){
        if(p-1+n-k>=v){
            if(a[k]+m>=a[p-1]) return true;
            else return false;
        }
        int restNo=v-(p-1+n-k);
        long now=0;
        for(int i=k-1;i>=p-1;i--){
            if(a[k]+m-a[i]>=m){
                restNo--;
            }
            else{
                long c=a[k]+m-a[i];
                if(now+c>=m) restNo--;
                now=(now+c)%m;
            }
        }
        return restNo<=0;
    }
    static void revSort(long[] a){
        Arrays.sort(a);
        int l=a.length;
        long tmp;
        for(int i=0;i<l/2;i++){
            tmp=a[i];
            a[i]=a[l-i-1];
            a[l-i-1]=tmp;
        }
