		long[] A=sc.nextLongArray(N);
		Arrays.sort(A);
		int from=0;
		int to=N-1;
		while ((to-from)>=1) {
			int mid=(to-from)/2+from;
			if (f(A, M, P, V, mid)) {
				to=mid;
