                after -= a[i];
                if (a[i] + m >= a[n - p]) {
                    long rem = m * (v - p + 1);
                    rem -= (n - p - i) * (a[i] + m) - after;
                    rem -= i * (a[i] + m) - prev;
                    if (rem <= 0) ans++;
                }
                prev += a[i];
            }
            out.ans(ans).ln();
        }

    }

    static class LightScanner {
