  public static class Solver {

    int N;
    long M, V, P;

    long[] A;

    public boolean ok(int t) {

      long[] B = new long[N];
      long[] C = Arrays.copyOf(A, N);

      long unvoted = M * V;

      long score = A[t] + M;
      unvoted -= M;

      for (int i=0; i<N && unvoted > 0; i++) {
        if (i == t) continue;
        if (A[i] <= score) {
          if (A[i] + M <= score) {
            B[i] = 0;
            C[i] = A[i] + M;
            unvoted -= M;
          } else {
            B[i] = M - (score-A[i]);
            C[i] = score;
            unvoted -= (score - A[i]);
          }
        } else {
          B[i] = 0;
          C[i] = A[i] + M;
          unvoted -= M;
        }
      }

      for (int i=N-1; i>=0 && unvoted > 0; i--) {
        if (B[i] > 0) {
          C[i] += B[i];
          unvoted -= B[i];
        }
      }

      Arrays.sort(C);

      /*
      out.println(t);
      out.print(C, " ");
      out.println(score);
      out.println();
      */

      for (int i=N-1; i>=0; i--) {
        if (C[i] == score) {
          return (i >= N - P);
        }
      }

      return false;

    }

    public Solver() {

      N = sc.nextInt();
      M = sc.nextLong();
