import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in)) {
            int N = sc.nextInt();
            long M = sc.nextLong();
            int V = sc.nextInt();
            int P = sc.nextInt();
            long[] A = new long[N];
            for (int i = 0; i < N; i++) {
                A[i] = sc.nextLong();
            }

            Arrays.sort(A);

            long[] S = new long[N];
            for (int i = 0; i < N; i++) {
                if (i == 0) {
                    S[i] = A[i];
                } else {
                    S[i] = S[i - 1] + A[i];
                }
            }

            //System.out.println(Arrays.toString(A));

            long ans = -1;

            for (int i = 0; i < N; i++) {
                long K = A[i] + M;

                if (K < A[N - P]) {
                    continue;
                }

                long x = M * (V - i - 1);
                if (x <= 0) {
                    ans = N - i;
                    break;
                }

                int pos = Arrays.binarySearch(A, K + 1);
                if (pos < 0) {
                    pos = -(pos + 1);
                }

                //System.out.println(i + " x : " + x + " pos : " + pos);

                x -= K * (pos - i - 1) - (S[pos - 1] - S[i]);
                if (x <= 0) {
                    ans = N - i;
                    break;
                }

                x -= M * (N - pos);
                if (x <= 0) {
                    ans = N - i;
                    break;
                }

                x -= M * (pos - (N - P) - 1) - (K * (pos - (N - P) - 1) - (S[pos - 1] - S[N - P]));
                if (x <= 0) {
                    ans = N - i;
                    break;
                }

                //System.out.println(i + " x : " + x);
            }

            System.out.println(ans);
        }
    }

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int m = scanner.nextInt();
		int v = scanner.nextInt();
		int p = scanner.nextInt();
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = scanner.nextInt();
		}
		scanner.close();
		Arrays.parallelSort(a);

		int result = p;

		for (int i = p + 1; i <= n; i++) {
			if (naive(i, n, m, v, p, a)) {
				result = i;
			} else {
				break;
			}
		}

		System.out.println(result);
	}

	static boolean naive(int k, int n, int m, int v, int p, int[] a) {
		int threshold = a[n - k] + m;
		if (threshold < a[n - p]) {
			return false;
		}
		long canVote = (p - 1) * m;
		for (int i = 0; i <= n - p; i++) {
			canVote += Math.min(m, threshold - a[i]);
		}
		return canVote >= (long) m * v;
	}

	static boolean canBeChosen(int k, int n, int m, int v, int p, int[] a) {
		if (a[n - k] == a[n - p]) {
			return true;
		}
		int threshold = a[n - k] + m;
		if (threshold < a[n - p]) {
			return false;
		}
		int remain = v - (n - k + p);
		if (remain <= 0) {
			return true;
		}
		int canVote = 0;
		for (int i = p; i < k; i++) {
			canVote += threshold - a[n - i];
		}
		return canVote >= remain * m;

	}
}

