    public static boolean check(int x){
        if(a[x]+m < a[p-1]){
            return false;
        }
        long sum = 0;
        for(int i=0; i<n; i++){
            if(i<p-1 || x<=i){
                sum+=m;
            }else{
                sum+=Math.max(a[x]+m-a[i], 0);
            }
        }

        return sum >= m*v;
    }
