class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        long m = in.nextLong();
        int v = in.nextInt();
        int p = in.nextInt();
        long[] a = in.nextLongArray(n);
        long[] s = Arrays.copyOf(a, n);
        sort(s, Comparator.reverseOrder());
        TreeMap<Long, Long> map = new TreeMap<>(Comparator.reverseOrder());
        for (int i = 0; i < n; i++) {
            map.put(a[i], map.getOrDefault(a[i], 0L) + 1);
        }
        long sum = 0;
        long border = -1;
        long ans = 0;
        long ok = 0;
        long ch = 0;
        Map.Entry<Long, Long> last = null;
        for (Map.Entry<Long, Long> entry : map.entrySet()) {
            sum += entry.getValue();
            if (border == -1) {
                ans += entry.getValue();
                if (p <= sum) {
                    border = entry.getKey();
                } else {
                    ch += entry.getValue();
                    v -= entry.getValue();
                }
                last = entry;
                continue;
            }
            long rem = n - sum + entry.getValue();
            long vote = (v - rem) * m;
            ok += m * last.getValue() - (sum - ch - entry.getValue()) * (last.getKey() - entry.getKey());
            if (vote <= ok) {
                ans += entry.getValue();
            }
            last = entry;
        }
        out.println(ans);
    }

    static void sort(long[] a, Comparator<Long> comparator) {
        Long[] b = new Long[a.length];
        for (int i = 0; i < a.length; i++) {
            b[i] = a[i];
        }
        Arrays.sort(b, comparator);
        for (int i = 0; i < a.length; i++) {
            a[i] = b[i];
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

