import java.util.*;
import java.util.Arrays;

class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int m = sc.nextInt();
    int v = sc.nextInt();
    int p = sc.nextInt();
    Integer a[] = new Integer[n];
    for (int i=0; i<n; i++){
      a[i] = sc.nextInt();
    }

    Arrays.sort(a, Collections.reverseOrder());
    int result = 0;
    int defaultMin = 0;
    for (int i=0; i<n; i++) {
      if (i<p) {
        result++;
        defaultMin = a[i];
        continue;
      }

      if (a[i]==defaultMin) {
        result++;
        continue;
      }

      if ((n-i)>v) {
        result++;
        continue;
      }


      if (defaultMin>a[i]+m) {
        continue;
      }

      if ((v-(n-i))<p) {
        result++;
        continue;
      }

      // 選択し入りに影響しない上位に入れた後のことを考える。
      int restV = v-(n-i)-(p-1);
      int poolVotes = restV * m;

      for (int j=p-1; j<n-i; j++) {
        if (i==j) {
          continue;
        }
        int tmp=a[j];
        if (tmp<a[i]+m) {
          int count = 0;
          while (tmp+1<a[i]+m) {
            poolVotes--;
            tmp++;
            count++;
            if (count==m) {
              continue;
            }
          }
        }
      }
      if (poolVotes<=0) {
        result++;
      }

    }


    System.out.println(result);
  }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int n = scanner.nextInt();
		int m = scanner.nextInt();
		int v = scanner.nextInt();
		int p = scanner.nextInt();
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = scanner.nextInt();
		}
		scanner.close();
		Arrays.parallelSort(a);

		int result = p;

		for (int i = p + 1; i <= n; i++) {
			if (naive(i, n, m, v, p, a)) {
				result = i;
			} else {
				break;
			}
		}

		System.out.println(result);
	}

	static boolean naive(int k, int n, int m, int v, int p, int[] a) {
		int threshold = a[n - k] + m;
		if (threshold < a[n - p]) {
			return false;
		}
		long canVote = (long) (p - 1) * m;
		for (int i = 0; i <= n - p; i++) {
			canVote += Math.min(m, threshold - a[i]);
		}
		return canVote >= (long) m * v;
	}

	static boolean canBeChosen(int k, int n, int m, int v, int p, int[] a) {
		if (a[n - k] == a[n - p]) {
			return true;
		}
		int threshold = a[n - k] + m;
		if (threshold < a[n - p]) {
			return false;
		}
		int remain = v - (n - k + p);
		if (remain <= 0) {
			return true;
		}
		int canVote = 0;
		for (int i = p; i < k; i++) {
			canVote += threshold - a[n - i];
		}
		return canVote >= remain * m;

	}
}

