		main.solve();
		System.exit(0);
	}

	void solve() {
		N = nextInt();
		M = nextLong();
		V = nextInt();
		P = nextInt();

		long []A = nextLongArray(N);
		Arrays.sort(A);
		long []maxup = A.clone();
		long []Rup = A.clone();
		long up = M*1;
		for(int i=0;i<N;i++) {
			maxup[i] += up;
		}
		for(int i=N-1;i>N-P;i--) {
			Rup[i] += up;
		}

		long order_p = Math.max(0,V-P);
		long cnt = 0,tr = N-P,threw_num = -1;
		for(int i=0;i<N;i++) {
			if(i>=tr) {
				cnt++;
				continue;
			}

			if(maxup[i]>=Rup[N-P]) {
				if(threw_num == maxup[i]) continue;

				if(order_p <= i) {
					cnt++;
					tr = i;
				}else {
					long _order_p = (order_p-i)*M; //右側に送るポイント
					int _i = i+1;
					while(_order_p > 0 && _i < tr+1) {
						long t = Math.max(maxup[i]-A[_i],0);
						if(t == 0)break;
						_order_p -= t;
						_i++;
					}
					if(_order_p <= 0) {
						tr = i;
						cnt++;
					}else {
						threw_num = A[i];
					}
				}
			}
		}

		out.println(cnt);

	}

