import java.util.function.IntPredicate;

public class Main {

    static int N, M, V, P;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        V = sc.nextInt();
        P = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        Arrays.sort(A);
        int lo = minimize(0, N, Main::isOk);
        return N - lo;
    }

    static boolean isOk(int idx) {
        // すでにP番目以内の場合はok
        if( N - idx <= P ) return true;

        // P番目まで繰り上げることを考える
        // とりあえずidxに全員が投票する
        int a = A[idx] + M;
        int p = A[N-P];
        int v = V-1;

        // 盛っても届かないなら無理
        if( a < p ) return false;

        // 残りの投票をいい感じにばらまいて大丈夫かどうか

        // 上位P-1個を増やしても問題ない
        v -= P-1;
        if( v < 0 ) return true;

        // [0, idx)を増やしても問題ない
        v -= idx;
        if( v < 0 ) return true;

        // (idx, N-P)の間のやつらに投票を配り切れたら勝ち
        long r = (long)v * M;
        for (int i = idx+1; i < N-P; i++) {
            r -= a - A[i];
        }
        return r <= 0;
    }

    static int minimize(int lo, int hi, IntPredicate p) {
        while(lo < hi) {
            int x = ((hi - lo) >>> 1) + lo;
            if( p.test(x) ) {
                hi = x;
            } else {
                lo = x + 1;
            }
        }
        return lo;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static void writeSingleLine(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < as.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(as[i]);
        }
        pw.println();
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg == null) j.add("null");
            else if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }

    static void printSingleLine(int[] array) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < array.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(array[i]);
        }
        pw.println();
        pw.flush();
    }

    static int lowerBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] < value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] <= value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

import java.util.*;

public class Main {

    static int N;
    static long M;
    static long V;
    static long P;
    static Integer[] A;

    public static boolean isOK(int index) {
        long max = (long)A[index]+M;
        long tmp = (long)(P-1)+(long)(N-index)-(long)V;

        // System.out.println("index, max, tmp: "+index+" "+max+" "+tmp);
        if (tmp>=0) {
            if (max>=A[(int)P-1]) return true;
            else return false;
        } else {
            long sum = 0;

            // if ((P-1)-index>=0) return true;

            for (int i=(int)P-1;i<index;i++) {
                sum += A[i];
            }
            // System.out.println(max*(index-(P-1))-(sum-tmp*M));
            if ((sum-tmp*M) <= max*(index-(P-1))) return true;
            else return false;
        }
    }

    public static int binary_search() {
        int right = -1;
        int left = A.length;

        while (Math.abs(right - left) > 1) {
            int mid = left + (right - left) / 2;

            if (isOK(mid)) right = mid;
            else left = mid;
        }
        return right;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = Integer.parseInt(sc.next());
        M = Integer.parseInt(sc.next());
        V = Integer.parseInt(sc.next());
        P = Integer.parseInt(sc.next());
        A = new Integer[N];
        for (int i=0;i<N;i++) {
            A[i] = Integer.parseInt(sc.next());
        }
        Arrays.sort(A, (o1, o2)->Integer.compare(o2, o1));
        // System.out.println(Arrays.toString(A));
        System.out.println(binary_search()+1);
    }
}

import java.util.*;
public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt(), M = sc.nextInt(), V = sc.nextInt(), P = sc.nextInt();
		int A[] = new int[N];
		for(int i = 0;i<N;i++) A[i]=sc.nextInt();
		sc.close();
		rsort(A);

		long l = P-1;
		long r = N-1;
		while(l+1<r) {
			long c = (l+r)/2;
			int tar = (int)c;
			int now = A[tar];
			long line = (long)now + M;
			//A[P-1]~A[tar - 1]をline以下にできるか
			long needPlus = ((long)V-(P-1)-((long)(N-1)-tar + 1))*M;
			long sum = 0;
			for(int i=P-1;i<tar;i++) {
				sum += A[i];
			}
			long max = Math.max(A[P-1], ((long)sum+needPlus+tar-(P-1)-1)/((long)tar-(P-1)));
			if(line>=max) l=c;
			else r=c;
		}

		System.out.println(l+1);
	}
	static void rsort(int arr[]) {
		Arrays.sort(arr);
		int len = arr.length;
		for(int i=0;i<len/2;i++) {
			int tmp = arr[i];
			arr[i]=arr[len-1-i];
			arr[len-1-i]=tmp;
		}
	}
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, v, p;
  final long m;
  final long[] as;

  Solver(int n, long m, int v, int p, long[] as) {
    this.n = n;
    this.m = m;
    this.v = v;
    this.p = p;
    this.as = as;
  }

  public int solve() {
    Arrays.sort(as);
    TreeMap<Long, Integer> map = new TreeMap<>();
    for (int i = n - p; i >= 0; i--) {
      map.put(as[i], map.getOrDefault(as[i], 0) + 1);
    }
    int negativeV = n - v;
    long aMax = as[n - p];
    long aSum = 0;
    int aCount = 0;
    for (Map.Entry<Long, Integer> entry : map.descendingMap().entrySet()) {
      long a = entry.getKey();
      int count = entry.getValue();
      if (aSum - a * aCount > negativeV * m || aMax - a > m) {
        break;
      }
      aSum += a * count;
      aCount += count;
    }
    return p - 1 + aCount;
  }
}

