            aTotal += A[i];
        }

        if(N - P - 1 == 0){
            System.out.println(P + (A[1] <= A[0] + M ? 1 : 0));
        }
        long result = 0;
        for(int i = 0; i < N - P; i++){
            long totalTmp = aTotal - A[i];
            if(A[N - P] <= A[i] + M){
                long tmp1 = (totalTmp + (V - 1 - (P - 1)) * M);
                long tmp2 = tmp1 / (N - P - 1);
                if(tmp2 * (N - P - 1) < tmp1){
                    tmp2++;
                }
                if(tmp2 <= A[i] + M){
                    result++;
                }
            }
        }
        System.out.println(result + P);

    }
}

