        long Slv()
        {
            var n = ScanInt;
            var m = Scan;
            var v = Scan;
            var p = Scan;
            var a = ScanLongs(n).OrderByDescending(x => x).ToArray();
            var b = new List<long>();

            if (n == p)
                return n;

            var res = 0L;
            var bs = a[p - 1];
            var memo = 0L;

            foreach (var i in Loop(n))
            {
                b.Add(0);

                if (i < p)
                {
                    b[i] = 0;
                }
                else
                {
                    b[i] = memo;
                    memo += bs - a[i];
                }
            }

            foreach (var i in Loop(n))
            {

                if (i < p)
                {
                    res++;
                    continue;
                }

                var rem = m * (v - (p - 1) - (n - i));
                var cap = (a[i] + m - bs) * (n - (p - 1) - (n - i)) + b[i];

                //Console.WriteLine($"{i} {rem} {cap}");

                if (cap >= rem)
                    res++;
            }

            return res;
        }

        public IEnumerable<string> Solve()
        {




            var res = Slv();
            yield return res.ToString();
        }
    }
