class Program
{
    static void Main(string[] args)
    {
        // 入力
        string[] input = Console.ReadLine().Split(' ');
        var n = long.Parse(input[0]); //問題数
        var m = long.Parse(input[1]); //ジャッジ数
        var v = long.Parse(input[2]); //投票数
        var p = long.Parse(input[3]); //選ばれる問題数

        string[] problem = Console.ReadLine().Split(' ');
        long[] score = new long[n];
        for (int i = 0; i < n; i++)
        {
            score[i] = long.Parse(problem[i]);
        }

        //配列を降順でソート
        Array.Sort(score);
        long ans = -1;
        long mv = m*v;
        for (int i = 0; i < n; i++)
        {
            long number = 0;

            for (int j = 0; j < n; j++)
            {
                if (j<=i)
                {
                    number += m;
                }
                else if (j>n-p)
                {
                    number += m;
                }
                else
                {
                    number += score[i]+m-score[j];
                }
            }

            if (number >= mv)
            {
                //Console.WriteLine(number);
                IEnumerable<long> tmp = score.Where( value => value>=score[i] );
                ans = tmp.Count();
                break;
            }

        }

        //出力
        Console.WriteLine(ans);
    }
