public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long M = GetLong();
		long V = GetLong();
		long P = GetLong();
		long[] A = GetLongs((int)N);
		Array.Sort(A);
		Array.Reverse(A);

		long ng = N;
		long ok = P - 1;
		while(Abs(ok - ng) > 1)
		{
			long mid = (ng + ok) / 2;
			if(A[mid] + M < A[P - 1])
			{
				ng = mid;
				continue;
			}

			long sum = (P - 1 + N - mid) * M;
			for(long i = P - 1; i < mid; i++)
				sum += Max(0, A[mid] + M - A[i]);

			if(sum >= M * V)
				ok = mid;
			else
				ng = mid;
		}
		WriteLine(ok + 1);
	}
}

