using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private long N, M, V, P;
    private long[] A;
    private long[] sum;
    private int index;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        V = sc.NextInt();
        P = sc.NextInt();
        A = sc.LongArray();
        Array.Sort(A, (x, y) => -x.CompareTo(y));
        index = Array.IndexOf(A, A[P - 1]);

        sum = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            if (A[i] < A[P - 1])
            {
                sum[i + 1] = sum[i] + A[P - 1] - A[i];
            }
        }

        long ok = 0;
        long ng = N;
        while (ng - ok > 1)
        {
            long med = (ok + ng) / 2;
            if (C(med))
            {
                ok = med;
            }
            else
            {
                ng = med;
            }
        }

        Console.WriteLine(ng);
    }

    bool C(long i)
    {
        if (A[i] >= A[P - 1]) return true;
        long n = index + N - i;

        long cnt = i - index;

        long nn = V - n;

        if (nn <= 0)
        {
            return A[i] + M >= A[P - 1];
        }
        else
        {
            long s = nn * M;
            s -= sum[i];

            long m = (s + cnt - 1) / cnt;

            return A[i] + M >= A[P - 1] + m;
        }
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

