        /// <summary>
        /// 二分探索のテンプレ
        /// IsOKがtrueとなる最も小さいインデックスを返す
        /// 返り値がA.Lengthなら全ての要素でfalseだったということ
        /// </summary>
        public int BinarySearch(int[] A)
        {
            int ng = -1;       // 「index = 0」 が条件を満たすこともあるので初期値は -1
            int ok = A.Length; // 「index = A.Length - 1」」が条件を満たさないこともあるので、初期値は A.Length

            while (Math.Abs(ok - ng) > 1)
            {
                int mid = (ng + ok) / 2;

                if (IsOk(mid, A))
                {
                    ok = mid;
                }
                else
                {
                    ng = mid;
                }
            }

            return ok;
        }

        public bool IsOk(int index, int[] A)
        {
            const int Threshold = 10;

            if (A[index] >= Threshold)
            {
                return true;
            }
            else
            {
                return false;
            }
        }

        public bool Check(int i)
        {
            if (TargetIndex <= i)
            {
                return true;
            }

            if (V <= i + 1)
            {
                long diff = TargetValue - A[i];
                return diff <= M;
            }

            long self = A[i];

            // ここ、ループ回さなくできる

            long sum    = 0;
            long maxNum = 0;
            for (int j = i + 1; j < N; j++)
            {
                long tmpVal = A[j] - self;
                sum    += tmpVal;
                maxNum =  Math.Max(maxNum, tmpVal);
            }

            long num = N - V;

            long canDelete = num * M;

            if (canDelete < sum)
            {
                return false;
            }

            if (M < maxNum)
            {
                return false;
            }

            return true;
        }
    }


