using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

static class Program
{
    static bool Ok(int N, int M, int V, int P, int[] A, int j)
    {
        if (A[j] + M < A[P - 1]) { return false; }
        long sum = Math.BigMul(M, P - 1);
        for (int i = P - 1; i < N; ++i)
        {
            sum += (i == j) ? M : Math.Min(A[j] + M - A[i], M);
        }
        return sum >= Math.BigMul(M, V);
    }

    static int Solve(int N, int M, int V, int P, int[] A)
    {
        if (Ok(N, M, V, P, A, N - 1)) { return N; }
        int ok = P - 1;
        int ng = N - 1;
        while (ng - ok >= 2)
        {
            int i = (ok + ng) / 2;
            if (Ok(N, M, V, P, A, i)) { ok = i; } else { ng = i; }
        }
        return ng;
    }

    static void Main(string[] args)
    {
        var V = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        var A = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Array.Sort(A, (a, b) => b.CompareTo(a));
        Console.WriteLine(Solve(V[0], V[1], V[2], V[3], A));
    }
}

