        private int  N;
        private long M;
        private int  V;
        private int  P;

        private long[] A;

        public void Solve()
        {
            N = cin.ReadInt;
            M = cin.ReadLong;
            V = cin.ReadInt;
            P = cin.ReadInt;

            A = cin.ReadLongArray(N);

            Array.Sort(A);

            int left  = -1;
            int right = N - 1;

            while (right - left > 1)
            {
                int mid = left + (right - left) / 2;

                if (IsOk(mid))
                {
                    right = mid;
                }
                else
                {
                    left = mid;
                }
            }

            cou.WriteLine(N - right);
        }

        public bool IsOk(int i)
        {
            long rem = Math.Max((V - (i + 1) - (P - 1)) * M, 0);

            int rc = Math.Max(N - (i + 1) - (P - 1), 0);

            long s   = A[i] + M;
            long sum = 0;

            bool f = true;

            for (int j = 0; j < rc; j++)
            {
                int k = i + 1 + j;

                if (k < N)
                {
                    if (A[k] > s) f = false;

                    sum += Math.Min(Math.Max(s - A[k], 0), M);
                }
            }

            if (f && sum >= rem)
            {
                return true;
            }

            return false;
        }
    }

