class MainClass : Scanner
{
    static void Main()
    {
        var (N, M, V, P) = ReadTuple<int,long,int,int>();
        var A = RLongs();
        Array.Sort(A);
        Array.Reverse(A);
        P--;
        int U = N - V;
        var D = new long[N];
        for (int i = 0; i < N-1; i++)
        {
            if (i < P) continue;
            D[i + 1] = D[i] + (A[i] - A[i + 1]) * (i+1-P);
        }

        int ans = 0;

        for (int i = 0; i < N; i++)
        {
            if (i + 1 <= P) { ans++;continue; }
            if (A[P] - A[i] > M) break;
            if (D[i] > Min(i + 1 - P, U) * M) break;

            ans++;
        }
        WriteLine(ans);
    }
}



