public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long M = GetLong();
		long V = GetLong();
		long P = GetLong();
		long[] A = GetLongs((int)N);

		Array.Sort(A);
		Array.Reverse(A);

		var lst = new LazySegmentTree((int)N);
		int last = Array.FindLastIndex(A, x => x == A[P - 1]);
		lst.RangeUpdate(0, last + 1, 1);

		for(int i = 0; i < P; i++)
		{
			long grp = A[i];
			long grpCnt = 1;
			while(i + 1 < N && A[i + 1] == grp)
			{
				i++;
				grpCnt++;
			}
			if(grpCnt + V > N)
				continue;

			long min = Min(grp, A[P - 1] + M);
			int r = right(A, P, M, min);
			lst.RangeUpdate((int)P - 1, Min((int)(P + grpCnt + 1), r + 1), 1);			
		}

		WriteLine(lst.Query(0, (int)N));
	}

	private int right(long[] A, long P, long M, long min)
	{
		int ng = A.Length;
		int ok = (int)P - 1;
		while(Abs(ng - ok) > 1)
		{
			int mid = (ng + ok) / 2;
			if(A[mid] + M >= min)
				ok = mid;
			else
				ng = mid;
		}
		return ok;
	}
}

public class LazySegmentTree
{
	private int N;
	private long[] dat;
	private long[] lazy;
	private bool[] isLazy;

	public LazySegmentTree(int n)
	{
		N = 1;		
		while(N < n)
			N <<= 1;

		dat = new long[2 * N - 1];
		for(int i = 0; i < 2 * N - 1; i++)
			dat[i] = 0;

		lazy = new long[2 * N - 1];
		isLazy = new bool[2 * N - 1];
	}

	private void eval(int k, int l, int r)
	{
		if(!isLazy[k])
			return;

		dat[k] = lazy[k];

		// propagate to children
		if(r - l > 1)
		{
			lazy[2 * k + 1] = lazy[k] / 2;
			lazy[2 * k + 2] = lazy[k] / 2;
			isLazy[2 * k + 1] = true;
			isLazy[2 * k + 2] = true;
		}

		isLazy[k] = false;
	}

	public void RangeUpdate(int a, int b, long x, int k = 0, int l = 0, int r = -1)
	{
		if(r == -1)
			r = N;

		// evaluate propagation from parent
		eval(k, l, r);

		if(b <= l || r <= a)
			return;

		if(a <= l && r <= b)
		{
			// update
			lazy[k] = (long)(r - l) * x;
			isLazy[k] = true;
			eval(k, l, r);
		}
		else
		{
			RangeUpdate(a, b, x, 2 * k + 1, l, (l + r) / 2);
			RangeUpdate(a, b, x, 2 * k + 2, (l + r) / 2, r);
			dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
		}
	}

	public long Query(int a, int b, int k = 0, int l = 0, int r = -1)
	{
		if(r == -1)
			r = N;

		if(r <= a || b <= l)
			return 0;

		eval(k, l, r);

		if(a <= l && r <= b)
			return dat[k];
		else
		{
			long vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
			long vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
			return vl + vr;
		}
	}
}

