class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, m, v, p;
        sc.Multi(out n, out m, out v, out p);
        var a = sc.LongArr;
        Array.Sort(a);
        int ng = -1, ok = n - 1;
        while (ok - ng > 1) {
            int i = (ok + ng) / 2;
            long rem = Math.Max((v - (i + 1) - (p - 1)) * (long)m, 0);
            int rc = Math.Max(n - (i + 1) - (p - 1), 0);
            long s = a[i] + m;
            long sum = 0;
            bool f = true;
            for (int j = 0; j < rc; j++)
            {
                int k = i + 1 + j;
                if (k < n) {
                    if (a[k] > s) f = false;

                    sum += Math.Min(Math.Max(s - a[k], 0), m);
                }
            }
            if (f && sum >= rem) {
                ok = i;
            }
            else {
                ng = i;
            }
        }
        Prt(n - ok);
    }
}

