	class Program
	{
		static void Main(string[] args)
		{
			var inputs = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToList();
			var number = inputs[0];
			var judgeMan = inputs[1];
			var scoreUpNumber = inputs[2];
			var selectNumber = inputs[3];
			// 降順に並び替え
			var array = Console.ReadLine().Split(' ').Select(x=> int.Parse(x)).OrderByDescending(x => x).ToList();

			var sourceSeparator = array[selectNumber];
			var lastSelectSourceIndex = array.FindLastIndex(x => x == sourceSeparator);
			var firstDropIndex = array.FindIndex(x => x + judgeMan < sourceSeparator);
			// 検索対象は lastSelectSourceIndex + 1 から firstDropIndex - 1 まで

			// 問答無用で lastSelectSourceIndex + 1 個は入る。
			var result = lastSelectSourceIndex + 1;

			// separatorが変わらない場合
			var separatorCount = array.Count(x => x == sourceSeparator);
			if(number - scoreUpNumber >= separatorCount)
			{
				Console.WriteLine(firstDropIndex);
			}
			else
			{
				// separator の値はどうなる？
				var separatorIndex = array.FindLastIndex(x => x > sourceSeparator);
				separatorCount += array.Count(x => x == separatorIndex);
				while(number - scoreUpNumber >= separatorCount)
				{
					separatorIndex = array.FindLastIndex(x => x > separatorIndex);
					separatorCount += array.Count(x => x == separatorIndex);
				}
				Console.WriteLine(array.FindIndex(x => x + judgeMan < array[separatorIndex]));
			}
		}
	}
