            if (n_buyable_voters >= V)
            {
                //上からP番目のやつと勝負
                long rival = A[N - P];
                long targetscore_addedVote = targetscore + M;
                if (targetscore_addedVote >= rival)
                {
                    ok = target;
                }
                else
                {
                    ng = target;
                }
            }
            else
            {
                //だめー。だとおもったが
                //そんなことなかった

                long n_candidates = 0;
                long sum_candidates = 0;
                for (long i = target+1; i <= N-P ; i++)
                {
                    while (A[i] == A[i + 1]) i++;
                    n_candidates++;
                    sum_candidates += A[i];
                }
                long uncontrollable_votes = (V - n_buyable_voters) * M;
                sum_candidates += uncontrollable_votes;
                long targetscore_addedVote = targetscore + M;
                long realenemy = (sum_candidates % n_candidates == 0) ? (sum_candidates / n_candidates) : (sum_candidates / n_candidates + 1);//(long)Math.Ceiling(sum_candidates*1.0 / n_candidates);
                if (targetscore_addedVote >= realenemy)
                {
                    ok = target;
                }
                else
                {
                    ng = target;
                }
            }


        }

        Console.WriteLine(N - ok);
    }


