    class Solver
    {
        public Solver()
        {
            Input input = new Input();
            input.Longs(ref N, ref M, ref V, ref P);
            A = input.ArrayLong();
        }

        private long N;
        private long M;
        private long V;
        private long P;
        private long[] A;
        private long minScore;

        public void Solve()
        {
            Array.Sort(A);
            Array.Reverse(A);

            //P番目のスコアと同じスコアになれば採用される
            minScore = A[P - 1];
            long pOver = 0;
            for (int i = 0; i < N; i++)
            {
                if (A[i] > minScore)
                {
                    pOver++;
                }
            }
            // 投票可能問題数が採用予定問題数以上のとき、ボーダースコアよりスコアが低い問題に投票させないと
            // 採用させることができない
            long voteByJudge = V - pOver;

            Console.WriteLine(Search(voteByJudge) + 1);
        }

        /// <summary>
        /// 二分探索
        /// </summary>
        /// <returns>条件を満たす最小の値</returns>
        long Search(long voteByJudge)
        {
            // だめ
            long ng = N;
            // 採用可能性あり
            long ok = -1;

            while (Math.Abs(ok - ng) > 1)
            {
                long mid = (ok + ng) / 2;
                if (isOk(mid, voteByJudge)) ok = mid;
                else ng = mid;
            }

            return ok;
        }

        bool isOk(long index, long voteByJudge)
        {
            // 採用可能
            if (A[index] >= minScore)
            {
                return true;
            }

            // どう足しても足りない
            if (A[index] + M < minScore)
            {
                return false;
            }

            // 投票可能問題が採用予定問題より小さいなら、
            // 採用確定問題にだけ投票すれば最低点を超えられる
            // 任意の問題を採用できる
            if (voteByJudge <= 0)
            {
                return true;
            }

            long rest = 0;
            long max = A[index] + M;
            for (int i = 0; i < N; i++)
            {
                if (A[i] > minScore)
                {
                    rest += M;
                    continue;
                }

                if (index == i)
                {
                    rest += M;
                    continue;
                }

                rest += Math.Min(max - A[i], M);
            }

            return rest >= M * V;
        }
    }
