    public partial class Program
    {
        public const string SiteName    = "AtCoder";
        public const string ContestName = "agc041";
        public const string ProblemName = "B";

        private int   NOrig;
        private int   M;
        private int   VOrig;
        private int   POrig;
        private int[] AOrig;

        private int   N;
        private int   V;
        private int[] A;

        private const int P = 1;

        private int TargetIndex;
        private int TargetValue;

        public void Solve()
        {
            NOrig = cin.ReadInt;
            M     = cin.ReadInt;
            VOrig = cin.ReadInt;
            POrig = cin.ReadInt;
            AOrig = cin.ReadIntArray(NOrig);

            Array.Sort(AOrig);

            N = NOrig - POrig + 1;
            V = VOrig - POrig + 1;

            A = new int[N];

            for (int i = 0; i < N; i++)
            {
                A[i] = AOrig[i];
            }

            TargetIndex = N - P;
            TargetValue = A[TargetIndex];

            // まず、最初に外した分を入れておく
            long ans = POrig - 1;

            int left  = 0;
            int right = N;

            while (right - left > 1)
            {
                int mid = left + (right - left) / 2;

                if (!Check(mid))
                {
                    left = mid;
                }
                else
                {
                    right = mid;
                }
            }

            ans += (N - left - 1);

            cou.WriteLine(ans);
        }

        public bool Check(int i)
        {
            if (TargetIndex <= i)
            {
                return true;
            }

            // if (V <= i + 1)
            // {
            //     int diff = TargetValue - A[i];
            //     return diff <= M;
            // }

            int self = A[i];

            // ここ、ループ回さなくできる

            long sum    = 0;
            int  maxNum = 0;
            for (int j = i + 1; j < N; j++)
            {
                int tmpVal = A[j] - self;
                sum    += tmpVal;
                maxNum =  Math.Max(maxNum, tmpVal);
            }

            int num = N - V;

            long canDelete = num * M;

            if (canDelete < sum)
            {
                return false;
            }

            if (M < maxNum)
            {
                return false;
            }

            return true;
        }
    }


