                {
                    AddedM[N - i - 1] += M;
                }
                var yojou = 0L;
                for (var i = N - processV - 1; i >= P - 1; i--)
                {
                    yojou += pivot - AddedM[i];
                }
                var cnt = N - processV - (P - 1);
