        Array.Sort(A);

        Dictionary<int, problemState> dict = new Dictionary<int, problemState>();
        for (int i = 0; i < N; i++)
        {
            int nowscore = A[i];
            if (dict.ContainsKey(nowscore))
            {
                dict[nowscore].friends++;
            }
            else
            {
                dict[nowscore] = new problemState();
                dict[nowscore].friends = 1;
                dict[nowscore].score = nowscore;
                dict[nowscore].lessers = i;
            }

        }

        int ok = N;
        int ng = -1;
        while (ok - ng > 1)
        {
            int target = (ok + ng) / 2;
            int targetscore = A[target];
            long n_buyable_voters = 1 + dict[targetscore].lessers + dict[targetscore].friends - 1 + P - 1;
            if (n_buyable_voters >= V)
            {
                //上からP番目のやつと勝負
                int rival = A[N - P];
                int targetscore_addedVote = targetscore + M;
                if (targetscore_addedVote >= rival)
                {
                    ok = target;
                }
                else
                {
                    ng = target;
                }
            }
            else
            {
                //だめー。だとおもったが
                //そんなことなかった

                long n_candidates = 0;
                long sum_candidates = 0;
                for (int i = target+1; i <= N-P ; i++)
                {
                    n_candidates++;
                    sum_candidates += A[i];
                }
                long uncontrollable_votes = (V - n_buyable_voters) * M;
                sum_candidates += uncontrollable_votes;
                int targetscore_addedVote = targetscore + M;
                long realenemy = (long)Math.Ceiling(sum_candidates*1.0 / n_candidates);
                if (targetscore_addedVote >= realenemy)
                {
                    ok = target;
                }
                else
                {
                    ng = target;
                }
            }


        }

        Console.WriteLine(N - ok);
    }


}

