class Solver
{
    Scanner sc = new Scanner();
    //
    int N;long M, V, P;
    int[] A;
    public void Solve()
    {
        sc.Make(out N, out M, out V, out P);
        A = sc.ArrInt;
        Array.Sort(A);
        var r = N; var l = -1;
        while (r - l > 1)
        {
            var m = (r + l) / 2;
            if (m >= (N - P)) { r = m;continue; }
            var rest = (V - P) * M;
            var max = A[m] + M;
            if (max < A[N - P]) { l = m;continue; }
            var sum = 0L;
            for (var i = 0; i < N - P+1; i++)
                if (i != m)
                    sum += Min(M,max - A[i]);
            if (rest <= sum) r = m;
            else l = m;
        }
        WriteLine(N - r);
    }
}

