using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		int N = int.Parse(str[0]);
		int M = int.Parse(str[1]);
		int V = int.Parse(str[2]);
		int P = int.Parse(str[3]);
		int[]A = new int[N];
		string[] str2 = Console.ReadLine().Split();
		for(var i=0;i<N;i++){
			A[i] = int.Parse(str2[i]);
		}
		Array.Sort(A,(x,y)=>y-x);
		var dic = new Dictionary<int,int>();
		for(var i=0;i<N;i++){
			if(!dic.ContainsKey(A[i])){
				dic[A[i]] = i;
			}
		}
		long[]S = new long[N];
		long sum = 0;
		for(var i=N-1;i>=0;i--){
			sum += A[i];
			S[i] = sum;
		}
		int min = P;
		int max = N;
		while(min<max){
			int m = (min+max)/2;
          	//Console.Error.WriteLine(min+" "+max+" "+m+" "+A[m]);
			long a = A[m]+M;
			int min2 = 0;
			int max2 = m;
			while(min2<max2){
				int m2 = (min2+max2)/2;
				if(A[m2]>a){
					min2 = m2+1;
				} else {
					max2 = m2;
				}
			}
			//Console.Error.WriteLine(min2);
			int m1 = min2;
			m1 = Math.Max(P-1,m1);
			long ct = a * (m-m1) - (S[m1] - S[m]);
			//Console.Error.WriteLine(m+" "+m1+" "+ct);
			ct += (long)Math.Min(V,(N-m)+(P-1))*M;
			//Console.Error.WriteLine(ct);
			if(ct >= (long)M * V && a >= A[P-1]){
				min = m+1;
			} else {
				max = m;
			}
		}
		Console.WriteLine(min);
	}
}

