class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;

    void calc()
    {
        int N = cin.nextInt();
        int M = cin.nextInt();
        int V = cin.nextInt();
        int P = cin.nextInt();
        long[] A = cin.ArrayLong(N);

        Array.Sort(A);

        int ok = N - 1; // ok can win
        int ng = -1; // ng can't win
        while(Math.Abs(ng - ok) > 1)
        {
            int mid = (ok + ng) / 2;
            if (check(A, N, M, V, P, mid)) ok = mid;
            else ng = mid;
        }
        Console.WriteLine(N - ok);
    }

    bool check(long[] A, int N, int M, int V, int P, int t)
    {
        int target = N - P;

        long sum = 0;

        long add = V - P;
        if (add < 0) add = 0;
        long need = add * M;

        for (int a = 0; a < target; a++)
        {
            int i = a;
            if (i >= t) i++;
            long diff = (A[t] + M) - A[i];
            //Console.WriteLine(t + " " + i + " " + diff);
            if (diff < 0) return false;
            sum += Math.Min(M, diff);
        }

        return sum >= need;
    }

}


