class XRand
{
    uint x, y, z, w;


    public XRand()
    {
        init();
    }

    public XRand(uint s)
    {
        init();
        init_xor128(s);
    }

    void init()
    {
        x = 314159265; y = 358979323; z = 846264338; w = 327950288;

    }

    public void init_xor128(uint s)
    {
        z ^= s;
        z ^= z >> 21; z ^= z << 35; z ^= z >> 4;
        z *= 736338717;
    }

    uint next()
    {
        uint t = x ^ x << 11; x = y; y = z; z = w; return w = w ^ w >> 19 ^ t ^ t >> 8;
    }

    public long nextLong(long m)
    {
        return (long)((((ulong)next() << 32) + next()) % (ulong)m);
    }

    public int nextInt(int m)
    {
        return (int)(next() % m);
    }

    public int nextIntP(int a)
    {
        return (int)Math.Pow(a, nextDouble());
    }

    public int nextInt(int min, int max)
    {
        return min + nextInt(max - min + 1);
    }


    public double nextDouble()
    {
        return (double)next() / uint.MaxValue;
    }

    public double nextDoubleP(double a)
    {
        return Math.Pow(a, nextDouble());
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
	static void Main(string[] args)
	{
		// 入力
		string[] input = Console.ReadLine().Split(' ');
		var n = long.Parse(input[0]); //問題数
        var m = long.Parse(input[1]); //ジャッジ数
		var v = long.Parse(input[2]); //投票数
        var p = long.Parse(input[3]); //選ばれる問題数

        string[] problem = Console.ReadLine().Split(' ');
        long[] score = new long[n];
        for (int i = 0; i < n; i++)
        {
            score[i] = long.Parse(problem[i]);
        }

        //配列を降順でソート
        Array.Sort(score);

        bool ok = false;
        long ans = -1;
        for (int i = 0; i < n; i++)
        {
            long[] tmp = new long[n];
            for (int j = 0; j <n; j++)
            {
                tmp[j] = score[j];
            }


            tmp[i] = tmp[i] + m ;
            int tmp2 = 0;
            for (int j = i+1; j < n; j++)
            {
                tmp2++;
                if (v-tmp2>0)
                {
                    tmp[j] = tmp[j] + m;
                }
                else
                {
                    break;
                }

            }

            IEnumerable<long> count = tmp.Where( value => value>tmp[i] );
            if (p > count.Count())
            {
                ok = true;
            }

            if (ok)
            {
                IEnumerable<long> number = score.Where( value => value>=score[i] );
                ans = number.Count();
                break;
            }

        }
        //出力
        Console.WriteLine(ans);
	}
}

