    class B
    {
        static void Main()
        {
            string[] lineRecord = Console.ReadLine().Trim().Split(' ');
            string[] scoreRecord = Console.ReadLine().Trim().Split(' ');

            var N = long.Parse(lineRecord[0]);
            var M = long.Parse(lineRecord[1]);
            var V = long.Parse(lineRecord[2]);
            var P = long.Parse(lineRecord[3]);

            var answer = CalcImpossible(N, M, V, P, scoreRecord);
            Console.WriteLine(answer);
        }

        private static long CalcImpossible(long N, long M, long V, long P, string[] scoreRecord)
        {
            long count = 0;

            var scoreList = new List<long>();
            long minQuestion = 0;
            foreach (var item in scoreRecord)
            {
                if (scoreList.Count < N - P && (minQuestion == 0 || long.Parse(item) < minQuestion))
                {
                    scoreList.Add(long.Parse(item));
                }
                else if(scoreList.Count < N - P && long.Parse(item) >= minQuestion)
                {
                    continue;
                }
                else
                {
                    minQuestion = scoreList.Max();
                    scoreList.Remove(minQuestion);

                    if(long.Parse(item) < minQuestion) scoreList.Add(long.Parse(item));
                }
            }

            if (N - V < scoreList.Count())
            {
                minQuestion += N - V;
            }
            return N - scoreList.Count(x => x < minQuestion - M);
        }
    }
