    class Solver
    {
        public Solver()
        {
            Input input = new Input();
            input.Longs(ref N, ref M, ref V, ref P);
            A = input.ArrayLong();
        }

        private long N;
        private long M;
        private long V;
        private long P;
        private long[] A;

        public void Solve()
        {
            Array.Sort(A);
            Array.Reverse(A);

            long ans = 0;
            //P番目のスコアと同じスコアになれば採用される
            long minScore = A[P - 1];
            long POver = 0;
            for (int i = 0; i < N; i++)
            {
                if (A[i] > minScore)
                {
                    POver++;
                }
            }
            // 投票可能問題数が採用予定問題数以上のとき、ボーダースコアよりスコアが低い問題に投票させないと
            // 採用させることができない
            long voteByJudge = V - POver;

            long restForBorder = 0;
            for (long i = P - 1; i < N; i++)
            {
                restForBorder += minScore - A[i];
            }

            // P番目までに入っている問題については採用されているので、それ以降について考える
            for (long i = 0; i < N; i++)
            {
                //ボーダー超え
                if (A[i] >= minScore)
                {
                    ans++;
                    continue;
                }

                // どうやっても足りない
                if (A[i] + M < minScore)
                {
                    break;
                }

                // 投票可能問題が採用予定問題より小さいなら、採用確定問題にだけ投票すれば最低点を超えられる
                // 任意の問題を採用できる
                if (V < P)
                {
                    ans++;
                    continue;
                }

                // ボーダーまでの残り点数回、受け入れられれば十分
                long rest = minScore - A[i];
                if (rest * voteByJudge <= restForBorder - rest)
                {
                    ans++;
                }
            }

            Console.WriteLine(ans);
        }
    }
}

