using System;

namespace AGC041
{
    class Program
    {
        private static int Solve(int n, int m, int v, int p, int[] a)
        {
            if (Validate(0, n, m, v, p, a)) return n;
            int mn = 0;
            int mx = n - p + 1;
            while (mn < mx - 1)
            {
                int i = (mn + mx) / 2;
                if (Validate(i, n, m, v, p, a)) mx = i;
                else mn = i;
            }
            return n - mx;
        }

        private static bool Validate(int i, int n, int m, int v, int p, int[] a)
        {
            if (a[i] + m < a[n - p]) return false;
            int sum = i > 0 ? i * m : 0;
            for (int j = i + 1; j < n - p + 1; ++j)
            {
                sum += Math.Max(0, a[i] + m - a[j]);
            }
            sum += (p - 1) * m;
            return sum >= m * (v - 1);
        }

        static void Main(string[] args)
        {
            var line = Console.ReadLine().Split(' ');
            var n = Convert.ToInt32(line[0]);
            var m = Convert.ToInt32(line[1]);
            var v = Convert.ToInt32(line[2]);
            var p = Convert.ToInt32(line[3]);
            var a = Array.ConvertAll(Console.ReadLine().Split(' '), Convert.ToInt32);
            Array.Sort(a);
            Console.WriteLine(Solve(n, m, v, p, a));
        }
    }
}

