        for (int i = 0; i < n; i++)
        {
            score[i] = long.Parse(problem[i]);
        }

        //配列を降順でソート
        Array.Sort(score);
        int ans = -1;
        int mv = m*v;
        for (int i = 0; i < n; i++)
        {
            long number = 0;

            for (int j = 0; j < n; j++)
            {
                if (j<=i)
                {
                    number += m;
                }
                else if (j>n-p)
                {
                    number += m;
                }
                else
                {
                    number += score[i]+m-score[j];
                }
            }

            if (number >= mv)
            {
                //Console.WriteLine(number);
                IEnumerable<long> tmp4 = score.Where( value => value>=score[i] );
                ans = tmp4.Count();
                break;
            }

        }

        //出力
        Console.WriteLine(ans);
    }
