using System;
using System.Linq;

public class Program
{
    private int N, M, V, P;
    private int[] A;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        V = sc.NextInt();
        P = sc.NextInt();
        A = sc.IntArray();
        Array.Sort(A, (a, b) => -a.CompareTo(b));
        /*
         * target強がP未満
         */
        int ok = 0;
        int ng = N;
        while (ng - ok > 1)
        {
            int med = (ok + ng) / 2;

            if (C(med))
            {
                ok = med;
            }
            else
            {
                ng = med;
            }
        }

        Console.WriteLine(ng);
    }

    bool C(int n)
    {
        int[] cp = A.ToArray();
        long tmp = (long) M * V;
        int[] t = new int[N];
        for (int i = 0; i < N; i++)
        {
            t[i] = M;
        }

        int target = A[n] + M;
        cp[n] += M;
        tmp -= M;
        t[n] -= M;

        for (int i = N - 1; i >= 0; i--)
        {
            if (cp[i] < target)
            {
                int d = Math.Min(M, target - cp[i]);
                t[i] -= d;
                cp[i] += d;
                tmp -= d;
            }
        }
        // 全部 target 以上

        int[] index = new int[N];
        for (int i = 0; i < N; i++)
        {
            index[i] = i;
        }

        Array.Sort(index, (a, b) => -t[a].CompareTo(t[b]));

        for (int i = 0; i < N && tmp > 0; i++)
        {
            int d = Math.Min(M, t[index[i]]);
            cp[index[i]] += d;
            t[index[i]] -= d;
            tmp -= d;
        }

        if (tmp > 0) return false;

        int cnt = 0;
        foreach (int i in cp)
        {
            if (i > target) cnt++;
        }

        return cnt < P;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
