using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    private long N, M, V, P;
    private long[] A;
    private long[] sum;
    private int index;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        V = sc.NextInt();
        P = sc.NextInt();
        A = sc.LongArray();
        Array.Sort(A, (x, y) => -x.CompareTo(y));
        index = Array.IndexOf(A, A[P - 1]);

        sum = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            if (A[i] < A[P - 1])
            {
                sum[i + 1] = sum[i] + A[P - 1] - A[i];
            }
        }

        long ok = 0;
        long ng = N;
        while (ng - ok > 1)
        {
            long med = (ok + ng) / 2;
            if (C(med))
            {
                ok = med;
            }
            else
            {
                ng = med;
            }
        }

        Console.WriteLine(ng);
    }

    bool C(long i)
    {
        if (A[i] >= A[P - 1]) return true;

        for (int c = index; c <= P - 1; c++)
        {
            long n = c + N - i;
            long cnt = i - c;
            long nn = V - n;
            if (nn <= 0)
            {
                if (A[i] + M >= A[P - 1])
                    return true;
            }
            else
            {
                long s = nn * M;
                s -= sum[i];

                long m = (s + cnt - 1) / cnt;

                if (A[i] + M >= A[P - 1] + m)
                {
                    return true;
                }
            }
        }

        return false;
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

