internal partial class Solver {
    public void Run() {
        var n = ni();
        var m = ni();
        var v = ni();
        var p = ni();
        var a = nl(n);

        Array.Sort(a);
        Array.Reverse(a);

        int lower = 0, upper = a.Length - 1;
        int val = -1;

        while (lower <= upper) {
            var mid = (lower + upper) / 2;
            // mid は採用されうるかどうかを判定
            var lastMidPoint = a[mid] + m;
            long maxAddNum = 1L * v * m - m;

            var after = a.ToArray();
            after[mid] += m;

            for (int i = n - 1; i >= 0; i--) {
                if (mid == i) continue;
                long remain = Math.Min(lastMidPoint - a[i], maxAddNum);
                if (remain > 0) {
                    var added = Math.Min(m, remain);
                    after[i] += added;
                    maxAddNum -= added;
                }
                if (maxAddNum == 0) break;
            }

            if (maxAddNum > 0) {
                for (int i = 0; i < n; i++) {
                    if (mid == i) continue;
                    var added = after[i] - a[i];
                    if (added < m) {
                        after[i] += m - added;
                        maxAddNum -= m - added;
                    }
                    if (maxAddNum <= 0) break;
                }
            }


            bool ok = false;

            if (maxAddNum <= 0) {
                int bigger = 0;
                for (int i = 0; i < n; i++) {
                    if (i != mid && after[mid] < after[i]) {
                        bigger++;
                    }
                }
                if (bigger <= p - 1) ok = true;
            }

            //after.Dump();
            //new { mid, maxAddNum, ok }.Dump();

            if (ok) {
                val = mid;
                lower = mid + 1;
            } else {
                upper = mid - 1;
            }
        }

        int ans = a.Where(x => x >= a[val]).Count();

        cout.WriteLine(ans);
    }
}

