        private int   NOrig;
        private long  M;
        private int   VOrig;
        private int   POrig;
        private int[] AOrig;

        private int    N;
        private long   V;
        private long[] A;

        private const int P = 1;

        private int  TargetIndex;
        private long TargetValue;

        public void Solve()
        {
            NOrig = cin.ReadInt;
            M     = cin.ReadLong;
            VOrig = cin.ReadInt;
            POrig = cin.ReadInt;
            AOrig = cin.ReadIntArray(NOrig);

            Array.Sort(AOrig);

            N = NOrig - POrig + 1;
            V = VOrig - POrig + 1;

            A = new long[N];

            for (int i = 0; i < N; i++)
            {
                A[i] = AOrig[i];
            }

            TargetIndex = N - P;
            TargetValue = A[TargetIndex];

            int ok = -1;
            int ng = N;

            // まず、最初に外した分を入れておく
            long ans = POrig - 1;

            while (ng - ok > 1)
            {
                int mid = ok + (ng - ok) / 2;

                if (!Check(mid))
                {
                    ok = mid;
                }
                else
                {
                    ng = mid;
                }
            }

            ans += (N - ok - 1);

            cou.WriteLine(ans);
        }

        public bool Check(int i)
        {
            if (TargetIndex <= i)
            {
                return true;
            }

            if (V <= i + 1)
            {
                long diff = TargetValue - A[i];
                return diff <= M;
            }

            long self = A[i];

            // ここ、ループ回さなくできる

            long sum    = 0;
            long maxNum = 0;
            for (int j = i + 1; j < N; j++)
            {
                long tmpVal = A[j] - self;
                sum    += tmpVal;
                maxNum =  Math.Max(maxNum, tmpVal);
            }

            long num = N - V;

            long canDelete = num * M;

            if (canDelete < sum)
            {
                return false;
            }

            if (M < maxNum)
            {
                return false;
            }

            return true;
        }
    }


