package main

import (
  "bufio"
  "os"
  "strconv"
  "strings"
  "fmt"
  "sort"
)

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func Max(a, b int) int {
  if a < b { return b }
  return a
}

func main() {
  NMVP := NextIntVec()
  N, M, V, P := NMVP[0], NMVP[1], NMVP[2], NMVP[3]
  A := NextIntVec()
  sort.Sort(sort.Reverse(sort.IntSlice(A)))
  T := A[P - 1]
  buf := 0
  cnt := P
  _V := Max(V - P, 0)
  for i, a := range A {
    if i < P { continue }
    if a + M < T { break }
    v := _V - (N - i - 1)
    if M * v <= buf + (i - P + 1) * (a + M - T) { cnt++ }
    buf += T - a
  }
  Write(cnt)
  Output()
}

