// Sort
type Val struct {
	id, num int
}
type ByNum []Val

func (a ByNum) Len() int           { return len(a) }
func (a ByNum) Less(i, j int) bool { return a[i].num < a[j].num }
func (a ByNum) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	N, M, V, P := sc.nextInt(), sc.nextInt(), sc.nextInt(), sc.nextInt()
	A := sc.nextIntSlice(N)
	sort.Sort(sort.Reverse(sort.IntSlice(A)))
	S := make([]int, N+1)
	S[0] = 0
	for i, a := range A {
		S[i+1] = S[i] + a
	}
	ans := 0
	for i := 1; i <= N; i++ {
		if search(A, A[i-1]) < P {
			ans++
			continue
		}
		changed := A[i-1] + M
		bigCount := search(A, changed)
		k := N - i + 1
		if !(bigCount < P) {
			continue
		}
		diff := (i-P+1)*M - (S[i] - S[P])
		if (P-1)*M+diff+k*M >= V*M {
			ans++
		}
	}

	fmt.Fprintln(wtr, ans)
	wtr.Flush()
}

// Aのなかでnより大きい要素数
func search(A []int, n int) int {
	ng := -1
	ok := len(A)
	for abs(ok-ng) > 1 {
		mid := (ok + ng) / 2
		if A[mid] <= n {
			ok = mid
		} else {
			ng = mid
		}
	}
	return ok
}

