func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	N, M, V, P := sc.nextInt(), sc.nextInt(), sc.nextInt(), sc.nextInt()
	A := sc.nextIntSlice(N)
	sort.Sort(sort.Reverse(sort.IntSlice(A)))
	S := make([]int, N+1)
	S[0] = 0
	for i, a := range A {
		S[i+1] = S[i] + a
	}
	ans := 0
	//fmt.Println(A)
	//fmt.Println(S)
	for i := 1; i <= N; i++ {
		if search(A, A[i-1]) <= P-1 {
			ans++
			continue
		}
		changed := A[i-1] + M
		bigCount := search(A, changed)
		k := N - i + 1
		if !(bigCount <= P-1) {
			continue
		}
		diff := (i-P)*changed - (S[i-1] - S[P-1])
		//fmt.Println(i-1, P-1)
		//fmt.Println("i: %d, n: %d, changed: %d, diff: %d, S: %d", i, A[i-1], changed, diff, S[i-1]-S[P-1])
		if (P-1)*M+diff+k*M >= V*M {
			ans++
		}
	}

	fmt.Fprintln(wtr, ans)
	wtr.Flush()
}

// Aのなかでnより大きい要素数
func search(A []int, n int) int {
	ng := -1
	ok := len(A)
	for abs(ok-ng) > 1 {
		mid := (ok + ng) / 2
		if A[mid] <= n {
			ok = mid
		} else {
			ng = mid
		}
	}
	return ok
}

