func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	v := getNextInt(scanner)
	p := getNextInt(scanner)
	aa := make([]int, n)
	ss := make([]int64, n+1)

	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	sort.Ints(aa)
	for i := 0; i < n; i++ {
		ss[i+1] = ss[i] + int64(aa[i])
	}

	ans := p
	var horobiyo int64
	for i := 0; i < n-p; i++ {
		// m*vだけ増える
		horobiyo = int64(m) * int64(v)
		// 自分以下
		horobiyo -= int64(i+1) * int64(m)
		// P番目より大きい
		horobiyo -= int64(p-1) * int64(m)
		// i+1番目～n-p番目はaa[i]+mまで加算できる
		horobiyo -= int64(aa[i]+m)*int64(n-p-i) - (ss[n-p+1] - ss[i+1])
		if horobiyo <= 0 {
			ans++
			continue
		}
	}

	fmt.Fprintln(writer, ans)
}

