)

func main() {
	var n, m, v, p int
	fmt.Scan(&n, &m, &v, &p)
	as := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&as[i])
	}
	sort.Sort(sort.Reverse(sort.IntSlice(as)))

	ok, ng := 0, n
	for ng-ok > 1 {
		mid := (ok + ng) / 2
		if check(as, mid, m, v, p) {
			ok = mid
		} else {
			ng = mid
		}
	}
	fmt.Println(ok + 1)
}

func check(as []int, x, m, v, p int) bool {
	if x <= p-1 {
		return true
	}
	if as[x]+m < as[p-1] {
		return false
	}

	point := m * v
	for i := 0; i < len(as); i++ {
		if i < p-1 || x <= i {
			point -= m
		}
	}
	if point <= 0 {
		return true
	}

	xv := as[x] + m
	for i := p - 1; i < x; i++ {
		if as[i] < xv {
			point -= xv - as[i]
		}
	}
	if point <= 0 {
		return true
	}

	return false
}

