func check(as []int, x, m, v, p int) bool {
	xv := as[x] + m
	if as[p-1] > xv {
		return false
	}

	pp := 0
	for i := 0; i < len(as); i++ {
		if i < p-1 || x <= i {
			pp += m
		} else {
			if as[i] < xv {
				pp += xv - as[i]
			}
		}
	}

	return m*v <= pp
}

