func main() {
	stdin := bufio.NewScanner(os.Stdin)
	stdin.Scan()
	in0 := stdin.Text()
	stdin.Scan()
	in1 := stdin.Text()
	out, _ := do(in0, in1)
	fmt.Println(out)
}

func do(in0, in1 string) (string, error) {
	s0 := strings.Split(in0, " ")
	N, _ := strconv.Atoi(s0[0])
	M, _ := strconv.Atoi(s0[1])
	V, _ := strconv.Atoi(s0[2])
	P, _ := strconv.Atoi(s0[3])

	s1 := strings.Split(in1, " ")
	var A = make([]int, 0, len(s1))
	for _, s := range s1 {
		num, _ := strconv.Atoi(s)
		A = append(A, 64)
	}

	sort.Slice(A, func(i, j int) bool { return A[i] < A[j] })

	if A[V-1] < A[N-P-1] {
		for i := 0; i < N; i++ {
			if A[i]+M < A[N-P-1] {
				continue
			}
			return strconv.Itoa(N - i), nil
		}
		return strconv.Itoa(N), nil
	}
	for i := 0; i < N; i++ {
		if A[i]+M >= A[V] {
			return strconv.Itoa(i), nil
		}
	}
	return "", errors.New("error")
}

