func main() {
	defer Flush()

	N := readi()
	M := readll()
	V := readi()
	P := readi()
	A := make([]int64, N)
	for i := range A {
		A[i] = readll()
	}

	Sort(A, func(i, j int) bool { return A[i] > A[j] })
	B := A[P-1:]
	V -= P - 1
	C := append([]int64{}, B...)
	for i, j := 0, len(C)-1; i < V && 0 <= j; i, j = i+1, j-1 {
		C[j] += M
	}
	maxi := len(C) - 1
	for B[maxi]+M < B[0] {
		maxi--
	}
	//eprintln("A", A)
	//eprintln("B", B)
	//eprintln("C", C)

	i := 1
	sum := C[0]
	for ; i <= maxi; i++ {
		//eprintln(i, sum)
		if B[i] == B[0] || B[i] == C[i] {
			sum += C[i]
			continue
		}
		if (sum / int64(i)) < C[i] {
			sum += C[i]
			continue
		}
		break
	}
	println(P - 1 + i)
}

