			panic(fmt.Sprintf("getInt(%d)", n))
		}
	}()
	return n
}

func pow(x, y, mod int) (ans int) {

	ans = 1
	for bit := 1 << uint(math.Floor(math.Log2(float64(y)))); ; bit >>= 1 {
		if y&bit != 0 {
			ans *= x
			if mod > 0 {
				ans %= mod
			}
		}
		if bit <= 1 {
			return
		}
		ans *= ans
		if mod > 0 {
			ans %= mod
		}
	}
}

type factType struct {
	prime int
	count int
}

func fact(n int) (facts []*factType) {

	for i := 2; i*i <= n; i++ {
		if n%i == 0 {
			fa := factType{prime: i}
			for n%fa.prime == 0 {
				n /= fa.prime
				fa.count++
			}
			facts = append(facts, &fa)
		}
	}
	if n > 1 {
		facts = append(facts, &factType{prime: n, count: 1})
	}
	return facts
}
func dec2bin(n int) (ret []bool) {
	for bit := 1 << uint(math.Floor(math.Log2(float64(n)))); ; bit >>= 1 {
		ret = append(ret, n&bit != 0)

		if bit <= 1 {
			return
		}
	}

}

func abs(v int) int {
	if v < 0 {
		v = -v
	}
	return v
}

func b2i(b bool) (i int) {
	if b {
		i = 1
	} else {
		i = 0
	}
	return
}

func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	_, m, v, p := r.nextInt(), r.nextInt(), r.nextInt(), r.nextInt()
	r.Scan(true)
	a := r.nextStringArray().toInts()
	sort.Sort(sort.Reverse(sort.IntSlice(a)))

	v -= p - 1
	if v < 1 {
		v = 1
	}

	mv := m * v
	b := a[p-1:]
	ev := func(s int) bool {
		ret := 0
		for i := 0; i < len(b); i++ {
			bv := b[i] + m
			if bv > s {
				bv = s
			}
			ret += bv - b[i]
		}
		return ret >= mv
	}

	lim := b[0]
	{
		minV := 0
		maxV := b[0] + m
		for minV < maxV {
			cenV := (minV + maxV) / 2
			if ev(cenV) {
				maxV = cenV
			} else {
				minV = cenV + 1
			}
		}
		if lim < minV {
			lim = minV
		}
	}

	ans := p - 1
	for i := len(b) - 1; i >= 0; i-- {
		if b[i]+m >= lim {
			ans++
		}
	}

	fmt.Fprintln(stdout, ans)
}

