			rest++
			a[n-rest] += m

			sort.Sort(sort.Reverse(sort.IntSlice(a)))
			for i := p; i < n; i++ {
				if a[p-1] != a[i] {
					if ans < i {
						ans = i
					}
					break
				}
			}
		}

	} else {
		for i := n - rest; i >= v; i-- {
			if a[i]+m >= a[p-1] {
				ans = i
				break
			}
		}
	}

	fmt.Fprintln(stdout, ans)
}

