func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	n, m, v, p := r.nextInt(), r.nextInt(), r.nextInt(), r.nextInt()
	r.Scan(true)
	a := r.nextStringArray().toInts()
	sort.Sort(sort.Reverse(sort.IntSlice(a)))

	rep := 0
	if v <= p {
		rep = v - 1
	} else {
		rep = p - 1
	}
	rest := v - rep

	for i := 0; i < rest; i++ {
		a[n-1-i] += m
	}
	ans := p

	if a[n-rest] >= a[p-1] {
		ans = n - rest + 1

		if p-2 >= 0 {
			for i := n - rest + 2; i < n; i++ {
				if a[i] >= a[p-2] {
					ans++
				}
			}
		}

	} else {
		for i := n - rest; i >= v; i-- {
			if a[i]+m >= a[p-1] {
				ans = i
				break
			}
		}
	}

	fmt.Fprintln(stdout, ans)
}

Scanf.scanf "%d %d %d %d" (fun n m v p ->
    let a = Array.init n (fun _ -> Scanf.scanf " %d" (fun a -> a)) in
    Array.sort (fun a b -> compare b a) a;

    let judge x =
        if a.(x) + m < a.(p - 1) then false else
            let s = n - 1 - x + 1 + p - 1 in
            if s >= v then true else
                let rec loop k sum =
                    if k = x then sum else loop (k + 1) (sum + a.(x) + m - a.(k))
                in
                loop p (m * s) >= m * v
    in

    let rec bin left right =
        if left = right then left else
            let mid = (left + right) / 2 in
            if judge mid then bin (mid + 1) right
                         else bin left mid
    in
    bin p n |> Printf.printf "%d\n"
)

