            if s >= v then true else
                let rec loop k sum =
                    if k = x then sum else loop (k + 1) (sum + a.(x) + m - a.(k))
                in
                loop (p - 1) (m * s) >= m * v
    in

    let rec bin left right =
        if left = right then left else
            let mid = left + (right - left) / 2 in
            if judge mid then bin (mid + 1) right
                         else bin left mid
    in
    Printf.printf "%d\n" @@ bin p n
)

Scanf.scanf "%d %d %d %d" (fun n m v p ->
    let a = Array.init n (fun _ -> Scanf.scanf " %d" (fun a -> a)) in
    Array.sort (fun a b -> compare b a) a;

    let border = a.(p - 1) in

    let bordersum =
        let rec loop i acc =
            if i = n then acc else
                loop (i + 1) (acc + border - a.(i))
        in
        loop p 0
    in

    let rec loop i acc =
        if i = n then acc else
            if a.(i) + m < border then acc else
                let nb = bordersum - (border - a.(i)) in
                if nb + (a.(i) + m - border) * (n - p) <= (v - p) * m then acc
                else loop (i + 1) (acc + 1)
    in
    loop p p |> Printf.printf "%d\n"
)

