    bool check(long i) {
        auto a = as[i] + M;
        if (as[P-1] > a) return false;

        auto x = (V - P + 1 - N + i) * M;
        if (x <= 0) return a >= as[P-1];

        foreach (j; P-1..i) {
            x -= min(M, a - as[j]);
            if (x <= 0) break;
        }

        return x <= 0;
    }

    if (check(N-1)) {
        writeln(N);
        return;
    }

    long l = P-1, r = N-1;
    while (l+1 < r) {
        auto m = (l+r)/2;
        if (check(m)) {
            l = m;
        } else {
            r = m;
        }
    }
    writeln(r);
}

