void main() {
  long N, M, V, P;
  scanln(N, M, V, P);
  long[] as = readln.split.to!(long[]).sort!"a>b".array;

  bool f(long c) {
    long[] bs = as[0..c] ~ as[c+1..$];
    long i = -1;
    {
      long x = as[c] + M;
      foreach(j; 0..N-1) {
        if (x >= bs[j]) {
          i = j;
          break;
        }
      }
      if (i < 0) {
        i = N-1;
      }
      bs = bs[0..i] ~ x ~ bs[i..$];
    }

    if (i >= P) {
      return false;
    }

    long T = N-i-1;

    long[] xs = new long[T];
    foreach(j; 0..T) {
      xs[j] = bs[i] - bs[i+j+1];
      if (j < P-1-i) {
        xs[j] = M;
      }
      assert(xs[j] >= 0);
    }

    xs ~= M.repeat(min(P-1, i)).array;
    xs.sort!"a>b";

    long v = 0;
    long j = 0;
    foreach(k, x; xs) {

      if (x >= M) {
        v++;
      } else {
        long y = x%M;
        if (j+y < M) {
          j += y;
        } else {
          j = y - (M-j);
          v++;
        }
      }
    }
    return v >= V-1;
  }

  long l = 0;
  long r = N;
  while(r-l > 1) {
    long c = (l + r)/2;
    if (f(c)) {
      l = c;
    } else {
      r = c;
    }
  }
  writeln(l + 1);
}



