void main(string[] args) {
  long N, M, V, P;
  readf(" %d %d %d %d ", &N, &M, &V, &P);

  const A = readln.split.map!(to!long).array.sort!"a < b".array;
  auto Ar = A.array.assumeSorted!"a < b";

  auto sp = new long[](N);
  foreach (i; 1..N) {
    sp[i] = sp[i-1];
    if (A[i] != A[i-1]) {
      sp[i] += (A[i]-A[i-1])*i;
    }
  }

  long ans;

  auto spr = sp.assumeSorted;
  foreach (i, a; A) {
    const long leftcap = M*i;
    const long rempt   = M*(V-1) - leftcap;
    if (rempt <= 0) {
      if (Ar.upperBound(a+M).count() < P) {
        ans = N - i;
        break;
      }
      continue;
    } else if (i+1 < N) {
      const long r = N - Ar.upperBound(a+M-1).count();
      if (r == N) {
        ans = N - i;
        break;
      }
      const long rcap     = sp[r] - sp[i+1] - (A[r]-a)*(i+1);
      const long remrempt = rempt - rcap;

      if (Ar.upperBound(a+M).count() < P) {
        if (remrempt > 0) {
          long splitcnt = remrempt/M;
          if (splitcnt*M != remrempt) ++splitcnt;
          if (splitcnt < P) {
            ans = N - i;
            break;
          }
        } else {
          ans = N - i;
          break;
        }
      }
    }
  }
  ans.writeln;
}

