    A.sort(reverse = True)

    used_vote = (P-1)*M
    res = M*V-used_vote

    # res を振り分けていく
    a = A[P-1:]
    r = a[0]
    l = 0
    while r - l > 1:
        mid = (r+l)//2
        goal = mid+M
        if a[0] > goal:
            l = mid
            continue

        need= 0 
