def judge(x):
    if N-P<=x<=N-1:
        return True

    cnt = 0

    for i in range(N-P+1):
        if i==x:
            continue

        cnt += min(M, A[x]+M-A[i])

    return cnt>=M*(V-P)

def binary_search():
    l, r = 0, N-1

    while l<=r:
        m = (l+r)//2

        if judge(m):
            r = m-1
        else:
            l = m+1

    return l

