def f(A, M, V, P, m):
    N = len(A)
    a = A[m]
    i = bisect.bisect_right(A, a + M)
    C = N - i

    if C >= P:
        return False

    C = P - 1
    i = N - C

    U = 0
    for j in range(i):
        if j == m:
            continue
        U += min(a + M - A[j], M)

    return U >= (V - 1 - C) * M


