class mmm:
	def __init__(self):
		self.n, self.m, self.v ,self.p = map(int, input().split())
		self.al=list(map(int, input().split()))
		self.al.sort(reverse=True)
		r=0
		m=self.al[0]
		self.diffl=[0]*self.n
		for i,v in enumerate(self.al):
			r+=m-v
			self.diffl[i]=r
		self.border=self.al[self.p-1]

		pa(self.diffl)
		pa(self.al)

	def is_ok(self,ni):
		if ni <= self.p-1:
			return True
		vv=self.al[ni]
		if vv + self.m < self.border:
			return False

		nv=self.v-((self.p-1)+(self.n-ni-1))
		if nv < 0:
			return True

		ss=nv*self.m
		di=self.diffl[ni]-self.diffl[self.p-1]

		div=self.al[0]-self.border
		din=di-(div*(ni))
		pa((ni,di,din))
		if din > ss:
			return True
		return False


	def solve(self):
		ok=0
		if self.is_ok(self.n-1):
			return self.n
		ng=self.n-1

		while ng-ok>=2:
			mm=(ng+ok)//2
			if self.is_ok(mm):
				ok=mm
			else:
				ng=mm
			#print(ok,ng,mm)
		return ok+1


