		self.border=self.al[self.p-1]

		pa(self.diffl)
		pa(self.al)

	def is_ok(self,ni):
		if ni <= self.p-1:
			return True
		vv=self.al[ni]
		if vv + self.m < self.border:
			return False

		nv=self.v-((self.p-1)+(self.n-ni))
		if nv <= 0:
			return True

		ss=nv*self.m
		di=self.diffl[ni-1]-self.diffl[self.p-1]

		div=self.al[0]-self.border
		din=di-(div*(ni-1-(self.p-1)))+(vv+self.m-self.border)*(ni-1-(self.p-1))
		pa((ni,di,din,div,ss,nv))

		if din > ss:
			return True
		return False


	def solve(self):
		ok=0
