# 選ばれる可能性のある最低点を求める
# 選びかた　・目標のやつには審査員だけ入れてやる
#          ・上よりP-1番目以下のやつらも入れられるだけ入れてやる
# 　　　　　・残りの奴らにはなでるように入れてやる
#          ・これでP番目以上になるやつがあったらご愁傷さま

def vote(x):
    if x >= n - p:
        return True
    elif x == -1:
        return False
    else:
        total_vote = m * (v-1)
        b_list = a_list[::]
        b_list[x] += m

        if b_list[x] < b_list[n-p]:
            return False

        for i in range(p-1):
            a = min(total_vote, m)
            b_list[-i-1] += a
            total_vote -= a
            if total_vote == 0:
                break

        for i in range(n-p+1):
            if i != x and b_list[x] > b_list[i]:
                a = min(total_vote, m, b_list[x] - b_list[i])
                b_list[i] += a
                total_vote -= a
                if total_vote == 0:
                    break

        if total_vote == 0:
            return True
        else:
            return False

