    N, M, V, P = map(int, rl().split())
    A = list(map(int, rl().split()))

    A.sort()

    def check(t):
        cnt = (t + 1) * M
        for idx in range(t + 1, N - P + 1):
            cnt += M - (A[idx] - A[t])
        cnt += (P - 1) * M
        return M * V <= cnt

    ok, ng = N - 1, -1
    while 1 < ok - ng:
        mid = (ok + ng) // 2
        if check(mid):
            ok = mid
        else:
            ng = mid
    print(N - ok)


