def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


class Bisect:
    def __init__(self, func):
        self.__func = func

    def bisect_left(self, x, lo, hi):
        while lo < hi:
            mid = (lo+hi)//2
            if self.__func(mid) < x:
                lo = mid+1
            else:
                hi = mid
        return lo

    def bisect_right(self, x, lo, hi):
        while lo < hi:
            mid = (lo+hi)//2
            if x < self.__func(mid):
                hi = mid
            else:
                lo = mid+1
        return lo

@mt
def slv(N, M, V, P, A):
    A.sort(reverse=True)
    def f(i):
        if i < P:
            return 0

        if V - P <= 0:
            if A[i] + M >= A[P-1]:
                return 0
            else:
                return 1
        else:
            am = A[i] + M
            r = V - P
            B = []
            for j in range(P-1, N):
                if j != i:
                    B.append(A[j])
                j += 1
            heapq.heapify(B)
            C = []
            rm = M * r
            while B:
                b = heapq.heappop(B)
                d  = am - b
                if d > 0:
                    if d > M:
                        d = M
                    if d <= rm:
                        rm -= d
                        C.append(b+d)
                    else:
                        C.append(b+rm)
                        rm = 0
                else:
                    C.append(b)
            return 0 if max(C) <= am and rm == 0 else 1

    b = Bisect(f)
    i = b.bisect_right(0.5, lo=0, hi=N)
    return i


