def judge(a, i, m, n, v, p):
    if i <= p: return True
    if a[i-1] + m < a[p-1]: return False
    check = (p - 1 + n - i)*m
    for j in range(p, i):
        check += a[i-1] + m - a[j-1] if a[i-1] + m - a[j-1] < m else m
    return check >= m*(v - 1)

