fn main() {
    let (n, m, v, p): (usize, usize, usize, usize);
    input!(n, m, v, p);
    let mut a = input_vector::<usize>();
    a.sort();
    a.reverse();

    let mut ok = 0;
    let mut ng = n;

    while ng - ok > 1 {
        let i = (ng + ok) / 2;
        let mut flag = false;

        let mut sum = 0;
        for j in 0..n {
            if j < p - 1 || i == j {
                sum += m;
            } else if a[i] + m < a[j] {
                break;
            } else {
                sum += std::cmp::min(a[i] + m - a[j], m);
            }

            //println!("s{}", sum);
        }
        //println!("{} {}", i, sum);
        if m * v <= sum {
            flag = true;
        }

        if flag {
            ok = i;
        } else {
            ng = i;
        }
    }
    println!("{}", ok + 1);
}

#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(dead_code)]

fn main() {
    let (N, M, V, P): (usize, i64, i64, usize) = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        let mut iter = line.split_whitespace();
        (
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
        )
    };
    let A: Vec<i64> = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect()
    };

    fn bis<P: Fn(i64) -> bool>(ok: i64, ng: i64, p: P) -> i64 {
        let mid = (ok + ng) / 2;
        if (ok - ng).abs() == 1 {
            ok
        } else if p(mid) {
            bis(mid, ng, p)
        } else {
            bis(ok, mid, p)
        }
    }

    let B = {
        let mut B = A.clone();
        B.sort();
        B.reverse();
        B
    };
    let ans = bis(1, N as i64 + 1, |n| {
        let n = n as usize;
        let x = B[n - 1] + M;
        n <= P
            || B[(P - 1)..(n - 1)].iter().map(|&b| x - b).sum::<i64>()
                >= M * (V - (P + N - n) as i64)
    });

    println!("{}", ans);
}

