use std::collections::BinaryHeap;

type MinHeap<T> = BinaryHeap<Reverse<T>>;

#[derive(Debug)]
pub struct MinHeapWithOffset {
    q: MinHeap<i64>,
    offset: i64,
}

impl MinHeapWithOffset {
    pub fn new() -> MinHeapWithOffset {
        MinHeapWithOffset {
            q: BinaryHeap::new(),
            offset: 0,
        }
    }
    pub fn all_add(&mut self, x: i64) {
        self.offset += x;
    }
    pub fn min(&self) -> i64 {
        self.q.peek().unwrap().0 + self.offset
    }
    pub fn pop(&mut self) -> i64 {
        self.q.pop().unwrap().0 + self.offset
    }
    pub fn push(&mut self, x: i64) {
        self.q.push(Reverse(x - self.offset))
    }
}

fn f(ys: &Vec<(usize, usize)>, n: usize, m: usize, v: usize, p: usize, i: usize) -> bool {
    if i < p {
        return true;
    }
    if i >= n {
        return false;
    }
    if ys[p - 1].0 > ys[i].0 + m {
        return false;
    }
    let mut zs = vec![];
    for k in p - 1..n {
        if k != i {
            zs.push(ys[i].0 + m - ys[k].0);
        }
    }
    zs.reverse();
    if (v - 1) <= (p - 1) {
        return true;
    }
    let w = (v - 1) - (p - 1);
    let mut rem = m as i64;
    let mut q = MinHeapWithOffset::new();
    let mut t = 0;
    for &z in &zs {
        t += min(m, z);
    }
    return t >= w * m;
    if t >= w * m {}
    // eprintln!("zs = {:?}", zs);
    for i in 0..w {
        q.push(zs[i] as i64);
    }
    for i in w..zs.len() {
        // eprintln!("q = {:?}", q);
        if q.min() < 0 {
            return false;
        }
        let top = q.pop();
        q.all_add(top);
        rem -= top as i64;
        if rem <= 0 {
            return true;
        }
        q.push(zs[i] as i64);
    }
    false
}

