fn main() {
    let (n, m, v, p): (usize, usize, usize, usize);
    input!(n, m, v, p);
    let mut a = input_vector::<usize>();
    a.sort();
    a.reverse();

    let mut ok = 0;
    let mut ng = n;

    while ng - ok > 1 {
        let i = (ng + ok) / 2;
        let mut flag = false;

        if i <= p - 1 {
            flag = true;
        } else {
            let mut sum = 0;
            for j in 0..n {
                if j < p - 1 || i <= j {
                    sum += m;
                } else if a[i] + m < a[j] {
                    break;
                } else {
                    sum += std::cmp::min(a[i] + m - a[j], m);
                }

               // println!("s{}", sum);
            }
            //println!("{} {}", i, sum);
            if m * v <= sum {
                flag = true;
            }
        }
        if flag {
            ok = i;
        } else {
            ng = i;
        }
    }
    println!("{}", ok + 1);
}

