        m: usize,
        v: usize,
        p: usize,
        mut a: [usize; n]
    }
    a.sort_by(|x, y| y.cmp(x));
    let mut t = 0;
    let mut f = true;
    for i in p - 1..n {
        if a[i] > a[n - 1] + m {
            f = false;
            break;
        } else {
            t += min(a[n - 1] + m - a[i], m);
        }
    }
    if f && t + (p - 1) * m >= v * m {
        println!("{}", n);
        return;
    }
    let mut l = a[n - 1];
    let mut r = 1000000000;
    while l + 1 < r {
        let mid = (l + r) / 2;
        let mut t = 0;
        let mut f = true;
        for i in p - 1..n {
            if a[i] > mid + m {
                f = false;
                break;
            } else {
                t += min(mid + m - a[i], m);
            }
        }
        if f && t + (p - 1) * m >= v * m {
            r = mid;
        } else {
            l = mid;
        }
    }
    let mut ans = 0;
