struct Solver {}
impl Solver {
    fn solve(&mut self) {
        let stdin = std::io::stdin();
        let mut scn = Scanner {
            stdin: stdin.lock(),
        };
        let n: usize = scn.read();
        let m: usize = scn.read();
        let v: i32 = scn.read();
        let p: usize = scn.read();
        let mut a: Vec<usize> = scn.vec(n);
        a.sort();
        let mut result = 0;
        let mut left = 0;
        let mut right = n;
        for _ in 0..5 {
            let med = (right + left) / 2;
            //eprintln!("{} {} {}", med, left, right);
            if med >= n {
                right = med;
                continue;
            }
            let mut b = a.clone();
            let mut tmp_v = v;
            let x1 = b[med] + m;
            b[med] = x1;
            tmp_v -= 1;
            //b.sort();

            let rank = {
                let mut result = 1;
                //let mut values = HashSet::new();
                for (idx, x) in b.iter().rev().enumerate() {
                    if *x == x1 {
                        result = idx;
                        break;
                    }
                }
                result + 1
            };

            if rank > p {
                left = med;
                continue;
            }

            //eprintln!("{:?}", b);
            //eprintln!("med: {} left: {} right: {} rank: {} {}", med, left, right, rank, a[med]);
            let mut buf = p - rank;

            let mut used = HashSet::new();
            used.insert(med);
            for (idx, x) in b.iter_mut().enumerate().rev() {
                //eprintln!("{} {} {} {}", x, tmp_v, buf, x1);
                //eprintln!("{:?}", used);
                if used.contains(&idx) {
                    continue;
                }
                //eprintln!("x: {}, x1: {}", x, x1);
                if *x > x1 {
                    *x += m;
                    tmp_v -= 1;
                    used.insert(idx);
                } else if *x < x1 {

                    if *x + m > x1 {
                        if buf > 0 {
                            *x += m;
                            buf -= 1;
                            tmp_v -= 1;
                            used.insert(idx);
                        }
                    } else {
                        *x += m;
                        tmp_v -= 1;
                        used.insert(idx);
                    }
                }
            }
            //eprintln!("tmp_v: {}", tmp_v);
            if tmp_v > 0 {
                let mut cnt = m;
                for (idx, x) in b.iter().enumerate() {
                    if used.contains(&idx) {
                        continue;
                    }
                    let mut rest = x1 - *x;
                    if rest >= cnt {
                        let t = cnt;
                        rest -= cnt;
                        tmp_v -= 1;
                        cnt = m - std::cmp::min(m - t, rest);
                    } else {
                        cnt -= rest;
                    }
                }
            }
            //eprintln!("{} {} {} {}", left, right , med, tmp_v);
            if tmp_v <= 0 {
                right = med;
            } else {
                left = med;
            }
        }
        //eprintln!("right: {}", right);
        println!("{}", n - right);
    }
}

