fn run() {
    input! {
        n: usize,
        m: i64,
        v: usize,
        p: usize,
        a: [i64; n],
    }
    let mut a = a;
    a.sort();
    a.reverse();
    let a = a;
    let mut ok = p - 1;
    let mut ng = n;
    while ng - ok > 1 {
        let mid = (ok + ng) / 2;
        if v <= p - 1 + n - mid {
            if a[p - 1] <= a[mid] + m {
                ok = mid;
            } else {
                ng = mid;
            }
        } else {
            let d = v - (p - 1) - (n - mid);
            let mut sum = m * d as i64;
            for i in (p - 1)..mid {
                sum -= a[mid] + m - a[i];
            }
            if sum <= 0 {
                ok = mid;
            } else {
                ng = mid;
            }
        }
    }
    let ans = ng;
    println!("{}", ans);
}

fn main() {
    run();
}

