fn main() {
    let (n, m, v, p) = (u(), u(), u(), u());
    let a = uv(n);

    let mut b = a.clone();
    b.sort();
    b.reverse();
    let border = b[p - 1];
    let mut sum = 0;
    let mut count = 0;

    let mut ans = 0;
    for i in 0..n {
        let k = b[i];
        if k > border {
            ans += 1;
            continue;
        }
        if k + m >= border {
            if p >= v && k >= border {
                ans += 1;
                continue;
            }
            let rest = n - i - 1;
            let t = m * v;
            let cap = p * m + rest * m + count * (k + m) - sum;
            //dbg!(&t, &cap, &count, &(p * v), &(k + m), &sum);
            // println!("");
            if t <= cap {
                ans += 1;
            }

            if border <= k + v {
                sum += k;
                count += 1;
            }
        } else {
            break;
        }
    }
    println!("{}", ans);
    //dbg!(border, b, ans);
