fn main() {
    let v = read_vec::<i64>();
    let (n, m, v, p) = (v[0] as usize, v[1], v[2], v[3]);
    let mut a = read_vec::<i64>();

    a.sort();
    a.reverse();

    let criterion = |x: usize| -> bool {
        let mut used = (p - 1) * m;
        let border = a[x] + m;
        for i in p as usize - 1..n {
            if i == x {
                continue;
            }
            if a[i] > border {
                return false;
            }
            used += min(m, border - a[i]);
        }
        if used >= m * (v as i64 - 1) {
            return true;
        } else {
            return false;
        }
    };
    let (ok, ng) = binary_search(0, n, criterion);
    println!("{}", ok + 1);
}

fn binary_search<F>(lb: usize, ub: usize, criterion: F) -> (usize, usize)
where
    F: Fn(usize) -> bool,
{
    let mut ok = lb;
    let mut ng = ub;
    while ng - ok > 1 {
        let mid = (ng + ok) / 2;
        if criterion(mid) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    (ok, ng)
}

