#[derive(Default)]
//NOTE
//declare variables to reduce the number of parameters for dp and dfs etc.
struct Solver {
    n: usize,
    m: usize,
    v: usize,
    p: usize,
    a: Vec<usize>,
}
impl Solver {
    fn check(&mut self, idx: usize) -> bool {
        let mut bigger: i32 = 0;
        let mut less: i32 = 0;
        let mut other: i32 = 0;
        for (i, x) in self.a.iter().enumerate() {
            if idx != i {
                if self.a[idx] + self.m < self.a[i] {
                    bigger += 1;
                } else if self.a[i] <= self.a[idx] {
                    less += 1;
                } else {
                    other += 1;
                }
            }
        }
        if self.p <= bigger as usize {
            return false;
        }
        let rest = self.v as i32 - 1 - bigger - less;
        if rest <= 0 {
            return true;
        }
        let mut total = 0;
        let mut cnt = 0;
        for (i, x) in self.a.iter().enumerate() {
            if self.a[idx] < self.a[i] && self.a[i] <= self.a[idx] + self.m {
                total += self.a[idx] + self.m - self.a[i];
                cnt += 1;
                let ok =
                    std::cmp::min(rest, std::cmp::min(total as i32 / (self.m as i32), other));
                let ng = rest - ok;
                if bigger + ng < self.p as i32 && cnt + ng <= other {
                    return true;
                }
            }
        }
        false
    }
    fn solve(&mut self) {
        let stdin = std::io::stdin();
        let mut scn = Scanner {
            stdin: stdin.lock(),
        };
        let n: usize = scn.read();
        let m: usize = scn.read();
        let v: usize = scn.read();
        let p: usize = scn.read();
        let mut a: Vec<usize> = scn.vec(n);
        a.sort();
        self.n = n;
        self.m = m;
        self.v = v;
        self.p = p;
        self.a = a;
        let mut left = 0;
        let mut right = n - 1;
        while right - left > 1 {
            let med = (right + left) / 2;
            if self.check(med) {
                right = med;
            } else {
                left = med;
            }
        }
        println!("{}", n - right);
    }
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| {
            let mut solver = Solver::default();
            solver.solve()
        })
        .unwrap()
        .join()
        .unwrap();
}
