fn main() {
    input! {
       n: usize,
       m: usize,
       v: usize,
       p: usize,
       a : [usize;n],
    }

    let mut ans = 0;
    let mut a = a;
    a.sort();
    let mut used = vec![false; n];
    let mut c = a[0];
    let mut d = 0;
    for i in 0..n {
        if d > p {
            if c != a[i] {
                break;
            }
        }
        d += 1;
        c = a[i];
        used[i] = true;
    }

    let b = a[n - v - 1] + m;
    ans += d;
    d = 0;
    c = a[n - v];
    let mut pos = 0;
    for i in (n - v)..n {
        if a[i] > b {
            break;
        }
        if d > p {
            if i + 1 < n && a[i] != a[i + 1] {
                break;
            }
        }

        c = a[i];
        if a[pos] + m <= a[i] {
            for j in pos..n {
                pos = j;
                d += 1;
                if a[j] + m > a[i] {
                    break;
                }
            }
        }
        d += 1;
        used[i] = true;
    }

    ans = 0;
    for i in 0..n {
        if used[i] == true {
            ans += 1;
        }
    }
    println!("{}", ans);
}

