fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n, m, v, p, a: [usize; n]);
    let mut a: Vec<_> = a;
    a.sort();
    a.reverse();
    let thres = a[p - 1];
    let f = |i: usize| {
        let t = a[i] + m;
        if t < thres {
            return false;
        }
        if let Some(res) = (v + i + 1).checked_sub(n + p) {
            let mut res = m * res;
            for j in ((p - 1)..i).rev() {
                let r = t - a[j];
                if r >= res {
                    return true;
                }
                res -= r;
            }
            return false;
        } else {
            true
        }
    };

    let mut l = p - 1;
    let mut r = n;
    while r - l > 1 {
        let m = (l + r) / 2;
        if f(m) {
            l = m;
        } else {
            r = m;
        }
    }
    println!("{}", l + 1);
}

