    }
    let mut ys: Vec<(usize, usize)> = xs.iter().enumerate().map(|(i, &x)| (x, i)).collect();
    ys.sort();
    ys.reverse();
    let mut res = 0;
    for i in (0..20).rev() {
        let t = res + (1 << i);
        // eprintln!("bin_t = {}", t);
        if f(&ys, n, m, v, p, t) {
            res = t;
        }
    }
    res += 1;
    println!("{}", res);
}

