      for i in k + 1..n - (p - 1) {
        let t = cmp::min(1, rest_score);
        a[i] += t;
        rest_score -= t;
      }
      dbg!(a, rest_score);
    }
    let mut b = a.iter().cloned().enumerate().collect::<Vec<_>>();
    b.sort_by_key(|&(_, b_i)| -(b_i as i64));
    let ans = (0..p).any(|i| b[i].0 == k)
      || (p..n)
        .take_while(|&i| b[i] == b[p - 1])
        .any(|i| b[i].0 == k);
    dbg!(k, a, ans);
    ans
  };

  if possible(0) {
    println!("{}", n);
    return;
  }

  let ans = {
    let mut ok = n - p;
    let mut ng = 0;
    while ok - ng > 1 {
      let mid = (ok + ng) / 2;
      dbg!(ok, mid, ng);
      if possible(mid) {
        ok = mid;
      } else {
        ng = mid;
      }
    }
    n - ok
  };
  println!("{}", ans);
}

