    cnt: u64,
    gt: u64,
    lt: u64,
}

fn main() {
    let nmvp: Vec<u64> = read_vec();
    let n = nmvp[0] as usize;
    let m = nmvp[1];
    let v = nmvp[2];
    let p = nmvp[3] as usize;
    let mut a: Vec<u64> = read_vec();
    a.sort_by(|x, y| y.partial_cmp(x).unwrap());

    let border = a[p - 1];

    let mut q = 0;
    for i in 0..n {
        if a[i] == a[p - 1] {
            q = i;
            break;
        }
    }

    let mut d: Vec<Data> = vec![];

    let mut tmp = 0;
    for i in 1..n {
        if a[i - 1] > a[i] {
            d.push(Data {
                val: a[i - 1],
                cnt: i as u64 - tmp,
                gt: tmp,
                lt: n as u64 - i as u64,
            });
            tmp = i as u64;
        }
    }
    d.push(Data {
        val: a[n - 1],
        cnt: n as u64 - tmp,
        gt: tmp,
        lt: 0,
    });

    /*
    println!("q : {}", q);

    for i in 0..d.len() {
        println!("{} {} {} {}", d[i].val, d[i].cnt, d[i].gt, d[i].lt);
    }
    */

    let mut idq = 0;
    for i in 0..d.len() {
        if d[i].val == border {
            idq = i;
            break;
        }
    }

    let mut ans = 0;

    for i in 0..d.len() {
        if d[i].val >= border {
            ans += d[i].cnt;
            continue;
        } else if d[i].val + m < border {
            continue;
        } else if d[i].cnt + d[i].lt + q as u64 >= v {
            ans += d[i].cnt;
            continue;
        }

        let rest = m * (v - d[i].cnt - d[i].lt - q as u64);
        let mut tmp = 0;
        for j in idq..i {
            tmp += (d[i].val + m - d[j].val) * d[j].cnt;
        }
        tmp += (p - 1 - q) as u64;

        if rest <= tmp {
            ans += d[i].cnt;
        } else {
            break;
        }
    }

    println!("{}", ans);
}

use std::cmp::Ordering;

pub trait BinarySearch<T> {
    fn lower_bound(&self, x: &T) -> Option<usize>;
    fn upper_bound(&self, x: &T) -> Option<usize>;
}

impl<T: Ord> BinarySearch<T> for [T] {
    //greater than or equal
    fn lower_bound(&self, x: &T) -> Option<usize> {
        let mut left = 0;
        let mut right = self.len();
        let mut result = None;
        while left < right {
            let med = (left + right) / 2;
            match self[med].cmp(x) {
                Ordering::Less => {
                    left = med + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    result = Some(med);
                    right = med;
                }
            }
        }
        result
    }
    fn upper_bound(&self, x: &T) -> Option<usize> {
        let mut left = 0;
        let mut right = self.len();
        let mut result = None;
        while left < right {
            let med = (left + right) / 2;
            match self[med].cmp(x) {
                Ordering::Equal | Ordering::Less => {
                    left = med + 1;
                }
                Ordering::Greater => {
                    result = Some(med);
                    right = med;
                }
            }
        }
        result
    }
}

