mod tests {
    use super::*;
    use rand::{thread_rng, Rng};
    #[test]
    fn test_binary_search() {
        let vec = vec![-100, 0, 1, 2, 10, 100, 1000];
        assert_eq!(vec.lower_bound(&1), Some(2));
        assert_eq!(vec.lower_bound(&100), Some(5));
        assert_eq!(vec.lower_bound(&-5000), Some(0));
        assert_eq!(vec.lower_bound(&999), Some(6));
        assert_eq!(vec.lower_bound(&1001), None);

        assert_eq!(vec.upper_bound(&-101), Some(0));
        assert_eq!(vec.upper_bound(&0), Some(2));
        assert_eq!(vec.upper_bound(&100), Some(6));
        assert_eq!(vec.upper_bound(&1000), None);
    }

    #[test]
    fn test_random_binary_search() {
        let test_case = 50;
        let max_value = 200;
        let query_num = 100;
        let mut rng = thread_rng();
        for _ in 0..test_case {
            let mut seq: Vec<i32> = (0..500).map(|_| rng.gen_range(0, max_value)).collect();
            seq.sort();

            for _ in 0..query_num {
                let query = rng.gen_range(0, max_value + 100);
                let result = (seq.lower_bound(&query), seq.upper_bound(&query));
                //sequential search
                let naive_search = |x: i32| {
                    let mut lower_result = None;
                    let mut upper_result = None;
                    for i in 0..seq.len() {
                        if lower_result.is_none() && x <= seq[i] {
                            lower_result = Some(i);
                        }
                        if upper_result.is_none() && x < seq[i] {
                            upper_result = Some(i);
                        }
                    }
                    (lower_result, upper_result)
                };

                assert_eq!(result, naive_search(query));
            }
        }
    }
}

use std::collections::*;
#[derive(Default)]
//NOTE
//declare variables to reduce the number of parameters for dp and dfs etc.
struct Solver {
    n: usize,
    m: usize,
    v: usize,
    p: usize,
    a: Vec<usize>,
}
impl Solver {
    fn check(&mut self, idx: usize) -> bool {
        let mut bigger: i32 = 0;
        let mut less: i32 = 0;
        let mut other: i32 = 0;
        for (i, x) in self.a.iter().enumerate() {
            if idx != i {
                if self.a[idx] + self.m < self.a[i] {
                    bigger += 1;
                } else if self.a[i] <= self.a[idx] {
                    less += 1;
                } else {
                    other += 1;
                }
            }
        }
        if self.p <= bigger as usize {
            return false;
        }
        let rest = self.v as i32 - 1 - bigger - less;
        if rest <= 0 {
            return true;
        }
        let mut total = 0;
        let mut cnt = 0;
        for (i, x) in self.a.iter().enumerate() {
            if self.a[idx] < self.a[i] && self.a[i] <= self.a[idx] + self.m {
                total += self.a[idx] + self.m - self.a[i];
                cnt += 1;
                let ok =
                    std::cmp::min(rest, std::cmp::min(total as i32 / (self.m as i32), other));
                let ng = rest - ok;
                if bigger + ng < self.p as i32 && cnt + ng <= other {
                    return true;
                }
            }
        }
        false
    }
    fn solve(&mut self) {
        let stdin = std::io::stdin();
        let mut scn = Scanner {
            stdin: stdin.lock(),
        };
        let n: usize = scn.read();
        let m: usize = scn.read();
        let v: usize = scn.read();
        let p: usize = scn.read();
        let mut a: Vec<usize> = scn.vec(n);
        a.sort();
        self.n = n;
        self.m = m;
        self.v = v;
        self.p = p;
        self.a = a;
        let mut left = -1;
        let mut right = n as i32;
        for _ in 0..100 {
            let med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }
            let med = med as usize;
            if self.check(med) {
                right = med as i32;
            } else {
                left = med as i32;
            }
        }
        println!("{}", n - right as usize);
    }
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| {
            let mut solver = Solver::default();
            solver.solve()
        })
        .unwrap()
        .join()
        .unwrap();
}
