pub fn binary_search_on_array_true_false<F: Fn(usize) -> bool, T>(xs: &[T], f: F) -> usize {
    let m = 30;
    let mut res = (1 << m) - 1;
    for i in (0..m).rev() {
        let t = res - (1 << i);
        if t < xs.len() {
            if !f(t) {
                res = t;
            }
        } else {
            res = t;
        }
    }
    res
}

