fn lower_bound<F>(l: usize, r: usize, criterion: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    l
}

fn solve() {
    let (n,m,v,p) = get!(usize, usize, usize, usize);
    let mut a = get!([usize]);

    a.sort_by(|e1,e2| e2.cmp(&e1));

    let crit = |index: usize| -> bool {
        if v+index+1 < n+p {
            return false;
        }
        let a_i = a[index] + m;
        let mut res = m*(v+index+1-n-p);
        for i in (p-1)..index {
            if a[i] > a_i {
                return true;
            }
            let tmp = a_i-a[i];
            if res <= tmp {
                return false;
            } else {
                res -= tmp;
            }
        }
        res > 0
    };
    let res = lower_bound(p-1, n, crit);
    println!("{}",res+1);
}

