#[fastout()]
fn main() {
    input! {
        n: usize, m: usize, v: usize, p: usize,
        mut a: [usize; n],
    }
    a.sort();
    a.reverse();
    let border = a[p-1];

    let mut ok = p-1;
    let mut ng = n;
    while ng > ok + 1 {
        let mid = (ok + ng) / 2;
        let score = a[mid] + m;
        if score < border {
            ng = mid;
            continue;
        }
        let upper_vote = m * (p - 1);
        let lower_vote = m * (n - mid - 1);
        let middle_vote = a[p-1..mid].iter().map(|&v| score - v).sum::<usize>();
        if m + upper_vote + lower_vote + middle_vote >= m * v {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    println!("{}", ok + 1);
}

