fn lower_bound<F>(l: usize, r: usize, criterion: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    l
}

fn solve() {
    let (n,m,v,p) = get!(usize, usize, usize, usize);
    let mut a = get!([usize]);

    a.sort_by(|e1,e2| e2.cmp(&e1));

    let crit = |index: usize| -> bool {
        if v+index+1 < n+p {
            return false;
        }
        let a_i = a[index] + m;
        let mut res = m*(v+index+1-n-p);
        for i in (p-1)..index {
            if a[i] > a_i {
                return true;
            }
            let mut tmp = a_i-a[i];
            if tmp > m {
                tmp = m;
            }
            if res <= tmp {
                return false;
            }
            res -= tmp;
        }
        res > 0
    };
    let res = lower_bound(p-1, n, crit);
    println!("{}",res+1);
}

use std::cmp::Ordering;

pub trait BinarySearch<T> {
    fn lower_bound(&self, x: &T) -> Option<usize>;
    fn upper_bound(&self, x: &T) -> Option<usize>;
}

impl<T: Ord> BinarySearch<T> for [T] {
    //greater than or equal
    fn lower_bound(&self, x: &T) -> Option<usize> {
        let mut left = 0;
        let mut right = self.len();
        let mut result = None;
        while left < right {
            let med = (left + right) / 2;
            match self[med].cmp(x) {
                Ordering::Less => {
                    left = med + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    result = Some(med);
                    right = med;
                }
            }
        }
        result
    }
    fn upper_bound(&self, x: &T) -> Option<usize> {
        let mut left = 0;
        let mut right = self.len();
        let mut result = None;
        while left < right {
            let med = (left + right) / 2;
            match self[med].cmp(x) {
                Ordering::Equal | Ordering::Less => {
                    left = med + 1;
                }
                Ordering::Greater => {
                    result = Some(med);
                    right = med;
                }
            }
        }
        result
    }
}

