use std::collections::*;
#[derive(Default)]
//NOTE
//declare variables to reduce the number of parameters for dp and dfs etc.
struct Solver {
    n: usize,
    m: usize,
    v: usize,
    p: usize,
    a: Vec<usize>,
}
impl Solver {
    fn check(&mut self, idx: usize) -> bool {
        let mut bigger: i64 = 0;
        let mut less: i64 = 0;
        let mut other: i64 = 0;
        for (i, x) in self.a.iter().enumerate() {
            if idx != i {
                if self.a[idx] + self.m < self.a[i] {
                    bigger += 1;
                } else if self.a[i] <= self.a[idx] {
                    less += 1;
                } else {
                    other += 1;
                }
            }
        }
        if self.p <= bigger as usize {
            return false;
        }
        let rest = self.v as i64 - 1 - bigger - less;
        if rest <= 0 {
            return true;
        }
        let mut total = 0;
        let mut cnt = 0;
        for (i, x) in self.a.iter().enumerate() {
            if self.a[idx] < self.a[i] && self.a[i] <= self.a[idx] + self.m {
                total += self.a[idx] + self.m - self.a[i];
                cnt += 1;
                let ok = std::cmp::min(rest, std::cmp::min(total as i64 / (self.m as i64), other));
                let ng = rest - ok;
                if bigger + ng < self.p as i64 {
                    return true;
                }
            }
        }
        false
    }
    fn solve(&mut self) {
        let stdin = std::io::stdin();
        let mut scn = Scanner {
            stdin: stdin.lock(),
        };
        let n: usize = scn.read();
        let m: usize = scn.read();
        let v: usize = scn.read();
        let p: usize = scn.read();
        let mut a: Vec<usize> = scn.vec(n);
        a.sort();
        self.n = n;
        self.m = m;
        self.v = v;
        self.p = p;
        self.a = a;
        let mut left = -1;
        let mut right = n as i32;
        for _ in 0..100 {
            let med = (right + left) / 2;
            if med < 0 {
                left = med;
                continue;
            }
            if med >= n as i32 {
                right = med;
                continue;
            }
            let med = med as usize;
            if self.check(med) {
                right = med as i32;
            } else {
                left = med as i32;
            }
        }
        println!("{}", n - right as usize);
    }
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| {
            let mut solver = Solver::default();
            solver.solve()
        })
        .unwrap()
        .join()
        .unwrap();
}
