fn read_line() -> String {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    buf
}

fn solve(n: usize, m: usize, v: i64, p: i64, a: &Vec<usize>) -> usize {
    let mut l = (p-1) as usize;
    let mut r = n;
    while r - l > 1 {
        let mid = (l+r)/2;

        let border = a[mid] + m;
        if border >= a[(p-1) as usize] {
            let mut rest = (m as i64) * cmp::max(v - p, 0);
            let mut tmp = (p - 1) as usize;
            while tmp < n && rest > 0 {
                if tmp != mid {
                    rest -= cmp::min(m, border - a[tmp]) as i64;
                }
                tmp += 1;
            }
            if rest > 0 {
                r = mid;
            } else {
                l = mid;
            }
        } else {
            r = mid;
        }
    }
    l + 1
}


