fn main() {
    let (n, m, v, p) = input_tuple();
    let mut p_vec = input_vec();
    p_vec.sort_by(|a, b| b.cmp(&a));
    // println!("{:?}", p_vec);

    let mut scores: Vec<u64> = Vec::new();
    let mut orders: Vec<u64> = Vec::new();
    orders.push(0);
    scores.push(p_vec[0]);
    let mut pre = p_vec[0];
    let mut idx = 0usize;
    for p in p_vec {
        if p != pre {
            idx += 1;
            orders.push(1);
            scores.push(p);
        } else {
            orders[idx] += 1;            
        }
        pre = p;
    }
    // println!("orders = {:?}", orders);
    // println!("scores = {:?}", scores);

    let mut sum = 0;
    let mut count = 0;
    let mut border = 0usize;
    for i in 0..orders.len() {
        count += orders[i];
        if count >= p {
            // println!("border = {}", i);
            // println!("count = {}", count);
            border = i;
            break;
        }
    }

    let mut exclude = orders[border];
    let mut excluded_scores = scores[border] * orders[border];
    for i in (border+1)..orders.len() {
        if scores[border] - scores[i] <= m {
            // println!("i = {}", i);
            // 票を分散させる
            let voted_score = scores[i] + m;
            // println!("voted = {}", voted_score);

            let left_score = voted_score * exclude - excluded_scores;
            // println!("left_score = {}", left_score);

            let mut left_vote = 0;
            if v < n - exclude {
                left_vote = 0;
            } else {
                left_vote = v * m - (n - exclude) * m
            }
            // println!("left_vote = {}", left_vote);
            if left_vote <= left_score {
                count += orders[i];
                exclude += orders[i];
                excluded_scores += scores[i] * orders[i];
            } else {
                break;
            }
        } else {
            break;
        }
    }
    println!("{}", count);
}

