// [l,h) の中でもっとも手前のfalseになる場所を探す. 全てのtrueはfalseより手前にある必要がある.
fn partition_point<F>(l0: usize, h0: usize, f: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut l = l0;
    let mut h = h0;

    while h - l > 0 {
        let m = l + (h - l) / 2;
        if f(m) {
            l = m + 1;
        } else {
            h = m;
        }
    }
    return l;
}





fn is_possible(
    score: i64,
    n: usize,
    m: usize,
    v: usize,
    p: usize,
    a: &Vec<i64>,
    asum: &Vec<i64>,
) -> bool {
    if a[n - p] <= score {
        true
    } else if (score + m as i64) < a[n - p] {
        false
    } else {
        // 点数がscore以下の問題low個全てに、全員が1票を入れる
        // high=n-(p-1)以降の問題全てに、全員が1票を入れる
        // 間のhigh-low個の問題に、スコアがscore+m を超えないように残りの票(v-low-(p-1))*mを振り分けることができるか?
        let low = partition_point(0, n, |i| a[i] <= score);
        let high = n - (p - 1);
        let remain_votes_per_judge = v as i64 - low as i64 - (p - 1) as i64;
        if remain_votes_per_judge <= 0 {
            true
        } else {
            let capacity = (score + m as i64) * ((high - low) as i64) - (asum[high] - asum[low]);
            remain_votes_per_judge * m as i64 <= capacity
        }
    }
}

