    } else if pos as usize >= a.len() {
        return true;
    }

    if a[pos as usize] + m < a[a.len() - p] {
        return false;
    }
    let mut plus = vec![0; a.len()];
    for i in 0..pos + 1 {
        plus[i as usize] = m;
    }
    for i in (a.len() - p + 1)..a.len() {
        if plus[i] != 0 {
            continue;
        }
        plus[i] = m;
    }
    let c = a[pos as usize] + plus[pos as usize];

    for i in (pos as usize + 1)..(a.len() - p + 1) {
        if plus[i] != 0 {
            continue;
        }
        if c < a[i] {
            plus[i] = m;
        } else {
            plus[i] = c - a[i];
        }
    }

    if plus.iter().fold(0, |a, x| a + x) >= m * v {
        return true;
    } else {
        return false;
    }
}

fn main() {
    input! {
       n: usize,
       m:usize,
       v:usize,
       p:usize,
       mut a:[usize;n],
    }

    let mut ans: usize = 0;
    a.sort();

    let mut l = -1 as i32;
    let mut r = (a.len() - 1) as i32;

    while r - l > 1 {
        let mid = (r + l) / 2;
        if ok(mid, &a, m, v, p) {
            r = mid;
        } else {
            l = mid;
        }
    }

    mydbg!(l, r, a.len());
    echo!(a.len() - r as usize);
}

