use std::io;
use std::cmp;
use std::collections::BinaryHeap;
use std::collections::HashMap;
use std::collections::HashSet;
use std::f64::consts::PI;

fn read_line() -> String {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    buf
}

fn solve(n: usize, m: usize, v: i32, p: i32, a: &Vec<usize>) -> usize {
    let mut l = (p-1) as usize;
    let mut r = n;
    while r - l > 1 {
        let mid = (l+r)/2;

        let border = a[mid] + m;
        if border >= a[(p-1) as usize] {
            let mut rest = (m as i32) * cmp::max(v - p, 0);
            let mut tmp = (p - 1) as usize;
            while tmp < n && rest > 0 {
                if tmp != mid {
                    rest -= cmp::min(m, border - a[tmp]) as i32;
                }
                tmp += 1;
            }
            if rest > 0 {
                r = mid;
            } else {
                l = mid;
            }
        } else {
            r = mid;
        }
    }
    l + 1
}


fn main() {
    let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();

    let n = line[0];
    let m = line[1];
    let v = line[2] as i32;
    let p = line[3] as i32;

    let mut a: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    a.sort();
    a.reverse();

    let ans = solve(n, m, v, p, &a);

    println!("{}", ans);
}

