/*
  n = 2, m = 3,
  valid
    2 2 2
    1 1 1 1 1 1
    2 1 1 1 1
  invalid
    6
    3 2 1
*/
pub fn fillable_n_m(xs: &Vec<usize>, n: usize, m: usize) -> bool {
    let mut xs = xs.clone();
    xs.sort();
    let mut t = 0;
    for &x in &xs {
        t += min(n, x);
    }
    t >= n * m
}

fn f(ys: &Vec<(usize, usize)>, n: usize, m: usize, v: usize, p: usize, i: usize) -> bool {
    if i < p {
        return true;
    }
    if i >= n {
        return false;
    }
    if ys[p - 1].0 > ys[i].0 + m {
        return false;
    }
    let mut zs = vec![];
    for k in p - 1..n {
        if k != i {
            zs.push(ys[i].0 + m - ys[k].0);
        }
    }
    zs.reverse();
    if (v - 1) <= (p - 1) {
        return true;
    }
    let w = (v - 1) - (p - 1);
    fillable_n_m(&zs, m, w)
}

fn main() {
    input! {
        n: usize,
        m: usize,
        v: usize,
        p: usize,
        xs: [usize; n],
    }
    let mut ys: Vec<(usize, usize)> = xs.iter().enumerate().map(|(i, &x)| (x, i)).collect();
    ys.sort();
    ys.reverse();
    let mut res = 0;
    for i in (0..20).rev() {
        let t = res + (1 << i);
        // eprintln!("bin_t = {}", t);
        if f(&ys, n, m, v, p, t) {
            res = t;
        }
    }
    res += 1;
    println!("{}", res);
}

