fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let m: usize = sc.read();
    let v: usize = sc.read();
    let p: usize = sc.read();
    let mut a: Vec<usize> = (0..n).map(|_| sc.read()).collect();
    a.sort_by(|a, b| b.cmp(a));

    let border = a[p - 1];
    let ans = if v <= p {
        a.iter().take_while(|&a| a + m >= border).count()
    } else {
        let v = v - p;
        1 + bis_usize(p - 1, n, |i| {
            let ceiling = a[i] + m;
            if ceiling < border {
                return false;
            }
            let mut cnt = m * v;
            for j in p-1..n {
                if j == i || a[j] > ceiling {
                    continue;
                }
                let d = if ceiling - a[j] < m {
                    ceiling - a[j]
                } else {
                    m
                };
                if d >= cnt {
                    return true;
                }
                cnt -= d;
            }
            false
        })
    };

    format!("{}\n", ans)
}

fn bis_usize<P>(t: usize, f: usize, eval: P) -> usize
where
    P: Fn(usize) -> bool,
{
    if t > f {
        if t - f == 1 {
            return t;
        }
    } else if f - t == 1 {
        return t;
    }
    let m = (t + f) >> 1;
    if eval(m) {
        bis_usize(m, f, eval)
    } else {
        bis_usize(t, m, eval)
    }
}

