fn f(ys: &Vec<(usize, usize)>, n: usize, m: usize, v: usize, p: usize, i: usize) -> bool {
    if i < p {
        return true;
    }
    if i >= n {
        return false;
    }
    if ys[p - 1].0 > ys[i].0 + m {
        return false;
    }
    let mut zs = vec![];
    for k in p - 1..n {
        if k != i {
            zs.push(ys[i].0 + m - ys[k].0);
        }
    }
    zs.reverse();
    if (v - 1) <= (p - 1) {
        return true;
    }
    let w = (v - 1) - (p - 1);
    let mut rem = m as i64;
    let mut q = BinaryHeap::new();
    let mut offset = 0;
    // eprintln!("zs = {:?}", zs);
    for i in 0..w {
        q.push(-(zs[i] as i64));
    }
    for i in w..zs.len() {
        // eprintln!("q = {:?}", q);
        if -(*q.peek().unwrap()) < offset {
            return false;
        }
        let top = -q.pop().unwrap() - offset;
        offset += top;
        rem -= top as i64;
        if rem <= 0 {
            return true;
        }
        q.push(-(offset + zs[i] as i64));
    }
    false
}

