fn check(n: usize, m: usize, v: usize, p: usize, a: &[usize], idx: usize) -> bool {
    let border = a[p - 1];
    let my_value = a[idx] + m;
    if my_value < border {
        return false;
    }
    if v <= p {
        return true;
    }
    let r = v - p;
    let mut sum: isize = r as isize * m as isize;
    for i in 0..n {
        if i < p - 1 {
            continue;
        }
        if i == idx {
            continue;
        }
        if a[i] >= my_value {
            continue;
        }
        let u = min(my_value - a[i], m);
        sum -= u as isize;
    }
    sum <= 0
}
fn run() {
    let n: usize = scan();
    let m: usize = scan();
    let v: usize = scan();
    let p: usize = scan();
    let mut a: Vec<usize> = scan_iter().collect();
    a.sort();
    a.reverse();

    let mut lb = 0;
    let mut ub = n;

    while ub - lb > 1 {
        let idx = (lb + ub) / 2;
        if check(n, m, v, p, &a, idx) {
            lb = idx;
        } else {
            ub = idx;
        }
    }
    println!("{}", lb + 1);
}

