fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let m: usize = sc.read();
    let v: usize = sc.read();
    let p: usize = sc.read();
    let mut a: Vec<usize> = (0..n).map(|_| sc.read()).collect();
    a.sort_by(|a,b| b.cmp(a));

    let ans = if v <= p {
        let border = a[p-1];
        a.iter().take_while(|&a| a + m >= border).count()
    } else {
        let v = v - p;
        1 + bis_usize(p-1, n, |i| {
            let ceiling = a[i] + m;
            let mut cnt = m * v;
            let mut f = false;
            for j in p..n {
                if j == i {
                    continue;
                }
                if a[j] > ceiling {
                    break;
                }
                let d = if ceiling - a[j] < m {
                    ceiling - a[j]
                } else {
                    m
                };
                if d >= cnt {
                    f = true;
                    break;
                }
                cnt -= d;
            }
            f
        })
    };

    format!("{}\n", ans)
}

fn bis_usize<P>(t: usize, f: usize, eval: P) -> usize
where
    P: Fn(usize) -> bool,
{
    if t > f {
        if t - f == 1 {
            return t;
        }
    } else if f - t == 1 {
        return t;
    }
    let m = (t + f) >> 1;
    if eval(m) {
        bis_usize(m, f, eval)
    } else {
        bis_usize(t, m, eval)
    }
}

