                return false;
            }
            let mut cnt = m * v;
            for j in 0..n {
                if j == i || a[j] > ceiling {
                    continue;
                }
                let d = if ceiling - a[j] < m {
                    ceiling - a[j]
                } else {
                    m
                };
                if d >= cnt {
                    return true;
                }
                cnt -= d;
            }
            false
        })
    };

    format!("{}\n", ans)
}

fn bis_usize<P>(t: usize, f: usize, eval: P) -> usize
where
    P: Fn(usize) -> bool,
{
    if t > f {
        if t - f == 1 {
            return t;
        }
    } else if f - t == 1 {
        return t;
    }
    let m = (t + f) >> 1;
    if eval(m) {
        bis_usize(m, f, eval)
    } else {
        bis_usize(t, m, eval)
    }
}

