impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_line(&mut self) -> String {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b'\n' || b == b'\r')
            .take_while(|&b| b != b'\n' && b != b'\r')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }

    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::io::stdin;
use std::str::FromStr;
use std::cmp::max;
use std::cmp::min;

fn main(){
    let (_n, m, v, p)  = {
        let v: Vec<usize> = get_vec();
        (v[0], v[1], v[2], v[3])
    };
    let mut xs: Vec<i64> = get_vec();
    xs.sort();
    xs.reverse();

    let s = p as i64 - 1;
    let u = max(0, v as i64 - s);
    let zs = &xs[s as usize..];

    let loc = solve_local(zs, u, m as i64) as i64;

    println!("{}", s + loc);
}

fn solve_local(zs: &[i64], v: i64, m: i64) -> usize {
    let ok = |i: usize| {
        let a = zs[i] + m;
        if a < zs[0] { return false };
        let sum: i64 = zs.iter().map(|z| min(a-z, m)).sum();
        if sum < v*m { return false };
        true
    };
    upper_bound(&ok, 0, zs.len()) + 1
}

fn upper_bound<F>(ok: &F, left: usize, right: usize) -> usize 
    where F: Fn(usize) -> bool {
    if left+1 >= right {
        return left;
    }
    let m = (left + right) / 2;
    if ok(m) {
        return upper_bound(ok, m, right);
    } else {
        return upper_bound(ok, left, m);
    }
}

